/** 설정집 세계관 — 구조화 섹션 (사이드바 폼 ↔ worldbuilding_md 직렬화) */
const WORLD_BUILDING_SCHEMA = [
  {
    id: "where_when",
    title: i18n.t('app.1_무대_및_시대_Where_When'),
    blurb: i18n.t('app.작품의_기본_바탕이_되는_공간과_시간선입니다'),
    fields: [
      { id: "reality", labelKey: "index.현실_가상_구분", label: i18n.t('index.현실_가상_구분'), example: i18n.t('app.현실에_가상이_섞인_형태_현대_도시_숨겨진') },
      { id: "era", label: i18n.t('app.시대_배경'), example: i18n.t('app.현대') },
      { id: "locale", label: i18n.t('app.주요_배경'), example: i18n.t('app.해안_도시_하버라인과_그_지하_구역') },
      { id: "heritage", label: i18n.t('app.관련_전승_역사'), example: i18n.t('index.예_관련_전승_역사') },
    ],
  },
  {
    id: "unique_concept",
    title: i18n.t('app.2_세계의_특이점_Unique_Concept'),
    blurb: i18n.t('app.이_세계를_다른_세계관과_다르게_만드는_단'),
    fields: [
      { id: "special", label: i18n.t('app.특수_요소'), example: i18n.t('app.감정을_연료로_쓰는_이능') },
      { id: "rules", label: i18n.t('app.작동_규칙'), example: i18n.t('app.강한_감정일수록_이능이_커지지만_감정_소모') },
      { id: "limits", label: i18n.t('app.한계와_대가'), example: i18n.t('app.과다_사용_시_기억_일부_소실') },
    ],
  },
  {
    id: "extreme_factor",
    title: i18n.t('app.3_영향을_주는_극단적_요소_Extreme'),
    blurb: i18n.t('app.이_세계의_평범한_일상을_위협하거나_전체_시'),
    fields: [
      { id: "extreme_event", label: i18n.t('app.극단적_사건_환경'), example: i18n.t('app.10년째_이어지는_검은_비_재앙') },
      { id: "extreme_impact", label: i18n.t('app.세상에_미친_영향'), example: i18n.t('app.야외_활동이_금지되고_빗물을_막는_기업이_도') },
    ],
  },
  {
    id: "system_life",
    title: i18n.t('app.4_기본_체계_및_사회_System_Life'),
    blurb: i18n.t('app.사람들이_살아가는_데_필요한_최소한의_사회적'),
    fields: [
      { id: "power", label: i18n.t('app.지배_구조'), example: i18n.t('app.방재_기업_연합이_통치') },
      { id: "daily", label: i18n.t('app.기본_생활'), example: i18n.t('app.크레딧_화폐_장거리_이동_허가제_안전_이_최') },
      { id: "class", label: i18n.t('app.계급_신분'), example: i18n.t('app.이능_보유자_우대_노노출_구역_거주자_차별') },
    ],
  },
  {
    id: "factions",
    title: i18n.t('app.5_세력_및_갈등_Factions'),
    blurb: i18n.t('app.주인공과_인물들이_부딪히게_될_주체들입니다'),
    fields: [
      { id: "factions", label: i18n.t('app.주요_세력'), example: i18n.t('app.방재_기업_연합_vs_지하_저항_조직_서킷') },
      { id: "conflict", label: i18n.t('app.갈등의_원인'), example: i18n.t('app.재앙_대응_독점을_둘러싼_이권_다툼') },
    ],
  },
];

const WORLD_FIELD_IDS = WORLD_BUILDING_SCHEMA.flatMap((sec) => sec.fields.map((f) => f.id));

function emptyWorldBuildingValues() {
  const values = Object.create(null);
  for (const id of WORLD_FIELD_IDS) values[id] = "";
  values.legacy = "";
  return values;
}

function worldBuildingExampleValues() {
  const values = emptyWorldBuildingValues();
  for (const sec of WORLD_BUILDING_SCHEMA) {
    for (const field of sec.fields) {
      values[field.id] = field.example || "";
    }
  }
  return values;
}

function escapeWorldHtml(text) {
  return String(text || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function worldToriBadgeHtml(fieldId, label, labelKey) {
  const head = labelKey
    ? `<span data-i18n="${escapeWorldHtml(labelKey)}">${escapeWorldHtml(label)}</span>`
    : escapeWorldHtml(label);
  return `<span class="world-sheet-field-head">${head}<button type="button" class="character-analysis-badge world-analysis-badge hidden" data-world-tori-field="${escapeWorldHtml(fieldId)}" title="${escapeWorldHtml(i18n.t('index.적어_둔_내용은_그대로_두고_토리_분석만_보'))}" data-i18n-title="index.적어_둔_내용은_그대로_두고_토리_분석만_보" data-i18n="index.새_분석_있음">${escapeWorldHtml(i18n.t('index.새_분석_있음'))}</button></span>`;
}

function ensureWorldbuildingMainForm() {
  const host = $("worldbuildingMainForm");
  if (!host) return null;
  if (host.dataset.built === "1") return host;
  host.dataset.built = "1";
  const cards = WORLD_BUILDING_SCHEMA.map((sec) => {
    const enMatch = String(sec.title || "").match(/\(([^)]+)\)\s*$/);
    const titlePlain = String(sec.title || "").replace(/\s*\([^)]*\)\s*$/, "").trim();
    const fields = sec.fields.map((field) => `
      <label class="world-main-field">${worldToriBadgeHtml(field.id, field.label, field.labelKey)}
        <textarea data-world-field="${escapeWorldHtml(field.id)}" rows="3" placeholder="예: ${escapeWorldHtml(field.example || "")}"></textarea>
      </label>`).join("");
    return `
      <article class="world-main-card" data-world-section="${escapeWorldHtml(sec.id)}">
        <h3 class="world-main-card-title">${escapeWorldHtml(titlePlain)}${enMatch ? ` <span class="world-cat-en">(${escapeWorldHtml(enMatch[1])})</span>` : ""}</h3>
        <p class="world-main-card-blurb">${escapeWorldHtml(sec.blurb)}</p>
        <div class="world-main-card-fields">${fields}</div>
      </article>`;
  }).join("");
  host.innerHTML = `${cards}
    <article class="world-main-card world-main-card-legacy world-cat-legacy hidden" id="worldCatLegacyMain" data-world-section="legacy" hidden>
      <h3 class="world-main-card-title">기타 · 기존 메모</h3>
      <p class="world-main-card-blurb">구조에 맞지 않던 이전 세계관 텍스트입니다. 위 칸으로 옮겨 정리해도 됩니다.</p>
      <div class="world-main-card-fields">
        <label class="world-main-field">기존 내용
          <textarea data-world-field="legacy" rows="4" placeholder=""></textarea>
        </label>
      </div>
    </article>`;
  host.querySelectorAll("[data-i18n]").forEach((el) => {
    el.textContent = decodeHtmlEntities(i18n.t(el.getAttribute("data-i18n")));
  });
  host.querySelectorAll("[data-i18n-title]").forEach((el) => {
    el.setAttribute("title", i18n.t(el.getAttribute("data-i18n-title")));
  });
  if (typeof syncWorldToriBadges === "function") syncWorldToriBadges();
  return host;
}

function worldBuildingFormRoots() {
  return [$("worldbuildingForm"), $("worldbuildingMainForm")].filter(Boolean);
}

function readWorldBuildingFormValuesFrom(form) {
  const values = emptyWorldBuildingValues();
  if (!form) return values;
  form.querySelectorAll("[data-world-field]").forEach((el) => {
    const key = el.dataset.worldField;
    if (!key) return;
    values[key] = String(el.value || "").trim();
  });
  return values;
}

function readWorldBuildingFormValues() {
  const focused = document.activeElement?.closest?.("#worldbuildingMainForm, #worldbuildingForm");
  if (focused) return readWorldBuildingFormValuesFrom(focused);
  if (isWorldbuildingMainOpen()) {
    return readWorldBuildingFormValuesFrom($("worldbuildingMainForm") || $("worldbuildingForm"));
  }
  return readWorldBuildingFormValuesFrom($("worldbuildingForm"));
}

function composeWorldbuildingMd(values) {
  const v = values || emptyWorldBuildingValues();
  const parts = [];
  for (const sec of WORLD_BUILDING_SCHEMA) {
    parts.push(`## ${sec.title}`);
    parts.push(sec.blurb);
    parts.push("");
    for (const field of sec.fields) {
      const text = String(v[field.id] || "").trim();
      parts.push(`### ${field.label}`);
      parts.push(text || "");
      parts.push("");
    }
  }
  const legacy = String(v.legacy || "").trim();
  if (legacy) {
    parts.push(i18n.t('app.기타_기존_메모'));
    parts.push(legacy);
    parts.push("");
  }
  return parts.join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

function parseWorldbuildingMd(raw) {
  const values = emptyWorldBuildingValues();
  let text = String(raw || "").trim();
  if (!text) return values;
  if (looksLikeHtml(text)) text = plainTextFromHtml(text).trim();
  if (!text) return values;

  const hasStructured = WORLD_BUILDING_SCHEMA.some((sec) => text.includes(sec.title)
    || text.includes(sec.title.replace(/\s*\([^)]*\)\s*$/, "").trim()));
  if (!hasStructured) {
    values.legacy = text;
    return values;
  }

  const labelToId = Object.create(null);
  for (const sec of WORLD_BUILDING_SCHEMA) {
    for (const field of sec.fields) {
      labelToId[field.label] = field.id;
    }
  }
  labelToId[i18n.t('app.기타_기존_메모_2')] = "legacy";
  labelToId[i18n.t('app.기타')] = "legacy";

  // Split on ### headings (field labels) or ## section titles we don't store as fields.
  const chunks = text.split(/\n(?=#{2,3}\s+)/);
  let currentField = null;
  const buffers = Object.create(null);
  for (const chunk of chunks) {
    const headingMatch = chunk.match(/^#{2,3}\s+(.+?)\s*(?:\n|$)/);
    if (!headingMatch) {
      if (currentField) {
        buffers[currentField] = `${buffers[currentField] || ""}\n${chunk}`.trim();
      } else {
        values.legacy = `${values.legacy}\n${chunk}`.trim();
      }
      continue;
    }
    const heading = headingMatch[1].replace(/\s+/g, " ").trim();
    const body = chunk.slice(headingMatch[0].length).trim();
    // Skip top-level section blurbs stored under ## titles.
    const isSection = WORLD_BUILDING_SCHEMA.some((sec) => sec.title === heading
      || sec.title.replace(/\s*\([^)]*\)\s*$/, "").trim() === heading.replace(/\s*\([^)]*\)\s*$/, "").trim()
      || heading.startsWith(sec.title.slice(0, 8)));
    if (isSection && !labelToId[heading]) {
      currentField = null;
      // Drop section blurb lines from body; keep leftover only if it looks like author content.
      const cleaned = body
        .split(/\n/)
        .filter((line) => {
          const t = line.trim();
          if (!t) return false;
          return !WORLD_BUILDING_SCHEMA.some((sec) => sec.blurb === t);
        })
        .join("\n")
        .trim();
      if (cleaned) values.legacy = `${values.legacy}\n${cleaned}`.trim();
      continue;
    }
    const fieldId = labelToId[heading]
      || labelToId[heading.replace(/\s*\([^)]*\)\s*$/, "").trim()]
      || null;
    if (fieldId) {
      currentField = fieldId;
      buffers[fieldId] = body;
    } else if (heading.includes(i18n.t('app.기타'))) {
      currentField = "legacy";
      buffers.legacy = body;
    } else {
      currentField = null;
      if (body) values.legacy = `${values.legacy}\n${body}`.trim();
    }
  }
  for (const [key, val] of Object.entries(buffers)) {
    values[key] = String(val || "").trim();
  }
  return values;
}

function fillWorldBuildingExamplePlaceholders() {
  for (const form of worldBuildingFormRoots()) {
    for (const sec of WORLD_BUILDING_SCHEMA) {
      for (const field of sec.fields) {
        const el = form.querySelector(`[data-world-field="${field.id}"]`);
        if (el && field.example) el.placeholder = `${i18n.t('app.예_field_example', {'field.example': field.example})}`;
      }
    }
  }
}

function applyWorldBuildingValuesToFormRoot(form, values, { force = false } = {}) {
  if (!form) return;
  const v = values || emptyWorldBuildingValues();
  const active = document.activeElement;
  const snap = snapshotOverflowScroll(form);
  form.querySelectorAll("[data-world-field]").forEach((el) => {
    const key = el.dataset.worldField;
    if (!key) return;
    if (!force && active === el) return;
    el.value = v[key] || "";
    applyToriDraftClass(el);
    autoResizeSettingsSidebarTextarea(el, { preserve: false });
  });
  restoreOverflowScroll(snap);
  const legacyWrap = form.querySelector("[data-world-section='legacy']")
    || (form.id === "worldbuildingForm" ? $("worldCatLegacy") : $("worldCatLegacyMain"));
  const hasLegacy = Boolean(String(v.legacy || "").trim());
  if (legacyWrap) {
    legacyWrap.classList.toggle("hidden", !hasLegacy);
    legacyWrap.hidden = !hasLegacy;
  }
}

function applyWorldBuildingValuesToForm(values, { force = false } = {}) {
  const v = values || emptyWorldBuildingValues();
  for (const form of worldBuildingFormRoots()) {
    applyWorldBuildingValuesToFormRoot(form, v, { force });
  }
  const serialized = $("projectWorldbuilding");
  if (serialized) serialized.value = composeWorldbuildingMd(v);
}

function syncWorldBuildingFormFromState({ force = false } = {}) {
  ensureWorldbuildingMainForm();
  applyWorldBuildingValuesToForm(parseWorldbuildingMd(state.worldbuildingMd || ""), { force });
}

/** true = 빈 세계관에 예제만 보여 주는 중(저장·AI 주입 전) */
let worldbuildingExampleDraft = false;

function pushWorldBuildingFormToState({ commitDraft = false } = {}) {
  const values = readWorldBuildingFormValues();
  const md = composeWorldbuildingMd(values);
  const serialized = $("projectWorldbuilding");
  if (serialized) serialized.value = md;
  if (worldbuildingExampleDraft && !commitDraft) {
    // 예제 초안은 화면에만 두고, 실제 저장값/AI 컨텍스트는 비워 둔다.
    return state.worldbuildingMd || "";
  }
  worldbuildingExampleDraft = false;
  state.worldbuildingMd = md;
  return md;
}

function seedWorldBuildingExamplesIfEmpty() {
  ensureWorldbuildingMainForm();
  const raw = String(state.worldbuildingMd || "").trim();
  if (raw) {
    worldbuildingExampleDraft = false;
    syncWorldBuildingFormFromState({ force: true });
    return false;
  }
  const examples = worldBuildingExampleValues();
  applyWorldBuildingValuesToForm(examples, { force: true });
  worldbuildingExampleDraft = true;
  const serialized = $("projectWorldbuilding");
  if (serialized) serialized.value = composeWorldbuildingMd(examples);
  return true;
}

function setWorldbuildingSaveStatus(text) {
  if ($("worldbuildingSaveInfo")) $("worldbuildingSaveInfo").textContent = text || "";
  if ($("synopsisSaveInfo") && state.settingsDocKind === "world") {
    $("synopsisSaveInfo").textContent = text || "";
  }
}

const COUNT_METRIC_LABEL = {
  chars_with_space: i18n.t('app.공백포함'),
  chars_no_space: i18n.t('app.공백제외'),
  words: i18n.t('app.단어'),
  letters: i18n.t('app.글자'),
};

const STAT_DISPLAY_KEY = "supertory.statDisplay.v2";
const STAT_SCOPE_KEY = "supertory.statScope"; // "current" | "project"
const SPACE_MODES = ["with", "without"]; // 공백포함 / 공백제외 (exclusive)
const UNIT_MODES = ["words", "letters", "both"]; // 단어 / 글자 / 둘 다
const DEFAULT_STAT_DISPLAY = { space: "with", unit: "words" };

function loadStatDisplay() {
  try {
    const raw = localStorage.getItem(STAT_DISPLAY_KEY);
    if (!raw) return { ...DEFAULT_STAT_DISPLAY };
    const parsed = JSON.parse(raw);
    const space = SPACE_MODES.includes(parsed?.space) ? parsed.space : DEFAULT_STAT_DISPLAY.space;
    const unit = UNIT_MODES.includes(parsed?.unit) ? parsed.unit : DEFAULT_STAT_DISPLAY.unit;
    return { space, unit };
  } catch (_) {
    return { ...DEFAULT_STAT_DISPLAY };
  }
}

function saveStatDisplay(display) {
  try {
    localStorage.setItem(STAT_DISPLAY_KEY, JSON.stringify(display));
  } catch (_) {
    /* ignore */
  }
}

function loadStatScope() {
  try {
    const v = localStorage.getItem(STAT_SCOPE_KEY);
    if (v === "project" || v === "current") return v;
  } catch (_) {
    /* ignore */
  }
  return "current";
}

function saveStatScope(scope) {
  try {
    localStorage.setItem(STAT_SCOPE_KEY, scope);
  } catch (_) {
    /* ignore */
  }
}

let statDisplay = loadStatDisplay();
let statScope = loadStatScope(); // "current" | "project"

function isStatVisible(key) {
  if (key === "chars_with_space" || key === "chars_no_space") return true;
  if (key === "words") return statDisplay.unit === "words" || statDisplay.unit === "both";
  if (key === "letters") return statDisplay.unit === "letters" || statDisplay.unit === "both";
  if (key === "scenes") return statScope === "project";
  return false;
}

function spaceMetricFromMode(mode) {
  return mode === "without" ? "chars_no_space" : "chars_with_space";
}

function spaceModeFromMetric(metric) {
  if (metric === "chars_no_space") return "without";
  if (metric === "chars_with_space") return "with";
  return SPACE_MODES.includes(statDisplay.space) ? statDisplay.space : DEFAULT_STAT_DISPLAY.space;
}

function applySpaceSegUi() {
  const metric = getGoalMetric();
  const spaceKey = (metric === "chars_with_space" || metric === "chars_no_space")
    ? metric
    : spaceMetricFromMode(statDisplay.space);
  document.querySelectorAll("#statsSpaceSeg [data-stat]").forEach((node) => {
    const on = node.dataset.stat === spaceKey;
    node.classList.toggle("is-active", on);
    node.setAttribute("aria-pressed", on ? "true" : "false");
  });
}

function selectSpaceMode(mode) {
  const next = SPACE_MODES.includes(mode) ? mode : DEFAULT_STAT_DISPLAY.space;
  if (statDisplay.space !== next) {
    statDisplay = { ...statDisplay, space: next };
    saveStatDisplay(statDisplay);
  }
  applyStatDisplayVisibility();
  setGoalMetric(spaceMetricFromMode(next));
}

function cycleUnitMode() {
  const i = UNIT_MODES.indexOf(statDisplay.unit);
  statDisplay = { ...statDisplay, unit: UNIT_MODES[(i + 1) % UNIT_MODES.length] };
  saveStatDisplay(statDisplay);
  applyStatDisplayVisibility();
  updateSceneStats();
}

function applyStatDisplayVisibility() {
  document.querySelectorAll("#statsCounts .stat-chip[data-stat]").forEach((node) => {
    const key = node.dataset.stat;
    if (!key) return;
    node.classList.toggle("is-hidden-stat", !isStatVisible(key));
  });
  applySpaceSegUi();
}

function setGoalMetric(metric) {
  if (!COUNT_METRIC_LABEL[metric]) return;
  const prev = $("sceneGoalMetric")?.value;
  if ($("sceneGoalMetric")) $("sceneGoalMetric").value = metric;
  if (metric === "chars_with_space" || metric === "chars_no_space") {
    const mode = spaceModeFromMetric(metric);
    if (statDisplay.space !== mode) {
      statDisplay = { ...statDisplay, space: mode };
      saveStatDisplay(statDisplay);
    }
  }
  document.querySelectorAll("#statsCounts .stat-chip[data-stat]").forEach((node) => {
    const key = node.dataset.stat;
    node.classList.toggle("is-goal-metric", key === metric);
    node.classList.toggle("is-active", key === metric);
  });
  applySpaceSegUi();
  updateSceneStats();
  if (state.sceneId && statScope === "current" && prev !== metric) {
    markSceneDirty();
    scheduleSceneGoalSave();
  }
}

function computeTextStats(plainText) {
  const text = String(plainText || "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/\u00a0/g, " ")
    .replace(/\u200b/g, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  // Spread for proper Unicode code points (Hangul, emoji, etc.)
  const charsWithSpace = [...text].length;
  const charsNoSpace = [...text.replace(/\s/g, "")].length;
  const words = (text.match(/\S+/g) || []).length;
  // Letters: Hangul, letters, numbers — no spaces/punctuation/symbols.
  const letters = (text.match(/[\p{L}\p{N}\p{Script=Hangul}]/gu) || []).length;
  return {
    chars_with_space: charsWithSpace,
    chars_no_space: charsNoSpace,
    words,
    letters,
  };
}

function formatStatNumber(n) {
  const num = Number(n) || 0;
  try {
    return num.toLocaleString("ko-KR");
  } catch (_) {
    return String(num);
  }
}

function getGoalMetric() {
  const metric = $("sceneGoalMetric")?.value || "chars_with_space";
  return COUNT_METRIC_LABEL[metric] ? metric : "chars_with_space";
}

function isProjectStatsScope() {
  return statScope === "project";
}

function syncStatsScopeUi() {
  const label = $("statsGoalLabel");
  const bar = $("manuscriptStatusBar");
  const isProject = isProjectStatsScope();
  document.querySelectorAll("#statsScopeSeg [data-scope]").forEach((btn) => {
    const on = btn.dataset.scope === (isProject ? "project" : "current");
    btn.classList.toggle("is-active", on);
    btn.classList.toggle("is-project", on && isProject);
    btn.setAttribute("aria-pressed", on ? "true" : "false");
  });
  if (label) label.textContent = i18n.t('app.목표');
  if (bar) bar.classList.toggle("is-scope-project", isProject);
  // Mirror stored goals into the single visible input.
  const goalVal = isProject
    ? Math.max(0, Number($("projectGoalCount")?.value || state.projectGoalCount || 0) || 0)
    : Math.max(0, Number($("sceneGoalCount")?.value || 0) || 0);
  if ($("statsGoalInput")) $("statsGoalInput").value = String(goalVal);
  applyStatDisplayVisibility();
  applySpaceSegUi();
}

function setStatsScope(scope) {
  const next = scope === "project" ? "project" : "current";
  if (statScope === next) return;
  statScope = next;
  saveStatScope(statScope);
  syncStatsScopeUi();
  updateSceneStats();
  if (isProjectStatsScope()) scheduleProjectManuscriptStats();
}

function toggleStatsScope() {
  setStatsScope(isProjectStatsScope() ? "current" : "project");
}

/** Excess unit word for overflow labels (100자 초과 / 100단어 초과). */
function goalExcessUnitWord(metric) {
  return metric === "words" ? i18n.t('app.단어') : i18n.t('app.자');
}

/**
 * Bucket excess into 100-unit steps once goal is met.
 * e.g. excess 150 → "100자 초과", 250 → "200자 초과".
 * Returns "" when excess < 100.
 */
function formatGoalExcessLabel(excess, metric) {
  const over = Math.max(0, Math.floor(Number(excess) || 0));
  if (over < 100) return "";
  const bucket = Math.floor(over / 100) * 100;
  return `${i18n.t('app.formatStatNumber_bucket', {'formatStatNumber(bucket)': formatStatNumber(bucket), 'goalExcessUnitWord(metric)': goalExcessUnitWord(metric)})}`;
}

/**
 * Red overlay fill after goal: restarts from 0% and climbs again by (excess / goal).
 * Caps at 100% of a second “lap” (value ≥ 2× goal → full red).
 */
function goalOverflowPercent(value, goal) {
  if (!(goal > 0) || !(value > goal)) return 0;
  const excess = value - goal;
  return Math.min(100, Math.round((excess / goal) * 100));
}

function updateGoalProgressUi({ value, goal, metric }) {
  const percent = goal > 0 ? Math.min(100, Math.round((value / goal) * 100)) : 0;
  const complete = goal > 0 && value >= goal;
  const inProgress = goal > 0 && value < goal;
  const excess = goal > 0 ? Math.max(0, value - goal) : 0;
  const overGoal = excess > 0;
  const overflowPct = goalOverflowPercent(value, goal);
  const excessLabel = complete ? formatGoalExcessLabel(excess, metric) : "";

  const fill = $("sceneGoalBarFill");
  const overflow = $("sceneGoalBarOverflow");
  const bar = $("sceneGoalBar");
  const label = $("sceneGoalProgressLabel");
  const overflowLabel = $("sceneGoalOverflowLabel");
  const statusBar = $("manuscriptStatusBar");

  if (fill) {
    // Base fill stays full once goal is reached; red layer shows overshoot.
    fill.style.width = goal > 0 ? `${Math.min(100, percent)}%` : "0%";
    fill.classList.toggle("is-complete", complete && !overGoal);
    fill.classList.toggle("is-progress", inProgress);
    fill.classList.toggle("is-empty", goal <= 0);
    // Keep complete coloring under red when overshooting.
    if (complete) fill.classList.add("is-complete");
  }
  if (overflow) {
    overflow.style.width = overGoal ? `${overflowPct}%` : "0%";
    overflow.classList.toggle("is-empty", !overGoal);
    overflow.title = overGoal
      ? `${i18n.t('app.목표_초과_formatStatNumber_e', {'formatStatNumber(excess)': formatStatNumber(excess), 'goalExcessUnitWord(metric)': goalExcessUnitWord(metric), overflowPct: overflowPct})}`
      : "";
  }
  if (statusBar) {
    statusBar.classList.toggle("is-complete", complete && !overGoal);
    statusBar.classList.toggle("is-progress", inProgress);
    statusBar.classList.toggle("is-over", overGoal);
  }
  if (bar) {
    bar.setAttribute("aria-valuenow", String(overGoal ? 100 + overflowPct : percent));
    bar.setAttribute("aria-valuemax", "100");
    bar.setAttribute(
      "aria-label",
      goal <= 0
        ? i18n.t('app.목표_없음')
        : overGoal
          ? `${i18n.t('app.COUNT_METRIC_LABEL_metr', {'COUNT_METRIC_LABEL[metric] || metric': COUNT_METRIC_LABEL[metric] || metric, goal: goal, excess: excess, 'goalExcessUnitWord(metric)': goalExcessUnitWord(metric)})}`
          : `${i18n.t('app.COUNT_METRIC_LABEL_metr_2', {'COUNT_METRIC_LABEL[metric] || metric': COUNT_METRIC_LABEL[metric] || metric, goal: goal, value: value, percent: percent})}`,
    );
  }
  if (label) {
    label.classList.toggle("is-complete", complete);
    label.classList.toggle("is-progress", inProgress);
    const metricLabel = COUNT_METRIC_LABEL[metric] || metric;
    const valTxt = formatStatNumber(value);
    let text;
    if (goal <= 0) text = `${metricLabel} ${valTxt}`;
    else if (complete) text = `${i18n.t('app.valTxt_formatStatNumber', {valTxt: valTxt, 'formatStatNumber(goal)': formatStatNumber(goal)})}`;
    else text = `${valTxt}/${formatStatNumber(goal)} · ${percent}%`;
    label.textContent = text;
    label.title = excessLabel ? `${text} · ${excessLabel}` : text;
  }
  if (overflowLabel) {
    if (excessLabel) {
      overflowLabel.textContent = excessLabel;
      overflowLabel.classList.remove("hidden");
      overflowLabel.title = `${i18n.t('app.목표보다_formatStatNumber_ex', {'formatStatNumber(excess)': formatStatNumber(excess), 'goalExcessUnitWord(metric)': goalExcessUnitWord(metric)})}`;
    } else {
      overflowLabel.textContent = "";
      overflowLabel.classList.add("hidden");
      overflowLabel.title = "";
    }
  }
  // Re-apply solid/gradient fill after class changes (empty/progress/complete).
  applyGoalBarColorsToDom();
}

function updateSceneStats() {
  const sceneStats = computeTextStats(getEditorPlainText());
  const metric = getGoalMetric();
  const isProject = isProjectStatsScope();
  const projectStats = projectStatsCache || {
    chars_with_space: 0,
    chars_no_space: 0,
    words: 0,
    letters: 0,
    scenes: 0,
  };
  const stats = isProject ? projectStats : sceneStats;
  const goal = isProject
    ? Math.max(0, Number($("projectGoalCount")?.value || state.projectGoalCount || 0) || 0)
    : Math.max(0, Number($("sceneGoalCount")?.value || 0) || 0);
  const value = stats[metric] ?? 0;

  document.querySelectorAll("#statsCounts .stat-chip[data-stat]").forEach((node) => {
    const key = node.dataset.stat;
    const strong = node.querySelector("strong");
    if (!strong) return;
    if (key === "scenes") strong.textContent = formatStatNumber(projectStats.scenes ?? 0);
    else strong.textContent = formatStatNumber(stats[key] ?? 0);
    node.classList.toggle("is-goal-metric", key === metric);
    node.classList.toggle("is-active", key === metric);
  });

  updateGoalProgressUi({ value, goal, metric });
  applySpaceSegUi();
  updateChapterSubtitleButtonState(sceneStats.chars_with_space);
}

