/** Cycle order: 그룹 1 → 2 → 3 */
const UI_THEME_CYCLE = UI_THEME_GROUPS.flatMap((group) => group.themes.map((item) => item.id));

const UI_THEME_IDS = new Set([
  "dawn", // legacy → library
  ...UI_THEME_CYCLE,
]);

function normalizeUiThemeId(theme) {
  if (theme === "dawn") return "library";
  if (UI_THEME_IDS.has(theme)) return theme;
  return "light";
}

function isUiThemeDark(theme) {
  const id = normalizeUiThemeId(theme);
  return id === "dark" || id === "attic";
}

function uiThemeScheme(theme) {
  return isUiThemeDark(theme) ? "dark" : "light";
}

function cloneGoalColorEntry(entry) {
  if (!entry || typeof entry !== "object") return null;
  if (entry.mode === "gradient") {
    return {
      mode: "gradient",
      from: entry.from,
      to: entry.to,
      id: entry.id || "",
    };
  }
  return {
    mode: "solid",
    hex: entry.hex,
    id: entry.id || "",
  };
}

function getGoalBarColorDefaults(themeId = null) {
  const id = typeof normalizeUiThemeId === "function"
    ? normalizeUiThemeId(themeId || (typeof getUiTheme === "function" ? getUiTheme() : "light"))
    : (themeId || "light");
  const pack = GOAL_BAR_THEME_DEFAULTS[id] || GOAL_BAR_THEME_DEFAULTS.light;
  return {
    progress: cloneGoalColorEntry(pack.progress),
    complete: cloneGoalColorEntry(pack.complete),
    overflow: cloneGoalColorEntry(pack.overflow),
  };
}

/** 사용자가 우클릭 메뉴로 고른 색만 저장 (테마 기본과 분리) */
let goalBarColorOverrides = { progress: null, complete: null, overflow: null };
let goalBarColors = getGoalBarColorDefaults("light");

function normalizeGoalColorEntry(raw, fallback) {
  if (!raw || typeof raw !== "object") {
    // Migrate v1 string hex → solid
    if (typeof raw === "string" && /^#/.test(raw)) {
      return { mode: "solid", hex: raw, id: "" };
    }
    return cloneGoalColorEntry(fallback) || { mode: "solid", hex: "#e6c749", id: "yellow" };
  }
  if (raw.mode === "gradient" && raw.from && raw.to) {
    return {
      mode: "gradient",
      from: raw.from,
      to: raw.to,
      id: raw.id || "",
    };
  }
  if (raw.hex) {
    return { mode: "solid", hex: raw.hex, id: raw.id || "" };
  }
  return cloneGoalColorEntry(fallback) || { mode: "solid", hex: "#e6c749", id: "yellow" };
}

function goalColorEntriesEqual(a, b) {
  if (!a || !b) return false;
  if (a.mode !== b.mode) return false;
  if (a.mode === "gradient") {
    return String(a.from).toLowerCase() === String(b.from).toLowerCase()
      && String(a.to).toLowerCase() === String(b.to).toLowerCase();
  }
  return String(a.hex || "").toLowerCase() === String(b.hex || "").toLowerCase();
}

/** Old default progress fills (노랑 / 토리 primary / 주황) → 테마 기본으로 승격 */
function isLegacyGoalProgressDefault(entry) {
  if (!entry || entry.mode !== "solid") return false;
  const hex = String(entry.hex || "").toLowerCase();
  if (entry.id === "yellow" || hex === "#f5c518" || hex === "#e6c749") return true;
  if (entry.id === "primary" || hex === "#1e293b") return true;
  if (entry.id === "orange" || hex === "#f39c12") return true;
  return false;
}

function isLegacyGoalCompleteDefault(entry) {
  if (!entry || entry.mode !== "solid") return false;
  const hex = String(entry.hex || "").toLowerCase();
  return entry.id === "green" || hex === "#2f9e4f";
}

function resolveGoalBarColors(overrides = goalBarColorOverrides, themeId = null) {
  const defaults = getGoalBarColorDefaults(themeId);
  return {
    progress: overrides?.progress
      ? normalizeGoalColorEntry(overrides.progress, defaults.progress)
      : defaults.progress,
    complete: overrides?.complete
      ? normalizeGoalColorEntry(overrides.complete, defaults.complete)
      : defaults.complete,
    overflow: overrides?.overflow
      ? normalizeGoalColorEntry(overrides.overflow, defaults.overflow)
      : defaults.overflow,
  };
}

function loadGoalBarColorOverrides() {
  try {
    let raw = localStorage.getItem(GOAL_BAR_COLOR_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      const src = parsed?.overrides && typeof parsed.overrides === "object" ? parsed.overrides : parsed;
      return {
        progress: src?.progress ? normalizeGoalColorEntry(src.progress, null) : null,
        complete: src?.complete ? normalizeGoalColorEntry(src.complete, null) : null,
        overflow: src?.overflow ? normalizeGoalColorEntry(src.overflow, null) : null,
      };
    }
    // Migrate v4 / older: 예전 전역 기본(주황·초록)이면 테마 기본을 쓰도록 override 비움
    const old = localStorage.getItem(GOAL_BAR_COLOR_KEY_LEGACY_V4)
      || localStorage.getItem("supertory.goalBarColors.v3")
      || localStorage.getItem("supertory.goalBarColors.v2")
      || localStorage.getItem("supertory.goalBarColors");
    if (!old) {
      return { progress: null, complete: null, overflow: null };
    }
    const parsed = JSON.parse(old);
    let progress = parsed?.progress
      ? normalizeGoalColorEntry(parsed.progress, { mode: "solid", hex: "#f39c12", id: "orange" })
      : null;
    let complete = parsed?.complete
      ? normalizeGoalColorEntry(parsed.complete, { mode: "solid", hex: "#2f9e4f", id: "green" })
      : null;
    if (progress && isLegacyGoalProgressDefault(progress)) progress = null;
    if (complete && isLegacyGoalCompleteDefault(complete)) complete = null;
    return { progress, complete, overflow: null };
  } catch (_) {
    return { progress: null, complete: null, overflow: null };
  }
}

function persistGoalBarColorOverrides(overrides = goalBarColorOverrides) {
  const payload = {
    overrides: {
      progress: overrides.progress || null,
      complete: overrides.complete || null,
      overflow: overrides.overflow || null,
    },
  };
  try {
    localStorage.setItem(GOAL_BAR_COLOR_KEY, JSON.stringify(payload));
  } catch (_) {
    /* ignore */
  }
}

function refreshGoalBarColorsFromThemeAndOverrides() {
  goalBarColors = resolveGoalBarColors(goalBarColorOverrides);
  applyGoalBarColorsToDom();
  syncGoalBarSwatchActive();
}

function saveGoalBarColorOverride(kind, entry) {
  if (!["progress", "complete", "overflow"].includes(kind)) return;
  const defaults = getGoalBarColorDefaults();
  const normalized = normalizeGoalColorEntry(entry, defaults[kind]);
  // 테마 기본과 같으면 override 제거 → 테마 전환 시 따라감
  if (goalColorEntriesEqual(normalized, defaults[kind])) {
    goalBarColorOverrides = { ...goalBarColorOverrides, [kind]: null };
  } else {
    goalBarColorOverrides = { ...goalBarColorOverrides, [kind]: normalized };
  }
  persistGoalBarColorOverrides();
  refreshGoalBarColorsFromThemeAndOverrides();
}

function resetGoalBarColorOverrides() {
  goalBarColorOverrides = { progress: null, complete: null, overflow: null };
  persistGoalBarColorOverrides();
  refreshGoalBarColorsFromThemeAndOverrides();
}

/** @deprecated 호환 — 새 코드는 saveGoalBarColorOverride / resetGoalBarColorOverrides 사용 */
function saveGoalBarColors(colors) {
  const defaults = getGoalBarColorDefaults();
  const next = { ...goalBarColorOverrides };
  if (colors && Object.prototype.hasOwnProperty.call(colors, "progress")) {
    const entry = colors.progress
      ? normalizeGoalColorEntry(colors.progress, defaults.progress)
      : null;
    next.progress = entry && !goalColorEntriesEqual(entry, defaults.progress) ? entry : null;
  }
  if (colors && Object.prototype.hasOwnProperty.call(colors, "complete")) {
    const entry = colors.complete
      ? normalizeGoalColorEntry(colors.complete, defaults.complete)
      : null;
    next.complete = entry && !goalColorEntriesEqual(entry, defaults.complete) ? entry : null;
  }
  if (colors && Object.prototype.hasOwnProperty.call(colors, "overflow")) {
    const entry = colors.overflow
      ? normalizeGoalColorEntry(colors.overflow, defaults.overflow)
      : null;
    next.overflow = entry && !goalColorEntriesEqual(entry, defaults.overflow) ? entry : null;
  }
  goalBarColorOverrides = next;
  persistGoalBarColorOverrides();
  refreshGoalBarColorsFromThemeAndOverrides();
}

function goalEntryCssBackground(entry) {
  const fallback = "#e6c749";
  if (!entry) return fallback;
  if (entry.mode === "gradient") {
    return `linear-gradient(90deg, ${entry.from} 0%, ${entry.to} 100%)`;
  }
  const hex = entry.hex || fallback;
  // Soft 3-stop shine without color-mix (broader browser support)
  return `linear-gradient(90deg, ${hex}cc 0%, ${hex} 55%, ${hex} 100%)`;
}

function goalEntryLabelColor(entry) {
  if (!entry) return "#e6c749";
  if (entry.mode === "gradient") return entry.to || entry.from || "#e6c749";
  return entry.hex || "#e6c749";
}

function applyGoalBarColorsToDom() {
  const fill = $("sceneGoalBarFill");
  const overflow = $("sceneGoalBarOverflow");
  const label = $("sceneGoalProgressLabel");
  if (!fill) return;

  const isEmpty = fill.classList.contains("is-empty");
  const isComplete = fill.classList.contains("is-complete");
  if (isEmpty) {
    fill.style.background = "transparent";
    fill.style.backgroundImage = "none";
  } else if (isComplete) {
    fill.style.background = goalEntryCssBackground(goalBarColors.complete);
  } else {
    fill.style.background = goalEntryCssBackground(goalBarColors.progress);
  }

  if (overflow) {
    overflow.style.background = goalEntryCssBackground(goalBarColors.overflow);
  }

  if (label) {
    if (label.classList.contains("is-complete")) {
      label.style.color = goalEntryLabelColor(goalBarColors.complete);
    } else if (label.classList.contains("is-progress")) {
      label.style.color = goalEntryLabelColor(goalBarColors.progress);
    } else {
      label.style.color = "";
    }
  }
}

function hideGoalBarColorMenu() {
  $("goalBarColorMenu")?.classList.add("hidden");
}

function syncGoalBarSwatchActive() {
  const menu = $("goalBarColorMenu");
  if (!menu) return;
  menu.querySelectorAll("[data-goal-preset]").forEach((btn) => {
    const kind = btn.dataset.goalKind;
    const mode = btn.dataset.goalMode;
    const id = btn.dataset.goalPreset;
    const entry = goalBarColors[kind];
    let active = false;
    if (entry && entry.mode === mode) {
      if (mode === "solid") active = entry.id === id || entry.hex === btn.dataset.goalHex;
      else active = entry.id === id
        || (entry.from === btn.dataset.goalFrom && entry.to === btn.dataset.goalTo);
    }
    btn.classList.toggle("is-active", active);
  });
}

function showGoalBarColorMenu(anchorEl) {
  const menu = $("goalBarColorMenu");
  if (!menu || !anchorEl) return;
  hideFormatApplyAllMenu?.();
  ensureGoalBarSwatchesFilled();
  syncGoalBarSwatchActive();
  menu.classList.remove("hidden");
  const rect = anchorEl.getBoundingClientRect();
  const pad = 8;
  const mw = menu.offsetWidth || 240;
  const mh = menu.offsetHeight || 280;
  let left = rect.left;
  let top = rect.bottom + 4;
  if (left + mw > window.innerWidth - pad) left = Math.max(pad, window.innerWidth - mw - pad);
  if (top + mh > window.innerHeight - pad) top = Math.max(pad, rect.top - mh - 4);
  menu.style.left = `${Math.max(pad, left)}px`;
  menu.style.top = `${Math.max(pad, top)}px`;
}

function ensureGoalBarSwatchesFilled() {
  const fillSolid = (hostId, kind) => {
    const host = $(hostId);
    if (!host || host.dataset.filled === "1") return;
    const primaryHex = resolveThemePrimaryHex();
    host.innerHTML = GOAL_BAR_SOLID_PRESETS.map((c) => {
      const hex = c.id === "primary" ? primaryHex : c.hex;
      return `
      <button type="button" class="goal-bar-swatch" data-goal-preset="${c.id}"
        data-goal-kind="${kind}" data-goal-mode="solid" data-goal-hex="${hex}"
        title="${c.label}" aria-label="${c.label}"
        style="background-color:${hex} !important; background-image:none !important;"></button>
    `;
    }).join("");
    host.dataset.filled = "1";
  };
  const fillGrad = (hostId, kind) => {
    const host = $(hostId);
    if (!host || host.dataset.filled === "1") return;
    host.innerHTML = GOAL_BAR_GRADIENT_PRESETS.map((c) => `
      <button type="button" class="goal-bar-swatch goal-bar-swatch-grad" data-goal-preset="${c.id}"
        data-goal-kind="${kind}" data-goal-mode="gradient"
        data-goal-from="${c.from}" data-goal-to="${c.to}"
        title="${c.label}" aria-label="${c.label}"
        style="background-image:linear-gradient(90deg, ${c.from}, ${c.to}) !important; background-color:transparent !important;"></button>
    `).join("");
    host.dataset.filled = "1";
  };
  fillSolid("goalBarProgressSolid", "progress");
  fillGrad("goalBarProgressGrad", "progress");
  fillSolid("goalBarCompleteSolid", "complete");
  fillGrad("goalBarCompleteGrad", "complete");
  fillSolid("goalBarOverflowSolid", "overflow");
  fillGrad("goalBarOverflowGrad", "overflow");
}

function setupGoalBarColorMenu() {
  goalBarColorOverrides = loadGoalBarColorOverrides();
  goalBarColors = resolveGoalBarColors(goalBarColorOverrides);
  ensureGoalBarSwatchesFilled();
  applyGoalBarColorsToDom();

  $("statusBarProgress")?.addEventListener("contextmenu", (event) => {
    event.preventDefault();
    event.stopPropagation();
    const target = $("statusBarProgress");
    setUiFeatureCtxTarget?.(target);
    showGoalBarColorMenu(target);
  });
  // Also allow right-click directly on the bar fill.
  $("sceneGoalBar")?.addEventListener("contextmenu", (event) => {
    event.preventDefault();
    event.stopPropagation();
    const target = $("statusBarProgress") || $("sceneGoalBar");
    setUiFeatureCtxTarget?.(target);
    showGoalBarColorMenu(target);
  });

  const menu = $("goalBarColorMenu");
  if (menu && menu.dataset.bound !== "1") {
    menu.dataset.bound = "1";
    menu.addEventListener("mousedown", (event) => {
      // Keep menu open; avoid status-bar blur quirks.
      event.stopPropagation();
    });
    menu.addEventListener("click", (event) => {
      event.stopPropagation();
      const swatch = event.target.closest("[data-goal-preset]");
      if (swatch) {
        const kind = swatch.dataset.goalKind;
        const mode = swatch.dataset.goalMode;
        if (!kind || !mode) return;
        let entry;
        if (mode === "gradient") {
          entry = {
            mode: "gradient",
            from: swatch.dataset.goalFrom,
            to: swatch.dataset.goalTo,
            id: swatch.dataset.goalPreset || "",
          };
        } else {
          const presetId = swatch.dataset.goalPreset || "";
          entry = {
            mode: "solid",
            hex: presetId === "primary"
              ? resolveThemePrimaryHex()
              : (swatch.dataset.goalHex || resolveThemePrimaryHex()),
            id: presetId,
          };
        }
        saveGoalBarColorOverride(kind, entry);
        return;
      }
      if (event.target.closest("[data-goal-color-reset]")) {
        resetGoalBarColorOverrides();
        hideGoalBarColorMenu();
        toast(i18n.t('app.게이지_색을_테마_기본값으로_돌렸습니다'));
      }
    });
  }

  document.addEventListener("click", (event) => {
    if (event.target.closest("#goalBarColorMenu, #statusBarProgress, #sceneGoalBar")) return;
    hideGoalBarColorMenu();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") hideGoalBarColorMenu();
  });
  window.addEventListener("blur", hideGoalBarColorMenu);
  window.addEventListener("resize", hideGoalBarColorMenu);
}

let projectStatsTimer = null;
let projectStatsInFlight = false;
let projectStatsNeedsRefresh = false;
let projectStatsCache = null;
let projectGoalSaveTimer = null;
let sceneGoalSaveTimer = null;

function renderProjectManuscriptStats(stats, { stale = false } = {}) {
  if (!stats) return;
  projectStatsCache = stats;
  if (stale) {
    const scenesChip = document.querySelector('#statsCounts [data-stat="scenes"]');
    if (scenesChip) scenesChip.title = i18n.t('app.전체_집계를_불러오지_못함_서버_재시작_후');
  }
  // Repaint when the footer is showing project totals.
  if (isProjectStatsScope()) updateSceneStats();
}

function scheduleProjectManuscriptStats() {
  if (!state.projectId) return;
  if (projectStatsTimer) window.clearTimeout(projectStatsTimer);
  projectStatsTimer = window.setTimeout(() => {
    refreshProjectManuscriptStats().catch(() => { /* quiet */ });
  }, 500);
}

async function refreshProjectManuscriptStats() {
  if (!state.projectId) return;
  if (projectStatsInFlight) {
    projectStatsNeedsRefresh = true;
    return;
  }
  projectStatsInFlight = true;
  projectStatsNeedsRefresh = false;
  const projectId = state.projectId;
  try {
    const stats = await api(`/api/projects/${projectId}/manuscript-stats`);
    if (Number(state.projectId) !== Number(projectId)) return;
    renderProjectManuscriptStats(stats);
  } catch (error) {
    if (projectStatsCache) {
      renderProjectManuscriptStats(projectStatsCache, { stale: true });
    } else {
      renderProjectManuscriptStats(
        {
          chars_with_space: 0,
          chars_no_space: 0,
          words: 0,
          letters: 0,
          scenes: 0,
          scenes_with_text: 0,
        },
        { stale: true },
      );
    }
  } finally {
    projectStatsInFlight = false;
    if (projectStatsNeedsRefresh) {
      projectStatsNeedsRefresh = false;
      scheduleProjectManuscriptStats();
    }
  }
}

function syncProjectGoalFromState() {
  const project = state.projects?.find((p) => Number(p.id) === Number(state.projectId));
  const goal = Math.max(0, Number(state.projectGoalCount ?? project?.goal_word_count ?? 0) || 0);
  state.projectGoalCount = goal;
  if ($("projectGoalCount")) $("projectGoalCount").value = String(goal);
  if (isProjectStatsScope() && $("statsGoalInput")) {
    $("statsGoalInput").value = String(goal);
  }
}

function scheduleProjectGoalSave() {
  if (!state.projectId) return;
  if (projectGoalSaveTimer) window.clearTimeout(projectGoalSaveTimer);
  projectGoalSaveTimer = window.setTimeout(() => {
    persistProjectGoal().catch(handleError);
  }, 600);
}

async function persistProjectGoal() {
  if (!state.projectId) return;
  const goal = Math.max(0, Number($("projectGoalCount")?.value || state.projectGoalCount || 0) || 0);
  state.projectGoalCount = goal;
  if ($("projectGoalCount")) $("projectGoalCount").value = String(goal);
  const result = await api(`/api/projects/${state.projectId}/settings`, {
    method: "PUT",
    body: JSON.stringify({ goal_word_count: goal }),
  });
  const project = state.projects?.find((p) => Number(p.id) === Number(state.projectId));
  if (project) project.goal_word_count = goal;
  if (result?.goal_word_count != null && project) {
    project.goal_word_count = Number(result.goal_word_count) || 0;
    state.projectGoalCount = Number(result.goal_word_count) || 0;
  }
  updateSceneStats();
}

function syncGoalFromVisibleInput() {
  const goal = Math.max(0, Number($("statsGoalInput")?.value || 0) || 0);
  if (isProjectStatsScope()) {
    if ($("projectGoalCount")) $("projectGoalCount").value = String(goal);
    state.projectGoalCount = goal;
  } else {
    if ($("sceneGoalCount")) $("sceneGoalCount").value = String(goal);
  }
  return goal;
}

function scheduleSceneGoalSave() {
  if (!state.sceneId || isProjectStatsScope()) return;
  if (sceneGoalSaveTimer) window.clearTimeout(sceneGoalSaveTimer);
  sceneGoalSaveTimer = window.setTimeout(() => {
    persistSceneGoal({ quiet: true }).catch(handleError);
  }, 500);
}

async function persistSceneGoal(options = {}) {
  const quiet = options.quiet !== false;
  if (!state.sceneId || !state.scene) return null;
  const goal = Math.max(0, Number($("sceneGoalCount")?.value || $("statsGoalInput")?.value || 0) || 0);
  const metric = getGoalMetric();
  if ($("sceneGoalCount")) $("sceneGoalCount").value = String(goal);
  if (!isProjectStatsScope() && $("statsGoalInput")) $("statsGoalInput").value = String(goal);
  const result = await api(`/api/scenes/${state.sceneId}/goal`, {
    method: "PUT",
    body: JSON.stringify({ goal_word_count: goal, goal_metric: metric }),
  });
  if (state.scene && Number(state.sceneId)) {
    state.scene.goal_word_count = goal;
    state.scene.goal_metric = metric;
  }
  updateSceneStats();
  if (!quiet) toast(i18n.t("app.저장했습니다"));
  return result;
}

function onStatsGoalInput() {
  syncGoalFromVisibleInput();
  updateSceneStats();
  if (isProjectStatsScope()) {
    scheduleProjectGoalSave();
    return;
  }
  if (state.sceneId) {
    markSceneDirty();
    scheduleSceneGoalSave();
  }
}

async function saveStatusBar(event) {
  if (event) event.preventDefault();
  syncGoalFromVisibleInput();
  if (isProjectStatsScope()) {
    if (projectGoalSaveTimer) {
      window.clearTimeout(projectGoalSaveTimer);
      projectGoalSaveTimer = null;
    }
    try {
      await persistProjectGoal();
    } catch (error) {
      handleError(error);
      return;
    }
  } else if (state.sceneId) {
    if (sceneGoalSaveTimer) {
      window.clearTimeout(sceneGoalSaveTimer);
      sceneGoalSaveTimer = null;
    }
    try {
      await persistSceneGoal({ quiet: true });
    } catch (error) {
      handleError(error);
      return;
    }
  }
  await saveScene();
}

/* —— Bulk-apply scene goals (right-click on 목표) —— */
function hideGoalBulkMenu() {
  $("goalBulkMenu")?.classList.add("hidden");
}

function showGoalBulkMenu(anchorEl) {
  const menu = $("goalBulkMenu");
  if (!menu || !anchorEl) return;
  hideGoalBarColorMenu?.();
  hideFormatApplyAllMenu?.();
  const goal = Math.max(0, Number($("statsGoalInput")?.value || $("sceneGoalCount")?.value || 0) || 0);
  const metric = getGoalMetric();
  const metricLabel = COUNT_METRIC_LABEL[metric] || metric;
  const label = $("goalBulkMenuLabel");
  if (label) {
    label.textContent = `${i18n.t('app.목표_formatStatNumber_goal', {'formatStatNumber(goal)': formatStatNumber(goal), metricLabel: metricLabel})}`;
  }
  menu.classList.remove("hidden");
  const rect = anchorEl.getBoundingClientRect();
  const pad = 8;
  const mw = menu.offsetWidth || 240;
  const mh = menu.offsetHeight || 100;
  let left = rect.left;
  let top = rect.bottom + 4;
  if (left + mw > window.innerWidth - pad) left = Math.max(pad, window.innerWidth - mw - pad);
  if (top + mh > window.innerHeight - pad) top = Math.max(pad, rect.top - mh - 4);
  menu.style.left = `${Math.max(pad, left)}px`;
  menu.style.top = `${Math.max(pad, top)}px`;
}

async function bulkApplySceneGoals({ includeMetric = false } = {}) {
  if (!state.projectId) {
    toast(i18n.t('app.작품을_먼저_선택해_주세요'));
    return;
  }
  const goal = Math.max(0, Number($("statsGoalInput")?.value || $("sceneGoalCount")?.value || 0) || 0);
  const metric = getGoalMetric();
  const metricLabel = COUNT_METRIC_LABEL[metric] || metric;
  const unitHint = metric === "words" ? i18n.t('app.단어') : i18n.t('app.자');
  const msg = includeMetric
    ? `${i18n.t('app.모든_씬에_목표_formatStatNumbe', {'formatStatNumber(goal)': formatStatNumber(goal), unitHint: unitHint, metricLabel: metricLabel})}`
    : `모든 씬에 목표 ${formatStatNumber(goal)}${unitHint}을(를) 일괄 적용할까요?\n(집계 기준은 각 씬 설정을 유지합니다)`;
  if (!window.confirm(msg)) return;

  const body = { goal_word_count: goal };
  if (includeMetric) body.goal_metric = metric;

  try {
    // When only count is applied, still send current metric only if API requires it —
    // backend defaults metric when omitted... our API always sets metric from body.
    // So for count-only we need backend to keep existing metrics.
    const result = await api(`/api/projects/${state.projectId}/scene-goals`, {
      method: "POST",
      body: JSON.stringify(includeMetric
        ? { goal_word_count: goal, goal_metric: metric, apply_metric: true }
        : { goal_word_count: goal, apply_metric: false }),
    });
    const n = Number(result?.count || 0) || 0;
    // Keep open scene fields in sync.
    if ($("sceneGoalCount")) $("sceneGoalCount").value = String(goal);
    if ($("statsGoalInput") && !isProjectStatsScope()) $("statsGoalInput").value = String(goal);
    if (includeMetric && $("sceneGoalMetric") && result?.goal_metric) {
      $("sceneGoalMetric").value = result.goal_metric;
    }
    if (state.scene) {
      state.scene.goal_word_count = goal;
      if (includeMetric && result?.goal_metric) state.scene.goal_metric = result.goal_metric;
      // Server bumped row_version for every scene; keep open scene in sync.
      if (state.scene.row_version != null) {
        state.scene.row_version = Number(state.scene.row_version) + 1;
      }
    }
    // Bulk already persisted goals — clear dirty only if nothing else is pending content edits.
    // (Do not force clean; user may still have unsaved manuscript text.)
    updateSceneStats();
    toast(n ? `${i18n.t('app.목표를_씬_n_개에_적용했습니다', {n: n})}` : i18n.t('app.적용할_씬이_없어요'));
  } catch (error) {
    handleError(error);
  }
}

function openGoalBulkMenuFrom(event, anchorEl) {
  event.preventDefault();
  event.stopPropagation();
  const host = $("statusBarGoalControls");
  const anchor = anchorEl || host || event.currentTarget;
  setUiFeatureCtxTarget?.(host || anchor);
  showGoalBulkMenu(anchor);
}

function setupGoalBulkMenu() {
  const host = $("statusBarGoalControls");
  const saveBtn = $("statusSaveButton")
    || document.querySelector(".manuscript-status-wrap .status-save-btn");
  host?.addEventListener("contextmenu", (event) => openGoalBulkMenuFrom(event, host));
  // Input often swallows contextmenu — bind explicitly too.
  $("statsGoalInput")?.addEventListener("contextmenu", (event) => {
    openGoalBulkMenuFrom(event, host || $("statsGoalInput"));
  });
  $("statsGoalLabel")?.addEventListener("contextmenu", (event) => {
    openGoalBulkMenuFrom(event, host || $("statsGoalLabel"));
  });
  // 목표 옆 「저장」에서도 우클릭 → 전체 적용 (서식 도구와 같은 패턴)
  saveBtn?.addEventListener("contextmenu", (event) => {
    openGoalBulkMenuFrom(event, saveBtn);
  });

  const menu = $("goalBulkMenu");
  if (menu && menu.dataset.bound !== "1") {
    menu.dataset.bound = "1";
    menu.addEventListener("click", (event) => {
      const item = event.target.closest?.("[data-goal-bulk]");
      if (!item) return;
      const mode = item.dataset.goalBulk;
      hideGoalBulkMenu();
      if (mode === "all-scenes") {
        bulkApplySceneGoals({ includeMetric: false }).catch(handleError);
      } else if (mode === "all-scenes-metric") {
        bulkApplySceneGoals({ includeMetric: true }).catch(handleError);
      }
    });
  }
  document.addEventListener("click", (event) => {
    if (event.target.closest("#goalBulkMenu, #statusBarGoalControls, #statusSaveButton, .status-save-btn")) {
      return;
    }
    hideGoalBulkMenu();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") hideGoalBulkMenu();
  });
  window.addEventListener("blur", hideGoalBulkMenu);
  window.addEventListener("resize", hideGoalBulkMenu);
}

/* —— Find in current manuscript (돋보기) —— */
let findMatches = [];
let findIndex = -1;

function clearFindHighlights(editor = $("sceneContent")) {
  if (!editor) return;
  editor.querySelectorAll("mark.find-hit").forEach((mark) => {
    const parent = mark.parentNode;
    if (!parent) return;
    while (mark.firstChild) parent.insertBefore(mark.firstChild, mark);
    parent.removeChild(mark);
    parent.normalize?.();
  });
  findMatches = [];
  findIndex = -1;
}

function updateFindCountUi() {
  const el = $("findCount");
  if (!el) return;
  if (!findMatches.length) {
    el.textContent = "0/0";
    return;
  }
  el.textContent = `${findIndex + 1}/${findMatches.length}`;
}

function setFindCurrent(index) {
  if (!findMatches.length) {
    findIndex = -1;
    updateFindCountUi();
    return;
  }
  findMatches.forEach((m) => m.classList.remove("find-hit-current"));
  findIndex = ((index % findMatches.length) + findMatches.length) % findMatches.length;
  const mark = findMatches[findIndex];
  mark.classList.add("find-hit-current");
  try {
    mark.scrollIntoView({ block: "center", behavior: "smooth", inline: "nearest" });
  } catch (_) {
    mark.scrollIntoView(true);
  }
  updateFindCountUi();
}

function runFindInEditor(query) {
  const editor = $("sceneContent");
  if (!editor) return;
  clearFindHighlights(editor);
  const q = String(query || "");
  if (!q) {
    updateFindCountUi();
    return;
  }
  const needle = q.toLowerCase();
  const walker = document.createTreeWalker(editor, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      if (!node.nodeValue || !node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
      if (node.parentElement?.closest?.("mark.find-hit")) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    },
  });
  const textNodes = [];
  while (walker.nextNode()) textNodes.push(walker.currentNode);

  const marks = [];
  for (const node of textNodes) {
    const text = node.nodeValue;
    const lower = text.toLowerCase();
    let from = 0;
    const parts = [];
    while (from < text.length) {
      const at = lower.indexOf(needle, from);
      if (at < 0) {
        parts.push(document.createTextNode(text.slice(from)));
        break;
      }
      if (at > from) parts.push(document.createTextNode(text.slice(from, at)));
      const mark = document.createElement("mark");
      mark.className = "find-hit";
      mark.textContent = text.slice(at, at + q.length);
      parts.push(mark);
      marks.push(mark);
      from = at + q.length;
    }
    if (parts.length === 1 && parts[0].nodeType === 3) continue;
    const parent = node.parentNode;
    if (!parent) continue;
    for (const p of parts) parent.insertBefore(p, node);
    parent.removeChild(node);
  }
  findMatches = marks;
  if (findMatches.length) setFindCurrent(0);
  else updateFindCountUi();
}

function openFindBar() {
  const bar = $("findBar");
  const toggle = $("findToggleButton");
  if (!bar) return;
  if ($("formatToolbarShell")?.classList.contains("is-collapsed")) {
    applyMsToolbarCollapsed("format", false, { toastMsg: false });
  }
  bar.classList.remove("hidden");
  toggle?.setAttribute("aria-expanded", "true");
  requestAnimationFrame(() => {
    $("findInput")?.focus();
    $("findInput")?.select();
  });
  const q = $("findInput")?.value || "";
  if (q) runFindInEditor(q);
}

function closeFindBar() {
  const bar = $("findBar");
  const toggle = $("findToggleButton");
  bar?.classList.add("hidden");
  toggle?.setAttribute("aria-expanded", "false");
  clearFindHighlights();
  updateFindCountUi();
}

function setupFindBar() {
  $("findToggleButton")?.addEventListener("click", () => {
    if ($("findBar")?.classList.contains("hidden")) openFindBar();
    else closeFindBar();
  });
  $("findCloseButton")?.addEventListener("click", closeFindBar);
  $("findNextButton")?.addEventListener("click", () => setFindCurrent(findIndex + 1));
  $("findPrevButton")?.addEventListener("click", () => setFindCurrent(findIndex - 1));
  let findTimer = null;
  $("findInput")?.addEventListener("input", () => {
    if (findTimer) window.clearTimeout(findTimer);
    findTimer = window.setTimeout(() => runFindInEditor($("findInput")?.value || ""), 120);
  });
  $("findInput")?.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      if (event.shiftKey) setFindCurrent(findIndex - 1);
      else setFindCurrent(findIndex + 1);
    } else if (event.key === "Escape") {
      event.preventDefault();
      closeFindBar();
    }
  });
  document.addEventListener("keydown", (event) => {
    if (!(event.ctrlKey || event.metaKey)) return;
    if (event.key.toLowerCase() !== "f") return;
    // Only when scene editor is visible
    if ($("sceneWorkspace")?.classList.contains("hidden")) return;
    if (isFocusWriteOpen()) return;
    if (typeof isViewerOpen === "function" && isViewerOpen()) return;
    event.preventDefault();
    openFindBar();
  });
}

/* —— AI 유사단어 찾기 (단어찾기) —— */
const SIMILAR_WORD_MAX_SINGLE = 40;
const SIMILAR_WORD_MAX_PHRASE = 280;
let similarWordPanelAnchor = null;
let similarWordSuppressOutsideClickUntil = 0;

function normalizeSimilarWordQuery(raw, { allowPhrase = true } = {}) {
  const t = String(raw || "").replace(/\s+/g, " ").trim();
  if (!t) return "";
  const phrase = allowPhrase && isSimilarWordPhraseQuery(t);
  const max = phrase ? SIMILAR_WORD_MAX_PHRASE : SIMILAR_WORD_MAX_SINGLE;
  return t.slice(0, max);
}

/** 문장·구절(여러 어절) 여부 — 핵심 표현 선별 모드 */
function isSimilarWordPhraseQuery(text) {
  const t = String(text || "").replace(/\s+/g, " ").trim();
  if (!t) return false;
  if (/\s/.test(t)) return true;
  if (/[.?!,…。，、;；:："'“”‘’()（）\[\]]/.test(t)) return true;
  // 공백 없는 긴 한국어 구절
  return t.length >= 10;
}

function getSelectedWordForSimilar() {
  const editor = getActiveRichEditor?.() || $("sceneContent") || $("focusWriteEditor");
  try {
    const sel = window.getSelection();
    if (sel && sel.rangeCount && !sel.isCollapsed) {
      const range = sel.getRangeAt(0);
      if (editor && editor.contains(range.commonAncestorContainer)) {
        return normalizeSimilarWordQuery(sel.toString() || "");
      }
    }
  } catch (_) {
    /* ignore */
  }
  return "";
}

function ensureSimilarWordPanelOnBody() {
  const panel = $("similarWordPanel");
  if (!panel) return null;
  if (panel.parentElement !== document.body) {
    document.body.appendChild(panel);
  }
  return panel;
}

function closeSimilarWordPanel() {
  const panel = $("similarWordPanel");
  panel?.classList.add("hidden");
  $("similarWordButton")?.setAttribute("aria-expanded", "false");
}

function positionSimilarWordPanel() {
  const panel = $("similarWordPanel");
  if (!panel || panel.classList.contains("hidden")) return;
  const btn = $("similarWordButton");
  const pad = 8;
  const pw = panel.offsetWidth || 340;
  const ph = panel.offsetHeight || 280;
  let left;
  let top;
  if (similarWordPanelAnchor
    && Number.isFinite(similarWordPanelAnchor.x)
    && Number.isFinite(similarWordPanelAnchor.y)) {
    left = similarWordPanelAnchor.x + 4;
    top = similarWordPanelAnchor.y + 4;
    if (left + pw > window.innerWidth - pad) left = Math.max(pad, similarWordPanelAnchor.x - pw - 4);
    if (top + ph > window.innerHeight - pad) top = Math.max(pad, similarWordPanelAnchor.y - ph - 4);
  } else if (btn) {
    const rect = btn.getBoundingClientRect();
    left = rect.right - pw;
    top = rect.bottom + 6;
    if (left < pad) left = pad;
    if (left + pw > window.innerWidth - pad) left = Math.max(pad, window.innerWidth - pw - pad);
    if (top + ph > window.innerHeight - pad) top = Math.max(pad, rect.top - ph - 6);
  } else {
    left = Math.max(pad, (window.innerWidth - pw) / 2);
    top = Math.max(pad, (window.innerHeight - ph) / 3);
  }
  panel.style.left = `${left}px`;
  panel.style.top = `${top}px`;
}

/**
 * @param {{ word?: string, autoRun?: boolean, anchorClientX?: number, anchorClientY?: number }} [options]
 */
function openSimilarWordPanel(options = {}) {
  const panel = ensureSimilarWordPanelOnBody();
  const btn = $("similarWordButton");
  if (!panel) return;
  // 우클릭으로 연 직후 document click 가 패널을 닫지 않도록
  similarWordSuppressOutsideClickUntil = Date.now() + 400;
  if ($("formatToolbarShell")?.classList.contains("is-collapsed")
    || document.querySelector('[data-toolbar-row="format-icons"]')?.classList.contains("is-collapsed")) {
    applyMsToolbarCollapsed?.("format-icons", false, { toastMsg: false });
  }
  closeFindBar?.();
  hideFormatListPalette?.();
  hideFormatSpecialPalette?.();
  hideFormatColorPalette?.();
  const word = normalizeSimilarWordQuery(options.word || getSelectedWordForSimilar() || "");
  const phrase = isSimilarWordPhraseQuery(word);
  const input = $("similarWordInput");
  if (input) {
    input.value = word;
    input.maxLength = phrase ? SIMILAR_WORD_MAX_PHRASE : SIMILAR_WORD_MAX_SINGLE;
    input.placeholder = phrase
      ? i18n.t('app.문장에서_핵심_표현을_골라_찾아_줘요')
      : i18n.t('app.원고에서_고르거나_입력');
  }
  const hint = $("similarWordHint");
  if (hint) {
    hint.textContent = phrase
      ? i18n.t('app.문장_구절이면_안의_핵심_단어_표현을_골라')
      : i18n.t('app.비슷하지만_다른_표현을_찾고_싶을_때_유용해');
  }
  const titleEl = panel.querySelector(".similar-word-panel-head strong");
  if (titleEl) titleEl.textContent = phrase ? i18n.t('app.표현_찾기') : i18n.t('app.단어찾기');
  if (Number.isFinite(options.anchorClientX) && Number.isFinite(options.anchorClientY)) {
    similarWordPanelAnchor = { x: options.anchorClientX, y: options.anchorClientY };
  } else if (btn) {
    similarWordPanelAnchor = null;
  }
  panel.classList.remove("hidden");
  btn?.setAttribute("aria-expanded", "true");
  positionSimilarWordPanel();
  requestAnimationFrame(() => {
    positionSimilarWordPanel();
    input?.focus();
    if (word && !phrase) input?.select();
    if (options.autoRun && word) {
      runSimilarWordFind().catch(handleError);
    }
  });
}

/** 우클릭 메뉴 → 단어찾기 (툴바 버튼과 동일 기능) */
function openSimilarWordsFromSelection(anchorEvent = null) {
  const raw = (pendingBaitQuote || getSelectedManuscriptText() || getSelectedWordForSimilar() || "").trim();
  if (!raw) {
    toast(i18n.t('app.본문에서_단어나_문장을_드래그로_선택한_뒤'));
    return;
  }
  const word = normalizeSimilarWordQuery(raw);
  openSimilarWordPanel({
    word,
    autoRun: true,
    anchorClientX: anchorEvent?.clientX,
    anchorClientY: anchorEvent?.clientY,
  });
}

function renderSimilarWordResult(text, word, { phrase = false } = {}) {
  const host = $("similarWordResult");
  if (!host) return;
  const raw = String(text || "").trim();
  if (!raw) {
    host.innerHTML = i18n.t('app.p_class_similar_word_em');
    return;
  }

  const addChip = (chips, seen, w) => {
    const t = String(w || "")
      .replace(/^[-*•·\d.)\s]+/, "")
      .replace(/^[「『"“'‘]+|[」』"”'’]+$/g, "")
      .replace(/^(유사어|대체|표현)\s*[:：]\s*/i, "")
      .trim();
    if (!t || t.length > 28 || t.length < 1) return;
    if (seen.has(t)) return;
    if (t === word) return;
    seen.add(t);
    chips.push(t);
  };

  const chipRow = (chips) => (chips.length
    ? `<div class="similar-word-chips" role="list">${chips.slice(0, 36).map((c) =>
      `<button type="button" class="similar-word-chip" role="listitem" data-insert-word="${escapeHtml(c)}">${escapeHtml(c)}</button>`
    ).join("")}</div>`
    : "");

  // 문장 모드: ### 선별: … 블록별 그룹
  if (phrase) {
    const blocks = [];
    let cur = null;
    raw.split(/\n/).forEach((line) => {
      const head = line.match(/^#{1,3}\s*선별\s*[:：]?\s*(.+)\s*$/i);
      if (head) {
        const label = String(head[1] || "").trim();
        if (label) {
          cur = { label, lines: [] };
          blocks.push(cur);
          return;
        }
      }
      if (/^#{1,3}\s*뉘앙스/.test(line.trim())) {
        cur = { label: i18n.t('app.뉘앙스_메모'), lines: [] };
        blocks.push(cur);
        return;
      }
      if (!cur) {
        cur = { label: i18n.t('app.제안'), lines: [] };
        blocks.push(cur);
      }
      cur.lines.push(line);
    });
    if (blocks.length) {
      host.innerHTML = blocks.map((block) => {
        const seen = new Set();
        const chips = [];
        block.lines.forEach((line) => {
          const cleaned = line.replace(/^#+\s*/, "").replace(/^[-*•]\s*/, "").trim();
          if (!cleaned || /^뉘앙스/.test(cleaned)) return;
          if (/[,，、·/|]/.test(cleaned) && cleaned.length < 160) {
            cleaned.split(/[,，、·/|]+/).forEach((part) => addChip(chips, seen, part));
          } else if (cleaned.length <= 28) {
            addChip(chips, seen, cleaned);
          }
        });
        const bodyText = block.lines.join("\n").trim();
        return (
          `<section class="similar-word-group">`
          + `<h4 class="similar-word-group-title">${escapeHtml(block.label)}</h4>`
          + chipRow(chips)
          + (bodyText
            ? `<div class="similar-word-markdown">${escapeHtml(bodyText).replace(/\n/g, "<br>")}</div>`
            : "")
          + `</section>`
        );
      }).join("");
      return;
    }
  }

  const chips = [];
  const seen = new Set();
  raw.split(/\n/).forEach((line) => {
    const cleaned = line.replace(/^#+\s*/, "").replace(/^[-*•]\s*/, "").trim();
    if (!cleaned || cleaned.startsWith("###") || cleaned.startsWith(i18n.t('app.뉘앙스'))) return;
    if (/[,，、·/|]/.test(cleaned) && cleaned.length < 120) {
      cleaned.split(/[,，、·/|]+/).forEach((part) => addChip(chips, seen, part));
    } else if (cleaned.length <= 24 && !cleaned.includes(" ")) {
      addChip(chips, seen, cleaned);
    } else if (cleaned.startsWith("-") || line.trim().startsWith("-")) {
      addChip(chips, seen, cleaned);
    }
  });
  host.innerHTML = `
    ${chipRow(chips)}
    <div class="similar-word-markdown">${escapeHtml(raw).replace(/\n/g, "<br>")}</div>
  `;
}

async function runSimilarWordFind() {
  const input = $("similarWordInput");
  let word = normalizeSimilarWordQuery(input?.value || "");
  if (!word) word = getSelectedWordForSimilar();
  if (!word) {
    toast(i18n.t('app.원고에서_단어나_문장을_드래그하거나_입력란에'));
    input?.focus();
    return;
  }
  const phrase = isSimilarWordPhraseQuery(word);
  if (input) {
    input.value = word;
    input.maxLength = phrase ? SIMILAR_WORD_MAX_PHRASE : SIMILAR_WORD_MAX_SINGLE;
  }
  ensureSimilarWordPanelOnBody();
  const panel = $("similarWordPanel");
  panel?.classList.remove("hidden");
  const resultEl = $("similarWordResult");
  const hint = $("similarWordHint");
  const runBtn = $("similarWordRun");
  if (resultEl) {
    resultEl.innerHTML = `<p class="similar-word-loading">${
      phrase ? i18n.t('app.토리가_문장_속_핵심_표현을_고르는_중') : i18n.t('app.토리가_비슷한_말을_찾는_중')
    }</p>`;
  }
  if (hint) {
    hint.textContent = phrase
      ? i18n.t('app.문장_구절이면_안의_핵심_단어_표현을_골라')
      : i18n.t('app.비슷하지만_다른_표현을_찾고_싶을_때_유용해');
  }
  if (runBtn) {
    runBtn.disabled = true;
    runBtn.textContent = i18n.t('app.찾는_중');
  }
  try {
    const project = state.projects?.find?.((item) => item.id === state.projectId);
    const sceneTitle = $("sceneTitle")?.value?.trim()
      || state.scene?.title
      || "";
    const sceneSynopsis = $("sceneSynopsis")?.value?.trim()
      || state.scene?.synopsis
      || "";
    let sceneContent = "";
    try {
      const ed = getActiveRichEditor?.() || $("sceneContent");
      sceneContent = (ed?.innerText || ed?.textContent || "").slice(0, 2500);
    } catch (_) {
      sceneContent = "";
    }
    const body = {
      mode: "similar_words",
      word,
      selected_text: word,
      user_prompt: word,
      phrase_mode: phrase,
      project_title: project?.title || state.projectTitle || "",
      purpose: state.purpose || project?.purpose || "general_novel",
      main_genre: state.mainGenre || project?.main_genre || "",
      sub_genre: state.subGenre || project?.sub_genre || "",
      scene_title: sceneTitle,
      scene_synopsis: sceneSynopsis,
      scene_content: sceneContent,
      project_id: state.projectId || null,
      focus_scene_only: true,
      tory_focus: true,
      persona_mode: typeof getToryPersonaMode === "function" ? getToryPersonaMode() : "default",
    };
    if (typeof buildToryProjectContextPayload === "function") {
      Object.assign(body, buildToryProjectContextPayload());
    }
    const result = await api("/api/ai/assist", {
      method: "POST",
      body: JSON.stringify(body),
    });
    // 비동기 중 닫혔어도 결과 오면 다시 연다
    ensureSimilarWordPanelOnBody();
    $("similarWordPanel")?.classList.remove("hidden");
    renderSimilarWordResult(result?.text || "", word, { phrase });
    if (hint) {
      hint.textContent = phrase
        ? i18n.t('app.칩을_누르면_본문에_넣어요_선별된_표현별로')
        : i18n.t('app.비슷하지만_다른_표현을_찾고_싶을_때_유용해');
    }
    toast(phrase ? i18n.t('app.문장_속_표현의_비슷한_말을_찾았어요') : i18n.t('app.유사_단어를_찾았어요'));
  } catch (error) {
    ensureSimilarWordPanelOnBody();
    $("similarWordPanel")?.classList.remove("hidden");
    if (resultEl) {
      resultEl.innerHTML = `${i18n.t('app.p_class_similar_word_em_2', {'escapeHtml(error?.message || "다시 시도해 주세요.")': escapeHtml(error?.message || "다시 시도해 주세요.")})}`;
    }
    handleError(error);
  } finally {
    if (runBtn) {
      runBtn.disabled = false;
      runBtn.textContent = i18n.t('app.찾기');
    }
    positionSimilarWordPanel();
  }
}

function setupSimilarWordFind() {
  const panel = ensureSimilarWordPanelOnBody();
  if (!panel || panel.dataset.bound === "1") return;
  panel.dataset.bound = "1";

  // 아이콘바 버튼은 제거됨 — 드래그 우클릭 메뉴에서만 사용
  $("similarWordButton")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (panel.classList.contains("hidden")) openSimilarWordPanel();
    else closeSimilarWordPanel();
  });
  $("similarWordClose")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    closeSimilarWordPanel();
  });
  $("similarWordRun")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    runSimilarWordFind().catch(handleError);
  });
  $("similarWordInput")?.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      runSimilarWordFind().catch(handleError);
    } else if (event.key === "Escape") {
      event.preventDefault();
      closeSimilarWordPanel();
    }
  });
  $("similarWordResult")?.addEventListener("click", (event) => {
    const chip = event.target.closest("[data-insert-word]");
    if (!chip) return;
    event.preventDefault();
    event.stopPropagation();
    const word = chip.dataset.insertWord;
    if (!word) return;
    const editor = getActiveRichEditor?.() || $("sceneContent");
    if (typeof insertSpecialChar === "function") {
      insertSpecialChar(word, editor);
    } else {
      try {
        focusEditor?.(editor);
        document.execCommand("insertText", false, word);
      } catch (_) {
        /* ignore */
      }
    }
    toast(`${i18n.t('app.word_을_를_넣었어요', {word: word})}`);
  });
  document.addEventListener("click", (event) => {
    if (Date.now() < similarWordSuppressOutsideClickUntil) return;
    if (event.target.closest("#similarWordPanel, #similarWordButton, #similarWordsMenuItem, #desktopContextMenu")) {
      return;
    }
    closeSimilarWordPanel();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") closeSimilarWordPanel();
  });
  window.addEventListener("resize", () => positionSimilarWordPanel());
}

/* —— 타자기 모드 (Typewriter Mode) —— */
const TYPEWRITER_MODE_STORAGE_KEY = "supertory.typewriterMode";
const TYPEWRITER_CENTER_RATIO = 0.47; /* 상단 기준 ~47% (45~50% 구간) */
let typewriterModeOn = false;
let typewriterSyncRaf = 0;
let typewriterLastSmooth = false;

function readTypewriterModePref() {
  try {
    return localStorage.getItem(TYPEWRITER_MODE_STORAGE_KEY) === "1";
  } catch (_) {
    return false;
  }
}

function writeTypewriterModePref(on) {
  try {
    localStorage.setItem(TYPEWRITER_MODE_STORAGE_KEY, on ? "1" : "0");
  } catch (_) {
    /* ignore */
  }
}

function getTypewriterEditor() {
  const focusModal = $("focusWriteModal");
  const focusEd = $("focusWriteEditor");
  if (focusEd && focusModal && !focusModal.classList.contains("hidden")) {
    if (document.activeElement === focusEd || focusEd.contains(document.activeElement)) {
      return focusEd;
    }
  }
  const active = document.activeElement;
  if (active) {
    const host = active.closest?.("#sceneContent, #focusWriteEditor, #synopsisContent, #synopsisContentB, .rich-editor");
    if (host?.isContentEditable || host?.getAttribute?.("contenteditable") === "true") return host;
    if (active.isContentEditable) return active;
  }
  return getActiveRichEditor?.() || $("sceneContent");
}

function getTypewriterScrollParent(editor) {
  if (!editor) return $("manuscriptPage");
  return (
    editor.closest(".manuscript-page")
    || editor.closest(".focus-write-body")
    || editor.closest(".focus-write-page")
    || $("manuscriptPage")
  );
}

function getCaretClientRectForTypewriter() {
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount) return null;
  const range = sel.getRangeAt(0);
  if (!range) return null;
  const collapsed = range.cloneRange();
  collapsed.collapse(true);
  const rects = collapsed.getClientRects();
  if (rects && rects.length) {
    const last = rects[rects.length - 1];
    if (last && (last.height > 0 || last.width > 0)) return last;
  }
  let rect = collapsed.getBoundingClientRect();
  if (rect && (rect.height > 0 || rect.width > 0)) return rect;
  // 빈 줄: 임시 마커로 측정 (선택 복원)
  try {
    const marker = document.createElement("span");
    marker.textContent = "\u200b";
    marker.style.cssText = "display:inline-block;width:0;height:1em;overflow:hidden;";
    collapsed.insertNode(marker);
    rect = marker.getBoundingClientRect();
    const parent = marker.parentNode;
    parent?.removeChild(marker);
    parent?.normalize?.();
    // 마커 삽입이 선택을 흐트릴 수 있어 원래 범위로 복원
    try {
      sel.removeAllRanges();
      sel.addRange(range);
    } catch (_) {
      /* ignore */
    }
    if (rect && (rect.height > 0 || rect.width > 0)) return rect;
  } catch (_) {
    /* ignore */
  }
  return null;
}

function ensureTypewriterHighlightEl(scrollParent) {
  if (!scrollParent) return null;
  let el = scrollParent.querySelector(":scope > .typewriter-line-highlight");
  if (el) return el;
  // manuscriptPage 기본 하이라이트를 다른 스크롤 부모로 옮기거나 복제
  el = document.createElement("div");
  el.className = "typewriter-line-highlight hidden";
  el.setAttribute("aria-hidden", "true");
  scrollParent.insertBefore(el, scrollParent.firstChild);
  return el;
}

function hideTypewriterHighlight() {
  document.querySelectorAll(".typewriter-line-highlight").forEach((node) => {
    node.classList.add("hidden");
  });
}

function updateTypewriterLineHighlight(scrollParent, caretRect) {
  const el = ensureTypewriterHighlightEl(scrollParent);
  if (!el || !caretRect || !scrollParent) {
    hideTypewriterHighlight();
    return;
  }
  const parentRect = scrollParent.getBoundingClientRect();
  const lineH = Math.max(caretRect.height || 0, 22);
  const top = scrollParent.scrollTop + (caretRect.top - parentRect.top) - (lineH - (caretRect.height || lineH)) * 0.15;
  el.style.top = `${Math.max(0, top)}px`;
  el.style.height = `${lineH}px`;
  el.style.left = "8px";
  el.style.right = "8px";
  el.classList.remove("hidden");
}

function syncTypewriterModeView(options = {}) {
  if (!typewriterModeOn) {
    hideTypewriterHighlight();
    return;
  }
  const editor = getTypewriterEditor();
  if (!editor) return;
  const scrollParent = getTypewriterScrollParent(editor);
  if (!scrollParent) return;
  if (!editor.contains(window.getSelection()?.anchorNode) && document.activeElement !== editor) {
    // 선택이 에디터 밖이면 하이라이트만 숨김 (스크롤은 유지)
    const pageHighlight = $("typewriterLineHighlight");
    if (pageHighlight && !editor.contains(pageHighlight)) {
      /* keep */
    }
  }
  const caretRect = getCaretClientRectForTypewriter();
  if (!caretRect) return;
  const parentRect = scrollParent.getBoundingClientRect();
  if (parentRect.height < 40) return;
  updateTypewriterLineHighlight(scrollParent, caretRect);

  const targetY = parentRect.top + parentRect.height * TYPEWRITER_CENTER_RATIO;
  const delta = caretRect.top + (caretRect.height || 0) * 0.35 - targetY;
  if (Math.abs(delta) < 1.5) return;

  const preferSmooth = options.smooth !== false && (options.forceSmooth || Math.abs(delta) > 28 || typewriterLastSmooth);
  typewriterLastSmooth = !!preferSmooth;
  const prevBehavior = scrollParent.style.scrollBehavior;
  if (preferSmooth) {
    scrollParent.classList.add("is-typewriter-mode");
    scrollParent.style.scrollBehavior = "smooth";
  } else {
    scrollParent.style.scrollBehavior = "auto";
  }
  const nextTop = Math.max(0, scrollParent.scrollTop + delta);
  try {
    scrollParent.scrollTo({ top: nextTop, behavior: preferSmooth ? "smooth" : "auto" });
  } catch (_) {
    scrollParent.scrollTop = nextTop;
  }
  // scroll-behavior 원복은 다음 프레임
  requestAnimationFrame(() => {
    if (prevBehavior) scrollParent.style.scrollBehavior = prevBehavior;
    else scrollParent.style.removeProperty("scroll-behavior");
  });
}

function scheduleTypewriterSync(options = {}) {
  if (!typewriterModeOn) return;
  if (typewriterSyncRaf) cancelAnimationFrame(typewriterSyncRaf);
  typewriterSyncRaf = requestAnimationFrame(() => {
    typewriterSyncRaf = 0;
    syncTypewriterModeView(options);
  });
}

function applyTypewriterModeUi(on) {
  typewriterModeOn = !!on;
  document.body.classList.toggle("typewriter-mode-on", typewriterModeOn);
  const btn = $("typewriterModeButton");
  if (btn) {
    btn.setAttribute("aria-pressed", typewriterModeOn ? "true" : "false");
    btn.classList.toggle("is-active", typewriterModeOn);
    btn.title = typewriterModeOn
      ? i18n.t('app.타자기_모드_켜짐_다시_누르면_끔')
      : i18n.t('app.타자기_모드_입력_줄을_화면_중앙에_고정');
  }
  const badge = $("typewriterModeOnBadge");
  if (badge) {
    badge.textContent = "on";
    badge.classList.toggle("hidden", !typewriterModeOn);
    badge.setAttribute("aria-hidden", typewriterModeOn ? "false" : "true");
  }
  $("manuscriptPage")?.classList.toggle("is-typewriter-mode", typewriterModeOn);
  if (!typewriterModeOn) {
    hideTypewriterHighlight();
    $("manuscriptPage")?.classList.remove("is-typewriter-mode");
  } else {
    scheduleTypewriterSync({ forceSmooth: true });
  }
}

function setTypewriterMode(on, options = {}) {
  applyTypewriterModeUi(on);
  writeTypewriterModePref(typewriterModeOn);
  if (options.announce) {
    toast(typewriterModeOn ? i18n.t('app.타자기_모드를_켰어요') : i18n.t('app.타자기_모드를_껐어요'));
  }
}

function toggleTypewriterMode(options = {}) {
  setTypewriterMode(!typewriterModeOn, options);
}

function setupTypewriterMode() {
  if (document.documentElement.dataset.typewriterBound === "1") return;
  document.documentElement.dataset.typewriterBound = "1";

  applyTypewriterModeUi(readTypewriterModePref());

  $("typewriterModeButton")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    toggleTypewriterMode({ announce: true });
  });

  const onEditorActivity = (event) => {
    if (!typewriterModeOn) return;
    const target = event.target;
    if (!target?.closest?.("#sceneContent, #focusWriteEditor, #synopsisContent, #synopsisContentB, .rich-editor, .manuscript-page")) {
      return;
    }
    const isEnter = event.type === "keydown" && event.key === "Enter";
    const isNav = event.type === "keydown" && (
      event.key === "ArrowUp" || event.key === "ArrowDown"
      || event.key === "PageUp" || event.key === "PageDown"
      || event.key === "Home" || event.key === "End"
    );
    scheduleTypewriterSync({
      forceSmooth: isEnter || isNav,
      smooth: true,
    });
  };

  document.addEventListener("input", onEditorActivity, true);
  document.addEventListener("keydown", onEditorActivity, true);
  document.addEventListener("keyup", onEditorActivity, true);
  document.addEventListener("mouseup", onEditorActivity, true);
  document.addEventListener("selectionchange", () => {
    if (!typewriterModeOn) return;
    const editor = getTypewriterEditor();
    const sel = window.getSelection();
    if (!editor || !sel?.anchorNode || !editor.contains(sel.anchorNode)) return;
    scheduleTypewriterSync({ smooth: true });
  });
  window.addEventListener("resize", () => {
    if (typewriterModeOn) scheduleTypewriterSync({ smooth: false });
  });
}

/* —— 스마트 문장부호 (따옴표 짝 자동완성) ——
 * 뮤블식 '엔터 후 홀수 추측'이 아니라, 코드 에디터 괄호처럼 입력 순간에 짝을 넣어요.
 * 직선 따옴표(" ')만 쓰고, 곡선형(“ ”)로 바꾸지 않아요.
 */
const SMART_PUNCTUATION_STORAGE_KEY = "supertory.smartPunctuation";
const SMART_PUNCTUATION_QUOTES = { '"': true, "'": true };
let smartPunctuationOn = true;
let smartPunctuationMute = false;

function readSmartPunctuationPref() {
  try {
    const raw = localStorage.getItem(SMART_PUNCTUATION_STORAGE_KEY);
    if (raw === null) return true;
    return raw !== "0";
  } catch (_) {
    return true;
  }
}

function writeSmartPunctuationPref(on) {
  try {
    localStorage.setItem(SMART_PUNCTUATION_STORAGE_KEY, on ? "1" : "0");
  } catch (_) {
    /* ignore */
  }
}

function isSmartPunctuationEnabled() {
  return smartPunctuationOn;
}

function getSmartPunctuationEditor(event) {
  const target = event?.target;
  if (!target?.closest) return null;
  const host = target.closest("#sceneContent, #focusWriteEditor, #synopsisContent, #synopsisContentB, [contenteditable].rich-editor");
  if (!host) return null;
  if (host.isContentEditable || host.getAttribute?.("contenteditable") === "true") return host;
  return null;
}

function syncSmartPunctuationMenuLabel() {
  const btn = $("smartPunctuationMenuItem");
  if (!btn) return;
  btn.textContent = smartPunctuationOn
    ? i18n.t("index.스마트_문장부호_끄기")
    : i18n.t("index.스마트_문장부호_켜기");
}

function setSmartPunctuationEnabled(on, options = {}) {
  smartPunctuationOn = !!on;
  writeSmartPunctuationPref(smartPunctuationOn);
  syncSmartPunctuationMenuLabel();
  if (options.announce) {
    toast(smartPunctuationOn
      ? i18n.t("index.스마트_문장부호를_켰어요")
      : i18n.t("index.스마트_문장부호를_껐어요"));
  }
}

function toggleSmartPunctuation(options = {}) {
  setSmartPunctuationEnabled(!smartPunctuationOn, options);
}

function peekAdjacentChar(direction) {
  const sel = window.getSelection();
  if (!sel?.rangeCount || !sel.isCollapsed) return "";
  const range = sel.getRangeAt(0);
  const node = range.startContainer;
  const offset = range.startOffset;
  if (node.nodeType === Node.TEXT_NODE) {
    if (direction > 0 && offset < node.data.length) {
      const ch = node.data.charAt(offset);
      if (ch === "\n" || ch === "\r") return "";
      return ch;
    }
    if (direction < 0 && offset > 0) {
      const ch = node.data.charAt(offset - 1);
      if (ch === "\n" || ch === "\r") return "";
      return ch;
    }
  }
  const saved = range.cloneRange();
  try {
    sel.modify("move", direction > 0 ? "forward" : "backward", "character");
    const moved = sel.getRangeAt(0);
    const probe = document.createRange();
    if (direction > 0) {
      probe.setStart(saved.startContainer, saved.startOffset);
      probe.setEnd(moved.startContainer, moved.startOffset);
    } else {
      probe.setStart(moved.startContainer, moved.startOffset);
      probe.setEnd(saved.startContainer, saved.startOffset);
    }
    const text = probe.toString();
    sel.removeAllRanges();
    sel.addRange(saved);
    if (!text || text.length !== 1 || text === "\n" || text === "\r") return "";
    return text;
  } catch (_) {
    try {
      sel.removeAllRanges();
      sel.addRange(saved);
    } catch (_) {
      /* ignore */
    }
    return "";
  }
}

function moveCaretOneChar(direction) {
  const sel = window.getSelection();
  if (!sel?.rangeCount) return;
  const range = sel.getRangeAt(0);
  const node = range.startContainer;
  const offset = range.startOffset;
  if (node.nodeType === Node.TEXT_NODE) {
    const next = offset + direction;
    if (next >= 0 && next <= node.data.length) {
      range.setStart(node, next);
      range.collapse(true);
      sel.removeAllRanges();
      sel.addRange(range);
      return;
    }
  }
  try {
    sel.modify("move", direction > 0 ? "forward" : "backward", "character");
  } catch (_) {
    /* ignore */
  }
}

function deleteEmptyQuotePairAroundCaret() {
  const sel = window.getSelection();
  if (!sel?.rangeCount || !sel.isCollapsed) return false;
  const origin = sel.getRangeAt(0).cloneRange();
  try {
    sel.modify("move", "backward", "character");
    const start = sel.getRangeAt(0).cloneRange();
    sel.removeAllRanges();
    sel.addRange(origin);
    sel.modify("move", "forward", "character");
    const end = sel.getRangeAt(0);
    const wipe = document.createRange();
    wipe.setStart(start.startContainer, start.startOffset);
    wipe.setEnd(end.startContainer, end.startOffset);
    sel.removeAllRanges();
    sel.addRange(wipe);
    smartPunctuationMute = true;
    try {
      document.execCommand("delete");
    } finally {
      smartPunctuationMute = false;
    }
    return true;
  } catch (_) {
    try {
      sel.removeAllRanges();
      sel.addRange(origin);
    } catch (_) {
      /* ignore */
    }
    return false;
  }
}

function insertSmartQuotePair(quote, selectedText) {
  smartPunctuationMute = true;
  try {
    document.execCommand("insertText", false, quote + selectedText + quote);
    moveCaretOneChar(-1);
  } finally {
    smartPunctuationMute = false;
  }
}

function onSmartPunctuationBeforeInput(event) {
  if (smartPunctuationMute || !smartPunctuationOn) return;
  if (event.isComposing || event.defaultPrevented) return;
  const editor = getSmartPunctuationEditor(event);
  if (!editor) return;
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount) return;
  if (!editor.contains(sel.anchorNode) && sel.anchorNode !== editor) return;

  const inputType = String(event.inputType || "");
  if (inputType === "deleteContentBackward") {
    if (!sel.isCollapsed) return;
    const prev = peekAdjacentChar(-1);
    const next = peekAdjacentChar(1);
    if (!SMART_PUNCTUATION_QUOTES[prev] || prev !== next) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    deleteEmptyQuotePairAroundCaret();
    return;
  }

  if (inputType !== "insertText") return;
  const quote = event.data;
  if (!quote || !SMART_PUNCTUATION_QUOTES[quote]) return;
  if (event.ctrlKey || event.metaKey || event.altKey) return;

  if (sel.isCollapsed) {
    if (peekAdjacentChar(1) === quote) {
      event.preventDefault();
      event.stopImmediatePropagation();
      moveCaretOneChar(1);
      return;
    }
    // don't → 영문 축약형은 홑따옴표 하나만. 한글 조사 뒤는 짝을 만들어요.
    if (quote === "'" && /[A-Za-z0-9]/.test(peekAdjacentChar(-1))) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    insertSmartQuotePair(quote, "");
    return;
  }

  const selected = sel.toString();
  event.preventDefault();
  event.stopImmediatePropagation();
  insertSmartQuotePair(quote, selected);
}

function setupSmartPunctuation() {
  if (document.documentElement.dataset.smartPunctuationBound === "1") return;
  document.documentElement.dataset.smartPunctuationBound = "1";
  smartPunctuationOn = readSmartPunctuationPref();
  syncSmartPunctuationMenuLabel();
  document.addEventListener("beforeinput", onSmartPunctuationBeforeInput, true);
}

function setupSceneStats() {
  syncStatsScopeUi();
  applyStatDisplayVisibility();
  setupGoalBarColorMenu();
  setupGoalBulkMenu();
  $("statsScopeSeg")?.addEventListener("click", (event) => {
    const btn = event.target.closest("[data-scope]");
    if (!btn || !$("statsScopeSeg").contains(btn)) return;
    setStatsScope(btn.dataset.scope);
  });
  $("sceneGoalMetric")?.addEventListener("change", updateSceneStats);
  $("statsGoalInput")?.addEventListener("input", onStatsGoalInput);
  $("statsGoalInput")?.addEventListener("change", onStatsGoalInput);
  $("statsGoalInput")?.addEventListener("blur", onStatsGoalInput);
  $("statsGoalInput")?.addEventListener("keydown", (event) => {
    if (event.key !== "Enter") return;
    event.preventDefault();
    saveStatusBar(event).catch(handleError);
  });
  $("statusSaveButton")?.addEventListener("click", (event) => {
    event.preventDefault();
    saveStatusBar(event).catch(handleError);
  });
  $("sceneContent")?.addEventListener("input", updateSceneStats);

  let statChipClickTimer = null;
  const onStatChipClick = (event) => {
    const chip = event.target.closest(".stat-chip");
    if (!chip || chip.classList.contains("stat-chip-static")) return;
    const group = chip.dataset.group;
    if (!group) return;
    if (group === "space") {
      if (statChipClickTimer) {
        window.clearTimeout(statChipClickTimer);
        statChipClickTimer = null;
      }
      selectSpaceMode(chip.dataset.stat === "chars_no_space" ? "without" : "with");
      return;
    }
    // Defer unit chips so double-click can cancel and set goal metric instead.
    if (statChipClickTimer) window.clearTimeout(statChipClickTimer);
    statChipClickTimer = window.setTimeout(() => {
      statChipClickTimer = null;
      if (group === "unit") cycleUnitMode();
    }, 220);
  };
  const onStatChipDblClick = (event) => {
    const chip = event.target.closest(".stat-chip");
    if (!chip || chip.classList.contains("stat-chip-static")) return;
    if (chip.dataset.group === "space") return;
    const metric = chip.dataset.stat;
    if (!COUNT_METRIC_LABEL[metric]) return;
    event.preventDefault();
    if (statChipClickTimer) {
      window.clearTimeout(statChipClickTimer);
      statChipClickTimer = null;
    }
    setGoalMetric(metric);
    toast(`${i18n.t('app.목표_기준_COUNT_METRIC_LABEL', {'COUNT_METRIC_LABEL[metric]': COUNT_METRIC_LABEL[metric]})}`);
  };
  $("statsCounts")?.addEventListener("click", onStatChipClick);
  $("statsCounts")?.addEventListener("dblclick", onStatChipDblClick);

  setupFindBar();
  setupSimilarWordFind();
  setupTypewriterMode();
  setupSmartPunctuation();
}

function updateEditorPlaceholder(editorEl = null) {
  const editor = editorEl || getActiveRichEditor() || $("sceneContent");
  if (!editor) return;
  const empty = !plainTextFromHtml(editor.innerHTML) && !editor.querySelector("img");
  editor.classList.toggle("placeholder-on", empty);
}

function focusEditor(editorEl = null) {
  const editor = editorEl || getActiveRichEditor() || $("sceneContent");
  editor?.focus();
}

function restoreSelection(range) {
  if (!range) return;
  const selection = window.getSelection();
  selection.removeAllRanges();
  selection.addRange(range);
}

function currentEditorRange(editorEl = null) {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) return null;
  const range = selection.getRangeAt(0);
  const editor = editorEl || getActiveRichEditor() || $("sceneContent");
  if (!editor || !editor.contains(range.commonAncestorContainer)) return null;
  return range;
}

/** Last non-empty selection in a rich editor — survives toolbar clicks that collapse the live selection. */
let lastEditorSelection = { editor: null, range: null };

function rememberLastEditorSelection(editorEl = null) {
  const editor = editorEl || getActiveRichEditor() || $("sceneContent");
  if (!editor) return null;
  try {
    const range = currentEditorRange(editor);
    if (!range || range.collapsed) return lastEditorSelection.range;
    // cloneRange so later DOM edits don't invalidate the live range object
    const cloned = range.cloneRange();
    lastEditorSelection = { editor, range: cloned };
    formatPaletteRange = cloned;
    formatPaletteEditor = editor;
    return cloned;
  } catch (_) {
    return lastEditorSelection.range;
  }
}

function getUsableEditorRange(editorEl = null) {
  const editor = editorEl || getActiveRichEditor() || $("sceneContent");
  if (!editor) return null;
  const live = currentEditorRange(editor);
  if (live && !live.collapsed) return live;
  if (
    lastEditorSelection.range
    && !lastEditorSelection.range.collapsed
    && lastEditorSelection.editor === editor
  ) {
    try {
      // Ensure range is still attached to the document
      if (editor.contains(lastEditorSelection.range.commonAncestorContainer)) {
        return lastEditorSelection.range;
      }
    } catch (_) {
      /* fall through */
    }
  }
  if (formatPaletteRange && !formatPaletteRange.collapsed) {
    try {
      if (editor.contains(formatPaletteRange.commonAncestorContainer)) {
        return formatPaletteRange;
      }
    } catch (_) {
      /* ignore */
    }
  }
  return live;
}

function wrapSelectionWithSpan(styles, options = {}) {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) return false;
  const range = selection.getRangeAt(0);
  const editor = getActiveRichEditor() || $("sceneContent");
  if (!editor || !editor.contains(range.commonAncestorContainer)) return false;

  const decorate = (span) => {
    Object.assign(span.style, styles);
    if (options.className) {
      String(options.className)
        .split(/\s+/)
        .filter(Boolean)
        .forEach((c) => span.classList.add(c));
    }
  };

  if (range.collapsed) {
    // Apply style for upcoming typing via a styled span caret.
    const span = document.createElement("span");
    decorate(span);
    span.appendChild(document.createTextNode("\u200b"));
    range.insertNode(span);
    const next = document.createRange();
    next.setStart(span.firstChild, 1);
    next.collapse(true);
    selection.removeAllRanges();
    selection.addRange(next);
    return true;
  }

  const fragment = range.extractContents();
  const span = document.createElement("span");
  decorate(span);
  span.appendChild(fragment);
  range.insertNode(span);
  selection.removeAllRanges();
  const next = document.createRange();
  next.selectNodeContents(span);
  selection.addRange(next);
  return true;
}

function applyEditorCommand(command, value = null) {
  try {
    document.execCommand("styleWithCSS", false, "true");
  } catch (_) {
    /* older engines */
  }
  document.execCommand(command, false, value);
  updateEditorPlaceholder();
  updateFormatButtonState();
}

function applyFontFamily(font) {
  if (!font) return;
  // fontName is still the most reliable cross-browser path.
  document.execCommand("styleWithCSS", false, "true");
  document.execCommand("fontName", false, font);
  updateEditorPlaceholder();
}

function applyFontSize(size) {
  if (!size) return;
  wrapSelectionWithSpan({ fontSize: size });
  updateEditorPlaceholder();
}

/** 장평: 글자 가로 비율(%). 100=기본. scaleX + font-stretch 로 적용. */
function normalizeJangpyeongPercent(value) {
  const n = Math.round(Number(String(value).replace(/%/g, "").trim()));
  if (!Number.isFinite(n)) return 100;
  return Math.min(200, Math.max(50, n));
}

function applyJangpyeong(percent) {
  const p = normalizeJangpyeongPercent(percent);
  const scale = p / 100;
  if (p === 100) {
    wrapSelectionWithSpan({
      fontStretch: "100%",
      transform: "none",
      display: "inline",
      transformOrigin: "left center",
    });
  } else {
    // scaleX 는 시각적 장평; font-stretch 는 가변 폰트 지원 시 보조
    wrapSelectionWithSpan({
      display: "inline-block",
      transform: `scaleX(${scale})`,
      transformOrigin: "left center",
      fontStretch: `${p}%`,
    });
  }
  updateEditorPlaceholder();
  try {
    const ed = getActiveRichEditor() || $("sceneContent");
    ed?.dispatchEvent(new Event("input", { bubbles: true }));
  } catch (_) {
    /* ignore */
  }
}

function applyJangpyeongToEntireDocument(percent, editorEl = null) {
  const editor = editorEl || getActiveRichEditor() || $("sceneContent");
  if (!editor) return;
  const p = normalizeJangpyeongPercent(percent);
  withEditorSelectAll(editor, () => applyJangpyeong(p));
}

function jangpyeongPercentFromStyle(styleValue) {
  const raw = String(styleValue || "").trim();
  if (!raw || raw === "none") return 100;
  const m = raw.match(/scaleX\(\s*([0-9.]+)\s*\)/i);
  if (m) {
    const s = Number(m[1]);
    if (Number.isFinite(s) && s > 0) return normalizeJangpyeongPercent(s * 100);
  }
  const pct = raw.match(/([0-9.]+)\s*%/);
  if (pct) return normalizeJangpyeongPercent(pct[1]);
  return 100;
}

/** Select all content inside a contenteditable, apply, then restore caret best-effort. */
function withEditorSelectAll(editor, fn) {
  if (!editor) return;
  focusEditor(editor);
  const selection = window.getSelection();
  const prev = selection?.rangeCount ? selection.getRangeAt(0).cloneRange() : null;
  try {
    const range = document.createRange();
    range.selectNodeContents(editor);
    selection?.removeAllRanges();
    selection?.addRange(range);
    fn();
  } finally {
    try {
      if (prev && selection) {
        selection.removeAllRanges();
        selection.addRange(prev);
      }
    } catch (_) {
      /* ignore restore failures */
    }
  }
  try {
    editor.dispatchEvent(new Event("input", { bubbles: true }));
  } catch (_) {
    /* ignore */
  }
  updateEditorPlaceholder(editor);
  updateFormatButtonState();
}

function applyFontFamilyToEntireDocument(font, editorEl = null) {
  const editor = editorEl || getActiveRichEditor() || $("sceneContent");
  if (!editor || !font) return;
  editor.style.fontFamily = font;
  withEditorSelectAll(editor, () => applyFontFamily(font));
}

function applyFontSizeToEntireDocument(size, editorEl = null) {
  const editor = editorEl || getActiveRichEditor() || $("sceneContent");
  if (!editor || !size) return;
  editor.style.fontSize = size;
  withEditorSelectAll(editor, () => applyFontSize(size));
}

function applyLineHeightToEntireDocument(value, editorEl = null) {
  const editor = editorEl || getActiveRichEditor() || $("sceneContent");
  if (!editor || !value) return;
  setStoredLineHeight(value);
  applyEditorWideLineHeight(value, [editor]);
  // Also stamp block children so pasted/exported HTML keeps spacing.
  editor.querySelectorAll("p, div, li, h1, h2, h3, h4, h5, h6, blockquote, pre").forEach((el) => {
    if (el.closest(".fn-footer")) return;
    el.style.lineHeight = value;
  });
  try {
    editor.dispatchEvent(new Event("input", { bubbles: true }));
  } catch (_) {
    /* ignore */
  }
  updateEditorPlaceholder(editor);
}

let formatApplyAllKind = null; // "font" | "size" | "lineHeight" | "jangpyeong"
let formatApplyAllValue = "";
let formatApplyAllEditor = null;

function hideFormatApplyAllMenu() {
  $("formatApplyAllMenu")?.classList.add("hidden");
  formatApplyAllKind = null;
  formatApplyAllValue = "";
  formatApplyAllEditor = null;
}

function formatApplyAllKindLabel(kind) {
  if (kind === "font") return i18n.t('app.글꼴');
  if (kind === "size") return i18n.t('app.크기');
  if (kind === "lineHeight") return i18n.t('app.줄간격');
  if (kind === "jangpyeong") return i18n.t('app.장평');
  return i18n.t('app.서식');
}

function showFormatApplyAllMenu(kind, value, anchorEl, editor) {
  const menu = $("formatApplyAllMenu");
  const label = $("formatApplyAllLabel");
  const btn = $("formatApplyAllButton");
  if (!menu || !btn || !value) return;
  hideGoalBarColorMenu?.();
  formatApplyAllKind = kind;
  formatApplyAllValue = value;
  formatApplyAllEditor = editor || getActiveRichEditor() || $("sceneContent");
  const kindLabel = formatApplyAllKindLabel(kind);
  const shortVal = kind === "font"
    ? (value.split(",")[0] || value).replace(/['"]/g, "").trim()
    : kind === "jangpyeong"
      ? `${normalizeJangpyeongPercent(value)}%`
      : value;
  if (label) label.textContent = `${kindLabel}: ${shortVal}`;
  btn.textContent = `${i18n.t('app.전체_문서에_kindLabel_적용', {kindLabel: kindLabel})}`;
  menu.classList.remove("hidden");
  const rect = anchorEl.getBoundingClientRect();
  const pad = 8;
  const mw = menu.offsetWidth || 180;
  const mh = menu.offsetHeight || 80;
  let left = rect.left;
  let top = rect.bottom + 4;
  if (left + mw > window.innerWidth - pad) left = Math.max(pad, window.innerWidth - mw - pad);
  if (top + mh > window.innerHeight - pad) top = Math.max(pad, rect.top - mh - 4);
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
}

function setupFormatApplyAllMenu() {
  const menu = $("formatApplyAllMenu");
  if (!menu || menu.dataset.bound === "1") return;
  menu.dataset.bound = "1";
  $("formatApplyAllButton")?.addEventListener("click", () => {
    const editor = formatApplyAllEditor || getActiveRichEditor() || $("sceneContent");
    const kind = formatApplyAllKind;
    const value = formatApplyAllValue;
    hideFormatApplyAllMenu();
    if (!editor || !value) return;
    if (kind === "font") applyFontFamilyToEntireDocument(value, editor);
    else if (kind === "size") applyFontSizeToEntireDocument(value, editor);
    else if (kind === "lineHeight") applyLineHeightToEntireDocument(value, editor);
    else if (kind === "jangpyeong") applyJangpyeongToEntireDocument(value, editor);
    toast(i18n.t('app.전체_문서에_적용했습니다'));
    if (editor.id === "sceneContent" && state.sceneId) markSceneDirty();
    else if (editor.id === "synopsisContent" || editor.id === "synopsisContentB") {
      markSettingsDocEditorDirty?.(editor);
    }
  });
  document.addEventListener("click", (event) => {
    if (event.target.closest("#formatApplyAllMenu")) return;
    hideFormatApplyAllMenu();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") hideFormatApplyAllMenu();
  });
  window.addEventListener("blur", hideFormatApplyAllMenu);
  window.addEventListener("resize", hideFormatApplyAllMenu);
}

/* —— Paragraph styles (본문 / 제목 / 인용 / 캡션) —— */
const PARAGRAPH_STYLES = {
  p: { tag: "p", label: i18n.t('app.본문') },
  h1: { tag: "h1", label: i18n.t('app.제목_1') },
  h2: { tag: "h2", label: i18n.t('app.제목_2') },
  h3: { tag: "h3", label: i18n.t('app.제목_3') },
  blockquote: { tag: "blockquote", label: i18n.t('app.인용') },
  caption: { tag: "p", label: i18n.t('app.캡션'), className: "sg-caption" },
};

function getBlockElementForParagraph(node, editor) {
  let el = node?.nodeType === 3 ? node.parentElement : node;
  const blockRe = /^(P|DIV|H1|H2|H3|H4|H5|H6|BLOCKQUOTE|LI|PRE)$/i;
  while (el && el !== editor) {
    if (el.nodeType === 1 && el.classList?.contains("ms-dan")) {
      el = el.parentElement;
      continue;
    }
    if (el.nodeType === 1 && blockRe.test(el.tagName) && el.parentElement) {
      // Prefer block that is a direct child of editor (or of a 단 wrapper) when possible.
      if (
        el.parentElement === editor
        || el.parentElement.classList?.contains("ms-dan")
        || blockRe.test(el.parentElement.tagName) === false
      ) {
        return el;
      }
    }
    el = el.parentElement;
  }
  return null;
}

function findDanWrapper(node, editor) {
  let el = node?.nodeType === 3 ? node.parentElement : node;
  while (el && el !== editor) {
    if (el.nodeType === 1 && el.classList?.contains("ms-dan")) return el;
    el = el.parentElement;
  }
  return null;
}

function isSelectionInDanColumns(editorEl = null) {
  const editor = editorEl || getActiveRichEditor() || $("sceneContent");
  const selection = window.getSelection();
  if (!editor || !selection?.rangeCount) return false;
  const node = selection.getRangeAt(0).commonAncestorContainer;
  if (!editor.contains(node)) return false;
  return Boolean(findDanWrapper(node, editor));
}

function unwrapDanColumns(wrapper) {
  const parent = wrapper?.parentNode;
  if (!parent) return;
  while (wrapper.firstChild) parent.insertBefore(wrapper.firstChild, wrapper);
  parent.removeChild(wrapper);
}

/** Toggle 2-column (단) layout around the current block / selection. */
function applyDanColumns(editorEl = null) {
  const editor = editorEl || getActiveRichEditor() || $("sceneContent");
  if (!editor) return;
  focusEditor(editor);
  const selection = window.getSelection();
  if (!selection?.rangeCount) return;
  const range = selection.getRangeAt(0);
  if (!editor.contains(range.commonAncestorContainer)) return;

  const existing = findDanWrapper(range.commonAncestorContainer, editor);
  if (existing) {
    unwrapDanColumns(existing);
  } else {
    const startBlock = getBlockElementForParagraph(range.startContainer, editor);
    const endBlock = getBlockElementForParagraph(range.endContainer, editor) || startBlock;
    if (!startBlock || !editor.contains(startBlock)) return;
    const nodes = [];
    let cur = startBlock;
    while (cur && editor.contains(cur)) {
      if (cur.classList?.contains("ms-dan")) break;
      nodes.push(cur);
      if (cur === endBlock) break;
      cur = cur.nextElementSibling;
    }
    if (!nodes.length || !nodes[0].parentNode) return;
    const wrap = document.createElement("div");
    wrap.className = "ms-dan";
    nodes[0].parentNode.insertBefore(wrap, nodes[0]);
    nodes.forEach((n) => wrap.appendChild(n));
    try {
      const next = document.createRange();
      next.selectNodeContents(wrap);
      next.collapse(true);
      selection.removeAllRanges();
      selection.addRange(next);
    } catch (_) { /* ignore */ }
  }

  updateEditorPlaceholder(editor);
  updateFormatButtonState();
  try {
    editor.dispatchEvent(new Event("input", { bubbles: true }));
  } catch (_) { /* ignore */ }
  if (editor.id === "sceneContent" && state.sceneId) markSceneDirty?.();
  else if (editor.id === "synopsisContent" || editor.id === "synopsisContentB") markSettingsDocEditorDirty?.(editor);
}

function detectParagraphStyle(editor) {
  if (!editor) return "p";
  const selection = window.getSelection();
  if (!selection || !selection.rangeCount) return "p";
  const range = selection.getRangeAt(0);
  if (!editor.contains(range.commonAncestorContainer)) return "p";
  const block = getBlockElementForParagraph(range.commonAncestorContainer, editor);
  if (!block) return "p";
  if (block.classList?.contains("sg-caption")) return "caption";
  const tag = (block.tagName || "").toLowerCase();
  if (tag === "h1" || tag === "h2" || tag === "h3") return tag;
  if (tag === "blockquote") return "blockquote";
  return "p";
}

function applyParagraphStyle(styleKey, editorEl = null) {
  const editor = editorEl || getActiveRichEditor() || $("sceneContent");
  const style = PARAGRAPH_STYLES[styleKey] || PARAGRAPH_STYLES.p;
  if (!editor) return;
  focusEditor(editor);
  try {
    document.execCommand("styleWithCSS", false, "true");
  } catch (_) {
    /* ignore */
  }

  const selection = window.getSelection();
  let block = null;
  if (selection?.rangeCount) {
    const range = selection.getRangeAt(0);
    if (editor.contains(range.commonAncestorContainer)) {
      block = getBlockElementForParagraph(range.commonAncestorContainer, editor);
    }
  }

  // formatBlock expects tag name with angle brackets in most browsers.
  const formatTag = style.tag === "p" ? "p" : style.tag;
  try {
    document.execCommand("formatBlock", false, `<${formatTag}>`);
  } catch (_) {
    try {
      document.execCommand("formatBlock", false, formatTag);
    } catch (__) {
      /* ignore */
    }
  }

  // Re-find block after formatBlock and set/clear caption class.
  if (selection?.rangeCount) {
    block = getBlockElementForParagraph(selection.getRangeAt(0).commonAncestorContainer, editor);
  }
  if (block && editor.contains(block)) {
    block.classList.remove("sg-caption");
    if (style.className) {
      // Ensure we are on a paragraph-like node for caption.
      if (block.tagName !== "P" && block.tagName !== "DIV") {
        try {
          document.execCommand("formatBlock", false, "<p>");
        } catch (_) {
          /* ignore */
        }
        if (selection?.rangeCount) {
          block = getBlockElementForParagraph(selection.getRangeAt(0).commonAncestorContainer, editor);
        }
      }
      block?.classList?.add(style.className);
    }
  }

  updateEditorPlaceholder(editor);
  try {
    editor.dispatchEvent(new Event("input", { bubbles: true }));
  } catch (_) {
    /* ignore */
  }
}

function syncParagraphStyleSelect(toolbar, editor) {
  if (!toolbar || !editor) return;
  const select = toolbar.querySelector("#formatParagraphStyle, [data-role='format-paragraph']");
  if (!select) return;
  const key = detectParagraphStyle(editor);
  if ([...select.options].some((o) => o.value === key)) select.value = key;
  else select.value = "p";
}

/* —— Line height (줄간격) —— */
const LINE_HEIGHT_STORAGE_KEY = "supertory.editorLineHeight";
const DEFAULT_LINE_HEIGHT = "1.8";
const LINE_HEIGHT_BLOCK_RE = /^(P|DIV|LI|H[1-6]|BLOCKQUOTE|SECTION|ARTICLE|PRE)$/i;

function getStoredLineHeight() {
  try {
    const v = localStorage.getItem(LINE_HEIGHT_STORAGE_KEY);
    if (v && /^\d+(\.\d+)?$/.test(v)) return v;
  } catch (_) {
    /* ignore */
  }
  return DEFAULT_LINE_HEIGHT;
}

function setStoredLineHeight(value) {
  try {
    if (value) localStorage.setItem(LINE_HEIGHT_STORAGE_KEY, value);
  } catch (_) {
    /* ignore */
  }
}

function syncLineHeightSelects(value) {
  const v = value || DEFAULT_LINE_HEIGHT;
  document.querySelectorAll("#formatLineHeight, [data-role='format-line-height']").forEach((select) => {
    if (!select) return;
    // Keep select in sync even if custom value was stored.
    if (![...select.options].some((o) => o.value === v)) {
      const opt = document.createElement("option");
      opt.value = v;
      opt.textContent = v;
      select.appendChild(opt);
    }
    select.value = v;
  });
}

function applyEditorWideLineHeight(value, editors = null) {
  const lh = value || DEFAULT_LINE_HEIGHT;
  const list = editors || [
    $("sceneContent"),
    $("synopsisContent"),
    $("focusWriteEditor"),
    $("splitSceneBodyEditor"),
  ].filter(Boolean);
  list.forEach((el) => {
    if (el) el.style.lineHeight = lh;
  });
  syncLineHeightSelects(lh);
}

function collectLineHeightBlocks(editor, range) {
  const blocks = new Set();
  if (!editor || !range) return blocks;

  const addBlockForNode = (node) => {
    let el = node?.nodeType === 3 ? node.parentElement : node;
    while (el && el !== editor) {
      if (el.nodeType === 1 && LINE_HEIGHT_BLOCK_RE.test(el.tagName)) {
        // Prefer the outermost block that is a direct child of the editor,
        // otherwise the nearest block ancestor.
        let outer = el;
        let walk = el.parentElement;
        while (walk && walk !== editor) {
          if (walk.nodeType === 1 && LINE_HEIGHT_BLOCK_RE.test(walk.tagName)) outer = walk;
          walk = walk.parentElement;
        }
        blocks.add(outer);
        return;
      }
      el = el.parentElement;
    }
  };

  if (range.collapsed) {
    addBlockForNode(range.startContainer);
    return blocks;
  }

  try {
    const walker = document.createTreeWalker(editor, NodeFilter.SHOW_ELEMENT, {
      acceptNode(node) {
        if (!LINE_HEIGHT_BLOCK_RE.test(node.tagName)) return NodeFilter.FILTER_SKIP;
        try {
          if (range.intersectsNode(node)) return NodeFilter.FILTER_ACCEPT;
        } catch (_) {
          /* ignore */
        }
        return NodeFilter.FILTER_SKIP;
      },
    });
    let node = walker.nextNode();
    while (node) {
      // Prefer outermost block under the editor to avoid nested duplicates.
      addBlockForNode(node);
      node = walker.nextNode();
    }
  } catch (_) {
    addBlockForNode(range.commonAncestorContainer);
  }

  if (!blocks.size) {
    addBlockForNode(range.startContainer);
    addBlockForNode(range.endContainer);
  }
  return blocks;
}

function applyLineHeight(value, editorEl = null) {
  const editor = editorEl || getActiveRichEditor() || $("sceneContent");
  if (!editor || !value) return;

  const selection = window.getSelection();
  const range = selection && selection.rangeCount
    ? selection.getRangeAt(0)
    : null;
  const inEditor = range && editor.contains(range.commonAncestorContainer);

  // Non-collapsed selection → paragraph/block line-height (saved with manuscript).
  if (inEditor && range && !range.collapsed) {
    const blocks = collectLineHeightBlocks(editor, range);
    if (blocks.size) {
      blocks.forEach((block) => {
        block.style.lineHeight = value;
      });
    } else {
      // Bare text + <br> manuscript: wrap selection.
      wrapSelectionWithSpan({ lineHeight: value });
    }
    updateEditorPlaceholder(editor);
    try {
      editor.dispatchEvent(new Event("input", { bubbles: true }));
    } catch (_) {
      /* ignore */
    }
    return;
  }

  // Caret only / no selection → editor-wide view preference (remembered).
  setStoredLineHeight(value);
  applyEditorWideLineHeight(value);
  updateEditorPlaceholder(editor);
}

/* Text / highlight colors: left-click apply, right-click palette */
const FORMAT_PRESET_COLORS = [
  { key: "red", hex: "#e74c3c", label: i18n.t('app.빨강') },
  { key: "blue", hex: "#3498db", label: i18n.t('app.파랑') },
  { key: "yellow", hex: "#f1c40f", label: i18n.t('app.노랑') },
  { key: "green", hex: "#27ae60", label: i18n.t('app.초록') },
  { key: "gray", hex: "#7f8c8d", label: i18n.t('app.회색') },
];
/** 형광펜 전용 — 네온/형광 느낌 프리셋 */
const FORMAT_HIGHLIGHT_PRESET_COLORS = [
  { key: "neon-pink", hex: "#FF9AF5", label: i18n.t('app.네온_핑크') },
  { key: "neon-yellow", hex: "#F5FF3D", label: i18n.t('app.네온_노랑') },
  { key: "neon-green", hex: "#A8FF7A", label: i18n.t('app.네온_초록') },
  { key: "neon-cyan", hex: "#3DFFF5", label: i18n.t('app.네온_시안') },
  { key: "neon-orange", hex: "#FFC45C", label: i18n.t('app.네온_주황') },
];
const FORMAT_COLOR_DEFAULTS = {
  text: "#e74c3c",
  highlight: "#F5FF3D",
  shade: "#efe4d4",
};
const formatColorState = {
  text: FORMAT_COLOR_DEFAULTS.text,
  highlight: FORMAT_COLOR_DEFAULTS.highlight,
  shade: FORMAT_COLOR_DEFAULTS.shade,
};
let formatPaletteKind = null; // "text" | "highlight" | "shade"
let formatPaletteRange = null;
let formatPaletteEditor = null;
/** "editor" | "tory-chat" — palette applies to manuscript or 토리 대화 형광펜 */
let formatPaletteTarget = "editor";

function applyTextColor(color) {
  if (!color) return;
  applyEditorCommand("foreColor", color);
}

/** 형광/음영 배경에 맞는 글자색 (밝은 배경 → 어두운 글자) */
function contrastInkForHighlightBg(hex) {
  return isColorDark(hex) ? "#fffdf8" : "#1a1510";
}

function getPageInkHexForEditor() {
  try {
    const fromBody = cssColorToHex(
      getComputedStyle(document.body).getPropertyValue("--page-ink").trim()
      || document.body.style.getPropertyValue("--page-ink"),
    );
    if (fromBody) return fromBody;
  } catch (_) {
    /* ignore */
  }
  try {
    const fromRoot = cssColorToHex(
      getComputedStyle(document.documentElement).getPropertyValue("--page-ink").trim(),
    );
    if (fromRoot) return fromRoot;
  } catch (_) {
    /* ignore */
  }
  try {
    const editor = getActiveRichEditor() || $("sceneContent");
    if (editor) {
      const computed = cssColorToHex(getComputedStyle(editor).color);
      // editor may still have leftover contrast ink — prefer theme default when page theme known
      const pageTheme = document.body?.dataset?.pageTheme || "";
      if (pageTheme === "chalkboard" || pageTheme === "night") {
        return themeDefaultInk(pageTheme) || "#ffffff";
      }
      if (computed) return computed;
    }
  } catch (_) {
    /* ignore */
  }
  return themeDefaultInk() || "#24211d";
}

function sameCssHex(a, b) {
  const x = cssColorToHex(a);
  const y = cssColorToHex(b);
  if (x && y) return x.toUpperCase() === y.toUpperCase();
  return normalizeCssColor(a) === normalizeCssColor(b);
}

function isHighlightContrastInkHex(hex) {
  if (!hex) return false;
  return sameCssHex(hex, "#1a1510") || sameCssHex(hex, "#fffdf8");
}

function selectionForegroundHex() {
  try {
    const selection = window.getSelection();
    if (selection && selection.rangeCount) {
      let node = selection.anchorNode;
      if (node && node.nodeType === 3) node = node.parentElement;
      if (node && node.nodeType === 1) {
        const computed = cssColorToHex(getComputedStyle(node).color);
        if (computed) return computed;
      }
    }
  } catch (_) {
    /* ignore */
  }
  try {
    return cssColorToHex(document.queryCommandValue("foreColor")) || "";
  } catch (_) {
    return "";
  }
}

function tagHighlightContrastInkElement(el, prevHex) {
  if (!el || el.nodeType !== 1) return;
  if (el.classList?.contains("sg-text-shade-box")) return;
  el.dataset.sgHlInk = "1";
  if (prevHex && !el.dataset.sgHlInkPrev) {
    el.dataset.sgHlInkPrev = prevHex;
  }
}

function tagHighlightContrastInkInSelection(prevHex, inkHex) {
  try {
    const editor = getActiveRichEditor() || $("sceneContent");
    const selection = window.getSelection();
    if (!editor || !selection || !selection.rangeCount) return;
    const range = selection.getRangeAt(0);
    if (range.collapsed || !editor.contains(range.commonAncestorContainer)) return;
    const root = range.commonAncestorContainer.nodeType === 1
      ? range.commonAncestorContainer
      : range.commonAncestorContainer.parentElement;
    root?.querySelectorAll?.("[style*='color'], font[color]").forEach((el) => {
      if (range.intersectsNode && !range.intersectsNode(el)) return;
      const raw = el.style?.color || el.getAttribute?.("color") || "";
      const hex = cssColorToHex(raw);
      if (hex && sameCssHex(hex, inkHex)) {
        tagHighlightContrastInkElement(el, prevHex);
      }
    });
    let node = selection.anchorNode;
    if (node && node.nodeType === 3) node = node.parentElement;
    while (node && node !== editor) {
      if (node.nodeType === 1) {
        const raw = node.style?.color || node.getAttribute?.("color") || "";
        const hex = cssColorToHex(raw);
        if (hex && sameCssHex(hex, inkHex)) {
          tagHighlightContrastInkElement(node, prevHex);
        }
      }
      node = node.parentElement;
    }
  } catch (_) {
    /* ignore */
  }
}

/** 형광 끄면 대비용으로 바꿨던 글자색을 원래(또는 페이지 기본)로 복원 */
function restoreHighlightContrastInkInSelection() {
  try {
    const editor = getActiveRichEditor() || $("sceneContent");
    const selection = window.getSelection();
    if (!editor || !selection || !selection.rangeCount) return;
    const range = selection.getRangeAt(0);
    if (!editor.contains(range.commonAncestorContainer)) return;
    const pageInk = getPageInkHexForEditor();
    const restoreEl = (el) => {
      if (!el?.dataset?.sgHlInk) return;
      const prev = el.dataset.sgHlInkPrev || "";
      if (prev) {
        el.style.color = prev;
        if (el.hasAttribute?.("color")) el.setAttribute("color", prev);
      } else {
        el.style.color = "";
        el.style.removeProperty?.("color");
        if (el.hasAttribute?.("color")) el.removeAttribute("color");
      }
      delete el.dataset.sgHlInk;
      delete el.dataset.sgHlInkPrev;
    };
    const root = range.commonAncestorContainer.nodeType === 1
      ? range.commonAncestorContainer
      : range.commonAncestorContainer.parentElement;
    root?.querySelectorAll?.("[data-sg-hl-ink]").forEach((el) => {
      if (range.intersectsNode && !range.intersectsNode(el)) return;
      restoreEl(el);
    });
    let anc = range.commonAncestorContainer;
    if (anc.nodeType === 3) anc = anc.parentElement;
    while (anc && anc !== editor) {
      if (anc.dataset?.sgHlInk) restoreEl(anc);
      anc = anc.parentElement;
    }
    // 태그 없는 경우(이전 칠하기): 대비용 잉크(#1a1510/#fffdf8)면 페이지 기본으로
    const fg = selectionForegroundHex();
    if (fg && isHighlightContrastInkHex(fg) && !sameCssHex(fg, pageInk)) {
      document.execCommand("styleWithCSS", false, "true");
      document.execCommand("foreColor", false, pageInk);
      root?.querySelectorAll?.("[style*='color'], font[color]").forEach((el) => {
        if (el.classList?.contains("sg-text-shade-box")) return;
        if (range.intersectsNode && !range.intersectsNode(el)) return;
        const raw = el.style?.color || el.getAttribute?.("color") || "";
        const hex = cssColorToHex(raw);
        if (hex && isHighlightContrastInkHex(hex)) {
          el.style.color = pageInk;
          if (el.hasAttribute?.("color")) el.setAttribute("color", pageInk);
          delete el.dataset.sgHlInk;
          delete el.dataset.sgHlInkPrev;
        }
      });
    }
  } catch (_) {
    /* ignore */
  }
}

/** 형광 배경과 글자색 대비가 부족하면(밝은 글자+밝은 형광 등) 글자색을 맞춤 */
function ensureHighlightTextContrast(highlightColor) {
  const bg = cssColorToHex(highlightColor) || String(highlightColor || "");
  if (!bg) return;
  const ink = contrastInkForHighlightBg(bg);
  const fg = selectionForegroundHex();
  const pageInk = getPageInkHexForEditor();
  const needsFlip = !fg || (isColorDark(fg) === isColorDark(bg));
  if (needsFlip) {
    const prev = (fg && !isHighlightContrastInkHex(fg) ? fg : "") || pageInk || "";
    document.execCommand("styleWithCSS", false, "true");
    document.execCommand("foreColor", false, ink);
    tagHighlightContrastInkInSelection(prev, ink);
  }
  // 선택 안 밝은/어두운 인라인 색이 형광에 묻히는 경우도 정리
  try {
    const editor = getActiveRichEditor() || $("sceneContent");
    const selection = window.getSelection();
    if (!editor || !selection || !selection.rangeCount) return;
    const range = selection.getRangeAt(0);
    if (range.collapsed || !editor.contains(range.commonAncestorContainer)) return;
    const root = range.commonAncestorContainer.nodeType === 1
      ? range.commonAncestorContainer
      : range.commonAncestorContainer.parentElement;
    root?.querySelectorAll?.("[style*='color'], font[color]").forEach((el) => {
      if (el.classList?.contains("sg-text-shade-box")) return;
      if (range.intersectsNode && !range.intersectsNode(el)) return;
      const raw = el.style?.color || el.getAttribute?.("color") || "";
      const hex = cssColorToHex(raw) || cssColorToHex(getComputedStyle(el).color);
      if (!hex) return;
      if (isColorDark(hex) === isColorDark(bg)) {
        if (!el.dataset.sgHlInkPrev) {
          el.dataset.sgHlInkPrev = (hex && !isHighlightContrastInkHex(hex) ? hex : "") || pageInk || "";
        }
        el.style.color = ink;
        if (el.hasAttribute?.("color")) el.setAttribute("color", ink);
        tagHighlightContrastInkElement(el, el.dataset.sgHlInkPrev);
      }
    });
  } catch (_) {
    /* ignore */
  }
}

function applyHighlight(color) {
  if (!color) return;
  document.execCommand("styleWithCSS", false, "true");
  // Prefer hiliteColor; fall back to backColor.
  if (!document.execCommand("hiliteColor", false, color)) {
    document.execCommand("backColor", false, color);
  }
  ensureHighlightTextContrast(color);
  updateEditorPlaceholder();
  updateFormatButtonState();
}

/** 텍스트 음영상자: 선택 구간에 패딩·모서리·그림자가 있는 배경 상자 (+ 대비 글자색) */
function contrastInkForShadeBg(hex) {
  // 어두운 상자 → 밝은 글자, 밝은 상자 → 어두운 글자
  return contrastInkForHighlightBg(hex);
}

function applyShadeBox(color) {
  if (!color) return;
  const ink = contrastInkForShadeBg(color);
  wrapSelectionWithSpan(
    {
      backgroundColor: color,
      color: ink,
      padding: "0.08em 0.32em",
      borderRadius: "4px",
      boxShadow: "0 1px 3px rgba(0,0,0,0.14), inset 0 0 0 1px rgba(0,0,0,0.06)",
      boxDecorationBreak: "clone",
      WebkitBoxDecorationBreak: "clone",
    },
    { className: "sg-text-shade-box" }
  );
  updateEditorPlaceholder();
  updateFormatButtonState();
}

function selectionHasShadeBox() {
  try {
    const editor = getActiveRichEditor() || $("sceneContent");
    const selection = window.getSelection();
    if (!editor || !selection || !selection.rangeCount) return false;
    const range = selection.getRangeAt(0);
    if (!editor.contains(range.commonAncestorContainer)) return false;
    let node = range.commonAncestorContainer;
    if (node.nodeType === 3) node = node.parentElement;
    while (node && node !== editor) {
      if (node.nodeType === 1 && (
        node.classList?.contains("sg-text-shade-box")
        || (node.style?.boxShadow && node.style?.backgroundColor)
      )) {
        return true;
      }
      node = node.parentElement;
    }
    if (!range.collapsed) {
      const root = range.commonAncestorContainer.nodeType === 1
        ? range.commonAncestorContainer
        : range.commonAncestorContainer.parentElement;
      const hits = root?.querySelectorAll?.(".sg-text-shade-box, [style*='box-shadow']") || [];
      for (const el of hits) {
        try {
          if (!range.intersectsNode || range.intersectsNode(el)) return true;
        } catch (_) {
          /* ignore */
        }
      }
    }
  } catch (_) {
    /* ignore */
  }
  return false;
}

function clearShadeBox() {
  try {
    const editor = getActiveRichEditor() || $("sceneContent");
    const selection = window.getSelection();
    if (editor && selection && selection.rangeCount) {
      const range = selection.getRangeAt(0);
      if (editor.contains(range.commonAncestorContainer)) {
        const targets = new Set();
        // 선택 구간의 조상 음영상자
        let node = range.commonAncestorContainer;
        if (node.nodeType === 3) node = node.parentElement;
        while (node && node !== editor) {
          if (node.nodeType === 1 && (
            node.classList?.contains("sg-text-shade-box")
            || (node.style?.boxShadow && node.style?.backgroundColor)
          )) {
            targets.add(node);
            break;
          }
          node = node.parentElement;
        }
        // 선택과 겹치는 하위 음영상자
        if (!range.collapsed) {
          const root = range.commonAncestorContainer.nodeType === 1
            ? range.commonAncestorContainer
            : range.commonAncestorContainer.parentElement;
          root?.querySelectorAll?.(".sg-text-shade-box, [style*='box-shadow']").forEach((el) => {
            try {
              if (!range.intersectsNode || range.intersectsNode(el)) targets.add(el);
            } catch (_) {
              /* ignore */
            }
          });
        }
        targets.forEach((el) => {
          try {
            el.classList.remove("sg-text-shade-box");
            el.style.backgroundColor = "";
            el.style.background = "";
            el.style.color = "";
            el.style.padding = "";
            el.style.borderRadius = "";
            el.style.boxShadow = "";
            el.style.boxDecorationBreak = "";
            el.style.WebkitBoxDecorationBreak = "";
            if (el.getAttribute("style") === "") el.removeAttribute("style");
            // 스타일·클래스가 없으면 span을 풀어 텍스트만 남김
            if (
              el.tagName === "SPAN"
              && !el.classList.length
              && !el.getAttribute("style")
              && el.attributes.length === 0
            ) {
              const parent = el.parentNode;
              if (!parent) return;
              while (el.firstChild) parent.insertBefore(el.firstChild, el);
              parent.removeChild(el);
              parent.normalize?.();
            }
          } catch (_) {
            /* ignore */
          }
        });
      }
    }
  } catch (_) {
    /* ignore */
  }
  updateEditorPlaceholder();
  updateFormatButtonState();
}

function clearHighlight() {
  document.execCommand("styleWithCSS", false, "true");
  if (!document.execCommand("hiliteColor", false, "transparent")) {
    document.execCommand("backColor", false, "transparent");
  }
  // Also strip highlight background from selected spans (more reliable than transparent alone).
  // 음영상자(.sg-text-shade-box)는 건드리지 않음.
  try {
    const editor = getActiveRichEditor() || $("sceneContent");
    const selection = window.getSelection();
    if (editor && selection && selection.rangeCount) {
      const range = selection.getRangeAt(0);
      if (!range.collapsed && editor.contains(range.commonAncestorContainer)) {
        const root = range.commonAncestorContainer.nodeType === 1
          ? range.commonAncestorContainer
          : range.commonAncestorContainer.parentElement;
        root?.querySelectorAll?.("[style*='background'], mark").forEach((el) => {
          if (el.classList?.contains("sg-text-shade-box")) return;
          if (range.intersectsNode && !range.intersectsNode(el)) return;
          el.style.backgroundColor = "";
          el.style.background = "";
          if (el.tagName === "MARK") {
            el.style.backgroundColor = "transparent";
          }
        });
        // 조상 span에만 형광이 있는 경우(선택이 span 안쪽 텍스트만인 경우)
        let anc = range.commonAncestorContainer;
        if (anc.nodeType === 3) anc = anc.parentElement;
        while (anc && anc !== editor) {
          if (anc.nodeType === 1
            && !anc.classList?.contains("sg-text-shade-box")
            && (anc.style?.backgroundColor || anc.style?.background)) {
            anc.style.backgroundColor = "";
            anc.style.background = "";
            break;
          }
          anc = anc.parentElement;
        }
      }
    }
  } catch (_) {
    /* ignore */
  }
  // 대비용으로 바꿨던 글자색 복원 (칠판 흰 글씨 등)
  restoreHighlightContrastInkInSelection();
  updateEditorPlaceholder();
  updateFormatButtonState();
}

function normalizeCssColor(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  try {
    const probe = document.createElement("span");
    probe.style.color = raw;
    probe.style.display = "none";
    document.body.appendChild(probe);
    const computed = getComputedStyle(probe).color;
    probe.remove();
    return String(computed || "").replace(/\s+/g, "").toLowerCase();
  } catch (_) {
    return raw.replace(/\s+/g, "").toLowerCase();
  }
}

function isIgnorableHighlightBg(bg, pageBgNorm = "") {
  const n = String(bg || "").replace(/\s+/g, "").toLowerCase();
  if (!n) return true;
  if (n === "transparent" || n === "rgba(0,0,0,0)") return true;
  if (n === "initial" || n === "inherit" || n === "unset") return true;
  if (n === "rgb(255,255,255)" || n === "#ffffff" || n === "white") return true;
  if (n === "rgb(255,253,248)") return true; // ivory page
  if (pageBgNorm && normalizeCssColor(bg) === pageBgNorm) return true;
  return false;
}

function selectionHasHighlight() {
  try {
    const editor = getActiveRichEditor() || $("sceneContent");
    const pageBgNorm = editor
      ? normalizeCssColor(getComputedStyle(editor).backgroundColor)
      : "";
    const values = [
      document.queryCommandValue("hiliteColor"),
      document.queryCommandValue("backColor"),
    ];
    for (const raw of values) {
      const v = String(raw || "").trim().toLowerCase();
      if (!v) continue;
      if (isIgnorableHighlightBg(v, pageBgNorm)) continue;
      return true;
    }
    // Fallback: selection 안/조상의 형광 배경 (음영상자는 제외).
    const selection = window.getSelection();
    if (selection && selection.rangeCount) {
      const range = selection.getRangeAt(0);
      if (editor && !editor.contains(range.commonAncestorContainer)) return false;
      let node = selection.anchorNode;
      if (node && node.nodeType === 3) node = node.parentElement;
      while (node && node !== editor && node !== document.body) {
        if (node.nodeType === 1) {
          if (node.classList?.contains("sg-text-shade-box")) {
            node = node.parentElement;
            continue;
          }
          // 인라인 배경만 형광으로 취급 (조상 computed는 테마/박스 오탐 방지)
          const inlineBg = node.style?.backgroundColor || node.style?.background || "";
          if (inlineBg && !isIgnorableHighlightBg(inlineBg, pageBgNorm)) return true;
          if (node.tagName === "MARK") return true;
        }
        node = node.parentElement;
      }
      if (!range.collapsed) {
        const root = range.commonAncestorContainer.nodeType === 1
          ? range.commonAncestorContainer
          : range.commonAncestorContainer.parentElement;
        const hits = root?.querySelectorAll?.("[style*='background']") || [];
        for (const el of hits) {
          if (el.classList?.contains("sg-text-shade-box")) continue;
          if (range.intersectsNode && !range.intersectsNode(el)) continue;
          const inlineBg = el.style?.backgroundColor || el.style?.background || "";
          if (inlineBg && !isIgnorableHighlightBg(inlineBg, pageBgNorm)) return true;
        }
      }
    }
  } catch (_) {
    /* ignore */
  }
  return false;
}

function selectionHasTextColor() {
  try {
    const pageInk = (typeof getPageInkHexForEditor === "function" && getPageInkHexForEditor())
      || (typeof themeDefaultInk === "function" ? themeDefaultInk() : "")
      || "#24211d";
    const raw = document.queryCommandValue("foreColor");
    const fromCmd = cssColorToHex(raw) || "";
    const fromSel = selectionForegroundHex();
    const fg = fromSel || fromCmd;
    if (!fg) return false;
    if (sameCssHex(fg, pageInk)) return false;
    // Black-ish defaults often reported as rgb(0,0,0) — treat close to dark page ink as none.
    if (
      (sameCssHex(fg, "#000000") || sameCssHex(fg, "#24211d") || sameCssHex(fg, "#1f1f1f"))
      && (sameCssHex(pageInk, "#000000") || sameCssHex(pageInk, "#24211d") || sameCssHex(pageInk, "#1f1f1f") || isColorDark(pageInk))
    ) {
      return false;
    }
    // Explicit inline color in selection (not just inherited page ink)
    const editor = getActiveRichEditor() || $("sceneContent");
    const selection = window.getSelection();
    if (editor && selection?.rangeCount) {
      const range = selection.getRangeAt(0);
      if (!range.collapsed && editor.contains(range.commonAncestorContainer)) {
        let node = selection.anchorNode;
        if (node && node.nodeType === 3) node = node.parentElement;
        while (node && node !== editor) {
          if (node.nodeType === 1) {
            const inline = node.style?.color || node.getAttribute?.("color") || "";
            if (inline && cssColorToHex(inline) && !sameCssHex(inline, pageInk)) return true;
          }
          node = node.parentElement;
        }
      }
    }
    return !sameCssHex(fg, pageInk);
  } catch (_) {
    return false;
  }
}

function clearTextColor() {
  // 선택 구간의 글자색을 지우고 페이지 기본 잉크(칠판=흰색 등)로 되돌림.
  const pageInk = (typeof getPageInkHexForEditor === "function" && getPageInkHexForEditor())
    || (typeof themeDefaultInk === "function" ? themeDefaultInk() : "")
    || "#24211d";
  const editor = getActiveRichEditor() || $("sceneContent");
  document.execCommand("styleWithCSS", false, "true");
  try {
    const selection = window.getSelection();
    if (editor && selection && selection.rangeCount) {
      const range = selection.getRangeAt(0);
      if (!range.collapsed && editor.contains(range.commonAncestorContainer)) {
        const stripColor = (el) => {
          if (!el || el.nodeType !== 1) return;
          if (el.classList?.contains("sg-text-shade-box")) return;
          try {
            el.style.removeProperty("color");
            el.style.color = "";
            if (el.hasAttribute("color")) el.removeAttribute("color");
            if (el.getAttribute("style") === "") el.removeAttribute("style");
            delete el.dataset?.sgHlInk;
            delete el.dataset?.sgHlInkPrev;
          } catch (_) {
            /* ignore */
          }
        };
        const root = range.commonAncestorContainer.nodeType === 1
          ? range.commonAncestorContainer
          : range.commonAncestorContainer.parentElement;
        root?.querySelectorAll?.("font[color], [style*='color'], [style*='Color']").forEach((el) => {
          try {
            if (range.intersectsNode && !range.intersectsNode(el)) return;
            stripColor(el);
          } catch (_) {
            /* ignore */
          }
        });
        let anc = range.commonAncestorContainer;
        if (anc.nodeType === 3) anc = anc.parentElement;
        while (anc && anc !== editor) {
          if (anc.style?.color || anc.getAttribute?.("color")) stripColor(anc);
          anc = anc.parentElement;
        }
      }
    }
  } catch (_) {
    /* ignore */
  }
  // 상속만으로 부족한 경우(브라우저/인라인 잔여) → 페이지 기본 잉크로 확정
  try {
    document.execCommand("foreColor", false, pageInk);
  } catch (_) {
    /* ignore */
  }
  updateEditorPlaceholder();
  updateFormatButtonState();
  try {
    editor?.dispatchEvent(new Event("input", { bubbles: true }));
  } catch (_) {
    /* ignore */
  }
}

function setFormatColorState(kind, color) {
  if (kind !== "text" && kind !== "highlight" && kind !== "shade") return;
  if (!color) return;
  formatColorState[kind] = color;
  document.querySelectorAll(`[data-color-bar="${kind}"]`).forEach((bar) => {
    bar.style.setProperty("--bar-color", color);
  });
  document.querySelectorAll(`[data-color-kind="${kind}"]`).forEach((btn) => {
    if (kind === "text") {
      const icon = btn.querySelector(".format-a-icon");
      if (icon) icon.style.borderBottomColor = color;
    }
    if (kind === "shade") {
      const box = btn.querySelector(".format-shade-box");
      if (box) box.style.backgroundColor = color;
      const letter = btn.querySelector(".format-shade-letter");
      if (letter) letter.style.color = contrastInkForShadeBg(color);
    }
  });
  if (kind === "highlight" && typeof syncToryChatHighlightBar === "function") {
    try { syncToryChatHighlightBar(); } catch (_) { /* defined later */ }
  }
}

/**
 * Apply color/highlight/shade to selection.
 * 글자색·형광펜·음영상자: 드래그 후 클릭 = 칠하기, 다시 클릭 = 지우기 (토글).
 * 팔레트에서 고른 색은 forceApply로 항상 적용.
 */
function applyFormatColorToSelection(kind, color, editorEl = null, options = {}) {
  const editor = editorEl || getActiveRichEditor() || lastEditorSelection.editor || $("sceneContent");
  if (!editor) return;
  focusEditor(editor);
  const usable = getUsableEditorRange(editor);
  if (usable) {
    try { restoreSelection(usable); } catch (_) { /* ignore */ }
  }
  const range = getUsableEditorRange(editor);
  if (!range || range.collapsed) {
    toast(i18n.t('app.문장을_드래그해_선택한_뒤_색_음영_버튼을'));
    return;
  }
  try { restoreSelection(range); } catch (_) { /* ignore */ }

  const forceApply = options.forceApply === true;
  const allowToggle = options.toggle === true
    || ((kind === "shade" || kind === "highlight" || kind === "text") && options.toggle !== false && !forceApply);
  const next = color || formatColorState[kind] || FORMAT_COLOR_DEFAULTS[kind];

  if (kind === "highlight") {
    if (allowToggle && !forceApply && selectionHasHighlight()) {
      clearHighlight();
      formatPaletteRange = currentEditorRange(editor) || formatPaletteRange;
      rememberLastEditorSelection(editor);
      try {
        editor.dispatchEvent(new Event("input", { bubbles: true }));
      } catch (_) {
        /* ignore */
      }
      return;
    }
    setFormatColorState("highlight", next);
    applyHighlight(next);
  } else if (kind === "shade") {
    if (allowToggle && !forceApply && selectionHasShadeBox()) {
      clearShadeBox();
      formatPaletteRange = currentEditorRange(editor) || formatPaletteRange;
      rememberLastEditorSelection(editor);
      try {
        editor.dispatchEvent(new Event("input", { bubbles: true }));
      } catch (_) {
        /* ignore */
      }
      return;
    }
    setFormatColorState("shade", next);
    applyShadeBox(next);
  } else {
    if (allowToggle && !forceApply && selectionHasTextColor()) {
      clearTextColor();
      formatPaletteRange = currentEditorRange(editor) || formatPaletteRange;
      rememberLastEditorSelection(editor);
      return;
    }
    setFormatColorState("text", next);
    applyTextColor(next);
  }
  formatPaletteRange = currentEditorRange(editor) || range;
  rememberLastEditorSelection(editor);
  // Ensure autosave / dirty tracking (execCommand may not fire input in all browsers)
  try {
    editor.dispatchEvent(new Event("input", { bubbles: true }));
  } catch (_) {
    /* ignore */
  }
}

function syncFormatPaletteSwatches(kind) {
  const palette = $("formatColorPalette");
  if (!palette) return;
  const presets = kind === "highlight" ? FORMAT_HIGHLIGHT_PRESET_COLORS : FORMAT_PRESET_COLORS;
  palette.classList.toggle("is-highlight-palette", kind === "highlight");
  const buttons = [...palette.querySelectorAll(".format-swatch")];
  presets.forEach((preset, index) => {
    const btn = buttons[index];
    if (!btn) return;
    btn.dataset.swatch = preset.hex;
    btn.title = preset.label;
    btn.setAttribute("aria-label", preset.label);
    btn.style.setProperty("--sw", preset.hex);
  });
}

function hideFormatColorPalette() {
  $("formatColorPalette")?.classList.add("hidden");
  formatPaletteKind = null;
  formatPaletteTarget = "editor";
}

function showFormatColorPalette(kind, anchorEl, editorEl = null, options = {}) {
  const palette = $("formatColorPalette");
  if (!palette || !anchorEl) return;
  formatPaletteKind = kind;
  formatPaletteTarget = options.target === "tory-chat" ? "tory-chat" : "editor";
  if (formatPaletteTarget === "tory-chat") {
    formatPaletteEditor = null;
    formatPaletteRange = null;
  } else {
    formatPaletteEditor = editorEl || getActiveRichEditor() || $("sceneContent");
    formatPaletteRange = currentEditorRange(formatPaletteEditor);
  }
  const label = $("formatColorPaletteLabel");
  if (label) {
    label.textContent = kind === "highlight"
      ? i18n.t('app.형광펜_색')
      : kind === "shade"
        ? i18n.t('app.음영상자_색')
        : i18n.t('app.글자색');
  }
  const clearBtn = $("formatPaletteClearButton");
  if (clearBtn) {
    clearBtn.textContent = kind === "highlight"
      ? i18n.t('app.형광_지우기')
      : kind === "shade"
        ? i18n.t('app.음영_지우기')
        : i18n.t('app.기본_색');
    clearBtn.hidden = false;
  }
  syncFormatPaletteSwatches(kind);
  const current = formatColorState[kind] || FORMAT_COLOR_DEFAULTS[kind];
  if ($("formatColorCustomPicker")) $("formatColorCustomPicker").value = current;
  palette.querySelectorAll(".format-swatch").forEach((btn) => {
    btn.classList.toggle("is-active", (btn.dataset.swatch || "").toLowerCase() === current.toLowerCase());
  });
  palette.classList.remove("hidden");
  const rect = anchorEl.getBoundingClientRect();
  const pad = 8;
  const pr = palette.getBoundingClientRect();
  let left = rect.left;
  let top = rect.bottom + 4;
  if (left + pr.width > window.innerWidth - pad) left = Math.max(pad, window.innerWidth - pr.width - pad);
  if (top + pr.height > window.innerHeight - pad) top = Math.max(pad, rect.top - pr.height - 4);
  palette.style.left = `${left}px`;
  palette.style.top = `${top}px`;
}

function setupFormatColorPalette() {
  setFormatColorState("text", formatColorState.text);
  setFormatColorState("highlight", formatColorState.highlight);
  setFormatColorState("shade", formatColorState.shade);

  const palette = $("formatColorPalette");
  if (!palette || palette.dataset.bound === "1") return;
  palette.dataset.bound = "1";

  palette.addEventListener("mousedown", (event) => {
    // Keep editor / chat selection while interacting with palette.
    event.preventDefault();
  });

  palette.addEventListener("click", (event) => {
    const swatch = event.target.closest("[data-swatch]");
    if (swatch && formatPaletteKind) {
      if (formatPaletteTarget === "tory-chat" && formatPaletteKind === "highlight") {
        applyToryChatHighlight(swatch.dataset.swatch);
        hideFormatColorPalette();
        return;
      }
      applyFormatColorToSelection(formatPaletteKind, swatch.dataset.swatch, formatPaletteEditor, { forceApply: true });
      hideFormatColorPalette();
      return;
    }
    if (event.target.closest("[data-palette-custom]")) {
      $("formatColorCustomPicker")?.click();
      return;
    }
    if (event.target.closest("[data-palette-clear]") && formatPaletteKind) {
      if (formatPaletteTarget === "tory-chat" && formatPaletteKind === "highlight") {
        clearToryChatHighlight();
        hideFormatColorPalette();
        return;
      }
      if (formatPaletteEditor) {
        focusEditor(formatPaletteEditor);
        if (formatPaletteRange) {
          try { restoreSelection(formatPaletteRange); } catch (_) { /* ignore */ }
        }
      }
      if (formatPaletteKind === "highlight") clearHighlight();
      else if (formatPaletteKind === "shade") clearShadeBox();
      else clearTextColor();
      hideFormatColorPalette();
    }
  });

  $("formatColorCustomPicker")?.addEventListener("input", (event) => {
    if (!formatPaletteKind) return;
    if (formatPaletteTarget === "tory-chat" && formatPaletteKind === "highlight") {
      // Preview bar only while dragging custom color; apply once on change
      setFormatColorState("highlight", event.target.value);
      return;
    }
    applyFormatColorToSelection(formatPaletteKind, event.target.value, formatPaletteEditor, { forceApply: true });
  });
  $("formatColorCustomPicker")?.addEventListener("change", (event) => {
    if (formatPaletteTarget === "tory-chat" && formatPaletteKind === "highlight") {
      applyToryChatHighlight(event.target?.value);
    }
    hideFormatColorPalette();
  });

  document.addEventListener("click", (event) => {
    if (event.target.closest("#formatColorPalette, [data-color-kind], #formatColorCustomPicker, #toryChatHighlightButton")) return;
    hideFormatColorPalette();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") hideFormatColorPalette();
  });
  window.addEventListener("blur", hideFormatColorPalette);
  window.addEventListener("resize", hideFormatColorPalette);
}

function contentToPreviewHtml(content) {
  if (!content || !String(content).trim()) {
    return escapeHtml(i18n.t('app.아직_쓴_원고가_없어요'));
  }
  if (looksLikeHtml(content)) {
    return sanitizeEditorHtml(content);
  }
  return escapeHtml(content).replace(/\r\n|\r|\n/g, "<br>");
}

function updateFormatButtonState(toolbarEl = null) {
  const states = [
    ["bold", "bold"],
    ["italic", "italic"],
    ["underline", "underline"],
    ["strike", "strikeThrough"],
    ["justifyLeft", "justifyLeft"],
    ["justifyCenter", "justifyCenter"],
    ["justifyRight", "justifyRight"],
    ["justifyFull", "justifyFull"],
  ];
  const root = toolbarEl || document;
  try {
    for (const [format, command] of states) {
      root.querySelectorAll(`[data-format="${format}"]`).forEach((button) => {
        button.classList.toggle("active", document.queryCommandState(command));
      });
    }
    let inList = false;
    try {
      inList = document.queryCommandState("insertUnorderedList")
        || document.queryCommandState("insertOrderedList");
    } catch (_) {
      inList = false;
    }
    root.querySelectorAll('[data-format="list"]').forEach((button) => {
      button.classList.toggle("active", inList);
    });
    const inDan = isSelectionInDanColumns();
    root.querySelectorAll('[data-format="dan"]').forEach((button) => {
      button.classList.toggle("active", inDan);
    });
  } catch (_) {
    /* ignore when selection is outside */
  }

  // Reflect active font / size in the selects (no separate "글꼴/크기" labels).
  const toolbars = toolbarEl
    ? [toolbarEl]
    : [$("formatToolbar"), $("synopsisFormatToolbar")].filter(Boolean);
  for (const toolbar of toolbars) {
    if (!toolbar) continue;
    const editor = (toolbar.id === "synopsisFormatToolbar"
      ? (getActiveRichEditor() || $("synopsisContent"))
      : ($("sceneContent") || getActiveRichEditor())) || $("sceneContent");
    if (editor) syncFormatFontSizeSelects(toolbar, editor);
  }
}

/* —— Unified list styles (bullet + number + symbols) —— */
const LIST_STYLE_STORAGE_KEY = "supertory.listStyle";
const LIST_STYLES = [
  // Bullets / symbols
  { key: "disc", kind: "ul", label: i18n.t('app.점'), preview: "•", css: "disc" },
  { key: "circle", kind: "ul", label: i18n.t('app.동그라미'), preview: "○", css: "circle" },
  { key: "square", kind: "ul", label: i18n.t('app.네모'), preview: "■", css: "square" },
  { key: "dash", kind: "ul", label: i18n.t('app.대시'), preview: "–", css: '"– "' },
  { key: "dot", kind: "ul", label: i18n.t('app.가운데점'), preview: "·", css: '"· "' },
  { key: "star", kind: "ul", label: i18n.t('app.별'), preview: "★", css: '"★ "' },
  { key: "hollow-star", kind: "ul", label: i18n.t('app.빈_별'), preview: "☆", css: '"☆ "' },
  { key: "diamond", kind: "ul", label: i18n.t('app.마름모'), preview: "◆", css: '"◆ "' },
  { key: "arrow", kind: "ul", label: i18n.t('app.화살표'), preview: "►", css: '"► "' },
  { key: "tri", kind: "ul", label: i18n.t('app.삼각형'), preview: "▸", css: '"▸ "' },
  { key: "check", kind: "ul", label: i18n.t('app.체크'), preview: "✓", css: '"✓ "' },
  { key: "note", kind: "ul", label: i18n.t('app.참고'), preview: "※", css: '"※ "' },
  { key: "heart", kind: "ul", label: i18n.t('app.하트'), preview: "♥", css: '"♥ "' },
  { key: "flower", kind: "ul", label: i18n.t('app.꽃'), preview: "❀", css: '"❀ "' },
  { key: "box", kind: "ul", label: i18n.t('app.빈_칸'), preview: "☐", css: '"☐ "' },
  { key: "hand", kind: "ul", label: i18n.t('app.손가락'), preview: "☞", css: '"☞ "' },
  // Numbers
  { key: "decimal", kind: "ol", label: "1. 2. 3.", preview: "1.", css: "decimal" },
  { key: "decimal-zero", kind: "ol", label: "01. 02.", preview: "01.", css: "decimal-leading-zero" },
  { key: "lower-alpha", kind: "ol", label: "a. b. c.", preview: "a.", css: "lower-alpha" },
  { key: "upper-alpha", kind: "ol", label: "A. B. C.", preview: "A.", css: "upper-alpha" },
  { key: "lower-roman", kind: "ol", label: "i. ii. iii.", preview: "i.", css: "lower-roman" },
  { key: "upper-roman", kind: "ol", label: "I. II. III.", preview: "I.", css: "upper-roman" },
];
const LIST_STYLE_BY_KEY = Object.fromEntries(LIST_STYLES.map((s) => [s.key, s]));
let formatListStyleKey = "disc";
let formatListPaletteEditor = null;
let formatListPaletteRange = null;

function getListStyle(key = formatListStyleKey) {
  return LIST_STYLE_BY_KEY[key] || LIST_STYLE_BY_KEY.disc;
}

function loadStoredListStyle() {
  try {
    const key = localStorage.getItem(LIST_STYLE_STORAGE_KEY);
    if (key && LIST_STYLE_BY_KEY[key]) formatListStyleKey = key;
  } catch (_) {
    /* ignore */
  }
  return formatListStyleKey;
}

function saveListStyle(key) {
  if (!LIST_STYLE_BY_KEY[key]) return;
  formatListStyleKey = key;
  try {
    localStorage.setItem(LIST_STYLE_STORAGE_KEY, key);
  } catch (_) {
    /* ignore */
  }
  updateListButtonMarks();
  document.querySelectorAll("#formatListPalette [data-list-style]").forEach((btn) => {
    btn.classList.toggle("is-active", btn.dataset.listStyle === key);
  });
}

function updateListButtonMarks() {
  const style = getListStyle();
  document.querySelectorAll("[data-list-mark]").forEach((el) => {
    el.textContent = style.preview || "•";
  });
  document.querySelectorAll(".format-list-btn, .format-bullet-btn").forEach((btn) => {
    btn.title = `${i18n.t('app.글머리_기호_style_label_클릭_적용', {'style.label': style.label})}`;
  });
}

function findListAncestor(node, editor) {
  let el = node?.nodeType === 3 ? node.parentElement : node;
  while (el && el !== editor) {
    if (el.nodeType === 1 && (el.tagName === "UL" || el.tagName === "OL")) return el;
    el = el.parentElement;
  }
  return null;
}

function replaceListTag(list, tagName) {
  if (!list || !list.parentNode) return list;
  const next = document.createElement(tagName);
  // Preserve known attributes/styles useful for list markers.
  if (list.getAttribute("style")) next.setAttribute("style", list.getAttribute("style"));
  if (list.dataset.listStyle) next.dataset.listStyle = list.dataset.listStyle;
  while (list.firstChild) next.appendChild(list.firstChild);
  list.parentNode.replaceChild(next, list);
  return next;
}

function applyCssListStyle(list, style) {
  if (!list || !style) return;
  list.style.listStyleType = style.css;
  list.style.listStylePosition = "outside";
  list.dataset.listStyle = style.key;
}

function removeListAtSelection(editor = getActiveRichEditor() || $("sceneContent")) {
  if (!editor) return;
  try {
    document.execCommand("styleWithCSS", false, "true");
  } catch (_) {
    /* ignore */
  }
  if (document.queryCommandState("insertOrderedList")) {
    document.execCommand("insertOrderedList", false, null);
  } else if (document.queryCommandState("insertUnorderedList")) {
    document.execCommand("insertUnorderedList", false, null);
  }
  updateEditorPlaceholder(editor);
  try {
    editor.dispatchEvent(new Event("input", { bubbles: true }));
  } catch (_) {
    /* ignore */
  }
  updateFormatButtonState();
}

function applyListStyle(styleKey, editorEl = null) {
  const editor = editorEl || getActiveRichEditor() || $("sceneContent");
  const style = getListStyle(styleKey);
  if (!editor || !style) return;
  saveListStyle(style.key);

  focusEditor(editor);
  try {
    document.execCommand("styleWithCSS", false, "true");
  } catch (_) {
    /* ignore */
  }

  const selection = window.getSelection();
  let list = null;
  if (selection?.rangeCount) {
    const range = selection.getRangeAt(0);
    if (editor.contains(range.commonAncestorContainer)) {
      list = findListAncestor(range.commonAncestorContainer, editor);
    }
  }

  const needOl = style.kind === "ol";
  if (!list) {
    document.execCommand(needOl ? "insertOrderedList" : "insertUnorderedList", false, null);
    if (selection?.rangeCount) {
      list = findListAncestor(selection.getRangeAt(0).commonAncestorContainer, editor);
    }
    // Fallback: nearest list inside editor
    if (!list) {
      const lists = editor.querySelectorAll(needOl ? "ol" : "ul");
      list = lists[lists.length - 1] || null;
    }
  } else if ((list.tagName === "OL") !== needOl) {
    list = replaceListTag(list, needOl ? "OL" : "UL");
  } else if (list.dataset.listStyle === style.key) {
    // Same style again → toggle list off.
    removeListAtSelection(editor);
    return;
  }

  if (list) applyCssListStyle(list, style);

  updateEditorPlaceholder(editor);
  try {
    editor.dispatchEvent(new Event("input", { bubbles: true }));
  } catch (_) {
    /* ignore */
  }
  updateFormatButtonState();
}

function hideFormatListPalette() {
  const palette = $("formatListPalette");
  if (!palette) return;
  palette.classList.add("hidden");
  document.querySelectorAll(".format-list-btn").forEach((btn) => {
    btn.setAttribute("aria-expanded", "false");
  });
}

function showFormatListPalette(anchorBtn, editor = null) {
  const palette = $("formatListPalette");
  if (!palette || !anchorBtn) return;
  hideFormatColorPalette?.();
  hideFormatSpecialPalette?.();
  formatListPaletteEditor = editor || getActiveRichEditor() || $("sceneContent");
  formatListPaletteRange = currentEditorRange(formatListPaletteEditor);

  document.querySelectorAll("#formatListPalette [data-list-style]").forEach((btn) => {
    btn.classList.toggle("is-active", btn.dataset.listStyle === formatListStyleKey);
  });

  palette.classList.remove("hidden");
  anchorBtn.setAttribute("aria-expanded", "true");

  const rect = anchorBtn.getBoundingClientRect();
  const pad = 8;
  const pw = palette.offsetWidth || 240;
  const ph = palette.offsetHeight || 280;
  let left = rect.left;
  let top = rect.bottom + 4;
  if (left + pw > window.innerWidth - pad) left = Math.max(pad, window.innerWidth - pw - pad);
  if (top + ph > window.innerHeight - pad) top = Math.max(pad, rect.top - ph - 4);
  palette.style.left = `${Math.max(pad, left)}px`;
  palette.style.top = `${Math.max(pad, top)}px`;
}

function setupFormatListPalette() {
  loadStoredListStyle();
  updateListButtonMarks();

  const bulletHost = $("formatListBulletOptions");
  const numberHost = $("formatListNumberOptions");
  if (bulletHost && !bulletHost.dataset.filled) {
    bulletHost.innerHTML = LIST_STYLES.filter((s) => s.kind === "ul").map((style) => `
      <button type="button" class="format-list-option" role="menuitem"
        data-list-style="${style.key}" title="${escapeHtml(style.label)}">
        <span class="format-list-option-preview">${escapeHtml(style.preview)}</span>
        <span class="format-list-option-label">${escapeHtml(style.label)}</span>
      </button>
    `).join("");
    bulletHost.dataset.filled = "1";
  }
  if (numberHost && !numberHost.dataset.filled) {
    numberHost.innerHTML = LIST_STYLES.filter((s) => s.kind === "ol").map((style) => `
      <button type="button" class="format-list-option" role="menuitem"
        data-list-style="${style.key}" title="${escapeHtml(style.label)}">
        <span class="format-list-option-preview">${escapeHtml(style.preview)}</span>
        <span class="format-list-option-label">${escapeHtml(style.label)}</span>
      </button>
    `).join("");
    numberHost.dataset.filled = "1";
  }

  const palette = $("formatListPalette");
  if (!palette || palette.dataset.bound === "1") {
    updateListButtonMarks();
    return;
  }
  palette.dataset.bound = "1";

  palette.addEventListener("mousedown", (event) => {
    // Keep editor selection while interacting with palette.
    event.preventDefault();
  });

  palette.addEventListener("click", (event) => {
    const option = event.target.closest("[data-list-style]");
    if (option) {
      const editor = formatListPaletteEditor || getActiveRichEditor() || $("sceneContent");
      focusEditor(editor);
      if (formatListPaletteRange) {
        try { restoreSelection(formatListPaletteRange); } catch (_) { /* ignore */ }
      }
      applyListStyle(option.dataset.listStyle, editor);
      hideFormatListPalette();
      return;
    }
    if (event.target.closest("[data-list-remove]")) {
      const editor = formatListPaletteEditor || getActiveRichEditor() || $("sceneContent");
      focusEditor(editor);
      if (formatListPaletteRange) {
        try { restoreSelection(formatListPaletteRange); } catch (_) { /* ignore */ }
      }
      removeListAtSelection(editor);
      hideFormatListPalette();
    }
  });

  document.addEventListener("click", (event) => {
    if (event.target.closest("#formatListPalette, .format-list-btn, .format-bullet-btn")) return;
    hideFormatListPalette();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") hideFormatListPalette();
  });
  window.addEventListener("blur", hideFormatListPalette);
  window.addEventListener("resize", hideFormatListPalette);
}

/* —— 특수문자 삽입 —— */
const SPECIAL_CHARS_UNIQUE = [
  "※", "★", "☆", "○", "●", "◎", "◇", "◆", "□", "■",
  "△", "▲", "▽", "▼", "▷", "▶", "◁", "◀",
  "♠", "♣", "♥", "♦", "♪", "♭", "♯",
  "→", "←", "↑", "↓", "↔", "⇒", "⇔",
  "·", "‥", "…", "∶", "∷",
  "±", "×", "÷", "≠", "≤", "≥", "∞", "℃", "℉",
  "§", "¶", "†", "‡", "〒",
  "①", "②", "③", "④", "⑤", "⑥", "⑦", "⑧", "⑨", "⑩",
  "⑴", "⑵", "⑶", "⑷", "⑸",
  "ⓐ", "ⓑ", "ⓒ", "ⓓ", "ⓔ",
  "「", "」", "『", "』", "【", "】", "〈", "〉", "《", "》",
  "©", "®", "™", "€", "£", "¥", "$",
];
let formatSpecialPaletteEditor = null;
let formatSpecialPaletteRange = null;

function hideFormatSpecialPalette() {
  const palette = $("formatSpecialPalette");
  if (!palette) return;
  palette.classList.add("hidden");
  document.querySelectorAll(".format-special-btn").forEach((btn) => {
    btn.setAttribute("aria-expanded", "false");
  });
}

function showFormatSpecialPalette(anchorBtn, editor = null) {
  const palette = $("formatSpecialPalette");
  if (!palette || !anchorBtn) return;
  hideFormatColorPalette?.();
  hideFormatListPalette?.();
  formatSpecialPaletteEditor = editor || getActiveRichEditor() || $("sceneContent");
  formatSpecialPaletteRange = currentEditorRange(formatSpecialPaletteEditor)
    || getUsableEditorRange(formatSpecialPaletteEditor);

  palette.classList.remove("hidden");
  anchorBtn.setAttribute("aria-expanded", "true");

  const rect = anchorBtn.getBoundingClientRect();
  const pad = 8;
  const pw = palette.offsetWidth || 280;
  const ph = palette.offsetHeight || 220;
  let left = rect.left;
  let top = rect.bottom + 4;
  if (left + pw > window.innerWidth - pad) left = Math.max(pad, window.innerWidth - pw - pad);
  if (top + ph > window.innerHeight - pad) top = Math.max(pad, rect.top - ph - 4);
  palette.style.left = `${Math.max(pad, left)}px`;
  palette.style.top = `${Math.max(pad, top)}px`;
}

function insertSpecialChar(char, editorEl = null) {
  const editor = editorEl || formatSpecialPaletteEditor || getActiveRichEditor() || $("sceneContent");
  if (!editor || !char) return;
  focusEditor(editor);
  const range = formatSpecialPaletteRange || getUsableEditorRange(editor) || currentEditorRange(editor);
  if (range) {
    try { restoreSelection(range); } catch (_) { /* ignore */ }
  }
  try {
    document.execCommand("styleWithCSS", false, "true");
  } catch (_) {
    /* ignore */
  }
  let ok = false;
  try {
    ok = document.execCommand("insertText", false, char);
  } catch (_) {
    ok = false;
  }
  if (!ok) {
    try {
      const sel = window.getSelection();
      if (sel && sel.rangeCount) {
        const r = sel.getRangeAt(0);
        r.deleteContents();
        const text = document.createTextNode(char);
        r.insertNode(text);
        r.setStartAfter(text);
        r.collapse(true);
        sel.removeAllRanges();
        sel.addRange(r);
      }
    } catch (_) {
      /* ignore */
    }
  }
  formatSpecialPaletteRange = currentEditorRange(editor);
  updateEditorPlaceholder(editor);
  try {
    editor.dispatchEvent(new Event("input", { bubbles: true }));
  } catch (_) {
    /* ignore */
  }
  if (editor.id === "sceneContent" && state.sceneId) markSceneDirty?.();
  else if (editor.id === "synopsisContent" || editor.id === "synopsisContentB") markSettingsDocEditorDirty?.(editor);
}

function setupFormatSpecialPalette() {
  const host = $("formatSpecialOptions");
  if (host && !host.dataset.filled) {
    host.innerHTML = SPECIAL_CHARS_UNIQUE.map((ch) => `
      <button type="button" class="format-special-option" role="menuitem"
        data-special-char="${escapeHtml(ch)}" title="${escapeHtml(ch)}">${escapeHtml(ch)}</button>
    `).join("");
    host.dataset.filled = "1";
  }

  const palette = $("formatSpecialPalette");
  if (!palette || palette.dataset.bound === "1") return;
  palette.dataset.bound = "1";

  palette.addEventListener("mousedown", (event) => {
    event.preventDefault();
  });

  palette.addEventListener("click", (event) => {
    const option = event.target.closest("[data-special-char]");
    if (!option) return;
    const ch = option.dataset.specialChar;
    const editor = formatSpecialPaletteEditor || getActiveRichEditor() || $("sceneContent");
    insertSpecialChar(ch, editor);
    // keep palette open for multiple inserts; refresh range
    formatSpecialPaletteRange = currentEditorRange(editor);
  });

  document.addEventListener("click", (event) => {
    if (event.target.closest("#formatSpecialPalette, .format-special-btn")) return;
    hideFormatSpecialPalette();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") hideFormatSpecialPalette();
  });
  window.addEventListener("blur", hideFormatSpecialPalette);
  window.addEventListener("resize", hideFormatSpecialPalette);
}

