/**
 * How the two header dropdowns behave for the current work purpose.
 * - fiction: 일반소설 / 웹소설 / 단편 → 메인·서브 장르
 * - translation: 원문 언어 · 번역문 언어
 * - fairy_tale: 유아용 / 초등용 (대상만)
 * - none: 종류만 선택 (추가 칸 숨김)
 */
function getPurposeCategoryMode(purpose = state.projectPurpose) {
  const p = normalizePurposeKey(purpose);
  if (p === "translation") return "translation";
  if (p === "fairy_tale") return "fairy_tale";
  if (
    p === "general_novel"
    || p === "web_novel"
    || p === "short_story"
  ) return "fiction";
  return "none";
}

function genrePickerTitleForMode(mode = getPurposeCategoryMode()) {
  if (mode === "translation") return i18n.t('app.원문_언어_번역문_언어');
  if (mode === "fairy_tale") return i18n.t('app.동화_대상_유아용_초등용');
  if (mode === "fiction") return i18n.t('app.메인_서브_장르');
  return i18n.t('app.장르');
}

/** Header genre <select>s are value stores only — never interactive dropdowns. */
function lockHeaderGenreSelects() {
  for (const id of ["mainGenreSelect", "subGenreSelect", "genreDetailSelect"]) {
    const select = $(id);
    if (!select) continue;
    select.disabled = true;
    select.setAttribute("aria-hidden", "true");
    select.tabIndex = -1;
    select.classList.add("genre-select-hidden");
  }
}

function updateGenrePickerVisibility() {
  const picker = $("genrePicker");
  if (!picker) return;
  const mode = getPurposeCategoryMode();
  const show = mode === "fiction" || mode === "translation" || mode === "fairy_tale";
  picker.classList.toggle("hidden", !show);
  picker.setAttribute("aria-hidden", show ? "false" : "true");
  picker.dataset.mode = mode;
  picker.title = genrePickerTitleForMode(mode);
  // 동화: 대상(유아용/초등용)만 — 두 번째 칸 숨김
  // 번역: 원문 + 번역문 둘 다
  // 소설류: 메인 + 서브
  const subField = $("subGenreSelect")?.closest?.(".genre-field");
  if (subField) {
    subField.classList.toggle("hidden", mode === "fairy_tale" || mode === "none");
  }
  const mainField = $("mainGenreSelect")?.closest?.(".genre-field");
  if (mainField) {
    mainField.classList.toggle("hidden", mode === "none");
  }
  lockHeaderGenreSelects();
  if (!show) {
    if ($("mainGenreDisplay")) $("mainGenreDisplay").disabled = true;
    if ($("subGenreDisplay")) $("subGenreDisplay").disabled = true;
    $("mainGenreCustom")?.classList.add("hidden");
    $("subGenreCustom")?.classList.add("hidden");
  }
}

function normalizePurposeKey(purpose) {
  const p = String(purpose || "").trim();
  if (p === "novel") return "general_novel"; // legacy DB value
  if (purposeLabel[p]) return p;
  return "general_novel";
}

function isKnownLanguage(key) {
  return WORK_LANGUAGES.some((g) => g.key === key);
}

function isKnownFairyAudience(key) {
  return FAIRY_TALE_AUDIENCES.some((g) => g.key === key);
}

function isKnownMainGenre(key) {
  return MAIN_GENRES.some((g) => g.key === key);
}

function isKnownSubGenre(mainKey, key) {
  const k = String(key || "");
  if (!k) return false;
  return (SUB_GENRES[mainKey] || []).some((g) => g.key === k)
    || FAIRY_TALE_SUBS.some((g) => g.key === k)
    || isKnownLanguage(k);
}

function isCustomGenreValue(value) {
  return String(value || "").startsWith(GENRE_CUSTOM_PREFIX);
}

function customGenreText(value) {
  const raw = String(value || "");
  if (isCustomGenreValue(raw)) return raw.slice(GENRE_CUSTOM_PREFIX.length);
  // Legacy free-text (unknown key) treated as custom label.
  if (raw && !isKnownMainGenre(raw) && !isKnownLanguage(raw) && !isKnownFairyAudience(raw) && raw !== "other") {
    return raw;
  }
  return "";
}

function toCustomGenreValue(text) {
  const trimmed = String(text || "").trim().slice(0, 40);
  return trimmed ? `${GENRE_CUSTOM_PREFIX}${trimmed}` : "other";
}

function mainGenreLabel(key = state.mainGenre) {
  const value = String(key || "").trim();
  if (!value) return i18n.t('app.미정');
  if (isCustomGenreValue(value)) return customGenreText(value) || i18n.t('app.기타');
  return MAIN_GENRES.find((g) => g.key === value)?.label
    || WORK_LANGUAGES.find((g) => g.key === value)?.label
    || FAIRY_TALE_AUDIENCES.find((g) => g.key === value)?.label
    || value;
}

function subGenreLabel(mainKey = state.mainGenre, subKey = state.subGenre) {
  const value = String(subKey || "").trim();
  if (!value) return i18n.t('app.미정');
  if (isCustomGenreValue(value)) return customGenreText(value) || i18n.t('app.기타');
  if (value === "adult19") return i18n.t('app.19금');
  if (WORK_LANGUAGES.some((g) => g.key === value)) {
    return WORK_LANGUAGES.find((g) => g.key === value)?.label || value;
  }
  if (FAIRY_TALE_SUBS.some((g) => g.key === value)) {
    return FAIRY_TALE_SUBS.find((g) => g.key === value)?.label || value;
  }
  const listKey = isKnownMainGenre(mainKey) ? mainKey : "other";
  return (SUB_GENRES[listKey] || []).find((g) => g.key === value)?.label || value;
}

function resolveMainGenreSelectValue(stored, mode = getPurposeCategoryMode()) {
  const value = String(stored || "");
  if (!value) return "";
  if (mode === "none") return "";
  if (mode === "translation") {
    if (isKnownLanguage(value)) return value;
    return "other";
  }
  if (mode === "fairy_tale") {
    if (isKnownFairyAudience(value)) return value;
    return "";
  }
  // fiction
  if (isKnownMainGenre(value)) return value;
  return "other"; // custom free-text or custom: prefix
}

function resolveSubGenreSelectValue(mainKey, stored, mode = getPurposeCategoryMode()) {
  const value = String(stored || "");
  if (!value) return "";
  if (mode === "none" || mode === "fairy_tale") return "";
  if (mode === "translation") {
    if (isKnownLanguage(value)) return value;
    return "other";
  }
  // fiction
  if (value === "adult19") {
    return purposeAllowsAdult19() ? "adult19" : "";
  }
  if (isKnownSubGenre(mainKey, value)) return value;
  if (isKnownSubGenre(mainKey === "other" ? "other" : mainKey, value)) return value;
  return "other";
}

function updateGenreCustomVisibility() {
  const hasProject = Boolean(state.projectId);
  const mode = getPurposeCategoryMode();
  const mainSelect = $("mainGenreSelect");
  const subSelect = $("subGenreSelect");
  const mainCustom = $("mainGenreCustom");
  const subCustom = $("subGenreCustom");
  const mainKey = mainSelect?.value || "";
  const subKey = subSelect?.value || "";
  // Translation / fairy tale: custom only when "기타" language/sub is chosen
  const showMainCustom = hasProject && mainKey === "other";
  const showSubCustom = hasProject && Boolean(mainKey) && subKey === "other";
  if (mainCustom) {
    mainCustom.classList.toggle("hidden", !showMainCustom);
    mainCustom.disabled = !showMainCustom;
    if (!showMainCustom) mainCustom.value = "";
    if (mode === "translation") mainCustom.placeholder = i18n.t('app.원문_언어_직접_입력');
    else if (mode === "fairy_tale") mainCustom.placeholder = i18n.t('app.대상_직접_입력');
    else mainCustom.placeholder = i18n.t('app.직접_입력');
  }
  if (subCustom) {
    subCustom.classList.toggle("hidden", !showSubCustom);
    subCustom.disabled = !showSubCustom;
    if (!showSubCustom) subCustom.value = "";
    if (mode === "translation") subCustom.placeholder = i18n.t('app.번역_언어_직접_입력');
    else subCustom.placeholder = i18n.t('app.직접_입력');
  }
}

function fillMainGenreSelect(selectedStored = "") {
  const select = $("mainGenreSelect");
  if (!select) return;
  const mode = getPurposeCategoryMode();
  if (mode === "none") {
    select.innerHTML = `<option value="">—</option>`;
    select.value = "";
    select.disabled = true;
    return;
  }
  const selectValue = resolveMainGenreSelectValue(selectedStored, mode);
  let placeholder = i18n.t('app.메인_장르');
  let options = MAIN_GENRES;
  if (mode === "translation") {
    placeholder = i18n.t('app.원문_언어');
    options = WORK_LANGUAGES;
  } else if (mode === "fairy_tale") {
    placeholder = i18n.t('app.유아용_초등용');
    options = FAIRY_TALE_AUDIENCES;
  }
  select.setAttribute("aria-label", placeholder);
  select.title = placeholder;
  select.innerHTML = [
    `<option value="">${escapeHtml(placeholder)}</option>`,
    ...options.map((g) =>
      `<option value="${escapeHtml(g.key)}">${escapeHtml(g.label)}</option>`
    ),
  ].join("");
  if ([...select.options].some((o) => o.value === selectValue)) select.value = selectValue;
  else select.value = "";
  lockHeaderGenreSelects();
  const mainCustom = $("mainGenreCustom");
  if (mainCustom) {
    // 동화 대상은 고정 2개 — 직접 입력 칸 불필요
    if (mode === "fairy_tale") {
      mainCustom.classList.add("hidden");
      mainCustom.disabled = true;
      mainCustom.value = "";
    } else if (selectValue === "other") {
      mainCustom.value = isCustomGenreValue(selectedStored)
        ? customGenreText(selectedStored)
        : (selectedStored && selectedStored !== "other" ? String(selectedStored) : "");
    } else {
      mainCustom.value = "";
    }
  }
}

function fillSubGenreSelect(mainKey = "", selectedStored = "") {
  const select = $("subGenreSelect");
  if (!select) return;
  const mode = getPurposeCategoryMode();
  if (mode === "none" || mode === "fairy_tale") {
    // 동화는 대상만 선택
    select.innerHTML = `<option value="">—</option>`;
    select.value = "";
    lockHeaderGenreSelects();
    $("subGenreCustom")?.classList.add("hidden");
    if ($("subGenreCustom")) $("subGenreCustom").disabled = true;
    return;
  }
  let placeholder = i18n.t('app.서브_장르');
  let subs = [];
  let listKey = mainKey;

  if (mode === "translation") {
    placeholder = i18n.t('app.번역문_언어');
    subs = WORK_LANGUAGES;
    listKey = "lang";
  } else if (mode === "fiction") {
    // 일반소설 · 웹소설 · 단편 only; 19금 available in subs
    listKey = isKnownMainGenre(mainKey) ? mainKey : (mainKey ? "other" : "");
    const baseSubs = SUB_GENRES[listKey] || [];
    subs = withAdult19Option(baseSubs);
  } else {
    subs = [];
    listKey = "";
  }

  select.setAttribute("aria-label", placeholder);
  if (!listKey || !subs.length) {
    select.innerHTML = `<option value="">${escapeHtml(placeholder)}</option>`;
    select.value = "";
    lockHeaderGenreSelects();
    const subCustom = $("subGenreCustom");
    if (subCustom) {
      subCustom.value = "";
      subCustom.classList.add("hidden");
      subCustom.disabled = true;
    }
    return;
  }
  select.innerHTML = [
    `<option value="">${escapeHtml(placeholder)}</option>`,
    ...subs.map((g) =>
      `<option value="${escapeHtml(g.key)}">${escapeHtml(g.label)}</option>`
    ),
  ].join("");
  const selectValue = resolveSubGenreSelectValue(
    mode === "translation" ? "lang" : listKey,
    selectedStored,
    mode,
  );
  // adult19 is always valid if present in list
  if ([...select.options].some((o) => o.value === selectValue)) select.value = selectValue;
  else if (selectedStored === "adult19" && [...select.options].some((o) => o.value === "adult19")) {
    select.value = "adult19";
  } else select.value = "";
  lockHeaderGenreSelects();
  const subCustom = $("subGenreCustom");
  if (subCustom) {
    if (select.value === "other") {
      subCustom.value = isCustomGenreValue(selectedStored)
        ? customGenreText(selectedStored)
        : (selectedStored && selectedStored !== "other" ? String(selectedStored) : "");
    } else {
      subCustom.value = "";
    }
  }
}

function fillGenreDetailSelect(mainKey = "", selectedSub = "", selectedStored = "") {
  const select = $("genreDetailSelect");
  const options = genreDetailOptionsForMainSub(mainKey, selectedSub);
  const next = fillGenreDetailSelectEl(select, options, selectedStored || "");
  state.genreDetail = next;
  lockHeaderGenreSelects();
}

function readGenreValuesFromUi() {
  const mainSelect = $("mainGenreSelect")?.value || "";
  const subSelect = $("subGenreSelect")?.value || "";
  const mainCustom = ($("mainGenreCustom")?.value || "").trim();
  const subCustom = ($("subGenreCustom")?.value || "").trim();
  let main = mainSelect;
  let sub = subSelect;
  if (mainSelect === "other") {
    main = mainCustom ? toCustomGenreValue(mainCustom) : "other";
  }
  if (subSelect === "other") {
    sub = subCustom ? toCustomGenreValue(subCustom) : "other";
  }
  const detail = normalizeGenreDetailKey(main, sub, $("genreDetailSelect")?.value || state.genreDetail || "");
  return { main, sub, genre_detail: detail };
}

function syncGenrePickerFromState() {
  // Ensure purpose is normalized before mode checks
  if (state.projectPurpose) {
    state.projectPurpose = normalizePurposeKey(state.projectPurpose);
  }
  updateGenrePickerVisibility();
  const mode = getPurposeCategoryMode();
  const hasProject = Boolean(state.projectId);
  if (mode === "none") {
    fillGenreDetailSelect("", "", "");
    updateGenreCustomVisibility();
    syncGenreDisplayButtons();
    return;
  }
  const main = $("mainGenreSelect");
  const sub = $("subGenreSelect");
  fillMainGenreSelect(state.mainGenre || "");
  lockHeaderGenreSelects();
  if (mode === "fairy_tale") {
    // 대상만 — 서브 비움
    fillSubGenreSelect("", "");
    fillGenreDetailSelect("", "", "");
    updateGenreCustomVisibility();
    syncGenreDisplayButtons();
    return;
  }
  if (mode === "translation") {
    // Always show both language lists (원문 / 번역문)
    fillSubGenreSelect("lang", state.subGenre || "");
    fillGenreDetailSelect("", "", "");
    lockHeaderGenreSelects();
    updateGenreCustomVisibility();
    if (hasProject) {
      const mainCustom = $("mainGenreCustom");
      const subCustom = $("subGenreCustom");
      if (mainCustom && main?.value === "other") {
        mainCustom.classList.remove("hidden");
        mainCustom.disabled = false;
        mainCustom.value = isCustomGenreValue(state.mainGenre)
          ? customGenreText(state.mainGenre)
          : (state.mainGenre && state.mainGenre !== "other" && !isKnownLanguage(state.mainGenre)
            ? state.mainGenre
            : mainCustom.value);
      }
      if (subCustom && sub?.value === "other") {
        subCustom.classList.remove("hidden");
        subCustom.disabled = false;
        subCustom.value = isCustomGenreValue(state.subGenre)
          ? customGenreText(state.subGenre)
          : (state.subGenre && state.subGenre !== "other" && !isKnownLanguage(state.subGenre)
            ? state.subGenre
            : subCustom.value);
      }
    }
    syncGenreDisplayButtons();
    return;
  }
  // fiction
  const mainKeyForSubs = resolveMainGenreSelectValue(state.mainGenre || "", mode);
  const subListKey = isKnownMainGenre(state.mainGenre) ? state.mainGenre : (mainKeyForSubs || "");
  fillSubGenreSelect(subListKey, state.subGenre || "");
  fillGenreDetailSelect(subListKey, state.subGenre || "", state.genreDetail || "");
  lockHeaderGenreSelects();
  updateGenreCustomVisibility();
  if (hasProject) {
    const mainCustom = $("mainGenreCustom");
    const subCustom = $("subGenreCustom");
    if (mainCustom && main?.value === "other") {
      mainCustom.classList.remove("hidden");
      mainCustom.disabled = false;
      mainCustom.value = isCustomGenreValue(state.mainGenre)
        ? customGenreText(state.mainGenre)
        : (state.mainGenre && state.mainGenre !== "other" && !isKnownMainGenre(state.mainGenre)
          ? state.mainGenre
          : mainCustom.value);
    }
    if (subCustom && sub?.value === "other") {
      subCustom.classList.remove("hidden");
      subCustom.disabled = false;
      const listKey = isKnownMainGenre(state.mainGenre) ? state.mainGenre : "other";
      subCustom.value = isCustomGenreValue(state.subGenre)
        ? customGenreText(state.subGenre)
        : (state.subGenre && state.subGenre !== "other" && !isKnownSubGenre(listKey, state.subGenre)
          ? state.subGenre
          : subCustom.value);
    }
  }
  syncGenreDisplayButtons();
}

let genrePersistTimer = null;
function schedulePersistProjectGenre() {
  if (genrePersistTimer) window.clearTimeout(genrePersistTimer);
  genrePersistTimer = window.setTimeout(() => {
    persistProjectGenre({ quiet: true }).catch(handleError);
  }, 400);
}

async function persistProjectGenre({ quiet = true } = {}) {
  if (!state.projectId) return;
  const { main, sub, genre_detail } = readGenreValuesFromUi();
  state.mainGenre = main;
  state.subGenre = sub;
  state.genreDetail = genre_detail;
  state.clusterId = inferClusterId(state.projectPurpose, main, sub);
  await api(`/api/projects/${state.projectId}/settings`, {
    method: "POST",
    body: JSON.stringify({
      main_genre: main,
      sub_genre: sub,
      cluster_id: state.clusterId,
      genre_detail,
    }),
  });
  const project = state.projects.find((p) => p.id === state.projectId);
  if (project) {
    project.main_genre = main;
    project.sub_genre = sub;
    project.cluster_id = state.clusterId;
    project.genre_detail = genre_detail;
  }
  syncGenreDisplayButtons();
  if (typeof renderSettingsCodex === "function") {
    try { renderSettingsCodex(); } catch (_) { /* ignore */ }
  }
  try { applyClusterFeatureGating(); } catch (_) { /* ignore */ }
  if (!quiet) toast(i18n.t('app.장르를_저장했습니다'));
}

function syncGenreDisplayButtons() {
  const mainSelect = $("mainGenreSelect");
  const subSelect = $("subGenreSelect");
  const mainBtn = $("mainGenreDisplay");
  const subBtn = $("subGenreDisplay");
  const mode = getPurposeCategoryMode();
  const hasProject = Boolean(state.projectId);

  if (mainBtn) {
    const opt = mainSelect?.selectedOptions?.[0];
    let label = (opt && opt.value)
      ? String(opt.textContent || "").trim()
      : (mainSelect?.options?.[0]?.textContent || i18n.t('app.장르')).trim();
    if (mainSelect?.value === "other") {
      const custom = ($("mainGenreCustom")?.value || "").trim();
      if (custom) label = custom;
    }
    const detailKey = $("genreDetailSelect")?.value || state.genreDetail || "";
    const detailText = genreDetailLabel(detailKey);
    if (detailText) label = `${label} · ${detailText}`;
    mainBtn.textContent = label || i18n.t('app.장르');
    mainBtn.classList.toggle("is-with-detail", Boolean(detailText));
    mainBtn.disabled = !hasProject || mode === "none";
    mainBtn.title = hasProject
      ? i18n.t('app.우클릭_장르_변경')
      : i18n.t('app.작품을_먼저_선택해_주세요_2');
  }
  if (subBtn) {
    const opt = subSelect?.selectedOptions?.[0];
    let label = (opt && opt.value)
      ? String(opt.textContent || "").trim()
      : (subSelect?.options?.[0]?.textContent || i18n.t('app.하위_장르')).trim();
    if (subSelect?.value === "other") {
      const custom = ($("subGenreCustom")?.value || "").trim();
      if (custom) label = custom;
    }
    subBtn.textContent = label || i18n.t('app.하위_장르');
    const subHidden = mode === "fairy_tale" || mode === "none";
    // Header <select> is always disabled (value store) — do not gate the display button on it.
    subBtn.disabled = !hasProject || subHidden;
    subBtn.title = hasProject
      ? (mode === "translation" ? i18n.t('app.우클릭_번역문_언어_변경') : i18n.t('app.우클릭_하위_장르_변경'))
      : i18n.t('app.작품을_먼저_선택해_주세요_2');
  }
}

function confirmGenreChange() {
  return window.confirm(
    i18n.t('app.토리가_새로운_장르_기준으로_다시_학습해야해'),
  );
}

function hideGenreContextMenu() {
  $("genreContextMenu")?.classList.add("hidden");
}

function placeGenreContextMenu(clientX, clientY) {
  const menu = $("genreContextMenu");
  if (!menu) return;
  menu.classList.remove("hidden");
  const pad = 8;
  const rect = menu.getBoundingClientRect();
  let left = Number(clientX) || 12;
  let top = Number(clientY) || 12;
  const w = rect.width || 200;
  const h = rect.height || 160;
  if (left + w > window.innerWidth - pad) left = Math.max(pad, window.innerWidth - w - pad);
  if (top + h > window.innerHeight - pad) top = Math.max(pad, window.innerHeight - h - pad);
  menu.style.left = `${Math.round(left)}px`;
  menu.style.top = `${Math.round(top)}px`;
}

function getGenreMenuOptions(kind = "main") {
  const mode = getPurposeCategoryMode();
  if (mode === "none") return { title: i18n.t('app.장르'), options: [] };
  if (kind === "main") {
    if (mode === "translation") {
      return { title: i18n.t('app.원문_언어_선택'), options: WORK_LANGUAGES };
    }
    if (mode === "fairy_tale") {
      return { title: i18n.t('app.동화_대상_선택'), options: FAIRY_TALE_AUDIENCES };
    }
    return { title: i18n.t('app.메인_장르_선택'), options: MAIN_GENRES };
  }
  // sub
  if (mode === "translation") {
    return { title: i18n.t('app.번역문_언어_선택'), options: WORK_LANGUAGES };
  }
  if (mode === "fairy_tale") {
    return { title: i18n.t('app.세부'), options: [] };
  }
  const mainKey = $("mainGenreSelect")?.value || "";
  const listKey = isKnownMainGenre(mainKey) ? mainKey : (mainKey ? "other" : "");
  const baseSubs = SUB_GENRES[listKey] || [];
  const options = typeof withAdult19Option === "function"
    ? withAdult19Option(baseSubs)
    : baseSubs;
  return {
    title: mainKey ? i18n.t('app.서브_장르_선택') : i18n.t('app.먼저_메인_장르를_선택하세요'),
    options: listKey ? options : [],
  };
}

function showGenreContextMenu(kind, clientX, clientY) {
  hidePurposeContextMenu();
  const menu = $("genreContextMenu");
  const host = $("genreContextMenuItems");
  const labelEl = $("genreContextMenuLabel");
  if (!menu || !host) return;
  if (!state.projectId) {
    toast(i18n.t('app.작품을_먼저_선택해_주세요'));
    return;
  }
  const { title, options } = getGenreMenuOptions(kind);
  if (labelEl) labelEl.textContent = title;
  const select = kind === "main" ? $("mainGenreSelect") : $("subGenreSelect");
  const current = select?.value || "";
  const rows = [
    {
      key: "",
      label: kind === "main"
        ? (getPurposeCategoryMode() === "translation" ? i18n.t('app.원문_언어_미정') : i18n.t('app.메인_장르_미정'))
        : (getPurposeCategoryMode() === "translation" ? i18n.t('app.번역문_언어_미정') : i18n.t('app.서브_장르_미정')),
    },
    ...options,
  ];
  const mainHtml = rows.map((opt) => {
    const key = String(opt.key ?? "");
    const active = key === current ? " is-active" : "";
    return `<button type="button" role="menuitem" class="${active.trim()}" data-genre-kind="${escapeHtml(kind)}" data-genre-key="${escapeHtml(key)}">
      <strong>${escapeHtml(opt.label)}</strong>
    </button>`;
  }).join("");
  const detailOptions = getPurposeCategoryMode() === "fiction"
    ? genreDetailOptionsForMainSub(
      $("mainGenreSelect")?.value || state.mainGenre || "",
      $("subGenreSelect")?.value || state.subGenre || "",
    )
    : [];
  const currentDetail = $("genreDetailSelect")?.value || state.genreDetail || "";
  const detailHtml = detailOptions.length
    ? `<div class="context-menu-divider" role="separator"></div><div class="context-menu-label">${escapeHtml(i18n.t("app.세부_장르_선택"))}</div>`
      + detailOptions.map((opt) => {
        const key = String(opt.key ?? "");
        const active = key === currentDetail ? " is-active" : "";
        return `<button type="button" role="menuitem" class="${active.trim()}" data-genre-kind="detail" data-genre-key="${escapeHtml(key)}">
          <strong>${escapeHtml(opt.label)}</strong>
        </button>`;
      }).join("")
    : "";
  host.innerHTML = mainHtml + detailHtml;
  placeGenreContextMenu(clientX, clientY);
}

function applyMainGenreChoice(mainKey) {
  const mode = getPurposeCategoryMode();
  const select = $("mainGenreSelect");
  if (!select || !state.projectId) return;
  const next = String(mainKey || "");
  if (select.value === next) return;
  if (!confirmGenreChange()) return;

  select.value = next;
  state.mainGenre = next === "other" ? "other" : next;
  if (mode === "fairy_tale") {
    state.subGenre = "";
    state.genreDetail = "";
    fillSubGenreSelect("", "");
    fillGenreDetailSelect("", "", "");
    updateGenreCustomVisibility();
    syncGenreDisplayButtons();
    persistProjectGenre({ quiet: false }).catch(handleError);
    return;
  }
  if (mode === "translation") {
    const keepSub = state.subGenre || "";
    fillSubGenreSelect("lang", keepSub);
    fillGenreDetailSelect("", "", "");
    updateGenreCustomVisibility();
    syncGenreDisplayButtons();
    if (next === "other") {
      $("mainGenreCustom")?.focus();
      schedulePersistProjectGenre();
      return;
    }
    persistProjectGenre({ quiet: false }).catch(handleError);
    return;
  }
  // fiction
  state.subGenre = "";
  state.genreDetail = "";
  fillSubGenreSelect(next, "");
  fillGenreDetailSelect(next, "", "");
  updateGenreCustomVisibility();
  syncGenreDisplayButtons();
  if (next === "other") {
    $("mainGenreCustom")?.focus();
    schedulePersistProjectGenre();
    return;
  }
  persistProjectGenre({ quiet: false }).catch(handleError);
}

function applySubGenreChoice(subKey) {
  const select = $("subGenreSelect");
  if (!select || !state.projectId) return;
  const next = String(subKey || "");
  if (select.value === next) return;
  if (!confirmGenreChange()) return;

  select.value = next;
  state.subGenre = next === "other" ? "other" : next;
  const mainKey = $("mainGenreSelect")?.value || state.mainGenre || "";
  state.genreDetail = "";
  fillGenreDetailSelect(mainKey, next === "other" ? "other" : next, "");
  updateGenreCustomVisibility();
  syncGenreDisplayButtons();
  if (next === "other") {
    $("subGenreCustom")?.focus();
    schedulePersistProjectGenre();
    return;
  }
  persistProjectGenre({ quiet: false }).catch(handleError);
}

function applyGenreDetailChoice(detailKey) {
  if (!state.projectId) return;
  const mainKey = $("mainGenreSelect")?.value || state.mainGenre || "";
  const subKey = $("subGenreSelect")?.value || state.subGenre || "";
  const next = normalizeGenreDetailKey(mainKey, subKey, detailKey);
  if (state.genreDetail === next && ($("genreDetailSelect")?.value || "") === next) return;
  fillGenreDetailSelect(mainKey, subKey, next);
  syncGenreDisplayButtons();
  persistProjectGenre({ quiet: false }).catch(handleError);
}

function setupGenrePicker() {
  fillMainGenreSelect("");
  fillSubGenreSelect("", "");
  lockHeaderGenreSelects();
  updateGenreCustomVisibility();
  syncGenreDisplayButtons();

  // Native <select> stays hidden — changes come from right-click menu.
  const onCustomInput = () => {
    syncGenreDisplayButtons();
    schedulePersistProjectGenre();
  };
  $("mainGenreCustom")?.addEventListener("input", onCustomInput);
  $("subGenreCustom")?.addEventListener("input", onCustomInput);
  $("mainGenreCustom")?.addEventListener("change", () => persistProjectGenre({ quiet: true }).catch(handleError));
  $("subGenreCustom")?.addEventListener("change", () => persistProjectGenre({ quiet: true }).catch(handleError));

  const bindDisplay = (btnId, kind) => {
    const btn = $(btnId);
    if (!btn || btn.dataset.genreCtxBound === "1") return;
    btn.dataset.genreCtxBound = "1";
    btn.addEventListener("click", (event) => {
      event.preventDefault();
    });
    btn.addEventListener("contextmenu", (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (btn.disabled) return;
      showGenreContextMenu(kind, event.clientX, event.clientY);
    });
  };
  bindDisplay("mainGenreDisplay", "main");
  bindDisplay("subGenreDisplay", "sub");

  $("genreContextMenu")?.addEventListener("click", (event) => {
    const item = event.target.closest?.("[data-genre-kind]");
    if (!item) return;
    event.preventDefault();
    const kind = item.dataset.genreKind || "main";
    const key = item.dataset.genreKey ?? "";
    hideGenreContextMenu();
    if (kind === "detail") applyGenreDetailChoice(key);
    else if (kind === "sub") applySubGenreChoice(key);
    else applyMainGenreChoice(key);
  });
  document.addEventListener("click", (event) => {
    if (!event.target.closest?.("#genreContextMenu, #purposeContextMenu, #mainGenreDisplay, #subGenreDisplay, #purposeDisplay")) {
      hideGenreContextMenu();
      hidePurposeContextMenu();
    }
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      hideGenreContextMenu();
      hidePurposeContextMenu();
    }
  });

  syncGenrePickerFromState();
}

function projectOptionLabel(project) {
  // Title only — purpose is already shown in the adjacent 「종류」 picker.
  return String(project?.title || i18n.t('app.제목_없음')).trim() || i18n.t('app.제목_없음');
}

function normalizeKeywordList(raw) {
  let list = raw;
  if (typeof list === "string") {
    const text = list.trim();
    if (!text) return [];
    try {
      const parsed = JSON.parse(text);
      list = Array.isArray(parsed) ? parsed : text.split(/[,，/\n|]+/);
    } catch (_) {
      list = text.split(/[,，/\n|]+/);
    }
  }
  if (!Array.isArray(list)) return [];
  const out = [];
  const seen = new Set();
  for (const item of list) {
    const label = String(item || "").trim().slice(0, 40);
    if (!label || seen.has(label)) continue;
    seen.add(label);
    out.push(label);
    if (out.length >= KEYWORD_MAX) break;
  }
  return out;
}

function isKeywordSelected(label) {
  return state.keywords.includes(label);
}

function setKeywordPickerOpen(open) {
  const panel = $("keywordPickerPanel");
  const toggle = $("keywordPickerToggle");
  if (!panel) return;
  panel.classList.toggle("hidden", !open);
  if (toggle) toggle.setAttribute("aria-expanded", open ? "true" : "false");
  if (open) {
    if (usesKeywordPresetCatalog()) renderKeywordCatalog();
    // Ensure the keywords settings box is open so the picker is visible.
    if (state.openSettingsSection !== "keywords") {
      setOpenSettingsSection("keywords");
    }
    if (!usesKeywordPresetCatalog()) {
      window.setTimeout(() => $("keywordCustomInput")?.focus(), 0);
    }
  }
}

function shakeKeywordChip(label) {
  const cleaned = String(label || "").trim();
  if (!cleaned) return;
  document.querySelectorAll(`[data-keyword="${CSS.escape(cleaned)}"]`).forEach((chip) => {
    chip.classList.remove("is-shake");
    void chip.offsetWidth;
    chip.classList.add("is-shake");
    window.setTimeout(() => chip.classList.remove("is-shake"), 420);
  });
}

function keywordLabelMax() {
  return usesKeywordPresetCatalog() ? 40 : 15;
}

function syncKeywordClusterUi() {
  const presets = usesKeywordPresetCatalog();
  $("keywordBank")?.classList.toggle("is-keyword-custom-only", !presets);
  $("keywordBoard")?.classList.toggle("is-keyword-custom-only", !presets);
  $("keywordPickerPanel")?.classList.toggle("is-keyword-custom-only", !presets);

  const toggle = $("keywordPickerToggle");
  if (toggle) {
    toggle.textContent = presets ? i18n.t("app.키워드_버튼") : i18n.t("app.태그_추가");
    toggle.title = presets ? i18n.t("index.태그에서_고르기") : i18n.t("index.태그_직접_추가");
    toggle.setAttribute("data-i18n", presets ? "app.키워드_버튼" : "app.태그_추가");
    toggle.setAttribute("data-i18n-title", presets ? "index.태그에서_고르기" : "index.태그_직접_추가");
  }

  const hint = $("keywordsHint");
  if (hint) {
    hint.textContent = presets
      ? i18n.t("index.태그를_고르면_이_작품_키워드로_저장됩니다")
      : i18n.t("index.태그를_직접_입력하면_이_작품_키워드로_저장");
    hint.setAttribute(
      "data-i18n",
      presets ? "index.태그를_고르면_이_작품_키워드로_저장됩니다" : "index.태그를_직접_입력하면_이_작품_키워드로_저장",
    );
  }

  const boardHint = $("keywordBoardHint");
  if (boardHint) {
    boardHint.textContent = presets
      ? i18n.t("index.위에서_작품_종류_장르를_보고_바꾸고_아래에")
      : i18n.t("index.위에서_작품_종류_장르를_보고_바꾸고_태그를");
    boardHint.setAttribute(
      "data-i18n",
      presets ? "index.위에서_작품_종류_장르를_보고_바꾸고_아래에" : "index.위에서_작품_종류_장르를_보고_바꾸고_태그를",
    );
  }

  const pickerTitle = $("keywordPickerTitle") || document.querySelector("#keywordPickerPanel .keyword-picker-title");
  if (pickerTitle) {
    pickerTitle.textContent = presets ? i18n.t("index.태그_고르기") : i18n.t("index.태그_추가");
  }

  const maxLen = keywordLabelMax();
  ["keywordCustomInput", "keywordBoardCustomInput"].forEach((id) => {
    const input = $(id);
    if (input) input.maxLength = maxLen;
  });
}

function keywordChipsHtml() {
  if (!state.keywords.length) return "";
  return state.keywords
    .map((label) => `
      <span class="keyword-chip" data-keyword="${escapeHtml(label)}">
        <span class="keyword-chip-label">${escapeHtml(label)}</span>
        <button type="button" class="keyword-chip-remove" data-keyword-remove="${escapeHtml(label)}" title="${i18n.t('app.제거')}" aria-label="${escapeHtml(label)} 제거">×</button>
      </span>
    `)
    .join("");
}

function keywordCatalogHtml() {
  return KEYWORD_CATALOG.map((group) => `
    <div class="keyword-category" data-keyword-group="${escapeHtml(group.key)}">
      <span class="keyword-category-title">${escapeHtml(group.title)}</span>
      <div class="keyword-tag-list">
        ${group.tags.map((tag) => {
          const selected = isKeywordSelected(tag);
          return `<button type="button" class="keyword-tag${selected ? " is-selected" : ""}" data-keyword-tag="${escapeHtml(tag)}" aria-pressed="${selected ? "true" : "false"}">${escapeHtml(tag)}</button>`;
        }).join("")}
      </div>
    </div>
  `).join("");
}

function renderKeywordChips() {
  const html = keywordChipsHtml();
  for (const id of ["keywordChipList", "keywordBoardChipList"]) {
    const list = $(id);
    if (list) list.innerHTML = html;
  }
}

function renderKeywordCatalog() {
  const html = keywordCatalogHtml();
  for (const id of ["keywordCatalog", "keywordBoardCatalog"]) {
    const catalog = $(id);
    if (catalog) catalog.innerHTML = html;
  }
}

function renderKeywordBox() {
  syncKeywordClusterUi();
  renderKeywordChips();
  const panel = $("keywordPickerPanel");
  if (usesKeywordPresetCatalog() && ((panel && !panel.classList.contains("hidden")) || state.keywordBoardOpen)) {
    renderKeywordCatalog();
  }
}

function hideKeywordBoard() {
  state.keywordBoardOpen = false;
  placeGenreBlockForKeywordBoard(false);
  $("keywordBoard")?.classList.add("hidden");
}

function hideCenterViewsForKeywordBoard() {
  void flushCharacterAutoSave();
  $("welcome")?.classList.add("hidden");
  $("sceneWorkspace")?.classList.add("hidden");
  $("characterEditor")?.classList.add("hidden");
  hideItemViews();
  $("ideaBoard")?.classList.add("hidden");
  $("characterBoard")?.classList.add("hidden");
  hideRelationCanvas();
  hideGitsiWorkspace();
  hideSynopsisMain();
  hideSettingsCollectionBoard();
  hideSettingsSearchBoard();
  closeSceneToolsDrawer();
  void closeSplitView();
  $("keywordBoard")?.classList.remove("hidden");
}

function closeKeywordBoard() {
  hideKeywordBoard();
  return returnToManuscriptFromSettingsMain();
}

/** Move the single genre control block between settings accordion and keyword main board. */
function placeGenreBlockForKeywordBoard(onBoard) {
  const block = $("settingsGenreBlock");
  const boardMount = $("keywordBoardGenreMount");
  const settingsHost = $("keywordsBody");
  if (!block || !boardMount || !settingsHost) return;
  if (onBoard) {
    if (block.parentElement !== boardMount) boardMount.appendChild(block);
    block.classList.add("is-on-keyword-board");
  } else {
    if (block.parentElement !== settingsHost) {
      const first = settingsHost.firstElementChild;
      if (first) settingsHost.insertBefore(block, first);
      else settingsHost.appendChild(block);
    }
    block.classList.remove("is-on-keyword-board");
  }
}

function openKeywordBoard() {
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  if (typeof isGlumpSprintActive === "function" && isGlumpSprintActive() && !confirmLeaveGlumpSprint()) {
    return;
  }
  state.keywordBoardOpen = true;
  state.ideaBoardOpen = false;
  state.characterBoardOpen = false;
  setActiveBinder("settings");
  state.openSettingsSection = "keywords";
  applySettingsSectionState();
  hideCenterViewsForKeywordBoard();
  placeGenreBlockForKeywordBoard(true);
  renderKeywordBox();
}

function renderKeywordBoard() {
  if (!state.keywordBoardOpen) return;
  placeGenreBlockForKeywordBoard(true);
  renderKeywordBox();
}

let keywordPersistTimer = null;
function schedulePersistProjectKeywords() {
  if (keywordPersistTimer) window.clearTimeout(keywordPersistTimer);
  keywordPersistTimer = window.setTimeout(() => {
    persistProjectKeywords({ quiet: true }).catch(handleError);
  }, 350);
}

async function persistProjectKeywords({ quiet = true } = {}) {
  if (!state.projectId) return;
  const keywords = normalizeKeywordList(state.keywords);
  state.keywords = keywords;
  await api(`/api/projects/${state.projectId}/settings`, {
    method: "POST",
    body: JSON.stringify({ keywords }),
  });
  const project = state.projects.find((p) => p.id === state.projectId);
  if (project) project.keywords = [...keywords];
  if (!quiet) toast(i18n.t('app.키워드를_저장했습니다'));
}

function addProjectKeyword(label) {
  const cleaned = String(label || "").trim().slice(0, keywordLabelMax());
  if (!cleaned) return false;
  if (state.keywords.includes(cleaned)) {
    shakeKeywordChip(cleaned);
    toast(i18n.t("app.이미_있는_태그예요"));
    return false;
  }
  if (state.keywords.length >= KEYWORD_MAX) {
    toast(`${i18n.t('app.키워드는_최대_KEYWORD_MAX_개까지', {KEYWORD_MAX: KEYWORD_MAX})}`);
    return false;
  }
  state.keywords = [...state.keywords, cleaned];
  renderKeywordBox();
  schedulePersistProjectKeywords();
  return true;
}

function removeProjectKeyword(label) {
  const cleaned = String(label || "").trim();
  if (!cleaned) return;
  state.keywords = state.keywords.filter((item) => item !== cleaned);
  renderKeywordBox();
  schedulePersistProjectKeywords();
}

function toggleProjectKeyword(label) {
  if (isKeywordSelected(label)) removeProjectKeyword(label);
  else addProjectKeyword(label);
}

function setupKeywordBox() {
  const toggle = $("keywordPickerToggle");
  const closeBtn = $("keywordPickerClose");
  const catalog = $("keywordCatalog");
  const chips = $("keywordChipList");
  const customInput = $("keywordCustomInput");
  const customAdd = $("keywordCustomAdd");
  const boardCatalog = $("keywordBoardCatalog");
  const boardChips = $("keywordBoardChipList");
  const boardCustomInput = $("keywordBoardCustomInput");
  const boardCustomAdd = $("keywordBoardCustomAdd");

  toggle?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (!state.projectId) {
      toast(i18n.t('app.먼저_작품을_선택해_주세요'));
      return;
    }
    const panel = $("keywordPickerPanel");
    const open = Boolean(panel?.classList.contains("hidden"));
    setKeywordPickerOpen(open);
  });
  closeBtn?.addEventListener("click", (event) => {
    event.preventDefault();
    setKeywordPickerOpen(false);
  });
  $("keywordBoardCloseButton")?.addEventListener("click", () => closeKeywordBoard().catch(handleError));

  const onCatalogClick = (event) => {
    const btn = event.target.closest?.("[data-keyword-tag]");
    if (!btn || !state.projectId) return;
    event.preventDefault();
    toggleProjectKeyword(btn.getAttribute("data-keyword-tag") || "");
  };
  catalog?.addEventListener("click", onCatalogClick);
  boardCatalog?.addEventListener("click", onCatalogClick);

  const onChipsClick = (event) => {
    const btn = event.target.closest?.("[data-keyword-remove]");
    if (!btn || !state.projectId) return;
    event.preventDefault();
    event.stopPropagation();
    removeProjectKeyword(btn.getAttribute("data-keyword-remove") || "");
  };
  chips?.addEventListener("click", onChipsClick);
  boardChips?.addEventListener("click", onChipsClick);

  const bindCustomCommit = (input, addBtn) => {
    const commitCustom = () => {
      if (!state.projectId) {
        toast(i18n.t('app.먼저_작품을_선택해_주세요'));
        return;
      }
      const value = input?.value || "";
      if (addProjectKeyword(value) && input) input.value = "";
    };
    addBtn?.addEventListener("click", (event) => {
      event.preventDefault();
      commitCustom();
    });
    input?.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        commitCustom();
      }
    });
  };
  bindCustomCommit(customInput, customAdd);
  bindCustomCommit(boardCustomInput, boardCustomAdd);

  renderKeywordBox();
}

function fillPurposeSelect(selected = "general_novel") {
  const select = $("purposeSelect");
  if (!select) return;
  const keys = Object.keys(purposeLabel);
  const value = normalizePurposeKey(selected);
  select.innerHTML = keys
    .map((key) => `<option value="${escapeHtml(key)}">${escapeHtml(purposeLabel[key])}</option>`)
    .join("");
  select.value = keys.includes(value) ? value : "general_novel";
  select.disabled = true;
  select.setAttribute("aria-hidden", "true");
  select.tabIndex = -1;
  select.classList.add("genre-select-hidden");
}

function syncPurposeDisplayButton() {
  const select = $("purposeSelect");
  const btn = $("purposeDisplay");
  if (!btn) return;
  const hasProject = Boolean(state.projectId);
  const opt = select?.selectedOptions?.[0];
  const label = (opt && opt.value)
    ? String(opt.textContent || "").trim()
    : (purposeLabel[normalizePurposeKey(state.projectPurpose)] || i18n.t('app.작품_종류'));
  btn.textContent = label || i18n.t('app.작품_종류');
  btn.disabled = !hasProject;
  btn.title = hasProject ? i18n.t('app.우클릭_작품_종류_변경') : i18n.t('app.작품을_먼저_선택해_주세요_2');
}

function syncPurposePickerFromState() {
  const select = $("purposeSelect");
  if (!select) return;
  const purpose = normalizePurposeKey(
    state.projectPurpose
    || state.projects.find((p) => p.id === state.projectId)?.purpose
    || "general_novel",
  );
  fillPurposeSelect(purpose);
  syncPurposeDisplayButton();
}

function hidePurposeContextMenu() {
  $("purposeContextMenu")?.classList.add("hidden");
}

function placePurposeContextMenu(clientX, clientY) {
  const menu = $("purposeContextMenu");
  if (!menu) return;
  menu.classList.remove("hidden");
  const pad = 8;
  const rect = menu.getBoundingClientRect();
  let left = Number(clientX) || 12;
  let top = Number(clientY) || 12;
  const w = rect.width || 200;
  const h = rect.height || 160;
  if (left + w > window.innerWidth - pad) left = Math.max(pad, window.innerWidth - w - pad);
  if (top + h > window.innerHeight - pad) top = Math.max(pad, window.innerHeight - h - pad);
  menu.style.left = `${Math.round(left)}px`;
  menu.style.top = `${Math.round(top)}px`;
}

function showPurposeContextMenu(clientX, clientY) {
  const host = $("purposeContextMenuItems");
  const menu = $("purposeContextMenu");
  if (!host || !menu) return;
  hideGenreContextMenu();
  const current = normalizePurposeKey($("purposeSelect")?.value || state.projectPurpose || "general_novel");
  host.innerHTML = Object.keys(purposeLabel).map((key) => {
    const active = key === current ? " is-active" : "";
    return `<button type="button" role="menuitem" class="${active.trim()}" data-purpose-key="${escapeHtml(key)}"><strong>${escapeHtml(purposeLabel[key])}</strong></button>`;
  }).join("");
  placePurposeContextMenu(clientX, clientY);
}

function applyPurposeChoice(nextRaw) {
  if (!state.projectId) return;
  const prevPurpose = normalizePurposeKey(state.projectPurpose);
  const prevMode = getPurposeCategoryMode(prevPurpose);
  const nextPurpose = normalizePurposeKey(nextRaw || "general_novel");
  const nextMode = getPurposeCategoryMode(nextPurpose);
  if (nextPurpose === prevPurpose) return;
  if (!confirmGenreChange()) {
    syncPurposePickerFromState();
    return;
  }
  state.projectPurpose = nextPurpose;
  if (prevMode !== nextMode || nextMode === "none") {
    state.mainGenre = "";
    state.subGenre = "";
    state.genreDetail = "";
  }
  fillPurposeSelect(nextPurpose);
  syncPurposeDisplayButton();
  syncGenrePickerFromState();
  persistProjectPurpose({ quiet: false })
    .then(async () => {
      if (prevMode !== nextMode || nextMode === "none") {
        await persistProjectGenre({ quiet: true });
      }
      syncGenrePickerFromState();
    })
    .catch((error) => {
      state.projectPurpose = prevPurpose;
      syncPurposePickerFromState();
      syncGenrePickerFromState();
      handleError(error);
    });
}

function setupPurposePicker() {
  fillPurposeSelect("general_novel");
  syncPurposeDisplayButton();

  const btn = $("purposeDisplay");
  if (btn && btn.dataset.purposeCtxBound !== "1") {
    btn.dataset.purposeCtxBound = "1";
    btn.addEventListener("click", (event) => {
      event.preventDefault();
    });
    btn.addEventListener("contextmenu", (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (btn.disabled) return;
      showPurposeContextMenu(event.clientX, event.clientY);
    });
  }

  $("purposeContextMenu")?.addEventListener("click", (event) => {
    const item = event.target.closest?.("[data-purpose-key]");
    if (!item) return;
    event.preventDefault();
    hidePurposeContextMenu();
    applyPurposeChoice(item.dataset.purposeKey);
  });

  syncPurposePickerFromState();
  syncGenrePickerFromState();
}

function refreshProjectSelectOptions() {
  const select = $("projectSelect");
  if (!select || !state.projects.length) return;
  const current = state.projectId;
  select.innerHTML = state.projects
    .map((project) => `<option value="${project.id}">${escapeHtml(projectOptionLabel(project))}</option>`)
    .join("");
  if (current) select.value = String(current);
}

function applyProjectsListPayload(projects, listMode = null) {
  state.projects = Array.isArray(projects) ? projects : [];
  if (listMode === "recent" || listMode === "manual") {
    state.projectListMode = listMode;
  } else if (state.projects[0]?.list_mode === "recent" || state.projects[0]?.list_mode === "manual") {
    state.projectListMode = state.projects[0].list_mode;
  }
  refreshProjectSelectOptions();
}

function bumpOpenedProjectInLocalList(projectId, lastOpenedAt = null) {
  const id = Number(projectId);
  if (!Number.isFinite(id) || !state.projects.length) return;
  const idx = state.projects.findIndex((p) => Number(p.id) === id);
  if (idx < 0) return;
  const item = state.projects[idx];
  if (lastOpenedAt) item.last_opened_at = lastOpenedAt;
  if (state.projectListMode !== "recent") {
    refreshProjectSelectOptions();
    return;
  }
  if (idx === 0) {
    refreshProjectSelectOptions();
    return;
  }
  state.projects.splice(idx, 1);
  state.projects.unshift(item);
  refreshProjectSelectOptions();
}

async function markProjectOpened(projectId = state.projectId) {
  const id = Number(projectId);
  if (!Number.isFinite(id) || id <= 0) return;
  try {
    const result = await api(`/api/projects/${id}/touch-open`, {
      method: "POST",
      body: "{}",
    });
    if (result?.list_mode === "recent" || result?.list_mode === "manual") {
      state.projectListMode = result.list_mode;
    }
    bumpOpenedProjectInLocalList(id, result?.last_opened_at || null);
    const title = state.projects.find((project) => Number(project.id) === id)?.title || "";
    try {
      await api(`/api/projects/${id}/checkout`, {
        method: "POST",
        body: JSON.stringify({ title }),
      });
    } catch (error) {
      console.warn("[supertory] project checkout failed", error);
    }
    await refreshMobileDraftsBanner(id);
  } catch (_) {
    // Opening must not fail because of list bookkeeping.
  }
}

let mobileDraftItems = [];
const ignoredMobileDraftIds = new Set();

function visibleMobileDrafts() {
  return (mobileDraftItems || []).filter((item) => !ignoredMobileDraftIds.has(String(item.draft_id)));
}

function draftConflictsWithDesktop(draft) {
  const based = Number(draft?.based_on_revision_no);
  const current = Number(draft?.revision_no);
  if (!Number.isFinite(based) || !Number.isFinite(current)) return false;
  return based !== current;
}

function hideMobileDraftBanner() {
  $("mobileDraftBanner")?.classList.add("hidden");
}

function updateMobileDraftBanner() {
  const banner = $("mobileDraftBanner");
  const text = $("mobileDraftBannerText");
  if (!banner || !text) return;
  const items = visibleMobileDrafts();
  if (!items.length) {
    banner.classList.add("hidden");
    return;
  }
  text.textContent = i18n.t("app.폰에서_쓴_초안이_n개_있어요", { n: items.length });
  banner.classList.remove("hidden");
}

async function refreshMobileDraftsBanner(projectId = state.projectId) {
  const id = Number(projectId);
  ignoredMobileDraftIds.clear();
  mobileDraftItems = [];
  hideMobileDraftBanner();
  if (!Number.isFinite(id) || id <= 0) return;
  try {
    const drafts = await api(`/api/projects/${id}/mobile-drafts`);
    mobileDraftItems = Array.isArray(drafts) ? drafts : [];
  } catch (error) {
    console.warn("[supertory] mobile drafts fetch failed", error);
    mobileDraftItems = [];
  }
  updateMobileDraftBanner();
}

function closeMobileDraftModal() {
  $("mobileDraftModal")?.classList.add("hidden");
}

function renderMobileDraftList() {
  const list = $("mobileDraftList");
  if (!list) return;
  const items = visibleMobileDrafts();
  if (!items.length) {
    list.innerHTML = `<p class="hint">${escapeHtml(i18n.t("app.확인할_초안이_없어요"))}</p>`;
    return;
  }
  list.innerHTML = items.map((item) => {
    const preview = String(item.content || "").replace(/\s+/g, " ").trim().slice(0, 200);
    const when = item.created_at ? formatLocalTimeFromIso(item.created_at) : "";
    const datePart = String(item.created_at || "").slice(0, 10);
    const conflict = draftConflictsWithDesktop(item)
      ? `<p class="mobile-draft-conflict">${escapeHtml(i18n.t("app.그_사이_데스크탑에서도_수정됐어요"))}</p>`
      : "";
    const draftId = escapeHtml(String(item.draft_id));
    return `
      <article class="mobile-draft-item" data-draft-id="${draftId}">
        <div class="mobile-draft-item-head">
          <strong>${escapeHtml(item.title || i18n.t("app.제목_없음"))}</strong>
          <span>${escapeHtml(datePart)} ${escapeHtml(when)}</span>
        </div>
        <p class="mobile-draft-preview">${escapeHtml(preview || "")}</p>
        ${conflict}
        <div class="mobile-draft-item-actions">
          <button type="button" class="primary compact-btn" data-draft-merge="${draftId}">${escapeHtml(i18n.t("app.반영하기"))}</button>
          <button type="button" class="secondary compact-btn" data-draft-ignore="${draftId}">${escapeHtml(i18n.t("app.무시하기"))}</button>
        </div>
      </article>
    `;
  }).join("");
}

function openMobileDraftModal() {
  const modal = $("mobileDraftModal");
  if (!modal) return;
  renderMobileDraftList();
  modal.classList.remove("hidden");
}

function ignoreMobileDraft(draftId) {
  ignoredMobileDraftIds.add(String(draftId));
  updateMobileDraftBanner();
  renderMobileDraftList();
  if (!visibleMobileDrafts().length) closeMobileDraftModal();
}

async function mergeMobileDraft(draftId) {
  const draft = mobileDraftItems.find((item) => String(item.draft_id) === String(draftId));
  if (!draft) return;
  await api(`/api/scene-drafts/${encodeURIComponent(String(draft.draft_id))}/merge`, {
    method: "POST",
    body: JSON.stringify({
      local_scene_id: draft.local_scene_id,
      content: draft.content || "",
    }),
  });
  mobileDraftItems = mobileDraftItems.filter((item) => String(item.draft_id) !== String(draftId));
  updateMobileDraftBanner();
  renderMobileDraftList();
  toast(i18n.t("app.초안을_반영했어요"));
  if (Number(state.sceneId) === Number(draft.local_scene_id)) {
    await openScene(draft.local_scene_id, { keepBinder: true });
  }
  if (!visibleMobileDrafts().length) closeMobileDraftModal();
}

function setupMobileDraftUi() {
  const bannerReview = $("mobileDraftBannerReview");
  bannerReview?.addEventListener("click", () => openMobileDraftModal());
  document.querySelectorAll("[data-close-mobile-drafts]").forEach((el) => {
    el.addEventListener("click", (event) => {
      event.preventDefault();
      closeMobileDraftModal();
    });
  });
  $("mobileDraftList")?.addEventListener("click", (event) => {
    const mergeBtn = event.target.closest?.("[data-draft-merge]");
    if (mergeBtn) {
      mergeMobileDraft(mergeBtn.getAttribute("data-draft-merge")).catch(handleError);
      return;
    }
    const ignoreBtn = event.target.closest?.("[data-draft-ignore]");
    if (ignoreBtn) {
      ignoreMobileDraft(ignoreBtn.getAttribute("data-draft-ignore"));
    }
  });
}

function postProjectCheckinKeepalive(projectId) {
  const id = Number(projectId);
  if (!Number.isFinite(id) || id <= 0) return;
  const url = `/api/projects/${id}/checkin`;
  try {
    if (typeof navigator !== "undefined" && typeof navigator.sendBeacon === "function") {
      const blob = new Blob(["{}"], { type: "application/json" });
      if (navigator.sendBeacon(url, blob)) return;
    }
  } catch (_) {
    /* fall through to fetch */
  }
  try {
    fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: "{}",
      keepalive: true,
    }).catch(() => {});
  } catch (_) {
    /* ignore */
  }
}

async function persistProjectListOrder(projectIds, { toastMessage = "" } = {}) {
  const result = await api("/api/projects/reorder", {
    method: "PUT",
    body: JSON.stringify({ project_ids: projectIds }),
  });
  applyProjectsListPayload(result?.projects || [], result?.list_mode || "manual");
  if (state.projectId) {
    const select = $("projectSelect");
    if (select) select.value = String(state.projectId);
  }
  if (toastMessage) toast(toastMessage);
  return result;
}

async function setProjectListMode(mode, { toastMessage = "" } = {}) {
  const result = await api("/api/projects/list-mode", {
    method: "PUT",
    body: JSON.stringify({ mode }),
  });
  applyProjectsListPayload(result?.projects || [], result?.list_mode || mode);
  if (state.projectId) {
    const select = $("projectSelect");
    if (select) select.value = String(state.projectId);
  }
  if (toastMessage) toast(toastMessage);
  return result;
}

async function moveProjectInList(direction) {
  if (!state.projects.length || !state.projectId) {
    toast(i18n.t('app.옮길_작품이_없어요'));
    return;
  }
  const ids = state.projects.map((p) => Number(p.id));
  const idx = ids.indexOf(Number(state.projectId));
  if (idx < 0) return;
  let next = idx;
  if (direction === "up") next = Math.max(0, idx - 1);
  else if (direction === "down") next = Math.min(ids.length - 1, idx + 1);
  else if (direction === "top") next = 0;
  else if (direction === "bottom") next = ids.length - 1;
  else return;
  if (next === idx) {
    toast(direction === "up" || direction === "top" ? i18n.t('app.이미_맨_위예요') : i18n.t('app.이미_맨_아래예요'));
    return;
  }
  const reordered = ids.slice();
  const [moved] = reordered.splice(idx, 1);
  reordered.splice(next, 0, moved);
  const labels = {
    up: i18n.t('app.작품을_한_칸_위로_옮겼어요'),
    down: i18n.t('app.작품을_한_칸_아래로_옮겼어요'),
    top: i18n.t('app.작품을_맨_위로_옮겼어요'),
    bottom: i18n.t('app.작품을_맨_아래로_옮겼어요'),
  };
  await persistProjectListOrder(reordered, { toastMessage: labels[direction] || i18n.t('app.작품_순서를_바꿨어요') });
}

function setupProjectListContextMenu() {
  const select = $("projectSelect");
  if (!select || select.dataset.projectListMenuBound === "1") return;
  select.dataset.projectListMenuBound = "1";
  select.addEventListener("contextmenu", (event) => {
    if (!state.projects.length) return;
    event.preventDefault();
    event.stopPropagation();
    const items = [
      {
        label: i18n.t('app.한_칸_위로'),
        hint: i18n.t('app.목록에서_현재_작품_이동'),
        run: () => { moveProjectInList("up").catch(handleError); },
      },
      {
        label: i18n.t('app.한_칸_아래로'),
        hint: i18n.t('app.목록에서_현재_작품_이동'),
        run: () => { moveProjectInList("down").catch(handleError); },
      },
      {
        label: i18n.t('app.맨_위로'),
        hint: i18n.t('app.목록_맨_앞'),
        run: () => { moveProjectInList("top").catch(handleError); },
      },
      {
        label: i18n.t('app.맨_아래로'),
        hint: i18n.t('app.목록_맨_끝'),
        run: () => { moveProjectInList("bottom").catch(handleError); },
      },
    ];
    if (state.projectListMode === "manual") {
      items.push({
        label: i18n.t('app.최근_작업순으로_정렬'),
        hint: i18n.t('app.시스템_기본값으로_되돌리기'),
        run: () => {
          setProjectListMode("recent", { toastMessage: i18n.t('app.최근_작업한_작품_순서로_정렬했어요') })
            .catch(handleError);
        },
      });
    }
    if (typeof showUiFeatureContextMenu === "function") {
      showUiFeatureContextMenu(event.clientX, event.clientY, select, items);
    }
  });
}

async function persistProjectPurpose({ quiet = true } = {}) {
  if (!state.projectId) return;
  const select = $("purposeSelect");
  const purpose = normalizePurposeKey(select?.value || state.projectPurpose || "general_novel");
  const clusterId = inferClusterId(purpose, state.mainGenre, state.subGenre);
  const result = await api(`/api/projects/${state.projectId}/settings`, {
    method: "POST",
    body: JSON.stringify({ purpose, cluster_id: clusterId }),
  });
  const next = normalizePurposeKey(result?.purpose || purpose);
  state.projectPurpose = next;
  state.clusterId = result?.cluster_id || clusterId;
  const project = state.projects.find((p) => p.id === state.projectId);
  if (project) {
    project.purpose = next;
    project.cluster_id = state.clusterId;
  }
  refreshProjectSelectOptions();
  if (typeof renderSettingsCodex === "function") {
    try { renderSettingsCodex(); } catch (_) { /* ignore */ }
  }
  try { applyClusterFeatureGating(); } catch (_) { /* ignore */ }
  if (!quiet) toast(`${i18n.t('app.작품_종류를_purposeLabel_next', {'purposeLabel[next] || next': purposeLabel[next] || next})}`);
}

function preferredProjectFromUrl() {
  const params = new URLSearchParams(window.location.search);
  const raw = params.get("project");
  if (!raw) return null;
  const id = Number(raw);
  return Number.isFinite(id) ? id : null;
}

/* Remember last project + scene so relaunch opens the previous working screen. */
const LAST_WORKSPACE_KEY = "supertory.lastWorkspace";

function loadLastWorkspace() {
  try {
    const raw = localStorage.getItem(LAST_WORKSPACE_KEY);
    const obj = raw ? JSON.parse(raw) : null;
    if (!obj || typeof obj !== "object") return null;
    const projectId = Number(obj.projectId);
    const sceneId = obj.sceneId == null || obj.sceneId === "" ? null : Number(obj.sceneId);
    return {
      projectId: Number.isFinite(projectId) && projectId > 0 ? projectId : null,
      sceneId: Number.isFinite(sceneId) && sceneId > 0 ? sceneId : null,
    };
  } catch (_) {
    return null;
  }
}

function saveLastWorkspace(overrides = {}) {
  try {
    const projectId = overrides.projectId !== undefined ? overrides.projectId : state.projectId;
    const sceneId = overrides.sceneId !== undefined ? overrides.sceneId : state.sceneId;
    const pid = Number(projectId);
    if (!Number.isFinite(pid) || pid <= 0) return;
    const sid = Number(sceneId);
    localStorage.setItem(LAST_WORKSPACE_KEY, JSON.stringify({
      projectId: pid,
      sceneId: Number.isFinite(sid) && sid > 0 ? sid : null,
      at: Date.now(),
    }));
  } catch (_) {
    /* ignore quota / private mode */
  }
}

function sceneExistsInCurrentOutline(sceneId) {
  const id = Number(sceneId);
  if (!Number.isFinite(id) || id <= 0) return false;
  if (typeof allScenes === "function") {
    return allScenes().some((scene) => Number(scene.id) === id);
  }
  for (const chapter of state.outline || []) {
    for (const scene of flattenChapterScenes(chapter)) {
      if (Number(scene.id) === id) return true;
    }
  }
  return false;
}

/** After a project loads at startup, reopen the last scene (or welcome). */
async function restoreLastWorkspaceView() {
  const last = loadLastWorkspace();
  if (!state.projectId) {
    showWelcome();
    return;
  }
  let sceneId = last && Number(last.projectId) === Number(state.projectId)
    ? last.sceneId
    : null;
  // Upgrade path: before lastWorkspace existed, episode tabs still remember open scenes.
  if (!sceneId && Array.isArray(state.episodeTabs) && state.episodeTabs.length) {
    const tabId = Number(state.episodeTabs[state.episodeTabs.length - 1]?.sceneId);
    if (sceneExistsInCurrentOutline(tabId)) sceneId = tabId;
  }
  if (sceneId && sceneExistsInCurrentOutline(sceneId)) {
    try {
      await openScene(sceneId);
      return;
    } catch (_) {
      /* fall through to welcome */
    }
  }
  showWelcome();
}

async function loadProjects(preferredId = null) {
  const projects = await api("/api/projects");
  applyProjectsListPayload(projects);
  const select = $("projectSelect");
  if (!state.projects.length) {
    select.innerHTML = i18n.t('app.option_아직_만든_작품이_없어요_op');
  }
  const fromUrl = preferredProjectFromUrl();
  const last = loadLastWorkspace();
  // URL / 명시 선호 ID → 직전 작업 작품 → 목록 첫 작품(최근 작업 또는 수동 1번)
  const chosen = preferredId || fromUrl || last?.projectId || state.projects[0]?.id || null;
  state.projectId = chosen && state.projects.some((project) => project.id === Number(chosen))
    ? Number(chosen)
    : (state.projects[0]?.id || null);
  if (state.projectId) {
    select.value = state.projectId;
    loadEpisodeTabsFromStorage();
    await loadProject();
    try {
      if (
        typeof openTranslationWorkspace === "function"
        && (translationWorkspaceState.hashOpenPending || window.location.hash === "#translation-workspace")
        && typeof isTranslationWorkspaceUnlocked === "function"
        && isTranslationWorkspaceUnlocked()
      ) {
        translationWorkspaceState.hashOpenPending = false;
        openTranslationWorkspace({ quiet: true });
      }
    } catch (_) { /* ignore */ }
    // 새 작품 생성 직후(preferredId)는 호출측이 씬을 열 수 있으므로 복원하지 않음.
    // URL로 특정 작품을 연 경우·일반 기동에서는 마지막 화면을 복원.
    if (!preferredId) {
      await restoreLastWorkspaceView();
    }
    if (fromUrl && Number(fromUrl) === state.projectId) {
      const project = state.projects.find((item) => item.id === state.projectId);
      if (project?.package_name || project?.package_path) {
        const name = project.package_name || String(project.package_path).split(/[/\\]/).pop();
        toast(`${i18n.t('app.작품_파일에서_열었어요_name', {name: name})}`);
      }
    }
  } else {
    showWelcome();
  }
}

async function loadProject() {
  if (!state.projectId) return;
  const projectIdAtStart = state.projectId;
  if (translationWorkspaceBelongsToOtherProject(projectIdAtStart)) {
    detachTranslationWorkspaceForProjectChange();
  }
  const [outline, characters, ideas, items] = await Promise.all([
    api(`/api/projects/${state.projectId}/outline`),
    api(`/api/projects/${state.projectId}/characters`),
    api(`/api/projects/${state.projectId}/ideas`),
    api(`/api/projects/${state.projectId}/items`).catch(() => []),
  ]);
  // Ignore stale responses if the user switched works mid-flight.
  if (state.projectId !== projectIdAtStart) return;
  state.characters = characters;
  state.items = Array.isArray(items) ? items : [];
  state.outline = outline.chapters || [];
  state.parts = Array.isArray(outline.parts) ? outline.parts : [];
  state.ungroupedChapters = Array.isArray(outline.ungrouped_chapters)
    ? outline.ungrouped_chapters
    : (state.parts.length ? [] : (state.outline || []));
  state.folders = Array.isArray(outline.folders) ? outline.folders : [];
  state.forceFoldersOutline = readForceFoldersOutline(projectIdAtStart);
  state.outlineProjectId = projectIdAtStart;
  // Drop cached episode HTML from the previous work.
  if (typeof clearViewerEpisodeCache === "function") clearViewerEpisodeCache();
  state.ideas = ideas;
  try {
    const localPins = loadLocalIdeaPins();
    if (localPins && typeof localPins === "object") {
      state.ideas = state.ideas.map((idea) => {
        if (Boolean(Number(idea?.is_pinned))) return idea;
        if (localPins[String(idea.id)]) return { ...idea, is_pinned: 1 };
        return idea;
      });
    }
  } catch (_) {
    /* ignore */
  }
  // 떡밥: localStorage → DB 마이그레이션 후 목록 로드 (캐시 채움)
  if (typeof refreshBaitsFromServer === "function") {
    try {
      await refreshBaitsFromServer(projectIdAtStart);
    } catch (baitErr) {
      console.warn(i18n.t('app.떡밥_목록을_불러오지_못했어요'), baitErr);
      state.baits = [];
    }
  }
  if (state.projectId !== projectIdAtStart) return;
  state.readerSessions = loadReaderChatSessions(projectIdAtStart);
  state.synopsisMd = outline.project?.synopsis_md || outline.project?.description_md || "";
  state.loglineMd = outline.project?.logline_md || "";
  state.introMd = outline.project?.intro_md || "";
  state.intentMd = outline.project?.intent_md || "";
  state.worldbuildingMd = outline.project?.worldbuilding_md || "";
  state.worldToriAnalysis = outline.project?.world_tori_analysis && typeof outline.project.world_tori_analysis === "object"
    ? outline.project.world_tori_analysis
    : {};
  seedWorldBuildingExamplesIfEmpty();
  syncWorldToriBadges();
  state.projectPurpose = normalizePurposeKey(
    outline.project?.purpose || state.projects.find((p) => p.id === state.projectId)?.purpose || "general_novel",
  );
  // Keep episode tabs valid for this outline.
  renderEpisodeChrome();
  const fromList = state.projects.find((p) => p.id === state.projectId);
  if (fromList && outline.project?.purpose) fromList.purpose = outline.project.purpose;
  state.toryPriorityMd = outline.project?.tory_priority_md || fromList?.tory_priority_md || "";
  if (fromList) fromList.tory_priority_md = state.toryPriorityMd;
  syncToryPriorityInput();
  state.outlineSummary = outline.project?.outline_summary || fromList?.outline_summary || "";
  if (fromList) fromList.outline_summary = state.outlineSummary;
  syncOutlineSummaryInput();
  // 흥행 공식 참고: project.linked_success_profile_id
  {
    const rawLink = outline.project?.linked_success_profile_id ?? fromList?.linked_success_profile_id;
    let linkId = null;
    if (rawLink != null && rawLink !== "" && rawLink !== 0 && rawLink !== "0") {
      const n = Number(rawLink);
      if (Number.isFinite(n) && n > 0) linkId = n;
    }
    state.linkedSuccessProfileId = linkId;
    if (fromList) fromList.linked_success_profile_id = linkId;
    state.linkedSuccessProfile = null;
    if (linkId) {
      try {
        await ensureLinkedSuccessProfile();
      } catch (_) {
        state.linkedSuccessProfile = null;
      }
    }
    if (typeof updateSuccessProfileRefUi === "function") updateSuccessProfileRefUi();
    if (typeof updateToryChatSuccessUi === "function") updateToryChatSuccessUi();
    if (typeof renderLinkedSuccessProfileCard === "function") {
      renderLinkedSuccessProfileCard().catch(() => {});
    }
  }
  state.mainGenre = outline.project?.main_genre || fromList?.main_genre || "";
  state.subGenre = outline.project?.sub_genre || fromList?.sub_genre || "";
  state.genreDetail = outline.project?.genre_detail || fromList?.genre_detail || "";
  state.clusterId = inferClusterId(
    state.projectPurpose || outline.project?.purpose || fromList?.purpose,
    state.mainGenre,
    state.subGenre,
    outline.project?.cluster_id || fromList?.cluster_id,
  );
  if (fromList) fromList.cluster_id = state.clusterId;
  state.keywords = normalizeKeywordList(
    outline.project?.keywords ?? fromList?.keywords ?? [],
  );
  if (fromList) fromList.keywords = [...state.keywords];
  syncPurposePickerFromState();
  syncGenrePickerFromState();
  refreshProjectSelectOptions();
  renderOutline(outline.chapters);
  renderCharacters();
  renderItems();
  renderIdeaBank();
  renderKeywordBox();
  // Settings accordion open state is per work.
  restoreOpenSettingsSection(projectIdAtStart);
  renderSettingsCodex();
  try { applyClusterFeatureGating(); } catch (_) { /* ignore */ }
  $("newChapterButton").disabled = false;
  if ($("renumberChaptersButton")) $("renumberChaptersButton").disabled = false;
  $("newCharacterButton").disabled = false;
  if ($("newItemButton")) $("newItemButton").disabled = false;
  $("newIdeaButton").disabled = false;
  // U4: binder undo button from server stack (don't await — keep loadProject snappy)
  refreshFolderUndoHintFromServer().catch(() => {});
  // Project-level goal + full-manuscript footer stats.
  if (outline.project?.goal_word_count != null) {
    state.projectGoalCount = Math.max(0, Number(outline.project.goal_word_count) || 0);
  } else {
    const fromList = state.projects.find((p) => p.id === state.projectId);
    state.projectGoalCount = Math.max(0, Number(fromList?.goal_word_count || 0) || 0);
  }
  syncProjectGoalFromState();
  syncStatsScopeUi();
  scheduleProjectManuscriptStats();
  updateSceneStats();
  if (typeof renderToryChatMessages === "function") renderToryChatMessages();
  if (typeof renderToryNotifyList === "function") renderToryNotifyList();
  // Record open time for recent-first list (manual mode keeps fixed order).
  markProjectOpened(projectIdAtStart).catch(() => {});
  if (typeof checkReadingInviteFeedback === "function") {
    checkReadingInviteFeedback().catch(() => {});
  }
}

function previewLines(text, count = 2) {
  const lines = String(text || "")
    .replace(/\r\n/g, "\n")
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
  if (!lines.length) return [];
  return lines.slice(0, count);
}

function renderPreviewElement(element, lines, emptyText) {
  if (!element) return;
  if (!lines.length) {
    element.innerHTML = `<span class="preview-empty">${escapeHtml(emptyText)}</span>`;
    return;
  }
  element.innerHTML = lines
    .map((line) => `<span class="preview-line">${escapeHtml(line)}</span>`)
    .join("");
}

function renderSettingsCodex() {
  // Ideas preview: first two sticky titles/bodies as two lines.
  const ideaLines = [];
  for (const idea of state.ideas) {
    if (ideaLines.length >= 2) break;
    const title = String(idea.title || "").trim();
    const body = String(idea.body_md || "").replace(/\s+/g, " ").trim();
    ideaLines.push(title || body || i18n.t('app.빈_메모'));
  }
  renderPreviewElement($("ideasPreview"), ideaLines, i18n.t('app.아직_메모가_없어요'));

  const baits = loadBaits();
  const baitLines = baits.slice(0, 2).map((bait) => {
    const head = (bait.summary || bait.quote || i18n.t('app.떡밥')).replace(/\s+/g, " ").trim();
    const recover = bait.recoverAt ? ` · 회수 ${bait.recoverAt}` : "";
    return `${head.slice(0, 42)}${head.length > 42 ? "…" : ""}${recover}`;
  });
  renderPreviewElement(
    $("baitsPreview"),
    baitLines,
    i18n.t('app.본문_드래그_우클릭_떡밥_던지기'),
  );
  renderBaitList();
  if (typeof renderToryNotifyList === "function") renderToryNotifyList();
  if (typeof renderLinkedSuccessProfileCard === "function") {
    renderLinkedSuccessProfileCard().catch(() => {});
  }

  // Previews hidden by CSS; keep sync for any future use.
  renderPreviewElement($("introPreview"), [], i18n.t('app.작품소개_기획의도'));
  renderPreviewElement($("logsynPreview"), [], i18n.t('app.로그라인_시놉시스'));
  {
    const purposeLabel = ($("purposeDisplay")?.textContent || "").trim();
    const mainLabel = state.mainGenre ? mainGenreLabel(state.mainGenre) : "";
    const subLabel = state.subGenre ? subGenreLabel(state.mainGenre, state.subGenre) : "";
    const genreBits = [purposeLabel, mainLabel, subLabel]
      .map((s) => String(s || "").trim())
      .filter((s) => s && s !== i18n.t('app.미정'));
    const genreLine = genreBits.length ? genreBits.join(" · ") : "";
    const kwLine = state.keywords.length ? state.keywords.slice(0, 6).join(" · ") : "";
    const previewLinesKw = [genreLine, kwLine].filter(Boolean);
    renderPreviewElement(
      $("keywordsPreview"),
      previewLinesKw,
      i18n.t('app.장르_키워드를_정해_보세요_더블클릭_또는'),
    );
  }
  renderKeywordBox();
  renderPreviewElement(
    $("worldPreview"),
    previewLines(
      looksLikeHtml(state.worldbuildingMd) ? plainTextFromHtml(state.worldbuildingMd) : state.worldbuildingMd,
      2,
    ),
    i18n.t('app.세계관을_적어_보세요_더블클릭_또는'),
  );

  // Characters: name + first line, in order (up to 2 entries for the 2-line preview)
  const characterLines = [];
  for (const character of state.characters) {
    if (characterLines.length >= 2) break;
    const name = String(character.name || i18n.t('app.이름_없음')).trim();
    const first = String(character.short_description || "").trim()
      || String(character.profile_md || "").split(/\n/).map((l) => l.trim()).find(Boolean)
      || "";
    characterLines.push(first ? `${name} — ${first}` : name);
  }
  renderPreviewElement($("charactersPreview"), characterLines, i18n.t('app.아직_인물이_없어요_더블클릭_또는'));

  const itemLines = [];
  for (const item of (state.items || [])) {
    if (itemLines.length >= 2) break;
    const name = String(item.name || i18n.t('app.이름_없음')).trim();
    const first = String(item.description || "").replace(/\s+/g, " ").trim();
    itemLines.push(first ? `${name} — ${first}` : name);
  }
  renderPreviewElement($("itemsPreview"), itemLines, i18n.t('app.아직_아이템이_없어요_더블클릭_또는'));

  const sources = loadSources();
  const sourceLines = sources.slice(0, 2).map((src) => {
    const head = String(src.title || i18n.t('app.자료')).replace(/\s+/g, " ").trim();
    return head.length > 48 ? `${head.slice(0, 48)}…` : head;
  });
  renderPreviewElement(
    $("sourcesPreview"),
    sourceLines,
    i18n.t('app.참고_책_기사_영상_출처를_모아_두세요'),
  );
  renderSourceList();
  renderToryVaultList();
  renderPreviewElement(
    $("readingInvitePreview"),
    [i18n.t("app.완성된_화를_베타_리더에게_링크로")],
    i18n.t("app.완성된_화를_베타_리더에게_링크로"),
  );

  if (!isSettingsDocMainOpen()) {
    syncSettingsDocSidebarFromState("intro");
    syncSettingsDocSidebarFromState("intent");
    syncSettingsDocSidebarFromState("synopsis");
    syncSettingsDocSidebarFromState("logline");
    syncSettingsDocSidebarFromState("world");
  } else {
    // Keep inactive sidebars in sync while editing one main doc.
    for (const kind of ["intro", "intent", "synopsis", "logline", "world"]) {
      if (kind !== state.settingsDocKind) syncSettingsDocSidebarFromState(kind);
    }
  }

  applySettingsSectionOrder();
  applySettingsSectionState();
  if (state.characterBoardOpen) renderCharacterBoard();
  if (state.relationCanvasOpen) paintRelationCanvas();
  if (state.itemBoardOpen) renderItemBoard();
  renderBookmarkBar();
  markBookmarkedTargets();
}

/** Per-project key for which settings accordion section is open. */
function openSettingsSectionStorageKey(projectId = state.projectId) {
  const id = Number(projectId);
  if (!Number.isFinite(id) || id <= 0) return null;
  return `supertory.openSettingsSection.${id}`;
}

function normalizeOpenSettingsSectionKey(raw) {
  const key = String(raw || "").trim();
  if (!key) return null;
  if (key === "synopsis" || key === "logline") return "logsyn";
  return key;
}

/**
 * Restore open settings folder for one work.
 * Migrates legacy global key once into this project, then removes the global key
 * so other works stay closed by default.
 */
function restoreOpenSettingsSection(projectId = state.projectId) {
  state.openSettingsSection = null;
  const storageKey = openSettingsSectionStorageKey(projectId);
  if (!storageKey) return;
  try {
    let stored = localStorage.getItem(storageKey);
    if (stored == null) {
      const legacy = localStorage.getItem("supertory.openSettingsSection");
      if (legacy != null && legacy !== "") {
        localStorage.setItem(storageKey, legacy);
        localStorage.removeItem("supertory.openSettingsSection");
        stored = legacy;
      }
    }
    state.openSettingsSection = normalizeOpenSettingsSectionKey(stored || "");
  } catch (_) {
    state.openSettingsSection = null;
  }
}

function persistOpenSettingsSection(projectId = state.projectId) {
  const storageKey = openSettingsSectionStorageKey(projectId);
  if (!storageKey) return;
  try {
    localStorage.setItem(storageKey, state.openSettingsSection || "");
  } catch (_) {
    /* ignore */
  }
}

function applySettingsSectionState() {
  const openKey = state.openSettingsSection;
  document.querySelectorAll(".settings-box").forEach((box) => {
    const key = box.dataset.settingsSection;
    const isOpen = Boolean(openKey && key === openKey);
    box.classList.toggle("is-open", isOpen);
    const toggle = box.querySelector("[data-settings-toggle]");
    const body = box.querySelector(".settings-box-body");
    if (toggle) toggle.setAttribute("aria-expanded", isOpen ? "true" : "false");
    if (body) {
      // Prefer class-driven display; keep hidden attribute for accessibility only.
      if (isOpen) {
        body.removeAttribute("hidden");
        body.hidden = false;
      } else {
        body.setAttribute("hidden", "");
        body.hidden = true;
      }
      body.style.removeProperty("display");
      body.style.removeProperty("height");
      body.style.removeProperty("max-height");
      body.style.removeProperty("overflow");
    }
    // Never let flex layout crush open content.
    box.style.flex = "0 0 auto";
    box.style.flexShrink = "0";
    box.style.height = "auto";
    box.style.maxHeight = "none";
    box.style.overflow = "visible";
  });
  // Remember open folder per work (not global across all projects).
  persistOpenSettingsSection();
  // After layout: grow textareas to full content height (scrollHeight needs display≠none).
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      if (!openKey) return;
      const openBox = document.querySelector(`.settings-box.is-open[data-settings-section="${openKey}"]`);
      const body = openBox?.querySelector(".settings-box-body");
      if (!body) return;
      const snap = snapshotOverflowScroll(body);
      body.querySelectorAll("textarea").forEach((ta) => autoResizeSettingsSidebarTextarea(ta, { preserve: false }));
      restoreOverflowScroll(snap);
    });
  });
}

function setOpenSettingsSection(sectionKey) {
  state.openSettingsSection = state.openSettingsSection === sectionKey ? null : sectionKey;
  if (state.openSettingsSection) setActiveBinder("settings");
  applySettingsSectionState();
  // 키워드 박스를 열면 태그 피커도 바로 펼침
  if (state.openSettingsSection === "keywords" && state.projectId) {
    setKeywordPickerOpen(true);
  } else if (typeof setKeywordPickerOpen === "function") {
    setKeywordPickerOpen(false);
  }
  if (state.openSettingsSection === "readingInvite" && state.projectId) {
    refreshReadingInvitePanel().catch(handleError);
  }
}

function getSettingsDocMeta(kind) {
  return SETTINGS_DOC_META[kind] || SETTINGS_DOC_META.synopsis;
}

const SETTINGS_DOC_TO_SECTION = {
  intro: "intro",
  intent: "intro",
  synopsis: "logsyn",
  logline: "logsyn",
  world: "world",
};

const SETTINGS_DOC_SIBLINGS = {
  intro: ["intro", "intent"],
  intent: ["intro", "intent"],
  synopsis: ["logline", "synopsis"],
  logline: ["logline", "synopsis"],
  world: ["world"],
};

function pullSettingsDocFromSidebar(kind) {
  const meta = getSettingsDocMeta(kind);
  if (kind === "world" && $("worldbuildingForm")) {
    // 메인으로 열거나 저장할 때는 예제 초안도 확정한다.
    return pushWorldBuildingFormToState({ commitDraft: true });
  }
  const el = $(meta.sidebarId);
  if (!el) return state[meta.stateKey] || "";
  const value = el.value || "";
  state[meta.stateKey] = value;
  return value;
}

function pullSettingsDocFamilyFromSidebar(kind) {
  const family = SETTINGS_DOC_SIBLINGS[kind] || [kind];
  for (const k of family) pullSettingsDocFromSidebar(k);
}

function getSettingsDocTextForSave(kind = state.settingsDocKind || "synopsis") {
  const meta = getSettingsDocMeta(kind);
  if (kind === "world" && ($("worldbuildingForm") || $("worldbuildingMainForm"))) {
    const formFocused = Boolean(
      document.activeElement?.closest?.("#worldbuildingMainForm, #worldbuildingForm"),
    );
    if (formFocused) return pushWorldBuildingFormToState({ commitDraft: true });
    if (worldbuildingExampleDraft) return state.worldbuildingMd || "";
    return pushWorldBuildingFormToState({ commitDraft: true });
  }
  const sidebar = $(meta.sidebarId);
  const mainEditor = isSynopsisWorkspaceOpen() ? getSettingsDocMainEditor(kind) : null;
  if (sidebar && document.activeElement === sidebar) {
    return sidebar.value || "";
  }
  if (mainEditor) {
    return getEditorContent(mainEditor);
  }
  if (sidebar) return sidebar.value || "";
  return state[meta.stateKey] || "";
}

function snapshotOverflowScroll(fromEl) {
  const saved = [];
  for (let n = fromEl; n && n.nodeType === 1; n = n.parentElement) {
    saved.push({ n, top: n.scrollTop, left: n.scrollLeft });
  }
  return { saved, winX: window.scrollX, winY: window.scrollY };
}

function restoreOverflowScroll(snap) {
  if (!snap) return;
  for (const { n, top, left } of snap.saved) {
    if (n.scrollTop !== top) n.scrollTop = top;
    if (n.scrollLeft !== left) n.scrollLeft = left;
  }
  if (window.scrollX !== snap.winX || window.scrollY !== snap.winY) {
    window.scrollTo(snap.winX, snap.winY);
  }
}

function autoResizeSettingsSidebarTextarea(el, options = {}) {
  if (!el || el.tagName !== "TEXTAREA") return;
  el.style.overflowY = "hidden";
  const minPx = 64;
  const extra = 2;
  const allowShrink = options.shrink !== false;
  const preserve = options.preserve !== false;

  // Grow in place. Collapsing to 0px first makes fields below jump up and
  // resets the settings/worldbuilding scroll parent to the top.
  if (el.scrollHeight > el.clientHeight + 1) {
    el.style.height = `${Math.max(minPx, el.scrollHeight + extra)}px`;
    return;
  }
  if (!allowShrink) return;

  const snap = preserve ? snapshotOverflowScroll(el) : null;
  el.style.height = "0px";
  const next = Math.max(minPx, el.scrollHeight + extra);
  el.style.height = `${next}px`;
  if (preserve) restoreOverflowScroll(snap);
}

function syncSettingsDocSidebarFromState(kind) {
  const meta = getSettingsDocMeta(kind);
  if (kind === "world" && ($("worldbuildingForm") || $("worldbuildingMainForm"))) {
    const formFocused = Boolean(
      document.activeElement?.closest?.("#worldbuildingMainForm, #worldbuildingForm"),
    );
    if (formFocused) return;
    syncWorldBuildingFormFromState({ force: false });
    return;
  }
  const el = $(meta.sidebarId);
  if (!el || document.activeElement === el) return;
  const raw = state[meta.stateKey] || "";
  el.value = looksLikeHtml(raw) ? plainTextFromHtml(raw) : raw;
  autoResizeSettingsSidebarTextarea(el);
}

/** Push current state into main editor when it shows the same settings doc. */
function syncSettingsDocMainFromState(kind, { force = false } = {}) {
  if (!isSettingsDocMainOpen()) return;
  if (kind === "world") {
    if (state.settingsDocKind !== "world") return;
    if (!force) {
      const focused = document.activeElement?.closest?.("#worldbuildingMainForm [data-world-field]");
      if (focused) return;
    }
    syncWorldBuildingFormFromState({ force: true });
    return;
  }
  const editor = getSettingsDocMainEditor(kind);
  if (!editor) return;
  if (!force && document.activeElement === editor) return;
  const raw = state[getSettingsDocMeta(kind).stateKey] || "";
  suppressSynopsisDirty = true;
  setEditorContent(raw, editor);
  suppressSynopsisDirty = false;
}

function syncSynopsisSidebarFromState() {
  syncSettingsDocSidebarFromState("synopsis");
}

let synopsisDirty = false;
let synopsisAutoSaveTimer = null;
let synopsisAutoSaveInFlight = false;
let suppressSynopsisDirty = false;
/** Per-kind pending autosave so concurrent fields don't drop saves. */
const settingsDocPending = Object.create(null);

function setSynopsisSaveStatus(text) {
  if ($("synopsisSaveInfo")) $("synopsisSaveInfo").textContent = text;
  if (state.settingsDocKind === "world") setWorldbuildingSaveStatus(text);
}

function markSynopsisDirty(kind = null) {
  if (suppressSynopsisDirty || !state.projectId) return;
  const saveKind = kind
    || state.settingsDocFocusKind
    || state.settingsDocKind
    || "synopsis";
  synopsisDirty = true;
  setSynopsisSaveStatus(i18n.t('app.저장_대기_중'));
  if (synopsisAutoSaveTimer) window.clearTimeout(synopsisAutoSaveTimer);
  synopsisAutoSaveTimer = window.setTimeout(() => {
    persistSettingsDoc(saveKind, { quiet: true }).catch(handleError);
  }, 1200);
}

function markSettingsDocEditorDirty(editor) {
  const kind = editor?.dataset?.settingsDocKind
    || state.settingsDocFocusKind
    || state.settingsDocKind
    || "synopsis";
  if (editor) {
    lastSettingsDocEditor = editor;
    state.settingsDocFocusKind = kind;
  }
  markSynopsisDirty(kind);
}

function scheduleSettingsDocAutoSave(kind) {
  if (!state.projectId || !kind) return;
  if (settingsDocPending[kind]) window.clearTimeout(settingsDocPending[kind]);
  settingsDocPending[kind] = window.setTimeout(() => {
    settingsDocPending[kind] = null;
    persistSettingsDoc(kind, { quiet: true }).catch(handleError);
  }, 900);
}

async function persistSettingsDoc(kind, options = {}) {
  const quiet = Boolean(options.quiet);
  const meta = getSettingsDocMeta(kind);
  if (!state.projectId) {
    if (!quiet) toast(i18n.t('app.먼저_작품을_선택해_주세요'));
    return null;
  }
  // Wait briefly if another save is in flight (avoid dropping manual save).
  if (synopsisAutoSaveInFlight) {
    if (quiet) {
      scheduleSettingsDocAutoSave(kind);
      return null;
    }
    for (let i = 0; i < 40 && synopsisAutoSaveInFlight; i += 1) {
      await new Promise((r) => window.setTimeout(r, 50));
    }
  }
  synopsisAutoSaveInFlight = true;
  if (quiet) setSynopsisSaveStatus(i18n.t('app.자동_저장_중'));
  try {
    // Always take latest from DOM/state right before request.
    const value = getSettingsDocTextForSave(kind);
    state[meta.stateKey] = value;
    const result = await api(`/api/projects/${state.projectId}/settings`, {
      method: "PUT",
      body: JSON.stringify({ [meta.apiField]: value }),
    });
    const saved = result[meta.apiField] != null ? result[meta.apiField] : value;
    state[meta.stateKey] = saved;
    // Keep other fields from API if returned.
    if (result.synopsis_md != null && kind !== "synopsis") state.synopsisMd = result.synopsis_md;
    if (result.logline_md != null && kind !== "logline") state.loglineMd = result.logline_md;
    if (result.intro_md != null && kind !== "intro") state.introMd = result.intro_md;
    if (result.intent_md != null && kind !== "intent") state.intentMd = result.intent_md;
    if (result.worldbuilding_md != null && kind !== "world") state.worldbuildingMd = result.worldbuilding_md;
    if (state.settingsDocKind === kind || getSettingsDocMainEditor(kind)) synopsisDirty = false;
    const stamp = new Date().toLocaleTimeString("ko-KR", { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    setSynopsisSaveStatus(quiet ? `${i18n.t('app.자동_저장됨_stamp', {stamp: stamp})}` : `${i18n.t('app.저장됨_stamp', {stamp: stamp})}`);
    // Sync the other surface (sidebar ↔ main) without clobbering the focused control.
    syncSettingsDocSidebarFromState(kind);
    // Refresh main pane when it is editing this same document — but never
    // while the user is actively typing in it: force-overwriting innerHTML
    // mid-edit resets the caret (it kept jumping to the top every autosave
    // cycle). syncSettingsDocMainFromState() already skips the focused
    // editor by default, so only unfocused panes get the canonical refresh.
    if (getSettingsDocMainEditor(kind)) {
      syncSettingsDocMainFromState(kind);
    }
    if (!quiet) toast(`${i18n.t('app.meta_toastLabel_을_를_저장했', {'meta.toastLabel': meta.toastLabel})}`);
    return result;
  } catch (error) {
    if (quiet) {
      setSynopsisSaveStatus(i18n.t('app.자동_저장_실패_다시_시도'));
      scheduleSettingsDocAutoSave(kind);
    }
    throw error;
  } finally {
    synopsisAutoSaveInFlight = false;
  }
}

async function persistSynopsis(options = {}) {
  return persistSettingsDoc(state.settingsDocKind || "synopsis", options);
}

async function saveProjectSynopsis() {
  await persistSettingsDoc("synopsis", { quiet: false });
}

async function saveProjectLogline() {
  await persistSettingsDoc("logline", { quiet: false });
}

async function saveProjectWorldbuilding() {
  await persistSettingsDoc("world", { quiet: false });
}

async function persistSettingsDocPair(kinds, options = {}) {
  const list = (kinds || []).filter(Boolean);
  let last = null;
  for (const k of list) {
    last = await persistSettingsDoc(k, options);
  }
  return last;
}

function pendingSettingsDocKinds() {
  const kinds = new Set();
  if (synopsisDirty) {
    if (state.settingsDocPair?.length) {
      state.settingsDocPair.forEach((k) => kinds.add(k));
    } else {
      kinds.add(state.settingsDocFocusKind || state.settingsDocKind || "synopsis");
    }
  }
  if (synopsisAutoSaveTimer) {
    window.clearTimeout(synopsisAutoSaveTimer);
    synopsisAutoSaveTimer = null;
    kinds.add(state.settingsDocFocusKind || state.settingsDocKind || "synopsis");
  }
  Object.keys(SETTINGS_DOC_META).forEach((kind) => {
    if (settingsDocPending[kind]) {
      window.clearTimeout(settingsDocPending[kind]);
      settingsDocPending[kind] = null;
      kinds.add(kind);
    }
  });
  return [...kinds];
}

async function flushPendingSettingsDocs() {
  const kinds = pendingSettingsDocKinds();
  for (const kind of kinds) {
    try {
      await persistSettingsDoc(kind, { quiet: true });
    } catch (_) {
      /* keep pending retry via persistSettingsDoc */
    }
  }
}

async function flushPendingCodexSaves() {
  const tasks = [
    flushCharacterAutoSave().catch(() => {}),
    flushPendingSettingsDocs(),
    flushIdeaCardAutosaves().catch(() => {}),
  ];
  if (typeof outlineSummarySaveTimer !== "undefined" && outlineSummarySaveTimer) {
    window.clearTimeout(outlineSummarySaveTimer);
    outlineSummarySaveTimer = null;
    tasks.push(persistOutlineSummary({ quiet: true }).catch(() => {}));
  }
  if (typeof toryPrioritySaveTimer !== "undefined" && toryPrioritySaveTimer) {
    window.clearTimeout(toryPrioritySaveTimer);
    toryPrioritySaveTimer = null;
    tasks.push(persistToryPriority({ quiet: true }).catch(() => {}));
  }
  await Promise.all(tasks);
}

function hideSynopsisMain() {
  $("synopsisWorkspace")?.classList.add("hidden");
  $("worldbuildingWorkspace")?.classList.add("hidden");
  document.querySelector(".synopsis-writing-column")?.classList.remove("is-dual");
  const a = $("synopsisContent");
  const b = $("synopsisContentB");
  if (a) delete a.dataset.settingsDocKind;
  if (b) delete b.dataset.settingsDocKind;
  state.settingsDocKind = null;
  state.settingsDocPair = null;
  state.settingsDocFocusKind = null;
  lastSettingsDocEditor = null;
}

function hideRelationCanvas() {
  state.relationCanvasOpen = false;
  exitRelationCanvasFullscreen();
  $("relationCanvas")?.classList.add("hidden");
  hideRelationPopups();
}

function hideCharacterBoard() {
  state.characterBoardOpen = false;
  $("characterBoard")?.classList.add("hidden");
}

function hideItemBoard() {
  state.itemBoardOpen = false;
  $("itemBoard")?.classList.add("hidden");
}

function hideSettingsSearchBoard() {
  state.settingsSearchOpen = false;
  $("settingsSearchBoard")?.classList.add("hidden");
}

let settingsSearchTimer = 0;
let settingsSearchToken = 0;
let settingsSearchBound = false;

function settingsSearchHighlight(text, query) {
  const raw = String(text || "");
  const needle = String(query || "").trim();
  if (!raw) return "";
  if (!needle) return escapeHtml(raw);
  const lower = raw.toLowerCase();
  const idx = lower.indexOf(needle.toLowerCase());
  if (idx < 0) return escapeHtml(raw);
  return (
    escapeHtml(raw.slice(0, idx))
    + "<mark>" + escapeHtml(raw.slice(idx, idx + needle.length)) + "</mark>"
    + escapeHtml(raw.slice(idx + needle.length))
  );
}

function settingsSearchHitButton(hit, query) {
  const type = String(hit?.type || "");
  const title = escapeHtml(hit?.title || "");
  const field = escapeHtml(hit?.field_label || hit?.field || "");
  const snippet = settingsSearchHighlight(hit?.snippet || "", query);
  const attrs = [
    "type=\"button\"",
    "class=\"settings-search-hit\"",
    `data-search-type="${escapeHtml(type)}"`,
    `data-search-id="${escapeHtml(String(hit?.id ?? ""))}"`,
  ];
  if (type === "world") {
    attrs.push(`data-search-field="${escapeHtml(String(hit.field || hit.id || ""))}"`);
  }
  if (type === "relation") {
    attrs.push(`data-search-a="${escapeHtml(String(hit.character_a_id || ""))}"`);
    attrs.push(`data-search-b="${escapeHtml(String(hit.character_b_id || ""))}"`);
  }
  return `<button ${attrs.join(" ")}><span class="settings-search-hit-title">${title}</span><span class="settings-search-hit-field">${field}</span><span class="settings-search-hit-snippet">${snippet}</span></button>`;
}

function renderSettingsSearchResults(payload, query) {
  const root = $("settingsSearchResults");
  if (!root) return;
  const q = String(query || "").trim();
  if (!q) {
    root.innerHTML = `<p class="hint settings-search-empty">${escapeHtml(i18n.t("index.캐릭터_아이템_세계관_관계를_한_번에_찾아요"))}</p>`;
    return;
  }
  const groups = [
    { key: "characters", title: i18n.t("app.캐릭터") },
    { key: "items", title: i18n.t("app.아이템") },
    { key: "world", title: i18n.t("app.세계관") },
    { key: "relations", title: i18n.t("app.관계_이어보기") },
  ];
  let total = 0;
  const html = groups.map((group) => {
    const hits = Array.isArray(payload?.[group.key]) ? payload[group.key] : [];
    total += hits.length;
    if (!hits.length) return "";
    return `<section class="settings-search-group"><h3 class="settings-search-group-title">${escapeHtml(group.title)} <span>${hits.length}</span></h3><div class="settings-search-group-list">${hits.map((hit) => settingsSearchHitButton(hit, q)).join("")}</div></section>`;
  }).join("");
  root.innerHTML = total
    ? html
    : `<p class="hint settings-search-empty">${escapeHtml(i18n.t("app.일치하는_설정이_없어요"))}</p>`;
  root.querySelectorAll("[data-search-type]").forEach((button) => {
    button.addEventListener("click", () => openSettingsSearchHit(button).catch(handleError));
  });
}

async function openSettingsSearchHit(button) {
  const type = button.getAttribute("data-search-type") || "";
  const id = button.getAttribute("data-search-id") || "";
  if (type === "character") {
    await openCharacter(id);
    return;
  }
  if (type === "item") {
    await openItem(id);
    return;
  }
  if (type === "world") {
    await openSettingsDocMain("world", {
      worldField: button.getAttribute("data-search-field") || id,
    });
    return;
  }
  if (type === "relation") {
    await openRelationCanvas({
      characterAId: Number(button.getAttribute("data-search-a")),
      characterBId: Number(button.getAttribute("data-search-b")),
    });
  }
}

async function runSettingsSearch(rawQuery) {
  const query = String(rawQuery || "").trim();
  const token = ++settingsSearchToken;
  if (!query) {
    renderSettingsSearchResults({}, "");
    return;
  }
  if (!state.projectId) {
    toast(i18n.t("app.먼저_작품을_선택해_주세요"));
    return;
  }
  const payload = await api(
    `/api/projects/${state.projectId}/settings-search?q=${encodeURIComponent(query)}`,
  );
  if (token !== settingsSearchToken) return;
  renderSettingsSearchResults(payload, query);
}

function scheduleSettingsSearch() {
  window.clearTimeout(settingsSearchTimer);
  settingsSearchTimer = window.setTimeout(() => {
    runSettingsSearch($("settingsSearchInput")?.value || "").catch(handleError);
  }, 300);
}

async function openSettingsSearchBoard() {
  if (!state.projectId) return toast(i18n.t("app.먼저_작품을_선택해_주세요"));
  if (typeof isGlumpSprintActive === "function" && isGlumpSprintActive() && !confirmLeaveGlumpSprint()) {
    return;
  }
  try { await flushCharacterAutoSave(); } catch (_) { /* continue */ }
  try { await flushItemAutoSave(); } catch (_) { /* continue */ }
  if (sceneDirty && state.sceneId) {
    try { await persistScene({ quiet: true, saveNote: i18n.t("app.자동_저장") }); } catch (_) { /* continue */ }
  }
  setActiveBinder("settings");
  state.settingsSearchOpen = true;
  state.characterBoardOpen = false;
  state.itemBoardOpen = false;
  state.ideaBoardOpen = false;
  state.keywordBoardOpen = false;
  hideKeywordBoard();
  hideCharacterBoard();
  hideRelationCanvas();
  hideItemViews();
  hideSynopsisMain();
  hideSettingsCollectionBoard();
  hideGitsiWorkspace();
  $("welcome")?.classList.add("hidden");
  $("ideaBoard")?.classList.add("hidden");
  $("keywordBoard")?.classList.add("hidden");
  $("sceneWorkspace")?.classList.add("hidden");
  $("characterEditor")?.classList.add("hidden");
  closeSceneToolsDrawer();
  await closeSplitView().catch(() => {});
  $("settingsSearchBoard")?.classList.remove("hidden");
  const input = $("settingsSearchInput");
  try { input?.focus({ preventScroll: true }); } catch (_) { input?.focus(); }
  if (String(input?.value || "").trim()) {
    runSettingsSearch(input.value).catch(handleError);
  } else {
    renderSettingsSearchResults({}, "");
  }
}

async function closeSettingsSearchBoard() {
  hideSettingsSearchBoard();
  await returnToManuscriptFromSettingsMain();
}

function bindSettingsSearchEvents() {
  if (settingsSearchBound) return;
  settingsSearchBound = true;
  $("openSettingsSearchButton")?.addEventListener("click", () => openSettingsSearchBoard().catch(handleError));
  $("closeSettingsSearchButton")?.addEventListener("click", () => closeSettingsSearchBoard().catch(handleError));
  $("settingsSearchInput")?.addEventListener("input", scheduleSettingsSearch);
  $("settingsSearchInput")?.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      closeSettingsSearchBoard().catch(handleError);
    }
  });
}

function hideItemViews() {
  hideItemBoard();
  $("itemEditor")?.classList.add("hidden");
}

function lastSceneIdForSettingsClose() {
  const current = Number(state.sceneId);
  if (Number.isFinite(current) && current > 0) return current;
  try {
    const last = typeof loadLastWorkspace === "function" ? loadLastWorkspace() : null;
    if (last && Number(last.projectId) === Number(state.projectId)) {
      const sid = Number(last.sceneId);
      if (Number.isFinite(sid) && sid > 0) return sid;
    }
  } catch (_) {
    /* ignore */
  }
  const tabs = state.episodeTabs || [];
  const tabId = Number(tabs[tabs.length - 1]?.sceneId);
  return Number.isFinite(tabId) && tabId > 0 ? tabId : 0;
}

/** 설정집 메인 닫기: 왼쪽 바인더는 유지하고, 가운데는 본문 작성 화면으로. */
async function returnToManuscriptFromSettingsMain() {
  try {
    await flushPendingCodexSaves();
  } catch (_) {
    /* still leave the settings main pane */
  }
  hideKeywordBoard();
  hideCharacterBoard();
  hideRelationCanvas();
  hideItemViews();
  hideSynopsisMain();
  hideSettingsCollectionBoard();
  hideGitsiWorkspace();
  hideSettingsSearchBoard();
  state.ideaBoardOpen = false;
  $("ideaBoard")?.classList.add("hidden");
  $("characterEditor")?.classList.add("hidden");
  $("itemEditor")?.classList.add("hidden");
  $("welcome")?.classList.add("hidden");

  const sceneId = lastSceneIdForSettingsClose();
  if (sceneId && Number(state.sceneId) === sceneId && state.scene) {
    showSceneEditorPane();
    return;
  }
  if (sceneId) {
    await openScene(sceneId, { keepBinder: true, keepCharacter: true });
    return;
  }
  showWelcome();
}

async function closeSynopsisMain() {
  const pair = state.settingsDocPair?.length
    ? state.settingsDocPair
    : (state.settingsDocKind ? [state.settingsDocKind] : []);
  if (synopsisDirty && pair.length) {
    try {
      await persistSettingsDocPair(pair, { quiet: true });
    } catch (_) {
      /* ignore */
    }
  }
  hideSynopsisMain();
  await returnToManuscriptFromSettingsMain();
}

function applySettingsDocChrome(kind) {
  const pair = getSettingsDocPairKinds(kind);
  const pairChrome = SETTINGS_DOC_PAIR_CHROME[kind];
  const meta = getSettingsDocMeta(kind);
  const title = pairChrome?.title || meta.title;
  const hint = pairChrome?.hint || meta.hint;
  if ($("settingsDocMainTitle")) $("settingsDocMainTitle").textContent = title;
  if ($("settingsDocMainHint")) $("settingsDocMainHint").textContent = hint;

  const column = document.querySelector(".synopsis-writing-column");
  column?.classList.toggle("is-dual", pair.length >= 2);

  const editors = [$("synopsisContent"), $("synopsisContentB")];
  const titles = [$("settingsDocPaneTitleA"), $("settingsDocPaneTitleB")];
  pair.forEach((k, i) => {
    const m = getSettingsDocMeta(k);
    if (titles[i]) titles[i].textContent = m.title;
    if (editors[i]) {
      editors[i].dataset.settingsDocKind = k;
      editors[i].setAttribute("aria-label", m.title);
      editors[i].dataset.placeholder = m.placeholder;
      updateEditorPlaceholder?.(editors[i]);
    }
  });
  // Hide unused second pane only if somehow single (should not happen for these docs).
  const paneB = document.querySelector('[data-settings-pane="b"]');
  if (paneB) paneB.classList.toggle("hidden", pair.length < 2);

  const pane = $("synopsisWorkspace");
  if (pane) {
    pane.dataset.settingsDoc = kind;
    pane.setAttribute("aria-label", `${i18n.t('app.title_편집', {title: title})}`);
  }
}

async function openSettingsDocMain(kind = "synopsis", options = {}) {
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  if (typeof isGlumpSprintActive === "function" && isGlumpSprintActive() && !confirmLeaveGlumpSprint()) {
    return;
  }
  try {
    await flushCharacterAutoSave();
  } catch (_) {
    /* continue */
  }
  if (!SETTINGS_DOC_META[kind]) kind = "synopsis";

  const pair = getSettingsDocPairKinds(kind);
  const prevPair = Array.isArray(state.settingsDocPair) ? state.settingsDocPair : [];
  const samePairOpen = isSynopsisWorkspaceOpen()
    && pair.length >= 2
    && prevPair.length >= 2
    && pair[0] === prevPair[0]
    && pair[1] === prevPair[1];

  // Always pull sibling textareas first so logline/intent aren't left only in the DOM.
  pullSettingsDocFamilyFromSidebar(kind);

  // Flush previous settings docs if switching away from another pair/doc.
  if (isSettingsDocMainOpen() && !samePairOpen) {
    const flushKinds = prevPair.length
      ? prevPair
      : (state.settingsDocKind ? [state.settingsDocKind] : []);
    for (const k of flushKinds) {
      if (pair.includes(k)) continue;
      try {
        await persistSettingsDoc(k, { quiet: true });
      } catch (_) {
        /* continue */
      }
    }
  }
  // Flush the target kind (and siblings) so main opens with saved content.
  if (!samePairOpen) {
    for (const k of pair) {
      try {
        await persistSettingsDoc(k, { quiet: true });
      } catch (_) {
        /* continue */
      }
    }
  }

  if (sceneDirty && state.sceneId) {
    try {
      await persistScene({ quiet: true, saveNote: i18n.t('app.자동_저장') });
    } catch (_) {
      /* continue */
    }
  }

  setActiveBinder("settings");
  state.openSettingsSection = SETTINGS_DOC_TO_SECTION[kind] || kind;
  applySettingsSectionState();
  state.settingsDocKind = kind;
  state.settingsDocPair = pair.length >= 2 ? pair.slice() : [kind];
  state.settingsDocFocusKind = kind;
  state.characterBoardOpen = false;
  state.itemBoardOpen = false;
  state.ideaBoardOpen = false;
  state.keywordBoardOpen = false;
  hideSettingsCollectionBoard();
  hideGitsiWorkspace();
  hideSettingsSearchBoard();

  $("welcome")?.classList.add("hidden");
  $("ideaBoard")?.classList.add("hidden");
  $("keywordBoard")?.classList.add("hidden");
  $("characterBoard")?.classList.add("hidden");
  hideRelationCanvas();
  $("characterEditor")?.classList.add("hidden");
  hideItemViews();
  $("sceneWorkspace")?.classList.add("hidden");
  closeSceneToolsDrawer();
  closeSplitView().catch(() => {});

  if (kind === "world") {
    $("synopsisWorkspace")?.classList.add("hidden");
    ensureWorldbuildingMainForm();
    bindWorldBuildingMainFormInputs();
    $("worldbuildingWorkspace")?.classList.remove("hidden");
    const loadText = pullSettingsDocFromSidebar("world") || state.worldbuildingMd || "";
    state.worldbuildingMd = loadText;
    if (!String(loadText || "").trim()) seedWorldBuildingExamplesIfEmpty();
    else syncWorldBuildingFormFromState({ force: true });
    synopsisDirty = false;
    setSynopsisSaveStatus(i18n.t('app.편집_중'));
    requestAnimationFrame(() => {
      const fieldId = String(options?.worldField || "").trim();
      const form = $("worldbuildingMainForm");
      let target = null;
      if (fieldId) {
        try {
          target = form?.querySelector?.(`[data-world-field="${CSS.escape(fieldId)}"]`);
        } catch (_) {
          target = form?.querySelector?.(`[data-world-field="${fieldId}"]`);
        }
      }
      if (!target) target = form?.querySelector?.("[data-world-field]");
      try { target?.focus?.({ preventScroll: true }); } catch (_) { target?.focus?.(); }
      try { target?.scrollIntoView?.({ block: "center", behavior: "smooth" }); } catch (_) { /* ignore */ }
    });
    return;
  }

  $("worldbuildingWorkspace")?.classList.add("hidden");
  applySettingsDocChrome(kind);
  $("synopsisWorkspace")?.classList.remove("hidden");

  if (!samePairOpen) {
    suppressSynopsisDirty = true;
    for (const k of pair) {
      const meta = getSettingsDocMeta(k);
      const loadText = pullSettingsDocFromSidebar(k) || state[meta.stateKey] || "";
      state[meta.stateKey] = loadText;
      const editor = getSettingsDocMainEditor(k);
      if (editor) setEditorContent(loadText, editor);
      syncSettingsDocSidebarFromState(k);
    }
    synopsisDirty = false;
    suppressSynopsisDirty = false;
    setSynopsisSaveStatus(i18n.t('app.편집_중'));
  } else {
    state.settingsDocFocusKind = kind;
    setSynopsisSaveStatus(i18n.t('app.편집_중'));
  }

  requestAnimationFrame(() => {
    const editor = getSettingsDocMainEditor(kind) || $("synopsisContent");
    if (!editor) return;
    lastSettingsDocEditor = editor;
    editor.setAttribute("contenteditable", "true");
    try {
      editor.focus({ preventScroll: true });
    } catch (_) {
      editor.focus();
    }
  });
}

async function openSynopsisMain() {
  return openSettingsDocMain("synopsis");
}

function renderCharacterBoard() {
  const grid = $("characterBoardGrid");
  if (!grid) return;
  const list = Array.isArray(state.characters) ? state.characters : [];
  renderCharacterRoleFilterRow(list);
  syncCharacterBoardGroupToggle();
  if (!list.length) {
    grid.classList.remove("is-grouped");
    grid.innerHTML = i18n.t('app.p_class_character_board');
    return;
  }
  if (characterBoardGroupView) {
    grid.classList.add("is-grouped");
    grid.innerHTML = CHARACTER_STORY_ROLES.concat(["unspecified"]).map((key) => {
      const members = key === "unspecified"
        ? list.filter((ch) => !characterStoryRole(ch.role))
        : list.filter((ch) => characterStoryRole(ch.role) === key);
      const collapsed = Boolean(characterRoleGroupsCollapsed[key]);
      const label = key === "unspecified" ? i18n.t("app.미지정") : (roleLabel[key] || key);
      const cards = members.length
        ? `<div class="character-board-group-cards">${members.map(characterBoardCardHtml).join("")}</div>`
        : `<p class="character-board-group-empty">${escapeHtml(i18n.t("app.이_역할의_인물이_아직_없어요"))}</p>`;
      return `
        <section class="character-board-group ${collapsed ? "is-collapsed" : ""}" data-character-role-group="${key}">
          <button type="button" class="character-board-group-head" data-character-role-group-toggle="${key}" aria-expanded="${collapsed ? "false" : "true"}">
            <span class="character-board-group-caret" aria-hidden="true">${collapsed ? "▸" : "▼"}</span>
            <span class="character-board-group-title">${escapeHtml(label)} (${members.length})</span>
          </button>
          <div class="character-board-group-body">${cards}</div>
        </section>`;
    }).join("");
  } else {
    grid.classList.remove("is-grouped");
    const shown = filteredCharactersForBoard(list);
    grid.innerHTML = shown.length
      ? shown.map(characterBoardCardHtml).join("")
      : `<p class="character-board-empty">${escapeHtml(i18n.t("app.이_역할의_인물이_아직_없어요"))}</p>`;
  }
  grid.querySelectorAll("[data-character-board]").forEach((button) => {
    button.addEventListener("click", () => {
      openCharacter(button.dataset.characterBoard).catch(handleError);
    });
  });
  grid.querySelectorAll("[data-character-role-group-toggle]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      const key = button.getAttribute("data-character-role-group-toggle") || "";
      if (!key) return;
      characterRoleGroupsCollapsed[key] = !characterRoleGroupsCollapsed[key];
      persistCharacterBoardViewPrefs();
      renderCharacterBoard();
    });
  });
}

function characterStoryRole(role) {
  const key = String(role || "").trim();
  return CHARACTER_STORY_ROLES.includes(key) ? key : "";
}

function characterStoryRoleLabel(role) {
  const key = characterStoryRole(role);
  return key ? (roleLabel[key] || key) : i18n.t("app.미지정");
}

function characterRoleCounts(list) {
  const counts = {
    all: list.length,
    protagonist: 0,
    antagonist: 0,
    supporting: 0,
    minor: 0,
    unspecified: 0,
  };
  list.forEach((ch) => {
    const key = characterStoryRole(ch.role);
    if (key) counts[key] += 1;
    else counts.unspecified += 1;
  });
  return counts;
}

function filteredCharactersForBoard(list) {
  const rows = Array.isArray(list) ? list : [];
  const filter = characterRoleFilter || "all";
  if (filter === "all") return rows;
  if (filter === "unspecified") return rows.filter((ch) => !characterStoryRole(ch.role));
  return rows.filter((ch) => characterStoryRole(ch.role) === filter);
}

function characterBoardCardHtml(character) {
  const name = escapeHtml(character.name || i18n.t('app.이름_없음'));
  const role = escapeHtml(characterStoryRoleLabel(character.role));
  const summary = escapeHtml(
    String(character.short_description || "").trim()
    || String(character.profile_md || "").split(/\n/).map((l) => l.trim()).find(Boolean)
    || i18n.t('app.소개를_적어_보세요')
  );
  const active = Number(state.characterId) === Number(character.id) ? "is-active" : "";
  const analysisMark = character.has_tori_analysis
    ? i18n.t('app.span_class_character_bo')
    : "";
  return `
      <button type="button" class="character-board-card ${active}" data-character-board="${character.id}" title="${name}">
        <span class="character-board-card-name">${name}</span>
        <span class="character-board-card-role">${role}</span>
        <span class="character-board-card-summary">${summary}</span>
        ${analysisMark}
      </button>`;
}

function persistCharacterBoardViewPrefs() {
  try {
    localStorage.setItem(CHARACTER_ROLE_FILTER_KEY, characterRoleFilter || "all");
    localStorage.setItem(CHARACTER_BOARD_GROUP_KEY, characterBoardGroupView ? "1" : "0");
    localStorage.setItem(CHARACTER_ROLE_COLLAPSE_KEY, JSON.stringify(characterRoleGroupsCollapsed || {}));
  } catch (_) { /* ignore */ }
}

function loadCharacterBoardViewPrefs() {
  try {
    const filter = String(localStorage.getItem(CHARACTER_ROLE_FILTER_KEY) || "all").trim();
    characterRoleFilter = (filter === "all" || CHARACTER_STORY_ROLES.includes(filter) || filter === "unspecified")
      ? filter
      : "all";
    characterBoardGroupView = localStorage.getItem(CHARACTER_BOARD_GROUP_KEY) === "1";
    const raw = JSON.parse(localStorage.getItem(CHARACTER_ROLE_COLLAPSE_KEY) || "{}");
    characterRoleGroupsCollapsed = raw && typeof raw === "object" ? raw : {};
  } catch (_) {
    characterRoleFilter = "all";
    characterBoardGroupView = false;
    characterRoleGroupsCollapsed = {};
  }
}

function renderCharacterRoleFilterRow(list) {
  const row = $("characterRoleFilterRow");
  if (!row) return;
  const counts = characterRoleCounts(list);
  const chips = [
    ["all", i18n.t("app.전체"), counts.all],
    ["protagonist", roleLabel.protagonist, counts.protagonist],
    ["antagonist", roleLabel.antagonist, counts.antagonist],
    ["supporting", roleLabel.supporting, counts.supporting],
    ["minor", roleLabel.minor, counts.minor],
    ["unspecified", i18n.t("app.미지정"), counts.unspecified],
  ];
  row.classList.toggle("is-grouped", characterBoardGroupView);
  row.innerHTML = chips.map(([value, label, count]) => {
    const active = !characterBoardGroupView && characterRoleFilter === value ? "is-active" : "";
    return `<button type="button" class="character-role-filter-chip ${active}" data-character-role-filter="${value}" role="tab" aria-selected="${active ? "true" : "false"}">${escapeHtml(label)} (${count})</button>`;
  }).join("");
  row.querySelectorAll("[data-character-role-filter]").forEach((btn) => {
    btn.addEventListener("click", () => {
      characterRoleFilter = btn.getAttribute("data-character-role-filter") || "all";
      characterBoardGroupView = false;
      persistCharacterBoardViewPrefs();
      renderCharacterBoard();
    });
  });
}

function syncCharacterBoardGroupToggle() {
  const toggle = $("characterBoardGroupToggle");
  if (toggle) toggle.checked = Boolean(characterBoardGroupView);
}

function setupCharacterBoardViewControls() {
  loadCharacterBoardViewPrefs();
  const toggle = $("characterBoardGroupToggle");
  if (toggle && toggle.dataset.bound !== "1") {
    toggle.dataset.bound = "1";
    toggle.addEventListener("change", () => {
      characterBoardGroupView = Boolean(toggle.checked);
      persistCharacterBoardViewPrefs();
      renderCharacterBoard();
    });
  }
}

function syncCharacterRoleChips(role) {
  const key = characterStoryRole(role);
  const hidden = $("characterRole");
  if (hidden) hidden.value = key;
  document.querySelectorAll("#characterRoleChips [data-character-role]").forEach((btn) => {
    const on = btn.getAttribute("data-character-role") === key && Boolean(key);
    btn.classList.toggle("is-active", on);
    btn.setAttribute("aria-pressed", on ? "true" : "false");
  });
}

function setupCharacterRoleChips() {
  const host = $("characterRoleChips");
  if (!host || host.dataset.bound === "1") return;
  host.dataset.bound = "1";
  host.addEventListener("click", (event) => {
    const chip = event.target.closest("[data-character-role]");
    if (!chip || !host.contains(chip)) return;
    event.preventDefault();
    const next = chip.getAttribute("data-character-role") || "";
    const current = String($("characterRole")?.value || "");
    syncCharacterRoleChips(current === next ? "" : next);
    markCharacterDirty();
  });
}

async function openCharacterBoard() {
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  if (typeof isGlumpSprintActive === "function" && isGlumpSprintActive() && !confirmLeaveGlumpSprint()) {
    return;
  }

  try {
    await flushCharacterAutoSave();
  } catch (_) {
    /* continue */
  }
  if (isSettingsDocMainOpen() && synopsisDirty) {
    try {
      const kinds = state.settingsDocPair?.length
        ? state.settingsDocPair
        : (state.settingsDocKind ? [state.settingsDocKind] : []);
      await persistSettingsDocPair(kinds, { quiet: true });
    } catch (_) {
      /* continue */
    }
  }
  if (sceneDirty && state.sceneId) {
    try {
      await persistScene({ quiet: true, saveNote: i18n.t('app.자동_저장') });
    } catch (_) {
      /* continue */
    }
  }

  setActiveBinder("settings");
  state.openSettingsSection = "characters";
  applySettingsSectionState();
  state.characterBoardOpen = true;
  state.ideaBoardOpen = false;
  state.keywordBoardOpen = false;
  hideRelationCanvas();
  hideSynopsisMain();
  hideSettingsCollectionBoard();
  hideGitsiWorkspace();
  hideSettingsSearchBoard();

  $("welcome")?.classList.add("hidden");
  $("ideaBoard")?.classList.add("hidden");
  $("keywordBoard")?.classList.add("hidden");
  $("sceneWorkspace")?.classList.add("hidden");
  $("characterEditor")?.classList.add("hidden");
  hideItemViews();
  closeSceneToolsDrawer();
  await closeSplitView().catch(() => {});

  $("characterBoard")?.classList.remove("hidden");
  renderCharacterBoard();
}

async function closeCharacterBoard() {
  hideCharacterBoard();
  await returnToManuscriptFromSettingsMain();
}

const REL_CARD_W = 188;
const REL_CARD_H = 124;
const REL_CARD_GAP = 36;
const REL_CARD_COLS = 4;
let relationCanvasData = { characters: [], relations: [] };
let relationCanvasPan = { x: 48, y: 36 };
let relationCanvasZoom = 1;
let relationSelectedIds = [];
let relationDrag = null;
let relationPanDrag = null;
let relationPopupId = null;
let relationLabelPair = null;
let relationCanvasBound = false;

function hideRelationPopups() {
  relationPopupId = null;
  relationLabelPair = null;
  $("relationSuggestPopup")?.classList.add("hidden");
  $("relationLabelModal")?.classList.add("hidden");
}

function relationCardSummary(character) {
  const fromProfile = String(character.profile_md || "")
    .replace(/^\[[^\]]+\]\s*/gm, "")
    .split(/\n/)
    .map((line) => line.trim())
    .find(Boolean);
  const cleaned = String(character.short_description || fromProfile || "")
    .replace(/\s+/g, " ")
    .trim();
  if (!cleaned) return i18n.t("app.소개를_적어_보세요");
  return cleaned.length > 90 ? `${cleaned.slice(0, 90)}…` : cleaned;
}

function defaultRelationPosition(index) {
  return {
    x: 40 + (index % REL_CARD_COLS) * (REL_CARD_W + REL_CARD_GAP),
    y: 40 + Math.floor(index / REL_CARD_COLS) * (REL_CARD_H + REL_CARD_GAP),
  };
}

function applyRelationTransform() {
  const world = $("relationCanvasWorld");
  if (!world) return;
  world.style.transform = `translate(${relationCanvasPan.x}px, ${relationCanvasPan.y}px) scale(${relationCanvasZoom})`;
}

function relationCardCenter(character) {
  return {
    x: Number(character.x) + REL_CARD_W / 2,
    y: Number(character.y) + REL_CARD_H / 2,
  };
}

function relationPairKey(rel) {
  const a = Number(rel.character_a_id);
  const b = Number(rel.character_b_id);
  return a < b ? `${a}:${b}` : `${b}:${a}`;
}

function offsetRelationLine(ac, bc, index, total) {
  if (total <= 1) {
    return { a: ac, b: bc, midX: (ac.x + bc.x) / 2, midY: (ac.y + bc.y) / 2 };
  }
  const dx = bc.x - ac.x;
  const dy = bc.y - ac.y;
  const len = Math.hypot(dx, dy) || 1;
  const shift = (index - (total - 1) / 2) * 18;
  const ox = (-dy / len) * shift;
  const oy = (dx / len) * shift;
  const a = { x: ac.x + ox, y: ac.y + oy };
  const b = { x: bc.x + ox, y: bc.y + oy };
  return { a, b, midX: (a.x + b.x) / 2, midY: (a.y + b.y) / 2 };
}

/** Pin a horizontal label so its visual center sits on a line-segment midpoint. */
function setRelationLabelAtLineMid(text, midX, midY) {
  text.setAttribute("text-anchor", "middle");
  text.setAttribute("dominant-baseline", "central");
  text.setAttribute("alignment-baseline", "middle");
  text.setAttribute("x", String(midX));
  text.setAttribute("y", String(midY));
}

function paintRelationLines() {
  const svg = $("relationCanvasSvg");
  if (!svg) return;
  const NS = "http://www.w3.org/2000/svg";
  while (svg.firstChild) svg.removeChild(svg.firstChild);
  const byId = {};
  (relationCanvasData.characters || []).forEach((ch) => { byId[ch.id] = ch; });
  const groups = new Map();
  (relationCanvasData.relations || []).forEach((rel) => {
    const a = byId[rel.character_a_id];
    const b = byId[rel.character_b_id];
    if (!a || !b) return;
    const key = relationPairKey(rel);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(rel);
  });
  groups.forEach((rels) => {
    const sample = rels[0];
    const ac = relationCardCenter(byId[sample.character_a_id]);
    const bc = relationCardCenter(byId[sample.character_b_id]);
    rels.forEach((rel, index) => {
      const placed = offsetRelationLine(ac, bc, index, rels.length);
      const suggested = rel.status === "suggested";
      const hit = document.createElementNS(NS, "line");
      hit.setAttribute("class", "rel-hit");
      hit.setAttribute("data-rel-id", String(rel.id));
      hit.setAttribute("x1", String(placed.a.x));
      hit.setAttribute("y1", String(placed.a.y));
      hit.setAttribute("x2", String(placed.b.x));
      hit.setAttribute("y2", String(placed.b.y));
      const line = document.createElementNS(NS, "line");
      line.setAttribute("class", `rel-line ${suggested ? "is-suggested" : ""}`);
      line.setAttribute("data-rel-id", String(rel.id));
      line.setAttribute("x1", String(placed.a.x));
      line.setAttribute("y1", String(placed.a.y));
      line.setAttribute("x2", String(placed.b.x));
      line.setAttribute("y2", String(placed.b.y));
      const text = document.createElementNS(NS, "text");
      text.setAttribute("class", "rel-label");
      text.textContent = suggested ? `${rel.label}${i18n.t("app.추정_접미사")}` : rel.label;
      hit.addEventListener("pointerdown", (event) => {
        event.stopPropagation();
        event.preventDefault();
        if (suggested) showRelationSuggestPopup(rel, event);
      });
      svg.appendChild(hit);
      svg.appendChild(line);
      svg.appendChild(text);
      setRelationLabelAtLineMid(text, placed.midX, placed.midY);
    });
  });
}

function paintRelationCards() {
  const host = $("relationCanvasCards");
  if (!host) return;
  const rows = relationCanvasData.characters || [];
  if (!rows.length) {
    host.innerHTML = `<p class="character-board-empty">${escapeHtml(i18n.t("app.등록된_인물이_아직_없어요"))}</p>`;
    return;
  }
  host.innerHTML = rows.map((ch) => {
    const selected = relationSelectedIds.includes(Number(ch.id)) ? "is-selected" : "";
    return `
      <article class="relation-canvas-card ${selected}" data-rel-card="${ch.id}" style="left:${Number(ch.x)}px;top:${Number(ch.y)}px">
        <span class="relation-canvas-card-name">${escapeHtml(ch.name || i18n.t("app.이름_없음"))}</span>
        <span class="relation-canvas-card-role">${escapeHtml(characterStoryRoleLabel(ch.role))}</span>
        <span class="relation-canvas-card-summary">${escapeHtml(relationCardSummary(ch))}</span>
        <button type="button" class="relation-canvas-card-profile" data-rel-profile="${ch.id}">${escapeHtml(i18n.t("app.프로필_보기"))} →</button>
      </article>`;
  }).join("");
  host.querySelectorAll("[data-rel-profile]").forEach((button) => {
    button.addEventListener("pointerdown", (event) => event.stopPropagation());
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      openCharacter(button.getAttribute("data-rel-profile")).catch(handleError);
    });
  });
}

function paintRelationCanvas() {
  paintRelationCards();
  paintRelationLines();
  applyRelationTransform();
}

async function persistRelationPositions(positions) {
  if (!state.projectId || !positions.length) return;
  await api(`/api/projects/${state.projectId}/character-canvas/positions`, {
    method: "PUT",
    body: JSON.stringify({ positions }),
  });
}

function ensureRelationLayout(characters) {
  let dirty = false;
  const laid = characters.map((ch, index) => {
    const next = { ...ch };
    if (next.x == null || next.y == null || Number.isNaN(Number(next.x)) || Number.isNaN(Number(next.y))) {
      const pos = defaultRelationPosition(index);
      next.x = pos.x;
      next.y = pos.y;
      dirty = true;
    }
    return next;
  });
  return { characters: laid, dirty };
}

async function loadRelationCanvas() {
  if (!state.projectId) return;
  const data = await api(`/api/projects/${state.projectId}/character-canvas`);
  const laid = ensureRelationLayout(Array.isArray(data.characters) ? data.characters : []);
  relationCanvasData = {
    characters: laid.characters,
    relations: Array.isArray(data.relations) ? data.relations : [],
  };
  paintRelationCanvas();
  if (laid.dirty) {
    persistRelationPositions(
      laid.characters.map((ch) => ({ character_id: ch.id, x: ch.x, y: ch.y }))
    ).catch(handleError);
  }
}

function relationStagePoint(event, stage) {
  const rect = stage.getBoundingClientRect();
  return {
    x: (event.clientX - rect.left - relationCanvasPan.x) / relationCanvasZoom,
    y: (event.clientY - rect.top - relationCanvasPan.y) / relationCanvasZoom,
  };
}

function toggleRelationSelection(characterId) {
  const id = Number(characterId);
  const idx = relationSelectedIds.indexOf(id);
  if (idx >= 0) relationSelectedIds.splice(idx, 1);
  else {
    if (relationSelectedIds.length >= 2) relationSelectedIds.shift();
    relationSelectedIds.push(id);
  }
  paintRelationCards();
}

function showRelationSuggestPopup(rel, event) {
  const popup = $("relationSuggestPopup");
  const stage = $("relationCanvasStage");
  if (!popup || !stage) return;
  hideRelationPopups();
  relationPopupId = Number(rel.id);
  $("relationSuggestPopupLabel").textContent = `${rel.label}${i18n.t("app.추정_접미사")}`;
  const rect = stage.getBoundingClientRect();
  popup.style.left = `${Math.min(rect.width - 200, Math.max(8, event.clientX - rect.left - 40))}px`;
  popup.style.top = `${Math.min(rect.height - 90, Math.max(8, event.clientY - rect.top - 20))}px`;
  popup.classList.remove("hidden");
}

function showRelationLabelModal() {
  if (relationSelectedIds.length !== 2) {
    toast(i18n.t("app.인물을_두_명_고른_뒤_관계를_이으세요"));
    return;
  }
  const modal = $("relationLabelModal");
  const stage = $("relationCanvasStage");
  if (!modal || !stage) return;
  hideRelationPopups();
  relationLabelPair = relationSelectedIds.slice();
  const input = $("relationLabelInput");
  if (input) input.value = "";
  modal.style.left = "24px";
  modal.style.top = "24px";
  modal.classList.remove("hidden");
  input?.focus();
}

async function saveManualRelation() {
  if (!state.projectId || !relationLabelPair || relationLabelPair.length !== 2) return;
  const label = String($("relationLabelInput")?.value || "").trim();
  if (!label) {
    toast(i18n.t("app.관계_이름"));
    return;
  }
  await api(`/api/projects/${state.projectId}/character-relations`, {
    method: "POST",
    body: JSON.stringify({
      character_a_id: relationLabelPair[0],
      character_b_id: relationLabelPair[1],
      label,
    }),
  });
  hideRelationPopups();
  relationSelectedIds = [];
  toast(i18n.t("app.관계를_이었어요"));
  await loadRelationCanvas();
}

async function acceptSuggestedRelation() {
  if (!relationPopupId) return;
  await api(`/api/character-relations/${relationPopupId}/accept`, { method: "POST" });
  hideRelationPopups();
  toast(i18n.t("app.관계_제안을_수락했어요"));
  await loadRelationCanvas();
}

async function deleteRelationEdge(relationId) {
  const id = Number(relationId || relationPopupId);
  if (!id) return;
  await api(`/api/character-relations/${id}`, { method: "DELETE" });
  hideRelationPopups();
  toast(i18n.t("app.관계_제안을_거절했어요"));
  await loadRelationCanvas();
}

async function requestRelationSuggestions() {
  if (!state.projectId) return;
  const button = $("relationSuggestButton");
  if (button) button.disabled = true;
  toast(i18n.t("app.관계_필드를_분석하는_중"));
  try {
    const result = await api(`/api/projects/${state.projectId}/character-relations/suggest`, {
      method: "POST",
      body: "{}",
    });
    if (result.canvas) {
      const laid = ensureRelationLayout(result.canvas.characters || relationCanvasData.characters);
      relationCanvasData = {
        characters: laid.characters,
        relations: result.canvas.relations || [],
      };
      paintRelationCanvas();
    } else {
      await loadRelationCanvas();
    }
    const added = Array.isArray(result.added) ? result.added.length : 0;
    toast(added
      ? i18n.t("app.count건의_관계를_제안했어요", { count: added })
      : i18n.t("app.새_관계_제안이_없어요"));
  } catch (error) {
    handleError(toAiAssistError(error));
  } finally {
    if (button) button.disabled = false;
  }
}

function setRelationZoom(next, origin) {
  const stage = $("relationCanvasStage");
  const zoom = Math.max(0.35, Math.min(2.2, next));
  if (!stage) {
    relationCanvasZoom = zoom;
    applyRelationTransform();
    return;
  }
  const rect = stage.getBoundingClientRect();
  const cx = origin ? origin.x - rect.left : rect.width / 2;
  const cy = origin ? origin.y - rect.top : rect.height / 2;
  const worldX = (cx - relationCanvasPan.x) / relationCanvasZoom;
  const worldY = (cy - relationCanvasPan.y) / relationCanvasZoom;
  relationCanvasZoom = zoom;
  relationCanvasPan.x = cx - worldX * relationCanvasZoom;
  relationCanvasPan.y = cy - worldY * relationCanvasZoom;
  applyRelationTransform();
}

function fitRelationCanvas() {
  const stage = $("relationCanvasStage");
  const rows = relationCanvasData.characters || [];
  if (!stage || !rows.length) return false;
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  rows.forEach((ch) => {
    minX = Math.min(minX, Number(ch.x));
    minY = Math.min(minY, Number(ch.y));
    maxX = Math.max(maxX, Number(ch.x) + REL_CARD_W);
    maxY = Math.max(maxY, Number(ch.y) + REL_CARD_H);
  });
  const width = Math.max(120, maxX - minX);
  const height = Math.max(80, maxY - minY);
  const rect = stage.getBoundingClientRect();
  if (rect.width < 40 || rect.height < 40) return false;
  const zoom = Math.max(0.35, Math.min(1.4, Math.min((rect.width - 48) / width, (rect.height - 48) / height)));
  relationCanvasZoom = zoom;
  relationCanvasPan.x = (rect.width - width * zoom) / 2 - minX * zoom;
  relationCanvasPan.y = (rect.height - height * zoom) / 2 - minY * zoom;
  applyRelationTransform();
  return true;
}

function scheduleFitRelationCanvas() {
  requestAnimationFrame(() => {
    if (fitRelationCanvas()) return;
    requestAnimationFrame(() => fitRelationCanvas());
  });
}

function isRelationCanvasFullscreen() {
  return Boolean($("relationCanvas")?.classList.contains("is-fullscreen"));
}

function syncRelationCanvasFullscreenUi() {
  const on = isRelationCanvasFullscreen();
  document.body.classList.toggle("relation-canvas-fullscreen", on);
  const exitBtn = $("relationFullscreenExitButton");
  if (exitBtn) {
    exitBtn.classList.toggle("hidden", !on);
    exitBtn.setAttribute("aria-hidden", on ? "false" : "true");
  }
  $("relationFitButton")?.setAttribute("aria-pressed", on ? "true" : "false");
}

function enterRelationCanvasFullscreen() {
  const canvas = $("relationCanvas");
  if (!canvas || canvas.classList.contains("hidden")) return;
  canvas.classList.add("is-fullscreen");
  syncRelationCanvasFullscreenUi();
  scheduleFitRelationCanvas();
}

function exitRelationCanvasFullscreen() {
  const canvas = $("relationCanvas");
  if (!canvas) return;
  const wasOn = canvas.classList.contains("is-fullscreen");
  canvas.classList.remove("is-fullscreen");
  syncRelationCanvasFullscreenUi();
  if (wasOn && state.relationCanvasOpen && !canvas.classList.contains("hidden")) {
    scheduleFitRelationCanvas();
  }
}

function onRelationCanvasFitClick() {
  if (isRelationCanvasFullscreen()) {
    scheduleFitRelationCanvas();
    return;
  }
  enterRelationCanvasFullscreen();
}

function onRelationCanvasKeydown(event) {
  if (event.key !== "Escape") return;
  if (!$("relationCanvas") || $("relationCanvas").classList.contains("hidden")) return;
  const labelModal = $("relationLabelModal");
  if (labelModal && !labelModal.classList.contains("hidden")) {
    hideRelationPopups();
    event.preventDefault();
    event.stopImmediatePropagation();
    return;
  }
  if (!isRelationCanvasFullscreen()) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  exitRelationCanvasFullscreen();
}

async function autoLayoutRelationCanvas() {
  const laid = (relationCanvasData.characters || []).map((ch, index) => {
    const pos = defaultRelationPosition(index);
    return { ...ch, x: pos.x, y: pos.y };
  });
  relationCanvasData.characters = laid;
  paintRelationCanvas();
  await persistRelationPositions(laid.map((ch) => ({ character_id: ch.id, x: ch.x, y: ch.y })));
  scheduleFitRelationCanvas();
}

function bindRelationCanvasEvents() {
  if (relationCanvasBound) return;
  relationCanvasBound = true;
  const stage = $("relationCanvasStage");
  if (stage) {
  stage.addEventListener("pointerdown", (event) => {
    if (event.button != null && event.button !== 0) return;
    const profile = event.target.closest?.("[data-rel-profile]");
    if (profile) return;
    const card = event.target.closest?.("[data-rel-card]");
    if (card) {
      hideRelationPopups();
      const id = Number(card.getAttribute("data-rel-card"));
      const ch = (relationCanvasData.characters || []).find((row) => Number(row.id) === id);
      if (!ch) return;
      relationDrag = {
        id,
        startX: event.clientX,
        startY: event.clientY,
        origX: Number(ch.x),
        origY: Number(ch.y),
        moved: false,
      };
      card.classList.add("is-dragging");
      stage.setPointerCapture?.(event.pointerId);
      return;
    }
    if (event.target.closest?.(".rel-hit, .relation-suggest-popup, .relation-label-modal")) return;
    hideRelationPopups();
    relationPanDrag = {
      startX: event.clientX,
      startY: event.clientY,
      origX: relationCanvasPan.x,
      origY: relationCanvasPan.y,
    };
    stage.classList.add("is-panning");
    stage.setPointerCapture?.(event.pointerId);
  });
  stage.addEventListener("pointermove", (event) => {
    if (relationDrag) {
      const dx = (event.clientX - relationDrag.startX) / relationCanvasZoom;
      const dy = (event.clientY - relationDrag.startY) / relationCanvasZoom;
      if (Math.abs(dx) + Math.abs(dy) > 3) relationDrag.moved = true;
      const ch = (relationCanvasData.characters || []).find((row) => Number(row.id) === relationDrag.id);
      if (!ch) return;
      ch.x = relationDrag.origX + dx;
      ch.y = relationDrag.origY + dy;
      const el = stage.querySelector(`[data-rel-card="${relationDrag.id}"]`);
      if (el) {
        el.style.left = `${ch.x}px`;
        el.style.top = `${ch.y}px`;
      }
      paintRelationLines();
      return;
    }
    if (relationPanDrag) {
      relationCanvasPan.x = relationPanDrag.origX + (event.clientX - relationPanDrag.startX);
      relationCanvasPan.y = relationPanDrag.origY + (event.clientY - relationPanDrag.startY);
      applyRelationTransform();
    }
  });
  const endPointer = (event) => {
    if (relationDrag) {
      const drag = relationDrag;
      relationDrag = null;
      stage.querySelector("[data-rel-card].is-dragging")?.classList.remove("is-dragging");
      if (!drag.moved) toggleRelationSelection(drag.id);
      else {
        const ch = (relationCanvasData.characters || []).find((row) => Number(row.id) === drag.id);
        if (ch) persistRelationPositions([{ character_id: ch.id, x: ch.x, y: ch.y }]).catch(handleError);
      }
    }
    if (relationPanDrag) {
      relationPanDrag = null;
      stage.classList.remove("is-panning");
    }
  };
  stage.addEventListener("pointerup", endPointer);
  stage.addEventListener("pointercancel", endPointer);
  stage.addEventListener("wheel", (event) => {
    event.preventDefault();
    const factor = event.deltaY > 0 ? 0.92 : 1.08;
    setRelationZoom(relationCanvasZoom * factor, { x: event.clientX, y: event.clientY });
  }, { passive: false });
  }
  $("relationSuggestButton")?.addEventListener("click", () => requestRelationSuggestions().catch(handleError));
  $("relationLinkButton")?.addEventListener("click", () => showRelationLabelModal());
  $("relationFitButton")?.addEventListener("click", () => onRelationCanvasFitClick());
  $("relationFullscreenExitButton")?.addEventListener("click", () => exitRelationCanvasFullscreen());
  $("relationLayoutButton")?.addEventListener("click", () => autoLayoutRelationCanvas().catch(handleError));
  $("relationZoomInButton")?.addEventListener("click", () => setRelationZoom(relationCanvasZoom * 1.12));
  $("relationZoomOutButton")?.addEventListener("click", () => setRelationZoom(relationCanvasZoom / 1.12));
  $("closeRelationCanvasButton")?.addEventListener("click", () => closeRelationCanvas().catch(handleError));
  document.addEventListener("keydown", onRelationCanvasKeydown, true);
  $("relationSuggestAcceptButton")?.addEventListener("click", () => acceptSuggestedRelation().catch(handleError));
  $("relationSuggestRejectButton")?.addEventListener("click", () => deleteRelationEdge().catch(handleError));
  $("relationLabelSaveButton")?.addEventListener("click", () => saveManualRelation().catch(handleError));
  $("relationLabelCancelButton")?.addEventListener("click", () => hideRelationPopups());
  $("relationLabelInput")?.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      saveManualRelation().catch(handleError);
    }
  });
}

async function openRelationCanvas(focus = null) {
  if (!state.projectId) return toast(i18n.t("app.먼저_작품을_선택해_주세요"));
  if (typeof isGlumpSprintActive === "function" && isGlumpSprintActive() && !confirmLeaveGlumpSprint()) {
    return;
  }
  try { await flushCharacterAutoSave(); } catch (_) { /* continue */ }
  if (sceneDirty && state.sceneId) {
    try { await persistScene({ quiet: true, saveNote: i18n.t("app.자동_저장") }); } catch (_) { /* continue */ }
  }
  setActiveBinder("settings");
  state.openSettingsSection = "characters";
  applySettingsSectionState();
  state.relationCanvasOpen = true;
  state.characterBoardOpen = false;
  state.ideaBoardOpen = false;
  state.keywordBoardOpen = false;
  hideSynopsisMain();
  hideSettingsCollectionBoard();
  hideGitsiWorkspace();
  hideSettingsSearchBoard();
  $("welcome")?.classList.add("hidden");
  $("ideaBoard")?.classList.add("hidden");
  $("keywordBoard")?.classList.add("hidden");
  $("sceneWorkspace")?.classList.add("hidden");
  $("characterEditor")?.classList.add("hidden");
  $("characterBoard")?.classList.add("hidden");
  hideItemViews();
  closeSceneToolsDrawer();
  await closeSplitView().catch(() => {});
  $("relationCanvas")?.classList.remove("hidden");
  bindRelationCanvasEvents();
  relationSelectedIds = [];
  const focusA = Number(focus?.characterAId);
  const focusB = Number(focus?.characterBId);
  if (Number.isFinite(focusA) && focusA > 0) relationSelectedIds.push(focusA);
  if (Number.isFinite(focusB) && focusB > 0 && !relationSelectedIds.includes(focusB)) {
    relationSelectedIds.push(focusB);
  }
  hideRelationPopups();
  await loadRelationCanvas();
  if (relationSelectedIds.length) paintRelationCanvas();
  scheduleFitRelationCanvas();
}

async function closeRelationCanvas() {
  hideRelationCanvas();
  await returnToManuscriptFromSettingsMain();
}

async function closeCharacterEditor() {
  try {
    await flushCharacterAutoSave();
  } catch (_) {
    /* keep going so the manuscript still opens */
  }
  $("characterEditor")?.classList.add("hidden");
  await returnToManuscriptFromSettingsMain();
}

function itemPreviewText(item, max = 90) {
  const cleaned = String(item?.description || "").replace(/\s+/g, " ").trim();
  if (!cleaned) return i18n.t("app.소개를_적어_보세요");
  return cleaned.length > max ? `${cleaned.slice(0, max)}…` : cleaned;
}

function renderItems() {
  const list = $("itemList");
  if (!list) return;
  const rows = Array.isArray(state.items) ? state.items : [];
  list.innerHTML = rows.length ? rows.map((item) => {
    const analysisMark = item.has_tori_analysis
      ? i18n.t("app.span_class_character_li")
      : "";
    return `
    <button class="character-link ${Number(state.itemId) === Number(item.id) ? "active" : ""}" data-item="${item.id}" title="${escapeHtml(item.name)}">
      <span class="character-name">${escapeHtml(item.name)}${analysisMark}</span>
      <span class="character-role">${escapeHtml(itemPreviewText(item, 48))}</span>
    </button>`;
  }).join("") : i18n.t("app.p_class_hint_아직_아이템이_없어요");
  list.querySelectorAll("[data-item]").forEach((button) => {
    button.addEventListener("click", () => openItem(button.dataset.item).catch(handleError));
  });
  renderSettingsCodex();
}

function itemBoardCardHtml(item) {
  const name = escapeHtml(item.name || i18n.t("app.이름_없음"));
  const owner = String(item.owner_name || "").trim();
  const summary = escapeHtml(itemPreviewText(item));
  const active = Number(state.itemId) === Number(item.id) ? "is-active" : "";
  const analysisMark = item.has_tori_analysis
    ? i18n.t("app.span_class_character_bo")
    : "";
  return `
      <button type="button" class="character-board-card ${active}" data-item-board="${item.id}" title="${name}">
        <span class="character-board-card-name">${name}</span>
        <span class="character-board-card-role">${escapeHtml(owner)}</span>
        <span class="character-board-card-summary">${summary}</span>
        ${analysisMark}
      </button>`;
}

function renderItemBoard() {
  const grid = $("itemBoardGrid");
  if (!grid) return;
  const list = Array.isArray(state.items) ? state.items : [];
  if (!list.length) {
    grid.innerHTML = i18n.t("app.p_class_item_board");
    return;
  }
  grid.innerHTML = list.map(itemBoardCardHtml).join("");
  grid.querySelectorAll("[data-item-board]").forEach((button) => {
    button.addEventListener("click", () => openItem(button.dataset.itemBoard).catch(handleError));
  });
}

async function openItemBoard() {
  if (!state.projectId) return toast(i18n.t("app.먼저_작품을_선택해_주세요"));
  if (typeof isGlumpSprintActive === "function" && isGlumpSprintActive() && !confirmLeaveGlumpSprint()) {
    return;
  }
  try {
    await flushItemAutoSave();
  } catch (_) {
    /* continue */
  }
  try {
    await flushCharacterAutoSave();
  } catch (_) {
    /* continue */
  }
  if (sceneDirty && state.sceneId) {
    try {
      await persistScene({ quiet: true, saveNote: i18n.t("app.자동_저장") });
    } catch (_) {
      /* continue */
    }
  }
  setActiveBinder("settings");
  state.openSettingsSection = "items";
  applySettingsSectionState();
  state.itemBoardOpen = true;
  state.characterBoardOpen = false;
  state.ideaBoardOpen = false;
  state.keywordBoardOpen = false;
  hideSynopsisMain();
  hideSettingsCollectionBoard();
  hideGitsiWorkspace();
  $("welcome")?.classList.add("hidden");
  $("ideaBoard")?.classList.add("hidden");
  $("keywordBoard")?.classList.add("hidden");
  $("sceneWorkspace")?.classList.add("hidden");
  $("characterEditor")?.classList.add("hidden");
  $("characterBoard")?.classList.add("hidden");
  hideRelationCanvas();
  $("itemEditor")?.classList.add("hidden");
  hideSettingsSearchBoard();
  closeSceneToolsDrawer();
  await closeSplitView().catch(() => {});
  $("itemBoard")?.classList.remove("hidden");
  renderItemBoard();
}

async function closeItemBoard() {
  hideItemBoard();
  await returnToManuscriptFromSettingsMain();
}

async function closeItemEditor() {
  try {
    await flushItemAutoSave();
  } catch (_) {
    /* keep going */
  }
  $("itemEditor")?.classList.add("hidden");
  await returnToManuscriptFromSettingsMain();
}

function fillItemOwnerSelect(ownerId) {
  const select = $("itemOwner");
  if (!select) return;
  const current = ownerId == null || ownerId === "" ? "" : String(ownerId);
  const people = Array.isArray(state.characters) ? state.characters : [];
  const options = [`<option value="">${escapeHtml(i18n.t("index.소유자_없음"))}</option>`]
    .concat(people.map((person) => {
      const id = String(person.id);
      const selected = current && id === current ? " selected" : "";
      return `<option value="${escapeHtml(id)}"${selected}>${escapeHtml(person.name || i18n.t("app.이름_없음"))}</option>`;
    }));
  select.innerHTML = options.join("");
  select.value = current;
}

function itemAliasNamesFrom(aliases) {
  return characterAliasNamesFrom(aliases);
}

function renderItemAliasList(aliases) {
  const list = $("itemAliasList");
  if (!list) return;
  const names = itemAliasNamesFrom(aliases);
  if (!names.length) {
    list.innerHTML = i18n.t("app.span_class_hint_아직_별칭이");
    return;
  }
  list.innerHTML = names.map((alias) => `
    <button type="button" class="chip alias-chip${isToriDraftText(alias) ? " is-tori-draft" : ""}" data-item-alias-remove="${escapeHtml(alias)}" title="${escapeHtml(i18n.t("app.별칭_삭제"))}">
      ${escapeHtml(alias)}
    </button>`).join("");
  list.querySelectorAll("[data-item-alias-remove]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      removeItemAlias(button.dataset.itemAliasRemove);
    });
  });
}

function setItemAliases(names, { render = true } = {}) {
  if (!state.item) state.item = { item: {}, aliases: [] };
  state.item.aliases = itemAliasNamesFrom(names).map((alias) => ({ alias }));
  if (render) renderItemAliasList(state.item.aliases);
}

function commitItemAliasInputToState() {
  const input = $("newItemAlias");
  const pending = splitAliasInput(input?.value || "");
  if (input) input.value = "";
  if (!pending.length || !state.item) return false;
  const merged = itemAliasNamesFrom([
    ...(state.item.aliases || []),
    ...pending,
  ]);
  if (sameAliasNames(merged, state.item.aliases)) return false;
  setItemAliases(merged);
  return true;
}

function removeItemAlias(alias) {
  if (!state.item || suppressItemDirty) return;
  const target = String(alias || "").trim().toLowerCase();
  if (!target) return;
  const next = itemAliasNamesFrom(state.item.aliases)
    .filter((name) => name.toLowerCase() !== target);
  setItemAliases(next);
  markItemDirty();
}

let itemDirty = false;
let suppressItemDirty = false;
let itemAutoSaveTimer = 0;
let itemAutoSaveInFlight = false;
const ITEM_AUTOSAVE_MS = 800;
const ITEM_EDITOR_FIELD_IDS = ["itemName", "itemDescription", "itemOwner"];

function setItemSaveStatus(text) {
  if ($("itemInfo")) $("itemInfo").textContent = text || "";
}

function markItemDirty() {
  if (suppressItemDirty) return;
  itemDirty = true;
  scheduleItemAutoSave();
}

function cancelItemAutoSave() {
  if (itemAutoSaveTimer) {
    window.clearTimeout(itemAutoSaveTimer);
    itemAutoSaveTimer = 0;
  }
}

function scheduleItemAutoSave() {
  if (!state.itemId || !state.item) return;
  cancelItemAutoSave();
  itemAutoSaveTimer = window.setTimeout(() => {
    itemAutoSaveTimer = null;
    persistItem({ quiet: true }).catch(handleError);
  }, ITEM_AUTOSAVE_MS);
}

function currentItemAliasNames() {
  const fromState = itemAliasNamesFrom(state.item?.aliases);
  const pending = splitAliasInput($("newItemAlias")?.value || "");
  const seen = new Set(fromState.map((name) => name.toLowerCase()));
  const names = fromState.slice();
  pending.forEach((name) => {
    const key = name.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    names.push(name);
  });
  return names;
}

function itemEditorPayload() {
  const ownerRaw = $("itemOwner")?.value || "";
  return {
    name: String($("itemName")?.value || "").trim(),
    description: String($("itemDescription")?.value || ""),
    owner_character_id: ownerRaw ? Number(ownerRaw) : null,
    aliases: currentItemAliasNames(),
    row_version: state.item?.item?.row_version,
  };
}

function syncItemToriBadges(item) {
  const pending = item?.tori_analysis && typeof item.tori_analysis === "object"
    ? item.tori_analysis
    : {};
  document.querySelectorAll(".item-analysis-badge").forEach((button) => {
    const field = button.getAttribute("data-item-tori-field");
    const has = Boolean(field && pending[field]?.content);
    button.classList.toggle("hidden", !has);
  });
}

function syncItemToriDraftStyle() {
  const el = $("itemDescription");
  if (el) applyToriDraftClass(el);
}

async function persistItem(options = {}) {
  const quiet = Boolean(options.quiet);
  const itemId = options.itemId ?? state.itemId;
  if (!itemId || (!state.item && !options.payload)) return;
  if (!options.payload) commitItemAliasInputToState();
  const payload = options.payload || itemEditorPayload();
  if (!payload.name) {
    setItemSaveStatus(i18n.t("app.이름을_입력해야_저장됩니다"));
    if (!quiet) toast(i18n.t("app.아이템_이름을_적어_주세요"));
    return;
  }
  if (itemAutoSaveInFlight) {
    if (quiet && !options.payload) {
      scheduleItemAutoSave();
      return;
    }
    for (let i = 0; i < 40 && itemAutoSaveInFlight; i += 1) {
      await new Promise((r) => window.setTimeout(r, 50));
    }
  }
  itemAutoSaveInFlight = true;
  if (quiet) setItemSaveStatus(i18n.t("app.자동_저장_중"));
  try {
    await api(`/api/items/${itemId}`, {
      method: "PUT",
      body: JSON.stringify(payload),
    });
    itemDirty = false;
    if (Number(state.itemId) === Number(itemId) && state.item?.item) {
      state.item.item = { ...state.item.item, ...payload };
      setItemAliases(payload.aliases, { render: true });
    }
    const stamp = new Date().toLocaleTimeString("ko-KR", { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    setItemSaveStatus(
      quiet
        ? `${i18n.t("app.자동_저장됨_stamp", { stamp })}`
        : `${i18n.t("app.저장됨_stamp", { stamp })}`,
    );
    if (!quiet) toast(i18n.t("app.아이템_설정을_저장했습니다"));
    try {
      const items = await api(`/api/projects/${state.projectId}/items`);
      if (Array.isArray(items)) state.items = items;
    } catch (_) {
      /* keep local list */
    }
    renderItems();
    if (state.itemBoardOpen) renderItemBoard();
  } catch (error) {
    if (quiet) {
      setItemSaveStatus(i18n.t("app.자동_저장_실패_다시_시도"));
      scheduleItemAutoSave();
    }
    throw error;
  } finally {
    itemAutoSaveInFlight = false;
  }
}

async function flushItemAutoSave() {
  const hasPendingAlias = Boolean(String($("newItemAlias")?.value || "").trim());
  const shouldSave = itemDirty || hasPendingAlias;
  cancelItemAutoSave();
  if (itemAutoSaveInFlight) {
    for (let i = 0; i < 40 && itemAutoSaveInFlight; i += 1) {
      await new Promise((r) => window.setTimeout(r, 50));
    }
  }
  if (!shouldSave || !state.itemId) return;
  await persistItem({ quiet: true });
}

function setupItemEditorAutosave() {
  const form = $("itemEditor");
  if (!form || form.dataset.autosaveBound === "1") return;
  form.dataset.autosaveBound = "1";
  ITEM_EDITOR_FIELD_IDS.forEach((id) => {
    const el = $(id);
    if (!el) return;
    el.addEventListener("input", (event) => {
      if (id === "itemDescription") claimToriDraftOnInput(el, event);
      markItemDirty();
    });
    el.addEventListener("change", markItemDirty);
    if (id === "itemDescription") {
      el.addEventListener("compositionend", () => {
        if (claimToriDraftOnInput(el)) markItemDirty();
      });
    }
    el.addEventListener("blur", () => {
      if (!itemDirty) return;
      cancelItemAutoSave();
      persistItem({ quiet: true }).catch(handleError);
    });
  });
  const aliasInput = $("newItemAlias");
  if (aliasInput) {
    aliasInput.addEventListener("input", markItemDirty);
    aliasInput.addEventListener("change", markItemDirty);
    aliasInput.addEventListener("blur", () => {
      commitItemAliasInputToState();
      if (!itemDirty) return;
      cancelItemAutoSave();
      persistItem({ quiet: true }).catch(handleError);
    });
  }
}

async function createItem(presetName = "") {
  if (!state.projectId) return toast(i18n.t("app.먼저_새_작품을_만들어_주세요"));
  const name = presetName
    ? String(presetName).trim()
    : await promptText({
      title: i18n.t("app.아이템_만들기"),
      message: i18n.t("app.아이템_이름을_적어_주세요"),
      label: i18n.t("app.이름"),
      defaultValue: i18n.t("app.새_아이템"),
      confirmLabel: i18n.t("app.만들기"),
    });
  if (name === null) return null;
  const created = await api(`/api/projects/${state.projectId}/items`, {
    method: "POST",
    body: JSON.stringify({ name: String(name).trim() || i18n.t("app.새_아이템") }),
  });
  state.openSettingsSection = "items";
  await loadProject();
  await openItem(created.id);
  toast(i18n.t("app.아이템_설정을_적어_보세요"));
  return created;
}

async function openItem(itemId) {
  if (typeof isGlumpSprintActive === "function" && isGlumpSprintActive() && !confirmLeaveGlumpSprint()) {
    return;
  }
  const nextId = Number(itemId);
  if (state.itemId && Number(state.itemId) !== nextId) {
    try {
      await flushItemAutoSave();
    } catch (_) {
      /* keep going */
    }
  }
  try {
    await flushCharacterAutoSave();
  } catch (_) {
    /* continue */
  }
  await closeSplitView();
  if (sceneDirty && state.sceneId) {
    try {
      await persistScene({ quiet: true, saveNote: i18n.t("app.자동_저장") });
    } catch (_) {
      /* keep going */
    }
  }
  state.ideaBoardOpen = false;
  state.characterBoardOpen = false;
  state.itemBoardOpen = false;
  state.keywordBoardOpen = false;
  $("ideaBoard")?.classList.add("hidden");
  $("keywordBoard")?.classList.add("hidden");
  $("characterBoard")?.classList.add("hidden");
  hideRelationCanvas();
  $("characterEditor")?.classList.add("hidden");
  $("itemBoard")?.classList.add("hidden");
  hideSynopsisMain();
  hideGitsiWorkspace();
  hideSettingsSearchBoard();
  state.itemId = nextId;
  state.item = await api(`/api/items/${itemId}`);
  const item = state.item.item;
  setActiveBinder("settings");
  state.openSettingsSection = "items";
  applySettingsSectionState();
  $("welcome").classList.add("hidden");
  $("sceneWorkspace").classList.add("hidden");
  $("itemEditor").classList.remove("hidden");
  closeSceneToolsDrawer();
  suppressItemDirty = true;
  cancelItemAutoSave();
  itemDirty = false;
  if ($("itemName")) $("itemName").value = item.name || "";
  if ($("itemDescription")) $("itemDescription").value = item.description || "";
  fillItemOwnerSelect(item.owner_character_id);
  state.item.aliases = Array.isArray(state.item.aliases)
    ? state.item.aliases.map((entry) => ({ ...entry }))
    : [];
  if ($("newItemAlias")) $("newItemAlias").value = "";
  renderItemAliasList(state.item.aliases);
  setItemSaveStatus("");
  suppressItemDirty = false;
  syncItemToriBadges(item);
  syncItemToriDraftStyle();
  resetItemChronicle();
  setupItemEditorAutosave();
  await loadProject();
}

async function saveItem(event) {
  event.preventDefault();
  cancelItemAutoSave();
  await persistItem({ quiet: false });
}

async function deleteItem() {
  if (!state.itemId || !state.item?.item) return;
  const name = String(state.item.item.name || i18n.t("app.이_아이템")).trim() || i18n.t("app.이_아이템");
  const ok = window.confirm(`「${name}」 아이템을 삭제할까요?\n\n목록에서 사라집니다.`);
  if (!ok) return;
  cancelItemAutoSave();
  itemDirty = false;
  await api(`/api/items/${state.itemId}`, { method: "DELETE" });
  state.itemId = null;
  state.item = null;
  $("itemEditor")?.classList.add("hidden");
  await loadProject();
  await openItemBoard();
  toast(`${i18n.t("app.name_을_를_삭제했어요", { name })}`);
}

async function addItemAlias() {
  if (!state.itemId || !state.item) return;
  const added = commitItemAliasInputToState();
  if (!added) return;
  cancelItemAutoSave();
  await persistItem({ quiet: true });
  toast(i18n.t("app.별칭을_추가했습니다"));
}

function openItemAnalysisModal(fieldName) {
  const item = state.item?.item;
  const pending = item?.tori_analysis && typeof item.tori_analysis === "object"
    ? item.tori_analysis
    : {};
  const entry = pending[fieldName];
  if (!entry?.content) {
    toast(i18n.t("app.보여줄_토리_분석이_없어요"));
    return;
  }
  characterAnalysisKind = "item";
  characterAnalysisField = fieldName;
  fillAnalysisModal(i18n.t("app.아이템_설명"), entry.content);
}

async function applyItemToriAnalysis() {
  if (!state.itemId || !characterAnalysisField) return;
  const ok = window.confirm(
    `「${i18n.t("app.아이템_설명")}」을(를) 토리 분석으로 바꿀까요?\n지금 적어 둔 내용은 사라집니다.`,
  );
  if (!ok) return;
  const result = await api(`/api/items/${state.itemId}/tori-analysis/apply`, {
    method: "POST",
    body: JSON.stringify({ field_name: characterAnalysisField }),
  });
  closeCharacterAnalysisModal();
  state.item = result;
  const item = result?.item;
  if (item && $("itemDescription")) $("itemDescription").value = item.description || "";
  if (Array.isArray(result?.aliases)) setItemAliases(result.aliases);
  syncItemToriBadges(item);
  syncItemToriDraftStyle();
  await loadProject();
  toast(i18n.t("app.토리_분석으로_바꿨어요"));
}

let sceneItemCandidates = [];
let sceneItemDismissedCandidates = new Set();
let sceneItemAnalysisWatchTimer = 0;
let sceneItemAnalysisWatchSceneId = 0;

function stopSceneItemAnalysisWatch() {
  if (sceneItemAnalysisWatchTimer) {
    window.clearInterval(sceneItemAnalysisWatchTimer);
    sceneItemAnalysisWatchTimer = 0;
  }
  sceneItemAnalysisWatchSceneId = 0;
}

function renderSceneItemCandidates() {
  const panel = $("sceneItemCandidatePanel");
  const list = $("sceneItemCandidateList");
  const statusEl = $("sceneItemCandidateStatus");
  if (!panel || !list) return;
  const names = sceneItemCandidates.filter(
    (name) => !sceneItemDismissedCandidates.has(String(name).toLowerCase()),
  );
  panel.classList.toggle("hidden", !names.length);
  if (statusEl) statusEl.textContent = "";
  if (!names.length) {
    list.innerHTML = "";
    return;
  }
  list.innerHTML = names.map((name) => {
    const safe = escapeHtml(name);
    const token = encodeURIComponent(name);
    return `<div class="scene-cast-candidate-row">
      <span class="scene-cast-name" title="${safe}">${safe}</span>
      <button type="button" class="secondary compact-btn" data-add-item-candidate="${token}">${i18n.t("index.아이템으로_등록")}</button>
    </div>`;
  }).join("");
}

async function addSceneItemCandidate(name) {
  const displayName = String(name || "").trim();
  if (!displayName || !state.projectId) return;
  const created = await api(`/api/projects/${state.projectId}/items`, {
    method: "POST",
    body: JSON.stringify({ name: displayName }),
  });
  if (!created?.id) return;
  sceneItemDismissedCandidates.add(displayName.toLowerCase());
  sceneItemCandidates = sceneItemCandidates.filter(
    (item) => String(item).toLowerCase() !== displayName.toLowerCase(),
  );
  renderSceneItemCandidates();
  await loadProject();
  toast(i18n.t("app.names_을_를_아이템으로_저장했어요", { names: displayName }));
}

function showItemTraitToast(entry) {
  const name = String(entry?.name || i18n.t("app.이_아이템"));
  const itemId = Number(entry?.id);
  const openSheet = () => {
    if (Number.isFinite(itemId) && itemId > 0) openItem(itemId).catch(handleError);
  };
  toast(
    i18n.t("app.name_의_아이템_설정에_새로운_내용이_추가됐어요", { name }),
    4200,
    {
      dismissible: true,
      action: { label: i18n.t("app.아이템_설정_열기"), onClick: openSheet },
      onClick: openSheet,
    },
  );
}

function watchSceneItemAnalysis(sceneId) {
  const id = Number(sceneId);
  if (!Number.isFinite(id) || id <= 0) return;
  stopSceneItemAnalysisWatch();
  sceneItemAnalysisWatchSceneId = id;
  const startedAt = Date.now();
  const tick = async () => {
    if (sceneItemAnalysisWatchSceneId !== id) return;
    try {
      const job = await api(`/api/scenes/${id}/item-analysis`);
      const status = String(job?.status || "idle");
      if (status === "running") return;
      if (status === "idle" && Date.now() - startedAt < 8000) return;
      stopSceneItemAnalysisWatch();
      const candidates = Array.isArray(job?.candidates) ? job.candidates : [];
      sceneItemCandidates = candidates.filter((name) => {
        const key = String(name || "").trim().toLowerCase();
        return key && !sceneItemDismissedCandidates.has(key);
      });
      renderSceneItemCandidates();
      if (status === "done") {
        const items = Array.isArray(job?.items) ? job.items : [];
        items.forEach((entry) => {
          if (entry?.filled || entry?.pending) showItemTraitToast(entry);
        });
        if (state.itemId && !$("itemEditor")?.classList.contains("hidden")) {
          const touched = items.some((entry) => Number(entry.id) === Number(state.itemId));
          if (touched) {
            try {
              await openItem(state.itemId);
            } catch (_) {
              /* ignore */
            }
          }
        }
      }
    } catch (_) {
      if (Date.now() - startedAt > 90000) stopSceneItemAnalysisWatch();
    }
  };
  sceneItemAnalysisWatchTimer = window.setInterval(() => {
    tick().catch(() => { /* keep quiet */ });
  }, 1200);
  tick().catch(() => { /* keep quiet */ });
}

function bindSettingsDocSidebarInput(kind) {
  const meta = getSettingsDocMeta(kind);
  if (kind === "world") {
    bindWorldBuildingFormInputs();
    return;
  }
  const el = $(meta.sidebarId);
  if (!el || el.dataset.settingsBound === "1") return;
  el.dataset.settingsBound = "1";
  const pushToStateAndMaybeMain = () => {
    state[meta.stateKey] = el.value;
    // Keep main editor in sync when the same document is open on the main pane.
    const main = getSettingsDocMainEditor(kind);
    if (isSettingsDocMainOpen() && main) {
      if (document.activeElement === main) {
        // Main has focus — don't clobber; state still updated for save.
      } else {
        suppressSynopsisDirty = true;
        setEditorContent(el.value, main);
        suppressSynopsisDirty = false;
      }
    }
  };
  el.addEventListener("input", () => {
    autoResizeSettingsSidebarTextarea(el, { shrink: false });
    pushToStateAndMaybeMain();
    scheduleSettingsDocAutoSave(kind);
  });
  // Blur/change flush — catches last keystrokes before leaving the field.
  el.addEventListener("change", () => {
    pushToStateAndMaybeMain();
    scheduleSettingsDocAutoSave(kind);
  });
  el.addEventListener("blur", () => {
    autoResizeSettingsSidebarTextarea(el);
    pushToStateAndMaybeMain();
    persistSettingsDoc(kind, { quiet: true }).catch(handleError);
  });
}

function bindWorldBuildingFormRoot(form) {
  if (!form || form.dataset.settingsBound === "1") return;
  form.dataset.settingsBound = "1";
  fillWorldBuildingExamplePlaceholders();
  const syncFromThisForm = () => {
    const values = readWorldBuildingFormValuesFrom(form);
    const md = composeWorldbuildingMd(values);
    worldbuildingExampleDraft = false;
    state.worldbuildingMd = md;
    synopsisDirty = true;
    const serialized = $("projectWorldbuilding");
    if (serialized) serialized.value = md;
    for (const other of worldBuildingFormRoots()) {
      if (other === form) continue;
      applyWorldBuildingValuesToFormRoot(other, values, { force: false });
    }
    return md;
  };
  form.addEventListener("input", (event) => {
    const el = event.target?.closest?.("[data-world-field]");
    if (!el) return;
    autoResizeSettingsSidebarTextarea(el, { shrink: false });
    claimToriDraftOnInput(el, event);
    syncFromThisForm();
    scheduleSettingsDocAutoSave("world");
    if (isWorldbuildingMainOpen()) setWorldbuildingSaveStatus(i18n.t('app.저장_대기_중'));
  });
  form.addEventListener("compositionend", (event) => {
    const el = event.target?.closest?.("[data-world-field]");
    if (!el) return;
    if (claimToriDraftOnInput(el)) syncFromThisForm();
  });
  form.addEventListener("change", (event) => {
    if (!event.target?.closest?.("[data-world-field]")) return;
    syncFromThisForm();
    scheduleSettingsDocAutoSave("world");
  });
  form.addEventListener("blur", (event) => {
    const el = event.target?.closest?.("[data-world-field]");
    if (!el) return;
    autoResizeSettingsSidebarTextarea(el);
    syncFromThisForm();
    persistSettingsDoc("world", { quiet: true }).catch(handleError);
  }, true);
}

function bindWorldBuildingFormInputs() {
  bindWorldBuildingFormRoot($("worldbuildingForm"));
}

function bindWorldBuildingMainFormInputs() {
  ensureWorldbuildingMainForm();
  bindWorldBuildingFormRoot($("worldbuildingMainForm"));
}

function setupSettingsCodex() {
  // Open section is restored per project in loadProject (not a global default).
  if (state.projectId) restoreOpenSettingsSection(state.projectId);
  document.querySelectorAll("[data-settings-toggle]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const key = button.dataset.settingsToggle;
      if (key) setOpenSettingsSection(key);
    });
  });
  /* Also allow clicking the header chrome (outside toggle/main) to expand */
  document.querySelectorAll(".settings-box-header").forEach((header) => {
    header.addEventListener("click", (event) => {
      if (event.target.closest("[data-settings-main]")) return;
      if (event.target.closest("[data-settings-toggle]")) return;
      const box = header.closest(".settings-box");
      const key = box?.dataset?.settingsSection;
      if (key) setOpenSettingsSection(key);
    });
  });
  /* Circle → icon: open this settings section on the main workspace */
  document.querySelectorAll("[data-settings-main]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const key = button.dataset.settingsMain;
      const meta = SETTINGS_BOOKMARK_META[key];
      if (!meta?.open) return;
      Promise.resolve(meta.open()).catch(handleError);
    });
  });
  document.querySelectorAll("[data-open-settings-doc]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const kind = button.dataset.openSettingsDoc;
      if (!kind) return;
      // Snapshot this field (+ siblings) before opening main.
      pullSettingsDocFamilyFromSidebar(kind);
      openSettingsDocMain(kind).catch(handleError);
    });
  });
  document.querySelectorAll("[data-save-settings-doc]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const kind = button.dataset.saveSettingsDoc;
      if (!kind) return;
      // Snapshot textarea into state immediately, then save (psychological + real).
      pullSettingsDocFromSidebar(kind);
      persistSettingsDoc(kind, { quiet: false })
        .then(() => {
          // If main is showing this doc, force-refresh from state.
          syncSettingsDocMainFromState(kind);
        })
        .catch(handleError);
    });
  });
  $("saveSynopsisMainButton")?.addEventListener("click", () => {
    const kinds = state.settingsDocPair?.length
      ? state.settingsDocPair
      : [state.settingsDocKind || "synopsis"];
    persistSettingsDocPair(kinds, { quiet: false }).catch(handleError);
  });
  $("closeSynopsisMainButton")?.addEventListener("click", () => closeSynopsisMain().catch(handleError));
  $("saveWorldbuildingMainButton")?.addEventListener("click", () => {
    pushWorldBuildingFormToState({ commitDraft: true });
    persistSettingsDoc("world", { quiet: false }).catch(handleError);
  });
  $("closeWorldbuildingMainButton")?.addEventListener("click", () => closeSynopsisMain().catch(handleError));
  $("worldPreview")?.addEventListener("dblclick", () => openSettingsDocMain("world").catch(handleError));
  $("charactersPreview")?.addEventListener("dblclick", () => openCharacterBoard().catch(handleError));
  $("itemsPreview")?.addEventListener("dblclick", () => openItemBoard().catch(handleError));
  $("keywordsPreview")?.addEventListener("dblclick", () => openKeywordBoard());
  $("closeCharacterBoardButton")?.addEventListener("click", () => closeCharacterBoard().catch(handleError));
  $("openRelationCanvasButton")?.addEventListener("click", () => openRelationCanvas().catch(handleError));
  $("openRelationCanvasMainButton")?.addEventListener("click", () => openRelationCanvas().catch(handleError));
  $("closeCharacterEditorButton")?.addEventListener("click", () => closeCharacterEditor().catch(handleError));
  $("newCharacterMainButton")?.addEventListener("click", () => createCharacter().catch(handleError));
  $("closeItemBoardButton")?.addEventListener("click", () => closeItemBoard().catch(handleError));
  $("closeItemEditorButton")?.addEventListener("click", () => closeItemEditor().catch(handleError));
  $("newItemMainButton")?.addEventListener("click", () => createItem().catch(handleError));
  $("deleteItemButton")?.addEventListener("click", () => deleteItem().catch(handleError));
  bindSettingsSearchEvents();
  setupCharacterBoardViewControls();
  bindSettingsDocSidebarInput("intro");
  bindSettingsDocSidebarInput("intent");
  bindSettingsDocSidebarInput("synopsis");
  bindSettingsDocSidebarInput("logline");
  bindSettingsDocSidebarInput("world");
  ensureWorldbuildingMainForm();
  bindWorldBuildingMainFormInputs();
  // Migrate stored open section keys (in-memory / already restored)
  if (state.openSettingsSection === "synopsis" || state.openSettingsSection === "logline") {
    state.openSettingsSection = "logsyn";
  }
  setupSettingsSectionDrag();
  applySettingsSectionOrder();
  applySettingsSectionState();
  setupLinkedSuccessProfileCard();
  renderLinkedSuccessProfileCard().catch(() => {});
}

const IDEA_COLORS = [
  { key: "yellow", label: i18n.t('app.노랑') },
  { key: "pink", label: i18n.t('app.분홍') },
  { key: "blue", label: i18n.t('app.파랑') },
  { key: "green", label: i18n.t('app.초록') },
  { key: "orange", label: i18n.t('app.주황') },
  { key: "purple", label: i18n.t('app.보라') },
];

function ideaPreview(text, max = 90) {
  const cleaned = String(text || "").replace(/\s+/g, " ").trim();
  if (!cleaned) return i18n.t('app.내용을_적어_보세요');
  return cleaned.length > max ? `${cleaned.slice(0, max)}…` : cleaned;
}

function ideaIsPinned(idea) {
  if (Boolean(Number(idea?.is_pinned))) return true;
  try {
    const map = loadLocalIdeaPins();
    return Boolean(map[String(idea?.id)]);
  } catch (_) {
    return false;
  }
}

function ideaPinStorageKey() {
  return `supertory.ideaPins.v1.${state.projectId || 0}`;
}

function loadLocalIdeaPins() {
  try {
    const raw = localStorage.getItem(ideaPinStorageKey());
    const parsed = raw ? JSON.parse(raw) : {};
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch (_) {
    return {};
  }
}

function saveLocalIdeaPin(ideaId, pinned) {
  try {
    const map = loadLocalIdeaPins();
    const key = String(ideaId);
    if (pinned) map[key] = 1;
    else delete map[key];
    localStorage.setItem(ideaPinStorageKey(), JSON.stringify(map));
  } catch (_) {
    /* ignore */
  }
}

/** 오른쪽→왼쪽 아래로 꽂힌 압정 (테두리 없는 아이콘 전용) */
function ideaPinGlyphHtml(size = 18) {
  const s = Math.max(12, Number(size) || 18);
  return (
    `<svg class="idea-pin-glyph" viewBox="0 0 24 24" width="${s}" height="${s}" aria-hidden="true" focusable="false">`
    + `<g transform="rotate(42 12 13)">`
    + `<path fill="currentColor" d="M12 2.55c2.1 0 3.8 1.7 3.8 3.8 0 1.25-.62 2.35-1.55 3.02l1.15 3.4c.4 1.2-.46 2.45-1.72 2.63l-1.18.17V20.3a1 1 0 1 1-2 0v-4.73l-1.18-.17c-1.26-.18-2.12-1.43-1.72-2.63l1.15-3.4A3.78 3.78 0 0 1 8.2 6.35C8.2 4.25 9.9 2.55 12 2.55zm0 1.9a1.9 1.9 0 1 0 .02 3.8 1.9 1.9 0 0 0-.02-3.8z"/>`
    + `</g></svg>`
  );
}

function renderIdeaBank() {
  const list = $("ideaNoteList");
  if (!list) return;
  if (!state.projectId) {
    list.innerHTML = i18n.t('app.p_class_idea_sticky_emp');
    if ($("newIdeaButton")) $("newIdeaButton").disabled = true;
    renderHeaderIdeaBar();
    return;
  }
  if ($("newIdeaButton")) $("newIdeaButton").disabled = false;
  if (!state.ideas.length) {
    list.innerHTML = i18n.t('app.p_class_idea_sticky_emp_2');
  } else {
    list.innerHTML = state.ideas.map((idea) => {
      const pinned = ideaIsPinned(idea);
      return `
      <button type="button" class="idea-sticky color-${escapeHtml(idea.color || "yellow")}${pinned ? " is-pinned" : ""}" data-idea="${idea.id}" title="${escapeHtml(idea.title || "메모")}${pinned ? " · 목차 하단 고정" : ""}">
        ${pinned ? `<span class="idea-sticky-pin" title="목차 하단 고정">${ideaPinGlyphHtml(16)}</span>` : ""}
        <span class="idea-sticky-title">${escapeHtml((!idea.title || idea.title === "새 메모") ? i18n.t('app.새_메모') : idea.title)}</span>
        <span class="idea-sticky-body">${escapeHtml(ideaPreview(idea.body_md))}</span>
      </button>`;
    }).join("");
    list.querySelectorAll("[data-idea]").forEach((button) => {
      button.addEventListener("click", () => openIdeaBoard(Number(button.dataset.idea)));
    });
  }
  if (state.ideaBoardOpen) renderIdeaBoard();
  renderSettingsCodex();
  renderHeaderIdeaBar();
}

function hideCenterViewsForIdeaBoard() {
  void flushCharacterAutoSave();
  $("welcome").classList.add("hidden");
  $("sceneWorkspace").classList.add("hidden");
  $("characterEditor").classList.add("hidden");
  hideItemViews();
  hideSynopsisMain();
  hideCharacterBoard();
  hideRelationCanvas();
  hideKeywordBoard();
  hideSettingsCollectionBoard();
  hideGitsiWorkspace();
  hideSettingsSearchBoard();
  $("ideaBoard").classList.remove("hidden");
  closeSceneToolsDrawer();
  void closeSplitView();
}

async function closeIdeaBoard() {
  try {
    await flushIdeaCardAutosaves();
  } catch (_) {
    /* continue */
  }
  state.ideaBoardOpen = false;
  $("ideaBoard").classList.add("hidden");
  await returnToManuscriptFromSettingsMain();
}

function openIdeaBoard(focusId = null) {
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  if (typeof isGlumpSprintActive === "function" && isGlumpSprintActive() && !confirmLeaveGlumpSprint()) {
    return;
  }
  state.ideaBoardOpen = true;
  state.keywordBoardOpen = false;
  setActiveBinder("settings");
  hideCenterViewsForIdeaBoard();
  renderIdeaBoard(focusId);
}

const IDEA_CARD_SIZE_PREFIX = "supertory.ideaCardSize.v1.";
const IDEA_CARD_DEFAULT_W = 354;
const IDEA_CARD_DEFAULT_H = 260;
const IDEA_CARD_MIN_W = 180;
const IDEA_CARD_MIN_H = 140;
const IDEA_CARD_MAX_W = 900;
const IDEA_CARD_MAX_H = 900;

function ideaCardSizeKey(ideaId) {
  const project = state.projectId != null ? Number(state.projectId) : 0;
  return `${IDEA_CARD_SIZE_PREFIX}${project}.${Number(ideaId) || 0}`;
}

function loadIdeaCardSize(ideaId) {
  try {
    const raw = localStorage.getItem(ideaCardSizeKey(ideaId));
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    const w = Math.round(Number(parsed?.w));
    const h = Math.round(Number(parsed?.h));
    if (!Number.isFinite(w) || !Number.isFinite(h)) return null;
    return {
      w: Math.min(IDEA_CARD_MAX_W, Math.max(IDEA_CARD_MIN_W, w)),
      h: Math.min(IDEA_CARD_MAX_H, Math.max(IDEA_CARD_MIN_H, h)),
    };
  } catch (_) {
    return null;
  }
}

function saveIdeaCardSize(ideaId, width, height) {
  const w = Math.round(Number(width));
  const h = Math.round(Number(height));
  if (!Number.isFinite(w) || !Number.isFinite(h)) return;
  try {
    localStorage.setItem(
      ideaCardSizeKey(ideaId),
      JSON.stringify({
        w: Math.min(IDEA_CARD_MAX_W, Math.max(IDEA_CARD_MIN_W, w)),
        h: Math.min(IDEA_CARD_MAX_H, Math.max(IDEA_CARD_MIN_H, h)),
      }),
    );
  } catch (_) {
    /* quota */
  }
}

function clearIdeaCardSize(ideaId) {
  try {
    localStorage.removeItem(ideaCardSizeKey(ideaId));
  } catch (_) {
    /* ignore */
  }
}

function applyIdeaCardSize(card, ideaId) {
  if (!card) return;
  const saved = loadIdeaCardSize(ideaId);
  const w = saved?.w || IDEA_CARD_DEFAULT_W;
  const h = saved?.h || IDEA_CARD_DEFAULT_H;
  card.style.width = `${w}px`;
  card.style.height = `${h}px`;
}

/**
 * Watch card box size (native CSS resize: both) and persist per idea.
 * Also supports optional custom corner drag via data-role="idea-resize".
 */
function bindIdeaCardResize(card, ideaId) {
  if (!card || !ideaId) return;
  // Avoid stacking observers if re-bound (e.g. color change)
  if (card._ideaResizeObserver) {
    try { card._ideaResizeObserver.disconnect(); } catch (_) { /* ignore */ }
    card._ideaResizeObserver = null;
  }
  applyIdeaCardSize(card, ideaId);

  let saveTimer = null;
  const persist = () => {
    const rect = card.getBoundingClientRect();
    if (rect.width < 40 || rect.height < 40) return;
    saveIdeaCardSize(ideaId, rect.width, rect.height);
  };
  const schedulePersist = () => {
    if (saveTimer) window.clearTimeout(saveTimer);
    saveTimer = window.setTimeout(persist, 120);
  };

  if (typeof ResizeObserver !== "undefined") {
    const ro = new ResizeObserver(() => {
      card.classList.add("is-resizing");
      schedulePersist();
      window.clearTimeout(card._ideaResizeClassTimer);
      card._ideaResizeClassTimer = window.setTimeout(() => {
        card.classList.remove("is-resizing");
      }, 180);
    });
    ro.observe(card);
    card._ideaResizeObserver = ro;
  } else {
    card.addEventListener("mouseup", persist);
  }

  // Custom drag handle (works even when native resize corner is hard to grab)
  const handle = card.querySelector('[data-role="idea-resize"]');
  if (handle && handle.dataset.bound !== "1") {
    handle.dataset.bound = "1";
    handle.addEventListener("pointerdown", (event) => {
      if (event.button != null && event.button !== 0) return;
      event.preventDefault();
      event.stopPropagation();
      const startX = event.clientX;
      const startY = event.clientY;
      const startW = card.offsetWidth;
      const startH = card.offsetHeight;
      card.classList.add("is-resizing");
      const onMove = (ev) => {
        const dw = ev.clientX - startX;
        const dh = ev.clientY - startY;
        const nextW = Math.min(IDEA_CARD_MAX_W, Math.max(IDEA_CARD_MIN_W, startW + dw));
        const nextH = Math.min(IDEA_CARD_MAX_H, Math.max(IDEA_CARD_MIN_H, startH + dh));
        card.style.width = `${nextW}px`;
        card.style.height = `${nextH}px`;
      };
      const onUp = () => {
        document.removeEventListener("pointermove", onMove);
        document.removeEventListener("pointerup", onUp);
        card.classList.remove("is-resizing");
        persist();
      };
      document.addEventListener("pointermove", onMove);
      document.addEventListener("pointerup", onUp);
      try { handle.setPointerCapture(event.pointerId); } catch (_) { /* ignore */ }
    });
  }

  const resetBtn = card.querySelector('[data-role="reset-idea-size"]');
  if (resetBtn && resetBtn.dataset.bound !== "1") {
    resetBtn.dataset.bound = "1";
    resetBtn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      clearIdeaCardSize(ideaId);
      card.style.width = `${IDEA_CARD_DEFAULT_W}px`;
      card.style.height = `${IDEA_CARD_DEFAULT_H}px`;
      toast(i18n.t('app.메모_크기를_기본값으로_돌렸어요'));
    });
  }
}

const ideaCardSaveTimers = new Map();

function scheduleIdeaCardAutoSave(card) {
  const id = Number(card?.dataset?.ideaCard);
  if (!id) return;
  if (ideaCardSaveTimers.has(id)) window.clearTimeout(ideaCardSaveTimers.get(id));
  ideaCardSaveTimers.set(id, window.setTimeout(() => {
    ideaCardSaveTimers.delete(id);
    saveIdeaFromCard(card, { quiet: true }).catch(handleError);
  }, 900));
}

function patchIdeaBankPreview(idea) {
  if (!idea?.id) return;
  const btn = document.querySelector(`[data-idea="${idea.id}"]`);
  if (!btn) return;
  const colorKey = IDEA_COLORS.some((c) => c.key === idea.color) ? idea.color : "yellow";
  const pinned = ideaIsPinned(idea);
  btn.className = `idea-sticky color-${colorKey}${pinned ? " is-pinned" : ""}`;
  const titleEl = btn.querySelector(".idea-sticky-title");
  const bodyEl = btn.querySelector(".idea-sticky-body");
  if (titleEl) {
    titleEl.textContent = (!idea.title || idea.title === "새 메모") ? i18n.t("app.새_메모") : idea.title;
  }
  if (bodyEl) bodyEl.textContent = ideaPreview(idea.body_md);
}

async function flushIdeaCardAutosaves() {
  const pendingIds = new Set(ideaCardSaveTimers.keys());
  for (const timer of ideaCardSaveTimers.values()) window.clearTimeout(timer);
  ideaCardSaveTimers.clear();
  const grid = $("ideaBoardGrid");
  const activeCard = document.activeElement?.closest?.("[data-idea-card]");
  const activeId = Number(activeCard?.dataset?.ideaCard || 0);
  if (activeId) pendingIds.add(activeId);
  if (!grid || !pendingIds.size) return;
  const cards = [...pendingIds]
    .map((id) => grid.querySelector(`[data-idea-card="${id}"]`))
    .filter(Boolean);
  await Promise.all(cards.map((card) => saveIdeaFromCard(card, { quiet: true }).catch(() => {})));
}

function renderIdeaBoard(focusId = null) {
  const grid = $("ideaBoardGrid");
  if (!grid || !state.ideaBoardOpen) return;
  if (!state.ideas.length) {
    grid.innerHTML = i18n.t('app.p_class_hint_메모가_없습니다_메');
    return;
  }
  grid.innerHTML = state.ideas.map((idea) => {
    const colorKey = IDEA_COLORS.some((c) => c.key === idea.color) ? idea.color : "yellow";
    const pinned = ideaIsPinned(idea);
    const clipSwatches = IDEA_COLORS.map((c) => `
      <button
        type="button"
        class="idea-clip-swatch color-${escapeHtml(c.key)}${c.key === colorKey ? " is-active" : ""}"
        data-role="idea-clip"
        data-idea-color-pick="${escapeHtml(c.key)}"
        title="${escapeHtml(c.label)}"
        aria-label="메모 색 ${escapeHtml(c.label)}"
        aria-pressed="${c.key === colorKey ? "true" : "false"}"
      ></button>
    `).join("");
    return `
    <article
      class="idea-card color-${escapeHtml(colorKey)}${pinned ? " is-pinned" : ""}"
      data-idea-card="${idea.id}"
      data-idea-color="${escapeHtml(colorKey)}"
      data-idea-pinned="${pinned ? "1" : "0"}"
      title="${i18n.t('app.우클릭_메모_색_모서리_드래그_크기')}"
    >
      <div class="idea-card-clips" role="group" aria-label="${i18n.t('app.메모_색_클립')}">
        ${clipSwatches}
      </div>
      <div class="idea-card-top">
        <input type="text" data-role="idea-title" value="${escapeHtml((!idea.title || idea.title === "새 메모") ? i18n.t('app.새_메모') : idea.title)}" placeholder="${i18n.t('app.제목_예_결말_아이디어')}">
        <button
          type="button"
          class="idea-card-pin${pinned ? " is-on" : ""}"
          data-role="pin-idea"
          title="${pinned ? "목차 하단 고정 해제" : "목차 하단에 고정"}"
          aria-label="${pinned ? "목차 하단 고정 해제" : "목차 하단에 고정"}"
          aria-pressed="${pinned ? "true" : "false"}"
        >${ideaPinGlyphHtml(26)}</button>
      </div>
      <textarea data-role="idea-body" placeholder="${i18n.t('app.러프하게_적어_두세요')}">${escapeHtml(idea.body_md || "")}</textarea>
      <div class="idea-card-actions">
        <button type="button" class="idea-card-size-reset" data-role="reset-idea-size" title="${i18n.t('app.기본_크기로')}">${i18n.t('app.크기_초기화_버튼')}</button>
          <button type="button" data-role="save-idea" title="${escapeHtml(i18n.t("index.저장_자동_저장됨"))}">${i18n.t('app.저장')}</button>
        <button type="button" data-role="delete-idea">${i18n.t('app.삭제')}</button>
      </div>
      <button type="button" class="idea-card-resize-hint" data-role="idea-resize" title="${i18n.t('app.끌어서_크기_조절')}" aria-label="${i18n.t('app.메모_크기_조절')}"></button>
    </article>`;
  }).join("");

  grid.querySelectorAll("[data-idea-card]").forEach((card) => {
    const id = Number(card.dataset.ideaCard);
    bindIdeaCardResize(card, id);
    const titleEl = card.querySelector('[data-role="idea-title"]');
    const bodyEl = card.querySelector('[data-role="idea-body"]');
    titleEl?.addEventListener("input", () => scheduleIdeaCardAutoSave(card));
    bodyEl?.addEventListener("input", () => scheduleIdeaCardAutoSave(card));
    const flushIdeaCard = () => {
      if (ideaCardSaveTimers.has(id)) {
        window.clearTimeout(ideaCardSaveTimers.get(id));
        ideaCardSaveTimers.delete(id);
      }
      saveIdeaFromCard(card, { quiet: true }).catch(handleError);
    };
    titleEl?.addEventListener("blur", flushIdeaCard);
    bodyEl?.addEventListener("blur", flushIdeaCard);
    card.querySelector('[data-role="save-idea"]').addEventListener("click", () => {
      saveIdeaFromCard(card).catch(handleError);
    });
    card.querySelector('[data-role="delete-idea"]').addEventListener("click", () => {
      deleteIdea(id).catch(handleError);
    });
    card.querySelector('[data-role="pin-idea"]')?.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      toggleIdeaPin(id).catch(handleError);
    });
    card.querySelectorAll('[data-role="idea-clip"]').forEach((btn) => {
      btn.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const key = btn.dataset.ideaColorPick;
        if (!key) return;
        applyIdeaCardColor(card, key, { save: true });
        syncIdeaCardClips(card, key);
        toast(`${i18n.t('app.메모_색_IDEA_COLORS_find_c', {'IDEA_COLORS.find((c) => c.key === key)?.label || key': IDEA_COLORS.find((c) => c.key === key)?.label || key})}`);
      });
    });
  });

  if (focusId) {
    const focusCard = grid.querySelector(`[data-idea-card="${focusId}"]`);
    focusCard?.scrollIntoView({ behavior: "smooth", block: "nearest" });
    focusCard?.querySelector('[data-role="idea-body"]')?.focus();
  }
}

function applyIdeaCardColor(card, colorKey, { save = true } = {}) {
  if (!card || !colorKey) return;
  const key = IDEA_COLORS.some((c) => c.key === colorKey) ? colorKey : "yellow";
  const size = { w: card.offsetWidth, h: card.offsetHeight };
  card.dataset.ideaColor = key;
  card.className = `idea-card color-${key}`;
  card.style.width = `${size.w}px`;
  card.style.height = `${size.h}px`;
  syncIdeaCardClips(card, key);
  // Keep resize observer alive after className reset
  const id = Number(card.dataset.ideaCard);
  if (id) bindIdeaCardResize(card, id);
  if (save) {
    saveIdeaFromCard(card, { quiet: true }).catch(handleError);
  }
}

function syncIdeaCardClips(card, colorKey) {
  if (!card) return;
  const key = colorKey || card.dataset.ideaColor || "yellow";
  card.querySelectorAll('[data-role="idea-clip"]').forEach((btn) => {
    const active = btn.dataset.ideaColorPick === key;
    btn.classList.toggle("is-active", active);
    btn.setAttribute("aria-pressed", active ? "true" : "false");
  });
}

async function createIdeaNote() {
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  const colors = IDEA_COLORS.map((item) => item.key);
  const color = colors[state.ideas.length % colors.length];
  const idea = await api(`/api/projects/${state.projectId}/ideas`, {
    method: "POST",
    body: JSON.stringify({ title: i18n.t('app.새_메모'), body_md: "", color }),
  });
  state.ideas.push(idea);
  state.openSettingsSection = "ideas";
  renderIdeaBank();
  openIdeaBoard(idea.id);
  toast(i18n.t('app.새_포스트잇_메모를_만들었어요'));
}

async function toggleIdeaPin(ideaId) {
  const id = Number(ideaId);
  const index = state.ideas.findIndex((item) => item.id === id);
  if (index < 0) return;
  const nextPinned = !ideaIsPinned(state.ideas[index]);
  // 로컬 선반영 — 서버 마이그레이션 전이라도 하단 고정이 바로 보이게
  saveLocalIdeaPin(id, nextPinned);
  state.ideas[index] = { ...state.ideas[index], is_pinned: nextPinned ? 1 : 0 };
  try {
    const updated = await api(`/api/ideas/${id}`, {
      method: "PUT",
      body: JSON.stringify({ is_pinned: nextPinned ? 1 : 0 }),
    });
    state.ideas[index] = updated;
    saveLocalIdeaPin(id, Boolean(Number(updated?.is_pinned)));
  } catch (err) {
    // 서버에 컬럼이 아직 없으면 로컬 고정만 유지
    console.warn("[supertory] idea pin API failed; using local pin", err);
  }
  state.ideas.sort((a, b) => {
    const pinDiff = Number(ideaIsPinned(b)) - Number(ideaIsPinned(a));
    if (pinDiff) return pinDiff;
    return (Number(a.sort_order) || 0) - (Number(b.sort_order) || 0) || (a.id - b.id);
  });
  renderIdeaBank();
  toast(nextPinned ? i18n.t('app.목차_하단에_고정했어요') : i18n.t('app.목차_하단_고정을_해제했어요'));
}

async function saveIdeaFromCard(card, options = {}) {
  const quiet = Boolean(options.quiet);
  const id = Number(card.dataset.ideaCard);
  const title = card.querySelector('[data-role="idea-title"]')?.value || "";
  const body_md = card.querySelector('[data-role="idea-body"]')?.value || "";
  const color = card.dataset.ideaColor
    || (card.className.match(/color-(\w+)/) || [])[1]
    || "yellow";
  const updated = await api(`/api/ideas/${id}`, {
    method: "PUT",
    body: JSON.stringify({ title, body_md, color }),
  });
  const index = state.ideas.findIndex((item) => item.id === id);
  if (index >= 0) state.ideas[index] = updated;
  if (quiet) {
    patchIdeaBankPreview(updated);
    return;
  }
  renderIdeaBank();
  toast(i18n.t('app.메모를_저장했습니다'));
}

async function deleteIdea(id) {
  if (!window.confirm(i18n.t('app.이_메모를_삭제할까요'))) return;
  await api(`/api/ideas/${id}`, { method: "DELETE", body: JSON.stringify({}) });
  state.ideas = state.ideas.filter((item) => item.id !== id);
  renderIdeaBank();
  if (state.ideaBoardOpen) renderIdeaBoard();
  toast(i18n.t('app.메모를_삭제했습니다'));
}

function setupIdeaBank() {
  $("newIdeaButton")?.addEventListener("click", () => createIdeaNote().catch(handleError));
  $("ideaBoardAddButton")?.addEventListener("click", () => createIdeaNote().catch(handleError));
  $("ideaBoardCloseButton")?.addEventListener("click", () => closeIdeaBoard().catch(handleError));
}

async function refreshAiStatus() {
  const setAiEnabled = (on) => {
    if ($("aiSubmitButton")) $("aiSubmitButton").disabled = !on;
    if ($("toryChatSendButton")) $("toryChatSendButton").disabled = !on;
    if ($("toryChatInput")) $("toryChatInput").disabled = !on;
  };
  const setAdminGemini = (statusText, modelText) => {
    if ($("adminGeminiStatus")) $("adminGeminiStatus").textContent = statusText;
    if ($("adminGeminiModel")) $("adminGeminiModel").textContent = modelText;
  };
  try {
    const status = await api("/api/ai/status");
    if (status.configured) {
      const model = status.model || "gemini";
      setAdminGemini(i18n.t('app.연결됨'), model);
      setAiEnabled(true);
    } else {
      setAdminGemini(
        i18n.t('app.API_키_없음_env_에_GEMINI_AP'),
        "—",
      );
      setAiEnabled(false);
    }
  } catch (error) {
    setAdminGemini(error.message || i18n.t('app.상태를_확인하지_못함'), "—");
    setAiEnabled(false);
  }
}

function focusAiAssistant() {
  setAiPanelOpen(true);
  if ($("aiMode")) {
    if (state.toryFocusSceneId) $("aiMode").value = "analyze";
    else $("aiMode").value = "free";
  }
  refreshAiStatus().catch(handleError);
  updateToryFocusUi();
  if (typeof updateForeshadowPanelVisibility === "function") updateForeshadowPanelVisibility();
  if (typeof updateContinuePanelVisibility === "function") updateContinuePanelVisibility();
  $("aiPrompt")?.focus();
}

function updateToryFocusUi() {
  const banner = $("toryFocusBanner");
  const label = $("toryFocusSceneLabel");
  const panel = $("aiPanel");
  const focused = Boolean(state.toryFocusSceneId);
  banner?.classList.toggle("hidden", !focused);
  panel?.classList.toggle("is-tory-focus", focused);
  if (label) {
    label.textContent = focused
      ? (state.toryFocusSceneTitle || `${i18n.t('app.씬_state_toryFocusSceneId', {'state.toryFocusSceneId': state.toryFocusSceneId})}`)
      : "";
  }
  // Highlight focused scene in binder when present.
  document.querySelectorAll(".scene-link.is-tory-focus").forEach((el) => {
    el.classList.remove("is-tory-focus");
  });
  if (focused) {
    document
      .querySelector(`.scene-link[data-scene="${state.toryFocusSceneId}"]`)
      ?.classList.add("is-tory-focus");
  }
}

function clearToryFocus({ silent = false } = {}) {
  state.toryFocusSceneId = null;
  state.toryFocusSceneTitle = "";
  updateToryFocusUi();
  if (!silent) toast(i18n.t('app.피드백_요청_연결을_해제했어요'));
}

async function startToryAnalyzeForScene(sceneId, sceneTitle = "") {
  const id = Number(sceneId);
  if (!id) return;
  // Open the manuscript so context matches the focused scene.
  try {
    await openScene(id);
  } catch (error) {
    handleError(error);
    return;
  }
  state.toryFocusSceneId = id;
  state.toryFocusSceneTitle = sceneTitle
    || state.scene?.title
    || $("sceneTitle")?.value
    || `${i18n.t('app.씬_id', {id: id})}`;
  setAiPanelOpen(true);
  if ($("aiMode")) $("aiMode").value = "analyze";
  updateForeshadowPanelVisibility();
  updateToryFocusUi();
  refreshAiStatus().catch(handleError);
  await runFocusedAnalysis({ alreadyFocused: true });
}

const ANALYZE_MULTI_MAX = 3;

/** "current" | "other" | "multi" */
function getAnalyzeTargetMode() {
  const checked = document.querySelector('input[name="analyzeTargetMode"]:checked');
  const raw = String(checked?.value || "current").trim().toLowerCase();
  if (raw === "other" || raw === "multi") return raw;
  return "current";
}

/** Keep "다른 회차" select always visible; enable only when mode is other. */
function setOtherSceneSelectActive(wrapId, selectId, active) {
  const wrap = $(wrapId);
  const select = $(selectId);
  wrap?.classList.remove("hidden");
  wrap?.classList.toggle("is-muted", !active);
  if (select) select.disabled = !active;
}

function getEpisodeTargetModeFromConfig(config) {
  const checked = document.querySelector(`input[name="${config.radioName}"]:checked`);
  const raw = String(checked?.value || "current").trim().toLowerCase();
  if (raw === "other") return "other";
  if (raw === "multi" && Number(config.multiMax) > 0) return "multi";
  return "current";
}

function episodeTargetOptionLabel(ep, currentId) {
  const id = Number(ep.sceneId);
  const mark = currentId && id === currentId ? i18n.t("app.현재_2") : "";
  return `${i18n.t("app.ep_index_화_ep_label_ep", {
    "ep.index": ep.index,
    "ep.label || ep.shortLabel || id": ep.label || ep.shortLabel || id,
    mark,
  })}`;
}

function fillEpisodeTargetSelect(selectId) {
  const select = $(selectId);
  if (!select) return;
  const sequence = typeof getEpisodeSequence === "function" ? getEpisodeSequence() : [];
  const prev = String(select.value || "");
  const currentId = state.sceneId ? Number(state.sceneId) : null;
  if (!sequence.length) {
    select.innerHTML = i18n.t("app.option_value_열_수_있는_회차가");
    return;
  }
  const opts = sequence.map((ep) => {
    const id = Number(ep.sceneId);
    return `<option value="${id}">${escapeHtml(episodeTargetOptionLabel(ep, currentId))}</option>`;
  });
  select.innerHTML = `${i18n.t("app.option_value_회차를_선택하세요", { 'opts.join("")': opts.join("") })}`;
  if (prev && sequence.some((ep) => String(ep.sceneId) === prev)) {
    select.value = prev;
  } else {
    const other = sequence.find((ep) => Number(ep.sceneId) !== currentId);
    select.value = other ? String(other.sceneId) : (currentId ? String(currentId) : "");
  }
}

function fillEpisodeTargetMultiList(config) {
  const host = $(config.multiListId);
  if (!host) return;
  const sequence = typeof getEpisodeSequence === "function" ? getEpisodeSequence() : [];
  const currentId = state.sceneId ? Number(state.sceneId) : null;
  if (!sequence.length) {
    host.innerHTML = i18n.t("app.p_class_hint_열_수_있는_회차가");
    return;
  }
  const prevChecked = new Set(
    Array.from(host.querySelectorAll('input[type="checkbox"]:checked'))
      .map((el) => String(el.value || "")),
  );
  host.innerHTML = sequence.map((ep) => {
    const id = Number(ep.sceneId);
    const checked = prevChecked.has(String(id)) ? " checked" : "";
    return (
      `<label class="${config.multiOptionClass}">`
      + `<input type="checkbox" name="${config.multiCheckboxName}" value="${id}"${checked}>`
      + `<span>${escapeHtml(episodeTargetOptionLabel(ep, currentId))}</span>`
      + `</label>`
    );
  }).join("");
  host.querySelectorAll('input[type="checkbox"]').forEach((box) => {
    box.addEventListener("change", () => {
      const checked = host.querySelectorAll('input[type="checkbox"]:checked');
      if (checked.length > config.multiMax) {
        box.checked = false;
        toast(`${i18n.t(config.multiMaxToastKey, config.multiMaxToastParams)}`);
        return;
      }
      if (config.multiWarnAt && box.checked && checked.length >= config.multiWarnAt) {
        toast(`${i18n.t(config.multiWarnToastKey, { "checked.length": checked.length })}`);
      }
    });
  });
}

function ensureEpisodeTargetExtraSlot(config) {
  if (!config.extraOptionSlot) return;
  const modal = $(config.modalId);
  if (!modal || modal.querySelector(".episode-target-extra-options")) return;
  const slot = document.createElement("div");
  slot.className = "episode-target-extra-options";
  const actions = modal.querySelector(".modal-actions");
  if (actions?.parentNode) actions.parentNode.insertBefore(slot, actions);
}

function renderEpisodeTargetOptions(config) {
  ensureEpisodeTargetExtraSlot(config);
  fillEpisodeTargetSelect(config.otherSelectId);
  const mode = getEpisodeTargetModeFromConfig(config);
  setOtherSceneSelectActive(config.otherWrapId, config.otherSelectId, mode === "other");
  if (!(Number(config.multiMax) > 0)) return;
  if (config.multiWrapId) {
    $(config.multiWrapId)?.classList.toggle("hidden", mode !== "multi");
  }
  if (config.multiHintId) {
    $(config.multiHintId)?.classList.toggle("hidden", mode !== "multi");
  }
  if (mode === "multi") fillEpisodeTargetMultiList(config);
}

function resolveEpisodeTargetSceneIds(config) {
  const mode = getEpisodeTargetModeFromConfig(config);
  if (mode === "multi" && Number(config.multiMax) > 0) {
    const boxes = Array.from(
      document.querySelectorAll(`#${config.multiListId} input[type="checkbox"]:checked`),
    );
    return boxes
      .map((el) => Number(el.value || 0))
      .filter((id) => Number.isFinite(id) && id > 0)
      .slice(0, config.multiMax);
  }
  if (mode === "other") {
    const n = Number($(config.otherSelectId)?.value || 0);
    return Number.isFinite(n) && n > 0 ? [n] : [];
  }
  const id = state.sceneId ? Number(state.sceneId) : 0;
  return id ? [id] : [];
}

function confirmEpisodeTarget(config) {
  const mode = getEpisodeTargetModeFromConfig(config);
  let ids = resolveEpisodeTargetSceneIds(config);
  if (!ids.length) {
    if (mode === "multi") {
      toast(i18n.t(config.emptyMultiMessageKey));
      return;
    }
    if (mode === "other") {
      toast(i18n.t(config.emptyOtherMessageKey || config.emptyMessageKey));
      if (config.focusOtherOnEmpty) $(config.otherSelectId)?.focus();
      return;
    }
    toast(i18n.t(config.emptyCurrentMessageKey || config.emptyMessageKey));
    return;
  }
  if (config.sortIds) {
    ids = typeof sortSceneIdsByEpisodeSequence === "function"
      ? sortSceneIdsByEpisodeSequence(ids)
      : ids;
  }
  if (config.confirmWarnAt && ids.length >= config.confirmWarnAt && config.confirmWarnToastKey) {
    toast(`${i18n.t(config.confirmWarnToastKey, { "ids.length": ids.length })}`);
  }
  const extraValue = config.extraFieldId ? String($(config.extraFieldId)?.value || "") : "";
  const selection = { mode, sceneIds: ids, sceneId: ids[0] || null };
  if (config.extraFieldId) config.onConfirm(selection, extraValue);
  else config.onConfirm(selection);
}

