function toryPriorityPreviewText(raw) {
  const cleaned = String(raw || "").replace(/\s+/g, " ").trim();
  if (!cleaned) return i18n.t('app.클릭하여_작성');
  return cleaned.length > 42 ? `${cleaned.slice(0, 42)}…` : cleaned;
}

function syncToryPriorityPreview() {
  const preview = $("toryPriorityPreview");
  if (!preview) return;
  if (!state.projectId) {
    preview.textContent = i18n.t('app.작품을_선택하세요');
    preview.classList.remove("has-text");
    return;
  }
  const text = String(state.toryPriorityMd || "").trim();
  preview.textContent = toryPriorityPreviewText(text);
  preview.classList.toggle("has-text", Boolean(text));
}

function setToryPriorityOpen(open) {
  const box = $("toryPriorityBox");
  const toggle = $("toryPriorityToggle");
  const popup = $("toryPriorityPopup");
  if (!box || !toggle || !popup) return;
  const next = Boolean(open);
  box.classList.toggle("is-open", next);
  toggle.setAttribute("aria-expanded", next ? "true" : "false");
  popup.classList.toggle("hidden", !next);
  popup.hidden = !next;
  if (next) {
    // First open: place near the launcher if no geometry yet
    if (!popup.style.width || !popup.style.left) {
      const rect = box.getBoundingClientRect();
      const width = Math.min(380, Math.max(280, window.innerWidth - 32));
      const height = Math.min(360, Math.max(220, Math.round(window.innerHeight * 0.42)));
      let left = Math.round(rect.right - width);
      let top = Math.round(rect.bottom + 8);
      left = Math.min(Math.max(8, left), window.innerWidth - width - 8);
      top = Math.min(Math.max(8, top), window.innerHeight - height - 8);
      popup.style.left = `${left}px`;
      popup.style.top = `${top}px`;
      popup.style.right = "auto";
      popup.style.width = `${width}px`;
      popup.style.height = `${height}px`;
    }
    syncToryPriorityInput();
    window.setTimeout(() => $("toryPriorityInput")?.focus(), 0);
  } else {
    syncToryPriorityPreview();
  }
}

function setupToryPriorityPopupChrome() {
  const popup = $("toryPriorityPopup");
  const dragBar = $("toryPriorityPopupDrag");
  if (!popup || popup.dataset.chromeBound === "1") return;
  popup.dataset.chromeBound = "1";

  const MIN_W = 280;
  const MIN_H = 200;
  let drag = null;
  let resize = null;

  const lockGeom = () => {
    const rect = popup.getBoundingClientRect();
    popup.style.left = `${Math.round(rect.left)}px`;
    popup.style.top = `${Math.round(rect.top)}px`;
    popup.style.right = "auto";
    popup.style.bottom = "auto";
    popup.style.width = `${Math.round(rect.width)}px`;
    popup.style.height = `${Math.round(rect.height)}px`;
    return rect;
  };

  dragBar?.addEventListener("pointerdown", (event) => {
    if (event.button != null && event.button !== 0) return;
    if (event.target.closest("button")) return;
    const rect = lockGeom();
    drag = {
      offsetX: event.clientX - rect.left,
      offsetY: event.clientY - rect.top,
      pointerId: event.pointerId,
    };
    document.body.classList.add("tory-priority-popup-dragging");
    try { dragBar.setPointerCapture?.(event.pointerId); } catch (_) { /* ignore */ }
    event.preventDefault();
  });

  popup.querySelectorAll("[data-resize-edge]").forEach((handle) => {
    handle.addEventListener("pointerdown", (event) => {
      if (event.button != null && event.button !== 0) return;
      event.preventDefault();
      event.stopPropagation();
      const rect = lockGeom();
      resize = {
        edge: handle.getAttribute("data-resize-edge") || "se",
        startX: event.clientX,
        startY: event.clientY,
        startLeft: rect.left,
        startTop: rect.top,
        startW: rect.width,
        startH: rect.height,
        pointerId: event.pointerId,
      };
      document.body.classList.add("tory-priority-popup-resizing");
      try { handle.setPointerCapture?.(event.pointerId); } catch (_) { /* ignore */ }
    });
  });

  const onMove = (event) => {
    if (drag && (drag.pointerId == null || drag.pointerId === event.pointerId)) {
      const vw = popup.getBoundingClientRect().width || MIN_W;
      const maxLeft = Math.max(8, window.innerWidth - 48);
      const maxTop = Math.max(8, window.innerHeight - 40);
      const minLeft = Math.min(8, window.innerWidth - vw);
      const left = Math.min(maxLeft, Math.max(minLeft, event.clientX - drag.offsetX));
      const top = Math.min(maxTop, Math.max(0, event.clientY - drag.offsetY));
      popup.style.left = `${Math.round(left)}px`;
      popup.style.top = `${Math.round(top)}px`;
      popup.style.right = "auto";
    }
    if (resize && (resize.pointerId == null || resize.pointerId === event.pointerId)) {
      const edge = resize.edge;
      const dx = event.clientX - resize.startX;
      const dy = event.clientY - resize.startY;
      let left = resize.startLeft;
      let top = resize.startTop;
      let width = resize.startW;
      let height = resize.startH;
      if (edge.includes("e")) width = resize.startW + dx;
      if (edge.includes("s")) height = resize.startH + dy;
      if (edge.includes("w")) {
        width = resize.startW - dx;
        left = resize.startLeft + dx;
      }
      if (edge.includes("n")) {
        height = resize.startH - dy;
        top = resize.startTop + dy;
      }
      width = Math.min(window.innerWidth - 16, Math.max(MIN_W, width));
      height = Math.min(window.innerHeight - 16, Math.max(MIN_H, height));
      if (edge.includes("w")) {
        left = Math.min(resize.startLeft + resize.startW - MIN_W, Math.max(0, left));
        width = resize.startLeft + resize.startW - left;
        width = Math.min(window.innerWidth - 16, Math.max(MIN_W, width));
      }
      if (edge.includes("n")) {
        top = Math.min(resize.startTop + resize.startH - MIN_H, Math.max(0, top));
        height = resize.startTop + resize.startH - top;
        height = Math.min(window.innerHeight - 16, Math.max(MIN_H, height));
      }
      left = Math.min(Math.max(0, left), window.innerWidth - Math.min(width, window.innerWidth - 8));
      top = Math.min(Math.max(0, top), window.innerHeight - Math.min(height, window.innerHeight - 8));
      popup.style.left = `${Math.round(left)}px`;
      popup.style.top = `${Math.round(top)}px`;
      popup.style.width = `${Math.round(width)}px`;
      popup.style.height = `${Math.round(height)}px`;
      popup.style.right = "auto";
    }
  };
  const onUp = (event) => {
    if (drag && (drag.pointerId == null || drag.pointerId === event.pointerId)) {
      drag = null;
      document.body.classList.remove("tory-priority-popup-dragging");
    }
    if (resize && (resize.pointerId == null || resize.pointerId === event.pointerId)) {
      resize = null;
      document.body.classList.remove("tory-priority-popup-resizing");
    }
  };
  window.addEventListener("pointermove", onMove);
  window.addEventListener("pointerup", onUp);
  window.addEventListener("pointercancel", onUp);
}

function syncToryPriorityInput() {
  const input = $("toryPriorityInput");
  if (!input) return;
  const hasProject = Boolean(state.projectId);
  input.disabled = !hasProject;
  const next = hasProject ? String(state.toryPriorityMd || "") : "";
  if (document.activeElement !== input) input.value = next;
  if (!hasProject) {
    input.placeholder = i18n.t('app.작품을_선택하면_작가_지침을_적을_수_있어요');
    const hint = $("toryPrioritySaveHint");
    if (hint) hint.textContent = "";
  } else {
    input.placeholder = i18n.t('app.예_주인공의_감정을_과장하지_말_것_반전을');
  }
  syncToryPriorityPreview();
  const toggle = $("toryPriorityToggle");
  if (toggle) toggle.disabled = !hasProject;
}

async function persistToryPriority({ quiet = true } = {}) {
  if (!state.projectId || toryPrioritySaving) return;
  const input = $("toryPriorityInput");
  const value = String(input?.value ?? state.toryPriorityMd ?? "").slice(0, 4000);
  if (value === String(state.toryPriorityMd || "")) {
    const hint = $("toryPrioritySaveHint");
    if (hint && !quiet) hint.textContent = i18n.t('app.저장됨');
    syncToryPriorityPreview();
    return;
  }
  toryPrioritySaving = true;
  const hint = $("toryPrioritySaveHint");
  if (hint) hint.textContent = i18n.t('app.저장_중');
  try {
    const result = await api(`/api/projects/${state.projectId}/settings`, {
      method: "PUT",
      body: JSON.stringify({ tory_priority_md: value }),
    });
    state.toryPriorityMd = result.tory_priority_md != null ? String(result.tory_priority_md) : value;
    const project = state.projects.find((item) => item.id === state.projectId);
    if (project) project.tory_priority_md = state.toryPriorityMd;
    if (hint) hint.textContent = state.toryPriorityMd.trim() ? i18n.t('app.저장됨_작업에_맞게_참고합니다') : i18n.t('app.비움_일반_기준으로_동작');
    syncToryPriorityPreview();
  } catch (error) {
    if (hint) hint.textContent = i18n.t('app.저장_실패');
    throw error;
  } finally {
    toryPrioritySaving = false;
  }
}

function setupToryPriorityField() {
  const input = $("toryPriorityInput");
  const toggle = $("toryPriorityToggle");
  const done = $("toryPriorityDoneButton");
  if (!input || input.dataset.bound === "1") return;
  input.dataset.bound = "1";
  setupToryPriorityPopupChrome();
  syncToryPriorityInput();
  setToryPriorityOpen(false);
  const schedule = () => {
    if (toryPrioritySaveTimer) window.clearTimeout(toryPrioritySaveTimer);
    toryPrioritySaveTimer = window.setTimeout(() => {
      persistToryPriority({ quiet: true }).catch(handleError);
    }, 700);
  };
  input.addEventListener("input", () => {
    const preview = $("toryPriorityPreview");
    if (preview && state.projectId) {
      const draft = String(input.value || "").trim();
      preview.textContent = toryPriorityPreviewText(draft);
      preview.classList.toggle("has-text", Boolean(draft));
    }
    schedule();
  });
  input.addEventListener("change", () => {
    if (toryPrioritySaveTimer) window.clearTimeout(toryPrioritySaveTimer);
    persistToryPriority({ quiet: false }).catch(handleError);
  });
  input.addEventListener("blur", () => {
    if (toryPrioritySaveTimer) window.clearTimeout(toryPrioritySaveTimer);
    persistToryPriority({ quiet: true }).catch(handleError);
  });
  toggle?.addEventListener("click", () => {
    if (!state.projectId) {
      toast(i18n.t('app.먼저_작품을_선택해_주세요'));
      return;
    }
    const open = toggle.getAttribute("aria-expanded") === "true";
    setToryPriorityOpen(!open);
  });
  done?.addEventListener("click", () => {
    if (toryPrioritySaveTimer) window.clearTimeout(toryPrioritySaveTimer);
    persistToryPriority({ quiet: true })
      .catch(handleError)
      .finally(() => setToryPriorityOpen(false));
  });
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    const popup = $("toryPriorityPopup");
    if (!popup || popup.classList.contains("hidden")) return;
    event.preventDefault();
    if (toryPrioritySaveTimer) window.clearTimeout(toryPrioritySaveTimer);
    persistToryPriority({ quiet: true })
      .catch(handleError)
      .finally(() => setToryPriorityOpen(false));
  });
}

/* ═══════════════════════════════════════════════════════════
   토리 1:1 대화 + 오른쪽 하단 알림 센터
   ═══════════════════════════════════════════════════════════ */
const TORY_CHAT_STORAGE_PREFIX = "supertory.toryChat.";
const TORY_CHAT_ARCHIVE_PREFIX = "supertory.toryChatArchive.";
/** successAnalysis live session: supertory.toryChat.successAnalysis.{projectId} */
const TORY_CHAT_SUCCESS_STORAGE_PREFIX = "supertory.toryChat.successAnalysis.";
const TORY_CHAT_SUCCESS_ARCHIVE_PREFIX = "supertory.toryChatArchive.successAnalysis.";
const TORY_CHAT_CHARACTER_STORAGE_PREFIX = "supertory.toryChat.character.";
const TORY_CHAT_CHARACTER_ARCHIVE_PREFIX = "supertory.toryChatArchive.character.";
const TORY_NOTIFY_STORAGE_PREFIX = "supertory.toryNotifs.";
const TORY_CHAT_MAX_MESSAGES = 80;
const TORY_CHAT_ARCHIVE_MAX = 40;
/** @type {"general"|"successAnalysis"} active Tory (not character) chat session kind */
let toryChatMode = "general";
/** @type {"home"|"tory"|"characters"|"character-room"|"reader"} */
let toryChatHub = "home";
/** Selected 설정집 character ids for character / group chat */
let toryChatCharacterIds = [];
/** @type {"chat"|"sim"} 내 캐릭터와 대화하기: 1:1 vs 시뮬레이션 */
let charListMode = "chat";
let toryChatSending = false;
let toryChatHistoryViewId = null;

let toryChatPopupOpen = false;
/** 1:1 질문칸 초안. 팝업으로 DOM을 옮길 때 IME 조합이 비는 경우를 대비합니다. */
let toryChatComposerDraft = "";

function captureToryChatComposerDraft({ commitIme = false } = {}) {
  const input = $("toryChatInput");
  if (commitIme) commitTextareaIme(input);
  if (input) toryChatComposerDraft = String(input.value || "");
  return toryChatComposerDraft;
}

function restoreToryChatComposerDraft(value = toryChatComposerDraft) {
  const input = $("toryChatInput");
  if (!input) return;
  const next = String(value ?? "");
  input.value = next;
  toryChatComposerDraft = next;
}

function setToryChatPopupDockHint(visible) {
  const hint = $("toryChatPopupDockHint");
  if (!hint) return;
  hint.classList.toggle("hidden", !visible);
  hint.hidden = !visible;
}

function showToryChatPopupInPanelSlot() {
  const toolsView = $("aiToolsView");
  toolsView?.classList.add("hidden");
  if (toolsView) toolsView.hidden = true;
  $("aiTabTools")?.classList.remove("is-active");
  $("aiTabTools")?.setAttribute("aria-selected", "false");
  $("aiTabChat")?.classList.add("is-active");
  $("aiTabChat")?.setAttribute("aria-selected", "true");
  setToryChatPopupDockHint(true);
}

function normalizeToryChatMode(mode) {
  const m = String(mode || toryChatMode || "general").trim();
  return m === "successAnalysis" ? "successAnalysis" : "general";
}

function getToryChatMode() {
  return normalizeToryChatMode(toryChatMode);
}

function normalizeToryChatCharacterIds(ids) {
  const seen = new Set();
  const out = [];
  (Array.isArray(ids) ? ids : []).forEach((raw) => {
    const id = Number(raw);
    if (!Number.isFinite(id) || id <= 0 || seen.has(id)) return;
    seen.add(id);
    out.push(id);
  });
  out.sort((a, b) => a - b);
  return out;
}

function isToryCharacterChatSession(chatMode = getToryChatSessionKey()) {
  return String(chatMode || "").startsWith("character:");
}

function getToryChatSessionKey() {
  if (toryChatHub === "character-room") {
    const ids = normalizeToryChatCharacterIds(toryChatCharacterIds);
    if (ids.length) return `character:${ids.join("-")}`;
  }
  return getToryChatMode();
}

function getToryChatPartnerCharacters() {
  const ids = normalizeToryChatCharacterIds(toryChatCharacterIds);
  const all = Array.isArray(state.characters) ? state.characters : [];
  return ids.map((id) => all.find((ch) => Number(ch.id) === id)).filter(Boolean);
}

function getToryChatPartnerNames() {
  return getToryChatPartnerCharacters().map((ch) => String(ch.name || "").trim() || `${i18n.t('app.인물_ch_id_2', {'ch.id': ch.id})}`);
}

function buildToryChatPartnerPayload() {
  return getToryChatPartnerCharacters().map((ch) => ({
    id: Number(ch.id),
    name: String(ch.name || "").trim() || `${i18n.t('app.인물_ch_id_2', {'ch.id': ch.id})}`,
    role: String(ch.role || ""),
    short_description: String(ch.short_description || "").trim().slice(0, 400),
    profile_md: String(ch.profile_md || "").replace(/\s+/g, " ").trim().slice(0, 800),
    strengths_md: String(ch.strengths_md || "").replace(/\s+/g, " ").trim().slice(0, 240),
    weaknesses_md: String(ch.weaknesses_md || "").replace(/\s+/g, " ").trim().slice(0, 240),
  }));
}

function syncToryChatRoomChrome() {
  const inCharacter = toryChatHub === "character-room";
  const names = getToryChatPartnerNames();
  const back = $("toryChatRoomBack");
  if (back) {
    const label = inCharacter ? i18n.t('app.인물_선택으로') : i18n.t('app.소통방으로');
    back.title = label;
    back.setAttribute("aria-label", label);
  }
  const input = $("toryChatInput");
  if (input) {
    if (inCharacter) {
      const who = names.length ? names.join(" · ") : i18n.t('app.캐릭터');
      input.placeholder = `${who}에게 말걸기\n(Enter 전송 Shift + Enter 줄바꿈)`;
      input.setAttribute("aria-label", `${i18n.t('app.who_에게_보낼_메시지', {who: who})}`);
    } else {
      input.placeholder = i18n.t('app.토리에게_말걸기_Enter_전송_Shift');
      input.setAttribute("aria-label", i18n.t('app.토리에게_보낼_메시지'));
    }
  }
  const box = $("toryChatMessages");
  if (box) box.setAttribute("aria-label", inCharacter ? i18n.t('app.캐릭터와의_대화') : i18n.t('app.토리와의_대화'));
}

function setToryChatHub(hub, { quiet = false } = {}) {
  const allowed = { home: 1, tory: 1, characters: 1, "character-room": 1, reader: 1 };
  const next = allowed[hub] ? hub : "home";
  if (next === "character-room" && !normalizeToryChatCharacterIds(toryChatCharacterIds).length) {
    toryChatHub = "characters";
    $("aiChatView")?.setAttribute("data-chat-hub", "characters");
    setCharListMode("chat");
    if (!quiet) toast(i18n.t('app.대화할_인물을_먼저_골라_주세요'));
    return false;
  }
  toryChatHub = next;
  $("aiChatView")?.setAttribute("data-chat-hub", next);
  if (next === "characters") {
    setCharListMode(charListMode || "chat");
  }
  if (next === "reader") syncReaderChatView();
  if (next === "tory" || next === "character-room") {
    syncToryChatRoomChrome();
    renderToryChatMessages();
  }
  updateToryChatSuccessUi();
  return true;
}

function setToryChatMode(mode, { quiet = false } = {}) {
  const next = normalizeToryChatMode(mode);
  if (next === "successAnalysis" && !getLinkedSuccessProfileId()) {
    if (!quiet) toast(i18n.t('app.먼저_흥행_프로파일을_이_작품에_연결해_주세'));
    return false;
  }
  toryChatMode = next;
  updateToryChatSuccessUi();
  renderToryChatMessages();
  if (!quiet) {
    toast(
      next === "successAnalysis"
        ? i18n.t('app.흥행요인_분석가_세션이에요_일반_대화와_기록')
        : i18n.t('app.일반_토리_대화로_돌아왔어요'),
    );
  }
  return true;
}

function setAiPanelTab(tab, { skipPopupClose = false, chatHub = null } = {}) {
  const next = tab === "chat" ? "chat" : "tools";
  const toolsView = $("aiToolsView");
  const chatView = $("aiChatView");
  const toolsTab = $("aiTabTools");
  const chatTab = $("aiTabChat");
  const isChat = next === "chat";

  // Panel chat: ensure chat UI lives in the side panel (not floating popup)
  if (isChat && toryChatPopupOpen && !skipPopupClose) {
    closeToryChatPopup({ restorePanelTab: false });
  }
  if (isChat && !toryChatPopupOpen) {
    restoreToryChatToPanel();
  }
  if (!isChat) {
    setToryChatPopupDockHint(false);
  } else if (toryChatPopupOpen && skipPopupClose) {
    setToryChatPopupDockHint(true);
  }

  toolsView?.classList.toggle("hidden", isChat);
  chatView?.classList.toggle("hidden", !isChat);
  if (toolsView) toolsView.hidden = isChat;
  if (chatView) chatView.hidden = !isChat;
  toolsTab?.classList.toggle("is-active", !isChat);
  chatTab?.classList.toggle("is-active", isChat || toryChatPopupOpen);
  if (toolsTab) toolsTab.setAttribute("aria-selected", isChat ? "false" : "true");
  if (chatTab) chatTab.setAttribute("aria-selected", isChat || toryChatPopupOpen ? "true" : "false");
  if (isChat) {
    if (chatHub) setToryChatHub(chatHub, { quiet: true });
    else if (!toryChatHub) setToryChatHub("home", { quiet: true });
    else {
      $("aiChatView")?.setAttribute("data-chat-hub", toryChatHub);
      if (toryChatHub === "characters") renderToryChatCharacterPicker();
      if (toryChatHub === "reader") syncReaderChatView();
      if (toryChatHub === "tory" || toryChatHub === "character-room") {
        syncToryChatRoomChrome();
        renderToryChatMessages();
      }
    }
    if (toryChatHub === "tory" || toryChatHub === "character-room") {
      requestAnimationFrame(() => $("toryChatInput")?.focus());
    }
  }
}

/** 도우미 패널: 직접요청 | 선택하기 | 결과보기 (기본값 직접요청) */
function setAiHelperPane(pane) {
  let next = "direct";
  if (pane === "select" || pane === "result" || pane === "direct") next = pane;
  else if (pane === "request") next = "direct"; // legacy
  const view = $("aiToolsView");
  const directTab = $("aiHelperPaneDirect");
  const selectTab = $("aiHelperPaneSelect");
  const resTab = $("aiHelperPaneResult");
  if (view) view.setAttribute("data-helper-pane", next);

  const tabs = [
    [directTab, "direct"],
    [selectTab, "select"],
    [resTab, "result"],
  ];
  tabs.forEach(([tab, key]) => {
    const on = next === key;
    tab?.classList.toggle("is-active", on);
    if (tab) tab.setAttribute("aria-selected", on ? "true" : "false");
  });

  if (next === "direct") {
    const sel = $("aiMode");
    if (sel && sel.value !== "free") {
      sel.value = "free";
      try { sel.dispatchEvent(new Event("change", { bubbles: true })); } catch (_) { /* ignore */ }
    }
    try { syncAiModePickerUi?.(); } catch (_) { /* ignore */ }
    try { updateContinuePanelVisibility?.(); } catch (_) { /* ignore */ }
    closeAiModePicker?.();
  } else if (next === "select") {
    try { renderAiModePickerMenu?.(); } catch (_) { /* ignore */ }
    try { syncAiModePickerUi?.(); } catch (_) { /* ignore */ }
    try { updateContinuePanelVisibility?.(); } catch (_) { /* ignore */ }
    try { syncAiSelectViewUi?.(); } catch (_) { /* ignore */ }
  } else {
    closeAiModePicker?.();
  }
}

/** 결과가 준비되면 결과보기 세그먼트로 전환 */
function ensureAiResultVisible() {
  const wrap = $("aiResultWrap");
  wrap?.classList.remove("hidden", "is-empty");
  try { setAiPanelTab("tools"); } catch (_) { /* ignore */ }
  setAiHelperPane("result");
}

/** 도구 모드를 고를 때 선택하기 탭으로 */
function ensureAiHelperSelectPane() {
  try { setAiPanelTab("tools"); } catch (_) { /* ignore */ }
  const mode = $("aiMode")?.value || "free";
  if (mode && mode !== "free") setAiHelperPane("select");
}

function setupAiHelperPaneTabs() {
  const host = document.querySelector(".ai-helper-pane-tabs");
  if (!host || host.dataset.bound === "1") return;
  host.dataset.bound = "1";
  host.addEventListener("click", (event) => {
    const btn = event.target.closest?.("[data-helper-pane]");
    if (!btn || !host.contains(btn)) return;
    event.preventDefault();
    setAiHelperPane(btn.getAttribute("data-helper-pane"));
  });
  // 모드 드롭바에서 기능 고르면 선택하기 탭 유지
  $("aiMode")?.addEventListener("change", () => {
    const mode = $("aiMode")?.value || "free";
    const pane = $("aiToolsView")?.getAttribute("data-helper-pane");
    if (pane === "result") return;
    if (mode === "free" && pane === "direct") return;
    if (mode !== "free") setAiHelperPane("select");
  });
  // 기본값: 직접요청
  setAiHelperPane("direct");
}

function restoreToryChatToPanel() {
  const chat = $("aiChatView");
  const body = document.querySelector("#aiPanel .ai-panel-body");
  if (!chat || !body) return;
  if (chat.parentElement === body) return;
  const hint = $("toryChatPopupDockHint");
  if (hint && hint.parentElement === body) body.insertBefore(chat, hint);
  else body.appendChild(chat);
}

function openToryChatPopup(options = {}) {
  const popup = $("toryChatPopup");
  const host = $("toryChatPopupBody");
  const chat = $("aiChatView");
  if (!popup || !host || !chat) return;

  const draft = captureToryChatComposerDraft({ commitIme: true });
  // 도우미(직접요청)로 바꾸지 않아요. 패널에 다른 입력칸이 보이면 별도 창처럼 느껴집니다.
  toryChatPopupOpen = true;
  showToryChatPopupInPanelSlot();
  host.appendChild(chat);
  chat.classList.remove("hidden");
  chat.hidden = false;
  popup.classList.remove("hidden");
  popup.hidden = false;
  $("toryChatPopupOpenButton")?.classList.add("hidden");

  // Default size/position if not yet set
  if (!popup.style.width) {
    popup.style.width = `${Math.min(420, window.innerWidth - 32)}px`;
  }
  if (!popup.style.height) {
    popup.style.height = `${Math.min(Math.round(window.innerHeight * 0.62), 560)}px`;
  }
  if (!popup.style.left && !popup.style.right) {
    popup.style.right = "24px";
    popup.style.top = "72px";
    popup.style.left = "auto";
  }

  const input = $("toryChatInput");
  if (options.prefill != null && input) {
    const text = String(options.prefill).slice(0, 4000);
    restoreToryChatComposerDraft(text);
    const caret = Number.isFinite(options.caret)
      ? Math.max(0, Math.min(text.length, options.caret))
      : text.length;
    requestAnimationFrame(() => {
      try {
        input.focus();
        input.setSelectionRange(caret, caret);
      } catch (_) {
        input.focus();
      }
    });
  } else {
    restoreToryChatComposerDraft(draft);
    requestAnimationFrame(() => input?.focus());
  }

  renderToryChatMessages();
  if (!options.silent) {
    toast(
      options.prefill
        ? i18n.t('app.선택_문장을_질문칸에_넣었어요_다듬은_뒤_보')
        : i18n.t('app.토리_대화를_팝업으로_열었어요_모서리로_크기'),
    );
  }
}

/**
 * Manuscript selection → 1:1 chat popup with quote prefilled (do not auto-send).
 */
function askToryFromSelection() {
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  const raw = (pendingBaitQuote || getSelectedManuscriptText() || "").trim();
  if (!raw) {
    toast(i18n.t('app.본문에서_단어나_문장을_드래그로_선택한_뒤'));
    return;
  }
  // Quote in the question box; leave room below so the author can add a question before send.
  const quote = raw.replace(/\s+\n/g, "\n").trim().slice(0, 3500);
  const prefill = `「${quote}」\n\n`;
  setToryChatHub("tory", { quiet: true });
  openToryChatPopup({ prefill, caret: prefill.length });
}

function closeToryChatPopup({ restorePanelTab = true } = {}) {
  const popup = $("toryChatPopup");
  if (!popup) return;
  const draft = captureToryChatComposerDraft({ commitIme: true });
  toryChatPopupOpen = false;
  setToryChatPopupDockHint(false);
  restoreToryChatToPanel();
  restoreToryChatComposerDraft(draft);
  $("toryChatPopupOpenButton")?.classList.remove("hidden");
  popup.classList.add("hidden");
  popup.hidden = true;
  if (restorePanelTab) {
    // Return chat view to panel so user can continue there
    setAiPanelTab("chat", { skipPopupClose: true });
  }
}

function applyFloatingPopupResize(popup, resizeState, event, minW, minH) {
  if (!popup || !resizeState) return;
  const edge = resizeState.edge || "se";
  const dx = event.clientX - resizeState.startX;
  const dy = event.clientY - resizeState.startY;
  let left = resizeState.startLeft;
  let top = resizeState.startTop;
  let width = resizeState.startW;
  let height = resizeState.startH;
  if (edge.includes("e")) width = resizeState.startW + dx;
  if (edge.includes("s")) height = resizeState.startH + dy;
  if (edge.includes("w")) {
    width = resizeState.startW - dx;
    left = resizeState.startLeft + dx;
  }
  if (edge.includes("n")) {
    height = resizeState.startH - dy;
    top = resizeState.startTop + dy;
  }
  width = Math.min(window.innerWidth - 16, Math.max(minW, width));
  height = Math.min(window.innerHeight - 16, Math.max(minH, height));
  if (edge.includes("w")) {
    left = Math.min(resizeState.startLeft + resizeState.startW - minW, Math.max(0, left));
    width = resizeState.startLeft + resizeState.startW - left;
    width = Math.min(window.innerWidth - 16, Math.max(minW, width));
  }
  if (edge.includes("n")) {
    top = Math.min(resizeState.startTop + resizeState.startH - minH, Math.max(0, top));
    height = resizeState.startTop + resizeState.startH - top;
    height = Math.min(window.innerHeight - 16, Math.max(minH, height));
  }
  left = Math.min(Math.max(0, left), window.innerWidth - Math.min(width, window.innerWidth - 8));
  top = Math.min(Math.max(0, top), window.innerHeight - Math.min(height, window.innerHeight - 8));
  popup.style.left = `${Math.round(left)}px`;
  popup.style.top = `${Math.round(top)}px`;
  popup.style.width = `${Math.round(width)}px`;
  popup.style.height = `${Math.round(height)}px`;
  popup.style.right = "auto";
  popup.style.bottom = "auto";
}

function setupToryChatPopupChrome() {
  const popup = $("toryChatPopup");
  const dragBar = $("toryChatPopupDrag");
  if (!popup) return;

  let drag = null;
  let resize = null;
  const MIN_W = 300;
  const MIN_H = 280;

  const lockGeom = () => {
    const rect = popup.getBoundingClientRect();
    popup.style.left = `${Math.round(rect.left)}px`;
    popup.style.top = `${Math.round(rect.top)}px`;
    popup.style.right = "auto";
    popup.style.bottom = "auto";
    popup.style.width = `${Math.round(rect.width)}px`;
    popup.style.height = `${Math.round(rect.height)}px`;
    return rect;
  };

  dragBar?.addEventListener("pointerdown", (event) => {
    if (event.button != null && event.button !== 0) return;
    if (event.target.closest("button")) return;
    const rect = lockGeom();
    drag = {
      offsetX: event.clientX - rect.left,
      offsetY: event.clientY - rect.top,
      pointerId: event.pointerId,
    };
    document.body.classList.add("tory-chat-popup-dragging");
    try { dragBar.setPointerCapture?.(event.pointerId); } catch (_) { /* ignore */ }
    event.preventDefault();
  });

  popup.querySelectorAll("[data-resize-edge]").forEach((handle) => {
    handle.addEventListener("pointerdown", (event) => {
      if (event.button != null && event.button !== 0) return;
      event.preventDefault();
      event.stopPropagation();
      const rect = lockGeom();
      resize = {
        edge: handle.getAttribute("data-resize-edge") || "se",
        startX: event.clientX,
        startY: event.clientY,
        startLeft: rect.left,
        startTop: rect.top,
        startW: rect.width,
        startH: rect.height,
        pointerId: event.pointerId,
      };
      document.body.classList.add("tory-chat-popup-resizing");
      try { handle.setPointerCapture?.(event.pointerId); } catch (_) { /* ignore */ }
    });
  });

  const onMove = (event) => {
    if (drag && (drag.pointerId == null || drag.pointerId === event.pointerId)) {
      const vw = popup.getBoundingClientRect().width || MIN_W;
      const maxLeft = Math.max(8, window.innerWidth - 48);
      const maxTop = Math.max(8, window.innerHeight - 40);
      const minLeft = Math.min(8, window.innerWidth - vw);
      const left = Math.min(maxLeft, Math.max(minLeft, event.clientX - drag.offsetX));
      const top = Math.min(maxTop, Math.max(0, event.clientY - drag.offsetY));
      popup.style.left = `${Math.round(left)}px`;
      popup.style.top = `${Math.round(top)}px`;
      popup.style.right = "auto";
    }
    if (resize && (resize.pointerId == null || resize.pointerId === event.pointerId)) {
      applyFloatingPopupResize(popup, resize, event, MIN_W, MIN_H);
    }
  };
  const onUp = (event) => {
    if (drag && (drag.pointerId == null || drag.pointerId === event.pointerId)) {
      drag = null;
      document.body.classList.remove("tory-chat-popup-dragging");
    }
    if (resize && (resize.pointerId == null || resize.pointerId === event.pointerId)) {
      resize = null;
      document.body.classList.remove("tory-chat-popup-resizing");
    }
  };
  window.addEventListener("pointermove", onMove);
  window.addEventListener("pointerup", onUp);
  window.addEventListener("pointercancel", onUp);

  $("toryChatPopupClose")?.addEventListener("click", () => {
    closeToryChatPopup({ restorePanelTab: true });
    toast(i18n.t('app.팝업_대화를_닫았어요'));
  });
  $("toryChatPopupDockButton")?.addEventListener("click", (event) => {
    event.preventDefault();
    closeToryChatPopup({ restorePanelTab: true });
  });
}

function toryChatStorageKey(projectId = state.projectId, chatMode = getToryChatSessionKey()) {
  const pid = projectId || "0";
  const raw = String(chatMode || "");
  if (raw.startsWith("character:")) {
    const ids = raw.slice("character:".length) || "none";
    return `${TORY_CHAT_CHARACTER_STORAGE_PREFIX}${pid}.${ids}`;
  }
  if (normalizeToryChatMode(chatMode) === "successAnalysis") {
    return `${TORY_CHAT_SUCCESS_STORAGE_PREFIX}${pid}`;
  }
  return `${TORY_CHAT_STORAGE_PREFIX}${pid}`;
}

function toryChatArchiveKey(projectId = state.projectId, chatMode = getToryChatSessionKey()) {
  const pid = projectId || "0";
  const raw = String(chatMode || "");
  if (raw.startsWith("character:")) {
    const ids = raw.slice("character:".length) || "none";
    return `${TORY_CHAT_CHARACTER_ARCHIVE_PREFIX}${pid}.${ids}`;
  }
  if (normalizeToryChatMode(chatMode) === "successAnalysis") {
    return `${TORY_CHAT_SUCCESS_ARCHIVE_PREFIX}${pid}`;
  }
  return `${TORY_CHAT_ARCHIVE_PREFIX}${pid}`;
}

function loadToryChatHistory(chatMode = getToryChatSessionKey()) {
  if (!state.projectId) return [];
  try {
    const raw = localStorage.getItem(toryChatStorageKey(state.projectId, chatMode));
    const arr = raw ? JSON.parse(raw) : [];
    if (!Array.isArray(arr)) return [];
    return arr
      .filter((m) => m && (m.role === "user" || m.role === "tory") && String(m.content || m.contentHtml || "").trim())
      .map((m) => ({
        role: m.role === "user" ? "user" : "tory",
        content: String(m.content || "").trim() || plainTextFromChatHtml(m.contentHtml || ""),
        contentHtml: m.contentHtml ? String(m.contentHtml) : "",
        at: m.at || "",
      }))
      .slice(-TORY_CHAT_MAX_MESSAGES);
  } catch (_) {
    return [];
  }
}

function saveToryChatHistory(list, chatMode = getToryChatSessionKey()) {
  if (!state.projectId) return;
  try {
    localStorage.setItem(
      toryChatStorageKey(state.projectId, chatMode),
      JSON.stringify((list || []).slice(-TORY_CHAT_MAX_MESSAGES)),
    );
  } catch (_) {
    /* ignore */
  }
}

function plainTextFromChatHtml(html) {
  if (!html) return "";
  const div = document.createElement("div");
  div.innerHTML = String(html);
  return (div.textContent || "").replace(/\s+/g, " ").trim();
}

/** Allow only marks / breaks inside chat bubble HTML. */
function sanitizeToryChatHtml(html) {
  const root = document.createElement("div");
  root.innerHTML = String(html || "");
  const walk = (node) => {
    const kids = [...node.childNodes];
    for (const child of kids) {
      if (child.nodeType === Node.TEXT_NODE) continue;
      if (child.nodeType !== Node.ELEMENT_NODE) {
        child.remove();
        continue;
      }
      const tag = child.tagName.toLowerCase();
      if (tag === "br") continue;
      if (tag === "mark" || (tag === "span" && child.classList.contains("tory-chat-hl"))) {
        const bg = child.style?.backgroundColor || child.getAttribute("data-hl") || "";
        child.removeAttribute("style");
        child.removeAttribute("class");
        child.className = "tory-chat-hl";
        if (bg) child.style.backgroundColor = bg;
        walk(child);
        continue;
      }
      // unwrap unknown tags, keep text
      while (child.firstChild) node.insertBefore(child.firstChild, child);
      child.remove();
    }
  };
  walk(root);
  return root.innerHTML;
}

function loadToryChatArchives(chatMode = getToryChatSessionKey()) {
  if (!state.projectId) return [];
  try {
    const raw = localStorage.getItem(toryChatArchiveKey(state.projectId, chatMode));
    const arr = raw ? JSON.parse(raw) : [];
    if (!Array.isArray(arr)) return [];
    const storedMode = isToryCharacterChatSession(chatMode)
      ? String(chatMode)
      : normalizeToryChatMode(chatMode);
    return arr
      .filter((s) => s && s.id && Array.isArray(s.messages) && s.messages.length)
      .map((s) => ({
        id: String(s.id),
        title: String(s.title || i18n.t('app.이전_대화')).trim() || i18n.t('app.이전_대화'),
        messages: s.messages
          .filter((m) => m && (m.role === "user" || m.role === "tory") && String(m.content || m.contentHtml || "").trim())
          .map((m) => ({
            role: m.role === "user" ? "user" : "tory",
            content: String(m.content || "").trim() || plainTextFromChatHtml(m.contentHtml || ""),
            contentHtml: m.contentHtml ? String(m.contentHtml) : "",
            at: m.at || "",
          })),
        archivedAt: s.archivedAt || s.createdAt || "",
        messageCount: Number(s.messageCount) || (s.messages || []).length,
        chatMode: storedMode,
      }))
      .slice(0, TORY_CHAT_ARCHIVE_MAX);
  } catch (_) {
    return [];
  }
}

function saveToryChatArchives(list, chatMode = getToryChatSessionKey()) {
  if (!state.projectId) return;
  try {
    localStorage.setItem(
      toryChatArchiveKey(state.projectId, chatMode),
      JSON.stringify((list || []).slice(0, TORY_CHAT_ARCHIVE_MAX)),
    );
  } catch (_) {
    /* ignore quota */
  }
}

function titleFromToryChatMessages(messages) {
  const firstUser = (messages || []).find((m) => m.role === "user" && m.content);
  if (!firstUser) return i18n.t('app.이전_대화');
  const t = String(firstUser.content).replace(/\s+/g, " ").trim();
  return t.length > 42 ? `${t.slice(0, 42)}…` : t;
}

/** Archive current chat (if any), then optionally clear. Returns archived session or null. */
function archiveCurrentToryChat({ clearAfter = true, chatMode = getToryChatSessionKey() } = {}) {
  if (!state.projectId) return null;
  const mode = isToryCharacterChatSession(chatMode)
    ? String(chatMode)
    : normalizeToryChatMode(chatMode);
  const messages = loadToryChatHistory(mode);
  if (!messages.length) return null;
  const session = {
    id: `tch-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
    title: titleFromToryChatMessages(messages),
    messages: messages.slice(),
    archivedAt: new Date().toISOString(),
    messageCount: messages.length,
    chatMode: mode,
  };
  const archives = loadToryChatArchives(mode);
  archives.unshift(session);
  saveToryChatArchives(archives, mode);
  if (clearAfter) {
    saveToryChatHistory([], mode);
    if (mode === getToryChatSessionKey()) renderToryChatMessages();
  }
  return session;
}

function formatToryChatArchiveWhen(iso) {
  if (!iso) return "";
  try {
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return "";
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    const hh = String(d.getHours()).padStart(2, "0");
    const mm = String(d.getMinutes()).padStart(2, "0");
    return `${y}.${m}.${day} ${hh}:${mm}`;
  } catch (_) {
    return "";
  }
}

function showToryChatHistoryListView() {
  toryChatHistoryViewId = null;
  $("toryChatHistoryList")?.classList.remove("hidden");
  $("toryChatHistoryListActions")?.classList.remove("hidden");
  $("toryChatHistoryDetail")?.classList.add("hidden");
  renderToryChatHistoryList();
}

function renderToryChatHistoryList() {
  const list = $("toryChatHistoryList");
  if (!list) return;
  if (!state.projectId) {
    list.innerHTML = i18n.t('app.p_class_tory_chat_histo_3');
    return;
  }
  const mode = getToryChatSessionKey();
  const archives = loadToryChatArchives(mode);
  if (!archives.length) {
    const names = getToryChatPartnerNames();
    const kind = isToryCharacterChatSession(mode)
      ? (names.length ? names.join(" · ") : i18n.t('app.캐릭터'))
      : (normalizeToryChatMode(mode) === "successAnalysis" ? i18n.t('app.흥행요인_분석가') : i18n.t('app.일반'));
    list.innerHTML = `${i18n.t('app.p_class_tory_chat_histo_4', {kind: kind})}`;
    return;
  }
  list.innerHTML = archives.map((s) => {
    const when = formatToryChatArchiveWhen(s.archivedAt);
    const count = s.messageCount || s.messages.length;
    return `
      <button type="button" class="tory-chat-history-item" data-tory-chat-archive="${escapeHtml(s.id)}">
        <strong>${escapeHtml(s.title)}</strong>
        <span class="count">${count}개</span>
        <span class="meta">${when ? `보관 ${escapeHtml(when)}` : i18n.t('app.이전_대화')}</span>
      </button>`;
  }).join("");
}

function openToryChatHistoryDetail(archiveId) {
  const session = loadToryChatArchives().find((s) => s.id === archiveId);
  if (!session) {
    toast(i18n.t('app.대화를_찾지_못했어요'));
    showToryChatHistoryListView();
    return;
  }
  toryChatHistoryViewId = session.id;
  $("toryChatHistoryList")?.classList.add("hidden");
  $("toryChatHistoryListActions")?.classList.add("hidden");
  const detail = $("toryChatHistoryDetail");
  detail?.classList.remove("hidden");
  if ($("toryChatHistoryDetailTitle")) {
    $("toryChatHistoryDetailTitle").textContent = session.title;
  }
  const box = $("toryChatHistoryDetailMessages");
  if (box) {
    box.innerHTML = session.messages.map((m) => {
      const isUser = m.role === "user";
      const cls = isUser ? "is-user" : "is-tory";
      const body = isUser
        ? escapeHtml(m.content)
        : (m.contentHtml
          ? sanitizeToryChatHtml(m.contentHtml)
          : escapeHtml(m.content).replace(/\r\n|\r|\n/g, "<br>"));
      return `<div class="tory-chat-bubble ${cls}">${toryChatBubbleMetaHtml(isUser)}<div class="tory-chat-bubble-body">${body}</div></div>`;
    }).join("");
    box.scrollTop = 0;
  }
}

function openToryChatHistoryModal() {
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  const modal = $("toryChatHistoryModal");
  if (!modal) return;
  showToryChatHistoryListView();
  modal.classList.remove("hidden");
}

function closeToryChatHistoryModal() {
  $("toryChatHistoryModal")?.classList.add("hidden");
  toryChatHistoryViewId = null;
}

function restoreToryChatArchive(archiveId, chatMode = getToryChatSessionKey()) {
  const mode = isToryCharacterChatSession(chatMode)
    ? String(chatMode)
    : normalizeToryChatMode(chatMode);
  const session = loadToryChatArchives(mode).find((s) => s.id === archiveId);
  if (!session) return toast(i18n.t('app.대화를_찾지_못했어요'));
  if (!isToryCharacterChatSession(mode) && mode !== getToryChatMode()) {
    setToryChatMode(mode, { quiet: true });
  }
  const current = loadToryChatHistory(mode);
  if (current.length) {
    const ok = window.confirm(
      i18n.t('app.지금_진행_중인_대화가_있어요_현재_대화를'),
    );
    if (!ok) return;
    archiveCurrentToryChat({ clearAfter: true, chatMode: mode });
  }
  saveToryChatHistory(session.messages, mode);
  if (isToryCharacterChatSession(mode)) {
    setToryChatHub("character-room", { quiet: true });
  } else {
    setToryChatHub("tory", { quiet: true });
  }
  renderToryChatMessages();
  closeToryChatHistoryModal();
  // Ensure chat UI is visible
  if (toryChatPopupOpen) {
    requestAnimationFrame(() => $("toryChatInput")?.focus());
  } else {
    setAiPanelTab("chat", { chatHub: toryChatHub });
  }
  toast(i18n.t('app.이전_대화를_불러왔어요_이어서_이야기할_수'));
}

function deleteToryChatArchive(archiveId, chatMode = getToryChatSessionKey()) {
  const mode = normalizeToryChatMode(chatMode);
  const archives = loadToryChatArchives(mode).filter((s) => s.id !== archiveId);
  saveToryChatArchives(archives, mode);
  toast(i18n.t('app.히스토리에서_삭제했어요'));
  showToryChatHistoryListView();
}

function setupToryChatHistoryUi() {
  document.querySelectorAll("[data-close-tory-chat-history]").forEach((el) => {
    el.addEventListener("click", closeToryChatHistoryModal);
  });
  $("toryChatHistoryBackButton")?.addEventListener("click", () => showToryChatHistoryListView());
  $("toryChatHistoryList")?.addEventListener("click", (event) => {
    const btn = event.target.closest?.("[data-tory-chat-archive]");
    if (!btn) return;
    openToryChatHistoryDetail(btn.dataset.toryChatArchive);
  });
  $("toryChatHistoryRestoreButton")?.addEventListener("click", () => {
    if (toryChatHistoryViewId) restoreToryChatArchive(toryChatHistoryViewId);
  });
  $("toryChatHistoryDeleteButton")?.addEventListener("click", () => {
    if (!toryChatHistoryViewId) return;
    if (!window.confirm(i18n.t('app.이_대화_기록을_완전히_삭제할까요'))) return;
    deleteToryChatArchive(toryChatHistoryViewId);
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !$("toryChatHistoryModal")?.classList.contains("hidden")) {
      // If detail open, go back to list first
      if (toryChatHistoryViewId && !$("toryChatHistoryDetail")?.classList.contains("hidden")) {
        showToryChatHistoryListView();
        return;
      }
      closeToryChatHistoryModal();
    }
  });
}

function toryChatBubbleMetaHtml(isUser) {
  if (isUser) {
    return `<span class="tory-chat-bubble-meta is-user-name">`
      + i18n.t('app.span_class_tory_chat_bu')
      + i18n.t('app.나_span');
  }
  if (toryChatHub === "character-room") {
    const names = getToryChatPartnerNames();
    const label = names.length ? names.join(" · ") : i18n.t('app.캐릭터');
    return `<span class="tory-chat-bubble-meta is-tory-name">`
      + `<span class="tory-chat-bubble-pen" aria-hidden="true" title="${escapeHtml(label)}">🎭</span>`
      + `${escapeHtml(label)}</span>`;
  }
  const mascot = typeof TORY_MODAL_MASCOT_SVG === "string" ? TORY_MODAL_MASCOT_SVG : "";
  return `<span class="tory-chat-bubble-meta is-tory-name">`
    + `<span class="tory-chat-bubble-mascot" aria-hidden="true">${mascot}</span>`
    + i18n.t('app.토리_span');
}

function toryChatBubbleCopyButtonHtml(isUser) {
  if (isUser || toryChatHub !== "character-room") return "";
  return i18n.t('app.button_type_button_clas')
    + `<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">`
    + `<rect x="9" y="9" width="13" height="13" rx="2"/>`
    + `<path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/>`
    + `</svg></button>`;
}

function renderToryChatMessages() {
  const box = $("toryChatMessages");
  if (!box) return;
  updateToryChatSuccessUi();
  const history = loadToryChatHistory();
  if (!history.length) {
    let empty = i18n.t('app.플롯_고민_캐릭터_말투_막히는_장면_br_1');
    if (toryChatHub === "character-room") {
      const names = getToryChatPartnerNames();
      empty = names.length > 1
        ? `${i18n.t('app.escapeHtml_names_join_단', {'escapeHtml(names.join(" · "))': escapeHtml(names.join(" · "))})}`
        : `${i18n.t('app.escapeHtml_names_0_이_인물', {'escapeHtml(names[0] || "이 인물")': escapeHtml(names[0] || "이 인물")})}`;
    } else if (getToryChatMode() === "successAnalysis") {
      empty = i18n.t('app.흥행요인_분석가_세션이에요_br_재미요소가');
    }
    box.innerHTML = `<p class="tory-chat-empty">${empty}</p>`;
    return;
  }
  box.innerHTML = history.map((m, index) => {
    const isUser = m.role === "user";
    const cls = isUser ? "is-user" : "is-tory";
    const body = isUser
      ? escapeHtml(m.content)
      : (m.contentHtml
        ? sanitizeToryChatHtml(m.contentHtml)
        : escapeHtml(m.content).replace(/\r\n|\r|\n/g, "<br>"));
    const copyClass = (!isUser && toryChatHub === "character-room") ? " has-copy" : "";
    return `<div class="tory-chat-bubble ${cls}${copyClass}" data-msg-index="${index}" data-msg-role="${isUser ? "user" : "tory"}">${toryChatBubbleCopyButtonHtml(isUser)}${toryChatBubbleMetaHtml(isUser)}<div class="tory-chat-bubble-body">${body}</div></div>`;
  }).join("");
  box.scrollTop = box.scrollHeight;
  syncToryChatHighlightBar();
}

async function copyToryChatCharacterReply(button) {
  const bubble = button?.closest?.(".tory-chat-bubble");
  if (!bubble || bubble.classList.contains("is-pending")) return;
  const index = Number(bubble.getAttribute("data-msg-index"));
  const history = loadToryChatHistory();
  const message = Number.isInteger(index) ? history[index] : null;
  const text = String(message?.content || "").replace(/\r\n/g, "\n");
  if (!text) return toast(i18n.t('app.복사할_내용이_없어요'));
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
    } else {
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.setAttribute("readonly", "");
      ta.style.position = "fixed";
      ta.style.left = "-9999px";
      document.body.appendChild(ta);
      ta.select();
      document.execCommand("copy");
      ta.remove();
    }
    toast(i18n.t('app.복사되었습니다'));
  } catch (_) {
    toast(i18n.t('app.복사에_실패했어요_직접_선택해서_복사해_주세'));
  }
}

function updateToryChatSuccessUi() {
  const linked = Boolean(getLinkedSuccessProfileId());
  const inSuccess = getToryChatMode() === "successAnalysis" && toryChatHub === "tory";
  const inCharacter = toryChatHub === "character-room";
  const summon = $("toryChatSuccessSummonButton");
  const banner = $("toryChatSuccessBanner");
  summon?.classList.toggle("hidden", inCharacter || !linked || inSuccess || toryChatHub !== "tory");
  banner?.classList.toggle("hidden", inCharacter || !inSuccess);
  $("aiChatView")?.classList.toggle("is-success-analysis", inSuccess && !inCharacter);
  if (inSuccess && !linked && toryChatHub === "tory") {
    toryChatMode = "general";
    banner?.classList.add("hidden");
    summon?.classList.add("hidden");
  }
}

/** Saved selection for palette (selection can drop on some browsers). */
let toryChatSavedHighlight = null;

function syncToryChatHighlightBar() {
  const bar = $("toryChatHighlightBar");
  if (!bar) return;
  const color = (typeof formatColorState !== "undefined" && formatColorState.highlight)
    || (typeof FORMAT_COLOR_DEFAULTS !== "undefined" && FORMAT_COLOR_DEFAULTS.highlight)
    || "#f1c40f";
  bar.style.background = color;
}

function getToryChatSelectionInfo() {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0 || sel.isCollapsed) return null;
  const range = sel.getRangeAt(0);
  let node = range.commonAncestorContainer;
  if (node.nodeType === Node.TEXT_NODE) node = node.parentElement;
  const bubble = node?.closest?.(".tory-chat-bubble.is-tory");
  if (!bubble || !bubble.closest("#toryChatMessages")) return null;
  const body = bubble.querySelector(".tory-chat-bubble-body");
  if (!body) return null;
  const startOk = body === range.startContainer || body.contains(range.startContainer);
  const endOk = body === range.endContainer || body.contains(range.endContainer);
  if (!startOk || !endOk) return null;
  const index = Number(bubble.dataset.msgIndex);
  if (!Number.isFinite(index)) return null;
  return { range, bubble, body, index, text: sel.toString() };
}

function captureToryChatHighlightSelection() {
  const info = getToryChatSelectionInfo();
  if (!info) {
    toryChatSavedHighlight = null;
    return null;
  }
  try {
    toryChatSavedHighlight = {
      range: info.range.cloneRange(),
      index: info.index,
      body: info.body,
      text: info.text,
    };
  } catch (_) {
    toryChatSavedHighlight = { range: info.range, index: info.index, body: info.body, text: info.text };
  }
  return toryChatSavedHighlight;
}

function resolveToryChatHighlightInfo() {
  const live = getToryChatSelectionInfo();
  if (live) {
    captureToryChatHighlightSelection();
    return live;
  }
  const saved = toryChatSavedHighlight;
  if (!saved?.range || !saved?.body || !document.contains(saved.body)) {
    toryChatSavedHighlight = null;
    return null;
  }
  return {
    range: saved.range,
    bubble: saved.body.closest?.(".tory-chat-bubble"),
    body: saved.body,
    index: saved.index,
    text: saved.text || "",
  };
}

function persistToryChatBubbleHtml(msgIndex, bodyEl) {
  const list = loadToryChatHistory();
  const item = list[msgIndex];
  if (!item || item.role !== "tory" || !bodyEl) return;
  const html = sanitizeToryChatHtml(bodyEl.innerHTML);
  item.contentHtml = html;
  item.content = plainTextFromChatHtml(html) || item.content;
  saveToryChatHistory(list);
}

function applyToryChatHighlight(color) {
  const info = resolveToryChatHighlightInfo();
  if (!info) {
    toast(i18n.t('app.토리_답변에서_칠할_부분을_드래그한_뒤_형광'));
    return;
  }
  const next = color
    || (typeof formatColorState !== "undefined" && formatColorState.highlight)
    || (typeof FORMAT_COLOR_DEFAULTS !== "undefined" && FORMAT_COLOR_DEFAULTS.highlight)
    || "#f1c40f";
  if (typeof setFormatColorState === "function") {
    setFormatColorState("highlight", next);
  }
  const mark = document.createElement("mark");
  mark.className = "tory-chat-hl";
  mark.style.backgroundColor = next;
  mark.style.color = (typeof contrastInkForHighlightBg === "function"
    ? contrastInkForHighlightBg(next)
    : "#1a1510");
  try {
    info.range.surroundContents(mark);
  } catch (_) {
    // Selection crosses elements — extract and wrap
    try {
      const frag = info.range.extractContents();
      mark.appendChild(frag);
      info.range.insertNode(mark);
    } catch (err) {
      toast(i18n.t('app.선택_구간에_형광펜을_칠하지_못했어요_다시'));
      return;
    }
  }
  window.getSelection()?.removeAllRanges();
  toryChatSavedHighlight = null;
  persistToryChatBubbleHtml(info.index, info.body);
  syncToryChatHighlightBar();
  toast(i18n.t('app.형광펜으로_칠했어요'));
}

function clearToryChatHighlight() {
  const info = resolveToryChatHighlightInfo();
  if (!info) {
    toast(i18n.t('app.지울_형광펜_부분을_토리_답변에서_드래그해'));
    return;
  }
  const marks = [...info.body.querySelectorAll("mark.tory-chat-hl, span.tory-chat-hl, .tory-chat-hl")];
  let cleared = 0;
  marks.forEach((el) => {
    try {
      if (typeof info.range.intersectsNode === "function" && !info.range.intersectsNode(el)) return;
    } catch (_) {
      /* ignore range errors */
    }
    const parent = el.parentNode;
    if (!parent) return;
    while (el.firstChild) parent.insertBefore(el.firstChild, el);
    parent.removeChild(el);
    try { parent.normalize(); } catch (_) { /* ignore */ }
    cleared += 1;
  });
  if (!cleared) {
    // Selection fully inside a mark that may not be listed if nested oddly
    let node = info.range.commonAncestorContainer;
    if (node.nodeType === Node.TEXT_NODE) node = node.parentElement;
    const wrap = node?.closest?.("mark.tory-chat-hl, .tory-chat-hl");
    if (wrap && info.body.contains(wrap)) {
      const parent = wrap.parentNode;
      while (wrap.firstChild) parent.insertBefore(wrap.firstChild, wrap);
      parent.removeChild(wrap);
      try { parent.normalize(); } catch (_) { /* ignore */ }
      cleared = 1;
    }
  }
  window.getSelection()?.removeAllRanges();
  toryChatSavedHighlight = null;
  persistToryChatBubbleHtml(info.index, info.body);
  syncToryChatHighlightBar();
  if (cleared) toast(i18n.t('app.형광펜을_지웠어요'));
  else toast(i18n.t('app.선택한_구간에_형광펜이_없어요'));
}

function collectFromToryChat() {
  // Prefer selection inside chat (tory or user), else last tory message
  const sel = window.getSelection();
  let text = "";
  if (sel && !sel.isCollapsed && sel.rangeCount) {
    const range = sel.getRangeAt(0);
    let node = range.commonAncestorContainer;
    if (node.nodeType === Node.TEXT_NODE) node = node.parentElement;
    if (node?.closest?.("#toryChatMessages, #toryChatHistoryDetailMessages")) {
      text = sel.toString().trim();
    }
  }
  if (!text) {
    const history = loadToryChatHistory();
    for (let i = history.length - 1; i >= 0; i -= 1) {
      if (history[i].role === "tory" && history[i].content) {
        text = history[i].content;
        break;
      }
    }
  }
  if (!text) {
    toast(i18n.t('app.수집할_토리_답변이_없어요_대화를_하거나_문'));
    return;
  }
  collectToToryVault({
    text,
    title: toryChatHub === "character-room" ? i18n.t('app.캐릭터_대화_수집') : i18n.t('app.토리_대화_수집'),
    mode: "chat",
    prompt: "",
  });
}

async function sendToryChatMessage(event) {
  if (event) event.preventDefault();
  if (toryChatSending) return;
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  const sessionKey = getToryChatSessionKey();
  const isCharacter = isToryCharacterChatSession(sessionKey);
  const chatMode = isCharacter ? "character" : getToryChatMode();
  if (!isCharacter && chatMode === "successAnalysis" && !getLinkedSuccessProfileId()) {
    setToryChatMode("general", { quiet: true });
    return toast(i18n.t('app.흥행_프로파일_연결이_없어_일반_대화로_전환'));
  }
  if (isCharacter && !getToryChatPartnerCharacters().length) {
    setToryChatHub("characters");
    return toast(i18n.t('app.대화할_인물을_먼저_골라_주세요'));
  }
  const input = $("toryChatInput");
  const text = (input?.value || "").trim();
  if (!text) return toast(i18n.t('app.메시지를_적어_주세요'));

  const history = loadToryChatHistory(sessionKey);
  // History sent to API excludes the new user message (server appends it as prompt)
  const apiHistory = history.map((m) => ({
    role: m.role === "user" ? "user" : "model",
    content: m.content,
  }));

  history.push({ role: "user", content: text, at: new Date().toISOString() });
  saveToryChatHistory(history, sessionKey);
  if (input) input.value = "";
  toryChatComposerDraft = "";
  renderToryChatMessages();

  // Pending bubble
  const box = $("toryChatMessages");
  if (box) {
    const pending = document.createElement("div");
    pending.className = "tory-chat-bubble is-tory is-pending";
    pending.id = "toryChatPending";
    pending.innerHTML = `${i18n.t('app.toryChatBubbleMetaHtml', {'toryChatBubbleMetaHtml(false)': toryChatBubbleMetaHtml(false)})}`;
    box.appendChild(pending);
    box.scrollTop = box.scrollHeight;
  }

  toryChatSending = true;
  const sendBtn = $("toryChatSendButton");
  if (sendBtn) {
    sendBtn.disabled = true;
    sendBtn.textContent = i18n.t('app.생각_중');
  }

  try {
    const project = state.projects.find((item) => item.id === state.projectId);
    const mainGenre = state.mainGenre || project?.main_genre || "";
    const subGenre = state.subGenre || project?.sub_genre || "";
    const payload = {
      mode: "chat",
      chat_mode: chatMode,
      prompt: text,
      user_prompt: text,
      history: apiHistory,
      project_title: project?.title || "",
      purpose: normalizePurposeKey(state.projectPurpose || project?.purpose || "general_novel"),
      main_genre: mainGenre,
      sub_genre: subGenre,
      main_genre_label: mainGenreLabel(mainGenre),
      sub_genre_label: subGenreLabel(mainGenre, subGenre),
      keywords: normalizeKeywordList(state.keywords || project?.keywords || []),
      scene_title: state.scene?.title || $("sceneTitle")?.value || "",
      scene_synopsis: state.scene?.synopsis_md || $("sceneSynopsis")?.value || "",
      scene_content: state.sceneId ? getEditorContent() : "",
      persona_mode: getToryPersonaMode(),
      ...buildToryProjectContextPayload(),
    };
    if (isCharacter) {
      payload.chat_partners = buildToryChatPartnerPayload();
    }
    if (chatMode === "successAnalysis") {
      const profile = await ensureLinkedSuccessProfile();
      if (!profile) {
        throw new Error(i18n.t('app.흥행_프로파일을_불러오지_못했어요_연결을_확'));
      }
      // Flat shape for server (profile fields + factors)
      payload.success_profile = {
        reader_popularity_factors: profile.reader_popularity_factors || profile.profile?.reader_popularity_factors,
        editor_popularity_factors: profile.editor_popularity_factors || profile.profile?.editor_popularity_factors,
        must_follow_factors: profile.must_follow_factors || profile.profile?.must_follow_factors,
        hook_style: profile.hook_style || profile.profile?.hook_style || "",
        pacing_pattern: profile.pacing_pattern || profile.profile?.pacing_pattern || "",
        dialogue_narration_balance:
          profile.dialogue_narration_balance || profile.profile?.dialogue_narration_balance || "",
        style_signature: profile.style_signature || profile.profile?.style_signature || "",
        summary: profile.summary || profile.profile?.summary || "",
      };
      // Nested profile object merge for factor fallbacks
      if (profile.profile && typeof profile.profile === "object") {
        payload.success_profile = { ...profile.profile, ...payload.success_profile };
      }
      payload.linked_success_profile_id = getLinkedSuccessProfileId();
    }
    const result = await api("/api/ai/assist", {
      method: "POST",
      body: JSON.stringify(payload),
    });
    const reply = String(result.text || "").trim() || i18n.t('app.응답이_비어_있어요');
    const next = loadToryChatHistory(sessionKey);
    next.push({ role: "tory", content: reply, at: new Date().toISOString() });
    saveToryChatHistory(next, sessionKey);
    renderToryChatMessages();
  } catch (error) {
    // Drop the pending user message only if we want retry — keep user msg, add error note
    const next = loadToryChatHistory(sessionKey);
    next.push({
      role: "tory",
      content: `${i18n.t('app.죄송해요_지금은_답을_못_했어요_error', {'error.message || "잠시 후 다시 시도해 주세요."': error.message || "잠시 후 다시 시도해 주세요."})}`,
      at: new Date().toISOString(),
    });
    saveToryChatHistory(next, sessionKey);
    renderToryChatMessages();
    handleError(error);
  } finally {
    toryChatSending = false;
    if (sendBtn) {
      sendBtn.disabled = false;
      sendBtn.textContent = i18n.t('app.보내기');
    }
    $("toryChatPending")?.remove();
  }
}

const TORY_PERSONA_STORAGE_KEY = "supertory.toryPersonaMode";
const TORY_PERSONA_MODES = ["default", "secretary", "friend", "aegyo", "teacher", "grumbler"];

function getToryPersonaMode() {
  try {
    const raw = (localStorage.getItem(TORY_PERSONA_STORAGE_KEY) || "default").trim().toLowerCase();
    return TORY_PERSONA_MODES.includes(raw) ? raw : "default";
  } catch (_) {
    return "default";
  }
}

function setToryPersonaMode(mode, { silent = false } = {}) {
  const next = TORY_PERSONA_MODES.includes(mode) ? mode : "default";
  try {
    localStorage.setItem(TORY_PERSONA_STORAGE_KEY, next);
  } catch (_) {
    /* ignore */
  }
  syncToryPersonaMenuUi();
  if (!silent) {
    const labels = {
      default: i18n.t('app.친절한_조수'),
      secretary: i18n.t('app.진지_비서'),
      friend: i18n.t('app.친구'),
      aegyo: i18n.t('app.애교'),
      teacher: i18n.t('app.선생님'),
      grumbler: i18n.t('app.투덜이'),
    };
    toast(`${i18n.t('app.토리_모드_labels_next_next', {'labels[next] || next': labels[next] || next})}`);
  }
}

function hideToryPersonaMenu() {
  $("toryPersonaMenu")?.classList.add("hidden");
}

function syncToryPersonaMenuUi() {
  const current = getToryPersonaMode();
  document.querySelectorAll("#toryPersonaMenu [data-tory-persona]").forEach((btn) => {
    btn.classList.toggle("is-active", btn.dataset.toryPersona === current);
  });
}

function showToryPersonaMenu(clientX, clientY) {
  const menu = $("toryPersonaMenu");
  if (!menu) return;
  hideToryPersonaMenu();
  syncToryPersonaMenuUi();
  menu.classList.remove("hidden");
  const pad = 8;
  const rect = menu.getBoundingClientRect();
  let left = clientX;
  let top = clientY;
  if (left + (rect.width || 220) > window.innerWidth - pad) {
    left = Math.max(pad, window.innerWidth - (rect.width || 220) - pad);
  }
  if (top + (rect.height || 200) > window.innerHeight - pad) {
    top = Math.max(pad, window.innerHeight - (rect.height || 200) - pad);
  }
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
}

function setupToryPersonaSelect() {
  // Persona is chosen via right-click on 도우미 tab (no always-visible bar)
  $("aiTabTools")?.addEventListener("contextmenu", (event) => {
    event.preventDefault();
    event.stopPropagation();
    setUiFeatureCtxTarget?.($("aiTabTools"));
    showToryPersonaMenu(event.clientX, event.clientY);
  });
  $("toryPersonaMenu")?.addEventListener("click", (event) => {
    const item = event.target.closest?.("[data-tory-persona]");
    if (!item) return;
    event.preventDefault();
    setToryPersonaMode(item.dataset.toryPersona || "default");
    hideToryPersonaMenu();
  });
  document.addEventListener("click", (event) => {
    if (!event.target.closest?.("#toryPersonaMenu, #aiTabTools")) hideToryPersonaMenu();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") hideToryPersonaMenu();
  });
  syncToryPersonaMenuUi();
}

function clearToryChatHistory() {
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  const mode = getToryChatSessionKey();
  if (!loadToryChatHistory(mode).length) return toast(i18n.t('app.지울_대화가_없어요'));
  if (!window.confirm(i18n.t('app.현재_대화를_비울까요_내용은_히스토리에_보관'))) return;
  const saved = archiveCurrentToryChat({ clearAfter: true, chatMode: mode });
  toast(saved ? i18n.t('app.대화를_지우고_히스토리에_보관했어요') : i18n.t('app.대화를_지웠어요'));
}

function toggleToryChatCharacterId(characterId, selected) {
  const id = Number(characterId);
  if (!Number.isFinite(id) || id <= 0) return;
  const set = new Set(normalizeToryChatCharacterIds(toryChatCharacterIds));
  if (selected) set.add(id);
  else set.delete(id);
  toryChatCharacterIds = normalizeToryChatCharacterIds([...set]);
}

function renderToryChatCharacterPicker() {
  const list = $("toryChatCharacterList");
  const startBtn = $("toryChatCharacterStart");
  if (!list) return;
  const selected = new Set(normalizeToryChatCharacterIds(toryChatCharacterIds));
  if (!state.projectId) {
    list.innerHTML = i18n.t('app.p_class_hint_먼저_작품을_선택해');
    if (startBtn) startBtn.disabled = true;
    return;
  }
  const chars = Array.isArray(state.characters) ? state.characters : [];
  if (!chars.length) {
    list.innerHTML = i18n.t('app.p_class_hint_설정집에_인물이_없');
    if (startBtn) startBtn.disabled = true;
    return;
  }
  list.innerHTML = chars.map((ch) => {
    const id = Number(ch.id);
    const name = escapeHtml(String(ch.name || "").trim() || `${i18n.t('app.인물_id', {id: id})}`);
    const role = escapeHtml(roleLabel[ch.role] || ch.role || "");
    const summary = escapeHtml(
      String(ch.short_description || "").trim()
      || String(ch.profile_md || "").replace(/\s+/g, " ").trim().slice(0, 80)
      || "",
    );
    const on = selected.has(id);
    return `
      <label class="tory-chat-character-row ${on ? "is-selected" : ""}">
        <input type="checkbox" data-tory-chat-character="${id}" ${on ? "checked" : ""}>
        <span class="tory-chat-character-row-body">
          <span class="tory-chat-character-row-name">${name}</span>
          <span class="tory-chat-character-row-meta">${role}${role && summary ? " · " : ""}${summary}</span>
        </span>
      </label>`;
  }).join("");
  if (startBtn) startBtn.disabled = selected.size === 0;
}

function toryChatCharacterFullIdentity(ch) {
  const short = String(ch?.short_description || "").trim();
  const profile = String(ch?.profile_md || "").trim();
  if (short && profile && short !== profile) return `${short}\n\n${profile}`;
  return short || profile || "";
}

function isToryChatCharacterAllOpen() {
  const modal = $("toryChatCharacterAllModal");
  return Boolean(modal && !modal.classList.contains("hidden"));
}

function closeToryChatCharacterAllModal() {
  $("toryChatCharacterAllModal")?.classList.add("hidden");
}

function toryChatCharacterAllCardHtml(ch, { selected, disabled, checkAttr }) {
  const id = Number(ch.id);
  const name = escapeHtml(String(ch.name || "").trim() || `${i18n.t('app.인물_id', {id: id})}`);
  const role = escapeHtml(roleLabel[ch.role] || ch.role || "");
  const identity = escapeHtml(toryChatCharacterFullIdentity(ch) || i18n.t('app.소개가_아직_없어요'));
  return `<label class="reader-persona-card reader-debate-card tory-chat-character-all-card${selected ? " is-selected" : ""}${disabled ? " is-disabled" : ""}" data-tory-chat-all-id="${id}">`
    + `<input type="checkbox" ${checkAttr}="${id}"${selected ? " checked" : ""}${disabled ? " disabled" : ""}>`
    + `<span class="reader-persona-card-text">`
    + `<span class="reader-persona-card-name">${name}${role ? ` <span class="tory-chat-character-all-role">· ${role}</span>` : ""}</span>`
    + `<span class="reader-persona-card-identity">${identity}</span>`
    + `</span>`
    + `</label>`;
}

function renderToryChatCharacterAllGrid() {
  const grid = $("toryChatCharacterAllGrid");
  if (!grid) return;
  const isSim = charListMode === "sim";
  const chars = Array.isArray(state.characters) ? state.characters : [];
  if (!state.projectId) {
    grid.innerHTML = i18n.t('app.p_class_hint_먼저_작품을_선택해');
    return;
  }
  if (!chars.length) {
    grid.innerHTML = i18n.t('app.p_class_hint_설정집에_인물이_없');
    return;
  }
  if (isSim) {
    const selected = new Set((charDebateState.selectedIds || []).map(Number));
    const atMax = selected.size >= CHAR_DEBATE_MAX;
    grid.innerHTML = chars.map((ch) => toryChatCharacterAllCardHtml(ch, {
      selected: selected.has(Number(ch.id)),
      disabled: !selected.has(Number(ch.id)) && atMax,
      checkAttr: "data-char-debate-all-check",
    })).join("");
  } else {
    const selected = new Set(normalizeToryChatCharacterIds(toryChatCharacterIds));
    grid.innerHTML = chars.map((ch) => toryChatCharacterAllCardHtml(ch, {
      selected: selected.has(Number(ch.id)),
      disabled: false,
      checkAttr: "data-tory-chat-all-check",
    })).join("");
  }
  syncToryChatCharacterAllCount();
}

function syncToryChatCharacterAllCount() {
  const countEl = $("toryChatCharacterAllCount");
  if (!countEl) return;
  const isSim = charListMode === "sim";
  countEl.classList.toggle("hidden", !isSim);
  if (!isSim) return;
  const n = (charDebateState.selectedIds || []).length;
  countEl.textContent = `${i18n.t('app.n_CHAR_DEBATE_MAX_명_선택됨', {n: n, CHAR_DEBATE_MAX: CHAR_DEBATE_MAX})}`;
}

function openToryChatCharacterAllModal() {
  const modal = $("toryChatCharacterAllModal");
  const grid = $("toryChatCharacterAllGrid");
  if (!modal || !grid) return;
  if (!state.projectId) {
    toast(i18n.t('app.작품을_먼저_선택해_주세요'));
    return;
  }
  const isSim = charListMode === "sim";
  const title = $("toryChatCharacterAllTitle");
  const hint = $("toryChatCharacterAllHint");
  if (title) title.textContent = isSim ? i18n.t('app.시뮬레이션_전체보기') : i18n.t('app.내_캐릭터_전체보기');
  if (hint) {
    hint.textContent = isSim
      ? i18n.t('app.카드를_눌러_시뮬레이션할_인물을_골라_주세요')
      : i18n.t('app.소개는_잘리지_않고_전부_보여_줍니다_고른');
  }
  renderToryChatCharacterAllGrid();
  modal.classList.remove("hidden");
  requestAnimationFrame(() => {
    const closeBtn = modal.querySelector("[data-close-tory-chat-character-all].modal-close");
    try {
      closeBtn?.focus({ preventScroll: true });
    } catch (_) {
      closeBtn?.focus();
    }
  });
}

function setCharListMode(mode) {
  if (mode === "sim" && !assertClusterFeature("character_sim")) return;
  if (mode !== "sim" && !isClusterFeatureVisible("character_chat") && isClusterFeatureVisible("character_sim")) {
    mode = "sim";
  } else if (mode !== "sim" && !isClusterFeatureVisible("character_chat")) {
    assertClusterFeature("character_chat");
    return;
  }
  const next = mode === "sim" ? "sim" : "chat";
  charListMode = next;
  const isSim = next === "sim";
  document.querySelectorAll("[data-char-list-mode]").forEach((btn) => {
    const on = btn.getAttribute("data-char-list-mode") === next;
    btn.classList.toggle("is-active", on);
    btn.setAttribute("aria-selected", on ? "true" : "false");
  });
  $("toryChatCharacterChatPane")?.classList.toggle("hidden", isSim);
  $("toryChatCharacterSimPane")?.classList.toggle("hidden", !isSim);
  if (isSim) {
    void prepareCharDebatePane();
  } else {
    renderToryChatCharacterPicker();
  }
  if (isToryChatCharacterAllOpen()) openToryChatCharacterAllModal();
}

async function openToryChatCharacterPicker() {
  if (!isClusterFeatureVisible("character_chat") && !isClusterFeatureVisible("character_sim")) {
    assertClusterFeature("character_chat");
    return;
  }
  if (!state.projectId) {
    setToryChatHub("characters", { quiet: true });
    toast(i18n.t('app.먼저_작품을_선택해_주세요'));
    return;
  }
  if (!Array.isArray(state.characters) || !state.characters.length) {
    try {
      const characters = await api(`/api/projects/${state.projectId}/characters`);
      if (Array.isArray(characters)) state.characters = characters;
    } catch (_) { /* keep empty */ }
  }
  toryChatCharacterIds = normalizeToryChatCharacterIds(toryChatCharacterIds)
    .filter((id) => (state.characters || []).some((ch) => Number(ch.id) === id));
  setToryChatHub("characters");
}

function startToryChatWithSelectedCharacters() {
  if (!assertClusterFeature("character_chat")) return;
  const ids = normalizeToryChatCharacterIds(toryChatCharacterIds);
  if (!ids.length) return toast(i18n.t('app.대화할_인물을_한_명_이상_골라_주세요'));
  toryChatCharacterIds = ids;
  setToryChatHub("character-room");
  const names = getToryChatPartnerNames();
  toast(
    names.length > 1
      ? `${i18n.t('app.names_join_단톡방을_열었어요', {'names.join(" · ")': names.join(" · ")})}`
      : `${i18n.t('app.names_0_인물_와_대화를_시작했어요', {'names[0] || "인물"': names[0] || "인물"})}`,
  );
  requestAnimationFrame(() => $("toryChatInput")?.focus());
}

const READER_PERSONA_CATEGORY_LABELS = {
  genre_specialist: i18n.t('app.장르_전문'),
  sub_genre_specialist: i18n.t('app.서브장르'),
  taste_preference: i18n.t('app.취향'),
  narrative_critic: i18n.t('app.서사_비평'),
  structure_wildcard: i18n.t('app.구조'),
};
const READER_AVATAR_BASE = "/assets/reader_avatars";
const READER_AVATAR_VERSION = "20260816d";
const READER_CHAT_SESSION_PREFIX = "supertory.readerChat.sessions.";

/** @type {Record<string, any[]>|null} */
let readerPersonaCache = null;
/** @type {any|null} */
let readerChatPersona = null;
/** @type {string} */
let readerChatSelectedId = "";
/** @type {Array<{role:string,content:string}>} */
let readerChatMessages = [];
let readerChatSending = false;
/** @type {{sceneId:number,title:string,content:string}|null} */
let readerChatAttached = null;

function readerChatSessionStorageKey(projectId = state.projectId) {
  return `${READER_CHAT_SESSION_PREFIX}${projectId || "0"}`;
}

function loadReaderChatSessions(projectId = state.projectId) {
  if (!projectId) return {};
  try {
    const raw = localStorage.getItem(readerChatSessionStorageKey(projectId));
    const obj = raw ? JSON.parse(raw) : {};
    return obj && typeof obj === "object" && !Array.isArray(obj) ? obj : {};
  } catch (_) {
    return {};
  }
}

function saveReaderChatSessions() {
  if (!state.projectId) return;
  try {
    localStorage.setItem(
      readerChatSessionStorageKey(state.projectId),
      JSON.stringify(state.readerSessions || {}),
    );
  } catch (_) {
    /* ignore quota */
  }
}

function rememberReaderChatSession(personaId, sessionId) {
  const id = String(personaId || "").trim();
  const sid = String(sessionId || "").trim();
  if (!id || !sid) return;
  if (!state.readerSessions || typeof state.readerSessions !== "object") {
    state.readerSessions = {};
  }
  state.readerSessions[id] = sid;
  saveReaderChatSessions();
}

function readerAvatarUrl(personaId) {
  return `${READER_AVATAR_BASE}/${encodeURIComponent(String(personaId || "").trim())}.png?v=${READER_AVATAR_VERSION}`;
}

function readerInitial(name) {
  const text = String(name || "").trim();
  return text ? text.charAt(0) : "?";
}

function readerAvatarMarkup(personaId, name, extraClass) {
  const cls = extraClass || "reader-persona-avatar";
  const fallbackCls = extraClass && extraClass.includes("peer")
    ? "reader-chat-peer-avatar-fallback"
    : extraClass && extraClass.includes("msg")
      ? "reader-chat-msg-avatar-fallback"
      : "reader-persona-avatar-fallback";
  return `<span class="${cls}">`
    + `<img src="${escapeHtml(readerAvatarUrl(personaId))}" alt=""`
    + ` data-reader-avatar="${escapeHtml(personaId)}">`
    + `<span class="${fallbackCls} hidden" aria-hidden="true">${escapeHtml(readerInitial(name))}</span>`
    + `</span>`;
}

function bindReaderAvatarErrors(root) {
  const host = root || document;
  host.querySelectorAll("img[data-reader-avatar]").forEach((img) => {
    if (img.dataset.boundError === "1") return;
    img.dataset.boundError = "1";
    img.addEventListener("error", () => {
      const personaId = img.getAttribute("data-reader-avatar") || "";
      console.error("[reader-avatar] failed to load", personaId);
      img.classList.add("hidden");
      img.nextElementSibling?.classList.remove("hidden");
    });
  });
}

function summarizeReaderIdentity(text, limit = 72) {
  const raw = String(text || "").replace(/\s+/g, " ").trim();
  if (!raw) return "";
  if (raw.length <= limit) return raw;
  return `${raw.slice(0, limit - 1)}…`;
}

function readerPersonaCardHtml(persona, { fullIdentity = false } = {}) {
  const identity = fullIdentity
    ? String(persona.identity || "").replace(/\s+/g, " ").trim()
    : summarizeReaderIdentity(persona.identity);
  return `<button type="button" class="reader-persona-card" data-reader-persona="${escapeHtml(persona.id)}" data-category="${escapeHtml(persona.category || "")}" aria-pressed="false">`
    + readerAvatarMarkup(persona.id, persona.name, "reader-persona-avatar")
    + `<span class="reader-persona-card-text">`
    + `<span class="reader-persona-card-name">${escapeHtml(persona.name || "")}</span>`
    + `<span class="reader-persona-card-identity">${escapeHtml(identity)}</span>`
    + `</span>`
    + `</button>`;
}

function flattenReaderPersonas(grouped) {
  const out = [];
  Object.keys(READER_PERSONA_CATEGORY_LABELS).forEach((key) => {
    const list = grouped && grouped[key];
    if (Array.isArray(list)) {
      list.forEach((item) => {
        if (item && item.id) out.push(item);
      });
    }
  });
  return out;
}

function showReaderPersonaGrid() {
  $("readerPersonaPicker")?.classList.remove("hidden");
  const room = $("readerChatRoom");
  room?.classList.add("hidden");
  if (room) room.hidden = true;
  $("readerDebateRoom")?.classList.add("hidden");
}

function showReaderChatRoom() {
  $("readerPersonaPicker")?.classList.add("hidden");
  const room = $("readerChatRoom");
  room?.classList.remove("hidden");
  if (room) room.hidden = false;
}

function syncReaderChatView() {
  state.readerSessions = loadReaderChatSessions();
  if (readerChatPersona) {
    showReaderChatRoom();
    renderReaderChatPeer();
    renderReaderChatMessages();
    renderReaderChatAttachChip();
    return;
  }
  showReaderPersonaGrid();
  void loadAndRenderReaderPersonas();
}

function openReaderPersonaPicker() {
  if (typeof skipReaderDebateReveal === "function") skipReaderDebateReveal();
  readerChatPersona = null;
  readerChatMessages = [];
  readerChatAttached = null;
  readerChatSending = false;
  readerManuscriptAttachTarget = "chat";
  $("readerDebateRoom")?.classList.add("hidden");
  setToryChatHub("reader");
}

async function loadAndRenderReaderPersonas() {
  const grid = $("readerPersonaGrid");
  if (!grid) return;
  if (!state.projectId) {
    grid.innerHTML = i18n.t('app.p_class_hint_작품을_먼저_선택해');
    return;
  }
  try {
    if (!readerPersonaCache) {
      readerPersonaCache = await api("/api/reader-personas");
    }
    const people = flattenReaderPersonas(readerPersonaCache);
    if (!people.length) {
      grid.innerHTML = i18n.t('app.p_class_hint_가상_독자를_불러오');
      return;
    }
    grid.innerHTML = people.map((persona) => readerPersonaCardHtml(persona)).join("");
    bindReaderAvatarErrors(grid);
    syncReaderChatSelectionUi();
  } catch (error) {
    grid.innerHTML = i18n.t('app.p_class_hint_독자_목록을_불러오');
    handleError(error);
  }
}

function findReaderPersona(personaId) {
  return flattenReaderPersonas(readerPersonaCache).find((item) => item.id === personaId) || null;
}

function renderReaderChatPeer() {
  const persona = readerChatPersona;
  if (!persona) return;
  const avatarHost = $("readerChatPeerAvatar");
  if (avatarHost) {
    avatarHost.innerHTML = `<img src="${escapeHtml(readerAvatarUrl(persona.id))}" alt="" data-reader-avatar="${escapeHtml(persona.id)}">`
      + `<span class="reader-chat-peer-avatar-fallback hidden" aria-hidden="true">${escapeHtml(readerInitial(persona.name))}</span>`;
    bindReaderAvatarErrors(avatarHost);
  }
  const nameEl = $("readerChatPeerName");
  if (nameEl) nameEl.textContent = persona.name || i18n.t('app.가상_독자');
  const catEl = $("readerChatPeerCategory");
  if (catEl) catEl.textContent = READER_PERSONA_CATEGORY_LABELS[persona.category] || persona.category || "";
  const input = $("readerChatInput");
  if (input) {
    const who = persona.name || i18n.t('app.이_독자');
    input.placeholder = `${who}에게 말걸기\n(Enter 전송 Shift + Enter 줄바꿈)`;
    input.setAttribute("aria-label", `${i18n.t('app.who_에게_보낼_메시지', {who: who})}`);
  }
}

function renderReaderChatMessages() {
  const box = $("readerChatMessages");
  if (!box) return;
  const persona = readerChatPersona;
  const name = persona?.name || i18n.t('app.가상_독자');
  const pending = readerChatSending;
  if (!readerChatMessages.length && !pending) {
    box.innerHTML = `${i18n.t('app.p_class_reader_chat_emp', {'escapeHtml(name)': escapeHtml(name)})}`;
    return;
  }
  const rows = readerChatMessages.map((msg) => {
    const isUser = msg.role === "user";
    const cls = isUser ? "is-user" : "is-assistant";
    const avatar = isUser ? "" : readerAvatarMarkup(persona.id, name, "reader-chat-msg-avatar");
    const body = escapeHtml(msg.content || "").replace(/\r\n|\r|\n/g, "<br>");
    return `<div class="reader-chat-msg ${cls}">`
      + avatar
      + `<div class="reader-chat-msg-body">`
      + (isUser ? "" : `<span class="reader-chat-msg-name">${escapeHtml(name)}</span>`)
      + `<div class="reader-chat-bubble">${body}</div>`
      + `</div></div>`;
  });
  if (pending && persona) {
    rows.push(
      `<div class="reader-chat-msg is-assistant is-pending">`
      + readerAvatarMarkup(persona.id, name, "reader-chat-msg-avatar")
      + `<div class="reader-chat-msg-body">`
      + `<span class="reader-chat-msg-name">${escapeHtml(name)}</span>`
      + `${i18n.t('app.div_class_reader_chat_b', {'escapeHtml(name)': escapeHtml(name)})}`
      + `</div></div>`,
    );
  }
  box.innerHTML = rows.join("");
  bindReaderAvatarErrors(box);
  box.scrollTop = box.scrollHeight;
}

function renderReaderChatAttachChip() {
  const chip = $("readerChatAttachChip");
  const label = $("readerChatAttachLabel");
  if (!chip) return;
  const attached = readerChatAttached;
  const on = Boolean(attached);
  chip.classList.toggle("hidden", !on);
  chip.hidden = !on;
  if (label) label.textContent = attached ? `${i18n.t('app.첨부됨_attached_title', {'attached.title': attached.title})}` : "";
}

async function openReaderChatWithPersona(personaId) {
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  if (!readerPersonaCache) {
    try {
      readerPersonaCache = await api("/api/reader-personas");
    } catch (error) {
      handleError(error);
      return;
    }
  }
  const persona = findReaderPersona(personaId);
  if (!persona) return toast(i18n.t('app.그_독자를_찾지_못했어요'));
  readerChatPersona = persona;
  readerChatAttached = null;
  readerChatSending = false;
  state.readerSessions = loadReaderChatSessions();
  showReaderChatRoom();
  renderReaderChatPeer();
  renderReaderChatAttachChip();
  readerChatMessages = [];
  renderReaderChatMessages();
  try {
    const history = await api(
      `/api/reader-chat/history?work_id=${encodeURIComponent(state.projectId)}&persona_id=${encodeURIComponent(persona.id)}`,
    );
    if (history?.session_id) rememberReaderChatSession(persona.id, history.session_id);
    readerChatMessages = Array.isArray(history?.messages)
      ? history.messages
        .filter((m) => m && (m.role === "user" || m.role === "assistant") && String(m.content || "").trim())
        .map((m) => ({ role: m.role, content: String(m.content || "").trim() }))
      : [];
  } catch (error) {
    handleError(error);
  }
  renderReaderChatMessages();
  requestAnimationFrame(() => $("readerChatInput")?.focus());
}

function closeReaderScenePicker() {
  $("readerScenePickerModal")?.classList.add("hidden");
}

function openReaderScenePicker() {
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  const modal = $("readerScenePickerModal");
  const list = $("readerScenePickerList");
  if (!modal || !list) return;
  const episodes = typeof listExportEpisodes === "function" ? listExportEpisodes() : [];
  if (!episodes.length) {
    list.innerHTML = i18n.t('app.p_class_export_scene_em');
  } else {
    list.innerHTML = episodes.map((ep) => `
      <button type="button" class="export-scene-item" data-reader-scene="${ep.id}">
        <span>${escapeHtml(ep.label)}</span>
      </button>`).join("");
  }
  modal.classList.remove("hidden");
}

async function attachReaderScene(sceneId) {
  const id = Number(sceneId);
  if (!id) return;
  const episodes = typeof listExportEpisodes === "function" ? listExportEpisodes() : [];
  const ep = episodes.find((item) => Number(item.id) === id);
  const title = ep?.title || `${i18n.t('app.회차_id', {id: id})}`;
  try {
    let html = "";
    if (Number(state.sceneId) === id && state.scene) {
      html = state.scene.content_md || "";
    } else {
      const detail = await api(`/api/scenes/${id}`);
      html = detail.content_md || "";
    }
    const content = plainTextFromHtml(html);
    if (!content) {
      toast(i18n.t('app.이_회차에_본문이_없어요'));
      return;
    }
    const attached = { sceneId: id, title, content };
    if (readerManuscriptAttachTarget === "debate") {
      readerDebateAttached = attached;
      renderReaderDebateAttachChip();
      closeReaderScenePicker();
      toast(`${i18n.t('app.title_을_첨부했어요', {title: title})}`);
      return;
    }
    readerChatAttached = attached;
    renderReaderChatAttachChip();
    closeReaderScenePicker();
    toast(`${i18n.t('app.title_을_첨부했어요', {title: title})}`);
  } catch (error) {
    handleError(error);
  }
}

function clearReaderChatAttach() {
  readerChatAttached = null;
  renderReaderChatAttachChip();
}

async function sendReaderChatMessage(event) {
  if (event) event.preventDefault();
  if (readerChatSending) return;
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  const persona = readerChatPersona;
  if (!persona) return toast(i18n.t('app.대화할_독자를_먼저_골라_주세요'));
  const input = $("readerChatInput");
  const text = String(input?.value || "").trim();
  if (!text) return toast(i18n.t('app.메시지를_입력해_주세요'));
  readerChatSending = true;
  readerChatMessages.push({ role: "user", content: text });
  if (input) input.value = "";
  renderReaderChatMessages();
  const payload = {
    work_id: String(state.projectId),
    persona_id: persona.id,
    user_message: text,
  };
  const sessionId = state.readerSessions?.[persona.id];
  if (sessionId) payload.session_id = sessionId;
  if (readerChatAttached?.content) payload.episode_content = readerChatAttached.content;
  try {
    const result = await api("/api/reader-chat", {
      method: "POST",
      body: JSON.stringify(payload),
    });
    if (result?.session_id) rememberReaderChatSession(persona.id, result.session_id);
    readerChatMessages.push({
      role: "assistant",
      content: String(result?.reply || "").trim() || i18n.t('app.응답이_비어_있어요_2'),
    });
  } catch (error) {
    readerChatMessages.pop();
    if (input && !input.value) input.value = text;
    handleError(error);
  } finally {
    readerChatSending = false;
    renderReaderChatMessages();
  }
}

function closeReaderPersonaAllModal() {
  $("readerPersonaAllModal")?.classList.add("hidden");
}

async function openReaderPersonaAllModal() {
  const modal = $("readerPersonaAllModal");
  const grid = $("readerPersonaAllGrid");
  if (!modal || !grid) return;
  if (!state.projectId) {
    toast(i18n.t('app.작품을_먼저_선택해_주세요'));
    return;
  }
  const isDebate = readerListMode === "debate";
  grid.classList.toggle("is-debate", isDebate);
  const title = $("readerPersonaAllTitle");
  const hint = $("readerPersonaAllHint");
  const countEl = $("readerPersonaAllDebateCount");
  if (title) title.textContent = isDebate ? i18n.t('app.토론_패널_전체보기') : i18n.t('app.가상_독자_전체보기');
  if (hint) {
    hint.textContent = isDebate
      ? i18n.t('app.카드를_눌러_토론할_독자를_골라_주세요_소개')
      : i18n.t('app.카드를_눌러_대화할_독자를_고른_뒤_대화_시');
  }
  countEl?.classList.toggle("hidden", !isDebate);
  try {
    if (!readerPersonaCache) {
      readerPersonaCache = await api("/api/reader-personas");
    }
    if (isDebate) {
      grid.innerHTML = readerDebateSectionsHtml({ fullIdentity: true })
        || i18n.t('app.p_class_hint_가상_독자를_불러오');
      bindReaderAvatarErrors(grid);
      syncReaderDebateSelectionUi();
    } else {
      const people = flattenReaderPersonas(readerPersonaCache);
      if (!people.length) {
        grid.innerHTML = i18n.t('app.p_class_hint_가상_독자를_불러오');
      } else {
        grid.innerHTML = people.map((persona) => readerPersonaCardHtml(persona, { fullIdentity: true })).join("");
        bindReaderAvatarErrors(grid);
        syncReaderChatSelectionUi();
      }
    }
  } catch (error) {
    grid.innerHTML = i18n.t('app.p_class_hint_독자_목록을_불러오');
    handleError(error);
  }
  modal.classList.remove("hidden");
  requestAnimationFrame(() => {
    const closeBtn = modal.querySelector("[data-close-reader-persona-all].modal-close");
    try {
      closeBtn?.focus({ preventScroll: true });
    } catch (_) {
      closeBtn?.focus();
    }
  });
}

function syncReaderChatSelectionUi() {
  const selected = String(readerChatSelectedId || "").trim();
  document.querySelectorAll("#readerPersonaGrid [data-reader-persona], #readerPersonaAllGrid [data-reader-persona]").forEach((card) => {
    const on = card.getAttribute("data-reader-persona") === selected;
    card.classList.toggle("is-selected", on);
    card.setAttribute("aria-pressed", on ? "true" : "false");
  });
  const startBtn = $("readerChatStartButton");
  if (startBtn) startBtn.disabled = !selected;
  const hint = $("readerChatStartHint");
  if (hint) {
    hint.textContent = selected ? "" : i18n.t('app.독자를_한_명_골라주세요');
    hint.hidden = Boolean(selected);
  }
}

function selectReaderPersonaForChat(personaId) {
  const id = String(personaId || "").trim();
  if (!id) return;
  readerChatSelectedId = id;
  syncReaderChatSelectionUi();
}

function startReaderChatFromPicker() {
  if (!readerChatSelectedId) return toast(i18n.t('app.독자를_한_명_골라주세요_2'));
  closeReaderPersonaAllModal();
  openReaderChatWithPersona(readerChatSelectedId).catch(handleError);
}

function pickReaderPersonaFromCard(card) {
  const personaId = card?.getAttribute?.("data-reader-persona");
  if (!personaId) return;
  selectReaderPersonaForChat(personaId);
  closeReaderPersonaAllModal();
}

function setupReaderChatUi() {
  $("readerPersonaGrid")?.addEventListener("click", (event) => {
    const card = event.target.closest?.("[data-reader-persona]");
    if (!card) return;
    event.preventDefault();
    pickReaderPersonaFromCard(card);
  });
  $("readerPersonaAllGrid")?.addEventListener("click", (event) => {
    if (readerListMode === "debate") return;
    const card = event.target.closest?.("[data-reader-persona]");
    if (!card) return;
    event.preventDefault();
    pickReaderPersonaFromCard(card);
  });
  $("readerChatStartButton")?.addEventListener("click", (event) => {
    event.preventDefault();
    startReaderChatFromPicker();
  });
  $("readerPersonaAllButton")?.addEventListener("click", (event) => {
    event.preventDefault();
    openReaderPersonaAllModal().catch(handleError);
  });
  document.querySelectorAll("[data-close-reader-persona-all]").forEach((el) => {
    el.addEventListener("click", () => closeReaderPersonaAllModal());
  });
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    const modal = $("readerPersonaAllModal");
    if (!modal || modal.classList.contains("hidden")) return;
    event.preventDefault();
    closeReaderPersonaAllModal();
  });
  $("readerChatSwitchButton")?.addEventListener("click", () => openReaderPersonaPicker());
  $("readerChatForm")?.addEventListener("submit", (event) => {
    sendReaderChatMessage(event).catch(handleError);
  });
  $("readerChatInput")?.addEventListener("keydown", (event) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      sendReaderChatMessage().catch(handleError);
    }
  });
  $("readerChatAttachButton")?.addEventListener("click", () => {
    readerManuscriptAttachTarget = "chat";
    openReaderScenePicker();
  });
  $("readerChatAttachClear")?.addEventListener("click", () => clearReaderChatAttach());
  $("readerScenePickerList")?.addEventListener("click", (event) => {
    const item = event.target.closest?.("[data-reader-scene]");
    if (!item) return;
    event.preventDefault();
    attachReaderScene(item.getAttribute("data-reader-scene")).catch(handleError);
  });
  document.querySelectorAll("[data-close-reader-scene-picker]").forEach((el) => {
    el.addEventListener("click", () => closeReaderScenePicker());
  });
}

const READER_DEBATE_MAX_TOTAL = 5;
const READER_DEBATE_MAX_PER_CATEGORY = 5;
const READER_DEBATE_MIN_START = 3;
const READER_DEBATE_REVEAL_MS_MIN = 1000;
const READER_DEBATE_REVEAL_MS_MAX = 1800;
/** @type {"chat"|"debate"} */
let readerListMode = "chat";
/** @type {string[]} */
let readerDebateSelectedIds = [];
/** @type {string[]} */
let readerDebateRoomIds = [];
/** @type {Array<{kind:string,roundNumber?:number,content?:string,personaId?:string,personaName?:string,skipped?:boolean}>} */
let readerDebateEntries = [];
/** @type {{sceneId:number,title:string,content:string}|null} */
let readerDebateAttached = null;
/** @type {"chat"|"debate"} */
let readerManuscriptAttachTarget = "chat";
let readerDebateApiBusy = false;
let readerDebateRevealBusy = false;
let readerDebateRevealSkip = false;
let readerDebateRevealGen = 0;
/** @type {Array<object>} */
let readerDebateRevealRemaining = [];
/** @type {string|null} */
let readerDebateTypingPersonaId = null;

function readerDebatePersonaById(personaId) {
  return flattenReaderPersonas(readerPersonaCache).find((item) => item.id === personaId) || null;
}

function readerDebateCountInCategory(category) {
  return readerDebateSelectedIds.filter((id) => readerDebatePersonaById(id)?.category === category).length;
}

function readerDebateIsBlocked(selectedIds, getCategory, candidateId) {
  if (selectedIds.includes(candidateId)) return false;
  if (selectedIds.length >= READER_DEBATE_MAX_TOTAL) return true;
  const category = getCategory(candidateId);
  const catCount = selectedIds.filter((id) => getCategory(id) === category).length;
  return catCount >= READER_DEBATE_MAX_PER_CATEGORY;
}

function readerDebateCardHtml(persona, { fullIdentity = false } = {}) {
  const identity = fullIdentity
    ? String(persona.identity || "").replace(/\s+/g, " ").trim()
    : summarizeReaderIdentity(persona.identity);
  const checked = readerDebateSelectedIds.includes(persona.id) ? " checked" : "";
  return `<label class="reader-persona-card reader-debate-card" data-reader-debate-id="${escapeHtml(persona.id)}" data-category="${escapeHtml(persona.category || "")}">`
    + `<input type="checkbox" data-reader-debate-check="${escapeHtml(persona.id)}"${checked}>`
    + readerAvatarMarkup(persona.id, persona.name, "reader-persona-avatar")
    + `<span class="reader-persona-card-text">`
    + `<span class="reader-persona-card-name">${escapeHtml(persona.name || "")}</span>`
    + `<span class="reader-persona-card-identity">${escapeHtml(identity)}</span>`
    + `</span>`
    + `</label>`;
}

function readerDebateSectionsHtml({ fullIdentity = false } = {}) {
  const grouped = readerPersonaCache || {};
  return Object.keys(READER_PERSONA_CATEGORY_LABELS).map((category) => {
    const people = Array.isArray(grouped[category]) ? grouped[category] : [];
    if (!people.length) return "";
    const cards = people.map((persona) => readerDebateCardHtml(persona, { fullIdentity })).join("");
    return `<section class="reader-debate-section" data-debate-category="${escapeHtml(category)}">`
      + `<div class="reader-debate-section-head">`
      + `<strong>${escapeHtml(READER_PERSONA_CATEGORY_LABELS[category] || category)}</strong>`
      + `${i18n.t('app.p_class_reader_debate_s', {'escapeHtml(category)': escapeHtml(category)})}`
      + `</div>`
      + `<div class="reader-debate-section-cards">${cards}</div>`
      + `</section>`;
  }).filter(Boolean).join("");
}

async function loadAndRenderReaderDebateGrid() {
  const grid = $("readerDebateGrid");
  if (!grid) return;
  if (!state.projectId) {
    grid.innerHTML = i18n.t('app.p_class_hint_작품을_먼저_선택해');
    return;
  }
  try {
    if (!readerPersonaCache) {
      readerPersonaCache = await api("/api/reader-personas");
    }
    grid.innerHTML = readerDebateSectionsHtml() || i18n.t('app.p_class_hint_가상_독자를_불러오');
    bindReaderAvatarErrors(grid);
  } catch (error) {
    grid.innerHTML = i18n.t('app.p_class_hint_독자_목록을_불러오');
    handleError(error);
    return;
  }
  try {
    syncReaderDebateSelectionUi();
  } catch (error) {
    handleError(error);
  }
}

function syncReaderDebateSelectionUi() {
  const total = readerDebateSelectedIds.length;
  const countText = `${i18n.t('app.total_READER_DEBATE_MAX', {total: total, READER_DEBATE_MAX_TOTAL: READER_DEBATE_MAX_TOTAL})}`;
  const countEl = $("readerDebateCount");
  if (countEl) countEl.textContent = countText;
  const allCountEl = $("readerPersonaAllDebateCount");
  if (allCountEl) allCountEl.textContent = countText;
  const canStart = total >= READER_DEBATE_MIN_START && total <= READER_DEBATE_MAX_TOTAL;
  const startBtn = $("readerDebateStartButton");
  if (startBtn) startBtn.disabled = !canStart;
  const hint = $("readerDebateStartHint");
  if (hint) {
    hint.textContent = canStart ? "" : i18n.t('app.최소_3명을_골라주세요');
    hint.hidden = canStart;
  }
  const totalFull = total >= READER_DEBATE_MAX_TOTAL;
  const getCategory = (id) => readerDebatePersonaById(id)?.category || "";
  document.querySelectorAll("[data-debate-limit]").forEach((el) => {
    const category = el.getAttribute("data-debate-limit") || "";
    const catFull = readerDebateCountInCategory(category) >= READER_DEBATE_MAX_PER_CATEGORY;
    el.classList.toggle("hidden", !catFull);
  });
  document.querySelectorAll("[data-reader-debate-id]").forEach((card) => {
    const id = card.getAttribute("data-reader-debate-id") || "";
    const selected = readerDebateSelectedIds.includes(id);
    const blocked = readerDebateIsBlocked(readerDebateSelectedIds, getCategory, id);
    card.classList.toggle("is-disabled", blocked);
    const input = card.querySelector("input[data-reader-debate-check]");
    if (input instanceof HTMLInputElement) {
      input.checked = selected;
      input.disabled = blocked;
    }
  });
}

function toggleReaderDebatePersona(personaId, checked) {
  const id = String(personaId || "").trim();
  const persona = readerDebatePersonaById(id);
  if (!id || !persona) return;
  const already = readerDebateSelectedIds.includes(id);
  if (checked) {
    if (already) return;
    if (readerDebateSelectedIds.length >= READER_DEBATE_MAX_TOTAL) return;
    if (readerDebateCountInCategory(persona.category) >= READER_DEBATE_MAX_PER_CATEGORY) return;
    readerDebateSelectedIds.push(id);
  } else if (already) {
    readerDebateSelectedIds = readerDebateSelectedIds.filter((item) => item !== id);
  }
  syncReaderDebateSelectionUi();
}

function setReaderListMode(mode) {
  if (mode === "debate" && !assertClusterFeature("reader_debate")) return;
  const next = mode === "debate" ? "debate" : "chat";
  readerListMode = next;
  const isDebate = next === "debate";
  document.querySelectorAll("[data-reader-list-mode]").forEach((btn) => {
    const on = btn.getAttribute("data-reader-list-mode") === next;
    btn.classList.toggle("is-active", on);
    btn.setAttribute("aria-selected", on ? "true" : "false");
  });
  $("readerPersonaChatHint")?.classList.toggle("hidden", isDebate);
  $("readerPersonaChatPane")?.classList.toggle("hidden", isDebate);
  $("readerPersonaGrid")?.classList.toggle("hidden", isDebate);
  $("readerDebatePane")?.classList.toggle("hidden", !isDebate);
  if (isDebate) void loadAndRenderReaderDebateGrid();
  else syncReaderChatSelectionUi();
}

function openReaderDebateRoom(personaIds) {
  return openReaderDebateRoomAsync(personaIds);
}

async function openReaderDebateRoomAsync(personaIds) {
  skipReaderDebateReveal();
  const ids = (Array.isArray(personaIds) ? personaIds : [])
    .map((id) => String(id || "").trim())
    .filter(Boolean);
  if (ids.length < READER_DEBATE_MIN_START) return;
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  if (!readerPersonaCache) {
    try {
      readerPersonaCache = await api("/api/reader-personas");
    } catch (error) {
      handleError(error);
      return;
    }
  }
  console.info("[reader-debate] start", ids);
  readerDebateRoomIds = ids.slice();
  readerDebateEntries = [];
  readerDebateAttached = null;
  readerDebateTypingPersonaId = null;
  readerDebateApiBusy = false;
  readerManuscriptAttachTarget = "debate";
  $("readerPersonaPicker")?.classList.add("hidden");
  const chatRoom = $("readerChatRoom");
  chatRoom?.classList.add("hidden");
  if (chatRoom) chatRoom.hidden = true;
  $("readerDebateRoom")?.classList.remove("hidden");
  renderReaderDebatePeers();
  renderReaderDebateAttachChip();
  renderReaderDebateMessages();
  setReaderDebateComposerEnabled(true);
  await loadReaderDebateHistory();
  requestAnimationFrame(() => $("readerDebateInput")?.focus());
}

function setReaderDebateComposerEnabled(enabled) {
  const on = Boolean(enabled);
  const input = $("readerDebateInput");
  const send = $("readerDebateSendButton");
  const attach = $("readerDebateAttachButton");
  if (input) input.disabled = !on;
  if (send) send.disabled = !on;
  if (attach) attach.disabled = !on;
}

function renderReaderDebateAttachChip() {
  const chip = $("readerDebateAttachChip");
  const label = $("readerDebateAttachLabel");
  if (!chip) return;
  const attached = readerDebateAttached;
  const on = Boolean(attached);
  chip.classList.toggle("hidden", !on);
  chip.hidden = !on;
  if (label) {
    label.textContent = attached
      ? `${i18n.t('app.첨부됨_attached_title', {'attached.title': attached.title})}`
      : "";
  }
}

function clearReaderDebateAttach() {
  readerDebateAttached = null;
  renderReaderDebateAttachChip();
}

function renderReaderDebatePeers() {
  const host = $("readerDebatePeers");
  if (!host) return;
  host.innerHTML = readerDebateRoomIds.map((id) => {
    const persona = readerDebatePersonaById(id);
    const name = persona?.name || id;
    return `<div class="reader-debate-peer" title="${escapeHtml(name)}">`
      + readerAvatarMarkup(id, name, "reader-debate-peer-avatar reader-chat-msg-avatar")
      + `<span class="reader-debate-peer-name">${escapeHtml(name)}</span>`
      + `</div>`;
  }).join("");
  bindReaderAvatarErrors(host);
}

function readerDebateLastRoundNumber() {
  let n = 0;
  for (const entry of readerDebateEntries) {
    if (entry.kind === "round" && Number(entry.roundNumber) > n) {
      n = Number(entry.roundNumber);
    }
  }
  return n;
}

function appendReaderDebatePersonaReply(reply) {
  const personaId = String(reply?.persona_id || "").trim();
  const persona = readerDebatePersonaById(personaId);
  const name = String(reply?.persona_name || persona?.name || "").trim() || i18n.t('app.가상_독자');
  const skipped = Boolean(reply?.skipped) || reply?.ok === false;
  const content = skipped
    ? i18n.t('app.지금은_답하지_못했어요')
    : String(reply?.message || "").trim();
  if (!content && !skipped) return;
  readerDebateEntries.push({
    kind: "persona",
    personaId,
    personaName: name,
    content: content || i18n.t('app.지금은_답하지_못했어요'),
    skipped,
  });
}

function renderReaderDebateMessages() {
  const box = $("readerDebateMessages");
  if (!box) return;
  if (!readerDebateEntries.length && !readerDebateTypingPersonaId) {
    box.innerHTML = `<p class="reader-chat-empty">${escapeHtml(i18n.t('app.토론을_시작해_보세요_질문을_보내면_고른'))}</p>`;
    return;
  }
  const rows = [];
  for (const entry of readerDebateEntries) {
    if (entry.kind === "round") {
      rows.push(
        `<div class="reader-debate-round-sep" role="separator">`
        + `<span>${escapeHtml(`${i18n.t('app.라운드')} ${Number(entry.roundNumber) || 1}`)}</span>`
        + `</div>`,
      );
      continue;
    }
    if (entry.kind === "user") {
      const body = escapeHtml(entry.content || "").replace(/\r\n|\r|\n/g, "<br>");
      rows.push(
        `<div class="reader-chat-msg is-user">`
        + `<div class="reader-chat-msg-body"><div class="reader-chat-bubble">${body}</div></div>`
        + `</div>`,
      );
      continue;
    }
    if (entry.kind === "persona") {
      const name = entry.personaName || i18n.t('app.가상_독자');
      const body = escapeHtml(entry.content || "").replace(/\r\n|\r|\n/g, "<br>");
      const skippedCls = entry.skipped ? " is-skipped" : "";
      rows.push(
        `<div class="reader-chat-msg is-assistant${skippedCls}">`
        + readerAvatarMarkup(entry.personaId, name, "reader-chat-msg-avatar")
        + `<div class="reader-chat-msg-body">`
        + `<span class="reader-chat-msg-name">${escapeHtml(name)}</span>`
        + `<div class="reader-chat-bubble">${body}</div>`
        + `</div></div>`,
      );
    }
  }
  if (readerDebateTypingPersonaId) {
    const persona = readerDebatePersonaById(readerDebateTypingPersonaId);
    const name = persona?.name || i18n.t('app.가상_독자');
    rows.push(
      `<div class="reader-chat-msg is-assistant is-pending">`
      + readerAvatarMarkup(readerDebateTypingPersonaId, name, "reader-chat-msg-avatar")
      + `<div class="reader-chat-msg-body">`
      + `<span class="reader-chat-msg-name">${escapeHtml(name)}</span>`
      + `${i18n.t('app.div_class_reader_chat_b', {'escapeHtml(name)': escapeHtml(name)})}`
      + `</div></div>`,
    );
  }
  box.innerHTML = rows.join("");
  bindReaderAvatarErrors(box);
  box.scrollTop = box.scrollHeight;
}

function readerDebateDelay(ms, aborted) {
  return new Promise((resolve) => {
    const started = Date.now();
    const tick = () => {
      if (aborted() || Date.now() - started >= ms) {
        resolve();
        return;
      }
      setTimeout(tick, 40);
    };
    setTimeout(tick, 40);
  });
}

function skipReaderDebateReveal() {
  if (!readerDebateRevealBusy && !readerDebateRevealRemaining.length) return;
  readerDebateRevealSkip = true;
  readerDebateRevealGen += 1;
  readerDebateTypingPersonaId = null;
  for (const reply of readerDebateRevealRemaining) {
    appendReaderDebatePersonaReply(reply);
  }
  readerDebateRevealRemaining = [];
  readerDebateRevealBusy = false;
  renderReaderDebateMessages();
  if (!readerDebateApiBusy) setReaderDebateComposerEnabled(true);
}

async function playReaderDebateReplies(replies) {
  const list = Array.isArray(replies) ? replies.slice() : [];
  if (!list.length) return;
  readerDebateRevealBusy = true;
  readerDebateRevealSkip = false;
  const gen = ++readerDebateRevealGen;
  readerDebateRevealRemaining = list.slice();
  setReaderDebateComposerEnabled(true);
  while (readerDebateRevealRemaining.length) {
    if (readerDebateRevealSkip || gen !== readerDebateRevealGen) break;
    const reply = readerDebateRevealRemaining[0];
    const personaId = String(reply?.persona_id || "").trim();
    readerDebateTypingPersonaId = personaId || null;
    renderReaderDebateMessages();
    const waitMs = READER_DEBATE_REVEAL_MS_MIN
      + Math.floor(Math.random() * (READER_DEBATE_REVEAL_MS_MAX - READER_DEBATE_REVEAL_MS_MIN + 1));
    await readerDebateDelay(
      waitMs,
      () => readerDebateRevealSkip || gen !== readerDebateRevealGen,
    );
    if (readerDebateRevealSkip || gen !== readerDebateRevealGen) break;
    readerDebateRevealRemaining.shift();
    readerDebateTypingPersonaId = null;
    appendReaderDebatePersonaReply(reply);
    renderReaderDebateMessages();
  }
  if (readerDebateRevealRemaining.length) {
    readerDebateTypingPersonaId = null;
    for (const reply of readerDebateRevealRemaining) {
      appendReaderDebatePersonaReply(reply);
    }
    readerDebateRevealRemaining = [];
  }
  readerDebateTypingPersonaId = null;
  readerDebateRevealBusy = false;
  renderReaderDebateMessages();
  if (!readerDebateApiBusy) setReaderDebateComposerEnabled(true);
}

function applyReaderDebateHistoryPayload(history) {
  readerDebateEntries = [];
  const rounds = Array.isArray(history?.rounds) ? history.rounds : [];
  const order = Array.isArray(history?.persona_order) ? history.persona_order : [];
  if (order.length) {
    const cleaned = order.map((id) => String(id || "").trim()).filter(Boolean);
    if (cleaned.length) readerDebateRoomIds = cleaned;
  }
  for (const round of rounds) {
    const rn = Number(round?.round_number) || 0;
    if (rn > 0) {
      readerDebateEntries.push({ kind: "round", roundNumber: rn });
    }
    const messages = Array.isArray(round?.messages) ? round.messages : [];
    for (const msg of messages) {
      const speaker = String(msg?.speaker_type || "").trim().toLowerCase();
      const text = String(msg?.message || "").trim();
      if (!text) continue;
      if (speaker === "user") {
        readerDebateEntries.push({ kind: "user", content: text });
        continue;
      }
      if (speaker === "persona") {
        const personaId = String(msg?.persona_id || "").trim();
        const persona = readerDebatePersonaById(personaId);
        readerDebateEntries.push({
          kind: "persona",
          personaId,
          personaName: String(msg?.persona_name || persona?.name || "").trim() || i18n.t('app.가상_독자'),
          content: text,
        });
      }
    }
  }
}

async function loadReaderDebateHistory() {
  if (!state.projectId || !readerDebateRoomIds.length) {
    readerDebateEntries = [];
    renderReaderDebateMessages();
    return;
  }
  try {
    const idsCsv = readerDebateRoomIds.map(encodeURIComponent).join(",");
    const history = await api(
      `/api/reader-debate/history?work_id=${encodeURIComponent(state.projectId)}&persona_ids=${idsCsv}`,
    );
    applyReaderDebateHistoryPayload(history || {});
  } catch (error) {
    handleError(error);
  }
  renderReaderDebatePeers();
  renderReaderDebateMessages();
}

function closeReaderDebateRoom() {
  skipReaderDebateReveal();
  readerDebateApiBusy = false;
  readerDebateTypingPersonaId = null;
  readerDebateAttached = null;
  readerManuscriptAttachTarget = "chat";
  $("readerDebateRoom")?.classList.add("hidden");
  $("readerPersonaPicker")?.classList.remove("hidden");
  setReaderListMode("debate");
}

function startReaderDebate() {
  if (!assertClusterFeature("reader_debate")) return;
  if (readerDebateSelectedIds.length < READER_DEBATE_MIN_START) return;
  if (readerDebateSelectedIds.length > READER_DEBATE_MAX_TOTAL) return;
  closeReaderPersonaAllModal();
  openReaderDebateRoomAsync(readerDebateSelectedIds).catch(handleError);
}

async function sendReaderDebateMessage(event) {
  if (event) event.preventDefault();
  if (readerDebateRevealBusy) {
    skipReaderDebateReveal();
  }
  if (readerDebateApiBusy) return;
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  if (readerDebateRoomIds.length < READER_DEBATE_MIN_START) {
    return toast(i18n.t('app.최소_3명을_골라주세요'));
  }
  const input = $("readerDebateInput");
  const text = String(input?.value || "").trim();
  if (!text) return toast(i18n.t('app.메시지를_입력해_주세요'));

  const roundNumber = readerDebateLastRoundNumber() + 1;
  readerDebateApiBusy = true;
  setReaderDebateComposerEnabled(false);
  readerDebateEntries.push({ kind: "round", roundNumber });
  readerDebateEntries.push({ kind: "user", content: text });
  if (input) input.value = "";
  renderReaderDebateMessages();

  const payload = {
    work_id: String(state.projectId),
    persona_ids: readerDebateRoomIds.slice(),
    user_message: text,
  };
  if (readerDebateAttached?.content) {
    payload.episode_content = readerDebateAttached.content;
  }
  try {
    const result = await api("/api/reader-debate", {
      method: "POST",
      body: JSON.stringify(payload),
    });
    const apiRound = Number(result?.round_number) || roundNumber;
    const lastRound = [...readerDebateEntries].reverse().find((e) => e.kind === "round");
    if (lastRound) lastRound.roundNumber = apiRound;
    if (Array.isArray(result?.persona_order) && result.persona_order.length) {
      const order = result.persona_order.map((id) => String(id || "").trim()).filter(Boolean);
      if (order.length) {
        readerDebateRoomIds = order;
        renderReaderDebatePeers();
      }
    }
    readerDebateApiBusy = false;
    await playReaderDebateReplies(result?.replies || []);
  } catch (error) {
    while (readerDebateEntries.length) {
      const last = readerDebateEntries[readerDebateEntries.length - 1];
      if (last.kind === "user" || last.kind === "round") {
        readerDebateEntries.pop();
        if (last.kind === "user") break;
        continue;
      }
      break;
    }
    if (input && !input.value) input.value = text;
    readerDebateApiBusy = false;
    setReaderDebateComposerEnabled(true);
    renderReaderDebateMessages();
    handleError(error);
  }
}

function setupReaderDebateUi() {
  document.querySelectorAll("[data-reader-list-mode]").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      event.preventDefault();
      setReaderListMode(btn.getAttribute("data-reader-list-mode"));
    });
  });
  $("readerDebateGrid")?.addEventListener("change", (event) => {
    const input = event.target.closest?.("input[data-reader-debate-check]");
    if (!(input instanceof HTMLInputElement)) return;
    toggleReaderDebatePersona(input.getAttribute("data-reader-debate-check"), input.checked);
  });
  $("readerPersonaAllGrid")?.addEventListener("change", (event) => {
    const input = event.target.closest?.("input[data-reader-debate-check]");
    if (!(input instanceof HTMLInputElement)) return;
    toggleReaderDebatePersona(input.getAttribute("data-reader-debate-check"), input.checked);
  });
  $("readerDebateStartButton")?.addEventListener("click", (event) => {
    event.preventDefault();
    startReaderDebate();
  });
  $("readerDebateRoomBack")?.addEventListener("click", () => closeReaderDebateRoom());
  $("readerDebateForm")?.addEventListener("submit", (event) => {
    sendReaderDebateMessage(event).catch(handleError);
  });
  $("readerDebateInput")?.addEventListener("keydown", (event) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      sendReaderDebateMessage().catch(handleError);
    }
  });
  $("readerDebateAttachButton")?.addEventListener("click", () => {
    readerManuscriptAttachTarget = "debate";
    openReaderScenePicker();
  });
  $("readerDebateAttachClear")?.addEventListener("click", () => clearReaderDebateAttach());
}

function setupToryChatHubUi() {
  $("toryChatHub")?.addEventListener("click", (event) => {
    const pick = event.target.closest?.("[data-chat-hub-pick]");
    if (!pick) return;
    event.preventDefault();
    const kind = pick.getAttribute("data-chat-hub-pick");
    if (kind === "tory") {
      setToryChatHub("tory");
      requestAnimationFrame(() => $("toryChatInput")?.focus());
      return;
    }
    if (kind === "characters") {
      openToryChatCharacterPicker().catch(handleError);
      return;
    }
    if (kind === "reader") {
      openReaderPersonaPicker();
    }
  });
  $("toryChatCharacterPickerBack")?.addEventListener("click", () => setToryChatHub("home"));
  $("toryChatReaderBack")?.addEventListener("click", () => setToryChatHub("home"));
  $("toryChatRoomBack")?.addEventListener("click", () => {
    if (toryChatHub === "character-room") setToryChatHub("characters");
    else setToryChatHub("home");
  });
  $("toryChatCharacterList")?.addEventListener("change", (event) => {
    const input = event.target.closest?.("input[data-tory-chat-character]");
    if (!input) return;
    toggleToryChatCharacterId(input.getAttribute("data-tory-chat-character"), input.checked);
    renderToryChatCharacterPicker();
    if (isToryChatCharacterAllOpen()) renderToryChatCharacterAllGrid();
  });
  $("toryChatCharacterStart")?.addEventListener("click", () => startToryChatWithSelectedCharacters());
  $("toryChatCharacterAllButton")?.addEventListener("click", (event) => {
    event.preventDefault();
    openToryChatCharacterAllModal();
  });
  $("toryChatCharacterAllGrid")?.addEventListener("change", (event) => {
    const chatInput = event.target.closest?.("input[data-tory-chat-all-check]");
    if (chatInput instanceof HTMLInputElement) {
      toggleToryChatCharacterId(chatInput.getAttribute("data-tory-chat-all-check"), chatInput.checked);
      renderToryChatCharacterPicker();
      renderToryChatCharacterAllGrid();
      return;
    }
    const simInput = event.target.closest?.("input[data-char-debate-all-check]");
    if (simInput instanceof HTMLInputElement) {
      toggleCharDebateCharacter(simInput.getAttribute("data-char-debate-all-check"), simInput.checked);
    }
  });
  document.querySelectorAll("[data-close-tory-chat-character-all]").forEach((el) => {
    el.addEventListener("click", () => closeToryChatCharacterAllModal());
  });
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    if (!isToryChatCharacterAllOpen()) return;
    event.preventDefault();
    closeToryChatCharacterAllModal();
  });
  document.querySelectorAll("[data-char-list-mode]").forEach((btn) => {
    btn.addEventListener("click", () => {
      setCharListMode(btn.getAttribute("data-char-list-mode"));
    });
  });
}

function setupToryChat() {
  setupToryPersonaSelect();
  setupToryChatPopupChrome();
  setupToryChatHistoryUi();
  setupToryChatHubUi();
  setupReaderChatUi();
  setupReaderDebateUi();

  $("aiTabTools")?.addEventListener("click", () => {
    hideToryPersonaMenu();
    setAiPanelTab("tools");
  });

  $("aiTabChat")?.addEventListener("click", () => {
    hideToryPersonaMenu();
    if (toryChatPopupOpen) {
      showToryChatPopupInPanelSlot();
      requestAnimationFrame(() => $("toryChatInput")?.focus());
      return;
    }
    setAiPanelTab("chat", { chatHub: "home" });
  });
  setupAiHelperPaneTabs();

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      if (!$("toryChatHistoryModal")?.classList.contains("hidden")) return;
      if (toryChatPopupOpen && !$("toryChatPopup")?.classList.contains("hidden")) {
        const otherModal = document.querySelector(".modal:not(.hidden)");
        if (!otherModal) closeToryChatPopup({ restorePanelTab: true });
      }
    }
  });

  $("toryChatForm")?.addEventListener("submit", (event) => {
    sendToryChatMessage(event).catch(handleError);
  });
  $("toryChatClearButton")?.addEventListener("click", clearToryChatHistory);
  $("toryChatSuccessSummonButton")?.addEventListener("click", () => {
    if (!getLinkedSuccessProfileId()) {
      toast(i18n.t('app.흥행_프로파일이_연결된_작품에서만_쓸_수_있'));
      updateToryChatSuccessUi();
      return;
    }
    ensureLinkedSuccessProfile()
      .then((profile) => {
        if (!profile) {
          toast(i18n.t('app.흥행_프로파일을_불러오지_못했어요'));
          return;
        }
        setToryChatMode("successAnalysis");
        setAiPanelTab("chat", { chatHub: "tory" });
        requestAnimationFrame(() => $("toryChatInput")?.focus());
      })
      .catch(handleError);
  });
  $("toryChatSuccessExitButton")?.addEventListener("click", () => {
    setToryChatMode("general");
  });
  updateToryChatSuccessUi();
  // Event delegation: buttons may move with chat into popup
  document.addEventListener("click", (event) => {
    const copyBtn = event.target.closest?.("[data-tory-chat-copy]");
    if (copyBtn) {
      event.preventDefault();
      event.stopPropagation();
      copyToryChatCharacterReply(copyBtn).catch(handleError);
      return;
    }
    const hlBtn = event.target.closest?.("#toryChatHighlightButton");
    if (hlBtn) {
      event.preventDefault();
      captureToryChatHighlightSelection();
      applyToryChatHighlight();
      return;
    }
    const collectBtn = event.target.closest?.("#toryChatCollectButton");
    if (collectBtn) {
      event.preventDefault();
      collectFromToryChat();
      return;
    }
    const openBtn = event.target.closest?.("#toryChatPopupOpenButton");
    if (openBtn) {
      event.preventDefault();
      openToryChatPopup();
      return;
    }
    const histBtn = event.target.closest?.("#toryChatHistoryButton");
    if (histBtn) {
      event.preventDefault();
      openToryChatHistoryModal();
    }
  });
  document.addEventListener("contextmenu", (event) => {
    const hlBtn = event.target.closest?.("#toryChatHighlightButton");
    if (!hlBtn) return;
    event.preventDefault();
    event.stopPropagation();
    captureToryChatHighlightSelection();
    if (typeof showFormatColorPalette === "function") {
      showFormatColorPalette("highlight", hlBtn, null, { target: "tory-chat" });
    } else {
      applyToryChatHighlight("#f1c40f");
    }
  });
  $("toryChatInput")?.addEventListener("input", () => {
    toryChatComposerDraft = String($("toryChatInput")?.value || "");
  });
  $("toryChatInput")?.addEventListener("keydown", (event) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      sendToryChatMessage().catch(handleError);
    }
  });
  setAiPanelTab("tools");
  renderToryChatMessages();
  syncToryChatHighlightBar();
}

/* —— 토리 알림 센터 (떡밥 + 수동) —— */
const TORY_NOTIFY_COLLAPSE_KEY = "supertory.toryNotifyCollapsed";
let toryNotifyFilter = "all"; // all | on | bait | custom

function toryNotifyStorageKey(projectId = state.projectId) {
  return `${TORY_NOTIFY_STORAGE_PREFIX}${projectId || "0"}`;
}

function loadCustomToryNotifs() {
  if (!state.projectId) return [];
  try {
    const raw = localStorage.getItem(toryNotifyStorageKey());
    const arr = raw ? JSON.parse(raw) : [];
    if (!Array.isArray(arr)) return [];
    return arr
      .filter((n) => n && n.id)
      .map((n) => ({
        id: String(n.id),
        type: "custom",
        title: String(n.title || "").trim() || i18n.t('app.알림'),
        message: String(n.message || "").trim(),
        sceneId: n.sceneId != null && n.sceneId !== "" ? Number(n.sceneId) || null : null,
        note: String(n.note || "").trim(),
        enabled: n.enabled !== false && n.enabled !== 0 && n.enabled !== "0" && n.enabled !== "false",
        createdAt: n.createdAt || "",
      }));
  } catch (_) {
    return [];
  }
}

function saveCustomToryNotifs(list) {
  if (!state.projectId) return;
  try {
    localStorage.setItem(toryNotifyStorageKey(), JSON.stringify(list || []));
  } catch (_) {
    /* ignore */
  }
  renderToryNotifyList();
}

/** Unified list: bait recovery notifies + manual custom notifies. */
function getUnifiedToryNotifs() {
  const items = [];
  for (const bait of loadBaits()) {
    // Show baits that have a recovery scene OR explicit recover note (planning)
    const hasRecoverScene = Number(bait.recoverSceneId) > 0;
    const hasRecoverNote = Boolean(String(bait.recoverAt || "").trim());
    if (!hasRecoverScene && !hasRecoverNote && bait.notifyOnRecover === false) continue;
    if (!hasRecoverScene && !hasRecoverNote) continue;
    const title = (bait.summary || bait.quote || i18n.t('app.떡밥_회수')).replace(/\s+/g, " ").trim().slice(0, 80);
    const sceneTitle = hasRecoverScene
      ? (sceneTitleById(bait.recoverSceneId) || `${i18n.t('app.씬_bait_recoverSceneId', {'bait.recoverSceneId': bait.recoverSceneId})}`)
      : "";
    items.push({
      id: `bait:${bait.id}`,
      type: "bait",
      baitId: bait.id,
      title: title || i18n.t('app.떡밥_회수'),
      message: (bait.recoverContent || bait.quote || "").replace(/\s+/g, " ").trim(),
      sceneId: hasRecoverScene ? Number(bait.recoverSceneId) : null,
      sceneLabel: sceneTitle || bait.recoverAt || i18n.t('app.회수_회차_미정'),
      note: bait.recoverAt || "",
      enabled: hasRecoverScene ? bait.notifyOnRecover !== false : false,
      createdAt: bait.createdAt || "",
    });
  }
  for (const n of loadCustomToryNotifs()) {
    items.push({
      ...n,
      type: "custom",
      sceneLabel: n.sceneId
        ? (sceneTitleById(n.sceneId) || `${i18n.t('app.씬_n_sceneId', {'n.sceneId': n.sceneId})}`)
        : (n.note || i18n.t('app.회차_미정')),
    });
  }
  items.sort((a, b) => {
    // Due for current scene first, then enabled, then newest
    const aDue = state.sceneId && Number(a.sceneId) === Number(state.sceneId) ? 1 : 0;
    const bDue = state.sceneId && Number(b.sceneId) === Number(state.sceneId) ? 1 : 0;
    if (aDue !== bDue) return bDue - aDue;
    if (Boolean(a.enabled) !== Boolean(b.enabled)) return a.enabled ? -1 : 1;
    return String(b.createdAt || "").localeCompare(String(a.createdAt || ""));
  });
  return items;
}

function filterToryNotifs(items) {
  const filter = toryNotifyFilter || "all";
  if (filter === "on") return items.filter((i) => i.enabled);
  if (filter === "bait") return items.filter((i) => i.type === "bait");
  if (filter === "custom") return items.filter((i) => i.type === "custom");
  return items;
}

function setToryNotifyFilter(filter) {
  toryNotifyFilter = ["all", "on", "bait", "custom"].includes(filter) ? filter : "all";
  document.querySelectorAll("[data-tory-notif-filter]").forEach((btn) => {
    const active = btn.dataset.toryNotifFilter === toryNotifyFilter;
    btn.classList.toggle("is-active", active);
    btn.setAttribute("aria-selected", active ? "true" : "false");
  });
  renderToryNotifyList();
}

function loadToryNotifyCollapsed() {
  try {
    const raw = localStorage.getItem(TORY_NOTIFY_COLLAPSE_KEY);
    // Default: open. Only collapse when user explicitly saved "1".
    if (raw == null) return false;
    return raw === "1";
  } catch (_) {
    return false;
  }
}

function applyToryNotifyCollapsed(collapsed) {
  const box = $("toryNotifyBox");
  const btn = $("toryNotifyCollapseButton");
  box?.classList.toggle("is-collapsed", Boolean(collapsed));
  if (btn) {
    btn.setAttribute("aria-expanded", collapsed ? "false" : "true");
    btn.title = collapsed ? i18n.t('app.알림_패널_펼치기') : i18n.t('app.알림_패널_접기');
  }
  try {
    localStorage.setItem(TORY_NOTIFY_COLLAPSE_KEY, collapsed ? "1" : "0");
  } catch (_) {
    /* ignore */
  }
}

function updateToryNotifyCountUi(onCount, total) {
  const countEl = $("toryNotifyCount");
  if (!countEl) return;
  countEl.innerHTML = `
    <span class="tory-notify-stat is-on" title="${i18n.t('app.켜진_알림')}">${onCount}</span>
    <span class="tory-notify-stat-sep">/</span>
    <span class="tory-notify-stat is-total" title="${i18n.t('app.전체_알림')}">${total}</span>`;
}

function renderToryNotifyDueBanner(items) {
  const banner = $("toryNotifyDueBanner");
  if (!banner) return;
  if (!state.projectId || !state.sceneId) {
    banner.classList.add("hidden");
    banner.innerHTML = "";
    return;
  }
  const due = items.filter(
    (i) => i.enabled && Number(i.sceneId) === Number(state.sceneId),
  );
  if (!due.length) {
    banner.classList.add("hidden");
    banner.innerHTML = "";
    return;
  }
  const sceneName = escapeHtml(
    state.scene?.title || $("sceneTitle")?.value || sceneTitleById(state.sceneId) || i18n.t('app.이_회차'),
  );
  banner.innerHTML = `${i18n.t('app.strong_지금_회차_알림_due_len', {'due.length': due.length, sceneName: sceneName})}`;
  banner.classList.remove("hidden");
}

function renderToryNotifyCard(item) {
  const isBait = item.type === "bait";
  const isDue = Boolean(
    item.enabled && state.sceneId && Number(item.sceneId) === Number(state.sceneId),
  );
  const typeLabel = isBait ? i18n.t('app.떡밥_회수') : i18n.t('app.수동_알림');
  const typeClass = isBait ? "is-bait" : "is-custom";
  const title = escapeHtml(item.title || i18n.t('app.알림'));
  const msg = escapeHtml((item.message || "").replace(/\s+/g, " ").trim().slice(0, 140));
  const sceneLabel = escapeHtml(item.sceneLabel || i18n.t('app.회차_미정'));
  const sceneChipClass = isDue ? "is-due" : (item.sceneId ? "" : "is-muted");
  const sceneChip = item.sceneId
    ? `${i18n.t('app.span_class_tory_notify', {sceneChipClass: sceneChipClass, 'uiIcon("book", 15)': uiIcon("book", 15), sceneLabel: sceneLabel})}`
    : `${i18n.t('app.span_class_tory_notify_2', {'uiIcon("book", 15)': uiIcon("book", 15), sceneLabel: sceneLabel})}`;
  const statusChip = item.enabled
    ? (isDue
      ? i18n.t('app.span_class_tory_notify_3')
      : i18n.t('app.span_class_tory_notify_4'))
    : i18n.t('app.span_class_tory_notify_5');
  const switchDisabled = isBait && !item.sceneId;
  const switchHtml = `
    <label class="tory-switch" title="${item.enabled ? i18n.t('app.알림_끄기') : i18n.t('app.알림_켜기')}">
      <input type="checkbox" data-tory-notif-toggle="${escapeHtml(item.id)}"
        ${item.enabled ? "checked" : ""} ${switchDisabled ? "disabled" : ""}
        aria-label="${item.enabled ? i18n.t('app.알림_끄기') : i18n.t('app.알림_켜기')}">
      <span class="tory-switch-track" aria-hidden="true"></span>
    </label>`;
  const foot = [];
  if (item.sceneId) {
    foot.push(`${i18n.t('app.button_type_button_clas_2', {'Number(item.sceneId)': Number(item.sceneId)})}`);
  }
  if (isBait) {
    foot.push(`${i18n.t('app.button_type_button_clas_3', {'escapeHtml(item.baitId || "")': escapeHtml(item.baitId || "")})}`);
  } else {
    foot.push(`${i18n.t('app.button_type_button_clas_4', {'escapeHtml(item.id)': escapeHtml(item.id)})}`);
    foot.push(`${i18n.t('app.button_type_button_clas_5', {'escapeHtml(item.id)': escapeHtml(item.id)})}`);
  }
  return `
    <article class="tory-notify-card ${item.enabled ? "is-on" : "is-off"}${isDue ? " is-due" : ""}"
      data-tory-notif-id="${escapeHtml(item.id)}" data-type="${escapeHtml(item.type)}">
      <div class="tory-notify-card-top">
        <span class="tory-notify-type ${typeClass}">${typeLabel}</span>
        ${switchHtml}
      </div>
      <div class="tory-notify-card-title">${title}</div>
      <div class="tory-notify-card-meta">${sceneChip}${statusChip}</div>
      ${msg ? `<p class="tory-notify-card-msg">${msg}</p>` : ""}
      <div class="tory-notify-card-foot">${foot.join("")}</div>
    </article>`;
}

function renderToryNotifyList() {
  const list = $("toryNotifyList");
  if (!list) return;
  if (!state.projectId) {
    updateToryNotifyCountUi(0, 0);
    renderToryNotifyDueBanner([]);
    list.innerHTML = `
      <div class="tory-notify-empty">
        <span class="tory-notify-empty-icon emoji-icon" aria-hidden="true">🔔</span>
        <strong>${i18n.t('app.작품을_먼저_선택해_주세요_2')}</strong>
        <p data-i18n="app.선택한_작품의_떡밥_수동_알림이_여기에_모입니다">${i18n.t('app.선택한_작품의_떡밥_수동_알림이_여기에_모입니다')}</p>
      </div>`;
    return;
  }

  const all = getUnifiedToryNotifs();
  const onCount = all.filter((i) => i.enabled).length;
  updateToryNotifyCountUi(onCount, all.length);
  renderToryNotifyDueBanner(all);

  const items = filterToryNotifs(all);
  if (!all.length) {
    list.innerHTML = `
      <div class="tory-notify-empty">
        <span class="tory-notify-empty-icon emoji-icon" aria-hidden="true">🪄</span>
        <strong data-i18n="app.아직_알림이_없어요">${i18n.t('app.아직_알림이_없어요')}</strong>
        <p data-i18n-html="app.떡밥_회수_알림을_켜_두거나_알림_만들기로_수동">${i18n.t('app.떡밥_회수_알림을_켜_두거나_알림_만들기로_수동')}</p>
      </div>`;
    return;
  }
  if (!items.length) {
    list.innerHTML = `
      <div class="tory-notify-empty">
        <span class="tory-notify-empty-icon emoji-icon" aria-hidden="true">🔎</span>
        <strong data-i18n="app.이_필터에_해당하는_알림이_없어요">${i18n.t('app.이_필터에_해당하는_알림이_없어요')}</strong>
        <p data-i18n="app.다른_필터를_고르거나_새_알림을_만들어_보세요">${i18n.t('app.다른_필터를_고르거나_새_알림을_만들어_보세요')}</p>
      </div>`;
    return;
  }
  list.innerHTML = items.map((item) => renderToryNotifyCard(item)).join("");
}

function fillToryNotifySceneSelect(selected = "") {
  const sel = $("toryNotifyEditScene");
  if (!sel) return;
  const scenes = typeof allScenes === "function" ? allScenes() : [];
  if (!scenes.length) {
    sel.innerHTML = i18n.t('app.option_value_회차가_없어요_op');
    return;
  }
  sel.innerHTML = [i18n.t('app.option_value_아직_미정_목록에만')]
    .concat(scenes.map((scene) => {
      const id = Number(scene.id);
      const label = escapeHtml(scene.title || `${i18n.t('app.씬_id', {id: id})}`);
      const chapter = scene.chapterTitle ? `${escapeHtml(scene.chapterTitle)} · ` : "";
      return `<option value="${id}">${chapter}${label}</option>`;
    }))
    .join("");
  if (selected) sel.value = String(selected);
}

function openToryNotifyEditModal(item = null) {
  const modal = $("toryNotifyEditModal");
  if (!modal) return;
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  fillToryNotifySceneSelect(item?.sceneId || state.sceneId || "");
  if ($("toryNotifyEditId")) $("toryNotifyEditId").value = item?.id || "";
  if ($("toryNotifyEditTitleInput")) $("toryNotifyEditTitleInput").value = item?.title || "";
  if ($("toryNotifyEditMessage")) $("toryNotifyEditMessage").value = item?.message || "";
  if ($("toryNotifyEditNote")) $("toryNotifyEditNote").value = item?.note || "";
  if ($("toryNotifyEditEnabled")) $("toryNotifyEditEnabled").checked = item ? item.enabled !== false : true;
  if ($("toryNotifyEditTitle")) {
    $("toryNotifyEditTitle").textContent = item ? i18n.t('app.알림_수정') : i18n.t('app.알림_만들기');
  }
  if ($("toryNotifyEditSave")) {
    $("toryNotifyEditSave").textContent = item ? i18n.t('app.저장') : i18n.t('app.알림_저장');
  }
  modal.classList.remove("hidden");
  requestAnimationFrame(() => $("toryNotifyEditTitleInput")?.focus());
}

function closeToryNotifyEditModal() {
  $("toryNotifyEditModal")?.classList.add("hidden");
}

function saveToryNotifyFromModal(event) {
  if (event) event.preventDefault();
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  const editId = ($("toryNotifyEditId")?.value || "").trim();
  const title = ($("toryNotifyEditTitleInput")?.value || "").trim();
  if (!title) return toast(i18n.t('app.알림_제목을_적어_주세요'));
  const message = ($("toryNotifyEditMessage")?.value || "").trim();
  const sceneId = Number($("toryNotifyEditScene")?.value || 0) || null;
  const note = ($("toryNotifyEditNote")?.value || "").trim();
  const enabled = Boolean($("toryNotifyEditEnabled")?.checked);
  const list = loadCustomToryNotifs();
  if (editId) {
    const item = list.find((n) => n.id === editId);
    if (!item) return toast(i18n.t('app.수정할_알림을_찾지_못했어요'));
    item.title = title;
    item.message = message;
    item.sceneId = sceneId;
    item.note = note;
    item.enabled = enabled;
    saveCustomToryNotifs(list);
    closeToryNotifyEditModal();
    toast(i18n.t('app.알림을_수정했어요'));
    return;
  }
  list.unshift({
    id: `tn-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
    type: "custom",
    title,
    message,
    sceneId,
    note,
    enabled,
    createdAt: new Date().toISOString(),
  });
  saveCustomToryNotifs(list);
  closeToryNotifyEditModal();
  toast(sceneId ? i18n.t('app.알림을_저장했어요_해당_회차를_열면_토리가') : i18n.t('app.알림을_목록에_저장했어요'));
}

function flipUnifiedToryNotif(id) {
  if (String(id).startsWith("bait:")) {
    const baitId = String(id).slice(5);
    const item = loadBaits().find((b) => b.id === baitId);
    if (!item) return;
    if (!Number(item.recoverSceneId)) {
      toast(i18n.t('app.회수_예정_회차를_먼저_지정해_주세요'));
      renderToryNotifyList();
      return;
    }
    const currentlyOn = item.notifyOnRecover !== false;
    updateBaitOnServer(baitId, { ...item, notifyOnRecover: !currentlyOn })
      .then(() => {
        renderBaitList();
        renderToryNotifyList();
        toast(!currentlyOn ? i18n.t('app.떡밥_알림을_켰어요') : i18n.t('app.떡밥_알림을_껐어요'));
      })
      .catch(handleError);
    return;
  }
  const list = loadCustomToryNotifs();
  const item = list.find((n) => n.id === id);
  if (!item) return;
  item.enabled = !item.enabled;
  saveCustomToryNotifs(list);
  toast(item.enabled ? i18n.t('app.알림을_켰어요') : i18n.t('app.알림을_껐어요'));
}

function setupToryNotifyCenter() {
  $("toryNotifyAddButton")?.addEventListener("click", () => openToryNotifyEditModal(null));
  $("toryNotifyEditForm")?.addEventListener("submit", (event) => saveToryNotifyFromModal(event));
  document.querySelectorAll("[data-close-tory-notify-edit]").forEach((el) => {
    el.addEventListener("click", closeToryNotifyEditModal);
  });
  $("toryNotifyCollapseButton")?.addEventListener("click", () => {
    const box = $("toryNotifyBox");
    applyToryNotifyCollapsed(!box?.classList.contains("is-collapsed"));
  });
  document.querySelectorAll("[data-tory-notif-filter]").forEach((btn) => {
    btn.addEventListener("click", () => setToryNotifyFilter(btn.dataset.toryNotifFilter || "all"));
  });

  $("toryNotifyList")?.addEventListener("change", (event) => {
    const input = event.target.closest?.("input[data-tory-notif-toggle]");
    if (!input) return;
    flipUnifiedToryNotif(input.dataset.toryNotifToggle);
  });

  $("toryNotifyList")?.addEventListener("click", (event) => {
    // Ignore clicks on the switch label (handled by change)
    if (event.target.closest?.(".tory-switch")) return;

    const openSceneBtn = event.target.closest?.("[data-tory-notif-open-scene]");
    if (openSceneBtn) {
      const sid = Number(openSceneBtn.dataset.toryNotifOpenScene);
      if (sid) openScene(sid).catch(handleError);
      return;
    }
    const editBtn = event.target.closest?.("[data-tory-notif-edit]");
    if (editBtn) {
      const id = editBtn.dataset.toryNotifEdit;
      const item = loadCustomToryNotifs().find((n) => n.id === id);
      if (item) openToryNotifyEditModal(item);
      return;
    }
    const delBtn = event.target.closest?.("[data-tory-notif-delete]");
    if (delBtn) {
      const id = delBtn.dataset.toryNotifDelete;
      if (!window.confirm(i18n.t('app.이_알림을_삭제할까요'))) return;
      saveCustomToryNotifs(loadCustomToryNotifs().filter((n) => n.id !== id));
      toast(i18n.t('app.알림을_삭제했어요'));
      return;
    }
    const baitBtn = event.target.closest?.("[data-tory-notif-open-bait]");
    if (baitBtn) {
      const baitId = baitBtn.dataset.toryNotifOpenBait;
      const item = loadBaits().find((b) => b.id === baitId);
      if (!item) return toast(i18n.t('app.떡밥을_찾지_못했어요'));
      setActiveBinder("settings");
      state.openSettingsSection = "baits";
      applySettingsSectionState();
      renderBaitList();
      openBaitModal(item);
    }
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !$("toryNotifyEditModal")?.classList.contains("hidden")) {
      closeToryNotifyEditModal();
    }
  });

  applyToryNotifyCollapsed(loadToryNotifyCollapsed());
  setToryNotifyFilter("all");
}

/* ═══════════════════════════════════════════════════════════
   글쓰기 기록 · 달력 · 목표 응원 · 폰 연동 기반
   ═══════════════════════════════════════════════════════════ */
const writingTracker = {
  prefs: {
    goal_chars: 2000,
    goal_notify: true,
    lonely_days: 3,
    lonely_notify: true,
    idle_minutes: 30,
    /** 글자수 자동집계 (기본 true). false면 기록 버튼 ON일 때만 */
    chars_auto: true,
    /** 집필 시간 자동집계 (기본 false). false면 기록 버튼 ON일 때만 */
    time_auto: false,
    /** 핸드폰 앱 작성 기록을 달력·통계에 포함 (기본 true) */
    include_phone_log: true,
    last_goal_notified_day: "",
    last_lonely_notified_day: "",
    first_met_day: "",
    /** 기록 버튼에 경과 시간 표시 (false면 「기록중」만) */
    show_timer: true,
  },
  /** 기록 버튼으로 켠 활성 타이머 모드 (시간 수동·글자 수동 시 강제 집계) */
  recording: false,
  pendingChars: 0,
  pendingActive: 0,
  /** 현재 기록 세션에서 버튼에 표시할 누적 초 (flush와 무관) */
  sessionDisplaySeconds: 0,
  pendingSessionStart: false,
  sessionStartedAt: null,
  lastActivityAt: 0,
  lastTickAt: 0,
  lastPlainLen: null,
  dayKey: "",
  dayCharsKnown: 0,
  tickTimer: null,
  flushTimer: null,
  uiTimer: null,
  flushing: false,
  calYear: 0,
  calMonth: 0, // 0-11
  selectedDay: "",
  daysMap: /** @type {Record<string, object>} */ ({}),
  /** 달력에서 날짜를 골라 기록 삭제하는 모드 */
  purgeSelectMode: false,
  purgeSelectedDays: /** @type {Set<string>} */ (new Set()),
  cheerTimer: null,
};

function localDayKey(date = new Date()) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function formatActiveDuration(seconds) {
  const s = Math.max(0, Math.floor(Number(seconds) || 0));
  if (s < 60) return `${i18n.t('app.s_초', {s: s})}`;
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const rem = s % 60;
  if (h > 0) return rem ? `${i18n.t('app.h_시간_m_분_rem_초', {h: h, m: m, rem: rem})}` : (m ? `${i18n.t('app.h_시간_m_분', {h: h, m: m})}` : `${i18n.t('app.h_시간', {h: h})}`);
  return rem ? `${i18n.t('app.m_분_rem_초', {m: m, rem: rem})}` : `${i18n.t('app.m_분', {m: m})}`;
}

function formatLocalTimeFromIso(iso) {
  if (!iso) return "—";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) {
    // maybe already local-ish string
    const m = String(iso).match(/T(\d{2}):(\d{2})/);
    if (m) return `${m[1]}:${m[2]}`;
    return String(iso);
  }
  return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
}

function formatKoreanDateLabel(dayKey) {
  const m = String(dayKey || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return dayKey || i18n.t('app.날짜');
  return `${i18n.t('app.Number_m_1_년_Number_m_2', {'Number(m[1])': Number(m[1]), 'Number(m[2])': Number(m[2]), 'Number(m[3])': Number(m[3])})}`;
}

function idleLimitMs() {
  return Math.max(5, Number(writingTracker.prefs.idle_minutes) || 30) * 60 * 1000;
}

/** 글자수: 자동 모드이거나 기록 버튼 ON */
function shouldTrackWritingChars() {
  return Boolean(writingTracker.prefs.chars_auto) || Boolean(writingTracker.recording);
}

/** 집필 시간: 자동 모드이거나 기록 버튼 ON */
function shouldTrackWritingTime() {
  return Boolean(writingTracker.prefs.time_auto) || Boolean(writingTracker.recording);
}

function ensureWritingDayBucket() {
  const today = localDayKey();
  if (writingTracker.dayKey && writingTracker.dayKey !== today) {
    // midnight rollover — flush previous day first
    flushWritingHeartbeat({ force: true }).catch(() => {});
    writingTracker.pendingChars = 0;
    writingTracker.pendingActive = 0;
    writingTracker.pendingSessionStart = false;
    writingTracker.sessionStartedAt = null;
    writingTracker.dayCharsKnown = 0;
  }
  writingTracker.dayKey = today;
}

function noteWritingActivityFromEditor() {
  if (!state.sceneId) return;
  const trackChars = shouldTrackWritingChars();
  const trackTime = shouldTrackWritingTime();
  if (!trackChars && !trackTime) return;
  const plain = getEditorPlainText() || "";
  const len = plain.length;
  ensureWritingDayBucket();
  const now = Date.now();
  if (writingTracker.lastPlainLen == null) {
    writingTracker.lastPlainLen = len;
  } else {
    if (trackChars) {
      const delta = len - writingTracker.lastPlainLen;
      if (delta > 0) {
        writingTracker.pendingChars += delta;
        writingTracker.dayCharsKnown += delta;
        maybeCelebrateWritingGoal();
      }
    }
    writingTracker.lastPlainLen = len;
  }
  if (trackTime) {
    const wasIdle = !writingTracker.lastActivityAt
      || (now - writingTracker.lastActivityAt) >= idleLimitMs();
    if (wasIdle || !writingTracker.sessionStartedAt) {
      writingTracker.sessionStartedAt = new Date().toISOString();
      writingTracker.pendingSessionStart = true;
      writingTracker.lastTickAt = now;
    }
    writingTracker.lastActivityAt = now;
  }
  updateWritingLogButtonUi();
}

function writingTick() {
  if (!shouldTrackWritingTime()) {
    writingTracker.lastTickAt = Date.now();
    return;
  }
  ensureWritingDayBucket();
  const now = Date.now();
  if (!writingTracker.lastActivityAt) {
    writingTracker.lastTickAt = now;
    updateWritingLogButtonUi();
    return;
  }
  if ((now - writingTracker.lastActivityAt) >= idleLimitMs()) {
    // SuperTORY open but idle — do not count time (차감)
    writingTracker.lastTickAt = now;
    updateWritingLogButtonUi();
    return;
  }
  const prev = writingTracker.lastTickAt || now;
  const add = Math.max(0, Math.min(30, Math.round((now - prev) / 1000)));
  if (add > 0) {
    writingTracker.pendingActive += add;
    // Session clock on the button only while explicit recording is on
    if (writingTracker.recording) {
      writingTracker.sessionDisplaySeconds += add;
    }
  }
  writingTracker.lastTickAt = now;
  updateWritingLogButtonUi();
}

function formatRecordingClock(totalSeconds) {
  const s = Math.max(0, Math.floor(Number(totalSeconds) || 0));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  if (h > 0) {
    return `${h}:${String(m).padStart(2, "0")}:${String(sec).padStart(2, "0")}`;
  }
  return `${m}:${String(sec).padStart(2, "0")}`;
}

function liveRecordingSeconds() {
  let sec = writingTracker.sessionDisplaySeconds || 0;
  if (!writingTracker.recording) return sec;
  const now = Date.now();
  if (
    writingTracker.lastActivityAt
    && writingTracker.lastTickAt
    && (now - writingTracker.lastActivityAt) < idleLimitMs()
  ) {
    sec += Math.max(0, Math.floor((now - writingTracker.lastTickAt) / 1000));
  }
  return sec;
}

const WRITING_SHOW_TIMER_KEY = "supertory.writingShowTimer";

function loadShowTimerPref() {
  try {
    const raw = localStorage.getItem(WRITING_SHOW_TIMER_KEY);
    if (raw === "0" || raw === "false") return false;
    if (raw === "1" || raw === "true") return true;
  } catch (_) {
    /* ignore */
  }
  return true; // default: show timer
}

function saveShowTimerPref(show) {
  const on = Boolean(show);
  writingTracker.prefs.show_timer = on;
  try {
    localStorage.setItem(WRITING_SHOW_TIMER_KEY, on ? "1" : "0");
  } catch (_) {
    /* ignore */
  }
}

function isWritingTimerVisible() {
  return writingTracker.prefs.show_timer !== false;
}

function updateWritingLogButtonUi() {
  const btn = $("writingLogButton");
  if (!btn) return;
  const on = Boolean(writingTracker.recording);
  const showTimer = isWritingTimerVisible();
  const timeAuto = Boolean(writingTracker.prefs.time_auto);
  const charsAuto = writingTracker.prefs.chars_auto !== false;
  btn.classList.toggle("is-recording", on);
  btn.setAttribute("aria-pressed", on ? "true" : "false");
  if (on) {
    btn.title = i18n.t('app.클릭_집필_시간_기록_정지_우클릭_달력_설정');
  } else if (timeAuto) {
    btn.title = charsAuto
      ? i18n.t('app.글자수_시간은_자동_집계_중_클릭_타이머_표')
      : i18n.t('app.시간은_자동_집계_중_클릭_타이머_수동_글자');
  } else {
    btn.title = charsAuto
      ? i18n.t('app.클릭_집필_시간_기록_시작_정지_글자수는_자')
      : i18n.t('app.클릭_글자수_시간_기록_시작_정지_우클릭_달');
  }

  // 아이콘은 활성/비활성 모두 유지. 아래 라벨만 "기록" ↔ "0:01" 전환.
  let icon = btn.querySelector(".format-timer-icon");
  if (!icon) {
    icon = document.createElement("span");
    icon.className = "format-tool-glyph format-timer-icon";
    icon.setAttribute("aria-hidden", "true");
    icon.innerHTML = '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.85" stroke-linecap="round" stroke-linejoin="round" focusable="false"><circle cx="12" cy="12" r="8.25"/><path d="M12 7.5V12l3 2"/></svg>';
  } else if (!icon.classList.contains("format-tool-glyph")) {
    icon.classList.add("format-tool-glyph");
  }
  icon.classList.remove("hidden");

  let label = btn.querySelector(".format-tool-label");
  if (!label) {
    label = document.createElement("span");
    label.className = "format-tool-label";
  }
  label.classList.remove("hidden");
  // 시계 숫자는 라벨 자리에서 갱신 (구 writingLogClock id 호환)
  label.id = "writingLogClock";
  label.classList.add("format-timer-clock");

  let badge = btn.querySelector("#writingLogOnBadge") || $("writingLogOnBadge");
  if (!badge || !btn.contains(badge)) {
    badge = document.createElement("span");
    badge.id = "writingLogOnBadge";
    badge.className = "format-tool-badge feature-chip-count feature-chip-on";
  }
  badge.textContent = "on";
  badge.classList.toggle("hidden", !on);
  badge.setAttribute("aria-hidden", on ? "false" : "true");

  if (on) {
    if (!showTimer) {
      label.textContent = i18n.t('app.기록중');
    } else {
      const time = formatRecordingClock(liveRecordingSeconds());
      const idle = writingTracker.lastActivityAt
        && (Date.now() - writingTracker.lastActivityAt) >= idleLimitMs();
      label.textContent = idle ? `${i18n.t('app.일시정지_time', {time: time})}` : time;
    }
    btn.setAttribute("aria-label", `${i18n.t('app.기록_중_label_textContent', {'label.textContent': label.textContent})}`);
  } else {
    label.textContent = i18n.t('app.기록');
    btn.setAttribute("aria-label", i18n.t('app.기록'));
  }
  // 예전 별도 clock 노드가 남아 있으면 제거
  btn.querySelectorAll(".format-timer-clock").forEach((el) => {
    if (el !== label) el.remove();
  });
  btn.replaceChildren(icon, label, badge);
}

function startWritingUiTimer() {
  if (writingTracker.uiTimer) return;
  writingTracker.uiTimer = window.setInterval(() => {
    // Only need per-second refresh when the clock is visible on the button
    if (writingTracker.recording && isWritingTimerVisible()) {
      updateWritingLogButtonUi();
    }
  }, 1000);
}

function stopWritingUiTimer() {
  if (writingTracker.uiTimer) {
    window.clearInterval(writingTracker.uiTimer);
    writingTracker.uiTimer = null;
  }
}

function toggleWritingRecording() {
  if (writingTracker.recording) {
    // stop explicit recording (auto modes may keep counting)
    writingTick();
    writingTracker.recording = false;
    stopWritingUiTimer();
    updateWritingLogButtonUi();
    flushWritingHeartbeat({ force: true }).catch(() => {});
    const stillChars = shouldTrackWritingChars();
    const stillTime = shouldTrackWritingTime();
    if (stillChars && stillTime) {
      toast(i18n.t('app.타이머를_멈췄어요_글자수_시간은_자동_집계가'));
    } else if (stillChars) {
      toast(i18n.t('app.집필_시간_기록을_멈췄어요_글자수는_자동으로'));
    } else if (stillTime) {
      toast(i18n.t('app.수동_기록을_멈췄어요_글쓴_시간은_자동_집계'));
    } else {
      toast(i18n.t('app.기록을_멈췄어요_우클릭으로_달력을_볼_수_있'));
    }
    return;
  }
  // start — new visible session clock; forces both char + time while ON
  ensureWritingDayBucket();
  writingTracker.recording = true;
  writingTracker.sessionDisplaySeconds = 0;
  const now = Date.now();
  writingTracker.lastActivityAt = now;
  writingTracker.lastTickAt = now;
  writingTracker.sessionStartedAt = new Date().toISOString();
  writingTracker.pendingSessionStart = true;
  writingTracker.lastPlainLen = state.sceneId
    ? (getEditorPlainText() || "").length
    : writingTracker.lastPlainLen;
  startWritingUiTimer();
  updateWritingLogButtonUi();
  if (writingTracker.prefs.time_auto) {
    toast(i18n.t('app.기록_타이머_표시_다시_누르면_끕니다'));
  } else {
    toast(i18n.t('app.집필_시간_기록_시작_다시_누르면_정지합니다'));
  }
}

async function flushWritingHeartbeat({ force = false } = {}) {
  if (writingTracker.flushing) return;
  const chars = writingTracker.pendingChars;
  const active = writingTracker.pendingActive;
  const sessionStart = writingTracker.pendingSessionStart;
  if (!force && chars <= 0 && active <= 0 && !sessionStart) return;
  if (chars <= 0 && active <= 0 && !sessionStart) return;
  ensureWritingDayBucket();
  writingTracker.flushing = true;
  const payload = {
    day: writingTracker.dayKey,
    chars_delta: chars,
    active_seconds_delta: active,
    session_start: sessionStart,
    session_started_at: writingTracker.sessionStartedAt,
    last_active_at: writingTracker.lastActivityAt
      ? new Date(writingTracker.lastActivityAt).toISOString()
      : new Date().toISOString(),
    project_id: state.projectId || null,
  };
  // optimistic clear
  writingTracker.pendingChars = 0;
  writingTracker.pendingActive = 0;
  writingTracker.pendingSessionStart = false;
  try {
    const result = await api("/api/writing/heartbeat", {
      method: "POST",
      body: JSON.stringify(payload),
    });
    if (result?.prefs) applyWritingPrefs(result.prefs);
    if (result?.chars_added != null) {
      writingTracker.dayCharsKnown = Math.max(
        writingTracker.dayCharsKnown,
        Number(result.chars_added) || 0,
      );
    }
    if (result?.goal_reached) {
      await celebrateWritingGoal(result.chars_added || writingTracker.dayCharsKnown);
    } else {
      maybeCelebrateWritingGoal();
    }
    // refresh open calendar day if same
    if (
      $("writingLogModal")
      && !$("writingLogModal").classList.contains("hidden")
      && writingTracker.selectedDay === writingTracker.dayKey
    ) {
      await selectWritingDay(writingTracker.dayKey, { silent: true });
    }
  } catch (error) {
    // re-queue on failure
    writingTracker.pendingChars += chars;
    writingTracker.pendingActive += active;
    writingTracker.pendingSessionStart = writingTracker.pendingSessionStart || sessionStart;
    if (force) console.warn("writing heartbeat failed", error);
  } finally {
    writingTracker.flushing = false;
  }
}

function applyWritingPrefs(prefs) {
  if (!prefs || typeof prefs !== "object") return;
  const showTimer = loadShowTimerPref();
  writingTracker.prefs = {
    goal_chars: Math.max(100, Number(prefs.goal_chars) || 2000),
    goal_notify: prefs.goal_notify !== false && prefs.goal_notify !== 0,
    lonely_days: Math.max(1, Number(prefs.lonely_days) || 3),
    lonely_notify: prefs.lonely_notify !== false && prefs.lonely_notify !== 0,
    idle_minutes: Math.max(5, Number(prefs.idle_minutes) || 30),
    // Default: chars auto ON, time auto OFF (manual via 기록 button)
    chars_auto: prefs.chars_auto !== false && prefs.chars_auto !== 0,
    time_auto: prefs.time_auto === true || prefs.time_auto === 1,
    include_phone_log: prefs.include_phone_log !== false && prefs.include_phone_log !== 0,
    last_goal_notified_day: String(prefs.last_goal_notified_day || ""),
    last_lonely_notified_day: String(prefs.last_lonely_notified_day || ""),
    first_met_day: String(prefs.first_met_day || "").trim(),
    show_timer: showTimer,
  };
  syncWritingPrefsForm();
  updateWritingLogButtonUi();
}

function isFirstMetDay(dayKey) {
  const met = String(writingTracker.prefs.first_met_day || "").trim();
  return Boolean(met && dayKey && met === dayKey);
}

const CAL_ACORN_SVG = (
  '<img class="cal-acorn-svg" src="/assets/tori-mascot.png" alt="" aria-hidden="true">'
);

function syncWritingPrefsForm() {
  const p = writingTracker.prefs;
  if ($("writingCharsAuto")) $("writingCharsAuto").checked = p.chars_auto !== false;
  if ($("writingTimeAuto")) $("writingTimeAuto").checked = Boolean(p.time_auto);
  if ($("writingGoalChars")) $("writingGoalChars").value = String(p.goal_chars);
  if ($("writingGoalNotify")) $("writingGoalNotify").checked = Boolean(p.goal_notify);
  if ($("writingLonelyDays")) $("writingLonelyDays").value = String(p.lonely_days);
  if ($("writingLonelyNotify")) $("writingLonelyNotify").checked = Boolean(p.lonely_notify);
  if ($("writingIdleMinutes")) $("writingIdleMinutes").value = String(p.idle_minutes);
  if ($("writingShowTimer")) $("writingShowTimer").checked = p.show_timer !== false;
  if ($("writingIncludePhoneLog")) $("writingIncludePhoneLog").checked = p.include_phone_log !== false;
}

function maybeCelebrateWritingGoal() {
  const p = writingTracker.prefs;
  if (!p.goal_notify) return;
  const day = localDayKey();
  if (p.last_goal_notified_day === day) return;
  const total = writingTracker.dayCharsKnown + writingTracker.pendingChars;
  if (total < (p.goal_chars || 2000)) return;
  celebrateWritingGoal(total).catch(handleError);
}

async function celebrateWritingGoal(totalChars) {
  const p = writingTracker.prefs;
  if (!p.goal_notify) return;
  const day = localDayKey();
  if (p.last_goal_notified_day === day) return;
  const goal = p.goal_chars || 2000;
  p.last_goal_notified_day = day;
  try {
    await api("/api/writing/prefs", {
      method: "POST",
      body: JSON.stringify({ last_goal_notified_day: day }),
    });
  } catch (_) {
    /* ignore mark failure */
  }
  showToryCheer(
    i18n.t('app.연속_목표_달성'),
    `${goal.toLocaleString("ko-KR")}자 달성! 오늘 ${Number(totalChars || goal).toLocaleString("ko-KR")}자까지 썼어요.\n토리가 응원해요. 잠깐 쉬어도, 다시 오면 기다릴게요.`,
  );
  tryDesktopNotification(
    i18n.t('app.SuperTORY_목표_달성'),
    `${i18n.t('app.goal_toLocaleString_ko_2', {'goal.toLocaleString("ko-KR")': goal.toLocaleString("ko-KR")})}`,
  );
}

function showToryCheer(title, message) {
  const card = $("toryCheerCard");
  if (!card) {
    toast(message);
    return;
  }
  if ($("toryCheerTitle")) $("toryCheerTitle").textContent = title || i18n.t('app.토리의_응원');
  if ($("toryCheerMessage")) $("toryCheerMessage").textContent = message || "";
  card.classList.remove("hidden");
  if (writingTracker.cheerTimer) window.clearTimeout(writingTracker.cheerTimer);
  writingTracker.cheerTimer = window.setTimeout(() => hideToryCheer(), 10000);
}

function hideToryCheer() {
  $("toryCheerCard")?.classList.add("hidden");
  if (writingTracker.cheerTimer) {
    window.clearTimeout(writingTracker.cheerTimer);
    writingTracker.cheerTimer = null;
  }
}

function tryDesktopNotification(title, body) {
  try {
    if (!("Notification" in window)) return;
    if (Notification.permission === "granted") {
      // eslint-disable-next-line no-new
      new Notification(title, { body });
    } else if (Notification.permission === "default") {
      Notification.requestPermission().then((perm) => {
        if (perm === "granted") {
          // eslint-disable-next-line no-new
          new Notification(title, { body });
        }
      }).catch(() => {});
    }
  } catch (_) {
    /* ignore */
  }
}

async function checkLonelyWriter() {
  try {
    const data = await api("/api/writing/days?from=1970-01-01&to=9999-12-31");
    if (data?.prefs) applyWritingPrefs(data.prefs);
    const p = writingTracker.prefs;
    if (!p.lonely_notify) return;
    const today = localDayKey();
    if (p.last_lonely_notified_day === today) return;
    const lastDay = data?.last_active_day || null;
    if (!lastDay) {
      // never wrote — skip nagging on first launch
      return;
    }
    const last = new Date(`${lastDay}T12:00:00`);
    const now = new Date(`${today}T12:00:00`);
    const diffDays = Math.floor((now - last) / (24 * 3600 * 1000));
    if (diffDays < (p.lonely_days || 3)) return;
    p.last_lonely_notified_day = today;
    try {
      await api("/api/writing/prefs", {
        method: "POST",
        body: JSON.stringify({ last_lonely_notified_day: today }),
      });
    } catch (_) { /* ignore */ }
    showToryCheer(
      i18n.t('app.토리가_외로워요'),
      `${diffDays}일 동안 글이 없었어요.\n조금만 써 주면 토리가 기뻐할 거예요. 휴대폰 앱이 생기면 거기로도 불러줄게요.`,
    );
    tryDesktopNotification("SuperTORY", i18n.t('app.토리가_외로워요_오늘_한_줄만_써볼까요'));
  } catch (_) {
    /* offline / first run */
  }
}

function setWritingLogTab(tab) {
  if (tab !== "calendar" && writingTracker.purgeSelectMode) {
    setWritingLogPurgeSelectMode(false);
  }
  document.querySelectorAll(".writing-log-tab").forEach((btn) => {
    const on = btn.dataset.writingTab === tab;
    btn.classList.toggle("is-active", on);
    btn.setAttribute("aria-selected", on ? "true" : "false");
  });
  document.querySelectorAll(".writing-log-pane").forEach((pane) => {
    pane.classList.toggle("hidden", pane.dataset.writingPane !== tab);
  });
  if (tab === "phone") refreshWritingPhonePane().catch(handleError);
  if (tab === "settings") syncWritingPrefsForm();
  if (tab === "stats") refreshWritingStatsPane().catch(handleError);
}

function shiftLocalDayKey(dayKey, deltaDays) {
  const m = String(dayKey || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return dayKey;
  const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  d.setDate(d.getDate() + deltaDays);
  return localDayKey(d);
}

/** Monday-start week key: YYYY-MM-DD of that Monday */
function weekStartKey(dayKey) {
  const m = String(dayKey || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return dayKey;
  const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  const dow = d.getDay(); // 0 Sun .. 6 Sat
  const offset = dow === 0 ? -6 : 1 - dow;
  d.setDate(d.getDate() + offset);
  return localDayKey(d);
}

function monthKeyFromDay(dayKey) {
  return String(dayKey || "").slice(0, 7); // YYYY-MM
}

function formatWeekLabel(mondayKey) {
  const sun = shiftLocalDayKey(mondayKey, 6);
  const a = String(mondayKey).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const b = String(sun).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!a || !b) return mondayKey;
  return `${Number(a[2])}/${Number(a[3])}–${Number(b[2])}/${Number(b[3])}`;
}

function formatMonthLabel(ym) {
  const m = String(ym || "").match(/^(\d{4})-(\d{2})$/);
  if (!m) return ym;
  return `${i18n.t('app.m_1_년_Number_m_2_월', {'m[1]': m[1], 'Number(m[2])': Number(m[2])})}`;
}

function aggregateWritingDays(daysList) {
  const byDay = {};
  for (const row of daysList || []) {
    const key = row?.day;
    if (!key) continue;
    byDay[key] = {
      day: key,
      chars: Number(row.chars_added) || 0,
      seconds: Number(row.active_seconds) || 0,
      sessions: Number(row.session_count) || 0,
    };
  }
  // Fold in pending today
  const today = localDayKey();
  if (!byDay[today]) {
    byDay[today] = { day: today, chars: 0, seconds: 0, sessions: 0 };
  }
  byDay[today].chars += writingTracker.pendingChars || 0;
  byDay[today].seconds += writingTracker.pendingActive || 0;
  if (writingTracker.pendingSessionStart) byDay[today].sessions += 1;

  const dayRows = Object.values(byDay)
    .filter((r) => r.chars > 0 || r.seconds > 0 || r.sessions > 0)
    .sort((a, b) => (a.day < b.day ? 1 : -1));

  const weekMap = {};
  const monthMap = {};
  for (const r of dayRows) {
    const wk = weekStartKey(r.day);
    if (!weekMap[wk]) weekMap[wk] = { key: wk, chars: 0, seconds: 0, days: 0 };
    weekMap[wk].chars += r.chars;
    weekMap[wk].seconds += r.seconds;
    weekMap[wk].days += 1;
    const mk = monthKeyFromDay(r.day);
    if (!monthMap[mk]) monthMap[mk] = { key: mk, chars: 0, seconds: 0, days: 0 };
    monthMap[mk].chars += r.chars;
    monthMap[mk].seconds += r.seconds;
    monthMap[mk].days += 1;
  }
  const weekRows = Object.values(weekMap).sort((a, b) => (a.key < b.key ? 1 : -1));
  const monthRows = Object.values(monthMap).sort((a, b) => (a.key < b.key ? 1 : -1));
  return { byDay, dayRows, weekRows, monthRows, today };
}

function renderWritingStatsTable(container, rows, columns) {
  if (!container) return;
  if (!rows.length) {
    container.innerHTML = i18n.t('app.p_class_hint_writing_st');
    return;
  }
  const head = columns.map((c) => `<th>${escapeHtml(c.label)}</th>`).join("");
  const body = rows.map((row) => {
    const tds = columns.map((c) => `<td>${c.render(row)}</td>`).join("");
    const cur = row.isCurrent ? " is-current" : "";
    return `<tr class="${cur}">${tds}</tr>`;
  }).join("");
  container.innerHTML = `
    <table class="writing-stats-table">
      <thead><tr>${head}</tr></thead>
      <tbody>${body}</tbody>
    </table>
  `;
}

async function refreshWritingStatsPane() {
  const highlights = $("writingStatsHighlights");
  const dailyEl = $("writingStatsDaily");
  const weeklyEl = $("writingStatsWeekly");
  const monthlyEl = $("writingStatsMonthly");
  if (!dailyEl || !weeklyEl || !monthlyEl) return;

  // Load enough history for monthly view (about 2 years)
  const to = localDayKey();
  const fromDate = new Date();
  fromDate.setFullYear(fromDate.getFullYear() - 2);
  const from = localDayKey(fromDate);
  let days = [];
  try {
    const data = await api(
      `/api/writing/days?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`,
    );
    if (data?.prefs) applyWritingPrefs(data.prefs);
    days = data?.days || [];
  } catch (error) {
    handleError(error);
  }

  const { byDay, dayRows, weekRows, monthRows, today } = aggregateWritingDays(days);
  const thisWeek = weekStartKey(today);
  const thisMonth = monthKeyFromDay(today);
  const todayRec = byDay[today] || { chars: 0, seconds: 0 };
  const weekRec = weekRows.find((w) => w.key === thisWeek) || { chars: 0, seconds: 0 };
  const monthRec = monthRows.find((m) => m.key === thisMonth) || { chars: 0, seconds: 0 };

  if (highlights) {
    highlights.innerHTML = `
      <div class="writing-stats-card">
        <strong>${i18n.t('app.오늘_일간')}</strong>
        <div class="stats-chars">${(() => {
          const n = todayRec.chars || 0;
          return n.toLocaleString("ko-KR") + i18n.t(n === 1 ? 'app.자_접미사_단수' : 'app.자_접미사');
        })()}</div>
        <div class="stats-time">${escapeHtml(formatActiveDuration(todayRec.seconds || 0))}</div>
      </div>
      <div class="writing-stats-card">
        <strong>${i18n.t('app.이번_주_주간')}</strong>
        <div class="stats-chars">${(() => {
          const n = weekRec.chars || 0;
          return n.toLocaleString("ko-KR") + i18n.t(n === 1 ? 'app.자_접미사_단수' : 'app.자_접미사');
        })()}</div>
        <div class="stats-time">${escapeHtml(formatActiveDuration(weekRec.seconds || 0))}</div>
      </div>
      <div class="writing-stats-card">
        <strong>${i18n.t('app.이번_달_월별')}</strong>
        <div class="stats-chars">${(() => {
          const n = monthRec.chars || 0;
          return n.toLocaleString("ko-KR") + i18n.t(n === 1 ? 'app.자_접미사_단수' : 'app.자_접미사');
        })()}</div>
        <div class="stats-time">${escapeHtml(formatActiveDuration(monthRec.seconds || 0))}</div>
      </div>
    `;
  }

  const dailyView = dayRows.slice(0, 31).map((r) => ({
    ...r,
    isCurrent: r.day === today,
    label: r.day === today
      ? `${i18n.t('app.formatKoreanDateLabel_r', {'formatKoreanDateLabel(r.day)': formatKoreanDateLabel(r.day)})}`
      : formatKoreanDateLabel(r.day),
  }));
  renderWritingStatsTable(dailyEl, dailyView, [
    { label: i18n.t('app.날짜'), render: (r) => escapeHtml(r.label) },
    { label: i18n.t('app.글자_수'), render: (r) => `${i18n.t('app.r_chars_0_toLocaleStrin', {'(r.chars || 0).toLocaleString("ko-KR")': (r.chars || 0).toLocaleString("ko-KR")})}` },
    { label: i18n.t('app.집필_시간'), render: (r) => escapeHtml(formatActiveDuration(r.seconds || 0)) },
  ]);

  const weeklyView = weekRows.slice(0, 26).map((r) => ({
    ...r,
    isCurrent: r.key === thisWeek,
    label: r.key === thisWeek
      ? `${i18n.t('app.formatWeekLabel_r_key_이', {'formatWeekLabel(r.key)': formatWeekLabel(r.key)})}`
      : formatWeekLabel(r.key),
  }));
  renderWritingStatsTable(weeklyEl, weeklyView, [
    { label: i18n.t('app.주_월_일'), render: (r) => escapeHtml(r.label) },
    { label: i18n.t('app.글자_수'), render: (r) => `${i18n.t('app.r_chars_0_toLocaleStrin', {'(r.chars || 0).toLocaleString("ko-KR")': (r.chars || 0).toLocaleString("ko-KR")})}` },
    { label: i18n.t('app.집필_시간'), render: (r) => escapeHtml(formatActiveDuration(r.seconds || 0)) },
  ]);

  const monthlyView = monthRows.slice(0, 24).map((r) => ({
    ...r,
    isCurrent: r.key === thisMonth,
    label: r.key === thisMonth
      ? `${i18n.t('app.formatMonthLabel_r_key', {'formatMonthLabel(r.key)': formatMonthLabel(r.key)})}`
      : formatMonthLabel(r.key),
  }));
  renderWritingStatsTable(monthlyEl, monthlyView, [
    { label: i18n.t('app.월'), render: (r) => escapeHtml(r.label) },
    { label: i18n.t('app.글자_수'), render: (r) => `${i18n.t('app.r_chars_0_toLocaleStrin', {'(r.chars || 0).toLocaleString("ko-KR")': (r.chars || 0).toLocaleString("ko-KR")})}` },
    { label: i18n.t('app.집필_시간'), render: (r) => escapeHtml(formatActiveDuration(r.seconds || 0)) },
  ]);
}

async function openWritingLogModal(tab = "calendar") {
  const modal = $("writingLogModal");
  if (!modal) return;
  const now = new Date();
  if (!writingTracker.calYear) {
    writingTracker.calYear = now.getFullYear();
    writingTracker.calMonth = now.getMonth();
  }
  const nextTab = ["calendar", "stats", "settings", "phone"].includes(tab) ? tab : "calendar";
  setWritingLogTab(nextTab);
  modal.classList.remove("hidden");
  if (nextTab === "calendar") {
    await loadWritingCalendarMonth();
    const today = localDayKey();
    await selectWritingDay(today);
  } else if (nextTab === "phone") {
    syncWritingPrefsForm();
  }
}

function closeWritingLogModal() {
  setWritingLogPurgeSelectMode(false);
  $("writingLogModal")?.classList.add("hidden");
}

function resetWritingPendingAfterClear(deletedDays, clearedAll) {
  const today = localDayKey();
  if (clearedAll || (Array.isArray(deletedDays) && deletedDays.includes(today))) {
    writingTracker.pendingChars = 0;
    writingTracker.pendingActive = 0;
    writingTracker.pendingSessionStart = false;
    writingTracker.sessionDisplaySeconds = 0;
    writingTracker.sessionStartedAt = null;
    updateWritingLogButtonUi();
  }
}

function dayHasWritingRecord(dayKey) {
  const rec = writingTracker.daysMap?.[dayKey];
  if (!rec) {
    if (dayKey === localDayKey()) {
      return (writingTracker.pendingChars > 0) || (writingTracker.pendingActive > 0) || writingTracker.pendingSessionStart;
    }
    return false;
  }
  const chars = Number(rec.chars_added) || 0;
  const secs = Number(rec.active_seconds) || 0;
  const sessions = Number(rec.session_count) || 0;
  let pendingChars = 0;
  let pendingActive = 0;
  if (dayKey === localDayKey()) {
    pendingChars = writingTracker.pendingChars || 0;
    pendingActive = writingTracker.pendingActive || 0;
  }
  return (chars + pendingChars) > 0 || (secs + pendingActive) > 0 || sessions > 0 || writingTracker.pendingSessionStart;
}

function updateWritingLogPurgeUi() {
  const modeOn = Boolean(writingTracker.purgeSelectMode);
  const btn = $("writingLogClearSelectButton");
  const actions = $("writingLogPurgeActions");
  const countEl = $("writingLogPurgeCount");
  const confirmBtn = $("writingLogPurgeConfirm");
  const modal = $("writingLogModal");
  btn?.classList.toggle("is-active", modeOn);
  btn?.setAttribute("aria-pressed", modeOn ? "true" : "false");
  btn && (btn.textContent = modeOn ? i18n.t('app.선택_삭제_중') : i18n.t('app.기록_선택_삭제'));
  actions?.classList.toggle("hidden", !modeOn);
  modal?.classList.toggle("is-purge-select", modeOn);
  const n = writingTracker.purgeSelectedDays?.size || 0;
  if (countEl) {
    countEl.textContent = modeOn
      ? (n ? `${i18n.t('app.n_일_선택됨_달력에서_날짜를_눌러_고르세', {n: n})}` : i18n.t('app.달력에서_지울_날짜를_고르세요'))
      : "";
  }
  if (confirmBtn) confirmBtn.disabled = !modeOn || n <= 0;
}

function setWritingLogPurgeSelectMode(on) {
  const next = Boolean(on);
  writingTracker.purgeSelectMode = next;
  if (!writingTracker.purgeSelectedDays) writingTracker.purgeSelectedDays = new Set();
  if (!next) writingTracker.purgeSelectedDays.clear();
  updateWritingLogPurgeUi();
  renderWritingCalendarGrid();
  if (next) {
    toast(i18n.t('app.달력에서_지울_날짜를_고른_뒤_선택한_기록'));
  }
}

function toggleWritingLogPurgeDay(dayKey) {
  if (!dayKey || !writingTracker.purgeSelectMode) return;
  if (!writingTracker.purgeSelectedDays) writingTracker.purgeSelectedDays = new Set();
  if (!dayHasWritingRecord(dayKey) && !writingTracker.purgeSelectedDays.has(dayKey)) {
    toast(i18n.t('app.지울_기록이_없는_날짜예요'));
    return;
  }
  if (writingTracker.purgeSelectedDays.has(dayKey)) writingTracker.purgeSelectedDays.delete(dayKey);
  else writingTracker.purgeSelectedDays.add(dayKey);
  updateWritingLogPurgeUi();
  renderWritingCalendarGrid();
}

async function clearAllWritingLogs() {
  if (!window.confirm(i18n.t('app.모든_글쓰기_기록_글자수_집필_시간_을_삭제'))) {
    return;
  }
  try {
    await flushWritingHeartbeat({ force: true });
  } catch (_) { /* ignore */ }
  const result = await api("/api/writing/days/clear", {
    method: "POST",
    body: JSON.stringify({ all: true }),
  });
  resetWritingPendingAfterClear([], true);
  writingTracker.daysMap = {};
  setWritingLogPurgeSelectMode(false);
  if ($("writingLogModal") && !$("writingLogModal").classList.contains("hidden")) {
    await loadWritingCalendarMonth();
    await selectWritingDay(localDayKey(), { silent: true });
    if (typeof refreshWritingStatsPane === "function") {
      try { await refreshWritingStatsPane(); } catch (_) { /* ignore */ }
    }
  }
  toast(result?.deleted ? `${i18n.t('app.기록_result_deleted_일을_모두', {'result.deleted': result.deleted})}` : i18n.t('app.지울_기록이_없었어요'));
}

async function confirmWritingLogPurgeSelection() {
  const checked = [...(writingTracker.purgeSelectedDays || [])].filter(Boolean);
  if (!checked.length) {
    toast(i18n.t('app.지울_날짜를_선택해_주세요'));
    return;
  }
  if (!window.confirm(`${i18n.t('app.선택한_checked_length_일의_기록', {'checked.length': checked.length})}`)) return;
  const result = await api("/api/writing/days/clear", {
    method: "POST",
    body: JSON.stringify({ days: checked }),
  });
  const deletedDays = result?.days || checked;
  resetWritingPendingAfterClear(deletedDays, false);
  deletedDays.forEach((day) => {
    if (writingTracker.daysMap) delete writingTracker.daysMap[day];
  });
  setWritingLogPurgeSelectMode(false);
  if ($("writingLogModal") && !$("writingLogModal").classList.contains("hidden")) {
    await loadWritingCalendarMonth();
    await selectWritingDay(writingTracker.selectedDay || localDayKey(), { silent: true });
  }
  toast(result?.deleted ? `${i18n.t('app.선택한_기록_result_deleted_일을', {'result.deleted': result.deleted})}` : i18n.t('app.선택한_날짜에_기록이_없었어요'));
}

function setupWritingLogPurgeControls() {
  const allBtn = $("writingLogClearAllButton");
  const selectBtn = $("writingLogClearSelectButton");
  if (!allBtn || allBtn.dataset.bound === "1") return;
  allBtn.dataset.bound = "1";
  allBtn.addEventListener("click", () => clearAllWritingLogs().catch(handleError));
  selectBtn?.addEventListener("click", () => {
    setWritingLogPurgeSelectMode(!writingTracker.purgeSelectMode);
  });
  $("writingLogPurgeCancel")?.addEventListener("click", () => setWritingLogPurgeSelectMode(false));
  $("writingLogPurgeConfirm")?.addEventListener("click", () => {
    confirmWritingLogPurgeSelection().catch(handleError);
  });
}

async function loadWritingCalendarMonth() {
  const y = writingTracker.calYear;
  const m = writingTracker.calMonth;
  if ($("writingCalTitle")) $("writingCalTitle").textContent = `${y}.${m + 1}`;
  const from = `${y}-${String(m + 1).padStart(2, "0")}-01`;
  const lastDate = new Date(y, m + 1, 0).getDate();
  const to = `${y}-${String(m + 1).padStart(2, "0")}-${String(lastDate).padStart(2, "0")}`;
  try {
    const data = await api(`/api/writing/days?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`);
    if (data?.prefs) applyWritingPrefs(data.prefs);
    writingTracker.daysMap = {};
    for (const day of data?.days || []) {
      if (day?.day) writingTracker.daysMap[day.day] = day;
    }
  } catch (error) {
    handleError(error);
    writingTracker.daysMap = {};
  }
  renderWritingCalendarGrid();
}

function renderWritingCalendarGrid() {
  const grid = $("writingCalGrid");
  if (!grid) return;
  const y = writingTracker.calYear;
  const m = writingTracker.calMonth;
  const firstDow = new Date(y, m, 1).getDay();
  const daysInMonth = new Date(y, m + 1, 0).getDate();
  const today = localDayKey();
  const purgeOn = Boolean(writingTracker.purgeSelectMode);
  const purgeSet = writingTracker.purgeSelectedDays || new Set();
  let maxChars = 1;
  Object.values(writingTracker.daysMap).forEach((d) => {
    maxChars = Math.max(maxChars, Number(d.chars_added) || 0);
  });
  if (writingTracker.pendingChars > 0) {
    maxChars = Math.max(maxChars, writingTracker.pendingChars);
  }
  const cells = [];
  for (let i = 0; i < firstDow; i += 1) {
    cells.push(`<button type="button" class="writing-cal-cell is-muted" disabled tabindex="-1"></button>`);
  }
  for (let day = 1; day <= daysInMonth; day += 1) {
    const key = `${y}-${String(m + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    const rec = writingTracker.daysMap[key];
    let chars = Number(rec?.chars_added) || 0;
    if (key === today) chars += writingTracker.pendingChars || 0;
    const heat = chars > 0 ? Math.max(12, Math.round((chars / maxChars) * 55)) : 0;
    const firstMet = isFirstMetDay(key);
    const purgePicked = purgeOn && purgeSet.has(key);
    const classes = [
      "writing-cal-cell",
      key === today ? "is-today" : "",
      !purgeOn && key === writingTracker.selectedDay ? "is-selected" : "",
      chars > 0 ? "has-write" : "",
      firstMet ? "is-first-met" : "",
      purgeOn ? "is-purge-target" : "",
      purgePicked ? "is-purge-picked" : "",
    ].filter(Boolean).join(" ");
    const titleBits = [key];
    if (firstMet) titleBits.push(i18n.t('app.토리와_처음_만난_날'));
    if (chars) titleBits.push(`${i18n.t('app.chars_자', {chars: chars})}`);
    if (purgeOn) titleBits.push(purgePicked ? i18n.t('app.삭제_선택됨') : i18n.t('app.클릭해서_삭제_선택'));
    cells.push(
      `<button type="button" class="${classes}" data-day="${key}" style="--write-heat:${heat}" title="${escapeHtml(titleBits.join(" · "))}"${purgePicked ? ' aria-pressed="true"' : ""}>`
      + `<span>${day}</span>`
      + `${firstMet ? CAL_ACORN_SVG : (chars > 0 ? '<span class="cal-dot"></span>' : "")}`
      + `</button>`,
    );
  }
  grid.innerHTML = cells.join("");
}

async function selectWritingDay(dayKey, { silent = false } = {}) {
  writingTracker.selectedDay = dayKey;
  renderWritingCalendarGrid();
  if ($("writingDayTitle")) $("writingDayTitle").textContent = formatKoreanDateLabel(dayKey);
  let rec = writingTracker.daysMap[dayKey];
  // include unsent pending for today
  let chars = Number(rec?.chars_added) || 0;
  let active = Number(rec?.active_seconds) || 0;
  let sessions = Number(rec?.session_count) || 0;
  let start = rec?.first_start_at || null;
  if (dayKey === localDayKey()) {
    chars += writingTracker.pendingChars;
    active += writingTracker.pendingActive;
    if (writingTracker.pendingSessionStart) sessions += 1;
    if (!start && writingTracker.sessionStartedAt) start = writingTracker.sessionStartedAt;
  }
  if (!silent) {
    try {
      const detail = await api(`/api/writing/days/${encodeURIComponent(dayKey)}`);
      if (detail) {
        writingTracker.daysMap[dayKey] = detail;
        chars = Number(detail.chars_added) || 0;
        active = Number(detail.active_seconds) || 0;
        sessions = Number(detail.session_count) || 0;
        start = detail.first_start_at || start;
        if (dayKey === localDayKey()) {
          chars += writingTracker.pendingChars;
          active += writingTracker.pendingActive;
        }
        if (detail.prefs) applyWritingPrefs(detail.prefs);
      }
    } catch (_) {
      /* use cache */
    }
  }
  if ($("writingDayChars")) {
    $("writingDayChars").textContent = chars
      ? `${i18n.t('app.chars_toLocaleString_ko', {'chars.toLocaleString("ko-KR")': chars.toLocaleString("ko-KR")})}`
      : i18n.t('app.0자');
  }
  if ($("writingDayStart")) {
    $("writingDayStart").textContent = start ? formatLocalTimeFromIso(start) : "—";
  }
  if ($("writingDayActive")) {
    $("writingDayActive").textContent = formatActiveDuration(active);
  }
  if ($("writingDaySessions")) {
    $("writingDaySessions").textContent = String(sessions || 0);
  }
  if ($("writingDayHint")) {
    const idle = writingTracker.prefs.idle_minutes || 30;
    $("writingDayHint").textContent =
      `${i18n.t('app.미입력_idle_분_이상은_집필_시간에서_제', {idle: idle})}`;
  }
  const firstMetBanner = $("writingFirstMetBanner");
  if (firstMetBanner) {
    firstMetBanner.classList.toggle("hidden", !isFirstMetDay(dayKey));
  }
  if (isFirstMetDay(dayKey) && $("writingDayTitle")) {
    $("writingDayTitle").textContent = `${i18n.t('app.formatKoreanDateLabel_d', {'formatKoreanDateLabel(dayKey)': formatKoreanDateLabel(dayKey)})}`;
  }
}

async function saveWritingPrefsFromForm() {
  const showTimer = Boolean($("writingShowTimer")?.checked);
  saveShowTimerPref(showTimer);
  const body = {
    chars_auto: Boolean($("writingCharsAuto")?.checked),
    time_auto: Boolean($("writingTimeAuto")?.checked),
    include_phone_log: Boolean($("writingIncludePhoneLog")?.checked),
    goal_chars: Number($("writingGoalChars")?.value || 2000),
    goal_notify: Boolean($("writingGoalNotify")?.checked),
    lonely_days: Number($("writingLonelyDays")?.value || 3),
    lonely_notify: Boolean($("writingLonelyNotify")?.checked),
    idle_minutes: Number($("writingIdleMinutes")?.value || 30),
  };
  const prefs = await api("/api/writing/prefs", {
    method: "POST",
    body: JSON.stringify(body),
  });
  applyWritingPrefs(prefs);
  // Re-apply timer visibility after server prefs merge
  saveShowTimerPref(showTimer);
  updateWritingLogButtonUi();
  toast(i18n.t('app.기록_설정을_저장했어요'));
}

async function saveWritingIncludePhoneLogPref() {
  const on = Boolean($("writingIncludePhoneLog")?.checked);
  writingTracker.prefs.include_phone_log = on;
  try {
    const prefs = await api("/api/writing/prefs", {
      method: "POST",
      body: JSON.stringify({ include_phone_log: on }),
    });
    applyWritingPrefs(prefs);
    toast(on ? i18n.t('app.핸드폰_작성_기록을_포함해요') : i18n.t('app.핸드폰_작성_기록을_제외해요'));
  } catch (error) {
    handleError(error);
    syncWritingPrefsForm();
  }
}

async function refreshWritingPhonePane() {
  try {
    const pair = await api("/api/writing/pair");
    if ($("writingPairCode")) {
      $("writingPairCode").textContent = pair?.pair_code || "————";
    }
    if ($("writingPairHint")) {
      $("writingPairHint").textContent = pair?.pair_code
        ? i18n.t('app.휴대폰_전용_앱에서_이_코드로_연결할_예정')
        : (pair?.paired
          ? `연결됨${pair.device_name ? ` · ${pair.device_name}` : ""}`
          : i18n.t('app.코드를_발급하면_앱_연동_준비가_됩니다'));
    }
  } catch (error) {
    if ($("writingPairHint")) $("writingPairHint").textContent = i18n.t('app.연동_정보를_불러오지_못했어요');
  }
  try {
    const inbox = await api("/api/writing/inbox");
    renderWritingInbox(inbox?.items || []);
  } catch (_) {
    renderWritingInbox([]);
  }
}

function renderWritingInbox(items) {
  const list = $("writingInboxList");
  if (!list) return;
  if (!items.length) {
    list.innerHTML = i18n.t('app.p_class_hint_writing_in');
    return;
  }
  list.innerHTML = items.map((item) => {
    const when = item.created_at ? formatLocalTimeFromIso(item.created_at) : "";
    const datePart = String(item.created_at || "").slice(0, 10);
    return `
      <article class="writing-inbox-item${item.read ? "" : " is-unread"}" data-inbox-id="${item.id}">
        <div class="writing-inbox-item-head">
          <strong>${escapeHtml(item.title || i18n.t('app.제목_없음'))}</strong>
          <span>${escapeHtml(datePart)} ${escapeHtml(when)}</span>
        </div>
        <p class="writing-inbox-preview">${escapeHtml(item.preview || "")}</p>
        <button type="button" class="secondary" data-inbox-copy="${item.id}">${i18n.t('app.복사')}</button>
      </article>
    `;
  }).join("");
  list._inboxItems = items;
}

async function issueWritingPairCode() {
  const pair = await api("/api/writing/pair", {
    method: "POST",
    body: JSON.stringify({}),
  });
  if ($("writingPairCode")) $("writingPairCode").textContent = pair?.pair_code || "————";
  if ($("writingPairHint")) {
    $("writingPairHint").textContent = i18n.t('app.휴대폰_전용_앱에서_이_코드로_연결할_예정');
  }
  toast(i18n.t('app.연동_코드를_발급했어요'));
}

function setupWritingLog() {
  setupWritingLogPurgeControls();
  const modal = $("writingLogModal");
  if (!modal || modal.dataset.bound === "1") {
    // still start tracker timers once
  } else {
    modal.dataset.bound = "1";
    modal.querySelectorAll("[data-close-writing-log]").forEach((el) => {
      el.addEventListener("click", (event) => {
        event.preventDefault();
        closeWritingLogModal();
      });
    });
    document.querySelectorAll(".writing-log-tab").forEach((btn) => {
      btn.addEventListener("click", () => setWritingLogTab(btn.dataset.writingTab || "calendar"));
    });
    $("writingCalPrev")?.addEventListener("click", async () => {
      writingTracker.calMonth -= 1;
      if (writingTracker.calMonth < 0) {
        writingTracker.calMonth = 11;
        writingTracker.calYear -= 1;
      }
      await loadWritingCalendarMonth();
    });
    $("writingCalNext")?.addEventListener("click", async () => {
      writingTracker.calMonth += 1;
      if (writingTracker.calMonth > 11) {
        writingTracker.calMonth = 0;
        writingTracker.calYear += 1;
      }
      await loadWritingCalendarMonth();
    });
    $("writingCalGrid")?.addEventListener("click", (event) => {
      const btn = event.target.closest?.("[data-day]");
      if (!btn) return;
      const day = btn.getAttribute("data-day") || "";
      if (writingTracker.purgeSelectMode) {
        toggleWritingLogPurgeDay(day);
        return;
      }
      selectWritingDay(day).catch(handleError);
    });
    $("writingPrefsSave")?.addEventListener("click", () => {
      saveWritingPrefsFromForm().catch(handleError);
    });
    $("writingPairRefresh")?.addEventListener("click", () => {
      issueWritingPairCode().catch(handleError);
    });
    $("writingIncludePhoneLog")?.addEventListener("change", () => {
      saveWritingIncludePhoneLogPref().catch(handleError);
    });
    $("writingInboxList")?.addEventListener("click", async (event) => {
      const btn = event.target.closest?.("[data-inbox-copy]");
      if (!btn) return;
      const id = Number(btn.getAttribute("data-inbox-copy"));
      const items = $("writingInboxList")?._inboxItems || [];
      const item = items.find((x) => Number(x.id) === id);
      if (!item) return;
      try {
        await navigator.clipboard.writeText(item.body_md || item.preview || "");
        toast(i18n.t('app.받은_글_내용을_복사했어요_원고에_붙여_넣으'));
      } catch (_) {
        toast(i18n.t('app.복사에_실패했어요'));
      }
      try {
        await api(`/api/writing/inbox/${id}/read`, { method: "POST", body: "{}" });
        btn.closest(".writing-inbox-item")?.classList.remove("is-unread");
      } catch (_) { /* ignore */ }
    });
    $("toryCheerClose")?.addEventListener("click", () => hideToryCheer());
    document.addEventListener("keydown", (event) => {
      if (event.key !== "Escape" || !modal || modal.classList.contains("hidden")) return;
      if (writingTracker.purgeSelectMode) {
        setWritingLogPurgeSelectMode(false);
        return;
      }
      closeWritingLogModal();
    });
  }

  // 좌클릭: 집필 타이머 시작/정지 · 우클릭: 기록 달력·설정
  // (툴바 1행으로 옮긴 뒤 sceneFeatureBar 위임 클릭이 닿지 않으므로 여기서 직접 연결)
  const logBtn = $("writingLogButton");
  if (logBtn && logBtn.dataset.writingBound !== "1") {
    logBtn.dataset.writingBound = "1";
    logBtn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      toggleWritingRecording();
    });
    logBtn.addEventListener("contextmenu", (event) => {
      event.preventDefault();
      event.stopPropagation();
      setUiFeatureCtxTarget?.(logBtn);
      if (typeof showUiFeatureContextMenu === "function") {
        showUiFeatureContextMenu(event.clientX, event.clientY, logBtn, [
          {
            label: i18n.t('app.기록_달력_설정'),
            hint: i18n.t('app.글쓰기_기록_열기'),
            run: () => { openWritingLogModal("calendar").catch(handleError); },
          },
          {
            label: i18n.t('app.폰_연동'),
            hint: i18n.t('app.연동_코드_핸드폰_기록_포함'),
            run: () => { openWritingLogModal("phone").catch(handleError); },
          },
        ]);
      } else {
        openWritingLogModal().catch(handleError);
      }
    });
  }
  writingTracker.prefs.show_timer = loadShowTimerPref();
  updateWritingLogButtonUi();

  // Track manuscript typing when chars/time auto or 기록 is on
  const onEditorInput = () => noteWritingActivityFromEditor();
  $("sceneContent")?.addEventListener("input", onEditorInput);
  // focus-write / synopsis don't count as "manuscript writing session" for now

  if (!writingTracker.tickTimer) {
    writingTracker.lastTickAt = Date.now();
    writingTracker.tickTimer = window.setInterval(() => {
      writingTick();
    }, 15000);
  }
  if (!writingTracker.flushTimer) {
    writingTracker.flushTimer = window.setInterval(() => {
      flushWritingHeartbeat().catch(() => {});
    }, 60000);
  }
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden") {
      writingTick();
      flushWritingHeartbeat({ force: true }).catch(() => {});
    }
  });
  window.addEventListener("beforeunload", () => {
    writingTick();
    // best-effort sync beacon
    try {
      const chars = writingTracker.pendingChars;
      const active = writingTracker.pendingActive;
      if (chars > 0 || active > 0 || writingTracker.pendingSessionStart) {
        const body = JSON.stringify({
          day: localDayKey(),
          chars_delta: chars,
          active_seconds_delta: active,
          session_start: writingTracker.pendingSessionStart,
          session_started_at: writingTracker.sessionStartedAt,
          last_active_at: new Date().toISOString(),
          project_id: state.projectId || null,
        });
        if (navigator.sendBeacon) {
          const blob = new Blob([body], { type: "application/json" });
          navigator.sendBeacon("/api/writing/heartbeat", blob);
        }
      }
    } catch (_) { /* ignore */ }
  });

  // load prefs + lonely check
  api("/api/writing/prefs")
    .then((prefs) => {
      applyWritingPrefs(prefs);
      return checkLonelyWriter();
    })
    .catch(() => {});
}

