function showBinderContextMenu(clientX, clientY, scene) {
  const menu = $("binderContextMenu");
  if (!menu || !scene?.id) return;
  hideChapterContextMenu();
  hidePartContextMenu();
  hideFolderColorMenu();
  hideDesktopContextMenu();
  hideSettingsContextMenu();
  hideBookmarkContextMenu();
  const title = String(scene.title || i18n.t('app.원고')).trim() || i18n.t('app.원고');
  binderContextScene = {
    id: Number(scene.id),
    title,
    chapterId: scene.chapterId != null ? Number(scene.chapterId) : null,
    parentSceneId: scene.parentSceneId != null && scene.parentSceneId !== ""
      ? Number(scene.parentSceneId)
      : null,
  };
  if ($("binderContextMenuLabel")) {
    $("binderContextMenuLabel").textContent = title.length > 28 ? `${title.slice(0, 28)}…` : title;
  }
  const promoteBtn = menu.querySelector('[data-binder-action="promote"]');
  if (promoteBtn) {
    promoteBtn.classList.toggle("hidden", !binderContextScene.parentSceneId);
  }
  const pinBtn = menu.querySelector('[data-binder-action="pin-top"]');
  if (pinBtn) {
    const pinned = isScenePinned(binderContextScene.id);
    const strong = pinBtn.querySelector("strong");
    const span = pinBtn.querySelector("span");
    if (strong) strong.textContent = pinned ? i18n.t('app.상단_고정_해제') : i18n.t('app.상단_고정');
    if (span) {
      span.textContent = pinned
        ? i18n.t('app.고정_목록에서_빼고_원래_위치로_둬요')
        : i18n.t('app.목차_맨_위에_고정해요');
    }
  }
  const italicBtn = menu.querySelector('[data-binder-action="title-italic"]');
  if (italicBtn) {
    const isChild = Boolean(binderContextScene.parentSceneId);
    italicBtn.classList.toggle("hidden", !isChild);
    if (isChild) {
      const on = isSceneTitleItalic(binderContextScene.id);
      const strong = italicBtn.querySelector("strong");
      const span = italicBtn.querySelector("span");
      if (strong) {
        strong.textContent = on
          ? i18n.t("app.이탤릭_표시_해제")
          : i18n.t("index.이탤릭체로_표시");
      }
      if (span) {
        span.textContent = on
          ? i18n.t("app.목차_제목을_보통_글씨로_돌려요")
          : i18n.t("index.목차에서_제목을_기울여_보여요");
      }
    }
  }
  positionContextMenu(menu, clientX, clientY, 320);
}

function startRenameScene(sceneId) {
  const id = Number(sceneId);
  if (!id) return;
  const btn = document.querySelector(
    `#outline .scene-link[data-scene="${id}"]:not([data-pinned])`,
  ) || document.querySelector(`.scene-link[data-scene="${id}"]`);
  if (!btn) {
    toast(i18n.t('app.회차를_찾지_못했어요'));
    return;
  }
  beginSceneRename(btn).catch(handleError);
}

function isOutlineInlineRenaming() {
  return Boolean(document.querySelector(".scene-rename-input, .chapter-rename-input"));
}

function applySceneLockFromServer(sceneId, payload, extras = {}) {
  const id = Number(sceneId);
  if (!id || !payload || typeof payload !== "object") return;
  const version = payload.row_version;
  const title = extras.title != null ? String(extras.title) : "";
  if (state.scene && Number(state.scene.id) === id) {
    if (version != null) state.scene.row_version = version;
    if (title) {
      state.scene.title = title;
      if ($("sceneTitle")) $("sceneTitle").value = title;
    }
  }
  if (state.splitScene && Number(state.splitScene.id) === id) {
    if (version != null) state.splitScene.row_version = version;
    if (title) {
      state.splitScene.title = title;
      if ($("splitSceneTitleInput")) $("splitSceneTitleInput").value = title;
    }
  }
}

async function beginSceneRename(titleButton) {
  const sceneId = Number(titleButton.dataset.scene);
  if (!sceneId) return;
  const row = titleButton.closest(".scene-row") || titleButton.parentElement;
  if (!row || row.querySelector(".scene-rename-input")) return;
  const titleSpan = titleButton.querySelector(".scene-title");
  const original = (titleSpan?.textContent || titleButton.textContent || "").trim();
  const input = document.createElement("input");
  input.type = "text";
  input.className = "chapter-rename-input scene-rename-input";
  input.value = original;
  input.setAttribute("aria-label", i18n.t('app.회차_이름_수정'));
  input.maxLength = 200;
  titleButton.replaceWith(input);
  try { input.scrollIntoView({ block: "nearest", inline: "nearest" }); } catch (_) { /* ignore */ }
  input.focus();
  input.select();
  let finished = false;
  const finish = async (save) => {
    if (finished) return;
    finished = true;
    const nextTitle = input.value.trim();
    if (!save || !nextTitle || nextTitle === original) {
      await loadProject();
      return;
    }
    try {
      const saved = await api(`/api/scenes/${sceneId}`, {
        method: "PUT",
        body: JSON.stringify({ title: nextTitle }),
      });
      applySceneLockFromServer(sceneId, saved, { title: nextTitle });
      await loadProject();
      toast(i18n.t('app.회차_이름을_바꿨어요'));
    } catch (error) {
      await loadProject();
      throw error;
    }
  };
  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      finish(true).catch(handleError);
    } else if (event.key === "Escape") {
      event.preventDefault();
      finish(false).catch(handleError);
    }
  });
  input.addEventListener("blur", () => finish(true).catch(handleError));
  input.addEventListener("mousedown", (event) => event.stopPropagation());
  input.addEventListener("click", (event) => event.stopPropagation());
}

async function trashChapter(chapterId, chapterTitle = "") {
  const id = Number(chapterId);
  if (!Number.isFinite(id) || id <= 0) {
    toast(i18n.t('app.폴더를_찾지_못했어요'));
    return;
  }
  const chapter = (state.outline || []).find((c) => Number(c.id) === id);
  // Strip UI suffixes from title attribute (e.g. " · 완결 (우클릭…)")
  let label = String(chapterTitle || chapter?.title || i18n.t('app.이_폴더')).trim() || i18n.t('app.이_폴더');
  label = label
    .replace(/\s*·\s*완결.*$/u, "")
    .replace(/\s*·\s*챕터 완결.*$/u, "")
    .replace(/\s*\(우클릭.*$/u, "")
    .replace(/\s*\(더블클릭.*$/u, "")
    .trim() || i18n.t('app.이_폴더');
  const sceneIds = flattenChapterScenes(chapter).map((s) => Number(s.id)).filter((n) => n > 0);
  const sceneCount = sceneIds.length;
  const ok = window.confirm(
    sceneCount > 0
      ? i18n.t('app.label_폴더와_안의_회차_sceneCo', { label, sceneCount })
      : i18n.t('app.label_폴더를_휴지통에_버리시겠습니까', { label }),
  );
  if (!ok) return;

  // If an open scene lives in this chapter, flush then clear
  const openSceneId = Number(state.sceneId);
  const openInChapter = sceneIds.includes(openSceneId);
  if (openInChapter && sceneDirty && openSceneId) {
    try {
      await persistScene({ quiet: true, saveNote: i18n.t('app.폴더_버리기_전_저장') });
    } catch (_) { /* still trash */ }
  }

  let result;
  try {
    result = await api(`/api/chapters/${id}/trash`, {
      method: "POST",
      body: JSON.stringify({}),
    });
    noteFolderUndoAvailable();
  } catch (error) {
    const msg = String(error?.message || error || "");
    if (/알 수 없는 요청|404/i.test(msg) || Number(error?.status) === 404) {
      throw new Error(
        i18n.t('app.폴더_버리기_API를_찾을_수_없습니다_Su'),
      );
    }
    throw error;
  }

  if (openInChapter) {
    state.sceneId = null;
    state.scene = null;
    sceneDirty = false;
    if (openSceneId) {
      try { removeEpisodeTab?.(openSceneId); } catch (_) { /* ignore */ }
    }
  }
  // Drop episode tabs for trashed scenes
  if (Array.isArray(state.episodeTabs) && sceneIds.length) {
    const drop = new Set(sceneIds);
    state.episodeTabs = state.episodeTabs.filter((t) => !drop.has(Number(t.sceneId)));
    try { renderEpisodeChrome?.(); } catch (_) { /* ignore */ }
  }
  if (state.splitSceneId && sceneIds.includes(Number(state.splitSceneId))) {
    try { await closeSplitView(); } catch (_) { /* ignore */ }
  }
  if (state.toryFocusSceneId && sceneIds.includes(Number(state.toryFocusSceneId))) {
    clearToryFocus({ silent: true });
  }

  // Optimistic binder update so the folder disappears even if a full reload lags
  if (Array.isArray(state.outline)) {
    state.outline = state.outline.filter((c) => Number(c.id) !== id);
    try { renderOutline(state.outline); } catch (_) { /* ignore */ }
  }

  await loadProject();
  if (openInChapter) showWelcome();
  const n = Number(result?.scene_count ?? sceneCount ?? 0);
  toast(n > 0
    ? `${i18n.t('app.label_폴더와_회차_n_개를_휴지통으로', {label: label, n: n})}`
    : `${i18n.t('app.label_폴더를_휴지통으로_옮겼어요', {label: label})}`);
  if (!$("adminModal")?.classList.contains("hidden")) {
    loadTrashList().catch(handleError);
  }
}

