function filenameFromContentDisposition(header, fallback) {
  const raw = String(header || "");
  const star = raw.match(/filename\*\s*=\s*UTF-8''([^;]+)/i);
  if (star) {
    try {
      return decodeURIComponent(star[1].trim());
    } catch (_) { /* fall through */ }
  }
  const quoted = raw.match(/filename\s*=\s*"([^"]+)"/i);
  if (quoted) return quoted[1];
  return fallback;
}

async function exportTypesetFile(formatKey = "docx") {
  hideTypesetExportMenu();
  const format = String(formatKey || "docx").trim().toLowerCase() === "hwpx" ? "hwpx" : "docx";
  if (!state.sceneId) {
    toast(i18n.t("app.먼저_목차에서_씬_하나를_열어_주세요"));
    return;
  }
  if (sceneDirty && state.sceneId) {
    try {
      await persistScene({ quiet: true, saveNote: i18n.t("app.내보내기_전_저장") });
    } catch (_) { /* still try export */ }
  }
  const saveToFolder = exportPrefs?.save_to_folder !== false;
  const exportDir = String(exportPrefs?.export_dir || "").trim();
  const body = {
    chapter_id: Number(state.sceneId),
    platform_id: normalizeTypesetPlatform(viewerSettings.typesetPlatform),
    format,
    save_to_folder: saveToFolder,
    export_dir: exportDir,
    reveal_after_save: exportPrefs?.reveal_after_save !== false,
  };
  const response = await fetch("/api/typeset/export", {
    method: "POST",
    credentials: "same-origin",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!response.ok) {
    let message = i18n.t("app.내보내기에_실패했습니다");
    try {
      const err = await response.json();
      if (err?.error) message = err.error;
    } catch (_) { /* ignore */ }
    throw new Error(message);
  }
  const contentType = (response.headers.get("Content-Type") || "").toLowerCase();
  if (saveToFolder || contentType.includes("application/json")) {
    const result = await response.json();
    if (!result?.ok && !result?.path) {
      throw new Error(result?.error || i18n.t("app.폴더에_저장하지_못했어요"));
    }
    const savedPath = result.path || result.filename || "";
    toast(i18n.t("app.선택한_회차를_저장했어요_savedPath", { savedPath }));
    return;
  }
  const buffer = await response.arrayBuffer();
  const mime = format === "hwpx"
    ? "application/hwp+zip"
    : "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
  const blob = new Blob([buffer], { type: mime });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filenameFromContentDisposition(
    response.headers.get("Content-Disposition"),
    format === "hwpx" ? "typeset.hwpx" : "typeset.docx",
  );
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}
let viewerResize = null;
/** Paper-book page-turn state (0-based spread index). */
let bookSpreadIndex = 0;
let bookSpreadCount = 1;
let bookPageLayoutTimer = null;
/** Paginated leaf HTML (one entry per half-page). */
let bookPages = [];
let bookPageMetrics = { m: 36, fontPx: 15, lineHeight: 1.8 };
/** True while a 3D page-flip animation is running. */
let bookFlipBusy = false;
let bookFlipTimer = null;
const BOOK_FLIP_MS = 720;
/** Viewer manuscript scope: "scene" | "full" */
let viewerScope = "scene";
let viewerTocOpen = false;
let viewerCommentsOpen = false;
let viewerCommentsPollTimer = null;
let viewerCommentsLoadToken = 0;
/** sceneId → normalized HTML (other scenes only; current always from editor) */
const viewerEpisodeCache = new Map();
let viewerLoadToken = 0;
/** Eager-load all episodes below this count; progressive batches above it. */
const VIEWER_FULL_EAGER_MAX = 100;
const VIEWER_FULL_BATCH_SIZE = 8;
const VIEWER_EPISODE_BREAK = `<div class="viewer-episode-break" aria-hidden="true"></div>`;
/** After book re-layout, jump to this scene id if set */
let viewerPendingJumpSceneId = null;
/** PDF / phone / e-ink discrete pages (HTML per leaf). */
let devicePages = [];
let devicePageIndex = 0;
let devicePageCount = 1;
let devicePageLayoutTimer = null;
let devicePageMetrics = { padY: 24, padX: 24, fontPx: 14, lineHeight: 1.8 };
/** When true, ignore scroll→index sync (programmatic jump). */
let devicePageScrollLock = false;
/** Cancels in-flight incremental page layout (independent of HTML fetch token). */
let viewerPageLayoutToken = 0;
/** Document-order slots: { sceneId, html, pages: string[]|null }. */
let viewerEpisodePageSlots = [];
let viewerPageMetricsKey = "";
/** Keep the on-screen scene/page while earlier episodes are prepended. */
let viewerViewAnchor = null;

function isViewerOpen() {
  return Boolean($("viewerModal") && !$("viewerModal").classList.contains("hidden"));
}

function clearViewerEpisodeCache() {
  viewerEpisodeCache.clear();
}

function normalizeViewerHtml(raw) {
  const text = raw == null ? "" : String(raw);
  if (!text.trim()) return "";
  const stripped = stripAuthorNoteHtml(stripFindHitMarkup(text));
  if (looksLikeHtml(stripped)) return sanitizeEditorHtml(stripped);
  return escapeHtml(stripped).replace(/\r\n|\r|\n/g, "<br>");
}

function getViewerEpisodeLabel(ep) {
  if (!ep) return i18n.t('app.본문');
  return formatEpisodeNavLabel(ep, ep.label || ep.shortLabel || `${i18n.t('app.ep_index_화_3', {'ep.index || ""': ep.index || ""})}`);
}

function wrapViewerEpisode(ep, bodyHtml, { showTitle = true } = {}) {
  const id = Number(ep?.sceneId) || 0;
  const title = escapeHtml(getViewerEpisodeLabel(ep));
  const titleBlock = showTitle
    ? `<h2 class="viewer-episode-title" data-viewer-scene="${id}" id="viewer-episode-${id}">${title}</h2>`
    : `<span class="viewer-episode-anchor" data-viewer-scene="${id}" id="viewer-episode-${id}" hidden></span>`;
  const body = (bodyHtml && String(bodyHtml).trim())
    ? bodyHtml
    : i18n.t('app.p_class_viewer_empty_sc');
  return `<section class="viewer-episode" data-viewer-scene="${id}">${titleBlock}<div class="viewer-episode-body">${body}</div></section>`;
}

let viewerPerf = null;

function resetViewerPerf() {
  viewerPerf = {
    fetchMs: 0,
    fetchN: 0,
    netN: 0,
    cacheN: 0,
    liveEditorN: 0,
    paginateMs: 0,
    overflowChecks: 0,
    pages: 0,
    htmlChars: 0,
    layoutName: "",
    mode: "",
    layoutDone: false,
  };
  try { window.__viewerPerf = viewerPerf; } catch (_) { /* ignore */ }
}

function publishViewerPerf() {
  try { window.__viewerPerf = viewerPerf; } catch (_) { /* ignore */ }
}

async function fetchViewerEpisodeHtml(sceneId) {
  const id = Number(sceneId);
  if (!Number.isFinite(id) || id <= 0) return "";
  // Always use live editor for the open scene (unsaved edits included).
  if (id === Number(state.sceneId)) {
    if (viewerPerf) viewerPerf.liveEditorN += 1;
    return normalizeViewerHtml(getEditorContent() || $("sceneContent")?.innerHTML || "");
  }
  if (viewerEpisodeCache.has(id)) {
    if (viewerPerf) viewerPerf.cacheN += 1;
    return viewerEpisodeCache.get(id);
  }
  if (viewerPerf) viewerPerf.netN += 1;
  const detail = await api(`/api/scenes/${id}`);
  const html = normalizeViewerHtml(detail?.content_md || "");
  viewerEpisodeCache.set(id, html);
  return html;
}

async function fetchWrappedEpisode(ep, { showTitle = true } = {}) {
  try {
    const html = await fetchViewerEpisodeHtml(ep.sceneId);
    return wrapViewerEpisode(ep, html, { showTitle });
  } catch (_) {
    return wrapViewerEpisode(ep, i18n.t('app.p_class_viewer_empty_sc_2'), { showTitle });
  }
}

async function fetchEpisodeParts(episodes, { showTitle = true } = {}) {
  const list = episodes || [];
  console.time("viewer:fetchEpisodeParts");
  const t0 = performance.now();
  try {
    return await Promise.all(list.map((ep) => fetchWrappedEpisode(ep, { showTitle })));
  } finally {
    const ms = performance.now() - t0;
    console.timeEnd("viewer:fetchEpisodeParts");
    if (viewerPerf) {
      viewerPerf.fetchMs += ms;
      viewerPerf.fetchN += list.length;
      publishViewerPerf();
    }
  }
}

function joinViewerEpisodeParts(parts) {
  return (parts || []).filter(Boolean).join(VIEWER_EPISODE_BREAK);
}

function isCurrentViewerLoad(token) {
  return token === viewerLoadToken && isViewerOpen() && viewerScope === "full";
}

function yieldViewerFullLoad() {
  return new Promise((resolve) => {
    if (typeof requestIdleCallback === "function") {
      requestIdleCallback(() => resolve(), { timeout: 120 });
    } else {
      setTimeout(resolve, 16);
    }
  });
}

function scheduleViewerFullRelayout({ jumpId = null, resetBook = false } = {}) {
  if (jumpId) viewerPendingJumpSceneId = jumpId;
  const mode = viewerSettings.mode;
  if (mode === "book") {
    scheduleBookPageLayout({ resetPage: resetBook && !jumpId });
  } else if (mode === "pdf" || mode === "phone" || mode === "eink") {
    if (jumpId) viewerPendingJumpSceneId = jumpId;
    scheduleDevicePageLayout({ resetPage: resetBook && !jumpId });
  } else if (jumpId) {
    requestAnimationFrame(() => jumpViewerToScene(jumpId));
  }
}

async function buildViewerBodyHtml(scope) {
  const sequence = getEpisodeSequence();
  if (scope !== "full") {
    const ep = sequence.find((e) => Number(e.sceneId) === Number(state.sceneId))
      || {
        sceneId: Number(state.sceneId),
        index: 1,
        label: $("sceneTitle")?.value?.trim() || state.scene?.title || i18n.t('app.본문'),
        shortLabel: $("sceneTitle")?.value?.trim() || state.scene?.title || i18n.t('app.본문'),
      };
    const html = normalizeViewerHtml(getEditorContent() || $("sceneContent")?.innerHTML || "");
    return wrapViewerEpisode(ep, html, { showTitle: false });
  }
  if (!sequence.length) {
    return i18n.t('app.p_class_hint_목차에_회차가_없습');
  }
  const parts = await fetchEpisodeParts(sequence, { showTitle: true });
  return joinViewerEpisodeParts(parts);
}

function syncViewerScopeTabs() {
  const scope = viewerScope === "full" ? "full" : "scene";
  viewerScope = scope;
  document.querySelectorAll("#viewerScopeTabs [data-viewer-scope]").forEach((btn) => {
    const on = btn.dataset.viewerScope === scope;
    btn.classList.toggle("is-active", on);
    btn.setAttribute("aria-pressed", on ? "true" : "false");
  });
}

function setViewerTocOpen(open) {
  viewerTocOpen = Boolean(open);
  if (viewerTocOpen && viewerCommentsOpen) {
    viewerCommentsOpen = false;
    applyViewerCommentsPanelVisibility();
    stopViewerCommentsPolling();
  }
  const panel = $("viewerTocPanel");
  const toggle = $("viewerTocToggle");
  if (panel) panel.classList.toggle("hidden", !viewerTocOpen);
  if (toggle) {
    toggle.setAttribute("aria-expanded", viewerTocOpen ? "true" : "false");
    toggle.classList.toggle("is-active", viewerTocOpen);
  }
}

function applyViewerCommentsPanelVisibility() {
  const panel = $("viewerReaderCommentsPanel");
  const toggle = $("viewerReaderCommentsButton");
  if (panel) panel.classList.toggle("hidden", !viewerCommentsOpen);
  if (toggle) {
    toggle.setAttribute("aria-expanded", viewerCommentsOpen ? "true" : "false");
    toggle.classList.toggle("is-active", viewerCommentsOpen);
  }
}

function stopViewerCommentsPolling() {
  if (viewerCommentsPollTimer) {
    clearInterval(viewerCommentsPollTimer);
    viewerCommentsPollTimer = null;
  }
}

function startViewerCommentsPolling(sceneId) {
  const id = Number(sceneId);
  stopViewerCommentsPolling();
  if (!id) return;
  viewerCommentsPollTimer = setInterval(() => {
    if (!viewerCommentsOpen) {
      stopViewerCommentsPolling();
      return;
    }
    if (Number(state.sceneId) !== id) {
      stopViewerCommentsPolling();
      return;
    }
    loadViewerReaderComments({ startIfNeeded: false }).catch(() => {});
  }, 3000);
}

function setViewerCommentsOpen(open) {
  viewerCommentsOpen = Boolean(open);
  if (viewerCommentsOpen && viewerTocOpen) {
    setViewerTocOpen(false);
  }
  applyViewerCommentsPanelVisibility();
  if (!viewerCommentsOpen) stopViewerCommentsPolling();
}

function viewerCommentsQuotaExhausted(data) {
  return String(data?.last_error_code || "") === "quota";
}

function viewerCommentsQuotaMessage() {
  return i18n.t("app.오늘_AI_사용량을_다_썼어요_내일_다시_시도");
}

function syncViewerCommentsRetryRow(data) {
  const row = $("viewerReaderCommentsRetryRow");
  const btn = $("viewerReaderCommentsRetryButton");
  const hint = $("viewerReaderCommentsRetryHint");
  if (!row || !btn) return;
  const comments = Array.isArray(data?.comments) ? data.comments : [];
  const generating = Boolean(data?.generating);
  const expected = Math.max(1, Number(data?.expected) || 3);
  const ready = comments.length;
  const quota = viewerCommentsQuotaExhausted(data);
  const showRetry = !generating && ready === 0 && !quota;
  const showFill = !generating && ready > 0 && ready < expected && !quota;
  const showQuota = quota && !generating && ready < expected;
  row.classList.toggle("hidden", !(showRetry || showFill || showQuota));
  if (hint) {
    hint.classList.toggle("hidden", !(showRetry || showQuota));
    if (showQuota) hint.textContent = viewerCommentsQuotaMessage();
    else if (showRetry) hint.textContent = i18n.t("app.댓글_생성에_실패했어요");
  }
  if (showQuota) {
    btn.disabled = true;
    btn.classList.add("hidden");
    return;
  }
  btn.classList.remove("hidden");
  btn.disabled = generating;
  if (showRetry) btn.textContent = i18n.t("app.다시_시도");
  else if (showFill) btn.textContent = i18n.t("app.댓글을_더_받아볼게요");
}

function syncViewerCommentsRefreshRow(data) {
  const row = $("viewerReaderCommentsRefreshRow");
  const btn = $("viewerReaderCommentsRefreshButton");
  const note = $("viewerReaderCommentsRefreshNote");
  if (!row || !btn || !note) return;
  const comments = Array.isArray(data?.comments) ? data.comments : [];
  const generating = Boolean(data?.generating);
  const canRefresh = Boolean(data?.can_refresh);
  const ready = comments.length;
  const quota = viewerCommentsQuotaExhausted(data);
  const showRow = ready >= 3 || (generating && ready > 0);
  row.classList.toggle("hidden", !showRow);
  const exhausted = showRow && !generating && !canRefresh;
  if (quota && !generating && showRow) {
    btn.disabled = true;
    btn.classList.add("hidden");
    note.classList.remove("hidden");
    note.textContent = viewerCommentsQuotaMessage();
    return;
  }
  note.textContent = i18n.t("app.댓글은_여기까지예요");
  if (exhausted) {
    btn.disabled = true;
    btn.classList.add("hidden");
    note.classList.remove("hidden");
  } else {
    note.classList.add("hidden");
    btn.classList.remove("hidden");
    btn.disabled = !canRefresh || generating;
  }
}

function renderViewerReaderComments(data) {
  const list = $("viewerReaderCommentsList");
  const hint = $("viewerReaderCommentsHint");
  if (!list) return;
  const comments = Array.isArray(data?.comments) ? data.comments : [];
  const expected = Math.max(1, Number(data?.expected) || 3);
  const generating = Boolean(data?.generating);
  const ready = comments.length;
  if (hint) {
    if (generating) {
      hint.textContent = ready >= expected
        ? i18n.t("app.가상독자_추가_댓글을_준비하는_중")
        : (ready
          ? i18n.t("app.가상독자_댓글_생성_중", { ready, expected })
          : i18n.t("app.가상독자_댓글을_준비하는_중"));
    } else if (!ready) {
      hint.textContent = viewerCommentsQuotaExhausted(data)
        ? viewerCommentsQuotaMessage()
        : i18n.t("app.댓글_생성에_실패했어요");
    } else {
      hint.textContent = "";
    }
  }
  const cards = comments.map((item) => {
    const personaId = String(item.persona_id || "").trim();
    const name = String(item.persona_name || "").trim() || i18n.t("app.가상_독자");
    const body = escapeHtml(item.comment_text || "").replace(/\r\n|\r|\n/g, "<br>");
    return `<div class="viewer-comment-card">`
      + readerAvatarMarkup(personaId, name, "reader-chat-msg-avatar")
      + `<div class="viewer-comment-card-body">`
      + `<span class="viewer-comment-card-name">${escapeHtml(name)}</span>`
      + `<div class="viewer-comment-card-text">${body}</div>`
      + `</div></div>`;
  });
  if (generating) {
    cards.push(
      `<div class="viewer-comment-pending">${
        ready >= expected
          ? i18n.t("app.가상독자_추가_댓글을_준비하는_중")
          : i18n.t("app.가상독자_댓글_생성_중", { ready, expected })
      }</div>`,
    );
  }
  list.innerHTML = cards.join("");
  bindReaderAvatarErrors(list);
  syncViewerCommentsRetryRow(data);
  syncViewerCommentsRefreshRow(data);
}

async function loadViewerReaderComments(options = {}) {
  if (!assertClusterFeature("reader_comments", { quiet: !options.startIfNeeded })) return;
  const sceneId = Number(state.sceneId);
  if (!sceneId) return null;
  const token = ++viewerCommentsLoadToken;
  let data = await api(`/api/scenes/${sceneId}/reader-comments`);
  if (
    options.startIfNeeded
    && !data?.generating
    && !(data?.comments || []).length
    && String(data?.last_error_code || "") !== "quota"
  ) {
    try {
      await api(`/api/scenes/${sceneId}/reader-comments/generate`, {
        method: "POST",
        body: JSON.stringify({}),
      });
    } catch (_) { /* GET still shows whatever is stored */ }
    if (token !== viewerCommentsLoadToken) return data;
    data = await api(`/api/scenes/${sceneId}/reader-comments`);
  }
  if (token !== viewerCommentsLoadToken) return data;
  renderViewerReaderComments(data);
  const generating = Boolean(data?.generating);
  if (generating && viewerCommentsOpen && Number(state.sceneId) === sceneId) {
    if (!viewerCommentsPollTimer) startViewerCommentsPolling(sceneId);
  } else {
    stopViewerCommentsPolling();
  }
  return data;
}

async function refreshViewerReaderComments() {
  const sceneId = Number(state.sceneId);
  if (!sceneId) return;
  const refreshBtn = $("viewerReaderCommentsRefreshButton");
  const retryBtn = $("viewerReaderCommentsRetryButton");
  if (refreshBtn) refreshBtn.disabled = true;
  if (retryBtn) retryBtn.disabled = true;
  try {
    await api(`/api/scenes/${sceneId}/reader-comments/generate`, {
      method: "POST",
      body: JSON.stringify({}),
    });
  } catch (error) {
    const code = String(error?.message || "");
    if (code === "max_refreshes_reached" || code === "no_more_personas") {
      const data = await api(`/api/scenes/${sceneId}/reader-comments`).catch(() => null);
      if (data) renderViewerReaderComments(data);
      else syncViewerCommentsRefreshRow({ comments: [{}, {}, {}], can_refresh: false, generating: false });
      return;
    }
    if (refreshBtn) refreshBtn.disabled = false;
    if (retryBtn) retryBtn.disabled = false;
    handleError(error);
    return;
  }
  await loadViewerReaderComments({ startIfNeeded: false });
}

function openViewerReaderCommentsFromCta() {
  if (!assertClusterFeature("reader_comments")) return;
  hideToast();
  markReaderCommentsStarted();
  if (typeof isViewerOpen === "function" && !isViewerOpen() && typeof openViewerMode === "function") {
    openViewerMode();
  }
  setViewerCommentsOpen(true);
  loadViewerReaderComments({ startIfNeeded: true }).catch(handleError);
}

function renderViewerToc() {
  const list = $("viewerTocList");
  const hint = $("viewerTocHint");
  if (!list) return;
  const sequence = getEpisodeSequence();
  const currentId = Number(state.sceneId) || 0;
  if (!sequence.length) {
    list.innerHTML = i18n.t('app.p_class_hint_style_padd');
    if (hint) hint.textContent = i18n.t('app.회차를_누르면_이동합니다');
    return;
  }
  if (hint) {
    hint.textContent = viewerScope === "full"
      ? i18n.t('app.회차를_누르면_해당_위치로_이동합니다')
      : i18n.t('app.다른_회차_선택_시_전체_원고로_전환됩니다');
  }
  list.innerHTML = sequence.map((ep) => {
    const isCurrent = Number(ep.sceneId) === currentId;
    const label = escapeHtml(getViewerEpisodeLabel(ep));
    return `
      <button type="button" class="viewer-toc-item${isCurrent ? " is-current" : ""}"
        data-viewer-toc-scene="${ep.sceneId}" title="${label}">
        <span class="viewer-toc-index">${ep.index}</span>
        <span class="viewer-toc-label">${label}</span>
      </button>`;
  }).join("");
}

function highlightViewerTocCurrent(sceneId = null) {
  const id = sceneId != null ? Number(sceneId) : Number(state.sceneId);
  document.querySelectorAll("#viewerTocList .viewer-toc-item").forEach((btn) => {
    btn.classList.toggle("is-current", Number(btn.dataset.viewerTocScene) === id);
  });
}

function findBookSpreadIndexForScene(sceneId) {
  const id = Number(sceneId);
  if (!Number.isFinite(id) || id <= 0) return -1;
  // Prefer scanning paginated HTML (works even mid-flip / after layout).
  for (let i = 0; i < bookPages.length; i += 1) {
    const html = bookPages[i] || "";
    if (
      html.includes(`data-viewer-scene="${id}"`)
      || html.includes(`id="viewer-episode-${id}"`)
    ) {
      return Math.floor(i / 2);
    }
  }
  const track = $("bookTrack");
  if (!track) return -1;
  const spreads = track.querySelectorAll(".book-base, .book-flip-leaf");
  for (let i = 0; i < spreads.length; i += 1) {
    if (spreads[i].querySelector(`[data-viewer-scene="${id}"]`)) {
      return bookSpreadIndex;
    }
  }
  return -1;
}

function findDevicePageIndexForScene(sceneId) {
  const id = Number(sceneId);
  if (!Number.isFinite(id) || id <= 0) return -1;
  for (let i = 0; i < devicePages.length; i += 1) {
    const html = devicePages[i] || "";
    if (
      html.includes(`data-viewer-scene="${id}"`)
      || html.includes(`id="viewer-episode-${id}"`)
    ) {
      return i;
    }
  }
  return -1;
}

function jumpViewerToScene(sceneId) {
  const id = Number(sceneId);
  if (!Number.isFinite(id) || id <= 0) return;
  highlightViewerTocCurrent(id);

  const mode = viewerSettings.mode;
  if (mode === "book") {
    const leaf = findDevicePageIndexForScene(id);
    if (leaf >= 0) {
      devicePageIndex = leaf;
      setViewerViewAnchor(id, viewerSceneAtPageIndex(leaf)?.pageInEpisode || 0);
      showBookSpreadInstant(Math.floor(leaf / 2));
      return;
    }
    viewerPendingJumpSceneId = id;
    setViewerViewAnchor(id, 0);
    scheduleBookPageLayout({ resetPage: false });
    return;
  }

  // phone/eink/typeset continuous scroll: jump inside viewerBody
  if (mode === "typeset" || ((mode === "phone" || mode === "eink") && isDeviceScrollFlow(mode))) {
    const body = $("viewerBody");
    const el = body?.querySelector(`#viewer-episode-${id}`)
      || body?.querySelector(`[data-viewer-scene="${id}"]`);
    if (el) {
      try {
        el.scrollIntoView({ behavior: "smooth", block: "start" });
      } catch (_) {
        el.scrollIntoView(true);
      }
      updateDevicePagerUi();
      return;
    }
  }

  if (mode === "pdf" || ((mode === "phone" || mode === "eink") && isDevicePagedMode(mode))) {
    const idx = findDevicePageIndexForScene(id);
    if (idx >= 0) {
      setViewerViewAnchor(id, viewerSceneAtPageIndex(idx)?.pageInEpisode || 0);
      showDevicePage(idx, { smooth: true });
      return;
    }
    viewerPendingJumpSceneId = id;
    setViewerViewAnchor(id, 0);
    scheduleDevicePageLayout({ resetPage: false });
    return;
  }

  const body = $("viewerBody");
  const el = body?.querySelector(`#viewer-episode-${id}`)
    || body?.querySelector(`[data-viewer-scene="${id}"]`);
  if (!el) return;
  try {
    el.scrollIntoView({ behavior: "smooth", block: "start" });
  } catch (_) {
    el.scrollIntoView(true);
  }
}

async function paintViewerBody(html, { token, jumpId = null, resetBook = false, titleN = 0 } = {}) {
  const body = $("viewerBody");
  if (!body || token !== viewerLoadToken || !isViewerOpen()) return false;
  body.innerHTML = html;
  body.setAttribute("contenteditable", "false");
  if (viewerSettings.mode === "typeset") applyTypesetBodyStyles();
  else applyEditorWideLineHeight(getStoredLineHeight(), [body]);
  if (viewerScope === "full") {
    if ($("viewerTitle")) {
      $("viewerTitle").textContent = titleN
        ? `${i18n.t('app.뷰어_전체_원고_n_화', { n: titleN })}`
        : i18n.t('app.뷰어_전체_원고');
    }
  } else {
    const title = $("sceneTitle")?.value?.trim() || state.scene?.title || i18n.t('app.본문');
    if ($("viewerTitle")) $("viewerTitle").textContent = `${i18n.t('app.뷰어_title', { title: title })}`;
  }
  renderViewerToc();
  scheduleViewerFullRelayout({ jumpId, resetBook });
  return true;
}

async function applyViewerFullContentProgressive({ token, jumpToSceneId }) {
  const body = $("viewerBody");
  const sequence = getEpisodeSequence();
  if (!body) return;
  if (!sequence.length) {
    await paintViewerBody(i18n.t('app.p_class_hint_목차에_회차가_없습'), { token, resetBook: true });
    return;
  }

  const wanted = Number(jumpToSceneId) || Number(state.sceneId) || 0;
  let startIndex = sequence.findIndex((ep) => Number(ep.sceneId) === wanted);
  if (startIndex < 0) startIndex = 0;
  const jumpId = Number(sequence[startIndex].sceneId);
  const total = sequence.length;

  let firstHtml;
  try {
    firstHtml = await fetchWrappedEpisode(sequence[startIndex], { showTitle: true });
  } catch (error) {
    if (!isCurrentViewerLoad(token)) return;
    handleError(error);
    body.innerHTML = i18n.t('app.p_class_hint_원고를_불러오지_못');
    return;
  }
  if (!isCurrentViewerLoad(token)) return;
  await paintViewerBody(firstHtml, { token, jumpId, resetBook: false, titleN: total });
  if ($("viewerTocHint")) $("viewerTocHint").textContent = i18n.t('app.불러오는_중');

  let loadedFrom = startIndex;
  let loadedTo = startIndex;

  const appendBatch = async (episodes) => {
    const parts = await fetchEpisodeParts(episodes, { showTitle: true });
    if (!isCurrentViewerLoad(token) || !body.isConnected) return false;
    const chunk = joinViewerEpisodeParts(parts);
    if (!chunk) return false;
    body.insertAdjacentHTML("beforeend", VIEWER_EPISODE_BREAK + chunk);
    scheduleViewerFullRelayout({ jumpId: 0, resetBook: false });
    if ($("viewerTocHint")) $("viewerTocHint").textContent = i18n.t('app.불러오는_중');
    return true;
  };

  const prependBatch = async (episodes) => {
    const parts = await fetchEpisodeParts(episodes, { showTitle: true });
    if (!isCurrentViewerLoad(token) || !body.isConnected) return false;
    const chunk = joinViewerEpisodeParts(parts);
    if (!chunk) return false;
    body.insertAdjacentHTML("afterbegin", chunk + VIEWER_EPISODE_BREAK);
    scheduleViewerFullRelayout({ jumpId, resetBook: false });
    if ($("viewerTocHint")) $("viewerTocHint").textContent = i18n.t('app.불러오는_중');
    return true;
  };

  while (loadedTo < total - 1) {
    await yieldViewerFullLoad();
    if (!isCurrentViewerLoad(token)) return;
    const next = sequence.slice(loadedTo + 1, loadedTo + 1 + VIEWER_FULL_BATCH_SIZE);
    if (!next.length) break;
    await appendBatch(next);
    loadedTo += next.length;
  }

  while (loadedFrom > 0) {
    await yieldViewerFullLoad();
    if (!isCurrentViewerLoad(token)) return;
    const from = Math.max(0, loadedFrom - VIEWER_FULL_BATCH_SIZE);
    const prev = sequence.slice(from, loadedFrom);
    if (!prev.length) break;
    await prependBatch(prev);
    loadedFrom = from;
  }

  if (!isCurrentViewerLoad(token)) return;
  if ($("viewerTocHint")) {
    $("viewerTocHint").textContent = i18n.t('app.회차를_누르면_해당_위치로_이동합니다');
  }
}

async function applyViewerContent({ resetBook = true, jumpToSceneId = null } = {}) {
  const body = $("viewerBody");
  if (!body || !isViewerOpen()) return;
  if (bookPageLayoutTimer) {
    window.clearTimeout(bookPageLayoutTimer);
    bookPageLayoutTimer = null;
  }
  if (devicePageLayoutTimer) {
    window.clearTimeout(devicePageLayoutTimer);
    devicePageLayoutTimer = null;
  }
  viewerPageLayoutToken += 1;
  resetViewerPerf();
  const token = ++viewerLoadToken;
  const scope = viewerScope === "full" ? "full" : "scene";
  viewerScope = scope;
  syncViewerScopeTabs();

  if (scope === "full") {
    body.innerHTML = i18n.t('app.p_class_hint_전체_원고를_불러오');
    if ($("viewerTitle")) $("viewerTitle").textContent = i18n.t('app.뷰어_전체_원고');
    if ($("viewerTocHint")) $("viewerTocHint").textContent = i18n.t('app.불러오는_중');
    const sequence = getEpisodeSequence();
    if (sequence.length > VIEWER_FULL_EAGER_MAX) {
      await applyViewerFullContentProgressive({ token, jumpToSceneId });
      return;
    }
  }

  let html;
  try {
    html = await buildViewerBodyHtml(scope);
  } catch (error) {
    if (token !== viewerLoadToken) return;
    handleError(error);
    body.innerHTML = i18n.t('app.p_class_hint_원고를_불러오지_못');
    return;
  }
  if (token !== viewerLoadToken || !isViewerOpen()) return;

  const jumpId = jumpToSceneId != null ? Number(jumpToSceneId) : null;
  const titleN = scope === "full" ? getEpisodeSequence().length : 0;
  const painted = await paintViewerBody(html, { token, jumpId, resetBook: resetBook && !jumpId, titleN });
  if (!painted) return;

  if (scope !== "full" && !jumpId && resetBook) {
    const stage = $("viewerStage");
    const scroll = $("viewerScroll");
    if (stage) stage.scrollTop = 0;
    if (scroll) scroll.scrollTop = 0;
  }

  if (scope === "full" && $("viewerTocHint")) {
    $("viewerTocHint").textContent = i18n.t('app.회차를_누르면_해당_위치로_이동합니다');
  }
}

async function setViewerScope(scope, { jumpToSceneId = null } = {}) {
  const next = scope === "full" ? "full" : "scene";
  viewerScope = next;
  syncViewerScopeTabs();
  // Opening full manuscript: show TOC and refresh episode cache for latest saved text.
  if (next === "full") {
    clearViewerEpisodeCache();
    if (!viewerTocOpen) setViewerTocOpen(true);
  }
  await applyViewerContent({
    resetBook: true,
    jumpToSceneId: jumpToSceneId != null ? jumpToSceneId : null,
  });
}

async function onViewerTocSelect(sceneId) {
  const id = Number(sceneId);
  if (!Number.isFinite(id) || id <= 0) return;
  if (viewerScope !== "full") {
    // Jump only works across episodes in full manuscript; switch scope then jump.
    await setViewerScope("full", { jumpToSceneId: id });
    return;
  }
  const body = $("viewerBody");
  const alreadyLoaded = Boolean(
    body?.querySelector(`#viewer-episode-${id}`)
    || body?.querySelector(`[data-viewer-scene="${id}"]`)
  );
  if (!alreadyLoaded && getEpisodeSequence().length > VIEWER_FULL_EAGER_MAX) {
    await applyViewerContent({ jumpToSceneId: id, resetBook: false });
    return;
  }
  jumpViewerToScene(id);
}

function loadViewerSettings() {
  const base = defaultViewerSettings();
  try {
    const raw = localStorage.getItem(VIEWER_SETTINGS_KEY);
    if (!raw) return base;
    const parsed = JSON.parse(raw);
    const merged = { ...base, ...parsed };
    merged.phoneFlow = normalizeDeviceFlow(merged.phoneFlow, "page");
    merged.einkFlow = normalizeDeviceFlow(merged.einkFlow, "page");
    merged.typesetPlatform = TYPESET_PLATFORM_ORDER.includes(merged.typesetPlatform)
      ? merged.typesetPlatform
      : "munpia";
    return merged;
  } catch (_) {
    return base;
  }
}

function saveViewerSettings() {
  try {
    localStorage.setItem(VIEWER_SETTINGS_KEY, JSON.stringify(viewerSettings));
    localStorage.setItem(VIEWER_MODE_KEY, viewerSettings.mode);
  } catch (_) {
    /* ignore */
  }
}

function syncViewerControlValues() {
  const s = viewerSettings;
  const setRange = (id, val, labelId) => {
    if ($(id)) $(id).value = String(val);
    if ($(labelId)) $(labelId).textContent = String(val);
  };
  setRange("viewerPdfFont", s.pdfFont, "viewerPdfFontVal");
  setRange("viewerPdfMargin", s.pdfMargin, "viewerPdfMarginVal");
  setRange("viewerPdfScale", s.pdfScale ?? 90, "viewerPdfScaleVal");
  setRange("viewerPdfLineHeight", clampViewerLineHeight(s.pdfLineHeight, 1.8), "viewerPdfLineHeightVal");
  if ($("viewerPdfLineHeightVal")) {
    $("viewerPdfLineHeightVal").textContent = formatViewerLineHeightLabel(s.pdfLineHeight ?? 1.8);
  }
  setRange("viewerBookFont", s.bookFont, "viewerBookFontVal");
  setRange("viewerBookMargin", s.bookMargin, "viewerBookMarginVal");
  setRange("viewerBookW", s.bookW, "viewerBookWVal");
  setRange("viewerBookH", s.bookH, "viewerBookHVal");
  setRange("viewerBookLineHeight", clampViewerLineHeight(s.bookLineHeight, 1.8), "viewerBookLineHeightVal");
  if ($("viewerBookLineHeightVal")) {
    $("viewerBookLineHeightVal").textContent = formatViewerLineHeightLabel(s.bookLineHeight ?? 1.8);
  }
  setRange("viewerPhoneFont", s.phoneFont, "viewerPhoneFontVal");
  setRange("viewerPhoneW", s.phoneW, "viewerPhoneWVal");
  setRange("viewerPhoneH", s.phoneH, "viewerPhoneHVal");
  setRange("viewerPhoneLineHeight", clampViewerLineHeight(s.phoneLineHeight, 1.7), "viewerPhoneLineHeightVal");
  if ($("viewerPhoneLineHeightVal")) {
    $("viewerPhoneLineHeightVal").textContent = formatViewerLineHeightLabel(s.phoneLineHeight ?? 1.7);
  }
  setRange("viewerEinkFont", s.einkFont, "viewerEinkFontVal");
  setRange("viewerEinkW", s.einkW, "viewerEinkWVal");
  setRange("viewerEinkH", s.einkH, "viewerEinkHVal");
  setRange("viewerEinkLineHeight", clampViewerLineHeight(s.einkLineHeight, 1.8), "viewerEinkLineHeightVal");
  if ($("viewerEinkLineHeightVal")) {
    $("viewerEinkLineHeightVal").textContent = formatViewerLineHeightLabel(s.einkLineHeight ?? 1.8);
  }
  if ($("viewerBookPaper")) $("viewerBookPaper").value = s.bookPaper || "cream";
  if ($("viewerPhoneBg")) $("viewerPhoneBg").value = s.phoneBg;
  if ($("viewerPhoneFlow")) $("viewerPhoneFlow").value = s.phoneFlow === "scroll" ? "scroll" : "page";
  if ($("viewerEinkStyle")) $("viewerEinkStyle").value = s.einkStyle;
  if ($("viewerEinkFlow")) $("viewerEinkFlow").value = s.einkFlow === "scroll" ? "scroll" : "page";
  syncTypesetControlValues();
}

/** phone/eink: page-turn vs continuous scroll-down */
function isDeviceScrollFlow(mode = viewerSettings.mode) {
  if (mode === "typeset") return true;
  if (mode === "phone") return (viewerSettings.phoneFlow || "page") === "scroll";
  if (mode === "eink") return (viewerSettings.einkFlow || "page") === "scroll";
  return false;
}

function normalizeDeviceFlow(value, fallback = "page") {
  return value === "scroll" ? "scroll" : (fallback === "scroll" ? "scroll" : "page");
}

function applyViewerLayout() {
  const mode = VIEWER_MODES.includes(viewerSettings.mode) ? viewerSettings.mode : "pdf";
  viewerSettings.mode = mode;
  const stage = $("viewerStage");
  const frame = $("viewerFrame");
  const body = $("viewerBody");
  if (!stage || !frame || !body) return;

  stage.dataset.viewerMode = mode;
  document.querySelectorAll("#viewerModeTabs [data-viewer-mode]").forEach((btn) => {
    const on = btn.dataset.viewerMode === mode;
    btn.classList.toggle("is-active", on);
    btn.setAttribute("aria-selected", on ? "true" : "false");
  });
  document.querySelectorAll("[data-viewer-controls]").forEach((el) => {
    el.classList.toggle("hidden", el.dataset.viewerControls !== mode);
  });
  const meta = VIEWER_MODE_META[mode] || VIEWER_MODE_META.pdf;
  if ($("viewerHint")) $("viewerHint").textContent = meta.hint;

  // Reset inline sizes then apply per mode (must clear minHeight leftover from PDF)
  frame.style.width = "";
  frame.style.height = "";
  frame.style.minHeight = "";
  frame.style.maxWidth = "";
  frame.style.maxHeight = "";
  frame.style.flex = "";
  body.style.fontSize = "";
  body.style.fontFamily = "";
  body.style.letterSpacing = "";
  body.style.lineHeight = "";
  body.style.removeProperty("--typeset-indent");
  body.style.removeProperty("--typeset-para-gap");
  body.style.padding = "";
  body.style.paddingLeft = "";
  body.style.paddingRight = "";
  body.style.background = "";
  body.style.color = "";
  body.style.minHeight = "";
  body.style.height = "";
  body.style.display = "";
  frame.style.background = "";
  frame.style.boxShadow = "";
  frame.style.overflow = "";
  // Phone mode writes inline --viewer-page-* vars; clear so eink/book CSS presets work.
  clearViewerPageColorVars(body, stage, frame);

  const scroll = $("viewerScroll");
  if (scroll) {
    scroll.style.flex = "";
    scroll.style.minHeight = "";
    scroll.style.height = "";
    scroll.style.overflow = "";
  }

  // Available height inside the stage (for clamping device height)
  const stageH = stage.clientHeight || Math.round(window.innerHeight * 0.7);
  const maxDeviceH = Math.max(480, stageH - 24);

  if (mode === "pdf") {
    // Stack of discrete A4 sheets (fixed 210×297 aspect). pdfScale only zooms.
    const scale = Math.min(120, Math.max(55, Number(viewerSettings.pdfScale) || 90)) / 100;
    viewerSettings.pdfScale = Math.round(scale * 100);
    const sheetW = Math.round(A4_WIDTH_PX * scale);
    frame.style.width = `${sheetW}px`;
    frame.style.maxWidth = "100%";
    frame.style.minHeight = "0";
    frame.style.height = "auto";
    frame.style.overflow = "visible";
    frame.style.background = "transparent";
    frame.style.boxShadow = "none";
    body.style.fontSize = `${viewerSettings.pdfFont}px`;
    body.style.minHeight = "";
    body.style.height = "";
    body.style.display = "none";
    if (scroll) {
      scroll.style.overflow = "visible";
      scroll.style.minHeight = "0";
      scroll.style.height = "auto";
      scroll.style.flex = "0 0 auto";
      scroll.style.width = "100%";
    }
    stage.removeAttribute("data-eink-style");
    stage.removeAttribute("data-book-paper");
    if ($("viewerPdfScaleVal")) $("viewerPdfScaleVal").textContent = String(viewerSettings.pdfScale);
    scheduleDevicePageLayout({ resetPage: false });
  } else if (mode === "book") {
    // Open hardcover: fixed page size (W×H). Vertical slider = book size, not scroll.
    // Text flows as multi-column pages → flip with prev/next (no scroll-down).
    viewerSettings.bookW = Math.min(1040, Math.max(640, Number(viewerSettings.bookW) || 900));
    viewerSettings.bookH = Math.min(900, Math.max(420, Number(viewerSettings.bookH) || 560));
    viewerSettings.bookFont = Math.min(22, Math.max(12, Number(viewerSettings.bookFont) || 15));
    viewerSettings.bookMargin = Math.min(64, Math.max(20, Number(viewerSettings.bookMargin) || 36));
    const paper = viewerSettings.bookPaper || "cream";
    const w = Math.min(viewerSettings.bookW, stage.clientWidth ? stage.clientWidth - 32 : viewerSettings.bookW);
    const h = Math.min(viewerSettings.bookH, maxDeviceH);
    frame.style.width = `${w}px`;
    frame.style.maxWidth = "100%";
    frame.style.height = `${h}px`;
    frame.style.minHeight = `${h}px`;
    frame.style.maxHeight = `${h}px`;
    frame.style.overflow = "hidden";
    body.style.fontSize = `${viewerSettings.bookFont}px`;
    const m = viewerSettings.bookMargin;
    body.style.padding = `${m}px ${m}px ${m}px ${m}px`;
    body.style.minHeight = "";
    body.style.height = "";
    if (scroll) {
      scroll.style.flex = "1 1 auto";
      scroll.style.minHeight = "0";
      scroll.style.height = "100%";
      scroll.style.overflow = "hidden";
    }
    stage.dataset.bookPaper = paper;
    stage.removeAttribute("data-eink-style");
    if ($("viewerBookWVal")) $("viewerBookWVal").textContent = String(viewerSettings.bookW);
    if ($("viewerBookHVal")) $("viewerBookHVal").textContent = String(viewerSettings.bookH);
    // Defer column metrics until frame has real size
    scheduleBookPageLayout();
  } else if (mode === "phone") {
    viewerSettings.phoneFlow = normalizeDeviceFlow(viewerSettings.phoneFlow, "page");
    viewerSettings.phoneH = Math.min(900, Math.max(480, Number(viewerSettings.phoneH) || 780));
    viewerSettings.phoneW = Math.min(430, Math.max(280, Number(viewerSettings.phoneW) || 390));
    const h = Math.min(viewerSettings.phoneH, maxDeviceH);
    const scrollFlow = viewerSettings.phoneFlow === "scroll";
    frame.style.width = `${viewerSettings.phoneW}px`;
    frame.style.height = `${h}px`;
    frame.style.minHeight = `${h}px`;
    frame.style.maxHeight = `${h}px`;
    frame.style.maxWidth = "100%";
    frame.style.overflow = "hidden";
    body.style.fontSize = `${viewerSettings.phoneFont}px`;
    body.style.minHeight = "0";
    body.style.height = "auto";
    body.style.columnCount = "";
    body.style.columnGap = "";
    body.style.padding = scrollFlow ? "16px 16px 28px" : "";
    body.style.lineHeight = String(clampViewerLineHeight(viewerSettings.phoneLineHeight, 1.7));
    const phoneBg = viewerSettings.phoneBg || "#fffdf8";
    const phoneInk = viewerSettings.phoneInk || "#24211d";
    applyViewerPageColors(body, phoneBg, phoneInk);
    applyViewerPageColors(stage, phoneBg, phoneInk);
    body.style.background = phoneBg;
    body.style.color = phoneInk;
    if (scroll) {
      scroll.style.flex = "1 1 auto";
      scroll.style.minHeight = "0";
      scroll.style.height = "100%";
      scroll.style.overflow = scrollFlow ? "auto" : "hidden";
    }
    stage.dataset.viewerFlow = scrollFlow ? "scroll" : "page";
    stage.removeAttribute("data-eink-style");
    stage.removeAttribute("data-book-paper");
    if ($("viewerPhoneHVal")) $("viewerPhoneHVal").textContent = String(viewerSettings.phoneH);
    if (scrollFlow) {
      // Continuous manuscript — no page stack
      body.style.display = "";
    } else {
      body.style.display = "none";
      scheduleDevicePageLayout({ resetPage: false });
    }
  } else if (mode === "typeset") {
    const spec = readTypesetDraftFromForm();
    const width = Math.min(800, Math.max(200, Number(spec.mobile_viewport_px) || 360));
    const h = Math.min(900, Math.max(480, maxDeviceH));
    frame.style.width = `${width}px`;
    frame.style.height = `${h}px`;
    frame.style.minHeight = `${h}px`;
    frame.style.maxHeight = `${h}px`;
    frame.style.maxWidth = "100%";
    frame.style.overflow = "hidden";
    body.style.minHeight = "0";
    body.style.height = "auto";
    body.style.columnCount = "";
    body.style.columnGap = "";
    body.style.padding = "16px 14px 32px";
    body.style.display = "";
    applyTypesetBodyStyles(spec);
    applyViewerPageColors(body, "#ffffff", "#111111");
    applyViewerPageColors(stage, "#ffffff", "#111111");
    body.style.background = "#ffffff";
    body.style.color = "#111111";
    if (scroll) {
      scroll.style.flex = "1 1 auto";
      scroll.style.minHeight = "0";
      scroll.style.height = "100%";
      scroll.style.overflow = "auto";
    }
    stage.dataset.viewerFlow = "scroll";
    stage.removeAttribute("data-eink-style");
    stage.removeAttribute("data-book-paper");
  } else {
    // eink — page-turn or scroll-down (same as phone)
    viewerSettings.einkFlow = normalizeDeviceFlow(viewerSettings.einkFlow, "page");
    viewerSettings.einkH = Math.min(900, Math.max(480, Number(viewerSettings.einkH) || 720));
    viewerSettings.einkW = Math.min(560, Math.max(300, Number(viewerSettings.einkW) || 420));
    const h = Math.min(viewerSettings.einkH, maxDeviceH);
    const scrollFlow = viewerSettings.einkFlow === "scroll";
    frame.style.width = `${viewerSettings.einkW}px`;
    frame.style.height = `${h}px`;
    frame.style.minHeight = `${h}px`;
    frame.style.maxHeight = `${h}px`;
    frame.style.maxWidth = "100%";
    frame.style.overflow = "hidden";
    body.style.fontSize = `${viewerSettings.einkFont}px`;
    body.style.minHeight = "0";
    body.style.height = "auto";
    body.style.columnCount = "";
    body.style.columnGap = "";
    body.style.padding = scrollFlow ? "20px 18px 32px" : "";
    body.style.lineHeight = String(clampViewerLineHeight(viewerSettings.einkLineHeight, 1.8));
    if (scroll) {
      scroll.style.flex = "1 1 auto";
      scroll.style.minHeight = "0";
      scroll.style.height = "100%";
      scroll.style.overflow = scrollFlow ? "auto" : "hidden";
    }
    const einkStyle = VIEWER_EINK_STYLES[viewerSettings.einkStyle]
      ? viewerSettings.einkStyle
      : "paper";
    viewerSettings.einkStyle = einkStyle;
    stage.dataset.einkStyle = einkStyle;
    stage.dataset.viewerFlow = scrollFlow ? "scroll" : "page";
    const palette = getViewerEinkPalette(einkStyle);
    applyViewerPageColors(body, palette.bg, palette.ink);
    applyViewerPageColors(stage, palette.bg, palette.ink);
    body.style.background = palette.bg;
    body.style.color = palette.ink;
    stage.removeAttribute("data-book-paper");
    if ($("viewerEinkHVal")) $("viewerEinkHVal").textContent = String(viewerSettings.einkH);
    if ($("viewerEinkStyle") && $("viewerEinkStyle").value !== einkStyle) {
      $("viewerEinkStyle").value = einkStyle;
    }
    if (scrollFlow) {
      body.style.display = "";
    } else {
      body.style.display = "none";
      scheduleDevicePageLayout({ resetPage: false });
    }
  }

  // Book track vs page stack vs continuous body
  const track = $("bookTrack");
  const pageStack = $("viewerPageStack");
  const deviceScroll = mode === "typeset" || ((mode === "phone" || mode === "eink") && isDeviceScrollFlow(mode));
  if (mode === "book") {
    if (track) track.hidden = false;
    if (pageStack) {
      pageStack.hidden = true;
      pageStack.innerHTML = "";
    }
    body.style.display = "none";
    stage.removeAttribute("data-viewer-flow");
  } else if (deviceScroll) {
    cancelBookFlipAnimation();
    if (track) {
      track.hidden = true;
      track.innerHTML = "";
      track.style.transform = "";
      track.style.width = "";
    }
    if (pageStack) {
      pageStack.hidden = true;
      pageStack.innerHTML = "";
    }
    body.style.display = "";
    body.style.columnCount = "";
    body.style.columnGap = "";
    body.style.columnWidth = "";
    body.style.columnFill = "";
    body.style.width = "";
    body.style.maxWidth = "";
    body.style.transform = "";
    // Reset scroll position when switching into scroll mode
    if (scroll) {
      requestAnimationFrame(() => {
        try { scroll.scrollTop = 0; } catch (_) { /* ignore */ }
      });
    }
    updateDevicePagerUi();
  } else if (mode === "pdf" || mode === "phone" || mode === "eink") {
    cancelBookFlipAnimation();
    if (track) {
      track.hidden = true;
      track.innerHTML = "";
      track.style.transform = "";
      track.style.width = "";
    }
    if (pageStack) pageStack.hidden = false;
    body.style.display = "none";
    if (mode === "pdf") stage.removeAttribute("data-viewer-flow");
  } else {
    cancelBookFlipAnimation();
    if (track) {
      track.hidden = true;
      track.innerHTML = "";
      track.style.transform = "";
      track.style.width = "";
    }
    if (pageStack) {
      pageStack.hidden = true;
      pageStack.innerHTML = "";
    }
    body.style.display = "";
    body.style.columnCount = "";
    body.style.columnGap = "";
    body.style.columnWidth = "";
    body.style.columnFill = "";
    body.style.width = "";
    body.style.maxWidth = "";
    body.style.transform = "";
    stage.removeAttribute("data-viewer-flow");
  }
  saveViewerSettings();
}

function scheduleBookPageLayout({ resetPage = false } = {}) {
  if (bookPageLayoutTimer) window.clearTimeout(bookPageLayoutTimer);
  bookPageLayoutTimer = window.setTimeout(() => {
    bookPageLayoutTimer = null;
    layoutBookPages({ resetPage });
  }, 50);
}

function scheduleDevicePageLayout({ resetPage = false } = {}) {
  if (devicePageLayoutTimer) window.clearTimeout(devicePageLayoutTimer);
  devicePageLayoutTimer = window.setTimeout(() => {
    devicePageLayoutTimer = null;
    layoutDevicePages({ resetPage });
  }, 50);
}

function isDevicePagedMode(mode = viewerSettings.mode) {
  // phone/eink scroll-down uses continuous body, not discrete page stack
  if (mode === "phone" || mode === "eink") {
    return !isDeviceScrollFlow(mode);
  }
  return mode === "pdf";
}

function getDevicePageScrollHost() {
  // PDF: stage scrolls through stacked A4 sheets
  // phone/eink: viewerScroll scrolls/snaps through screen pages
  if (viewerSettings.mode === "pdf") return $("viewerStage");
  return $("viewerScroll");
}

function setViewerBookNavVisible(visible) {
  const prev = $("viewerBookPrev");
  const next = $("viewerBookNext");
  [prev, next].forEach((btn) => {
    if (!btn) return;
    btn.hidden = !visible;
    btn.setAttribute("aria-hidden", visible ? "false" : "true");
    if (!visible) btn.disabled = true;
  });
}

function updateDevicePagerUi() {
  const mode = viewerSettings.mode;
  const pager = $("viewerBookPager");
  const prev = $("viewerBookPrev");
  const next = $("viewerBookNext");
  if (mode === "book") return; // book has its own updater

  if (mode === "pdf") {
    // PDF: scroll only — hide side nav buttons; show page index in pager + hint
    setViewerBookNavVisible(false);
    const label = `${i18n.t('app.devicePageIndex_1_devic', {'devicePageIndex + 1': devicePageIndex + 1, devicePageCount: devicePageCount})}`;
    if (pager) {
      pager.textContent = label;
      pager.title = `${i18n.t('app.A4_devicePageCount_장_스크롤', {devicePageCount: devicePageCount})}`;
    }
    if ($("viewerHint")) {
      $("viewerHint").textContent = `${i18n.t('app.A4_페이지_label_스크롤_또는_PgDn', {label: label})}`;
    }
    return;
  }

  if (mode === "typeset") {
    setViewerBookNavVisible(false);
    if (pager) {
      pager.textContent = i18n.t("app.스크롤");
      pager.title = i18n.t("app.아래로_스크롤하여_읽기");
    }
    const meta = VIEWER_MODE_META.typeset || {};
    if ($("viewerHint")) $("viewerHint").textContent = meta.hint || "";
    return;
  }

  if (mode === "phone" || mode === "eink") {
    if (isDeviceScrollFlow(mode)) {
      // 스크롤 다운: 책넘김 버튼 숨김 (휠·터치 스크롤만)
      setViewerBookNavVisible(false);
      if (pager) {
        pager.textContent = i18n.t('app.스크롤');
        pager.title = i18n.t('app.아래로_스크롤하여_읽기');
      }
      const meta = VIEWER_MODE_META[mode] || {};
      if ($("viewerHint")) {
        $("viewerHint").textContent = `${i18n.t('app.meta_label_mode_스크롤_다운', {'meta.label || mode': meta.label || mode})}`;
      }
      return;
    }
    setViewerBookNavVisible(true);
    if (pager) {
      pager.textContent = `${devicePageIndex + 1} / ${devicePageCount}`;
      pager.title = `${i18n.t('app.페이지_devicePageIndex_1_de', {'devicePageIndex + 1': devicePageIndex + 1, devicePageCount: devicePageCount})}`;
    }
    if (prev) prev.disabled = devicePageIndex <= 0;
    if (next) next.disabled = devicePageIndex >= devicePageCount - 1;
    if ($("viewerHint")) {
      const meta = VIEWER_MODE_META[mode] || {};
      $("viewerHint").textContent = `${i18n.t('app.meta_label_mode_책_넘김_휠', {'meta.label || mode': meta.label || mode})}`;
    }
  }
}

/** Scroll phone/eink continuous body by roughly one viewport (scroll-down mode). */
function scrollDeviceViewport(delta) {
  if (!isViewerOpen()) return;
  if (!isDeviceScrollFlow()) return;
  const scroll = $("viewerScroll");
  if (!scroll) return;
  const dir = delta > 0 ? 1 : delta < 0 ? -1 : 0;
  if (!dir) return;
  const step = Math.max(120, Math.round(scroll.clientHeight * 0.88));
  scroll.scrollBy({ top: dir * step, behavior: "smooth" });
  window.setTimeout(() => updateDevicePagerUi(), 320);
}

function splitViewerEpisodeHtml(html) {
  const wrap = document.createElement("div");
  wrap.innerHTML = html || "";
  const episodes = [];
  for (const node of [...wrap.childNodes]) {
    if (node.nodeType === 1 && node.matches?.("section.viewer-episode")) {
      episodes.push({
        sceneId: Number(node.getAttribute("data-viewer-scene")) || 0,
        html: node.outerHTML,
      });
    }
  }
  if (!episodes.length && String(html || "").trim()) {
    return [{ sceneId: Number(state.sceneId) || 0, html: String(html || "") }];
  }
  return episodes;
}

function assembleViewerPageSlots() {
  const pages = [];
  for (const slot of viewerEpisodePageSlots) {
    if (!slot || !slot.pages) continue;
    pages.push(...slot.pages);
  }
  return pages.length ? pages : [""];
}

function viewerSceneAtPageIndex(pageIndex) {
  let idx = 0;
  for (const slot of viewerEpisodePageSlots) {
    if (!slot || !slot.pages) continue;
    const n = slot.pages.length;
    if (pageIndex < idx + n) {
      return { sceneId: Number(slot.sceneId) || 0, pageInEpisode: pageIndex - idx };
    }
    idx += n;
  }
  return null;
}

function viewerPageIndexForScene(sceneId, pageInEpisode = 0) {
  const id = Number(sceneId);
  let idx = 0;
  for (const slot of viewerEpisodePageSlots) {
    if (!slot || !slot.pages) continue;
    if (Number(slot.sceneId) === id) {
      const last = Math.max(0, slot.pages.length - 1);
      return idx + Math.min(Math.max(0, pageInEpisode), last);
    }
    idx += slot.pages.length;
  }
  return -1;
}

function setViewerViewAnchor(sceneId, pageInEpisode = 0) {
  const id = Number(sceneId);
  if (!Number.isFinite(id) || id <= 0) return;
  viewerViewAnchor = {
    sceneId: id,
    pageInEpisode: Math.max(0, Number(pageInEpisode) || 0),
  };
}

function syncViewerViewAnchorFromIndex(pageIndex = devicePageIndex) {
  const a = viewerSceneAtPageIndex(pageIndex);
  if (a && Number(a.sceneId) > 0) viewerViewAnchor = a;
}

function restoreViewerIndexFromAnchor() {
  const id = Number(viewerViewAnchor?.sceneId);
  if (!Number.isFinite(id) || id <= 0) return false;
  const idx = viewerPageIndexForScene(id, viewerViewAnchor.pageInEpisode || 0);
  if (idx < 0) return false;
  devicePageIndex = idx;
  return true;
}

function computeViewerPageBox() {
  const mode = viewerSettings.mode;
  const scroll = $("viewerScroll");
  if (mode === "book") {
    if (vwTooSmall(scroll)) return { retry: true };
    const vw = scroll.clientWidth;
    const vh = scroll.clientHeight;
    if (vw < 80 || vh < 80) return { retry: true };
    const m = Math.min(64, Math.max(20, Number(viewerSettings.bookMargin) || 36));
    const fontPx = Math.min(22, Math.max(12, Number(viewerSettings.bookFont) || 15));
    const lineHeight = clampViewerLineHeight(viewerSettings.bookLineHeight, 1.8);
    viewerSettings.bookLineHeight = lineHeight;
    bookPageMetrics = { m, fontPx, lineHeight };
    const pageW = Math.floor(vw / 2);
    return {
      kind: "book",
      innerW: Math.max(40, pageW - m * 2),
      innerH: Math.max(40, vh - m * 2),
      fontPx,
      lineHeight,
      fontFamily: "Georgia,'Noto Serif KR','Malgun Gothic',serif",
    };
  }
  if (!isDevicePagedMode(mode)) return null;
  const body = $("viewerBody");
  const stack = $("viewerPageStack");
  if (!body || !stack) return null;
  let innerW;
  let innerH;
  let fontPx;
  let padX;
  let padY;
  let lineHeight = 1.8;
  if (mode === "pdf") {
    fontPx = Math.min(22, Math.max(11, Number(viewerSettings.pdfFont) || 14));
    lineHeight = clampViewerLineHeight(viewerSettings.pdfLineHeight, 1.8);
    viewerSettings.pdfLineHeight = lineHeight;
    padX = Math.min(96, Math.max(24, Number(viewerSettings.pdfMargin) || 56));
    padY = padX;
    const padT = Math.round(padY * 0.85);
    const padB = Math.round(padY * 1.1);
    innerW = Math.max(40, A4_WIDTH_PX - padX * 2);
    innerH = Math.max(40, A4_HEIGHT_PX - padT - padB);
  } else if (mode === "phone") {
    fontPx = Math.min(24, Math.max(12, Number(viewerSettings.phoneFont) || 15));
    lineHeight = clampViewerLineHeight(viewerSettings.phoneLineHeight, 1.7);
    viewerSettings.phoneLineHeight = lineHeight;
    padX = 16;
    padY = 16;
    const vw = scroll?.clientWidth || Math.max(200, (Number(viewerSettings.phoneW) || 390) - 6);
    const vh = scroll?.clientHeight || Math.max(300, (Number(viewerSettings.phoneH) || 780) - 48);
    if (vw < 40 || vh < 40) return { retry: true };
    innerW = Math.max(40, vw - padX * 2);
    innerH = Math.max(40, vh - padY * 2);
  } else {
    fontPx = Math.min(26, Math.max(13, Number(viewerSettings.einkFont) || 17));
    lineHeight = clampViewerLineHeight(viewerSettings.einkLineHeight, 1.8);
    viewerSettings.einkLineHeight = lineHeight;
    padX = 20;
    padY = 22;
    const vw = scroll?.clientWidth || Math.max(200, (Number(viewerSettings.einkW) || 420) - 4);
    const vh = scroll?.clientHeight || Math.max(300, (Number(viewerSettings.einkH) || 720) - 4);
    if (vw < 40 || vh < 40) return { retry: true };
    innerW = Math.max(40, vw - padX * 2);
    innerH = Math.max(40, vh - padY * 2);
  }
  const scalePct = Math.min(120, Math.max(55, Number(viewerSettings.pdfScale) || 90));
  devicePageMetrics = {
    padX,
    padY,
    fontPx,
    scale: mode === "pdf" ? scalePct : 100,
    lineHeight,
    fontFamily: mode === "pdf"
      ? '"Malgun Gothic","Noto Serif KR",Georgia,serif'
      : 'Georgia,"Noto Serif KR","Malgun Gothic",serif',
  };
  return {
    kind: "device",
    innerW,
    innerH,
    fontPx,
    lineHeight,
    fontFamily: devicePageMetrics.fontFamily,
  };
}

function vwTooSmall(scroll) {
  return !scroll || scroll.clientWidth < 80 || scroll.clientHeight < 80;
}

function makePdfSheetWrap(html, pageIndex) {
  const metrics = devicePageMetrics;
  const scale = Math.min(120, Math.max(55, Number(metrics.scale) || Number(viewerSettings.pdfScale) || 90)) / 100;
  const padT = Math.round(metrics.padY * 0.85);
  const padB = Math.round(metrics.padY * 1.1);
  const padX = metrics.padX;
  const wrap = document.createElement("div");
  wrap.className = "pdf-sheet-wrap";
  wrap.dataset.pageIndex = String(pageIndex);
  wrap.style.width = `${Math.round(A4_WIDTH_PX * scale)}px`;
  wrap.style.height = `${Math.round(A4_HEIGHT_PX * scale)}px`;
  const sheet = document.createElement("article");
  sheet.className = "pdf-sheet";
  sheet.dataset.pageIndex = String(pageIndex);
  sheet.setAttribute("aria-label", `${i18n.t('app.i_1_페이지', {'i + 1': pageIndex + 1})}`);
  sheet.style.width = `${A4_WIDTH_PX}px`;
  sheet.style.height = `${A4_HEIGHT_PX}px`;
  sheet.style.transform = `scale(${scale})`;
  sheet.style.transformOrigin = "top left";
  const inner = document.createElement("div");
  inner.className = "pdf-sheet-inner";
  inner.style.padding = `${padT}px ${padX}px ${padB}px ${padX}px`;
  inner.style.fontSize = `${metrics.fontPx}px`;
  inner.style.lineHeight = String(metrics.lineHeight || 1.8);
  inner.innerHTML = html || "";
  sheet.appendChild(inner);
  wrap.appendChild(sheet);
  return wrap;
}

function makeDeviceSheet(html, pageIndex, { active = false, sheetH = 400 } = {}) {
  const metrics = devicePageMetrics;
  const lh = metrics.lineHeight || 1.7;
  const sheet = document.createElement("article");
  sheet.className = `device-sheet${active ? " is-active" : ""}`;
  sheet.dataset.pageIndex = String(pageIndex);
  sheet.setAttribute("aria-label", `${i18n.t('app.i_1_페이지', {'i + 1': pageIndex + 1})}`);
  sheet.setAttribute("aria-hidden", active ? "false" : "true");
  sheet.style.height = `${sheetH}px`;
  sheet.style.minHeight = `${sheetH}px`;
  sheet.style.maxHeight = `${sheetH}px`;
  const inner = document.createElement("div");
  inner.className = "device-sheet-inner";
  inner.style.padding = `${metrics.padY}px ${metrics.padX}px`;
  inner.style.fontSize = `${metrics.fontPx}px`;
  inner.style.lineHeight = String(lh);
  inner.innerHTML = html || "";
  sheet.appendChild(inner);
  return sheet;
}

function reindexDevicePageStack(stack, mode) {
  if (!stack) return;
  if (mode === "pdf") {
    stack.querySelectorAll(".pdf-sheet-wrap").forEach((wrap, i) => {
      wrap.dataset.pageIndex = String(i);
      const sheet = wrap.querySelector(".pdf-sheet");
      if (sheet) {
        sheet.dataset.pageIndex = String(i);
        sheet.setAttribute("aria-label", `${i18n.t('app.i_1_페이지', {'i + 1': i + 1})}`);
      }
    });
    return;
  }
  stack.querySelectorAll(".device-sheet").forEach((sheet, i) => {
    sheet.dataset.pageIndex = String(i);
    sheet.setAttribute("aria-label", `${i18n.t('app.i_1_페이지', {'i + 1': i + 1})}`);
  });
}

function paintDevicePageStack({ hint = "replace", count = 0 } = {}) {
  const stack = $("viewerPageStack");
  const mode = viewerSettings.mode;
  if (!stack || !isDevicePagedMode(mode)) return;

  stack.hidden = false;
  const metrics = devicePageMetrics;
  const pages = devicePages.length ? devicePages : [""];

  if (mode === "pdf") {
    if (hint === "replace" || stack.dataset.pageMode !== "pdf") {
      stack.innerHTML = "";
      stack.className = "viewer-page-stack is-pdf-stack";
      stack.dataset.pageMode = "pdf";
      pages.forEach((html, i) => stack.appendChild(makePdfSheetWrap(html, i)));
      return;
    }
    if (hint === "append" && count > 0) {
      const start = Math.max(0, pages.length - count);
      for (let i = start; i < pages.length; i += 1) {
        stack.appendChild(makePdfSheetWrap(pages[i], i));
      }
      return;
    }
    if (hint === "prepend" && count > 0) {
      const host = getDevicePageScrollHost();
      const sample = stack.querySelector(".pdf-sheet-wrap");
      const sheetH = sample
        ? sample.offsetHeight
        : Math.round(A4_HEIGHT_PX * ((Number(metrics.scale) || 90) / 100));
      const frag = document.createDocumentFragment();
      for (let i = 0; i < count; i += 1) {
        frag.appendChild(makePdfSheetWrap(pages[i], i));
      }
      stack.insertBefore(frag, stack.firstChild);
      reindexDevicePageStack(stack, "pdf");
      if (host) host.scrollTop += sheetH * count;
      return;
    }
    return;
  }

  // phone / eink: keep only nearby sheets so 500-page stacks don't freeze the DOM
  stack.className = "viewer-page-stack is-device-stack";
  stack.dataset.pageMode = mode;
  const scroll = $("viewerScroll");
  const sheetH = Math.max(120, scroll?.clientHeight || 400);
  const active = Math.min(Math.max(0, devicePageIndex), Math.max(0, pages.length - 1));
  const from = Math.max(0, active - 1);
  const to = Math.min(pages.length - 1, active + 1);
  stack.innerHTML = "";
  for (let i = from; i <= to; i += 1) {
    stack.appendChild(makeDeviceSheet(pages[i], i, { active: i === active, sheetH }));
  }
}

function syncDevicePageIndexFromScroll() {
  if (devicePageScrollLock) return;
  if (!isDevicePagedMode() || !isViewerOpen()) return;
  const host = getDevicePageScrollHost();
  const stack = $("viewerPageStack");
  if (!host || !stack) return;
  const selector = viewerSettings.mode === "pdf" ? ".pdf-sheet-wrap" : ".device-sheet";
  const sheets = stack.querySelectorAll(selector);
  if (!sheets.length) return;

  const hostRect = host.getBoundingClientRect();
  const focusY = hostRect.top + Math.min(hostRect.height * 0.35, 80);
  let best = 0;
  let bestDist = Infinity;
  sheets.forEach((sheet, i) => {
    const r = sheet.getBoundingClientRect();
    const dist = Math.abs(r.top - focusY);
    if (dist < bestDist) {
      bestDist = dist;
      const pageIndex = Number(sheet.dataset.pageIndex);
      best = Number.isFinite(pageIndex) ? pageIndex : i;
    }
  });
  if (best !== devicePageIndex) {
    devicePageIndex = best;
    syncViewerViewAnchorFromIndex(devicePageIndex);
    updateDevicePagerUi();
  }
}

function showDevicePage(index, { smooth = false, direction = 0 } = {}) {
  if (!isDevicePagedMode() || !isViewerOpen()) return;
  const stack = $("viewerPageStack");
  if (!stack) return;

  const max = Math.max(0, devicePageCount - 1);
  const prevIndex = devicePageIndex;
  const i = Math.min(Math.max(0, Number(index) || 0), max);
  devicePageIndex = i;

  if (viewerSettings.mode === "pdf") {
    const host = getDevicePageScrollHost();
    const sheet = stack.querySelector(`.pdf-sheet-wrap[data-page-index="${i}"]`)
      || stack.querySelectorAll(".pdf-sheet-wrap")[i];
    if (!sheet) {
      updateDevicePagerUi();
      return;
    }
    devicePageScrollLock = true;
    const behavior = smooth ? "smooth" : "auto";
    try {
      const stage = $("viewerStage");
      if (stage) {
        const stageTop = stage.getBoundingClientRect().top;
        const sheetTop = sheet.getBoundingClientRect().top;
        const nextTop = stage.scrollTop + (sheetTop - stageTop) - 12;
        stage.scrollTo({ top: Math.max(0, nextTop), behavior });
      }
    } catch (_) {
      try { sheet.scrollIntoView(true); } catch (__) { /* ignore */ }
    }
    updateDevicePagerUi();
    syncViewerViewAnchorFromIndex(devicePageIndex);
    window.setTimeout(() => {
      devicePageScrollLock = false;
      syncDevicePageIndexFromScroll();
    }, smooth ? 420 : 80);
    return;
  }

  // phone / eink: swap visible page (no scroll)
  paintDevicePageStack({ hint: "replace" });
  const sheets = stack.querySelectorAll(".device-sheet");
  if (!sheets.length) {
    updateDevicePagerUi();
    return;
  }
  const dir = direction || (i > prevIndex ? 1 : i < prevIndex ? -1 : 0);
  sheets.forEach((sheet) => {
    const on = Number(sheet.dataset.pageIndex) === i;
    sheet.classList.toggle("is-active", on);
    sheet.setAttribute("aria-hidden", on ? "false" : "true");
    sheet.classList.remove("turn-from-next", "turn-from-prev");
    if (on && smooth && dir) {
      sheet.classList.add(dir > 0 ? "turn-from-next" : "turn-from-prev");
      // Restart animation
      // eslint-disable-next-line no-unused-expressions
      sheet.offsetWidth;
      sheet.classList.add("is-turning");
      window.setTimeout(() => sheet.classList.remove("is-turning", "turn-from-next", "turn-from-prev"), 280);
    }
  });
  // Keep scroll host pinned (in case of residual scroll position)
  const scroll = $("viewerScroll");
  if (scroll) scroll.scrollTop = 0;
  updateDevicePagerUi();
  syncViewerViewAnchorFromIndex(devicePageIndex);
}

function turnDevicePage(delta) {
  if (!isViewerOpen()) return;
  // phone/eink scroll-down: move by viewport instead of discrete pages
  if (isDeviceScrollFlow()) {
    scrollDeviceViewport(delta);
    return;
  }
  if (!isDevicePagedMode()) return;
  const dir = delta > 0 ? 1 : delta < 0 ? -1 : 0;
  if (!dir) return;
  const next = devicePageIndex + dir;
  if (next < 0 || next >= devicePageCount) return;
  showDevicePage(next, {
    smooth: viewerSettings.mode !== "pdf",
    direction: dir,
  });
}

async function paginateViewerEpisodesIncremental({
  job,
  loadToken,
  jumpId,
  resetPage,
  box,
}) {
  const still = () => (
    job === viewerPageLayoutToken
    && loadToken === viewerLoadToken
    && isViewerOpen()
  );
  if (!still()) return;

  const body = $("viewerBody");
  if (!body) return;
  const episodes = splitViewerEpisodeHtml(body.innerHTML || "");
  if (!episodes.length) {
    devicePages = [""];
    devicePageCount = 1;
    bookPages = [""];
    bookSpreadCount = 1;
    if (box.kind === "device") paintDevicePageStack({ hint: "replace" });
    if (viewerPerf) {
      viewerPerf.layoutDone = true;
      viewerPerf.pages = 1;
      publishViewerPerf();
    }
    return;
  }

  const key = `${viewerSettings.mode}:${box.innerW}x${box.innerH}:${box.fontPx}:${box.lineHeight}`;
  const prevById = new Map();
  if (key === viewerPageMetricsKey) {
    viewerEpisodePageSlots.forEach((slot) => {
      if (slot && slot.pages && slot.sceneId) prevById.set(Number(slot.sceneId), slot);
    });
  } else {
    viewerPageMetricsKey = key;
  }

  viewerEpisodePageSlots = episodes.map((ep) => {
    const prev = prevById.get(Number(ep.sceneId));
    if (prev && prev.html === ep.html && Array.isArray(prev.pages)) {
      return prev;
    }
    return { sceneId: ep.sceneId, html: ep.html, pages: null };
  });

  const currentAnchor = viewerSceneAtPageIndex(devicePageIndex);
  let startIndex = viewerEpisodePageSlots.findIndex((slot) => Number(slot.sceneId) === Number(jumpId));
  if (startIndex < 0 && viewerViewAnchor?.sceneId) {
    startIndex = viewerEpisodePageSlots.findIndex((slot) => Number(slot.sceneId) === Number(viewerViewAnchor.sceneId));
  }
  if (startIndex < 0 && currentAnchor) {
    startIndex = viewerEpisodePageSlots.findIndex((slot) => Number(slot.sceneId) === Number(currentAnchor.sceneId));
  }
  if (startIndex < 0) startIndex = 0;
  const shouldJump = Boolean(Number(jumpId)) || resetPage;

  const paginateSlot = (slotIndex) => {
    const slot = viewerEpisodePageSlots[slotIndex];
    if (!slot) return 0;
    if (Array.isArray(slot.pages)) return slot.pages.length;
    const t0 = performance.now();
    const pages = paginateHtmlToPages(slot.html, box.innerW, box.innerH, box.fontPx, {
      lineHeight: box.lineHeight,
      fontFamily: box.fontFamily,
    });
    slot.pages = pages.length ? pages : [""];
    console.log(
      `viewer:pageBatch scene=${slot.sceneId} pages=${slot.pages.length} ms=${Math.round(performance.now() - t0)} done=${viewerEpisodePageSlots.filter((s) => s && s.pages).length}/${viewerEpisodePageSlots.length}`
    );
    return slot.pages.length;
  };

  const applyAssembled = ({ hint = "replace", count = 0, jumpNow = false } = {}) => {
    if (!still()) return;
    const pages = (hint === "replace" && jumpNow)
      ? (viewerEpisodePageSlots[startIndex]?.pages?.length
        ? viewerEpisodePageSlots[startIndex].pages
        : [""])
      : assembleViewerPageSlots();
    devicePages = pages;
    devicePageCount = Math.max(1, pages.length);
    bookPages = pages;
    bookSpreadCount = Math.max(1, Math.ceil(bookPages.length / 2));

    if (jumpNow) {
      devicePageIndex = 0;
      const jumpScene = Number(jumpId) || Number(viewerEpisodePageSlots[startIndex]?.sceneId) || 0;
      setViewerViewAnchor(jumpScene, 0);
    } else {
      restoreViewerIndexFromAnchor();
    }
    devicePageIndex = Math.min(Math.max(0, devicePageIndex), devicePageCount - 1);
    bookSpreadIndex = Math.min(
      Math.max(0, Math.floor(devicePageIndex / 2)),
      Math.max(0, bookSpreadCount - 1)
    );

    if (box.kind === "book") {
      const track = $("bookTrack");
      const scroll = $("viewerScroll");
      if (track && scroll) {
        cancelBookFlipAnimation();
        ensureBookViewport(track, scroll.clientHeight);
        paintBookSpread(bookSpreadIndex);
        updateBookPagerUi();
      }
      return;
    }

    paintDevicePageStack({ hint, count });
    updateDevicePagerUi();
    if (jumpNow || hint === "prepend") {
      highlightViewerTocCurrent(jumpId || viewerViewAnchor?.sceneId || viewerEpisodePageSlots[startIndex]?.sceneId);
      requestAnimationFrame(() => showDevicePage(devicePageIndex, { smooth: false }));
    }
  };

  const order = [startIndex];
  for (let i = startIndex + 1; i < viewerEpisodePageSlots.length; i += 1) order.push(i);
  for (let i = startIndex - 1; i >= 0; i -= 1) order.push(i);

  const stack = $("viewerPageStack");
  const hasPaintedStack = Boolean(
    (box.kind === "device" && stack?.querySelector(".pdf-sheet-wrap, .device-sheet"))
    || (box.kind === "book" && $("bookTrack")?.querySelector(".book-viewport"))
  );

  paginateSlot(startIndex);
  if (!still()) return;

  if (shouldJump || !hasPaintedStack) {
    const startSlot = viewerEpisodePageSlots[startIndex];
    devicePages = startSlot?.pages?.length ? startSlot.pages : [""];
    devicePageCount = Math.max(1, devicePages.length);
    bookPages = devicePages;
    bookSpreadCount = Math.max(1, Math.ceil(bookPages.length / 2));
    devicePageIndex = 0;
    bookSpreadIndex = 0;
    applyAssembled({ hint: "replace", jumpNow: true });
  } else {
    applyAssembled({ hint: "replace", jumpNow: false });
  }
  if (viewerPerf) {
    viewerPerf.layoutDone = true;
    viewerPerf.layoutName = box.kind === "book" ? "layoutBookPages" : "layoutDevicePages";
    viewerPerf.mode = viewerSettings.mode;
    viewerPerf.pages = devicePageCount;
    publishViewerPerf();
  }

  const paintedIds = new Set();
  paintedIds.add(Number(viewerEpisodePageSlots[startIndex]?.sceneId));

  for (const slotIndex of order) {
    if (!still()) return;
    const slot = viewerEpisodePageSlots[slotIndex];
    if (!slot) continue;
    if (paintedIds.has(Number(slot.sceneId)) && Array.isArray(slot.pages)) continue;
    await yieldViewerFullLoad();
    if (!still()) return;
    const added = paginateSlot(slotIndex);
    if (!still()) return;
    paintedIds.add(Number(slot.sceneId));
    const isBefore = slotIndex < startIndex;
    applyAssembled({
      hint: isBefore ? "prepend" : "append",
      count: added,
      jumpNow: false,
    });
  }

  if (!still()) return;
  if (viewerPerf) {
    viewerPerf.pages = devicePageCount;
    viewerPerf.layoutDone = true;
    publishViewerPerf();
  }
}

function startViewerPageLayout({ token = viewerLoadToken, jumpId = null, resetPage = false } = {}) {
  if (!isViewerOpen()) return;
  const mode = viewerSettings.mode;
  if (mode !== "book" && !isDevicePagedMode(mode)) return;
  const box = computeViewerPageBox();
  if (!box) return;
  if (box.retry) {
    if (mode === "book") scheduleBookPageLayout({ resetPage });
    else scheduleDevicePageLayout({ resetPage });
    return;
  }
  const job = ++viewerPageLayoutToken;
  const jump = Number(jumpId) || Number(viewerPendingJumpSceneId) || 0;
  if (jump) {
    viewerPendingJumpSceneId = null;
    setViewerViewAnchor(jump, 0);
  }
  paginateViewerEpisodesIncremental({
    job,
    loadToken: token,
    jumpId: jump,
    resetPage,
    box,
  }).catch((error) => {
    if (typeof handleError === "function") handleError(error);
  });
}

function layoutDevicePages({ resetPage = false } = {}) {
  if (!isViewerOpen() || !isDevicePagedMode()) return;
  const body = $("viewerBody");
  const stack = $("viewerPageStack");
  if (!body || !stack) return;
  startViewerPageLayout({
    token: viewerLoadToken,
    jumpId: viewerPendingJumpSceneId,
    resetPage,
  });
}

/**
 * Split rich HTML into page-sized chunks that fit a fixed (width × height) box.
 * Splits long text and oversized elements across pages so content continues
 * instead of being clipped on a single sheet.
 */
function paginateHtmlToPages(html, pageWidth, pageHeight, fontSizePx, styleOpts = {}) {
  console.time("viewer:paginateHtmlToPages");
  const paginateT0 = performance.now();
  let overflowChecks = 0;
  const pages = [];
  const lineHeight = styleOpts.lineHeight || 1.75;
  const fontFamily = styleOpts.fontFamily
    || '"Malgun Gothic","Noto Serif KR",Georgia,serif';
  const measureHost = document.createElement("div");
  measureHost.setAttribute("aria-hidden", "true");
  measureHost.style.cssText = [
    "position:absolute",
    "left:-10000px",
    "top:0",
    "visibility:hidden",
    `width:${Math.max(40, pageWidth)}px`,
    `height:${Math.max(40, pageHeight)}px`,
    "overflow:hidden",
    "box-sizing:border-box",
    `font-size:${fontSizePx}px`,
    `font-family:${fontFamily}`,
    `line-height:${lineHeight}`,
    "white-space:pre-wrap",
    "word-break:break-word",
  ].join(";");
  document.body.appendChild(measureHost);

  const source = document.createElement("div");
  source.innerHTML = html || "";
  const queue = [...source.childNodes].filter((n) => {
    if (n.nodeType === 3) return String(n.textContent || "").replace(/\u200b/g, "").length > 0;
    return n.nodeType === 1;
  });

  const overflows = () => {
    overflowChecks += 1;
    return measureHost.scrollHeight > pageHeight + 0.5
      || measureHost.scrollWidth > pageWidth + 0.5;
  };

  const pageTextLen = () => (page.textContent || "").replace(/\u200b/g, "").length;

  const linePx = Math.max(1, fontSizePx * lineHeight);
  const charsPerLine = Math.max(1, pageWidth / Math.max(1, fontSizePx));
  let estimatedChars = Math.max(1, Math.floor((pageHeight / linePx) * charsPerLine));
  let sealedCount = 0;

  let page = document.createElement("div");
  measureHost.appendChild(page);

  const noteSealedPageChars = (charCount) => {
    if (!(charCount > 0)) return;
    if (sealedCount < 2) {
      estimatedChars = sealedCount === 0
        ? charCount
        : Math.max(1, Math.round((estimatedChars + charCount) / 2));
    } else {
      estimatedChars = Math.max(1, Math.round(estimatedChars * 0.6 + charCount * 0.4));
    }
    sealedCount += 1;
  };

  const sealPage = () => {
    const n = pageTextLen();
    pages.push(page.innerHTML.trim());
    noteSealedPageChars(n);
    measureHost.innerHTML = "";
    page = document.createElement("div");
    measureHost.appendChild(page);
  };

  const pageHasContent = () => {
    if (!page.childNodes.length) return false;
    const t = (page.textContent || "").replace(/\u200b/g, "").trim();
    if (t) return true;
    return Boolean(page.querySelector("img, br, hr, table, svg, video"));
  };

  const tryAppendTo = (parent, node) => {
    const clone = node.cloneNode(true);
    parent.appendChild(clone);
    if (!overflows()) return true;
    parent.removeChild(clone);
    return false;
  };

  const ATOMIC_TAGS = new Set([
    "IMG", "HR", "TABLE", "THEAD", "TBODY", "TR", "TD", "TH",
    "SVG", "VIDEO", "IFRAME", "CANVAS", "INPUT", "BUTTON", "SELECT", "TEXTAREA",
  ]);

  /** Binary-split text into parent so overflow continues on later pages. */
  const probeFits = (parent, text, len) => {
    if (len <= 0) return true;
    const probe = document.createTextNode(text.slice(0, len));
    parent.appendChild(probe);
    const ok = !overflows();
    parent.removeChild(probe);
    return ok;
  };

  const binaryBest = (parent, text, lo, hi) => {
    let best = 0;
    let a = Math.max(1, lo);
    let b = Math.max(a, hi);
    while (a <= b) {
      const mid = (a + b) >> 1;
      if (probeFits(parent, text, mid)) {
        best = mid;
        a = mid + 1;
      } else {
        b = mid - 1;
      }
    }
    return best;
  };

  const appendTextInto = (parent, fullText) => {
    let rest = String(fullText || "");
    if (!rest) return "";
    while (rest.length) {
      const used = pageTextLen();
      const capacity = Math.max(1, estimatedChars - used);
      const shortRest = rest.length <= 32;
      const restFitsWindow = rest.length <= Math.ceil(capacity * 1.1);
      const calibrateWide = sealedCount < 2;

      let best = 0;
      if (calibrateWide || shortRest || restFitsWindow) {
        best = binaryBest(parent, rest, 1, rest.length);
      } else {
        const winLo = Math.max(1, Math.floor(capacity * 0.9));
        const winHi = Math.min(rest.length, Math.max(winLo, Math.ceil(capacity * 1.1)));
        if (!probeFits(parent, rest, winLo)) {
          best = winLo <= 1 ? 0 : binaryBest(parent, rest, 1, winLo - 1);
        } else if (!probeFits(parent, rest, winHi)) {
          best = binaryBest(parent, rest, winLo, winHi);
          if (best < winLo) best = winLo;
        } else if (winHi >= rest.length) {
          best = rest.length;
        } else {
          best = binaryBest(parent, rest, winHi, rest.length);
          if (best < winHi) best = winHi;
        }
      }

      if (best <= 0) {
        if (pageHasContent()) {
          // Close current page; keep going with same parent tag via new page.
          sealPage();
          // After seal, parent is detached — caller must reopen wrappers.
          // Return remaining text so caller can resume.
          return rest;
        }
        // Empty page: force at least one character so we make progress.
        best = Math.min(1, rest.length) || 1;
      }
      parent.appendChild(document.createTextNode(rest.slice(0, best)));
      rest = rest.slice(best);
      if (rest.length) {
        sealPage();
        return rest;
      }
    }
    return "";
  };

  /**
   * Place a node into the current page. If it does not fit, split across pages.
   * openAncestors: array of element nodes (shallow clones) wrapping the content
   * so nested structure is preserved when spanning pages.
   */
  const placeNode = (node, openAncestors = []) => {
    if (!node) return;

    // Ensure wrapper chain exists on current page
    const ensureWrappers = () => {
      let parent = page;
      const live = [];
      for (const anc of openAncestors) {
        const el = anc.cloneNode(false);
        parent.appendChild(el);
        live.push(el);
        parent = el;
      }
      return { parent, live };
    };

    if (node.nodeType === 3) {
      let rest = String(node.textContent || "");
      while (rest) {
        const { parent } = ensureWrappers();
        const leftover = appendTextInto(parent, rest);
        if (!leftover) break;
        rest = leftover;
        // page was sealed; wrappers were discarded — loop recreates them
      }
      return;
    }

    if (node.nodeType !== 1) return;

    // Try placing the whole node (with wrappers) first
    {
      const { parent, live } = ensureWrappers();
      if (tryAppendTo(parent, node)) return;
      // Undo empty wrappers if nothing was added
      live.forEach((el) => {
        if (el.parentNode && !el.childNodes.length) el.remove();
      });
    }

    // Need a clean page if current page already has content
    if (pageHasContent()) {
      sealPage();
      const { parent, live } = ensureWrappers();
      if (tryAppendTo(parent, node)) return;
      live.forEach((el) => {
        if (el.parentNode && !el.childNodes.length) el.remove();
      });
    }

    // Atomic oversized node: force onto its own page (may clip, but rare)
    if (ATOMIC_TAGS.has(node.tagName) || node.tagName === "BR") {
      const { parent } = ensureWrappers();
      parent.appendChild(node.cloneNode(true));
      sealPage();
      return;
    }

    // Split children into clones of this element across pages
    const kids = [...node.childNodes];
    if (!kids.length) {
      const { parent } = ensureWrappers();
      parent.appendChild(node.cloneNode(false));
      return;
    }

    const nextAncestors = openAncestors.concat([node]);
    for (const kid of kids) {
      if (kid.nodeType === 3 && !String(kid.textContent || "").replace(/\u200b/g, "").length) {
        continue;
      }
      placeNode(kid, nextAncestors);
    }
  };

  for (const node of queue) {
    placeNode(node, []);
  }
  if (pageHasContent() || !pages.length) {
    pages.push(page.innerHTML.trim());
  }

  measureHost.remove();
  const out = pages.length ? pages : [""];
  const paginateMs = performance.now() - paginateT0;
  console.timeEnd("viewer:paginateHtmlToPages");
  console.log(
    `viewer:paginateHtmlToPages pages=${out.length} overflowChecks=${overflowChecks} htmlChars=${(html || "").length} ms=${Math.round(paginateMs)}`
  );
  if (viewerPerf) {
    viewerPerf.paginateMs += paginateMs;
    viewerPerf.overflowChecks += overflowChecks;
    viewerPerf.pages = out.length;
    viewerPerf.htmlChars = (html || "").length;
    publishViewerPerf();
  }
  return out;
}

function cancelBookFlipAnimation() {
  if (bookFlipTimer) {
    window.clearTimeout(bookFlipTimer);
    bookFlipTimer = null;
  }
  bookFlipBusy = false;
  const track = $("bookTrack");
  track?.querySelectorAll(".book-flip-leaf").forEach((el) => el.remove());
  track?.querySelector(".book-viewport")?.classList.remove("is-flipping");
}

function ensureBookViewport(track, vh) {
  track.hidden = false;
  track.style.width = "100%";
  track.style.height = `${vh}px`;
  track.style.transform = "";
  track.style.transition = "none";
  let viewport = track.querySelector(".book-viewport");
  if (!viewport) {
    track.innerHTML = `
      <div class="book-viewport">
        <div class="book-base">
          <div class="book-page book-page-left"><div class="book-page-inner"></div></div>
          <div class="book-page book-page-right"><div class="book-page-inner"></div></div>
        </div>
      </div>`;
    viewport = track.querySelector(".book-viewport");
  }
  return viewport;
}

function fillBookPageElement(pageEl, html, metrics = bookPageMetrics) {
  if (!pageEl) return;
  let inner = pageEl.querySelector(":scope > .book-page-inner");
  if (!inner) {
    inner = document.createElement("div");
    inner.className = "book-page-inner";
    pageEl.appendChild(inner);
  }
  const m = metrics.m;
  const fontPx = metrics.fontPx;
  inner.style.padding = `${m}px`;
  inner.style.fontSize = `${fontPx}px`;
  inner.style.lineHeight = String(metrics.lineHeight || 1.8);
  inner.innerHTML = html || "";
}

function makeBookFlipFace(faceClass, html, metrics = bookPageMetrics) {
  const face = document.createElement("div");
  face.className = `book-flip-face ${faceClass}`;
  const inner = document.createElement("div");
  inner.className = "book-page-inner";
  inner.style.padding = `${metrics.m}px`;
  inner.style.fontSize = `${metrics.fontPx}px`;
  inner.style.lineHeight = String(metrics.lineHeight || 1.8);
  inner.innerHTML = html || "";
  face.appendChild(inner);
  return face;
}

function paintBookSpread(index) {
  const track = $("bookTrack");
  const viewport = track?.querySelector(".book-viewport");
  if (!viewport) return;
  const left = viewport.querySelector(".book-page-left");
  const right = viewport.querySelector(".book-page-right");
  const i = Math.min(Math.max(0, index), Math.max(0, bookSpreadCount - 1));
  fillBookPageElement(left, bookPages[i * 2] || "", bookPageMetrics);
  fillBookPageElement(right, bookPages[i * 2 + 1] || "", bookPageMetrics);
}

/** Jump to a spread without animation (TOC, Home/End, re-layout). */
function showBookSpreadInstant(index) {
  cancelBookFlipAnimation();
  bookSpreadIndex = Math.min(Math.max(0, Number(index) || 0), Math.max(0, bookSpreadCount - 1));
  paintBookSpread(bookSpreadIndex);
  const left = bookSpreadIndex * 2;
  const right = left + 1;
  if (devicePageIndex !== left && devicePageIndex !== right) {
    devicePageIndex = left;
  }
  syncViewerViewAnchorFromIndex(devicePageIndex);
  updateBookPagerUi();
}

function prefersReducedBookMotion() {
  try {
    return Boolean(window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches);
  } catch (_) {
    return false;
  }
}

/**
 * 3D page-flip: text stays painted on each face; only the leaf rotates around the spine.
 * direction > 0: turn forward (right leaf → left)
 * direction < 0: turn backward (left leaf → right)
 */
function animateBookFlip(direction, toIndex) {
  const track = $("bookTrack");
  const viewport = track?.querySelector(".book-viewport");
  if (!viewport) {
    showBookSpreadInstant(toIndex);
    return;
  }
  const fromIndex = bookSpreadIndex;
  if (fromIndex === toIndex) return;

  const fromL = bookPages[fromIndex * 2] || "";
  const fromR = bookPages[fromIndex * 2 + 1] || "";
  const toL = bookPages[toIndex * 2] || "";
  const toR = bookPages[toIndex * 2 + 1] || "";

  const baseLeft = viewport.querySelector(".book-page-left");
  const baseRight = viewport.querySelector(".book-page-right");
  if (!baseLeft || !baseRight) {
    showBookSpreadInstant(toIndex);
    return;
  }

  cancelBookFlipAnimation();
  bookFlipBusy = true;
  updateBookPagerUi();
  viewport.classList.add("is-flipping");

  // Remove stale leaves
  viewport.querySelectorAll(".book-flip-leaf").forEach((el) => el.remove());

  const leaf = document.createElement("div");
  leaf.className = "book-flip-leaf";
  leaf.setAttribute("aria-hidden", "true");

  if (direction > 0) {
    // Under: left stays current; right shows destination right as leaf peels away.
    fillBookPageElement(baseLeft, fromL, bookPageMetrics);
    fillBookPageElement(baseRight, toR, bookPageMetrics);
    leaf.classList.add("is-forward");
    // Front of turning leaf = current right; back = next left
    leaf.appendChild(makeBookFlipFace("book-flip-front", fromR, bookPageMetrics));
    leaf.appendChild(makeBookFlipFace("book-flip-back", toL, bookPageMetrics));
  } else {
    // Under: right stays current; left shows destination left as leaf peels away.
    fillBookPageElement(baseLeft, toL, bookPageMetrics);
    fillBookPageElement(baseRight, fromR, bookPageMetrics);
    leaf.classList.add("is-backward");
    // Front of turning leaf = current left; back = previous right
    leaf.appendChild(makeBookFlipFace("book-flip-front", fromL, bookPageMetrics));
    leaf.appendChild(makeBookFlipFace("book-flip-back", toR, bookPageMetrics));
  }

  viewport.appendChild(leaf);

  let finished = false;
  const finish = () => {
    if (finished) return;
    finished = true;
    if (bookFlipTimer) {
      window.clearTimeout(bookFlipTimer);
      bookFlipTimer = null;
    }
    leaf.remove();
    viewport.classList.remove("is-flipping");
    bookSpreadIndex = toIndex;
    devicePageIndex = bookSpreadIndex * 2;
    bookFlipBusy = false;
    paintBookSpread(bookSpreadIndex);
    syncViewerViewAnchorFromIndex(devicePageIndex);
    updateBookPagerUi();
  };

  const onEnd = (event) => {
    if (event.target !== leaf) return;
    if (event.propertyName && event.propertyName !== "transform") return;
    finish();
  };
  leaf.addEventListener("transitionend", onEnd);

  // Kick off transition on next frames so initial pose paints first
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      if (!leaf.isConnected) return;
      leaf.classList.add("is-flipped");
    });
  });

  bookFlipTimer = window.setTimeout(finish, BOOK_FLIP_MS + 120);
}

function layoutBookPages({ resetPage = false } = {}) {
  if (viewerSettings.mode !== "book" || !isViewerOpen()) return;
  const scroll = $("viewerScroll");
  const body = $("viewerBody");
  const track = $("bookTrack");
  if (!scroll || !body || !track) return;
  if (scroll.clientWidth < 80 || scroll.clientHeight < 80) return;
  startViewerPageLayout({
    token: viewerLoadToken,
    jumpId: viewerPendingJumpSceneId,
    resetPage,
  });
}

/** @deprecated name kept for call sites — instant paint, no slide */
function applyBookSpreadTransform() {
  showBookSpreadInstant(bookSpreadIndex);
}

function updateBookPagerUi() {
  const pager = $("viewerBookPager");
  if (pager) {
    // Show leaf range: spread 0 → pages 1–2, etc.
    const leftNo = bookSpreadIndex * 2 + 1;
    const rightNo = bookSpreadIndex * 2 + 2;
    const totalLeaves = Math.max(leftNo, bookSpreadCount * 2);
    const flipping = bookFlipBusy ? i18n.t('app.넘기는_중') : "";
    pager.textContent = `${i18n.t('app.leftNo_rightNo_쪽_bookSp', {leftNo: leftNo, rightNo: rightNo, 'bookSpreadIndex + 1': bookSpreadIndex + 1, bookSpreadCount: bookSpreadCount, flipping: flipping})}`;
    pager.title = `${i18n.t('app.전체_약_totalLeaves_쪽', {totalLeaves: totalLeaves})}`;
  }
  setViewerBookNavVisible(true);
  const prev = $("viewerBookPrev");
  const next = $("viewerBookNext");
  if (prev) prev.disabled = bookFlipBusy || bookSpreadIndex <= 0;
  if (next) next.disabled = bookFlipBusy || bookSpreadIndex >= bookSpreadCount - 1;
}

function turnBookSpread(delta) {
  if (viewerSettings.mode !== "book" || !isViewerOpen()) return;
  if (bookFlipBusy) return;
  const dir = delta > 0 ? 1 : delta < 0 ? -1 : 0;
  if (!dir) return;
  const next = bookSpreadIndex + dir;
  if (next < 0 || next >= bookSpreadCount) return;
  if (prefersReducedBookMotion()) {
    showBookSpreadInstant(next);
    return;
  }
  animateBookFlip(dir, next);
}

function openViewerMode(preferredMode = null) {
  if (!state.sceneId) {
    toast(i18n.t('app.먼저_목차에서_씬_하나를_열어_주세요'));
    return;
  }
  const modal = $("viewerModal");
  const body = $("viewerBody");
  const mainEd = $("sceneContent");
  if (!modal || !body || !mainEd) return;

  viewerSettings = loadViewerSettings();
  if (preferredMode && VIEWER_MODES.includes(preferredMode)) {
    viewerSettings.mode = preferredMode;
  }
  syncViewerControlValues();
  syncViewerScopeTabs();
  setViewerTocOpen(viewerTocOpen);
  renderViewerToc();
  setViewerCommentsOpen(viewerCommentsOpen);
  if (viewerCommentsOpen && lastPersistedSceneStatus === "complete") {
    loadViewerReaderComments({ startIfNeeded: true }).catch(handleError);
  }

  const title = $("sceneTitle")?.value?.trim() || state.scene?.title || i18n.t('app.본문');
  if ($("viewerTitle")) {
    $("viewerTitle").textContent = viewerScope === "full"
      ? i18n.t('app.뷰어_전체_원고')
      : `${i18n.t('app.뷰어_title', {title: title})}`;
  }

  bookSpreadIndex = 0;
  viewerPendingJumpSceneId = null;
  if (viewerScope === "full") clearViewerEpisodeCache();
  $("splitPaneResizer")?.classList.add("hidden");
  $("focusWriteSplitResizer")?.classList.add("hidden");
  modal.classList.remove("hidden");
  document.body.classList.add("viewer-open");
  document.body.classList.toggle("viewer-maximized", isViewerMaximized());
  // Sync maximize button label in case preference was restored before button existed
  setViewerMaximized(isViewerMaximized(), { relayout: false });
  applyViewerLayout();
  applyViewerContent({ resetBook: true }).catch(handleError);
  syncViewerReaderCommentsButton({ pulse: true });
  if (viewerSettings.mode === "typeset") {
    renderTypesetPlatformTabs();
    ensureTypesetPresets()
      .then(() => {
        syncTypesetControlValues();
        applyViewerLayout();
      })
      .catch(handleError);
  }
}

function closeViewerMode() {
  stopViewerCommentsPolling();
  $("viewerModal")?.classList.add("hidden");
  document.body.classList.remove("viewer-open");
  viewerResize = null;
  viewerLoadToken += 1;
  viewerPageLayoutToken += 1;
  viewerEpisodePageSlots = [];
  viewerPageMetricsKey = "";
  viewerPendingJumpSceneId = null;
  viewerViewAnchor = null;
  cancelBookFlipAnimation();
  // Keep maximize preference, but clear transient body class
  document.body.classList.remove("viewer-maximized");
  if (typeof applySplitLayout === "function") {
    applySplitLayout();
  }
}

function isViewerMaximized() {
  return Boolean($("viewerModal")?.classList.contains("is-maximized"));
}

function setViewerMaximized(on, { relayout = true } = {}) {
  const modal = $("viewerModal");
  const btn = $("viewerMaximizeButton");
  const maximized = Boolean(on);
  modal?.classList.toggle("is-maximized", maximized);
  document.body.classList.toggle("viewer-maximized", maximized && isViewerOpen());
  if (btn) {
    btn.classList.toggle("is-active", maximized);
    btn.setAttribute("aria-pressed", maximized ? "true" : "false");
    btn.textContent = maximized ? i18n.t('app.창_모드') : i18n.t('app.최대화');
    btn.title = maximized ? i18n.t('app.원래_창_크기로') : i18n.t('app.뷰어_창_최대화');
  }
  try {
    localStorage.setItem("supertory.viewerMaximized", maximized ? "1" : "0");
  } catch (_) { /* ignore */ }

  if (!relayout || !isViewerOpen()) return;
  // Stage size changed — reflow pages after layout settles
  requestAnimationFrame(() => {
    applyViewerLayout();
    if (viewerSettings.mode === "book") scheduleBookPageLayout({ resetPage: false });
    else if (isDevicePagedMode()) scheduleDevicePageLayout({ resetPage: false });
  });
}

function toggleViewerMaximized() {
  setViewerMaximized(!isViewerMaximized());
}

function setupViewerMode() {
  viewerSettings = loadViewerSettings();
  // Restore maximize preference
  try {
    if (localStorage.getItem("supertory.viewerMaximized") === "1") {
      setViewerMaximized(true, { relayout: false });
    }
  } catch (_) { /* ignore */ }

  // Book icon on format toolbar (right of find)
  $("viewerModeButton")?.addEventListener("click", () => {
    openViewerMode();
  });

  $("viewerReaderCommentsButton")?.addEventListener("click", () => {
    if (!assertClusterFeature("reader_comments")) return;
    if ($("viewerReaderCommentsButton")?.disabled) return;
    const nextOpen = !viewerCommentsOpen;
    setViewerCommentsOpen(nextOpen);
    if (nextOpen) {
      markReaderCommentsStarted();
      loadViewerReaderComments({ startIfNeeded: true }).catch(handleError);
    }
  });
  $("viewerReaderCommentsClose")?.addEventListener("click", () => {
    setViewerCommentsOpen(false);
  });
  $("viewerReaderCommentsRefreshButton")?.addEventListener("click", () => {
    const btn = $("viewerReaderCommentsRefreshButton");
    if (!btn || btn.disabled || btn.classList.contains("hidden")) return;
    refreshViewerReaderComments().catch(handleError);
  });
  $("viewerReaderCommentsRetryButton")?.addEventListener("click", () => {
    const btn = $("viewerReaderCommentsRetryButton");
    const row = $("viewerReaderCommentsRetryRow");
    if (!btn || btn.disabled || row?.classList.contains("hidden")) return;
    refreshViewerReaderComments().catch(handleError);
  });

  $("viewerMaximizeButton")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    toggleViewerMaximized();
  });

  $("viewerModeTabs")?.addEventListener("click", (event) => {
    const tab = event.target.closest?.("[data-viewer-mode]");
    if (!tab) return;
    viewerSettings.mode = tab.dataset.viewerMode;
    if (viewerSettings.mode === "book") bookSpreadIndex = 0;
    if (isDevicePagedMode()) devicePageIndex = 0;
    const applyMode = () => {
      applyViewerLayout();
      if (viewerSettings.mode === "book") scheduleBookPageLayout({ resetPage: true });
      else if (isDevicePagedMode()) scheduleDevicePageLayout({ resetPage: true });
    };
    if (viewerSettings.mode === "typeset") {
      renderTypesetPlatformTabs();
      ensureTypesetPresets()
        .then(() => {
          syncTypesetControlValues();
          applyMode();
        })
        .catch(handleError);
      return;
    }
    applyMode();
  });

  $("viewerTypesetPlatforms")?.addEventListener("click", (event) => {
    if (event.target.closest?.("[data-typeset-add]")) {
      event.preventDefault();
      showTypesetNewPop();
      return;
    }
    const renameBtn = event.target.closest?.("[data-typeset-rename]");
    if (renameBtn) {
      event.preventDefault();
      const chip = renameBtn.closest("[data-typeset-platform]");
      if (chip) startTypesetRename(chip.dataset.typesetPlatform);
      return;
    }
    const delBtn = event.target.closest?.("[data-typeset-delete]");
    if (delBtn) {
      event.preventDefault();
      const chip = delBtn.closest("[data-typeset-platform]");
      if (chip) deleteTypesetPreset(chip.dataset.typesetPlatform).catch(handleError);
      return;
    }
    const tab = event.target.closest?.("[data-typeset-platform]");
    if (!tab) return;
    viewerSettings.typesetPlatform = normalizeTypesetPlatform(tab.dataset.typesetPlatform);
    saveViewerSettings();
    const apply = () => {
      syncTypesetControlValues();
      applyViewerLayout();
    };
    if (!typesetPresets) {
      ensureTypesetPresets().then(apply).catch(handleError);
      return;
    }
    apply();
  });
  $("viewerTypesetPlatforms")?.addEventListener("dblclick", (event) => {
    const label = event.target.closest?.("[data-typeset-label]");
    if (!label) return;
    const chip = label.closest("[data-typeset-platform]");
    if (chip) startTypesetRename(chip.dataset.typesetPlatform);
  });
  $("viewerTypesetNewConfirm")?.addEventListener("click", () => {
    createTypesetPresetFromPop().catch(handleError);
  });
  $("viewerTypesetNewCancel")?.addEventListener("click", () => hideTypesetNewPop());
  $("viewerTypesetNewLabel")?.addEventListener("keydown", (event) => {
    event.stopPropagation();
    if (event.key === "Enter") {
      event.preventDefault();
      createTypesetPresetFromPop().catch(handleError);
    } else if (event.key === "Escape") {
      event.preventDefault();
      hideTypesetNewPop();
    }
  });

  const bindTypesetField = (id) => {
    const el = $(id);
    if (!el) return;
    const relayout = () => {
      if (viewerSettings.mode !== "typeset") return;
      applyViewerLayout();
    };
    el.addEventListener("input", relayout);
    el.addEventListener("change", relayout);
  };
  [
    "viewerTypesetFont",
    "viewerTypesetFontSize",
    "viewerTypesetLineHeight",
    "viewerTypesetLetterSpacing",
    "viewerTypesetIndent",
    "viewerTypesetParaSpacing",
    "viewerTypesetMarginLeft",
    "viewerTypesetMarginRight",
    "viewerTypesetMarginTop",
    "viewerTypesetMarginBottom",
    "viewerTypesetViewport",
  ].forEach(bindTypesetField);

  $("viewerTypesetSave")?.addEventListener("click", () => {
    saveTypesetPresetFromForm().catch(handleError);
  });
  $("viewerTypesetExport")?.addEventListener("click", (event) => {
    event.stopPropagation();
    toggleTypesetExportMenu();
  });
  $("viewerTypesetExportMenu")?.addEventListener("click", (event) => {
    const btn = event.target.closest?.("[data-typeset-export]");
    if (!btn) return;
    event.preventDefault();
    exportTypesetFile(btn.dataset.typesetExport).catch(handleError);
  });
  document.addEventListener("click", (event) => {
    if (!event.target.closest?.(".viewer-typeset-export-wrap")) {
      hideTypesetExportMenu();
    }
  });

  // Current scene vs full manuscript
  $("viewerScopeTabs")?.addEventListener("click", (event) => {
    const tab = event.target.closest?.("[data-viewer-scope]");
    if (!tab) return;
    const next = tab.dataset.viewerScope === "full" ? "full" : "scene";
    if (next === viewerScope) return;
    setViewerScope(next).catch(handleError);
  });

  $("viewerTocToggle")?.addEventListener("click", () => {
    setViewerTocOpen(!viewerTocOpen);
    if (viewerTocOpen) renderViewerToc();
  });
  $("viewerTocClose")?.addEventListener("click", () => {
    setViewerTocOpen(false);
  });

  $("viewerTocList")?.addEventListener("click", (event) => {
    const btn = event.target.closest?.("[data-viewer-toc-scene]");
    if (!btn) return;
    const id = Number(btn.dataset.viewerTocScene);
    if (!Number.isFinite(id) || id <= 0) return;
    onViewerTocSelect(id).catch(handleError);
  });

  const bindRange = (id, key, labelId, { isLineHeight = false } = {}) => {
    $(id)?.addEventListener("input", () => {
      let v = Number($(id).value);
      if (!Number.isFinite(v)) return;
      if (isLineHeight) {
        v = clampViewerLineHeight(v, 1.8);
        viewerSettings[key] = v;
        if ($(labelId)) $(labelId).textContent = formatViewerLineHeightLabel(v);
      } else {
        viewerSettings[key] = v;
        if ($(labelId)) $(labelId).textContent = String(v);
      }
      applyViewerLayout();
      if (viewerSettings.mode === "book"
        && (key === "bookFont" || key === "bookMargin" || key === "bookW" || key === "bookH"
          || key === "bookLineHeight")) {
        scheduleBookPageLayout({ resetPage: false });
      }
      if (isDevicePagedMode()
        && (key === "pdfFont" || key === "pdfMargin" || key === "pdfLineHeight"
          || key === "phoneFont" || key === "phoneW" || key === "phoneH" || key === "phoneLineHeight"
          || key === "einkFont" || key === "einkW" || key === "einkH" || key === "einkLineHeight")) {
        scheduleDevicePageLayout({ resetPage: false });
      }
    });
  };
  bindRange("viewerPdfFont", "pdfFont", "viewerPdfFontVal");
  bindRange("viewerPdfLineHeight", "pdfLineHeight", "viewerPdfLineHeightVal", { isLineHeight: true });
  bindRange("viewerPdfMargin", "pdfMargin", "viewerPdfMarginVal");
  // PDF size slider: zoom only (A4 ratio fixed, page breaks stay put)
  $("viewerPdfScale")?.addEventListener("input", () => {
    const v = Number($("viewerPdfScale").value);
    if (!Number.isFinite(v)) return;
    viewerSettings.pdfScale = Math.min(120, Math.max(55, v));
    if ($("viewerPdfScaleVal")) $("viewerPdfScaleVal").textContent = String(viewerSettings.pdfScale);
    saveViewerSettings();
    if (viewerSettings.mode !== "pdf" || !isViewerOpen()) return;
    const scale = viewerSettings.pdfScale / 100;
    const frame = $("viewerFrame");
    if (frame) {
      frame.style.width = `${Math.round(A4_WIDTH_PX * scale)}px`;
      frame.style.maxWidth = "100%";
    }
    devicePageMetrics = { ...devicePageMetrics, scale: viewerSettings.pdfScale };
    paintDevicePageStack();
    requestAnimationFrame(() => showDevicePage(devicePageIndex, { smooth: false }));
  });
  bindRange("viewerBookFont", "bookFont", "viewerBookFontVal");
  bindRange("viewerBookLineHeight", "bookLineHeight", "viewerBookLineHeightVal", { isLineHeight: true });
  bindRange("viewerBookMargin", "bookMargin", "viewerBookMarginVal");
  bindRange("viewerBookW", "bookW", "viewerBookWVal");
  bindRange("viewerBookH", "bookH", "viewerBookHVal");
  bindRange("viewerPhoneFont", "phoneFont", "viewerPhoneFontVal");
  bindRange("viewerPhoneLineHeight", "phoneLineHeight", "viewerPhoneLineHeightVal", { isLineHeight: true });
  bindRange("viewerPhoneW", "phoneW", "viewerPhoneWVal");
  bindRange("viewerPhoneH", "phoneH", "viewerPhoneHVal");
  bindRange("viewerEinkFont", "einkFont", "viewerEinkFontVal");
  bindRange("viewerEinkLineHeight", "einkLineHeight", "viewerEinkLineHeightVal", { isLineHeight: true });
  bindRange("viewerEinkW", "einkW", "viewerEinkWVal");
  bindRange("viewerEinkH", "einkH", "viewerEinkHVal");

  $("viewerBookPaper")?.addEventListener("change", () => {
    viewerSettings.bookPaper = $("viewerBookPaper").value || "cream";
    applyViewerLayout();
    scheduleBookPageLayout({ resetPage: false });
  });

  $("viewerBookPrev")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (viewerSettings.mode === "book") turnBookSpread(-1);
    else if (viewerSettings.mode === "phone" || viewerSettings.mode === "eink") turnDevicePage(-1);
  });
  $("viewerBookNext")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (viewerSettings.mode === "book") turnBookSpread(1);
    else if (viewerSettings.mode === "phone" || viewerSettings.mode === "eink") turnDevicePage(1);
  });

  // Click left/right page area to turn (book + phone/eink page mode; not PDF / not scroll-down)
  $("viewerScroll")?.addEventListener("click", (event) => {
    if (!isViewerOpen()) return;
    if (event.target.closest?.(".viewer-book-nav, .viewer-resize-handle")) return;
    const mode = viewerSettings.mode;
    if (mode !== "book" && mode !== "phone" && mode !== "eink") return;
    // Continuous scroll: don't steal clicks for page turns
    if ((mode === "phone" || mode === "eink") && isDeviceScrollFlow(mode)) return;
    const scroll = $("viewerScroll");
    if (!scroll) return;
    const rect = scroll.getBoundingClientRect();
    const x = event.clientX - rect.left;
    if (x < rect.width * 0.42) {
      if (mode === "book") turnBookSpread(-1);
      else turnDevicePage(-1);
    } else if (x > rect.width * 0.58) {
      if (mode === "book") turnBookSpread(1);
      else turnDevicePage(1);
    }
  });

  // Book: wheel = page turn. phone/eink page mode: wheel = page turn.
  // phone/eink scroll mode: natural free scroll (do not preventDefault).
  $("viewerScroll")?.addEventListener("wheel", (event) => {
    if (!isViewerOpen()) return;
    const mode = viewerSettings.mode;
    if (mode === "book") {
      event.preventDefault();
      if (Math.abs(event.deltaY) < 4 && Math.abs(event.deltaX) < 4) return;
      if (event.deltaY > 0 || event.deltaX > 0) turnBookSpread(1);
      else turnBookSpread(-1);
      return;
    }
    if (mode === "phone" || mode === "eink") {
      if (isDeviceScrollFlow(mode)) {
        // Native scroll; refresh pager affordances after a beat
        window.setTimeout(() => updateDevicePagerUi(), 80);
        return;
      }
      event.preventDefault();
      if (Math.abs(event.deltaY) < 4 && Math.abs(event.deltaX) < 4) return;
      if (event.deltaY > 0 || event.deltaX > 0) turnDevicePage(1);
      else turnDevicePage(-1);
    }
  }, { passive: false });

  // Scroll-down mode: update prev/next enable state while user scrolls
  $("viewerScroll")?.addEventListener("scroll", () => {
    if (!isViewerOpen()) return;
    if (!isDeviceScrollFlow()) return;
    updateDevicePagerUi();
  }, { passive: true });

  $("viewerStage")?.addEventListener("scroll", () => {
    if (!isViewerOpen()) return;
    if (viewerSettings.mode === "pdf") syncDevicePageIndexFromScroll();
  }, { passive: true });

  // Touch swipe: book horizontal; phone/eink page mode = page turn; scroll mode = native pan
  let bookTouch = null;
  $("viewerScroll")?.addEventListener("touchstart", (event) => {
    const mode = viewerSettings.mode;
    if (mode !== "book" && mode !== "phone" && mode !== "eink") return;
    // Continuous scroll uses native touch scrolling
    if ((mode === "phone" || mode === "eink") && isDeviceScrollFlow(mode)) return;
    const t = event.changedTouches?.[0];
    if (!t) return;
    bookTouch = { x: t.clientX, y: t.clientY, mode };
  }, { passive: true });
  $("viewerScroll")?.addEventListener("touchend", (event) => {
    if (!bookTouch || !isViewerOpen()) return;
    const t = event.changedTouches?.[0];
    if (!t) return;
    const dx = t.clientX - bookTouch.x;
    const dy = t.clientY - bookTouch.y;
    const mode = bookTouch.mode;
    bookTouch = null;
    if (mode === "book") {
      if (Math.abs(dx) < 40 || Math.abs(dx) < Math.abs(dy)) return;
      if (dx < 0) turnBookSpread(1);
      else turnBookSpread(-1);
      return;
    }
    // phone / eink page-turn: swipe in either axis turns page
    if (Math.abs(dx) < 36 && Math.abs(dy) < 36) return;
    if (Math.abs(dx) >= Math.abs(dy)) {
      if (dx < 0) turnDevicePage(1);
      else turnDevicePage(-1);
    } else {
      if (dy < 0) turnDevicePage(1);
      else turnDevicePage(-1);
    }
  }, { passive: true });
  $("viewerPhoneBg")?.addEventListener("change", () => {
    const sel = $("viewerPhoneBg");
    viewerSettings.phoneBg = sel.value;
    const opt = sel.selectedOptions?.[0];
    viewerSettings.phoneInk = opt?.dataset?.ink || "#24211d";
    applyViewerLayout();
    if (isDevicePagedMode()) scheduleDevicePageLayout({ resetPage: false });
  });
  $("viewerPhoneFlow")?.addEventListener("change", () => {
    viewerSettings.phoneFlow = normalizeDeviceFlow($("viewerPhoneFlow")?.value, "page");
    applyViewerLayout();
    if (isDevicePagedMode()) scheduleDevicePageLayout({ resetPage: true });
  });
  $("viewerEinkStyle")?.addEventListener("change", () => {
    viewerSettings.einkStyle = $("viewerEinkStyle").value || "paper";
    applyViewerLayout();
    if (isDevicePagedMode()) scheduleDevicePageLayout({ resetPage: false });
  });
  $("viewerEinkFlow")?.addEventListener("change", () => {
    viewerSettings.einkFlow = normalizeDeviceFlow($("viewerEinkFlow")?.value, "page");
    applyViewerLayout();
    if (isDevicePagedMode()) scheduleDevicePageLayout({ resetPage: true });
  });

  // Drag resize for book / phone / eink (document-level move so vertical drag keeps working)
  const handle = $("viewerResizeHandle");
  const onResizeMove = (event) => {
    if (!viewerResize) return;
    if (viewerResize.pointerId != null && event.pointerId !== viewerResize.pointerId) return;
    event.preventDefault();
    const dw = event.clientX - viewerResize.startX;
    const dh = event.clientY - viewerResize.startY;
    let w = Math.round(viewerResize.startW + dw);
    let h = Math.round(viewerResize.startH + dh);
    if (viewerResize.mode === "phone") {
      w = Math.min(430, Math.max(280, w));
      h = Math.min(900, Math.max(480, h));
      viewerSettings.phoneW = w;
      viewerSettings.phoneH = h;
    } else if (viewerResize.mode === "book") {
      w = Math.min(1040, Math.max(640, w));
      h = Math.min(900, Math.max(420, h));
      viewerSettings.bookW = w;
      viewerSettings.bookH = h;
    } else {
      w = Math.min(560, Math.max(300, w));
      h = Math.min(900, Math.max(480, h));
      viewerSettings.einkW = w;
      viewerSettings.einkH = h;
    }
    syncViewerControlValues();
    applyViewerLayout();
    if (viewerResize?.mode === "book") scheduleBookPageLayout({ resetPage: false });
    else if (viewerResize?.mode === "phone" || viewerResize?.mode === "eink") {
      scheduleDevicePageLayout({ resetPage: false });
    }
  };
  const onResizeEnd = (event) => {
    if (!viewerResize) return;
    if (viewerResize.pointerId != null && event.pointerId != null
      && event.pointerId !== viewerResize.pointerId) return;
    const wasBook = viewerResize.mode === "book";
    const wasDevice = viewerResize.mode === "phone" || viewerResize.mode === "eink";
    viewerResize = null;
    document.removeEventListener("pointermove", onResizeMove, true);
    document.removeEventListener("pointerup", onResizeEnd, true);
    document.removeEventListener("pointercancel", onResizeEnd, true);
    saveViewerSettings();
    if (wasBook) scheduleBookPageLayout({ resetPage: false });
    else if (wasDevice) scheduleDevicePageLayout({ resetPage: false });
  };
  handle?.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    const mode = viewerSettings.mode;
    if (mode !== "phone" && mode !== "eink" && mode !== "book") return;
    event.preventDefault();
    event.stopPropagation();
    const frame = $("viewerFrame");
    if (!frame) return;
    const rect = frame.getBoundingClientRect();
    viewerResize = {
      mode,
      startX: event.clientX,
      startY: event.clientY,
      startW: rect.width,
      startH: rect.height,
      pointerId: event.pointerId,
    };
    document.addEventListener("pointermove", onResizeMove, true);
    document.addEventListener("pointerup", onResizeEnd, true);
    document.addEventListener("pointercancel", onResizeEnd, true);
    try { handle.setPointerCapture?.(event.pointerId); } catch (_) { /* ignore */ }
  });

  document.querySelectorAll("[data-close-viewer]").forEach((el) => {
    el.addEventListener("click", closeViewerMode);
  });
  document.addEventListener("keydown", (event) => {
    if (!isViewerOpen()) return;
    if (event.key === "Escape") {
      event.preventDefault();
      closeViewerMode();
      return;
    }
    const mode = viewerSettings.mode;
    if (mode === "book") {
      if (event.key === "ArrowRight" || event.key === "PageDown" || event.key === " ") {
        event.preventDefault();
        turnBookSpread(1);
      } else if (event.key === "ArrowLeft" || event.key === "PageUp") {
        event.preventDefault();
        turnBookSpread(-1);
      } else if (event.key === "Home") {
        event.preventDefault();
        showBookSpreadInstant(0);
      } else if (event.key === "End") {
        event.preventDefault();
        showBookSpreadInstant(Math.max(0, bookSpreadCount - 1));
      }
      return;
    }
    if (mode === "phone" || mode === "eink") {
      if (event.key === "ArrowRight" || event.key === "PageDown" || event.key === " ") {
        event.preventDefault();
        turnDevicePage(1);
      } else if (event.key === "ArrowLeft" || event.key === "PageUp") {
        event.preventDefault();
        turnDevicePage(-1);
      } else if (event.key === "Home") {
        event.preventDefault();
        showDevicePage(0, { smooth: false });
      } else if (event.key === "End") {
        event.preventDefault();
        showDevicePage(Math.max(0, devicePageCount - 1), { smooth: false });
      }
      return;
    }
    // PDF: arrow/page keys scroll one A4 sheet at a time (no side buttons)
    if (mode === "pdf") {
      if (event.key === "ArrowDown" || event.key === "PageDown" || event.key === " ") {
        event.preventDefault();
        turnDevicePage(1);
      } else if (event.key === "ArrowUp" || event.key === "PageUp") {
        event.preventDefault();
        turnDevicePage(-1);
      } else if (event.key === "Home") {
        event.preventDefault();
        showDevicePage(0, { smooth: false });
      } else if (event.key === "End") {
        event.preventDefault();
        showDevicePage(Math.max(0, devicePageCount - 1), { smooth: false });
      }
    }
  });
}

function handleToolsAction(action) {
  if (action === "import") {
    openImportModal();
    return;
  }
  if (action === "focus-write") {
    openFocusWrite();
    return;
  }
  if (action === "viewer-mode") {
    openViewerMode();
    return;
  }
  if (action === "world-scan") {
    // Kept for binder / legacy tools; prefer Analyze menu → 설정 붕괴 감지기.
    runWorldScan().catch(handleError);
    return;
  }
  if (action === "tory-analyze") {
    if (!state.sceneId) {
      toast(i18n.t('app.먼저_목차에서_씬_하나를_열어_주세요'));
      return;
    }
    const title = state.scene?.title || $("sceneTitle")?.value || "";
    startToryAnalyzeForScene(state.sceneId, title).catch(handleError);
    return;
  }
  if (action === "writing-log") {
    toggleWritingRecording();
    return;
  }
  if (action === "bookmark-list") {
    toggleBookmarkListPanel();
    return;
  }

  if (action === "notes" || action === "characters" || action === "links" || action === "spellcheck") {
    openSceneToolsDrawer(action);
    // 맞춤법: 패널만 열고, 검사는 「Gemini 검사기」/「바른한글 검사기」에서만 실행
  }
}

function setBrowserSpellcheckEnabled(enabled) {
  const on = Boolean(enabled);
  ["sceneContent", "synopsisContent", "splitSceneBodyEditor"].forEach((id) => {
    const el = $(id);
    if (!el) return;
    el.setAttribute("spellcheck", on ? "true" : "false");
    el.spellcheck = on;
  });
  try {
    localStorage.setItem("supertory.browserSpellcheck", on ? "1" : "0");
  } catch (_) {
    /* ignore */
  }
}

function replaceTextInContentEditable(editor, original, replacement) {
  if (!editor || !original) return false;
  const walker = document.createTreeWalker(editor, NodeFilter.SHOW_TEXT);
  let node = walker.nextNode();
  while (node) {
    const value = node.nodeValue || "";
    const idx = value.indexOf(original);
    if (idx >= 0) {
      node.nodeValue = value.slice(0, idx) + replacement + value.slice(idx + original.length);
      return true;
    }
    node = walker.nextNode();
  }
  // Fallback: plain text replace once (may lose some rich spans if not found in text nodes).
  const plain = editor.innerText || "";
  const at = plain.indexOf(original);
  if (at < 0) return false;
  // Last resort: replace first HTML text occurrence carefully
  const html = editor.innerHTML || "";
  const escaped = original.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const next = html.replace(new RegExp(escaped), () => {
    // Keep simple text; if original had no tags this is fine.
    return replacement
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  });
  if (next === html) return false;
  editor.innerHTML = next;
  return true;
}

function renderSpellcheckResults(payload) {
  const list = $("spellcheckResultList");
  const status = $("spellcheckStatus");
  if (!list) return;
  const errors = payload?.errors || [];
  list.dataset.hasResults = "1";
  if (status) {
    const provider = payload?.provider_label || payload?.provider || "";
    status.textContent = provider
      ? `${payload.message || ""} · ${provider}`
      : (payload?.message || "");
  }
  if (!errors.length) {
    list.innerHTML = `${i18n.t('app.p_class_hint_spellcheck', {'escapeHtml(payload?.message || "오류가 없습니다.")': escapeHtml(payload?.message || "오류가 없습니다.")})}`;
    return;
  }
  list.innerHTML = errors.map((err, index) => {
    const original = escapeHtml(err.original || "");
    const help = escapeHtml(err.help || "");
    const method = escapeHtml(err.method_label || i18n.t('app.교정'));
    const suggestions = (err.suggestions || []).map((s) => `
      <button type="button" data-spell-apply="${index}" data-suggestion="${escapeHtml(s)}" title="${i18n.t('app.이_표현으로_바꾸기')}">
        ${escapeHtml(s)}
      </button>`).join("");
    return `
      <article class="spellcheck-item" data-spell-index="${index}">
        <div class="spellcheck-item-head">
          <span class="spellcheck-original">${original}</span>
          <span class="spellcheck-method">${method}</span>
        </div>
        ${help ? `<p class="spellcheck-help">${help}</p>` : ""}
        <div class="spellcheck-suggestions">
          ${suggestions || i18n.t('app.span_class_hint_제안_없음_s')}
        </div>
      </article>`;
  }).join("");

  // stash raw errors for apply handlers
  list._spellErrors = errors;
}

async function runSpellcheck(options = {}) {
  const prefer = options.prefer || "auto"; // auto | gemini
  const editor = getActiveRichEditor() || $("sceneContent");
  if (!editor) return toast(i18n.t('app.검사할_편집기가_없어요'));
  const text = getEditorPlainText(editor).trim();
  if (!text) return toast(i18n.t('app.검사할_글을_먼저_적어_주세요'));

  const status = $("spellcheckStatus");
  const button = $("runSpellcheckButton");
  const publicBtn = $("runSpellcheckPublicButton");
  if (status) {
    status.textContent = prefer === "gemini"
      ? i18n.t('app.Gemini_검사기로_검사_중')
      : prefer === "public"
        ? i18n.t('app.바른한글_검사기에_연결_중')
        : i18n.t('app.맞춤법_검사_중_Gemini_우선');
  }
  if (button) {
    button.disabled = true;
    if (prefer !== "public") button.textContent = i18n.t('app.검사_중');
  }
  if (publicBtn) publicBtn.disabled = true;
  try {
    const result = await api("/api/spellcheck", {
      method: "POST",
      body: JSON.stringify({ text, prefer }),
    });
    renderSpellcheckResults(result);
    toast(result.error_count ? `${i18n.t('app.맞춤법_제안_result_error_coun', {'result.error_count': result.error_count})}` : i18n.t('app.맞춤법_검사_완료'));
  } catch (error) {
    let message = error.message || i18n.t('app.검사에_실패했습니다');
    // Old Python process (before spellcheck was added) returns this for unknown routes.
    if (/알 수 없는 요청/.test(message)) {
      message = i18n.t('app.맞춤법_API를_찾을_수_없습니다_Super');
    }
    if (status) status.textContent = message;
    const list = $("spellcheckResultList");
    if (list) {
      list.dataset.hasResults = "1";
      list.innerHTML = `<p class="hint spellcheck-empty">${escapeHtml(message)}</p>`;
    }
    throw new Error(message);
  } finally {
    if (button) {
      button.disabled = false;
      button.textContent = i18n.t('app.Gemini_검사기');
    }
    if (publicBtn) publicBtn.disabled = false;
  }
}

function setupSpellcheckPanel() {
  // Restore browser underline preference.
  let browserOn = true;
  try {
    const stored = localStorage.getItem("supertory.browserSpellcheck");
    if (stored === "0") browserOn = false;
  } catch (_) {
    browserOn = true;
  }
  setBrowserSpellcheckEnabled(browserOn);
  const toggle = $("browserSpellcheckToggle");
  if (toggle) {
    toggle.checked = browserOn;
    toggle.addEventListener("change", () => {
      setBrowserSpellcheckEnabled(toggle.checked);
      toast(toggle.checked ? i18n.t('app.브라우저_철자_밑줄을_켰어요') : i18n.t('app.브라우저_철자_밑줄을_껐어요'));
    });
  }

  $("runSpellcheckButton")?.addEventListener("click", () => runSpellcheck({ prefer: "auto" }).catch(handleError));
  $("runSpellcheckPublicButton")?.addEventListener("click", () => runSpellcheck({ prefer: "public" }).catch(handleError));
  $("spellcheckResultList")?.addEventListener("click", (event) => {
    const btn = event.target.closest?.("[data-spell-apply]");
    if (!btn) return;
    event.preventDefault();
    const list = $("spellcheckResultList");
    const errors = list?._spellErrors || [];
    const index = Number(btn.dataset.spellApply);
    const err = errors[index];
    const suggestion = btn.dataset.suggestion || "";
    if (!err?.original || !suggestion) return;
    const editor = getActiveRichEditor() || $("sceneContent");
    if (!editor) return;
    const ok = replaceTextInContentEditable(editor, err.original, suggestion);
    if (!ok) {
      toast(i18n.t('app.본문에서_해당_표현을_찾지_못했어요_직접_고'));
      return;
    }
    updateEditorPlaceholder(editor);
    if (editor.id === "sceneContent") {
      updateSceneStats();
      markSceneDirty();
    } else if (editor.id === "synopsisContent" || editor.id === "synopsisContentB") {
      markSettingsDocEditorDirty(editor);
    } else if (editor.id === "splitSceneBodyEditor") {
      markSplitDirty?.();
    }
    toast(`${i18n.t('app.err_original_suggestion', {'err.original': err.original, suggestion: suggestion})}`);
  });
}

/* ── Manuscript toolbar collapse (meta / format-icons / format-format / feature) ── */
const MS_TOOLBAR_COLLAPSE_KEY = "supertory.msToolbarCollapsed";
const MS_FORMAT_ROW_KEYS = ["format-icons", "format-format"];

function normalizeMsToolbarKey(which) {
  if (which === "feature") return "feature";
  if (which === "meta" || which === "synopsis") return "meta";
  if (which === "format-icons" || which === "icons") return "format-icons";
  if (which === "format-format" || which === "format-tools") return "format-format";
  // legacy: whole format shell → both format rows
  if (which === "format") return "format";
  return "format";
}

function defaultMsToolbarCollapsedMap() {
  return {
    meta: false,
    "format-icons": false,
    "format-format": false,
    feature: false,
  };
}

function loadMsToolbarCollapsed() {
  try {
    const raw = localStorage.getItem(MS_TOOLBAR_COLLAPSE_KEY);
    const obj = raw ? JSON.parse(raw) : null;
    if (!obj || typeof obj !== "object") return defaultMsToolbarCollapsedMap();
    const map = defaultMsToolbarCollapsedMap();
    map.meta = Boolean(obj.meta);
    map.feature = Boolean(obj.feature);
    // Prefer per-row flags; migrate legacy `format` to both rows
    if (obj["format-icons"] != null || obj["format-format"] != null) {
      map["format-icons"] = Boolean(obj["format-icons"]);
      map["format-format"] = Boolean(obj["format-format"]);
    } else if (obj.format) {
      map["format-icons"] = true;
      map["format-format"] = true;
    }
    return map;
  } catch (_) {
    return defaultMsToolbarCollapsedMap();
  }
}

function saveMsToolbarCollapsed(stateMap) {
  try {
    localStorage.setItem(MS_TOOLBAR_COLLAPSE_KEY, JSON.stringify(stateMap));
  } catch (_) {
    /* ignore */
  }
}

function msToolbarReopenButton(key) {
  if (key === "meta") return $("editorMetaReopenButton");
  if (key === "feature") return $("sceneFeatureBarReopenButton");
  if (key === "format-icons") return $("formatIconsReopenButton");
  if (key === "format-format") return $("formatFormatReopenButton");
  return null;
}

function isFormatRowKey(key) {
  return key === "format-icons" || key === "format-format";
}

function syncFormatShellFromRows() {
  const shell = document.querySelector('.ms-toolbar-shell[data-toolbar-shell="format"]');
  if (!shell) return;
  const iconsRow = document.querySelector('[data-toolbar-row="format-icons"]');
  const formatRow = document.querySelector('[data-toolbar-row="format-format"]');
  const iconsGone = !iconsRow || iconsRow.classList.contains("is-collapsed");
  const formatGone = !formatRow || formatRow.classList.contains("is-collapsed");
  const bothGone = iconsGone && formatGone;
  shell.classList.toggle("is-collapsed", bothGone);
  shell.classList.toggle("format-icons-collapsed", iconsGone);
  shell.classList.toggle("format-format-collapsed", formatGone);
  // Hide find bar when the icons row (find toggle lives there) is collapsed
  if (iconsGone) {
    $("findBar")?.classList.add("hidden");
    $("findToggleButton")?.setAttribute("aria-expanded", "false");
  }
}

function syncMsChromeReopenStrip() {
  const strip = $("msChromeReopenStrip");
  if (!strip) return;
  const anyVisible = Array.from(strip.querySelectorAll("[data-toolbar-show]")).some(
    (btn) => !btn.hidden && !btn.classList.contains("hidden")
  );
  strip.hidden = !anyVisible;
}

function refreshManuscriptLayoutAfterChromeChange() {
  if (state.splitEnabled && state.splitMode === "split" && typeof layoutSplitPrimaryPane === "function") {
    requestAnimationFrame(() => layoutSplitPrimaryPane());
  }
}

function applyMsToolbarCollapsed(which, collapsed, { persist = true, toastMsg = true } = {}) {
  const key = normalizeMsToolbarKey(which);

  // Legacy: collapse/show entire format → both rows
  if (key === "format") {
    applyMsToolbarCollapsed("format-icons", collapsed, { persist, toastMsg: false });
    applyMsToolbarCollapsed("format-format", collapsed, { persist, toastMsg: false });
    if (toastMsg && collapsed) toast(i18n.t('app.서식_도구를_숨겼어요'));
    if (toastMsg && !collapsed) toast(i18n.t('app.서식_도구를_다시_열었어요'));
    return;
  }

  if (isFormatRowKey(key)) {
    const row = document.querySelector(`[data-toolbar-row="${key}"]`);
    const reopen = msToolbarReopenButton(key);
    if (!row) return;
    row.classList.toggle("is-collapsed", Boolean(collapsed));
    if (reopen) {
      reopen.hidden = !collapsed;
      reopen.classList.toggle("hidden", !collapsed);
    }
    syncFormatShellFromRows();
    syncMsChromeReopenStrip();
    if (persist) {
      const map = loadMsToolbarCollapsed();
      map[key] = Boolean(collapsed);
      saveMsToolbarCollapsed(map);
    }
    refreshManuscriptLayoutAfterChromeChange();
    if (toastMsg && collapsed) {
      toast(key === "format-icons" ? i18n.t('app.도구_아이콘을_숨겼어요') : i18n.t('app.서식_도구를_숨겼어요'));
    }
    return;
  }

  const shell = document.querySelector(
    `.ms-toolbar-shell[data-toolbar-shell="${key}"], [data-toolbar-shell="${key}"]#editorMetaShell, [data-toolbar-shell="${key}"].scene-synopsis-in-status`,
  ) || document.querySelector(`[data-toolbar-shell="${key}"]`);
  const reopen = msToolbarReopenButton(key);
  if (!shell) return;
  shell.classList.toggle("is-collapsed", Boolean(collapsed));
  if (key === "meta") shell.hidden = Boolean(collapsed);
  if (reopen) {
    reopen.hidden = !collapsed;
    reopen.classList.toggle("hidden", !collapsed);
  }
  syncMsChromeReopenStrip();
  if (persist) {
    const map = loadMsToolbarCollapsed();
    map[key] = Boolean(collapsed);
    saveMsToolbarCollapsed(map);
  }
  refreshManuscriptLayoutAfterChromeChange();
  if (toastMsg && collapsed) {
    const msg =
      key === "meta" ? i18n.t('app.요약_칸을_숨겼어요')
        : key === "feature" ? i18n.t('app.기능_바를_숨겼어요')
          : i18n.t('app.도구를_숨겼어요');
    toast(msg);
  }
}

function setupManuscriptToolbarCollapse() {
  const map = loadMsToolbarCollapsed();
  applyMsToolbarCollapsed("meta", map.meta, { persist: false, toastMsg: false });
  applyMsToolbarCollapsed("format-icons", map["format-icons"], { persist: false, toastMsg: false });
  applyMsToolbarCollapsed("format-format", map["format-format"], { persist: false, toastMsg: false });
  applyMsToolbarCollapsed("feature", map.feature, { persist: false, toastMsg: false });

  document.querySelectorAll("[data-toolbar-hide]").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      applyMsToolbarCollapsed(btn.dataset.toolbarHide || "format-format", true);
    });
  });
  document.querySelectorAll("[data-toolbar-show]").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const which = btn.dataset.toolbarShow || "format-format";
      applyMsToolbarCollapsed(which, false, { toastMsg: false });
      const key = normalizeMsToolbarKey(which);
      toast(
        key === "meta" ? i18n.t('app.요약_칸을_다시_열었어요')
          : key === "feature" ? i18n.t('app.기능_바를_다시_열었어요')
            : key === "format-icons" ? i18n.t('app.도구_아이콘을_다시_열었어요')
              : i18n.t('app.서식_도구를_다시_열었어요')
      );
    });
  });
}

function setupSceneFeatureBar() {
  // import is opened from the header + create menu (setupCreateMenu)
  setupManuscriptToolbarCollapse();

  const onToolsActionClick = (event) => {
    // Don't treat hide / analyze menu toggle as a tools action
    if (event.target.closest?.("[data-toolbar-hide]")) return;
    if (event.target.closest?.("#analyzeMenuButton")) return;
    if (event.target.closest?.("#analyzeMenuDropdown")) return;
    // writing log has its own click handler (setupWritingLog)
    if (event.target.closest?.("#writingLogButton")) return;
    if (event.target.closest?.("#splitViewButton")) return;
    const actionBtn = event.target.closest("[data-tools-action]");
    if (actionBtn) {
      event.preventDefault();
      handleToolsAction(actionBtn.dataset.toolsAction);
    }
  };
  $("sceneFeatureBar")?.addEventListener("click", onToolsActionClick);
  // 작가메모·등장인물 등: 4줄 상자 아이콘 행으로 이동
  document.querySelector(".format-toolbar-row-icons")?.addEventListener("click", onToolsActionClick);
  $("closeSceneToolsDrawer")?.addEventListener("click", closeSceneToolsDrawer);
  setupSceneToolsDrawerDrag();
  $("sceneNotes")?.addEventListener("input", () => {
    updateAuthorNotesBadge();
  });
  updateAuthorNotesBadge();
  updateReferenceMaterialsBadge();
  setupSpellcheckPanel();

  $("splitViewButton")?.addEventListener("click", (event) => {
    event.stopPropagation();
    if (!state.sceneId) {
      toast(i18n.t('app.먼저_목차에서_씬_하나를_열어_주세요'));
      return;
    }
    toggleViewModeMenu("main");
  });
  $("switchSplitModeButton")?.addEventListener("click", (event) => {
    event.stopPropagation();
    toggleViewModeMenu("split");
  });

  const onViewModePick = (event) => {
    const button = event.target.closest("[data-view-mode]");
    if (!button) return;
    event.preventDefault();
    event.stopPropagation();
    closeViewModeMenu();
    handleViewModeChoice(button.dataset.viewMode).catch(handleError);
  };
  $("viewModeDropdown")?.addEventListener("click", onViewModePick);
  $("splitModeDropdown")?.addEventListener("click", onViewModePick);

  document.addEventListener("click", (event) => {
    if (!event.target.closest(".view-mode-control, #viewModeDropdown, #splitModeDropdown, #focusWriteSplitButton")) {
      closeViewModeMenu();
    }
  });
  const repositionViewMenus = () => {
    const view = $("viewModeDropdown");
    const viewBtn = (typeof isFocusWriteOpen === "function" && isFocusWriteOpen() && $("focusWriteSplitButton"))
      ? $("focusWriteSplitButton")
      : $("splitViewButton");
    if (view && viewBtn && !view.classList.contains("hidden")) placeFeatureDropdown(view, viewBtn);
    const split = $("splitModeDropdown");
    const splitBtn = $("switchSplitModeButton");
    if (split && splitBtn && !split.classList.contains("hidden")) placeFeatureDropdown(split, splitBtn);
  };
  window.addEventListener("resize", repositionViewMenus);
  window.addEventListener("scroll", repositionViewMenus, true);
}

function setActiveBinder(binderKey, opts = {}) {
  const key = binderKey === "settings" ? "settings" : "manuscript";
  state.activeBinder = key;
  const manuscript = $("manuscriptBinder");
  const settings = $("settingsBinder");
  const tabManuscript = $("binderTabManuscript");
  const tabSettings = $("binderTabSettings");
  manuscript?.classList.toggle("hidden", key !== "manuscript");
  settings?.classList.toggle("hidden", key !== "settings");
  tabManuscript?.classList.toggle("is-active", key === "manuscript");
  tabSettings?.classList.toggle("is-active", key === "settings");
  tabManuscript?.setAttribute("aria-selected", key === "manuscript" ? "true" : "false");
  tabSettings?.setAttribute("aria-selected", key === "settings" ? "true" : "false");
  try {
    localStorage.setItem(BINDER_STORAGE_KEY, key);
  } catch (_) {
    /* ignore */
  }
  if (key === "settings" && typeof renderLinkedSuccessProfileCard === "function") {
    renderLinkedSuccessProfileCard().catch(() => {});
  }
}

function setupBinderSwitch() {
  let preferred = "manuscript";
  try {
    const stored = localStorage.getItem(BINDER_STORAGE_KEY);
    if (stored === "settings") preferred = "settings";
  } catch (_) {
    preferred = "manuscript";
  }
  setActiveBinder(preferred, { skipReturn: true });
  document.querySelectorAll("[data-binder]").forEach((button) => {
    button.addEventListener("click", () => {
      setActiveBinder(button.dataset.binder);
    });
  });
}

const GITSI_DISPLAY_NAME_KEY = "supertory.gitsiDisplayName";
let gitsiJoinInFlight = false;
/** @type {{ dispose?: Function, executeCommand?: Function, addListener?: Function, getIFrame?: Function } | null} */
let gitsiApi = null;
/** @type {Promise<void> | null} */
let gitsiScriptPromise = null;
/** @type {ResizeObserver | null} */
let gitsiResizeObserver = null;
let gitsiAudioMuted = true;
let gitsiVideoMuted = true;
let gitsiSharing = false;
/** @type {{ pointerId: number, startX: number, startY: number, origLeft: number, origTop: number } | null} */
let gitsiDrag = null;
let gitsiNativeInCall = false;
let gitsiNativeRoom = "";
let gitsiDefaultRoomCode = "";
let gitsiRoomsReady = false;
let gitsiIconLongPressTimer = null;
let gitsiIconLongPressFired = false;
const GITSI_ICON_LONG_PRESS_MS = 500;

function canUseGitsiWindow() {
  return typeof window.electronAPI?.openGitsiWindow === "function";
}

function loadJitsiExternalApi() {
  if (typeof window.JitsiMeetExternalAPI === "function") return Promise.resolve();
  if (gitsiScriptPromise) return gitsiScriptPromise;
  gitsiScriptPromise = new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = "https://meet.jit.si/external_api.js";
    script.async = true;
    script.onload = () => {
      if (typeof window.JitsiMeetExternalAPI === "function") resolve();
      else reject(new Error(i18n.t("index.룸에_입장하지_못했어요")));
    };
    script.onerror = () => reject(new Error(i18n.t("index.룸에_입장하지_못했어요")));
    document.head.appendChild(script);
  });
  return gitsiScriptPromise;
}

function gitsiDisplayName() {
  try {
    const saved = String(localStorage.getItem(GITSI_DISPLAY_NAME_KEY) || "").trim();
    if (saved) return saved.slice(0, 40);
  } catch (_) {
    /* ignore */
  }
  return i18n.t("index.짓시_표시_이름_예시");
}

function isGitsiInCall() {
  if (canUseGitsiWindow()) return Boolean(gitsiNativeInCall);
  return Boolean(gitsiApi) && !$("gitsiFloat")?.classList.contains("hidden");
}

function isGitsiPopoverOpen() {
  const popup = $("gitsiPopover");
  return Boolean(popup && !popup.hidden && popup.classList.contains("is-open"));
}

function positionGitsiPopover() {
  const popup = $("gitsiPopover");
  const button = $("gitsiPopoverButton");
  if (!popup || !button) return;
  const rect = button.getBoundingClientRect();
  const pad = 8;
  const wasOpen = popup.classList.contains("is-open");
  popup.hidden = false;
  popup.style.visibility = "hidden";
  popup.classList.add("is-open");
  const mw = Math.min(popup.offsetWidth || 280, window.innerWidth - pad * 2);
  let left = rect.right + 8;
  let top = rect.bottom - (popup.offsetHeight || 200);
  if (left + mw > window.innerWidth - pad) {
    left = Math.max(pad, window.innerWidth - mw - pad);
  }
  if (top < pad) top = pad;
  if (top + (popup.offsetHeight || 200) > window.innerHeight - pad) {
    top = Math.max(pad, window.innerHeight - (popup.offsetHeight || 200) - pad);
  }
  popup.style.left = `${Math.round(left)}px`;
  popup.style.top = `${Math.round(top)}px`;
  popup.style.bottom = "auto";
  popup.style.visibility = "";
  if (!wasOpen) {
    popup.classList.remove("is-open");
    void popup.offsetWidth;
    requestAnimationFrame(() => popup.classList.add("is-open"));
  }
}

function closeGitsiPopover() {
  const popup = $("gitsiPopover");
  const button = $("gitsiPopoverButton");
  if (popup) {
    popup.classList.remove("is-open");
    popup.hidden = true;
    popup.style.visibility = "";
  }
  if (button) button.setAttribute("aria-expanded", "false");
}

function hideGitsiWorkspace() {
  closeGitsiPopover();
}

function openGitsiPopover() {
  if (typeof closeUiThemeRail === "function") closeUiThemeRail();
  if (typeof closeAmbientPopup === "function") closeAmbientPopup();
  const button = $("gitsiPopoverButton");
  const popup = $("gitsiPopover");
  if (!button || !popup) return;
  button.setAttribute("aria-expanded", "true");
  const codeInput = $("gitsiRoomCodeInput");
  if (codeInput && !String(codeInput.value || "").trim()) {
    void suggestGitsiRoomCode();
  }
  void refreshGitsiRecent();
  positionGitsiPopover();
}

function toggleGitsiPopover() {
  if (isGitsiInCall()) {
    if (canUseGitsiWindow()) {
      try { window.electronAPI.focusGitsiWindow?.(); } catch (_) { /* ignore */ }
      closeGitsiPopover();
      return;
    }
    const floatEl = $("gitsiFloat");
    if (floatEl?.classList.contains("is-mini")) setGitsiFloatMode("expanded");
    else setGitsiFloatMode("mini");
    closeGitsiPopover();
    return;
  }
  if (isGitsiPopoverOpen()) closeGitsiPopover();
  else openGitsiPopover();
}

function syncGitsiCallUi() {
  $("gitsiPopoverButton")?.classList.toggle("is-in-call", isGitsiInCall());
  const mic = $("gitsiMicButton");
  const cam = $("gitsiCamButton");
  const share = $("gitsiShareButton");
  if (mic) {
    mic.classList.toggle("is-muted", gitsiAudioMuted);
    mic.classList.toggle("is-on", !gitsiAudioMuted);
    mic.setAttribute("aria-pressed", gitsiAudioMuted ? "false" : "true");
  }
  if (cam) {
    cam.classList.toggle("is-muted", gitsiVideoMuted);
    cam.classList.toggle("is-on", !gitsiVideoMuted);
    cam.setAttribute("aria-pressed", gitsiVideoMuted ? "false" : "true");
  }
  if (share) {
    share.classList.toggle("is-on", gitsiSharing);
    share.setAttribute("aria-pressed", gitsiSharing ? "true" : "false");
  }
}

function renderGitsiRecent(rooms) {
  const host = $("gitsiRecentList");
  if (!host) return;
  const list = Array.isArray(rooms) ? rooms : [];
  gitsiDefaultRoomCode = "";
  for (const room of list) {
    if (room && (room.is_default === 1 || room.is_default === true)) {
      gitsiDefaultRoomCode = String(room.room_code || "").trim();
      break;
    }
  }
  gitsiRoomsReady = true;
  if (!list.length) {
    host.innerHTML = `<p class="hint gitsi-recent-empty">${i18n.t("index.아직_만든_룸이_없어요")}</p>`;
    return;
  }
  host.innerHTML = list.map((room) => {
    const code = String(room?.room_code || "").replace(/"/g, "&quot;");
    const safe = String(room?.room_code || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
    const isDefault = Boolean(room?.is_default);
    const starLabel = (isDefault ? i18n.t("index.기본_룸") : i18n.t("index.기본으로_설정"))
      .replace(/&/g, "&amp;")
      .replace(/"/g, "&quot;")
      .replace(/</g, "&lt;");
    const removeLabel = i18n.t("index.목록에서_삭제")
      .replace(/&/g, "&amp;")
      .replace(/"/g, "&quot;")
      .replace(/</g, "&lt;");
    return `<div class="gitsi-recent-row">
      <button type="button" class="gitsi-recent-item" data-gitsi-room="${code}"><code>${safe}</code></button>
      <button type="button" class="gitsi-recent-star${isDefault ? " is-on" : ""}" data-gitsi-star="${code}" title="${starLabel}" aria-label="${starLabel}" aria-pressed="${isDefault ? "true" : "false"}">${isDefault ? "★" : "☆"}</button>
      <button type="button" class="gitsi-recent-remove" data-gitsi-remove="${code}" title="${removeLabel}" aria-label="${removeLabel}">×</button>
    </div>`;
  }).join("");
}

async function refreshGitsiRecent() {
  try {
    const data = await api("/api/gitsi/rooms");
    renderGitsiRecent(data?.rooms || []);
  } catch (error) {
    renderGitsiRecent([]);
    handleError?.(error);
  }
}

async function setGitsiDefaultRoom(roomCode, enabled) {
  const payload = { is_default: Boolean(enabled) };
  const code = String(roomCode || "").trim();
  if (code) payload.room_code = code;
  const room = await api("/api/gitsi/rooms/default", {
    method: "POST",
    body: JSON.stringify(payload),
  });
  const next = String(room?.room_code || "").trim();
  const input = $("gitsiRoomCodeInput");
  if (input && next && enabled) input.value = next;
  toast(enabled ? i18n.t("index.기본_룸으로_지정했어요") : i18n.t("index.기본_룸을_해제했어요"));
  await refreshGitsiRecent();
  return room;
}

async function removeGitsiRecentRoom(roomCode) {
  const code = String(roomCode || "").trim();
  if (!code) return;
  await api(`/api/gitsi/rooms/${encodeURIComponent(code)}`, { method: "DELETE" });
  toast(i18n.t("index.룸을_목록에서_지웠어요"));
  await refreshGitsiRecent();
}

async function ensureGitsiRoomsLoaded() {
  if (gitsiRoomsReady) return;
  await refreshGitsiRecent();
}

function clearGitsiIconLongPress() {
  if (gitsiIconLongPressTimer) {
    clearTimeout(gitsiIconLongPressTimer);
    gitsiIconLongPressTimer = null;
  }
}

function openGitsiPopoverForced() {
  if (isGitsiPopoverOpen()) {
    positionGitsiPopover();
    return;
  }
  openGitsiPopover();
}

async function handleGitsiIconActivate() {
  if (gitsiIconLongPressFired) return;
  if (isGitsiInCall()) {
    toggleGitsiPopover();
    return;
  }
  if (isGitsiPopoverOpen()) {
    closeGitsiPopover();
    return;
  }
  await ensureGitsiRoomsLoaded();
  if (gitsiDefaultRoomCode) {
    void joinGitsiRoom(gitsiDefaultRoomCode);
    return;
  }
  openGitsiPopover();
}

async function suggestGitsiRoomCode() {
  const input = $("gitsiRoomCodeInput");
  try {
    const data = await api("/api/gitsi/suggest-code");
    if (input && data?.room_code) input.value = data.room_code;
  } catch (error) {
    if (input && !String(input.value || "").trim()) {
      input.value = `supertory-${Math.random().toString(36).slice(2, 6)}`;
    }
    handleError?.(error);
  }
}

function gitsiMeetIframe() {
  try {
    const fromApi = gitsiApi?.getIFrame?.();
    if (fromApi) return fromApi;
  } catch (_) {
    /* ignore */
  }
  return $("gitsiMeetHost")?.querySelector("iframe") || null;
}

function syncGitsiMeetFrameSize() {
  const host = $("gitsiMeetHost");
  const floatEl = $("gitsiFloat");
  if (!host || !floatEl || floatEl.classList.contains("hidden")) return null;
  const rect = host.getBoundingClientRect();
  const w = Math.max(1, Math.round(rect.width));
  const h = Math.max(1, Math.round(rect.height));
  const iframe = gitsiMeetIframe();
  const applySize = (el) => {
    if (!el || !el.style) return;
    el.style.setProperty("width", `${w}px`, "important");
    el.style.setProperty("height", `${h}px`, "important");
    if (el.setAttribute) {
      el.setAttribute("width", String(w));
      el.setAttribute("height", String(h));
    }
  };
  applySize(iframe);
  Array.from(host.children || []).forEach((child) => applySize(child));
  return { w, h };
}

function bindGitsiMeetResize() {
  const host = $("gitsiMeetHost");
  const floatEl = $("gitsiFloat");
  if (!host) return;
  if (typeof ResizeObserver === "function") {
    if (!gitsiResizeObserver) {
      gitsiResizeObserver = new ResizeObserver(() => {
        syncGitsiMeetFrameSize();
      });
    }
    gitsiResizeObserver.disconnect();
    gitsiResizeObserver.observe(host);
    if (floatEl) gitsiResizeObserver.observe(floatEl);
  }
}

function unbindGitsiMeetResize() {
  try {
    gitsiResizeObserver?.disconnect();
  } catch (_) {
    /* ignore */
  }
}

function applyGitsiExpandedRect() {
  const el = $("gitsiFloat");
  if (!el) return;
  const work = $("workArea")?.getBoundingClientRect();
  if (work && work.width > 40 && work.height > 40) {
    el.style.setProperty("--gitsi-expand-top", `${Math.round(work.top)}px`);
    el.style.setProperty("--gitsi-expand-left", `${Math.round(work.left)}px`);
    el.style.setProperty("--gitsi-expand-width", `${Math.round(work.width)}px`);
    el.style.setProperty("--gitsi-expand-height", `${Math.round(work.height)}px`);
    return;
  }
  el.style.setProperty("--gitsi-expand-top", "12px");
  el.style.setProperty("--gitsi-expand-left", "12px");
  el.style.setProperty("--gitsi-expand-width", `${Math.max(1, window.innerWidth - 24)}px`);
  el.style.setProperty("--gitsi-expand-height", `${Math.max(1, window.innerHeight - 24)}px`);
}

function rememberGitsiMiniBox(el) {
  const r = el.getBoundingClientRect();
  el.style.left = `${Math.round(r.left)}px`;
  el.style.top = `${Math.round(r.top)}px`;
  el.style.right = "auto";
  el.style.bottom = "auto";
}

function clampGitsiMiniPosition(el) {
  if (!el || !el.classList.contains("is-mini")) return;
  const r = el.getBoundingClientRect();
  const pad = 8;
  const left = Math.min(Math.max(pad, r.left), Math.max(pad, window.innerWidth - r.width - pad));
  const top = Math.min(Math.max(pad, r.top), Math.max(pad, window.innerHeight - r.height - pad));
  el.style.left = `${Math.round(left)}px`;
  el.style.top = `${Math.round(top)}px`;
  el.style.right = "auto";
  el.style.bottom = "auto";
}

function setGitsiFloatMode(mode) {
  const el = $("gitsiFloat");
  if (!el || el.classList.contains("hidden")) return;
  const expanded = mode === "expanded";
  if (expanded) {
    rememberGitsiMiniBox(el);
    applyGitsiExpandedRect();
  }
  el.classList.toggle("is-expanded", expanded);
  el.classList.toggle("is-mini", !expanded);
  requestAnimationFrame(() => {
    syncGitsiMeetFrameSize();
    setTimeout(syncGitsiMeetFrameSize, 60);
    setTimeout(syncGitsiMeetFrameSize, 240);
  });
}

function showGitsiFloatMini() {
  const el = $("gitsiFloat");
  if (!el) return;
  el.classList.remove("hidden", "is-expanded");
  el.classList.add("is-mini");
  el.setAttribute("aria-hidden", "false");
  if (!el.dataset.gitsiDragged) {
    const work = $("workArea")?.getBoundingClientRect();
    const w = 280;
    const h = 200;
    const pad = 16;
    let left;
    let top;
    if (work && work.width > 80) {
      left = work.right - w - pad;
      top = work.bottom - h - pad;
    } else {
      left = window.innerWidth - w - pad;
      top = window.innerHeight - h - pad;
    }
    el.style.left = `${Math.round(left)}px`;
    el.style.top = `${Math.round(top)}px`;
    el.style.right = "auto";
    el.style.bottom = "auto";
  }
  state.gitsiOpen = true;
  syncGitsiCallUi();
}

function hideGitsiFloat() {
  const el = $("gitsiFloat");
  if (!el) return;
  el.classList.add("hidden", "is-mini");
  el.classList.remove("is-expanded", "is-dragging");
  el.setAttribute("aria-hidden", "true");
  state.gitsiOpen = false;
  syncGitsiCallUi();
}

function onGitsiWindowResize() {
  if (isGitsiPopoverOpen()) positionGitsiPopover();
  const el = $("gitsiFloat");
  if (!el || el.classList.contains("hidden")) return;
  if (el.classList.contains("is-expanded")) applyGitsiExpandedRect();
  else clampGitsiMiniPosition(el);
  syncGitsiMeetFrameSize();
}

function gitsiExecute(command) {
  try {
    gitsiApi?.executeCommand?.(command);
  } catch (_) {
    /* ignore */
  }
}

function leaveGitsiMeeting() {
  if (canUseGitsiWindow()) {
    try { window.electronAPI.closeGitsiWindow?.(); } catch (_) { /* ignore */ }
    return;
  }
  disposeGitsiMeeting();
  toast(i18n.t("index.짓시_룸에서_나왔어요"));
}

function scheduleGitsiFrameSync() {
  requestAnimationFrame(() => {
    syncGitsiMeetFrameSize();
    setTimeout(syncGitsiMeetFrameSize, 50);
    setTimeout(syncGitsiMeetFrameSize, 300);
  });
}

async function showGitsiMeeting(roomCode) {
  if (canUseGitsiWindow()) {
    closeGitsiPopover();
    hideGitsiFloat();
    disposeGitsiApiOnly();
    gitsiNativeInCall = true;
    gitsiNativeRoom = roomCode;
    syncGitsiCallUi();
    const lang = i18n.getLang?.() || document.documentElement.lang || "ko";
    await window.electronAPI.openGitsiWindow({
      room: roomCode,
      name: gitsiDisplayName(),
      lang,
    });
    return;
  }
  const current = String($("gitsiActiveRoomCode")?.textContent || "").trim();
  if (gitsiApi && current === roomCode && !$("gitsiFloat")?.classList.contains("hidden")) {
    closeGitsiPopover();
    setGitsiFloatMode("mini");
    return;
  }
  disposeGitsiApiOnly();
  const host = $("gitsiMeetHost");
  const codeEl = $("gitsiActiveRoomCode");
  if (codeEl) codeEl.textContent = roomCode;
  if (!host) return;
  showGitsiFloatMini();
  closeGitsiPopover();
  await loadJitsiExternalApi();
  gitsiAudioMuted = true;
  gitsiVideoMuted = true;
  gitsiSharing = false;
  syncGitsiCallUi();
  const lang = i18n.getLang?.() || document.documentElement.lang || "ko";
  const displayName = gitsiDisplayName();
  gitsiApi = new window.JitsiMeetExternalAPI("meet.jit.si", {
    roomName: roomCode,
    parentNode: host,
    width: "100%",
    height: "100%",
    lang,
    userInfo: { displayName },
    configOverwrite: {
      startWithAudioMuted: true,
      startWithVideoMuted: true,
      disableShortcuts: true,
      prejoinConfig: { enabled: false },
      prejoinPageEnabled: false,
      disableInviteFunctions: true,
      toolbarButtons: [
        "microphone",
        "camera",
        "desktop",
        "chat",
        "raisehand",
        "participants-pane",
        "tileview",
        "settings",
        "hangup",
      ],
    },
    interfaceConfigOverwrite: {
      SHOW_CHROME_EXTENSION_BANNER: false,
      DISABLE_JOIN_LEAVE_NOTIFICATIONS: true,
      TOOLBAR_ALWAYS_VISIBLE: true,
    },
  });
  bindGitsiMeetResize();
  scheduleGitsiFrameSync();
  gitsiApi.addListener?.("videoConferenceJoined", () => {
    try {
      gitsiApi.executeCommand?.("displayName", displayName);
    } catch (_) {
      /* ignore */
    }
    scheduleGitsiFrameSync();
  });
  gitsiApi.addListener?.("audioMuteStatusChanged", (payload) => {
    gitsiAudioMuted = payload?.muted !== false;
    syncGitsiCallUi();
  });
  gitsiApi.addListener?.("videoMuteStatusChanged", (payload) => {
    gitsiVideoMuted = payload?.muted !== false;
    syncGitsiCallUi();
  });
  gitsiApi.addListener?.("screenSharingStatusChanged", (payload) => {
    gitsiSharing = Boolean(payload?.on);
    syncGitsiCallUi();
  });
  gitsiApi.addListener?.("readyToClose", () => {
    disposeGitsiMeeting();
  });
}

function disposeGitsiApiOnly() {
  unbindGitsiMeetResize();
  const api = gitsiApi;
  gitsiApi = null;
  if (api) {
    try {
      api.dispose?.();
    } catch (_) {
      /* ignore */
    }
  }
  const host = $("gitsiMeetHost");
  if (host) host.innerHTML = "";
}

function disposeGitsiMeeting() {
  disposeGitsiApiOnly();
  gitsiAudioMuted = true;
  gitsiVideoMuted = true;
  gitsiSharing = false;
  hideGitsiFloat();
  const codeEl = $("gitsiActiveRoomCode");
  if (codeEl) codeEl.textContent = "";
}

async function joinGitsiRoom(rawCode) {
  if (gitsiJoinInFlight) return;
  const input = $("gitsiRoomCodeInput");
  const roomCode = String(rawCode != null ? rawCode : (input?.value || "")).trim();
  gitsiJoinInFlight = true;
  try {
    const payload = {};
    if (roomCode) payload.room_code = roomCode;
    const room = await api("/api/gitsi/rooms", {
      method: "POST",
      body: JSON.stringify(payload),
    });
    const code = String(room?.room_code || "").trim();
    if (!code) throw new Error(i18n.t("index.룸에_입장하지_못했어요"));
    if (input) input.value = code;
    try {
      await showGitsiMeeting(code);
    } catch (meetError) {
      disposeGitsiMeeting();
      if (canUseGitsiWindow()) {
        try { window.electronAPI.closeGitsiWindow?.(); } catch (_) { /* ignore */ }
      }
      throw meetError;
    }
    toast(room?.created ? i18n.t("index.짓시_룸을_만들었어요") : i18n.t("index.짓시_룸에_입장했어요"));
    void refreshGitsiRecent();
  } catch (error) {
    handleError?.(error);
  } finally {
    gitsiJoinInFlight = false;
  }
}

function onGitsiPointerMove(event) {
  if (!gitsiDrag) return;
  const el = $("gitsiFloat");
  if (!el) return;
  const left = gitsiDrag.origLeft + (event.clientX - gitsiDrag.startX);
  const top = gitsiDrag.origTop + (event.clientY - gitsiDrag.startY);
  el.style.left = `${Math.round(left)}px`;
  el.style.top = `${Math.round(top)}px`;
}

function onGitsiPointerUp() {
  if (!gitsiDrag) return;
  const el = $("gitsiFloat");
  el?.classList.remove("is-dragging");
  if (el) clampGitsiMiniPosition(el);
  gitsiDrag = null;
}

function setupGitsi() {
  try {
    window.electronAPI?.onGitsiWindowStatus?.((payload) => {
      const inCall = Boolean(payload?.inCall) && !payload?.closed;
      const wasInCall = gitsiNativeInCall;
      gitsiNativeInCall = inCall;
      gitsiNativeRoom = inCall ? String(payload?.room || gitsiNativeRoom || "") : "";
      syncGitsiCallUi();
      if (wasInCall && !inCall) {
        toast(i18n.t("index.짓시_룸에서_나왔어요"));
      }
    });
  } catch (_) {
    /* ignore */
  }
  void refreshGitsiRecent();
  $("gitsiPopoverButton")?.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    gitsiIconLongPressFired = false;
    clearGitsiIconLongPress();
    gitsiIconLongPressTimer = setTimeout(() => {
      gitsiIconLongPressFired = true;
      openGitsiPopoverForced();
    }, GITSI_ICON_LONG_PRESS_MS);
  });
  $("gitsiPopoverButton")?.addEventListener("pointerup", () => {
    clearGitsiIconLongPress();
  });
  $("gitsiPopoverButton")?.addEventListener("pointerleave", () => {
    clearGitsiIconLongPress();
  });
  $("gitsiPopoverButton")?.addEventListener("pointercancel", () => {
    clearGitsiIconLongPress();
  });
  $("gitsiPopoverButton")?.addEventListener("click", (event) => {
    event.stopPropagation();
    if (gitsiIconLongPressFired) {
      event.preventDefault();
      return;
    }
    void handleGitsiIconActivate();
  });
  $("gitsiPopoverButton")?.addEventListener("contextmenu", (event) => {
    event.preventDefault();
    event.stopPropagation();
    clearGitsiIconLongPress();
    gitsiIconLongPressFired = true;
    openGitsiPopoverForced();
  });
  $("gitsiJoinButton")?.addEventListener("click", () => {
    void joinGitsiRoom();
  });
  $("gitsiSetDefaultButton")?.addEventListener("click", () => {
    const code = String($("gitsiRoomCodeInput")?.value || "").trim();
    void setGitsiDefaultRoom(code, true).catch((error) => handleError?.(error));
  });
  $("gitsiLeaveButton")?.addEventListener("click", leaveGitsiMeeting);
  $("gitsiLeaveMiniButton")?.addEventListener("click", leaveGitsiMeeting);
  $("gitsiExpandButton")?.addEventListener("click", () => setGitsiFloatMode("expanded"));
  $("gitsiShrinkButton")?.addEventListener("click", () => setGitsiFloatMode("mini"));
  $("gitsiMiniHit")?.addEventListener("click", () => setGitsiFloatMode("expanded"));
  $("gitsiMicButton")?.addEventListener("click", () => gitsiExecute("toggleAudio"));
  $("gitsiCamButton")?.addEventListener("click", () => gitsiExecute("toggleVideo"));
  $("gitsiShareButton")?.addEventListener("click", () => gitsiExecute("toggleShareScreen"));
  $("gitsiCopyCodeButton")?.addEventListener("click", async () => {
    const code = String($("gitsiActiveRoomCode")?.textContent || "").trim();
    if (!code) return;
    try {
      await navigator.clipboard.writeText(code);
      toast(i18n.t("index.룸_코드를_복사했어요"));
    } catch (_) {
      toast(code);
    }
  });
  $("gitsiRoomCodeInput")?.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      void joinGitsiRoom();
    }
  });
  $("gitsiRecentList")?.addEventListener("click", (event) => {
    const remove = event.target.closest?.("[data-gitsi-remove]");
    if (remove) {
      event.preventDefault();
      event.stopPropagation();
      const code = String(remove.getAttribute("data-gitsi-remove") || "").trim();
      if (!code) return;
      void removeGitsiRecentRoom(code).catch((error) => handleError?.(error));
      return;
    }
    const star = event.target.closest?.("[data-gitsi-star]");
    if (star) {
      event.preventDefault();
      event.stopPropagation();
      const code = String(star.getAttribute("data-gitsi-star") || "").trim();
      if (!code) return;
      const nextOn = star.getAttribute("aria-pressed") !== "true";
      void setGitsiDefaultRoom(code, nextOn).catch((error) => handleError?.(error));
      return;
    }
    const button = event.target.closest?.("[data-gitsi-room]");
    if (!button) return;
    const code = String(button.getAttribute("data-gitsi-room") || "").trim();
    const input = $("gitsiRoomCodeInput");
    if (input && code) input.value = code;
    void joinGitsiRoom(code);
  });
  $("gitsiFloatDrag")?.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    if (event.target.closest?.("button")) return;
    const el = $("gitsiFloat");
    if (!el || !el.classList.contains("is-mini")) return;
    event.preventDefault();
    rememberGitsiMiniBox(el);
    el.classList.add("is-dragging");
    el.dataset.gitsiDragged = "1";
    gitsiDrag = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      origLeft: el.getBoundingClientRect().left,
      origTop: el.getBoundingClientRect().top,
    };
  });
  window.addEventListener("pointermove", onGitsiPointerMove);
  window.addEventListener("pointerup", onGitsiPointerUp);
  window.addEventListener("pointercancel", onGitsiPointerUp);
  window.addEventListener("resize", onGitsiWindowResize);
  document.addEventListener("click", (event) => {
    if (!isGitsiPopoverOpen()) return;
    if (event.target?.closest?.("#gitsiPopover, #binderGitsiControl")) return;
    closeGitsiPopover();
  });
  window.addEventListener("message", (event) => {
    const data = event.data;
    if (!data || data.source !== "supertory-gitsi") return;
    if (data.type === "left") {
      disposeGitsiMeeting();
    } else if (data.type === "error" && data.message) {
      toast(String(data.message));
    }
  });
}

const OUTLINE_WIDTH_STORAGE_KEY = "supertory.outlineWidth";
/* —— Dismissible onboarding tips (목차 / 설정집 / 생각수첩) —— */
const GUIDE_TIP_STORAGE_KEY = "supertory.hiddenGuideTips";
const GUIDE_TIP_DEFS = [
  { id: "outline", label: i18n.t('app.목차_안내_폴더_드래그_우클릭') },
  { id: "settingsBinder", label: i18n.t('app.설정집_안내_펼치기_폴더_순서') },
  { id: "ideaBoard", label: i18n.t('app.생각수첩_보드_안내') },
  { id: "baits", label: i18n.t('app.떡밥모음_안내') },
];
/** @type {Set<string>} */
let hiddenGuideTips = new Set();

function loadHiddenGuideTips() {
  const set = new Set();
  try {
    const raw = localStorage.getItem(GUIDE_TIP_STORAGE_KEY);
    if (raw) {
      const arr = JSON.parse(raw);
      if (Array.isArray(arr)) {
        for (const id of arr) {
          if (typeof id === "string" && id) set.add(id);
        }
      }
    }
  } catch (_) { /* ignore */ }
  // Migrate legacy outline tip flag into the shared store
  try {
    if (localStorage.getItem("supertory.outlineTipHidden") === "1") set.add("outline");
  } catch (_) { /* ignore */ }
  return set;
}

function saveHiddenGuideTips() {
  try {
    localStorage.setItem(GUIDE_TIP_STORAGE_KEY, JSON.stringify([...hiddenGuideTips]));
    if (hiddenGuideTips.has("outline")) localStorage.setItem("supertory.outlineTipHidden", "1");
    else localStorage.removeItem("supertory.outlineTipHidden");
  } catch (_) { /* ignore */ }
  updateGuideTipCountUi();
  renderHiddenGuideTipsList();
}

function isGuideTipHidden(id) {
  return hiddenGuideTips.has(String(id || ""));
}

function setGuideTipHidden(id, hidden, { quiet = false } = {}) {
  const key = String(id || "");
  if (!key || !GUIDE_TIP_DEFS.some((d) => d.id === key)) return;
  if (hidden) hiddenGuideTips.add(key);
  else hiddenGuideTips.delete(key);
  saveHiddenGuideTips();
  syncGuideTipBoxes();
  if (!quiet) {
    const label = GUIDE_TIP_DEFS.find((d) => d.id === key)?.label || i18n.t('app.안내');
    toast(hidden ? `${i18n.t('app.label_을_를_숨겼습니다', {label: label})}` : `${i18n.t('app.label_을_를_다시_표시합니다', {label: label})}`);
  }
}

function syncGuideTipBoxes() {
  document.querySelectorAll("[data-guide-tip]").forEach((el) => {
    const id = el.getAttribute("data-guide-tip");
    el.classList.toggle("hidden", isGuideTipHidden(id));
  });
}

function updateGuideTipCountUi() {
  const n = hiddenGuideTips.size;
  const hint = $("guideTipCountHint");
  if (hint) hint.textContent = n ? `${i18n.t('app.숨긴_안내_n_개', {n: n})}` : i18n.t('app.숨긴_안내_없음');
}

function renderHiddenGuideTipsList() {
  const list = $("hiddenGuideTipsList");
  if (!list) return;
  const items = GUIDE_TIP_DEFS.filter((d) => hiddenGuideTips.has(d.id));
  if (!items.length) {
    list.innerHTML = i18n.t('app.p_class_hint_trash_empt_5');
    updateGuideTipCountUi();
    return;
  }
  list.innerHTML = items.map((d) => `
    <div class="hidden-feature-item" data-guide-tip-id="${escapeHtml(d.id)}">
      <div class="hidden-feature-main">
        <span class="hidden-feature-title">${escapeHtml(d.label)}</span>
      </div>
      <button type="button" class="primary compact-btn" data-guide-tip-activate="${escapeHtml(d.id)}">${i18n.t('index.다시_표시')}</button>
    </div>
  `).join("");
  updateGuideTipCountUi();
}

function resetAllHiddenGuideTips() {
  if (!hiddenGuideTips.size) {
    toast(i18n.t('app.숨긴_안내가_없어요'));
    return;
  }
  if (!window.confirm(`${i18n.t('app.숨긴_안내_hiddenGuideTips_si', {'hiddenGuideTips.size': hiddenGuideTips.size})}`)) return;
  hiddenGuideTips = new Set();
  saveHiddenGuideTips();
  syncGuideTipBoxes();
  toast(i18n.t('app.모든_안내를_다시_표시했습니다'));
}

function setupGuideTips() {
  if (setupGuideTips._bound) return;
  setupGuideTips._bound = true;
  hiddenGuideTips = loadHiddenGuideTips();
  syncGuideTipBoxes();
  renderHiddenGuideTipsList();

  document.addEventListener("click", (event) => {
    const btn = event.target.closest?.("[data-guide-tip-dismiss]");
    if (!btn) return;
    event.preventDefault();
    event.stopPropagation();
    setGuideTipHidden(btn.getAttribute("data-guide-tip-dismiss"), true);
  });

  $("guideTipResetButton")?.addEventListener("click", resetAllHiddenGuideTips);
  $("hiddenGuideTipsList")?.addEventListener("click", (event) => {
    const btn = event.target.closest?.("[data-guide-tip-activate]");
    if (!btn) return;
    event.preventDefault();
    setGuideTipHidden(btn.getAttribute("data-guide-tip-activate"), false);
  });
}

const OUTLINE_WIDTH_MIN = 180;
const OUTLINE_WIDTH_MAX = 480;

function applyOutlineWidth(widthPx) {
  const width = Math.max(OUTLINE_WIDTH_MIN, Math.min(OUTLINE_WIDTH_MAX, Math.round(widthPx)));
  document.documentElement.style.setProperty("--outline-width", `${width}px`);
  return width;
}

function setupOutlineResizer() {
  const resizer = $("outlineResizer");
  if (!resizer) return;

  try {
    const stored = Number(localStorage.getItem(OUTLINE_WIDTH_STORAGE_KEY));
    if (Number.isFinite(stored) && stored >= OUTLINE_WIDTH_MIN) {
      applyOutlineWidth(stored);
    }
  } catch (_) {
    /* ignore */
  }

  let drag = null;

  const onMove = (event) => {
    if (!drag) return;
    const next = applyOutlineWidth(event.clientX - drag.startX + drag.startWidth);
    drag.currentWidth = next;
  };

  const onUp = () => {
    if (!drag) return;
    document.body.classList.remove("outline-resizing");
    try {
      localStorage.setItem(OUTLINE_WIDTH_STORAGE_KEY, String(drag.currentWidth || OUTLINE_WIDTH_MIN));
    } catch (_) {
      /* ignore */
    }
    drag = null;
    window.removeEventListener("pointermove", onMove);
    window.removeEventListener("pointerup", onUp);
    window.removeEventListener("pointercancel", onUp);
  };

  resizer.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    if (!isBinderPanelOpen()) return;
    const panel = $("outlinePanel");
    const startWidth = panel ? panel.getBoundingClientRect().width : 250;
    drag = {
      startX: event.clientX,
      startWidth,
      currentWidth: startWidth,
    };
    document.body.classList.add("outline-resizing");
    resizer.setPointerCapture?.(event.pointerId);
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
    event.preventDefault();
  });
}

const AI_PANEL_WIDTH_STORAGE_KEY = "supertory.aiPanelWidth";
const AI_PANEL_WIDTH_MIN = 240;
const AI_PANEL_WIDTH_MAX = 560;

function applyAiPanelWidth(widthPx) {
  const width = Math.max(AI_PANEL_WIDTH_MIN, Math.min(AI_PANEL_WIDTH_MAX, Math.round(widthPx)));
  document.documentElement.style.setProperty("--ai-panel-width", `${width}px`);
  return width;
}

function setupAiPanelResizer() {
  const resizer = $("aiPanelResizer");
  if (!resizer) return;

  try {
    const stored = Number(localStorage.getItem(AI_PANEL_WIDTH_STORAGE_KEY));
    if (Number.isFinite(stored) && stored >= AI_PANEL_WIDTH_MIN) {
      applyAiPanelWidth(stored);
    }
  } catch (_) {
    /* ignore */
  }

  let drag = null;

  const onMove = (event) => {
    if (!drag) return;
    // Right panel: drag left edge leftward to widen
    const next = applyAiPanelWidth(drag.startWidth + (drag.startX - event.clientX));
    drag.currentWidth = next;
  };

  const onUp = () => {
    if (!drag) return;
    document.body.classList.remove("ai-panel-resizing");
    try {
      localStorage.setItem(AI_PANEL_WIDTH_STORAGE_KEY, String(drag.currentWidth || AI_PANEL_WIDTH_MIN));
    } catch (_) {
      /* ignore */
    }
    drag = null;
    window.removeEventListener("pointermove", onMove);
    window.removeEventListener("pointerup", onUp);
    window.removeEventListener("pointercancel", onUp);
  };

  resizer.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    if (typeof isAiPanelOpen === "function" && !isAiPanelOpen()) return;
    if (document.body.classList.contains("ai-panel-collapsed")) return;
    const panel = $("aiPanel");
    const startWidth = panel ? panel.getBoundingClientRect().width : 300;
    drag = {
      startX: event.clientX,
      startWidth,
      currentWidth: startWidth,
    };
    document.body.classList.add("ai-panel-resizing");
    resizer.setPointerCapture?.(event.pointerId);
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
    event.preventDefault();
  });
}

async function revealCurrentPackage() {
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  const result = await api(`/api/projects/${state.projectId}/reveal-package`, {
    method: "POST",
    body: JSON.stringify({}),
  });
  toast(`${i18n.t('app.탐색기에서_열었어요_result_packag', {'result.package_name || "작품 파일"': result.package_name || "작품 파일"})}`);
}

const BINDER_COLLAPSE_PREFIX = "supertory.binderCollapsed.";

function binderCollapseStorageKey(projectId = state.projectId) {
  return `${BINDER_COLLAPSE_PREFIX}${projectId || "0"}`;
}

/** Walk nested scene tree depth-first. */
function walkSceneTree(nodes, visit, depth = 0) {
  for (const scene of nodes || []) {
    visit(scene, depth);
    if (scene.children?.length) walkSceneTree(scene.children, visit, depth + 1);
  }
}

/** Walk top-level folders and folders nested under manuscripts. */
function walkBinderChapters(chapters, visit) {
  for (const chapter of chapters || []) {
    visit(chapter);
    walkSceneTree(chapter.scenes || [], (scene) => {
      for (const nested of scene.child_chapters || []) {
        walkBinderChapters([nested], visit);
      }
    });
  }
}

function flattenChapterScenes(chapter) {
  if (!chapter) return [];
  // Prefer live tree so status / completeness stay correct after binder sync.
  const out = [];
  walkSceneTree(chapter.scenes || [], (scene) => out.push(scene));
  if (out.length) return out;
  if (Array.isArray(chapter.scenes_flat) && chapter.scenes_flat.length) {
    return chapter.scenes_flat;
  }
  return [];
}

function flattenAllOutlineScenes() {
  const out = [];
  walkBinderChapters(getBinderChaptersInOrder(), (chapter) => {
    walkSceneTree(chapter.scenes || [], (scene) => {
      out.push({ ...scene, chapterId: chapter.id, chapterTitle: chapter.title });
    });
  });
  return out;
}

function findChapterIdForScene(sceneId) {
  const id = Number(sceneId);
  let foundId = null;
  walkBinderChapters(getBinderChaptersInOrder(), (chapter) => {
    if (foundId != null) return;
    walkSceneTree(chapter.scenes || [], (scene) => {
      if (foundId == null && Number(scene.id) === id) foundId = Number(chapter.id);
    });
  });
  return foundId;
}

function getCollapsedChapterIds() {
  if (!state.projectId) return new Set();
  try {
    const raw = localStorage.getItem(binderCollapseStorageKey());
    const arr = raw ? JSON.parse(raw) : [];
    return new Set((Array.isArray(arr) ? arr : []).map(Number).filter((id) => id > 0));
  } catch (_) {
    return new Set();
  }
}

function binderSceneCollapseStorageKey() {
  return `supertory.binderSceneCollapsed.${state.projectId || 0}`;
}

function getCollapsedSceneIds() {
  if (!state.projectId) return new Set();
  try {
    const raw = localStorage.getItem(binderSceneCollapseStorageKey());
    const arr = raw ? JSON.parse(raw) : [];
    return new Set((Array.isArray(arr) ? arr : []).map(Number).filter((id) => id > 0));
  } catch (_) {
    return new Set();
  }
}

function setSceneCollapsed(sceneId, collapsed) {
  const id = Number(sceneId);
  if (!id) return;
  const set = getCollapsedSceneIds();
  if (collapsed) set.add(id);
  else set.delete(id);
  try {
    localStorage.setItem(binderSceneCollapseStorageKey(), JSON.stringify([...set]));
  } catch (_) { /* ignore */ }
}

function toggleSceneExpanded(sceneId) {
  const id = Number(sceneId);
  if (!id) return;
  const wasCollapsed = getCollapsedSceneIds().has(id);
  setSceneCollapsed(id, !wasCollapsed);
  const expanded = wasCollapsed; // we just expanded if it was collapsed
  const host = $("outline")?.querySelector(`.scene-tree-item[data-scene-node="${id}"]`);
  if (host) {
    host.classList.toggle("is-collapsed", !expanded);
    const kids = host.querySelector(":scope > .scene-children");
    if (kids) {
      kids.hidden = !expanded;
      kids.classList.toggle("is-collapsed", !expanded);
    }
    const twistie = host.querySelector(":scope > .scene-row .scene-twistie");
    if (twistie) twistie.setAttribute("aria-expanded", expanded ? "true" : "false");
  }
}

function persistCollapsedChapterIds(collapsedSet) {
  if (!state.projectId) return;
  try {
    localStorage.setItem(binderCollapseStorageKey(), JSON.stringify([...collapsedSet]));
  } catch (_) {
    /* ignore quota / private mode */
  }
}

function setChapterCollapsed(chapterId, collapsed) {
  const id = Number(chapterId);
  if (!id) return;
  const collapsedSet = getCollapsedChapterIds();
  if (collapsed) collapsedSet.add(id);
  else collapsedSet.delete(id);
  persistCollapsedChapterIds(collapsedSet);
}

function binderPartCollapseStorageKey() {
  return `supertory.binderPartCollapsed.${state.projectId || 0}`;
}

function getCollapsedPartIds() {
  if (!state.projectId) return new Set();
  try {
    const raw = localStorage.getItem(binderPartCollapseStorageKey());
    const arr = raw ? JSON.parse(raw) : [];
    return new Set((Array.isArray(arr) ? arr : []).map(Number).filter((id) => id > 0));
  } catch (_) {
    return new Set();
  }
}

function persistCollapsedPartIds(collapsedSet) {
  if (!state.projectId) return;
  try {
    localStorage.setItem(binderPartCollapseStorageKey(), JSON.stringify([...collapsedSet]));
  } catch (_) {
    /* ignore */
  }
}

function setPartCollapsed(partId, collapsed) {
  const id = Number(partId);
  if (!id) return;
  const collapsedSet = getCollapsedPartIds();
  if (collapsed) collapsedSet.add(id);
  else collapsedSet.delete(id);
  persistCollapsedPartIds(collapsedSet);
}

function togglePartExpanded(partId) {
  const id = Number(partId);
  if (!id) return;
  const outline = $("outline");
  // Box shell is always .outline-part; chapter-source boxes use data-chapter-id.
  const section = outline?.querySelector(`.outline-part[data-part-id="${id}"]`)
    || outline?.querySelector(`.outline-part[data-chapter-id="${id}"]`);
  const expanded = section?.dataset?.expanded !== "true";
  setPartCollapsed(id, !expanded);
  if (section) applyPartExpandedState(section, expanded);
}

function applyPartExpandedState(section, expanded) {
  if (!section) return;
  section.classList.toggle("is-collapsed", !expanded);
  section.dataset.expanded = expanded ? "true" : "false";
  const twistie = section.querySelector(".part-twistie");
  if (twistie) {
    twistie.setAttribute("aria-expanded", expanded ? "true" : "false");
    twistie.title = expanded ? i18n.t('app.폴더_목록_접기') : i18n.t('app.폴더_목록_펼치기');
  }
  const children = section.querySelector(".part-children");
  if (children) {
    children.hidden = !expanded;
    children.classList.toggle("is-collapsed", !expanded);
  }
}

/** localStorage: force folders outline for projects after non-legacy reparent. */
function forceFoldersOutlineKey(projectId = state.projectId) {
  return `supertory.forceFolders.${projectId || 0}`;
}

function readForceFoldersOutline(projectId = state.projectId) {
  try {
    return localStorage.getItem(forceFoldersOutlineKey(projectId)) === "1";
  } catch (_) {
    return false;
  }
}

function writeForceFoldersOutline(projectId, on) {
  try {
    const key = forceFoldersOutlineKey(projectId);
    if (on) localStorage.setItem(key, "1");
    else localStorage.removeItem(key);
  } catch (_) { /* ignore */ }
}

/** Prefer outline.folders when present or force flag is set. */
function shouldUseFoldersOutline() {
  if (!Array.isArray(state.folders)) return false;
  if (state.forceFoldersOutline) return true;
  return state.folders.length > 0;
}

/**
 * Normalize API folder node for binder render.
 * - folder_id: real folder.id (reparent)
 * - id: legacy part/chapter source_id when mapped (rename/trash/scene APIs)
 */
function normalizeApiFolderNode(folder, depth = 0, parentPartSourceId = null) {
  if (!folder || typeof folder !== "object") return folder;
  const folderId = Number(folder.id);
  const sourceKind = folder.source_kind || null;
  const rawSid = folder.source_id;
  const sourceId = rawSid != null && rawSid !== "" ? Number(rawSid) : null;
  // is_box is a visual flag independent of hierarchy. Explicit false wins.
  // Legacy part maps default to boxed when is_box omitted.
  let isBox;
  if (folder.is_box === false || folder.is_box === 0 || folder.is_box === "0") {
    isBox = false;
  } else if (folder.is_box === true || folder.is_box === 1 || folder.is_box === "1") {
    isBox = true;
  } else {
    isBox = sourceKind === "part";
  }
  const legacyId = Number.isFinite(sourceId) && sourceId > 0 ? sourceId : folderId;
  // part_id for child styling: if parent is source part, keep link even when unboxed
  const nextParentPart = sourceKind === "part" ? legacyId : parentPartSourceId;
  const kids = Array.isArray(folder.children) ? folder.children : [];
  const color = folder.color != null && folder.color !== ""
    ? String(folder.color).trim().toLowerCase()
    : null;
  const colorBright = folder.color_bright != null && folder.color_bright !== ""
    ? String(folder.color_bright).trim().toLowerCase()
    : null;
  return {
    ...folder,
    folder_id: folderId,
    id: legacyId,
    is_box: isBox,
    is_pinned: folder.is_pinned ? 1 : 0,
    is_bookmarked: folder.is_bookmarked ? 1 : 0,
    color,
    color_bright: colorBright,
    kind: isBox ? "part" : "chapter",
    source_kind: sourceKind,
    source_id: Number.isFinite(sourceId) ? sourceId : null,
    part_id: isBox ? null : parentPartSourceId,
    depth,
    scenes: Array.isArray(folder.scenes) ? folder.scenes : [],
    children: kids.map((ch) => normalizeApiFolderNode(ch, depth + 1, nextParentPart)),
  };
}

function collectChaptersFromFolderForest(nodes, out = []) {
  for (const node of nodes || []) {
    if (!node) continue;
    if (!binderFolderNodeIsBox(node)) {
      out.push({
        id: node.id,
        title: node.title,
        part_id: node.part_id,
        notes_md: node.notes_md,
        scenes: node.scenes || [],
        folder_id: node.folder_id,
      });
    }
    collectChaptersFromFolderForest(node.children || [], out);
  }
  return out;
}

/** Chapters in binder display order: parts first, then ungrouped. */
function getBinderChaptersInOrder() {
  if (shouldUseFoldersOutline()) {
    const roots = (state.folders || []).map((f) => normalizeApiFolderNode(f));
    const fromFolders = collectChaptersFromFolderForest(roots);
    if (fromFolders.length) return fromFolders;
  }
  const out = [];
  for (const part of state.parts || []) {
    for (const chapter of part.chapters || []) out.push(chapter);
  }
  for (const chapter of state.ungroupedChapters || []) out.push(chapter);
  if (!out.length && Array.isArray(state.outline)) return state.outline.slice();
  return out;
}

/** Ensure the chapter (and ancestor manuscripts) holding the active scene is visible. */
function ensureActiveSceneChapterExpanded(chapters) {
  if (!state.sceneId || !Array.isArray(chapters)) return;
  const targetId = Number(state.sceneId);
  let found = false;
  const path = [];
  let hostChapter = null;

  const walkScenes = (nodes, ancestors, chapter) => {
    for (const scene of nodes || []) {
      const next = ancestors.concat(Number(scene.id));
      if (Number(scene.id) === targetId) {
        found = true;
        hostChapter = chapter;
        path.push(...ancestors);
        return true;
      }
      for (const nested of scene.child_chapters || []) {
        if (walkScenes(nested.scenes || [], next, nested)) return true;
      }
      if (walkScenes(scene.children || [], next, chapter)) return true;
    }
    return false;
  };

  for (const chapter of chapters) {
    if (walkScenes(chapter.scenes || [], [], chapter)) break;
  }
  if (!found || !hostChapter) return;
  setChapterCollapsed(hostChapter.id, false);
  if (hostChapter.part_id != null) setPartCollapsed(hostChapter.part_id, false);
  // Expand ancestor folders when the host itself is nested under a manuscript.
  walkBinderChapters(chapters, (ch) => {
    if (Number(ch.id) === Number(hostChapter.id)) return;
    walkSceneTree(ch.scenes || [], (scene) => {
      for (const nested of scene.child_chapters || []) {
        if (Number(nested.id) === Number(hostChapter.id)) {
          setChapterCollapsed(ch.id, false);
          setSceneCollapsed(Number(scene.id), false);
        }
      }
    });
  });
  for (const ancestorId of path) setSceneCollapsed(ancestorId, false);
}

function applyChapterExpandedState(section, expanded) {
  if (!section) return;
  const chapterId = section.dataset.chapterId;
  section.classList.toggle("is-collapsed", !expanded);
  section.dataset.expanded = expanded ? "true" : "false";
  const twistie = section.querySelector(".chapter-twistie");
  if (twistie) {
    twistie.setAttribute("aria-expanded", expanded ? "true" : "false");
    twistie.title = expanded ? i18n.t('app.씬_목록_접기') : i18n.t('app.씬_목록_펼치기');
    twistie.setAttribute("aria-label", expanded ? i18n.t('app.씬_목록_접기') : i18n.t('app.씬_목록_펼치기'));
  }
  const children = section.querySelector(".chapter-children");
  if (children) {
    children.hidden = !expanded;
    children.classList.toggle("is-collapsed", !expanded);
  }
  if (chapterId) setChapterCollapsed(chapterId, !expanded);
}

function toggleChapterExpanded(chapterId) {
  const outline = $("outline");
  const section = outline?.querySelector(`.outline-chapter[data-chapter-id="${chapterId}"]`);
  if (!section) return;
  const expanded = section.dataset.expanded !== "true";
  applyChapterExpandedState(section, expanded);
}

/**
 * Push open-scene meta (status, title, …) into outline state and re-render the binder
 * so the left list stays in sync without waiting for a full loadProject().
 */
function syncOpenSceneToOutlineBinder(patch = {}) {
  const sceneId = Number(patch.sceneId ?? state.sceneId);
  if (!sceneId) return false;

  const nextStatus = patch.status != null
    ? String(patch.status)
    : ($("sceneStatus")?.value || state.scene?.status || null);
  const nextTitle = patch.title != null
    ? String(patch.title)
    : ($("sceneTitle")?.value?.trim() || state.scene?.title || null);
  const nextBodyPreview = patch.body_preview != null
    ? String(patch.body_preview)
    : (typeof getEditorPlainText === "function"
      ? firstSentenceFromPlain(getEditorPlainText())
      : null);

  const applyToScene = (scene) => {
    if (!scene || Number(scene.id) !== sceneId) return false;
    if (nextStatus != null) scene.status = nextStatus;
    if (nextTitle != null && nextTitle !== "") scene.title = nextTitle;
    if (isUntitledSceneTitle(scene.title) && nextBodyPreview != null) {
      scene.body_preview = nextBodyPreview;
    }
    return true;
  };

  // Walk binder chapters (parts + ungrouped) and flat outline — same objects, but
  // scenes_flat is a separate snapshot that must be updated too.
  const seenChapter = new Set();
  const chapters = [];
  for (const ch of [
    ...getBinderChaptersInOrder(),
    ...(Array.isArray(state.outline) ? state.outline : []),
  ]) {
    const id = Number(ch?.id);
    if (!id || seenChapter.has(id)) continue;
    seenChapter.add(id);
    chapters.push(ch);
  }

  let found = false;
  for (const chapter of chapters) {
    walkSceneTree(chapter.scenes || [], (scene) => {
      if (applyToScene(scene)) found = true;
    });
    if (Array.isArray(chapter.scenes_flat)) {
      for (const scene of chapter.scenes_flat) {
        if (applyToScene(scene)) found = true;
      }
    }
  }

  if (state.scene && Number(state.scene.id || state.sceneId) === sceneId) {
    if (nextStatus != null) state.scene.status = nextStatus;
    if (nextTitle != null && nextTitle !== "") state.scene.title = nextTitle;
  }

  if (!found) return false;
  renderOutline(state.outline);
  return true;
}

function renderSceneTreeHtml(scenes, {
  chapterId,
  depth = 0,
  collapsed,
  collapsedScenes,
  baitPlantIds,
  baitRecoverIds,
  pinnedSet,
  parentSceneId = null,
  hasTrailingSiblings = false,
}) {
  const list = Array.isArray(scenes) ? scenes : [];
  const folderCollapse = collapsed instanceof Set ? collapsed : new Set();
  if (!list.length) {
    return depth === 0
      ? i18n.t('app.p_class_hint_scene_empt')
      : "";
  }
  const pins = pinnedSet instanceof Set ? pinnedSet : new Set();
  const bookmarksSnapshot = loadBookmarks();
  return list.map((scene, index) => {
    // Not last if more scene siblings follow, or parent will render nested folders after this list.
    const isLast = index === list.length - 1 && !hasTrailingSiblings;
    const isComplete = scene.status === "complete";
    const statusText = statusLabel[scene.status] || scene.status || "";
    // 작성 상태는 고정 폭 슬롯 → 북마크 유무와 관계없이 열 정렬
    const statusInner = isComplete
      ? i18n.t('app.span_class_scene_comple')
      : `<span class="scene-status">${escapeHtml(statusText)}</span>`;
    const statusMarkup = `<span class="scene-status-slot">${statusInner}</span>`;
    const sid = Number(scene.id);
    // 북마크는 작성 상태 왼쪽 고정 슬롯 (없어도 자리는 유지)
    const sceneBm = findBookmark(bookmarksSnapshot, "scene", sid);
    const bookmarkMark = sceneBm
      ? `${i18n.t('app.span_class_scene_bookma', {'escapeHtml(bookmarkColorMeta(sceneBm.color).label || "")': escapeHtml(bookmarkColorMeta(sceneBm.color).label || ""), 'bookmarkColorMeta(sceneBm.color).hex': bookmarkColorMeta(sceneBm.color).hex})}`
      : `<span class="scene-bookmark-slot" aria-hidden="true"></span>`;
    const kids = scene.children || [];
    const childFolders = Array.isArray(scene.child_chapters) ? scene.child_chapters : [];
    const hasKids = kids.length > 0;
    const hasChildFolders = childFolders.length > 0;
    const hasNest = hasKids || hasChildFolders;
    const childCollapsed = collapsedScenes.has(sid);
    const childExpanded = !childCollapsed;
    const hasPlant = baitPlantIds.has(sid);
    const hasRecover = baitRecoverIds.has(sid);
    const isPinned = pins.has(sid);
    const baitIcons = [
      hasPlant
        ? i18n.t('app.span_class_scene_bait_b')
        : "",
      hasRecover
        ? i18n.t('app.span_class_scene_bait_b_2')
        : "",
    ].join("");
    const pinIcon = isPinned
      ? i18n.t('app.span_class_scene_pin_ba')
      : "";
    const baitTitleBits = [
      hasPlant ? i18n.t('app.떡밥_심음') : "",
      hasRecover ? i18n.t('app.떡밥_회수_예정') : "",
      isPinned ? i18n.t('app.상단_고정') : "",
    ].filter(Boolean).join(" · ");
    const titleExtra = [isComplete ? i18n.t('app.완성') : "", baitTitleBits].filter(Boolean).join(" · ");
    const parentAttr = parentSceneId != null ? String(parentSceneId) : "";
    const display = getOutlineSceneDisplay(scene);
    const italicOn = Boolean(parentSceneId) && isSceneTitleItalic(sid);
    const titleClass = [
      display.isPreview ? "scene-title is-body-preview" : "scene-title",
      italicOn ? "is-title-italic" : "",
    ].filter(Boolean).join(" ");
    // 하위가 있을 때만 접기 버튼. 잎도 같은 폭 스페이서로 작성상태 열을 맞춤
    const expanded = childExpanded ? "true" : "false";
    const twistieTitle = childExpanded ? i18n.t('app.하위_접기') : i18n.t('app.하위_펼치기');
    const twistie = hasNest
      ? i18n.t('app.button_type_button_clas_10', { sid: sid, expanded: expanded, title: twistieTitle })
      : `<span class="scene-twistie-spacer" aria-hidden="true"></span>`;
    // Folders render after child manuscripts under the same parent.
    // Route through recursive binder renderer (non-box chapter path → same markup).
    const nestDepth = Math.min(depth + 1, 8);
    const nestedFoldersHtml = hasChildFolders
      ? childFolders.map((ch, folderIndex) => renderBinderFolderNodeHtml(
          asBinderFolderNode(ch, { isBox: false }),
          {
            collapsed: folderCollapse,
            collapsedScenes,
            baitPlantIds,
            baitRecoverIds,
            pinnedSet: pins,
            folderLevel: nestDepth >= 2 ? "is-level-2" : "is-level-1",
            nestedUnderScene: true,
            nestDepth,
            binderDepth: Math.min(nestDepth, 8),
            isLastSibling: folderIndex === childFolders.length - 1,
          },
        )).join("")
      : "";
    const childrenHtml = hasNest
      ? `<div class="scene-children ${childExpanded ? "" : "is-collapsed"}" ${childExpanded ? "" : "hidden"} data-parent-scene="${sid}">
          ${hasKids ? renderSceneTreeHtml(kids, {
            chapterId,
            depth: depth + 1,
            collapsed: folderCollapse,
            collapsedScenes,
            baitPlantIds,
            baitRecoverIds,
            pinnedSet: pins,
            parentSceneId: sid,
            hasTrailingSiblings: hasChildFolders,
          }) : ""}
          ${nestedFoldersHtml}
        </div>`
      : "";
    const addAfterBtn = `${i18n.t('app.button_type_button_clas_11', {sid: sid, chapterId: chapterId, parentAttr: parentAttr})}`;
    return `
      <div class="scene-tree-item depth-${Math.min(depth, 8)} ${isLast ? "is-last" : ""} ${hasNest ? "" : "is-leaf"} ${childExpanded || !hasNest ? "" : "is-collapsed"}" data-scene-node="${sid}" data-depth="${depth}" draggable="true">
        <div class="scene-row">
          ${twistie}
          <button type="button" draggable="true" class="scene-link ${Number(state.sceneId) === sid ? "active" : ""} ${isComplete ? "is-complete" : ""} ${isPinned ? "is-pinned" : ""} ${sceneBm ? "is-bookmarked" : ""}" data-scene="${sid}" data-chapter-id="${chapterId}" data-parent-scene="${parentAttr}" title="${escapeHtml(display.tooltip)}${titleExtra ? ` · ${titleExtra}` : ""}${sceneBm ? " · 북마크" : ""} · 더블클릭: 이름 바꾸기 · 끌어 원하는 위치에 놓기 (위/아래: 순서 · 가운데: 하위)">
            ${bookmarkMark}
            ${statusMarkup}
            ${pinIcon}
            ${baitIcons}
            <span class="${titleClass}">${escapeHtml(display.label)}</span>
          </button>
          ${addAfterBtn}
        </div>
        ${childrenHtml}
      </div>`;
  }).join("");
}

/**
 * Phase 4-1: recursive binder folder render helpers.
 * Outline API still returns legacy part→chapter (depth 2). These helpers walk
 * an arbitrary tree so deeper nesting can plug in later without a second rewrite.
 * With current data, DOM/classes match the previous fixed two-level loop.
 */

/** Tag a legacy outline node for the recursive renderer. */
/** 목차 폴더 행 왼쪽 아이콘 (펼침 버튼 겸용 · 선 그림) */
const FOLDER_ICON_SVG = `<svg class="folder-glyph" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">
  <path class="folder-body" d="M3.75 8.25A1.75 1.75 0 0 1 5.5 6.5h4.05c.33 0 .65.12.9.34l1.35 1.16c.25.22.57.34.9.34H18.5a1.75 1.75 0 0 1 1.75 1.75v7.4a1.75 1.75 0 0 1-1.75 1.75H5.5A1.75 1.75 0 0 1 3.75 17.15V8.25z"/>
  <path d="M3.75 10.5h16.5"/>
</svg>`;

function asBinderFolderNode(node, { isBox = false } = {}) {
  if (!node || typeof node !== "object") return node;
  if (node.kind != null || Object.prototype.hasOwnProperty.call(node, "is_box")) {
    return node;
  }
  return { ...node, kind: isBox ? "part" : "chapter", is_box: Boolean(isBox) };
}

/** Whether this binder node uses the box shell (visual is_box; independent of depth). */
function binderFolderNodeIsBox(node) {
  if (!node || typeof node !== "object") return false;
  if (Object.prototype.hasOwnProperty.call(node, "is_box")) {
    const v = node.is_box;
    if (v === false || v === 0 || v === "0" || v === "false") return false;
    return v === true || v === 1 || v === "1" || v === "true";
  }
  if (node.kind === "part") return true;
  if (node.kind === "chapter") return false;
  return false;
}

/**
 * Immediate child folders under a binder node.
 * - Box (part): legacy `chapters` (or future `children`)
 * - Non-box chapter: only explicit nested lists (`children` / `child_folders`),
 *   never legacy `chapters` (that field is the part→chapter list).
 */
function getBinderChildFolders(node) {
  if (!node || typeof node !== "object") return [];
  if (Array.isArray(node.children) && node.children.length) return node.children;
  if (Array.isArray(node.child_folders) && node.child_folders.length) {
    return node.child_folders;
  }
  if (binderFolderNodeIsBox(node) && Array.isArray(node.chapters)) {
    return node.chapters;
  }
  return [];
}

function isTransparentBinderNode(node) {
  if (!node) return false;
  if (node.transparent === true || node.transparent === 1 || node.transparent === "1") return true;
  return String(node.notes_md || "").includes("supertory:transparent_volume");
}

/** Keep one empty hidden 「본편」 tray; extra empty trays stack duplicate + buttons. */
function withoutEmptyDuplicateTransparentFolders(folders) {
  const list = Array.isArray(folders) ? folders : [];
  let keptEmpty = false;
  return list.filter((node) => {
    if (!isTransparentBinderNode(node)) return true;
    const hasScenes = Array.isArray(node.scenes) && node.scenes.length > 0;
    const nested = getBinderChildFolders(node);
    if (hasScenes || nested.length) return true;
    if (keptEmpty) return false;
    keptEmpty = true;
    return true;
  });
}

/**
 * Recursive binder folder node renderer.
 * is_box → outline-part box shell; otherwise → chapter shell + scene leaves.
 * Nested folder children are rendered by recursing into this same function.
 */
function renderBinderFolderNodeHtml(node, opts = {}) {
  if (!node) return "";
  const {
    collapsed,
    collapsedScenes,
    collapsedParts,
    baitPlantIds,
    baitRecoverIds,
    pinnedSet,
    folderLevel = null,
    nestedUnderScene = false,
    nestDepth = 1,
    binderDepth = 0,
    isLastSibling = true,
  } = opts;
  const depth = Math.max(0, Math.min(Number(binderDepth) || 0, 8));
  const depthClass = ` binder-depth-${depth}`;
  const depthAttr = ` data-binder-depth="${depth}"`;

  if (binderFolderNodeIsBox(node)) {
    const childFolders = withoutEmptyDuplicateTransparentFolders(getBinderChildFolders(node));
    const partExpanded = !(collapsedParts instanceof Set && collapsedParts.has(Number(node.id)));
    const folderIdAttr = node.folder_id != null && node.folder_id !== ""
      ? ` data-folder-id="${Number(node.folder_id)}"`
      : "";
    const colorKey = String(node.color || "").trim().toLowerCase();
    const colorAttr = colorKey ? ` data-folder-color="${escapeHtml(colorKey)}"` : "";
    const colorBrightKey = String(node.color_bright || "").trim().toLowerCase();
    const colorBrightAttr = colorBrightKey ? ` data-folder-color-bright="${escapeHtml(colorBrightKey)}"` : "";
    const pinAttr = ` data-is-pinned="${node.is_pinned ? "1" : "0"}"`;
    const bmOn = Boolean(node.is_bookmarked);
    const bmAttr = ` data-is-bookmarked="${bmOn ? "1" : "0"}"`;
    const boxAttr = ` data-is-box="1"`;
    const sk = node.source_kind || "";
    const sourceKindAttr = sk ? ` data-source-kind="${escapeHtml(sk)}"` : "";
    // APIs: part source → part id attrs; chapter source boxed as shell still uses chapter APIs
    const isChapterSource = sk === "chapter";
    const renameAttr = isChapterSource
      ? `data-rename-chapter="${node.id}"`
      : `data-rename-part="${node.id}"`;
    // Box shell is always .outline-part; expand/collapse via part toggle only.
    const toggleAttr = `data-toggle-part="${node.id}"`;
    const titleClass = isChapterSource
      ? `chapter-title folder-title-box folder-title is-level-0${bmOn ? " is-bookmarked" : ""}`
      : `part-title folder-title-box folder-title is-level-0${bmOn ? " is-bookmarked" : ""}`;
    const idAttrs = isChapterSource
      ? ` data-chapter-id="${node.id}" data-part-id=""`
      : ` data-part-id="${node.id}"`;
    const childOpts = {
      collapsed,
      collapsedScenes,
      collapsedParts,
      baitPlantIds,
      baitRecoverIds,
      pinnedSet,
      binderDepth: depth + 1,
    };
    const scenes = Array.isArray(node.scenes) ? node.scenes : [];
    const hasScenes = scenes.length > 0;
    const sceneItems = hasScenes
      ? renderSceneTreeHtml(scenes, {
          chapterId: node.id,
          depth: 0,
          collapsed,
          collapsedScenes,
          baitPlantIds,
          baitRecoverIds,
          pinnedSet,
          parentSceneId: null,
        })
      : "";
    const foldersHtml = childFolders.length
      ? childFolders.map((ch, idx) => renderBinderFolderNodeHtml(
          asBinderFolderNode(ch, { isBox: binderFolderNodeIsBox(ch) }),
          {
            ...childOpts,
            folderLevel: binderFolderNodeIsBox(ch)
              ? "is-level-0"
              : (depth >= 1 ? "is-level-2" : "is-level-1"),
            isLastSibling: idx === childFolders.length - 1,
          },
        )).join("")
      : "";
    const chapterHtml = (hasScenes || childFolders.length)
      ? `${sceneItems}${foldersHtml}`
      : i18n.t('app.p_class_hint_part_empty');
    const folderTreeClass = (!nestedUnderScene && depth > 0) ? " is-folder-tree-child" : "";
    const lastClass = (depth > 0 && isLastSibling) ? " is-last" : "";
    const nestedFoldersClass = childFolders.length ? " has-nested-folders" : "";
    return `
    <section class="outline-part${depthClass} ${partExpanded ? "" : "is-collapsed"}${folderTreeClass}${lastClass}"${idAttrs}${folderIdAttr}${depthAttr}${colorAttr}${colorBrightAttr}${pinAttr}${bmAttr}${boxAttr}${sourceKindAttr} data-expanded="${partExpanded ? "true" : "false"}" draggable="false">
      <div class="part-row" draggable="true" title="${i18n.t('app.끌어_폴더_순서_바꾸기')}">
        <button
          type="button"
          class="part-twistie chapter-twistie folder-icon-btn"
          ${toggleAttr}
          aria-expanded="${partExpanded ? "true" : "false"}"
          title="${partExpanded ? "폴더 목록 접기" : "폴더 목록 펼치기"}"
        >${FOLDER_ICON_SVG}</button>
        ${folderBookmarkMarkHtml(bmOn)}
        <button type="button" draggable="true" class="${titleClass}" ${renameAttr} title="${escapeHtml(node.title)} (더블클릭: 이름 바꾸기 · 끌어 이동)">${escapeHtml(node.title)}</button>
      </div>
      <div class="part-children ${partExpanded ? "" : "is-collapsed"}${nestedFoldersClass}" ${partExpanded ? "" : "hidden"} data-part-chapters="${isChapterSource ? "" : node.id}" role="group" aria-label="${escapeHtml(node.title)} 폴더">
        ${chapterHtml}
      </div>
    </section>`;
  }

  // Non-box folder: chapter shell + scene leaves (+ optional nested folders).
  return renderChapterOutlineHtml(node, {
    collapsed,
    collapsedScenes,
    collapsedParts,
    baitPlantIds,
    baitRecoverIds,
    pinnedSet,
    folderLevel,
    nestedUnderScene,
    nestDepth,
    binderDepth: depth,
    isLastSibling,
  });
}

function renderChapterOutlineHtml(chapter, {
  collapsed,
  collapsedScenes,
  collapsedParts,
  baitPlantIds,
  baitRecoverIds,
  pinnedSet,
  folderLevel: folderLevelOverride = null,
  nestedUnderScene = false,
  nestDepth = 1,
  binderDepth = 0,
  isLastSibling = true,
}) {
  const scenes = chapter.scenes || [];
  const hasScenes = scenes.length > 0;
  const transparent = Boolean(chapter.transparent) ||
    String(chapter.notes_md || "").includes("supertory:transparent_volume");
  const expanded = transparent ? true : !collapsed.has(Number(chapter.id));
  const flat = flattenChapterScenes(chapter);
  const allComplete = hasScenes && flat.length > 0 && flat.every((scene) => scene.status === "complete");
  // Nested under a manuscript: keep staircase by starting children one step deeper.
  const sceneDepth = nestedUnderScene ? Math.min(Number(nestDepth) + 1, 8) : 0;
  // Nested folders under this chapter (unlimited depth)
  const nestedChildFolders = withoutEmptyDuplicateTransparentFolders(
    getBinderChildFolders(asBinderFolderNode(chapter, { isBox: false })),
  );
  const depth = Math.max(0, Math.min(Number(binderDepth) || 0, 8));
  const hasNestedFolders = nestedChildFolders.length > 0;
  const sceneItems = hasScenes
    ? renderSceneTreeHtml(scenes, {
        chapterId: chapter.id,
        depth: sceneDepth,
        collapsed,
        collapsedScenes,
        baitPlantIds,
        baitRecoverIds,
        pinnedSet,
        parentSceneId: null,
      })
    : (transparent || hasNestedFolders
      ? ""
      : i18n.t('app.p_class_hint_scene_empt'));
  const nestedChildFoldersHtml = hasNestedFolders
    ? nestedChildFolders.map((ch, idx) => renderBinderFolderNodeHtml(
        asBinderFolderNode(ch, { isBox: binderFolderNodeIsBox(ch) }),
        {
          collapsed,
          collapsedScenes,
          collapsedParts,
          baitPlantIds,
          baitRecoverIds,
          pinnedSet,
          binderDepth: depth + 1,
          folderLevel: binderFolderNodeIsBox(ch)
            ? "is-level-0"
            : (depth >= 1 ? "is-level-2" : "is-level-1"),
          isLastSibling: idx === nestedChildFolders.length - 1,
        },
      )).join("")
    : "";
  // Only inject a trailing block when nested folders exist (visual parity when empty).
  const afterScenesHtml = nestedChildFoldersHtml ? `\n        ${nestedChildFoldersHtml}` : "";

  const hasParentPart = chapter.part_id != null && chapter.part_id !== "";
  const partAttr = hasParentPart
    ? ` data-part-id="${Number(chapter.part_id)}"`
    : ' data-part-id=""';
  const folderIdAttr = chapter.folder_id != null && chapter.folder_id !== ""
    ? ` data-folder-id="${Number(chapter.folder_id)}"`
    : "";
  const colorKey = String(chapter.color || "").trim().toLowerCase();
  const colorAttr = colorKey ? ` data-folder-color="${escapeHtml(colorKey)}"` : "";
  const colorBrightKey = String(chapter.color_bright || "").trim().toLowerCase();
  const colorBrightAttr = colorBrightKey ? ` data-folder-color-bright="${escapeHtml(colorBrightKey)}"` : "";
  const pinAttr = ` data-is-pinned="${chapter.is_pinned ? "1" : "0"}"`;
  const bmOn = Boolean(chapter.is_bookmarked);
  const bmAttr = ` data-is-bookmarked="${bmOn ? "1" : "0"}"`;
  const boxAttr = ` data-is-box="0"`;
  const sk = chapter.source_kind || "chapter";
  const sourceKindAttr = ` data-source-kind="${escapeHtml(sk)}"`;
  // Sub-folder under top box → level-1; ungrouped top folder → level-0; under manuscript → level-2
  const folderLevel = folderLevelOverride
    || (hasParentPart ? "is-level-1" : "is-level-0");
  const sceneNestDepthClass = nestedUnderScene ? ` depth-${Math.min(Number(nestDepth) || 1, 8)}` : "";
  const binderDepthClass = ` binder-depth-${depth}`;
  const binderDepthAttr = ` data-binder-depth="${depth}"`;
  const lastClass = ((nestedUnderScene || depth > 0) && isLastSibling) ? " is-last" : "";
  const nestClass = nestedUnderScene ? " is-nested-under-scene" : "";
  const folderTreeClass = (!nestedUnderScene && depth > 0) ? " is-folder-tree-child" : "";
  const nestedFoldersClass = hasNestedFolders ? " has-nested-folders" : "";
  if (transparent) {
    // Internal 「본편」 folder: hide row, show manuscripts directly under the 권.
    return `
    <section class="outline-chapter is-transparent-chapter${nestClass}${sceneNestDepthClass}${binderDepthClass}${lastClass}" data-chapter-id="${chapter.id}"${partAttr}${folderIdAttr}${binderDepthAttr}${boxAttr}${sourceKindAttr} data-transparent="true" data-expanded="true" data-depth="${nestedUnderScene ? nestDepth : ""}" draggable="false">
      <div class="chapter-children" role="group" aria-label="${i18n.t('app.원고')}">
        ${sceneItems}${afterScenesHtml}
        <button type="button" class="chapter-add-scene transparent-add-scene" data-chapter="${chapter.id}" title="${i18n.t('app.원고_추가')}">+</button>
      </div>
    </section>`;
  }
  return `
    <section class="outline-chapter ${expanded ? "" : "is-collapsed"} ${allComplete ? "is-chapter-complete" : ""}${nestClass}${folderTreeClass}${sceneNestDepthClass}${binderDepthClass}${lastClass}" data-chapter-id="${chapter.id}"${partAttr}${folderIdAttr}${binderDepthAttr}${colorAttr}${colorBrightAttr}${pinAttr}${bmAttr}${boxAttr}${sourceKindAttr} data-expanded="${expanded ? "true" : "false"}" data-depth="${nestedUnderScene ? nestDepth : ""}" draggable="${nestedUnderScene ? "false" : "true"}">
      <div class="chapter-row ${allComplete ? "is-chapter-complete" : ""}" title="${i18n.t('app.끌어_폴더_순서_바꾸기')}">
        <button
          type="button"
          class="chapter-twistie folder-icon-btn"
          data-toggle-chapter="${chapter.id}"
          aria-expanded="${expanded ? "true" : "false"}"
          title="${expanded ? "원고 목록 접기" : "원고 목록 펼치기"}"
          aria-label="${expanded ? "원고 목록 접기" : "원고 목록 펼치기"}"
        >${FOLDER_ICON_SVG}</button>
        ${folderBookmarkMarkHtml(bmOn)}
        <button type="button" draggable="${nestedUnderScene ? "false" : "true"}" class="chapter-title folder-title-box folder-title ${folderLevel}${bmOn ? " is-bookmarked" : ""} ${allComplete ? "is-complete" : ""}" data-rename-chapter="${chapter.id}" title="${escapeHtml(chapter.title)}${allComplete ? " · 완결" : ""} (더블클릭: 이름 바꾸기${nestedUnderScene ? "" : " · 끌어 이동"})">${escapeHtml(chapter.title)}</button>
      </div>
      <div class="chapter-children ${expanded ? "" : "is-collapsed"}${nestedFoldersClass}" ${expanded ? "" : "hidden"} role="group" aria-label="${escapeHtml(chapter.title)} 씬">
        ${sceneItems}${afterScenesHtml}
      </div>
    </section>`;
}

let outlineSceneOpenTimer = null;

function renderOutline(chaptersArg) {
  const outline = $("outline");
  if (!outline) return;
  const useFolders = shouldUseFoldersOutline();
  const parts = Array.isArray(state.parts) ? state.parts : [];
  const ungrouped = Array.isArray(state.ungroupedChapters)
    ? state.ungroupedChapters
    : (Array.isArray(chaptersArg) ? chaptersArg : (state.outline || []));
  const flatChapters = getBinderChaptersInOrder();
  const foldersEmpty = useFolders && !(state.folders || []).length;
  if (foldersEmpty || (!useFolders && !flatChapters.length && !parts.length)) {
    outline.innerHTML = i18n.t('app.p_class_hint_아직_챕터가_없어요');
    try { updateOutlineFolderCount(); } catch (_) { /* ignore */ }
    return;
  }

  ensureActiveSceneChapterExpanded(flatChapters);
  const collapsed = getCollapsedChapterIds();
  const collapsedScenes = getCollapsedSceneIds();
  const collapsedParts = getCollapsedPartIds();
  const baitPlantIds = typeof getBaitPlantSceneIds === "function" ? getBaitPlantSceneIds() : new Set();
  const baitRecoverIds = typeof getBaitRecoverSceneIds === "function" ? getBaitRecoverSceneIds() : new Set();
  const pinnedSet = new Set(sanitizePinnedSceneIds());
  const chapterOpts = {
    collapsed,
    collapsedScenes,
    collapsedParts,
    baitPlantIds,
    baitRecoverIds,
    pinnedSet,
  };

  try { applyOutlineTitleFontSize(getOutlineTitleFontSize(), { persist: false }); } catch (_) { /* ignore */ }
  try { applyOutlineRowGap(getOutlineRowGap(), { persist: false }); } catch (_) { /* ignore */ }
  try { updateOutlineFolderCount(); } catch (_) { /* ignore */ }

  let bodyHtml = "";
  if (useFolders) {
    // Canonical unlimited-depth tree (outline.folders → folder.id on data-folder-id)
    const roots = (state.folders || []).map((f) => normalizeApiFolderNode(f));
    bodyHtml = roots.map((node) => renderBinderFolderNodeHtml(
      asBinderFolderNode(node, { isBox: binderFolderNodeIsBox(node) }),
      chapterOpts,
    )).join("");
  } else {
    // Legacy fallback: parts (boxes) + ungrouped chapters
    const partBlocks = parts.map((part) => renderBinderFolderNodeHtml(
      asBinderFolderNode(part, { isBox: true }),
      chapterOpts,
    )).join("");
    const ungroupedHtml = ungrouped.length
      ? `
    <div class="outline-ungrouped ${parts.length ? "" : "is-flat"}" data-part-chapters="" data-part-id="">
      ${parts.length ? i18n.t('app.div_class_outline_ungro') : ""}
      ${ungrouped.map((ch) => renderBinderFolderNodeHtml(
        asBinderFolderNode(ch, { isBox: false }),
        chapterOpts,
      )).join("")}
    </div>`
      : (parts.length
        ? i18n.t('app.p_class_hint_outline_un')
        : "");
    bodyHtml = `${partBlocks}${ungroupedHtml}`;
  }

  outline.innerHTML = `${renderPinnedOutlineSectionHtml()}${bodyHtml}`;

  try { applyOutlineTitleFontSize(getOutlineTitleFontSize(), { persist: false }); } catch (_) { /* ignore */ }
  try { applyOutlineRowGap(getOutlineRowGap(), { persist: false }); } catch (_) { /* ignore */ }
  try { updateOutlineFolderCount(); } catch (_) { /* ignore */ }

  outline.querySelectorAll("[data-toggle-chapter]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      event.preventDefault();
      toggleChapterExpanded(button.dataset.toggleChapter);
    });
    button.addEventListener("mousedown", (event) => event.stopPropagation());
  });
  outline.querySelectorAll("[data-toggle-part]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      event.preventDefault();
      togglePartExpanded(button.dataset.togglePart);
    });
    button.addEventListener("mousedown", (event) => event.stopPropagation());
  });
  outline.querySelectorAll("[data-toggle-scene]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      event.preventDefault();
      toggleSceneExpanded(button.dataset.toggleScene);
    });
    button.addEventListener("mousedown", (event) => event.stopPropagation());
  });
  outline.querySelectorAll("[data-add-after-scene]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      event.preventDefault();
      const sceneId = Number(button.dataset.addAfterScene);
      if (!sceneId) return;
      const chapterId = button.dataset.chapterId || findChapterIdForScene(sceneId);
      if (!chapterId) {
        toast(i18n.t('app.폴더를_찾지_못했어요'));
        return;
      }
      const parentRaw = button.dataset.parentScene;
      const parentSceneId = parentRaw === "" || parentRaw == null ? null : Number(parentRaw);
      createScene(chapterId, {
        afterSceneId: sceneId,
        parentSceneId: Number.isFinite(parentSceneId) ? parentSceneId : null,
      }).catch(handleError);
    });
    button.addEventListener("mousedown", (event) => event.stopPropagation());
  });
  outline.querySelectorAll("[data-chapter]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      setChapterCollapsed(button.dataset.chapter, false);
      createScene(button.dataset.chapter).catch(handleError);
    });
  });
  outline.querySelectorAll("[data-part-add-chapter]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      const partId = Number(button.dataset.partAddChapter);
      setPartCollapsed(partId, false);
      createChapter({ partId }).catch(handleError);
    });
  });
  const openFolderContextFromSection = (event, section, row) => {
    if (!section) return;
    event.preventDefault();
    event.stopPropagation();
    const folderRaw = section.dataset?.folderId;
    const folderId = folderRaw === "" || folderRaw == null ? null : Number(folderRaw);
    const isBoxRaw = section.dataset?.isBox;
    const colorRaw = section.dataset?.folderColor;
    const colorBrightRaw = section.dataset?.folderColorBright;
    const pinRaw = section.dataset?.isPinned;
    const bmRaw = section.dataset?.isBookmarked;
    const sk = section.dataset?.sourceKind || "";
    const titleBtn = row.querySelector("[data-rename-chapter], [data-rename-part]");
    const title = titleBtn?.textContent || titleBtn?.getAttribute("title") || "";
    const isBox = isBoxRaw === "1" || isBoxRaw === "true";
    const isPinned = pinRaw === "1" || pinRaw === "true";
    const isBookmarked = bmRaw === "1" || bmRaw === "true";
    const color = colorRaw || null;
    const colorBright = colorBrightRaw || null;
    // Prefer source_kind for API menu; boxed chapter still uses chapter menu
    if (sk === "chapter" || section.dataset?.chapterId) {
      const chapterId = section.dataset.chapterId
        || titleBtn?.dataset?.renameChapter
        || section.dataset.partId;
      if (!chapterId) return;
      const partRaw = section.dataset?.partId;
      showChapterContextMenu(event.clientX, event.clientY, {
        id: chapterId,
        title,
        partId: partRaw === "" || partRaw == null ? null : Number(partRaw),
        folderId,
        isBox,
        isPinned,
        isBookmarked,
        color,
        color_bright: colorBright,
      });
      return;
    }
    const partId = section.dataset.partId
      || titleBtn?.dataset?.renamePart
      || section.dataset.chapterId;
    if (!partId) return;
    showPartContextMenu(event.clientX, event.clientY, {
      id: partId,
      title,
      folderId,
      isBox,
      isPinned,
      isBookmarked,
      color,
      color_bright: colorBright,
    });
  };
  outline.querySelectorAll(".chapter-row").forEach((row) => {
    row.addEventListener("contextmenu", (event) => {
      if (event.target.closest?.("[data-scene]")) return;
      const section = row.closest?.(".outline-chapter");
      openFolderContextFromSection(event, section, row);
    });
  });
  outline.querySelectorAll(".part-row").forEach((row) => {
    row.addEventListener("contextmenu", (event) => {
      const section = row.closest?.(".outline-part");
      openFolderContextFromSection(event, section, row);
    });
  });
  outline.querySelectorAll("[data-scene]").forEach((button) => {
    button.addEventListener("click", (event) => {
      if (event.detail > 1) return;
      if (isOutlineInlineRenaming()) return;
      const sceneId = button.dataset.scene;
      if (Number(sceneId) === Number(state.sceneId)) return;
      if (outlineSceneOpenTimer) window.clearTimeout(outlineSceneOpenTimer);
      outlineSceneOpenTimer = window.setTimeout(() => {
        outlineSceneOpenTimer = null;
        if (isOutlineInlineRenaming()) return;
        openScene(sceneId).catch(handleError);
      }, 220);
    });
    button.addEventListener("dblclick", (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (outlineSceneOpenTimer) {
        window.clearTimeout(outlineSceneOpenTimer);
        outlineSceneOpenTimer = null;
      }
      startRenameScene(button.dataset.scene);
    });
  });
  // Folder titles: single click = select only; rename via double-click.
  // Do not stop mousedown propagation — that blocks HTML5 drag from the title.
  outline.querySelectorAll("[data-rename-chapter]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      event.preventDefault();
      outline.querySelectorAll(".chapter-title.is-selected, .part-title.is-selected").forEach((el) => el.classList.remove("is-selected"));
      button.classList.add("is-selected");
    });
    button.addEventListener("dblclick", (event) => {
      event.preventDefault();
      event.stopPropagation();
      beginChapterRename(button).catch(handleError);
    });
  });
  outline.querySelectorAll("[data-rename-part]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      event.preventDefault();
      outline.querySelectorAll(".chapter-title.is-selected, .part-title.is-selected").forEach((el) => el.classList.remove("is-selected"));
      button.classList.add("is-selected");
    });
    button.addEventListener("dblclick", (event) => {
      event.preventDefault();
      event.stopPropagation();
      beginPartRename(button).catch(handleError);
    });
  });
  injectChapterInsertSlots(outline);
  setupChapterDragAndDrop(outline);
  setupPartDragAndDrop(outline);
  setupFolderTreeDragAndDrop(outline);
  setupSceneNestDragAndDrop(outline);
  setupNewChapterDrag();
  setupBinderContextMenu();
  updateChapterInsertBanner();
  updateToryFocusUi();
  renderBookmarkBar();
  markBookmarkedTargets();
}

async function beginChapterRename(titleButton) {
  const chapterId = Number(titleButton.dataset.renameChapter);
  if (!chapterId) return;
  const section = titleButton.closest(".outline-chapter");
  const row = titleButton.closest(".chapter-row");
  if (!row || row.querySelector(".chapter-rename-input")) return;

  const original = state.outline.find((chapter) => chapter.id === chapterId)?.title
    || titleButton.textContent
    || "";
  const input = document.createElement("input");
  input.type = "text";
  input.className = "chapter-rename-input";
  input.value = original;
  input.setAttribute("aria-label", i18n.t('app.챕터_이름_수정'));
  input.maxLength = 200;
  titleButton.replaceWith(input);
  input.focus();
  input.select();

  // While renaming, disable chapter drag so the input is usable.
  if (section) section.draggable = false;

  let finished = false;
  const finish = async (save) => {
    if (finished) return;
    finished = true;
    const nextTitle = input.value.trim();
    if (section) section.draggable = true;
    if (!save || !nextTitle || nextTitle === original) {
      await loadProject();
      return;
    }
    try {
      await api(`/api/chapters/${chapterId}`, {
        method: "PUT",
        body: JSON.stringify({ title: nextTitle }),
      });
      noteFolderUndoAvailable();
      const chapter = state.outline.find((item) => item.id === chapterId);
      if (chapter) chapter.title = nextTitle;
      await loadProject();
      toast(i18n.t('app.챕터_이름을_바꿨어요'));
    } catch (error) {
      await loadProject();
      throw error;
    }
  };

  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      finish(true).catch(handleError);
    } else if (event.key === "Escape") {
      event.preventDefault();
      finish(false).catch(handleError);
    }
  });
  input.addEventListener("blur", () => {
    finish(true).catch(handleError);
  });
  input.addEventListener("mousedown", (event) => event.stopPropagation());
  input.addEventListener("click", (event) => event.stopPropagation());
}

function chapterGroupContainer(section) {
  return section?.closest?.("[data-part-chapters]") || section?.parentElement || null;
}

function chapterGroupPartId(containerOrSection) {
  const el = containerOrSection?.closest?.("[data-part-chapters]")
    || containerOrSection?.closest?.(".outline-part")
    || containerOrSection;
  if (!el || !el.dataset) return null;
  if (Object.prototype.hasOwnProperty.call(el.dataset, "partChapters")) {
    const raw = el.dataset.partChapters;
    if (raw === "" || raw == null) return null;
    const n = Number(raw);
    return Number.isFinite(n) ? n : null;
  }
  if (el.classList?.contains("outline-part") && el.dataset.partId) {
    const n = Number(el.dataset.partId);
    return Number.isFinite(n) ? n : null;
  }
  const raw = el.dataset.partId;
  if (raw === "" || raw == null) return null;
  const n = Number(raw);
  return Number.isFinite(n) ? n : null;
}

/** Drop target for folder (chapter) drag: sibling reorder or move into another top folder. */
function resolveChapterDropTarget(outline, clientX, clientY, eventTarget) {
  if (!outline) return null;
  const x = Number(clientX);
  const y = Number(clientY);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return null;

  let el = eventTarget && eventTarget.nodeType === 1
    ? eventTarget
    : null;
  try {
    const stack = document.elementsFromPoint(x, y) || [];
    // Prefer a node under the pointer that is not the dragging chapter itself.
    const preferred = stack.find((node) => (
      node
      && node.nodeType === 1
      && outline.contains(node)
      && !(chapterDragEl && (node === chapterDragEl || chapterDragEl.contains(node)))
    ));
    if (preferred) el = preferred;
    else if (!el) el = stack.find((node) => node && node.nodeType === 1 && outline.contains(node)) || null;
  } catch (_) {
    if (!el) {
      try { el = document.elementFromPoint(x, y); } catch (__) { el = null; }
    }
  }
  if (!el || !outline.contains(el)) {
    // Fall through to geometry hit-test below.
    el = null;
  }

  // Sibling chapter reorder (never treat the dragged chapter as a drop anchor).
  const chapterEl = el?.closest?.(".outline-chapter");
  if (
    chapterEl
    && outline.contains(chapterEl)
    && chapterEl !== chapterDragEl
    && !chapterEl.classList.contains("is-dragging")
  ) {
    const container = chapterGroupContainer(chapterEl);
    const rect = chapterEl.getBoundingClientRect();
    const before = y < rect.top + rect.height / 2;
    return {
      partId: chapterGroupPartId(container || chapterEl),
      container,
      relativeTo: chapterEl,
      before,
      partEl: chapterEl.closest?.(".outline-part") || null,
    };
  }

  // Any point inside a top-level folder box counts as a drop into that folder.
  for (const partEl of outline.querySelectorAll(":scope > .outline-part")) {
    const rect = partEl.getBoundingClientRect();
    if (x < rect.left || x > rect.right || y < rect.top || y > rect.bottom) continue;
    const container = partEl.querySelector("[data-part-chapters]") || partEl;
    return {
      partId: Number(partEl.dataset.partId) || null,
      container,
      relativeTo: null,
      before: false,
      partEl,
    };
  }

  // Ungrouped zone (or empty-ungrouped hint) → part_id null
  const ungrouped = outline.querySelector(".outline-ungrouped");
  if (ungrouped) {
    const rect = ungrouped.getBoundingClientRect();
    if (x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom) {
      return {
        partId: null,
        container: ungrouped,
        relativeTo: null,
        before: false,
        partEl: null,
      };
    }
  }
  const ungroupedEmpty = outline.querySelector(".outline-ungrouped-empty");
  if (ungroupedEmpty) {
    const rect = ungroupedEmpty.getBoundingClientRect();
    if (x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom) {
      return {
        partId: null,
        container: ungrouped || ungroupedEmpty,
        relativeTo: null,
        before: false,
        partEl: null,
      };
    }
  }

  // Closest()-based fallback when geometry misses (e.g. transformed scroll edge).
  const partEl = el?.closest?.(".outline-part");
  if (partEl && outline.contains(partEl)) {
    const container = partEl.querySelector("[data-part-chapters]") || partEl;
    return {
      partId: Number(partEl.dataset.partId) || null,
      container,
      relativeTo: null,
      before: false,
      partEl,
    };
  }
  const ungroupedClosest = el?.closest?.(".outline-ungrouped, .outline-ungrouped-empty");
  if (ungroupedClosest && outline.contains(ungroupedClosest)) {
    const container = ungroupedClosest.classList?.contains("outline-ungrouped")
      ? ungroupedClosest
      : (ungrouped || ungroupedClosest);
    return {
      partId: null,
      container,
      relativeTo: null,
      before: false,
      partEl: null,
    };
  }
  return null;
}

let chapterDragEl = null;

function clearChapterDropMarkers(outline = $("outline")) {
  outline?.querySelectorAll(".outline-chapter").forEach((section) => {
    section.classList.remove("drag-over-before", "drag-over-after", "is-dragging");
  });
  outline?.querySelectorAll(".outline-part.is-folder-drop, .outline-ungrouped.is-folder-drop").forEach((el) => {
    el.classList.remove("is-folder-drop");
  });
}

function setupChapterDragAndDrop(outline) {
  if (!outline) return;
  // Bind once with delegation — supports cross-folder moves after re-render.
  if (outline.dataset.chapterDragBound === "1") return;
  outline.dataset.chapterDragBound = "1";

  outline.addEventListener("dragstart", (event) => {
    // folders-mode uses setupFolderTreeDragAndDrop + reparent API
    if (shouldUseFoldersOutline()) return;
    if (event.target.closest?.(".scene-tree-item, .chapter-children")) return;
    if (chapterInsertDragActive) return;

    const section = event.target.closest?.(".outline-chapter");
    if (!section || !outline.contains(section)) return;
    // Allow drag from title, ⋮⋮ handle, or row — not from +/twistie/inputs.
    if (event.target.closest?.("button.chapter-add-scene, button[data-chapter], button.chapter-twistie, .chapter-insert-slot, input, textarea")) {
      event.preventDefault();
      return;
    }
    // Nested-under-scene chapters are not reparented via this path.
    if (section.dataset.transparent === "true" || section.getAttribute("draggable") === "false") {
      event.preventDefault();
      return;
    }

    event.stopPropagation();
    chapterDragEl = section;
    section.classList.add("is-dragging");
    event.dataTransfer.effectAllowed = "move";
    try {
      event.dataTransfer.setData("text/plain", `chapter:${section.dataset.chapterId || ""}`);
      event.dataTransfer.setData(
        "application/x-supertory-chapter",
        String(section.dataset.chapterId || ""),
      );
    } catch (_) { /* ignore */ }
    try {
      event.dataTransfer.setDragImage(section, 20, 12);
    } catch (_) { /* ignore */ }
  }, true);

  outline.addEventListener("dragend", () => {
    chapterDragEl = null;
    clearChapterDropMarkers(outline);
  }, true);

  outline.addEventListener("dragover", (event) => {
    if (shouldUseFoldersOutline()) return;
    if (!chapterDragEl || chapterInsertDragActive) return;
    if (typeof sceneNestDragId !== "undefined" && sceneNestDragId) return;
    const target = resolveChapterDropTarget(outline, event.clientX, event.clientY, event.target);
    if (!target) return;
    if (target.relativeTo === chapterDragEl) return;

    event.preventDefault();
    event.stopPropagation();
    try { event.dataTransfer.dropEffect = "move"; } catch (_) { /* ignore */ }

    clearChapterDropMarkers(outline);
    chapterDragEl.classList.add("is-dragging");

    const fromPartId = chapterGroupPartId(chapterGroupContainer(chapterDragEl) || chapterDragEl);
    const toPartId = target.partId;
    const sameGroup = fromPartId === toPartId || (fromPartId == null && toPartId == null);

    if (sameGroup && target.relativeTo) {
      target.relativeTo.classList.toggle("drag-over-before", target.before);
      target.relativeTo.classList.toggle("drag-over-after", !target.before);
      return;
    }

    // Cross-folder (or same-folder empty area): highlight the whole destination box.
    const partBox = target.partEl
      || (toPartId != null
        ? outline.querySelector(`.outline-part[data-part-id="${toPartId}"]`)
        : null);
    const ungroupedBox = toPartId == null
      ? outline.querySelector(".outline-ungrouped, .outline-ungrouped-empty")
      : null;
    if (partBox) partBox.classList.add("is-folder-drop");
    if (ungroupedBox) ungroupedBox.classList.add("is-folder-drop");
    if (sameGroup && target.relativeTo) {
      target.relativeTo.classList.toggle("drag-over-before", target.before);
      target.relativeTo.classList.toggle("drag-over-after", !target.before);
    } else if (!sameGroup && target.relativeTo) {
      target.relativeTo.classList.toggle("drag-over-before", target.before);
      target.relativeTo.classList.toggle("drag-over-after", !target.before);
    }
  }, true);

  outline.addEventListener("drop", (event) => {
    if (shouldUseFoldersOutline()) return;
    if (!chapterDragEl || chapterInsertDragActive) return;
    if (typeof sceneNestDragId !== "undefined" && sceneNestDragId) return;
    const dragged = chapterDragEl;
    const target = resolveChapterDropTarget(outline, event.clientX, event.clientY, event.target);
    if (!target || target.relativeTo === dragged) {
      clearChapterDropMarkers(outline);
      chapterDragEl = null;
      return;
    }
    event.preventDefault();
    event.stopPropagation();

    const chapterId = Number(dragged.dataset.chapterId);
    if (!chapterId || !state.projectId) {
      chapterDragEl = null;
      clearChapterDropMarkers(outline);
      return;
    }

    const fromPartId = chapterGroupPartId(chapterGroupContainer(dragged) || dragged);
    const toPartId = target.partId;
    const sameGroup = fromPartId === toPartId || (fromPartId == null && toPartId == null);

    const run = async () => {
      try {
        if (!sameGroup) {
          await api(`/api/chapters/${chapterId}/move`, {
            method: "POST",
            body: JSON.stringify({ part_id: toPartId }),
          });
        }

        // After cross-folder move, reload then place next to drop sibling if any
        if (!sameGroup) {
          await loadProject();
          if (target.relativeTo) {
            const outlineNow = $("outline");
            const movedEl = outlineNow?.querySelector(`.outline-chapter[data-chapter-id="${chapterId}"]`);
            const relId = Number(target.relativeTo.dataset.chapterId);
            const relEl = outlineNow?.querySelector(`.outline-chapter[data-chapter-id="${relId}"]`);
            const container = movedEl ? chapterGroupContainer(movedEl) : null;
            if (movedEl && relEl && container && container.contains(relEl) && container.contains(movedEl)) {
              const siblings = [...container.querySelectorAll(":scope > .outline-chapter")];
              const without = siblings.filter((n) => n !== movedEl);
              let insertAt = without.indexOf(relEl);
              if (insertAt < 0) insertAt = without.length;
              if (!target.before) insertAt += 1;
              without.splice(insertAt, 0, movedEl);
              without.forEach((node) => container.appendChild(node));
              await reorderChapters(
                without.map((n) => Number(n.dataset.chapterId)),
                toPartId,
              );
              toast(i18n.t('app.폴더를_옮기고_순서를_맞췄어요'));
              return;
            }
          }
          toast(i18n.t('app.폴더를_옮겼어요'));
          return;
        }

        // Same group: reorder next to sibling
        if (target.relativeTo && target.container) {
          const chapters = [...target.container.querySelectorAll(":scope > .outline-chapter")];
          const fromIndex = chapters.indexOf(dragged);
          let toIndex = chapters.indexOf(target.relativeTo);
          if (fromIndex >= 0 && toIndex >= 0) {
            chapters.splice(fromIndex, 1);
            toIndex = chapters.indexOf(target.relativeTo);
            if (toIndex < 0) toIndex = chapters.length;
            const insertAt = target.before ? toIndex : toIndex + 1;
            chapters.splice(insertAt, 0, dragged);
            target.container.querySelectorAll(":scope > .chapter-insert-slot").forEach((s) => s.remove());
            chapters.forEach((node) => target.container.appendChild(node));
            injectChapterInsertSlots($("outline"));
            await reorderChapters(
              chapters.map((n) => Number(n.dataset.chapterId)),
              toPartId,
            );
            return;
          }
        }

        // Same group, empty area of the folder box → move to end
        if (target.container) {
          const chapters = [...target.container.querySelectorAll(":scope > .outline-chapter")];
          const fromIndex = chapters.indexOf(dragged);
          if (fromIndex >= 0 && fromIndex !== chapters.length - 1) {
            chapters.splice(fromIndex, 1);
            chapters.push(dragged);
            target.container.querySelectorAll(":scope > .chapter-insert-slot").forEach((s) => s.remove());
            chapters.forEach((node) => target.container.appendChild(node));
            injectChapterInsertSlots($("outline"));
            await reorderChapters(
              chapters.map((n) => Number(n.dataset.chapterId)),
              toPartId,
            );
            return;
          }
        }
      } catch (error) {
        handleError(error);
        loadProject().catch(handleError);
      } finally {
        chapterDragEl = null;
        clearChapterDropMarkers($("outline"));
      }
    };

    run();
  }, true);
}

function setupPartDragAndDrop(outline) {
  if (!outline) return;
  let dragged = null;
  const clearDropMarkers = () => {
    outline.querySelectorAll(".outline-part").forEach((section) => {
      section.classList.remove("drag-over-before", "drag-over-after", "is-dragging");
    });
  };

  // Bind once with delegation so chapter→folder drops are not blocked by part.draggable.
  if (outline.dataset.partDragBound === "1") return;
  outline.dataset.partDragBound = "1";

  outline.addEventListener("dragstart", (event) => {
    if (shouldUseFoldersOutline()) return;
    if (chapterDragEl || chapterInsertDragActive) return;
    if (typeof sceneNestDragId !== "undefined" && sceneNestDragId) return;
    if (event.target.closest?.(".scene-tree-item, .chapter-children, .outline-chapter")) return;
    // Unified with chapter: ⋮⋮ handle, title, or row (not twistie / + / rename input).
    if (event.target.closest?.(".part-twistie, .part-add-chapter, input, textarea")) {
      event.preventDefault();
      return;
    }
    const dragSource = event.target.closest?.(
      ".part-drag-handle, .part-title[data-rename-part], .part-row",
    );
    if (!dragSource || !outline.contains(dragSource)) return;
    const section = dragSource.closest?.(".outline-part");
    if (!section || !outline.contains(section)) return;
    event.stopPropagation();
    dragged = section;
    section.classList.add("is-dragging");
    event.dataTransfer.effectAllowed = "move";
    try {
      event.dataTransfer.setData("text/plain", `part:${section.dataset.partId || ""}`);
      event.dataTransfer.setData("application/x-supertory-part", String(section.dataset.partId || ""));
    } catch (_) { /* ignore */ }
    try {
      event.dataTransfer.setDragImage(section, 20, 12);
    } catch (_) { /* ignore */ }
  }, true);

  outline.addEventListener("dragend", (event) => {
    if (!dragged) return;
    if (
      event.target.closest?.(".part-drag-handle, .part-title, .part-row, .outline-part")
      || event.target === dragged
    ) {
      dragged = null;
      clearDropMarkers();
    }
  }, true);

  outline.addEventListener("dragover", (event) => {
    if (shouldUseFoldersOutline()) return;
    if (!dragged || !dragged.classList?.contains("outline-part")) return;
    if (chapterDragEl) return;
    const section = event.target.closest?.(".outline-part");
    if (!section || !outline.contains(section) || section === dragged) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    const rect = section.getBoundingClientRect();
    const before = event.clientY < rect.top + rect.height / 2;
    section.classList.toggle("drag-over-before", before);
    section.classList.toggle("drag-over-after", !before);
    outline.querySelectorAll(".outline-part").forEach((other) => {
      if (other !== section) other.classList.remove("drag-over-before", "drag-over-after");
    });
  }, true);

  outline.addEventListener("drop", (event) => {
    if (shouldUseFoldersOutline()) return;
    if (!dragged || !dragged.classList?.contains("outline-part")) return;
    if (chapterDragEl) return;
    const section = event.target.closest?.(".outline-part");
    if (!section || !outline.contains(section)) return;
    event.preventDefault();
    event.stopPropagation();
    if (dragged === section || !state.projectId) {
      clearDropMarkers();
      dragged = null;
      return;
    }
    const rect = section.getBoundingClientRect();
    const before = event.clientY < rect.top + rect.height / 2;
    const parts = [...outline.querySelectorAll(":scope > .outline-part")];
    const fromIndex = parts.indexOf(dragged);
    let toIndex = parts.indexOf(section);
    if (fromIndex < 0 || toIndex < 0) {
      clearDropMarkers();
      dragged = null;
      return;
    }
    parts.splice(fromIndex, 1);
    toIndex = parts.indexOf(section);
    if (toIndex < 0) {
      clearDropMarkers();
      dragged = null;
      return;
    }
    const insertAt = before ? toIndex : toIndex + 1;
    parts.splice(insertAt, 0, dragged);
    const ungrouped = outline.querySelector(".outline-ungrouped, .outline-ungrouped-empty");
    parts.forEach((node) => outline.insertBefore(node, ungrouped || null));
    clearDropMarkers();
    const partIds = parts.map((node) => Number(node.dataset.partId));
    const finished = dragged;
    dragged = null;
    reorderParts(partIds).catch((error) => {
      handleError(error);
      loadProject().catch(handleError);
    });
    finished?.classList.remove("is-dragging");
  }, true);
}

/** @type {HTMLElement|null} */
let folderTreeDragEl = null;

function clearFolderTreeDropMarkers(outline = $("outline")) {
  outline?.querySelectorAll(
    ".outline-part, .outline-chapter",
  ).forEach((section) => {
    section.classList.remove(
      "drag-over-before",
      "drag-over-after",
      "is-dragging",
      "is-folder-drop",
    );
  });
}

function folderSectionParentFolderId(section, outline) {
  if (!section) return null;
  let cur = section.parentElement;
  while (cur && cur !== outline) {
    if (cur.dataset?.folderId != null && cur.dataset.folderId !== "") {
      const n = Number(cur.dataset.folderId);
      if (Number.isFinite(n) && n > 0) return n;
    }
    cur = cur.parentElement;
  }
  return null;
}

function collectDomFolderSubtreeIds(section) {
  const ids = new Set();
  if (!section) return ids;
  const root = Number(section.dataset?.folderId);
  if (Number.isFinite(root) && root > 0) ids.add(root);
  section.querySelectorAll?.("[data-folder-id]").forEach((el) => {
    const n = Number(el.dataset.folderId);
    if (Number.isFinite(n) && n > 0) ids.add(n);
  });
  return ids;
}

/**
 * Scrivener-style folder drop zones (same ratios as scene move; scene code untouched).
 * before <28% | inside 28–72% | after >72% of the target folder header/row height.
 */
function resolveFolderMoveDrop(outline, clientX, clientY, eventTarget) {
  if (!folderTreeDragEl || !outline) return null;
  const movingId = Number(folderTreeDragEl.dataset.folderId);
  if (!Number.isFinite(movingId) || movingId <= 0) return null;
  const subtree = collectDomFolderSubtreeIds(folderTreeDragEl);

  const x = Number(clientX);
  const y = Number(clientY);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return null;

  let el = eventTarget && eventTarget.nodeType === 1 ? eventTarget : null;
  try {
    const stack = document.elementsFromPoint(x, y) || [];
    const preferred = stack.find((node) => (
      node
      && node.nodeType === 1
      && outline.contains(node)
      && !(folderTreeDragEl && (node === folderTreeDragEl || folderTreeDragEl.contains(node)))
    ));
    if (preferred) el = preferred;
    else if (!el) el = stack.find((node) => node && outline.contains(node)) || null;
  } catch (_) { /* ignore */ }

  const section = el?.closest?.(
    ".outline-part[data-folder-id], .outline-chapter[data-folder-id]",
  );
  if (!section || !outline.contains(section)) return null;
  if (section === folderTreeDragEl) return null;
  if (section.dataset.transparent === "true") return null;

  const targetId = Number(section.dataset.folderId);
  if (!Number.isFinite(targetId) || targetId <= 0) return null;
  if (subtree.has(targetId)) return null;

  // Prefer the title row height for zone ratios (closer to Scrivener item hit).
  const row = section.querySelector(":scope > .part-row, :scope > .chapter-row") || section;
  const rect = row.getBoundingClientRect();
  const ratio = (y - rect.top) / Math.max(rect.height, 1);

  if (ratio < 0.28) {
    return {
      mode: "before",
      position: "before",
      folderId: movingId,
      targetId,
      new_parent_id: folderSectionParentFolderId(section, outline),
      target_id: targetId,
      el: section,
    };
  }
  if (ratio > 0.72) {
    return {
      mode: "after",
      position: "after",
      folderId: movingId,
      targetId,
      new_parent_id: folderSectionParentFolderId(section, outline),
      target_id: targetId,
      el: section,
    };
  }
  return {
    mode: "inside",
    position: "inside",
    folderId: movingId,
    targetId,
    new_parent_id: targetId,
    target_id: targetId,
    el: section,
  };
}

function applyFolderMoveDropHint(outline, drop) {
  clearFolderTreeDropMarkers(outline);
  folderTreeDragEl?.classList.add("is-dragging");
  if (!drop?.el) return;
  if (drop.mode === "before") {
    drop.el.classList.add("drag-over-before");
  } else if (drop.mode === "after") {
    drop.el.classList.add("drag-over-after");
  } else if (drop.mode === "inside") {
    drop.el.classList.add("is-folder-drop");
  }
}

/**
 * Unlimited-depth folder DnD → POST /api/folders/{id}/reparent.
 * Active only when shouldUseFoldersOutline(); legacy chapter/part DnD stays for fallback.
 */
function setupFolderTreeDragAndDrop(outline) {
  if (!outline) return;
  if (outline.dataset.folderTreeDragBound === "1") return;
  outline.dataset.folderTreeDragBound = "1";

  outline.addEventListener("dragstart", (event) => {
    if (!shouldUseFoldersOutline()) return;
    if (chapterInsertDragActive) return;
    if (typeof sceneNestDragId !== "undefined" && sceneNestDragId) return;
    // Scene rows only — do NOT blanket-block .chapter-children (nested folders live there).
    const sceneItem = event.target.closest?.(".scene-tree-item");
    const folderHeader = event.target.closest?.(
      ":is(.outline-part, .outline-chapter)[data-folder-id] > .part-row, "
      + ":is(.outline-part, .outline-chapter)[data-folder-id] > .chapter-row, "
      + ".part-drag-handle, .chapter-drag-handle, "
      + ".part-title[data-rename-part], .chapter-title[data-rename-chapter]",
    );
    if (sceneItem && !folderHeader) return;
    if (event.target.closest?.(
      "button.chapter-add-scene, button[data-chapter], button.chapter-twistie, "
      + ".part-twistie, .part-add-chapter, .chapter-insert-slot, input, textarea",
    )) {
      event.preventDefault();
      return;
    }

    const section = event.target.closest?.(
      ".outline-part[data-folder-id], .outline-chapter[data-folder-id]",
    );
    if (!section || !outline.contains(section)) return;
    if (section.dataset.transparent === "true") {
      event.preventDefault();
      return;
    }
    const folderId = Number(section.dataset.folderId);
    if (!Number.isFinite(folderId) || folderId <= 0) return;

    event.stopPropagation();
    folderTreeDragEl = section;
    section.classList.add("is-dragging");
    event.dataTransfer.effectAllowed = "move";
    try {
      event.dataTransfer.setData("text/plain", `folder:${folderId}`);
      event.dataTransfer.setData("application/x-supertory-folder", String(folderId));
    } catch (_) { /* ignore */ }
    try {
      event.dataTransfer.setDragImage(section, 20, 12);
    } catch (_) { /* ignore */ }
  }, true);

  outline.addEventListener("dragend", () => {
    if (!folderTreeDragEl) return;
    folderTreeDragEl = null;
    clearFolderTreeDropMarkers(outline);
  }, true);

  outline.addEventListener("dragover", (event) => {
    if (!shouldUseFoldersOutline() || !folderTreeDragEl) return;
    if (typeof sceneNestDragId !== "undefined" && sceneNestDragId) return;
    const drop = resolveFolderMoveDrop(
      outline, event.clientX, event.clientY, event.target,
    );
    if (!drop) return;
    event.preventDefault();
    event.stopPropagation();
    try { event.dataTransfer.dropEffect = "move"; } catch (_) { /* ignore */ }
    applyFolderMoveDropHint(outline, drop);
  }, true);

  outline.addEventListener("dragleave", (event) => {
    if (!folderTreeDragEl) return;
    const related = event.relatedTarget;
    if (related && outline.contains(related)) return;
    clearFolderTreeDropMarkers(outline);
    folderTreeDragEl?.classList.add("is-dragging");
  }, true);

  outline.addEventListener("drop", (event) => {
    if (!shouldUseFoldersOutline() || !folderTreeDragEl) return;
    if (typeof sceneNestDragId !== "undefined" && sceneNestDragId) return;
    const drop = resolveFolderMoveDrop(
      outline, event.clientX, event.clientY, event.target,
    );
    event.preventDefault();
    event.stopPropagation();
    clearFolderTreeDropMarkers(outline);
    const moving = folderTreeDragEl;
    folderTreeDragEl = null;
    if (!drop || !moving || !state.projectId) return;

    const folderId = Number(drop.folderId);
    if (!folderId) return;

    const body = {
      new_parent_id: drop.new_parent_id,
      position: drop.position,
      target_id: drop.target_id,
    };

    (async () => {
      try {
        const result = await api(`/api/folders/${folderId}/reparent`, {
          method: "POST",
          body: JSON.stringify(body),
        });
        if (result && result.folder_sync_complete === false) {
          state.forceFoldersOutline = true;
          writeForceFoldersOutline(state.projectId, true);
        }
        if (result && result.moved) noteFolderUndoAvailable();
        await loadProject();
        if (drop.mode === "inside") {
          toast(i18n.t('app.폴더를_안으로_넣었어요'));
        } else {
          toast(i18n.t('app.폴더_위치를_바꿨어요'));
        }
      } catch (error) {
        handleError(error);
        loadProject().catch(handleError);
      }
    })();
  }, true);
}

async function reorderChapters(chapterIds, partId = null) {
  if (!state.projectId || !chapterIds.length) return;
  await api(`/api/projects/${state.projectId}/chapters/reorder`, {
    method: "PUT",
    body: JSON.stringify({ chapter_ids: chapterIds, part_id: partId }),
  });
  await loadProject();
  toast(i18n.t('app.챕터_순서를_바꿨어요'));
}

async function reorderParts(partIds) {
  if (!state.projectId || !partIds.length) return;
  await api(`/api/projects/${state.projectId}/parts/reorder`, {
    method: "PUT",
    body: JSON.stringify({ part_ids: partIds }),
  });
  await loadProject();
  toast(i18n.t('app.권_부_순서를_바꿨어요'));
}

function renderCharacters() {
  const list = $("characterList");
  if (!list) return;
  list.innerHTML = state.characters.length ? state.characters.map((character) => {
    const firstLine = String(character.short_description || "").trim()
      || String(character.profile_md || "").split(/\n/).map((line) => line.trim()).find(Boolean)
      || roleLabel[characterStoryRole(character.role)]
      || "";
    const analysisMark = character.has_tori_analysis
      ? i18n.t('app.span_class_character_li')
      : "";
    return `
    <button class="character-link ${state.characterId === character.id ? "active" : ""}" data-character="${character.id}" title="${escapeHtml(character.name)}">
      <span class="character-name">${escapeHtml(character.name)}${analysisMark}</span>
      <span class="character-role">${escapeHtml(firstLine)}</span>
    </button>`;
  }).join("") : i18n.t('app.p_class_hint_아직_인물이_없어요');
  list.querySelectorAll("[data-character]").forEach((button) => button.addEventListener("click", () => openCharacter(button.dataset.character)));
  renderSettingsCodex();
  if (toryChatHub === "characters" || toryChatHub === "character-room") {
    try { renderToryChatCharacterPicker(); } catch (_) { /* ignore */ }
    if (toryChatHub === "character-room") {
      try { syncToryChatRoomChrome(); } catch (_) { /* ignore */ }
    }
  }
}

function showWelcome() {
  if (typeof isGlumpSprintActive === "function" && isGlumpSprintActive() && !confirmLeaveGlumpSprint()) {
    return;
  }
  void flushPendingCodexSaves();
  void closeSplitView();
  state.sceneId = null;
  state.characterId = null;
  state.illustrations = [];
  state.referenceLinks = [];
  if (!state.ideaBoardOpen) {
    $("ideaBoard")?.classList.add("hidden");
  }
  if (!state.keywordBoardOpen) {
    $("keywordBoard")?.classList.add("hidden");
  }
  hideCharacterBoard();
  hideRelationCanvas();
  hideItemViews();
  hideSettingsCollectionBoard();
  hideGitsiWorkspace();
  hideSettingsSearchBoard();
  $("welcome").classList.remove("hidden");
  $("sceneWorkspace").classList.add("hidden");
  $("characterEditor").classList.add("hidden");
  hideSynopsisMain();
  $("newChapterButton").disabled = !state.projectId;
  if ($("renumberChaptersButton")) $("renumberChaptersButton").disabled = !state.projectId;
  $("newCharacterButton").disabled = !state.projectId;
  if ($("newItemButton")) $("newItemButton").disabled = !state.projectId;
  $("newIdeaButton").disabled = !state.projectId;
  if (!state.projectId) {
    state.folderUndoHint = 0;
    state.folderRedoHint = 0;
  }
  if (typeof syncFolderHistoryButtons === "function") syncFolderHistoryButtons();
  else if (typeof syncFolderUndoButton === "function") syncFolderUndoButton();
  syncPurposePickerFromState();
  syncGenrePickerFromState();
  syncToryPriorityInput();
  closeViewModeMenu();
  closeSceneToolsDrawer();
  updateAuthorNotesBadge();
  updateReferenceMaterialsBadge();
  renderEpisodeChrome();
  updateSplitChrome();
  if (state.ideaBoardOpen) {
    $("welcome").classList.add("hidden");
    $("ideaBoard")?.classList.remove("hidden");
    $("keywordBoard")?.classList.add("hidden");
  } else if (state.keywordBoardOpen) {
    $("welcome").classList.add("hidden");
    $("keywordBoard")?.classList.remove("hidden");
    $("ideaBoard")?.classList.add("hidden");
  }
  updateWelcomeGuideUi();
  // Persist "project open, no scene" so relaunch can return to welcome for this work.
  if (state.projectId) saveLastWorkspace({ sceneId: null });
}

/* —— Welcome screen: animated Tory + +button guide —— */
const WELCOME_GUIDE_DISMISS_KEY = "supertory.welcomePlusGuideDismissed";
/**
 * Session-only dismiss for ad popups (X).
 * "다시 보지 않기" stores kind+version in localStorage until feed version changes.
 */
const WELCOME_AD_POPUP_IDS = ["event", "notice"];
const WELCOME_AD_POPUP_SESSION_PREFIX = "supertory.welcomeAdPopup.session.";
/** Permanent (per version): supertory.welcomeAdPopup.dismissed.{kind}.{version} = "1" */
const WELCOME_AD_POPUP_DISMISSED_PREFIX = "supertory.welcomeAdPopup.dismissed.";
/** Remote feed (no rebuild). Local fallback: same-origin /notice-feed.json */
const NOTICE_FEED_REMOTE_URL =
  "https://raw.githubusercontent.com/cultnoni/supertory/main/web/notice-feed.json";
const NOTICE_FEED_LOCAL_URL = "/notice-feed.json";
const WELCOME_SPEECH_LINES = [
  i18n.t('app.반가워요_작가님'),
  i18n.t('app.먼저_왼쪽_위_를_눌러봐요'),
  i18n.t('app.새_글_쓰기부터_시작하면_돼요'),
  i18n.t('app.써_둔_글이_있으면_가져오기도_가능'),
  i18n.t('app.준비되면_같이_써봐요'),
  i18n.t('app.토리와_함께'),
];
let welcomeSpeechTimer = null;
let welcomeSpeechIndex = 0;
let welcomeGuideDismissedSession = false;
/** @type {Record<string, boolean>} */
const welcomeAdPopupSessionDismissed = {};
/** @type {Record<string, object|null>|null} null = not loaded / failed */
let welcomeAdFeed = null;
let welcomeAdFeedLoaded = false;
let welcomeAdFeedLoading = null;

function isWelcomeScreenVisible() {
  const el = $("welcome");
  return Boolean(el && !el.classList.contains("hidden"));
}

function localDateKey() {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function normalizeWelcomeAdItem(raw) {
  if (!raw || typeof raw !== "object") return null;
  const version = String(raw.version || "v1").trim() || "v1";
  const title_ko = String(raw.title_ko || raw.title || "").trim();
  const title_en = String(raw.title_en || "").trim();
  const body_ko = String(raw.body_ko || raw.body || "").trim();
  const body_en = String(raw.body_en || "").trim();
  if (!title_ko && !title_en && !body_ko && !body_en) return null;
  return {
    badge_ko: String(raw.badge_ko || raw.badge || "").trim(),
    badge_en: String(raw.badge_en || "").trim(),
    title_ko,
    title_en,
    body_ko,
    body_en,
    enabled: raw.enabled !== false && raw.enabled !== 0,
    version,
    startDate: String(raw.startDate || "").trim(),
    endDate: String(raw.endDate || "").trim(),
  };
}

function parseWelcomeAdFeed(data) {
  if (!data || typeof data !== "object") return null;
  /** @type {Record<string, object|null>} */
  const out = {};
  for (const kind of WELCOME_AD_POPUP_IDS) {
    out[kind] = normalizeWelcomeAdItem(data[kind]);
  }
  if (!out.event && !out.notice) return null;
  return out;
}

async function fetchWelcomeAdFeedJson(url, timeoutMs = 2500) {
  const sep = url.includes("?") ? "&" : "?";
  const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
  const timer = controller && timeoutMs
    ? window.setTimeout(() => controller.abort(), timeoutMs)
    : 0;
  try {
    const response = await fetch(`${url}${sep}t=${Date.now()}`, {
      method: "GET",
      cache: "no-store",
      credentials: "omit",
      signal: controller ? controller.signal : undefined,
    });
    if (!response.ok) throw new Error(`notice-feed HTTP ${response.status}`);
    const data = await response.json();
    const parsed = parseWelcomeAdFeed(data);
    if (!parsed) throw new Error("notice-feed empty or invalid");
    return parsed;
  } finally {
    if (timer) window.clearTimeout(timer);
  }
}

/**
 * Load notice/event feed: remote GitHub raw → local /notice-feed.json → null (hide all).
 * @returns {Promise<Record<string, object|null>|null>}
 */
async function loadWelcomeAdFeed() {
  if (welcomeAdFeedLoaded) return welcomeAdFeed;
  if (welcomeAdFeedLoading) return welcomeAdFeedLoading;
  welcomeAdFeedLoading = (async () => {
    let feed = null;
    try {
      if (typeof navigator !== "undefined" && navigator.onLine === false) {
        throw new Error("offline");
      }
      feed = await fetchWelcomeAdFeedJson(NOTICE_FEED_REMOTE_URL, 2500);
    } catch (remoteError) {
      try {
        feed = await fetchWelcomeAdFeedJson(NOTICE_FEED_LOCAL_URL, 2500);
      } catch (localError) {
        console.warn(
          "welcome ad feed unavailable",
          remoteError?.message || remoteError,
          localError?.message || localError,
        );
        feed = null;
      }
    }
    welcomeAdFeed = feed;
    welcomeAdFeedLoaded = true;
    welcomeAdFeedLoading = null;
    applyWelcomeAdFeedToDom();
    refreshWelcomeAdPopupsVisibility();
    return welcomeAdFeed;
  })();
  return welcomeAdFeedLoading;
}

function getWelcomeAdItem(kind) {
  if (!welcomeAdFeed || typeof welcomeAdFeed !== "object") return null;
  return welcomeAdFeed[kind] || null;
}

function welcomeAdItemVersion(kind) {
  const item = getWelcomeAdItem(kind);
  const v = String(item?.version || "v1").trim();
  return v || "v1";
}

/** Inclusive local calendar window: startDate ≤ today ≤ endDate (missing bounds open). */
function isWelcomeAdItemInDateWindow(item, today = localDateKey()) {
  if (!item) return false;
  const start = String(item.startDate || "").trim();
  const end = String(item.endDate || "").trim();
  if (start && /^\d{4}-\d{2}-\d{2}$/.test(start) && today < start) return false;
  if (end && /^\d{4}-\d{2}-\d{2}$/.test(end) && today > end) return false;
  return true;
}

function isWelcomeAdItemActive(kind) {
  const item = getWelcomeAdItem(kind);
  if (!item) return false;
  if (!item.enabled) return false;
  if (!isWelcomeAdItemInDateWindow(item)) return false;
  if (!item.title_ko && !item.title_en && !item.body_ko && !item.body_en) return false;
  return true;
}

function applyWelcomeAdFeedToDom() {
  const lang = i18n.getLang();
  for (const kind of WELCOME_AD_POPUP_IDS) {
    const item = getWelcomeAdItem(kind);
    const badgeEl = document.querySelector(`[data-ad-popup-badge="${kind}"]`);
    const titleEl = document.querySelector(`[data-ad-popup-title="${kind}"]`);
    const bodyEl = document.querySelector(`[data-ad-popup-body="${kind}"]`);
    if (badgeEl) badgeEl.textContent = item?.[`badge_${lang}`] || item?.badge_ko || "";
    if (titleEl) titleEl.textContent = item?.[`title_${lang}`] || item?.title_ko || "";
    if (bodyEl) bodyEl.textContent = item?.[`body_${lang}`] || item?.body_ko || "";
  }
}

/**
 * @param {"session"|"dismissed"} scope
 * session → sessionStorage (X close)
 * dismissed → localStorage permanent until notice-feed version changes
 */
function welcomeAdPopupStorageKey(kind, scope) {
  const version = welcomeAdItemVersion(kind);
  if (scope === "dismissed") {
    return `${WELCOME_AD_POPUP_DISMISSED_PREFIX}${kind}.${version}`;
  }
  return `${WELCOME_AD_POPUP_SESSION_PREFIX}${kind}.${version}`;
}

function isWelcomeAdPopupDismissed(kind) {
  if (welcomeAdPopupSessionDismissed[kind]) return true;
  try {
    if (sessionStorage.getItem(welcomeAdPopupStorageKey(kind, "session")) === "1") return true;
    // Current kind+version permanently dismissed ("다시 보지 않기")
    if (localStorage.getItem(welcomeAdPopupStorageKey(kind, "dismissed")) === "1") return true;
  } catch (_) {
    /* ignore */
  }
  return false;
}

function dismissWelcomeAdPopup(kind, { permanent = false } = {}) {
  if (!WELCOME_AD_POPUP_IDS.includes(kind)) return;
  welcomeAdPopupSessionDismissed[kind] = true;
  try {
    sessionStorage.setItem(welcomeAdPopupStorageKey(kind, "session"), "1");
    if (permanent) {
      localStorage.setItem(welcomeAdPopupStorageKey(kind, "dismissed"), "1");
    }
  } catch (_) {
    /* ignore */
  }
  const el = document.querySelector(`[data-ad-popup="${kind}"]`);
  if (el) {
    el.hidden = true;
    el.setAttribute("aria-hidden", "true");
  }
  refreshWelcomeAdPopupsVisibility();
}

function refreshWelcomeAdPopupsVisibility() {
  const host = $("welcomeAdPopups");
  if (!host) return;
  const onWelcome = isWelcomeScreenVisible();
  let anyVisible = false;
  for (const kind of WELCOME_AD_POPUP_IDS) {
    const el = document.querySelector(`[data-ad-popup="${kind}"]`);
    if (!el) continue;
    const show = onWelcome
      && welcomeAdFeedLoaded
      && isWelcomeAdItemActive(kind)
      && !isWelcomeAdPopupDismissed(kind);
    el.hidden = !show;
    el.setAttribute("aria-hidden", show ? "false" : "true");
    if (show) anyVisible = true;
  }
  host.classList.toggle("hidden", !anyVisible);
  host.setAttribute("aria-hidden", anyVisible ? "false" : "true");
}

function setupWelcomeAdPopups() {
  const host = $("welcomeAdPopups");
  if (!host || host.dataset.bound === "1") return;
  host.dataset.bound = "1";
  host.addEventListener("click", (e) => {
    const closeBtn = e.target.closest?.("[data-ad-popup-close]");
    if (closeBtn) {
      e.preventDefault();
      dismissWelcomeAdPopup(closeBtn.getAttribute("data-ad-popup-close") || "");
      return;
    }
    const permanentBtn = e.target.closest?.("[data-ad-popup-dismiss-permanent]");
    if (permanentBtn) {
      e.preventDefault();
      dismissWelcomeAdPopup(
        permanentBtn.getAttribute("data-ad-popup-dismiss-permanent") || "",
        { permanent: true },
      );
    }
  });
  loadWelcomeAdFeed().catch(() => {
    welcomeAdFeed = null;
    welcomeAdFeedLoaded = true;
    welcomeAdFeedLoading = null;
    refreshWelcomeAdPopupsVisibility();
  });
}

function isWelcomeGuideDismissed() {
  if (welcomeGuideDismissedSession) return true;
  try {
    return sessionStorage.getItem(WELCOME_GUIDE_DISMISS_KEY) === "1";
  } catch (_) {
    return false;
  }
}

function setWelcomeGuideDismissed(dismissed) {
  welcomeGuideDismissedSession = Boolean(dismissed);
  try {
    sessionStorage.setItem(WELCOME_GUIDE_DISMISS_KEY, dismissed ? "1" : "0");
  } catch (_) {
    /* ignore */
  }
}

function positionWelcomePlusGuide() {
  /* 시작 화살표·안내 박스 UI 제거됨 */
  $("welcomePlusGuide")?.classList.add("hidden");
}

function updateWelcomeGuideUi() {
  refreshWelcomeAdPopupsVisibility();
  $("welcomePlusGuide")?.classList.add("hidden");
  if (!isWelcomeScreenVisible()) {
    stopWelcomeSpeechCycle();
    return;
  }
  startWelcomeSpeechCycle();
}

function startWelcomeSpeechCycle() {
  const speech = $("welcomeSpeech");
  if (!speech) return;
  if (welcomeSpeechTimer) return;
  welcomeSpeechIndex = 0;
  speech.textContent = WELCOME_SPEECH_LINES[0];
  welcomeSpeechTimer = window.setInterval(() => {
    if (!isWelcomeScreenVisible()) {
      stopWelcomeSpeechCycle();
      return;
    }
    welcomeSpeechIndex = (welcomeSpeechIndex + 1) % WELCOME_SPEECH_LINES.length;
    speech.textContent = WELCOME_SPEECH_LINES[welcomeSpeechIndex];
  }, 3200);
}

function stopWelcomeSpeechCycle() {
  if (welcomeSpeechTimer) {
    window.clearInterval(welcomeSpeechTimer);
    welcomeSpeechTimer = null;
  }
}

function dismissWelcomePlusGuide() {
  setWelcomeGuideDismissed(true);
  $("welcomePlusGuide")?.classList.add("hidden");
}

/* 시작 안내(+ 화살표 박스)는 더 이상 표시하지 않음 */

function setupWelcomeScreen() {
  setupWelcomeAdPopups();
  // Header + opens create menu; hide the floating guide when user engages it
  $("createMenuButton")?.addEventListener("click", () => {
    if (isWelcomeScreenVisible()) dismissWelcomePlusGuide();
  });
  window.addEventListener("resize", () => {
    if (isWelcomeScreenVisible()) positionWelcomePlusGuide();
  });
  window.addEventListener("load", () => updateWelcomeGuideUi());
  const welcome = $("welcome");
  if (welcome && typeof MutationObserver !== "undefined") {
    const mo = new MutationObserver(() => updateWelcomeGuideUi());
    mo.observe(welcome, { attributes: true, attributeFilter: ["class"] });
  }
  // Visibility refreshes again after feed load; hide until then if not yet loaded
  refreshWelcomeAdPopupsVisibility();
}

function openNewProjectModal() {
  const modal = $("newProjectModal");
  if (!modal) return;
  const titleInput = $("newProjectTitle");
  const purposeSelect = $("newProjectPurpose");
  if (titleInput) titleInput.value = "";
  if (purposeSelect) {
    const keys = Object.keys(purposeLabel);
    purposeSelect.innerHTML = keys
      .map((key) => `<option value="${escapeHtml(key)}">${escapeHtml(purposeLabel[key])}</option>`)
      .join("");
    purposeSelect.value = "general_novel";
  }
  setModalClusterId("newProject", "");
  renderGenreClusterGrid("newProject", "");
  syncModalGenreFields("newProject", purposeSelect?.value || "general_novel");
  resetModalDraftKeywords("newProject");
  const submit = $("newProjectSubmitButton");
  if (submit) {
    submit.disabled = false;
    submit.textContent = i18n.t('app.만들기');
  }
  const inheritToggle = $("newProjectInheritToggle");
  const inheritChronicle = $("newProjectInheritChronicle");
  if (inheritToggle) inheritToggle.checked = false;
  if (inheritChronicle) inheritChronicle.checked = false;
  fillNewProjectInheritSources();
  syncNewProjectInheritExtras();
  modal.classList.remove("hidden");
  window.setTimeout(() => titleInput?.focus(), 0);
}

function closeNewProjectModal() {
  $("newProjectModal")?.classList.add("hidden");
  const submit = $("newProjectSubmitButton");
  if (submit) {
    submit.disabled = false;
    submit.textContent = i18n.t('app.만들기');
  }
}

async function submitNewProject(event) {
  event?.preventDefault?.();
  const title = String($("newProjectTitle")?.value || "").trim();
  if (!title) {
    toast(i18n.t('app.작품_제목을_적어_주세요'));
    $("newProjectTitle")?.focus();
    return;
  }
  const purpose = normalizePurposeKey(
    $("newProjectPurpose")?.value || "general_novel",
  );
  const genres = readModalGenreValues("newProject", purpose);
  if (!genres.ok) {
    toast(genres.error || i18n.t('app.장르를_선택해_주세요_토리_학습에_필요해요'));
    $(genres.focusId)?.focus();
    return;
  }
  const inheritOn = Boolean($("newProjectInheritToggle")?.checked);
  const inheritFrom = Number($("newProjectInheritSource")?.value || 0);
  if (inheritOn && !inheritFrom) {
    toast(i18n.t("app.이어받을_작품을_골라_주세요"));
    $("newProjectInheritSource")?.focus();
    return;
  }
  const submit = $("newProjectSubmitButton");
  if (submit) {
    submit.disabled = true;
    submit.textContent = i18n.t('app.만드는_중');
  }
  try {
    const payload = {
        title,
        purpose: genres.purpose || purpose,
        main_genre: genres.main,
        sub_genre: genres.sub,
        genre_detail: genres.genre_detail || "",
        cluster_id: genres.cluster_id || getModalClusterId("newProject"),
        keywords: getModalDraftKeywords("newProject"),
    };
    if (inheritOn && inheritFrom) {
      payload.inherit_from_project_id = inheritFrom;
      payload.inherit_chronicle = Boolean($("newProjectInheritChronicle")?.checked);
    }
    const project = await api("/api/projects", {
      method: "POST",
      body: JSON.stringify(payload),
    });
    resetModalDraftKeywords("newProject");
    closeNewProjectModal();
    await loadProjects(project.id);
    try {
      await createDefaultOpeningStructure();
    } catch (err) {
      console.warn("[supertory] default opening structure failed", err);
    }
    const packageNote = project.package_name ? ` 파일: projects\\${project.package_name}` : "";
    if (project.inherited_from_title) {
      toast(i18n.t("app.title_의_설정을_이어받았어요", { title: project.inherited_from_title }));
    } else {
      toast(`${i18n.t('app.새_purposeLabel_purpose_작', {'purposeLabel[purpose] || "작품"': purposeLabel[purpose] || "작품", packageNote: packageNote})}`);
    }
  } catch (error) {
    if (submit) {
      submit.disabled = false;
      submit.textContent = i18n.t('app.만들기');
    }
    throw error;
  }
}

function fillNewProjectInheritSources() {
  const select = $("newProjectInheritSource");
  if (!select) return;
  const rows = Array.isArray(state.projects) ? state.projects : [];
  const current = Number(state.projectId || 0);
  const options = rows
    .filter((item) => Number(item?.id) > 0)
    .map((item) => {
      const id = Number(item.id);
      const selected = current && id === current ? " selected" : "";
      return `<option value="${id}"${selected}>${escapeHtml(item.title || i18n.t("app.작품"))}</option>`;
    });
  const placeholder = `<option value="">${escapeHtml(i18n.t("app.이어받을_작품을_골라_주세요"))}</option>`;
  select.innerHTML = placeholder + options.join("");
  if (current && rows.some((item) => Number(item.id) === current)) {
    select.value = String(current);
  }
  const block = $("newProjectInheritBlock");
  if (block) block.classList.toggle("is-empty", !rows.length);
}

function syncNewProjectInheritExtras() {
  const on = Boolean($("newProjectInheritToggle")?.checked);
  $("newProjectInheritExtras")?.classList.toggle("hidden", !on);
}

function setupNewProjectModal() {
  $("newProjectForm")?.addEventListener("submit", (event) => {
    submitNewProject(event).catch(handleError);
  });
  document.querySelectorAll("[data-close-new-project]").forEach((element) => {
    element.addEventListener("click", closeNewProjectModal);
  });
  setupGenreClusterPicker("newProject");
  $("newProjectPurpose")?.addEventListener("change", () => {
    syncModalGenreFields("newProject", $("newProjectPurpose")?.value || "general_novel");
  });
  $("newProjectMainGenre")?.addEventListener("change", () => {
    applyModalClusterPurpose("newProject");
    syncModalGenreFields("newProject", $("newProjectPurpose")?.value || "general_novel", {
      keepMain: true,
    });
  });
  setupModalKeywordField("newProject");
  $("newProjectInheritToggle")?.addEventListener("change", syncNewProjectInheritExtras);
}

/** Draft keywords for new-project / import modals (do not touch state.keywords until saved). */
const modalDraftKeywords = {
  newProject: [],
  import: [],
};

function getModalDraftKeywords(prefix) {
  return normalizeKeywordList(modalDraftKeywords[prefix] || []);
}

function resetModalDraftKeywords(prefix, seed = []) {
  modalDraftKeywords[prefix] = normalizeKeywordList(seed);
  setModalKeywordPickerOpen(prefix, false);
  renderModalKeywordField(prefix);
}

function renderModalKeywordField(prefix) {
  const list = $(`${prefix}KeywordChipList`);
  const catalog = $(`${prefix}KeywordCatalog`);
  const tags = getModalDraftKeywords(prefix);
  if (list) {
    list.innerHTML = tags.map((label) => `
      <span class="keyword-chip" data-keyword="${escapeHtml(label)}">
        <span class="keyword-chip-label">${escapeHtml(label)}</span>
        <button type="button" class="keyword-chip-remove" data-modal-keyword-remove="${escapeHtml(label)}" title="${i18n.t('app.제거')}" aria-label="${escapeHtml(label)} 제거">×</button>
      </span>
    `).join("");
  }
  if (catalog) {
    catalog.innerHTML = KEYWORD_CATALOG.map((group) => `
      <div class="keyword-category" data-keyword-group="${escapeHtml(group.key)}">
        <span class="keyword-category-title">${escapeHtml(group.title)}</span>
        <div class="keyword-tag-list">
          ${group.tags.map((tag) => {
            const selected = tags.includes(tag);
            return `<button type="button" class="keyword-tag${selected ? " is-selected" : ""}" data-modal-keyword-tag="${escapeHtml(tag)}" aria-pressed="${selected ? "true" : "false"}">${escapeHtml(tag)}</button>`;
          }).join("")}
        </div>
      </div>
    `).join("");
  }
}

function setModalKeywordPickerOpen(prefix, open) {
  const panel = $(`${prefix}KeywordPickerPanel`);
  const toggle = $(`${prefix}KeywordPickerToggle`);
  if (!panel) return;
  panel.classList.toggle("hidden", !open);
  if (toggle) toggle.setAttribute("aria-expanded", open ? "true" : "false");
  if (open) renderModalKeywordField(prefix);
}

function addModalDraftKeyword(prefix, label) {
  const cleaned = String(label || "").trim().slice(0, 40);
  if (!cleaned) return false;
  const current = getModalDraftKeywords(prefix);
  if (current.includes(cleaned)) return false;
  if (current.length >= KEYWORD_MAX) {
    toast(`${i18n.t('app.키워드는_최대_KEYWORD_MAX_개까지', {KEYWORD_MAX: KEYWORD_MAX})}`);
    return false;
  }
  modalDraftKeywords[prefix] = [...current, cleaned];
  renderModalKeywordField(prefix);
  return true;
}

function removeModalDraftKeyword(prefix, label) {
  const cleaned = String(label || "").trim();
  if (!cleaned) return;
  modalDraftKeywords[prefix] = getModalDraftKeywords(prefix).filter((item) => item !== cleaned);
  renderModalKeywordField(prefix);
}

function toggleModalDraftKeyword(prefix, label) {
  const cleaned = String(label || "").trim();
  if (!cleaned) return;
  if (getModalDraftKeywords(prefix).includes(cleaned)) removeModalDraftKeyword(prefix, cleaned);
  else addModalDraftKeyword(prefix, cleaned);
}

function setupModalKeywordField(prefix) {
  const toggle = $(`${prefix}KeywordPickerToggle`);
  const closeBtn = $(`${prefix}KeywordPickerClose`);
  const catalog = $(`${prefix}KeywordCatalog`);
  const chipList = $(`${prefix}KeywordChipList`);
  const customInput = $(`${prefix}KeywordCustomInput`);
  const customAdd = $(`${prefix}KeywordCustomAdd`);
  toggle?.addEventListener("click", () => {
    const panel = $(`${prefix}KeywordPickerPanel`);
    const open = Boolean(panel?.classList.contains("hidden"));
    setModalKeywordPickerOpen(prefix, open);
  });
  closeBtn?.addEventListener("click", () => setModalKeywordPickerOpen(prefix, false));
  catalog?.addEventListener("click", (event) => {
    const tag = event.target.closest?.("[data-modal-keyword-tag]");
    if (!tag || !catalog.contains(tag)) return;
    toggleModalDraftKeyword(prefix, tag.getAttribute("data-modal-keyword-tag") || "");
  });
  chipList?.addEventListener("click", (event) => {
    const btn = event.target.closest?.("[data-modal-keyword-remove]");
    if (!btn || !chipList.contains(btn)) return;
    removeModalDraftKeyword(prefix, btn.getAttribute("data-modal-keyword-remove") || "");
  });
  const commitCustom = () => {
    if (addModalDraftKeyword(prefix, customInput?.value || "")) {
      if (customInput) customInput.value = "";
    }
  };
  customAdd?.addEventListener("click", commitCustom);
  customInput?.addEventListener("keydown", (event) => {
    if (event.key !== "Enter") return;
    event.preventDefault();
    commitCustom();
  });
}

/** Open the new-project modal (Electron-safe; no window.prompt). */
function createProject() {
  openNewProjectModal();
}

/** @type {{ resolve: ((value: string|null) => void) } | null} */
let textPromptWaiter = null;

/**
 * Electron-safe text prompt (window.prompt is unavailable in Electron).
 * @param {string | {
 *   title?: string,
 *   message?: string,
 *   defaultValue?: string,
 *   placeholder?: string,
 *   label?: string,
 *   maxlength?: number,
 *   confirmLabel?: string,
 * }} messageOrOptions
 * @param {string} [defaultValue]
 * @returns {Promise<string|null>} entered string, or null if cancelled
 */
function promptText(messageOrOptions, defaultValue = "") {
  const opts = typeof messageOrOptions === "string"
    ? { message: messageOrOptions, defaultValue }
    : (messageOrOptions || {});
  const modal = $("textPromptModal");
  const input = $("textPromptInput");
  if (!modal || !input) {
    // Browser fallback (dev / non-Electron)
    try {
      return Promise.resolve(
        window.prompt(opts.message || opts.title || i18n.t('app.입력'), opts.defaultValue ?? ""),
      );
    } catch (_) {
      return Promise.resolve(null);
    }
  }
  if (textPromptWaiter) {
    textPromptWaiter.resolve(null);
    textPromptWaiter = null;
  }
  const titleEl = $("textPromptModalTitle");
  const messageEl = $("textPromptModalMessage");
  const submitBtn = $("textPromptSubmit");
  if (titleEl) titleEl.textContent = opts.title || i18n.t('app.입력');
  if (messageEl) {
    messageEl.textContent = String(opts.message || "").trim();
  }
  const labelTextEl = $("textPromptLabelText");
  if (labelTextEl) labelTextEl.textContent = opts.label || i18n.t('app.이름');
  input.maxLength = Number(opts.maxlength) > 0 ? Number(opts.maxlength) : 120;
  input.placeholder = opts.placeholder || "";
  input.value = opts.defaultValue != null ? String(opts.defaultValue) : "";
  if (submitBtn) submitBtn.textContent = opts.confirmLabel || i18n.t('app.확인');
  modal.classList.remove("hidden");
  window.setTimeout(() => {
    input.focus();
    input.select();
  }, 0);
  return new Promise((resolve) => {
    textPromptWaiter = { resolve };
  });
}

function closeTextPromptModal(result = null) {
  $("textPromptModal")?.classList.add("hidden");
  const waiter = textPromptWaiter;
  textPromptWaiter = null;
  if (waiter) waiter.resolve(result);
}

function setupTextPromptModal() {
  const form = $("textPromptForm");
  if (!form || form.dataset.bound === "1") return;
  form.dataset.bound = "1";
  form.addEventListener("submit", (event) => {
    event.preventDefault();
    const value = $("textPromptInput")?.value ?? "";
    closeTextPromptModal(value);
  });
  document.querySelectorAll("[data-close-text-prompt]").forEach((el) => {
    el.addEventListener("click", () => closeTextPromptModal(null));
  });
}

/**
 * Fill main/sub genre selects in new-project or import modal.
 * @param {"newProject"|"import"} prefix
 * @param {string} purpose
 * @param {{ keepMain?: boolean, keepSub?: boolean, main?: string, sub?: string }} [opts]
 */
function syncModalGenreFields(prefix, purpose, opts = {}) {
  const clusterId = getModalClusterId(prefix);
  if ($(`${prefix}ClusterGrid`)) {
    if (!clusterId || clusterId === "locked") {
      hideModalGenreSelects(prefix);
      return;
    }
    if (clusterId === "fairytale") {
      purpose = "fairy_tale";
      if ($(`${prefix}Purpose`)) $(`${prefix}Purpose`).value = "fairy_tale";
      $(`${prefix}MainGenreWrap`)?.classList.remove("hidden");
      hideModalGenreDetail(prefix);
    } else {
      fillModalClusterSubGenres(prefix, clusterId, opts);
      return;
    }
  }
  const mode = getPurposeCategoryMode(purpose);
  const mainSelect = $(`${prefix}MainGenre`);
  const subSelect = $(`${prefix}SubGenre`);
  const subWrap = $(`${prefix}SubGenreWrap`);
  if (!mainSelect || !subSelect) return;

  const prevMain = opts.keepMain ? mainSelect.value : (opts.main || "");
  const prevSub = opts.keepSub || opts.keepMain ? subSelect.value : (opts.sub || "");

  let mainOptions = MAIN_GENRES;
  let mainLabel = i18n.t('app.메인_장르');
  let subLabel = i18n.t('app.서브_장르');
  let showSub = true;
  if (mode === "translation") {
    mainOptions = WORK_LANGUAGES;
    mainLabel = i18n.t('app.원문_언어');
    subLabel = i18n.t('app.번역문_언어');
  } else if (mode === "fairy_tale") {
    mainOptions = FAIRY_TALE_AUDIENCES;
    mainLabel = i18n.t('app.동화_대상');
    showSub = false;
  } else if (mode === "none") {
    mainOptions = MAIN_GENRES;
    mainLabel = i18n.t('app.장르_분위기');
    showSub = false;
  }

  if ($(`${prefix}MainGenreLabel`)) {
    $(`${prefix}MainGenreLabel`).textContent = mainLabel;
  }
  if ($(`${prefix}SubGenreLabel`)) {
    $(`${prefix}SubGenreLabel`).textContent = subLabel;
  }
  if (subWrap) {
    subWrap.classList.toggle("hidden", !showSub);
  }

  const placeholderMain = mode === "translation"
    ? i18n.t('app.원문_언어를_선택해_주세요')
    : mode === "fairy_tale"
      ? i18n.t('app.동화_대상을_선택해_주세요')
      : i18n.t('app.장르를_선택해_주세요');
  mainSelect.innerHTML = `<option value="">${escapeHtml(placeholderMain)}</option>`
    + mainOptions.map((g) => `<option value="${escapeHtml(g.key)}">${escapeHtml(g.label)}</option>`).join("");
  if (prevMain && mainOptions.some((g) => g.key === prevMain)) mainSelect.value = prevMain;
  else mainSelect.value = "";
  mainSelect.required = true;
  mainSelect.disabled = false;

  if (!showSub) {
    subSelect.innerHTML = `<option value="">—</option>`;
    subSelect.value = "";
    subSelect.required = false;
    subSelect.disabled = true;
    return;
  }

  let subOptions = [];
  if (mode === "translation") {
    subOptions = WORK_LANGUAGES;
  } else {
    const mainKey = mainSelect.value;
    const prevPurpose = state.projectPurpose;
    state.projectPurpose = normalizePurposeKey(purpose);
    subOptions = withAdult19Option(mainKey ? (SUB_GENRES[mainKey] || []) : []);
    state.projectPurpose = prevPurpose;
  }
  const placeholderSub = mode === "translation"
    ? i18n.t('app.번역문_언어를_선택해_주세요')
    : i18n.t('app.세부_장르를_선택해_주세요');
  subSelect.disabled = !subOptions.length;
  subSelect.required = Boolean(subOptions.length);
  subSelect.innerHTML = `<option value="">${escapeHtml(placeholderSub)}</option>`
    + subOptions.map((g) => `<option value="${escapeHtml(g.key)}">${escapeHtml(g.label)}</option>`).join("");
  if (prevSub && subOptions.some((g) => g.key === prevSub)) subSelect.value = prevSub;
  else subSelect.value = "";
}

/**
 * @returns {{ ok: true, main: string, sub: string } | { ok: false, error: string, focusId: string }}
 */
function readModalGenreValues(prefix, purpose) {
  const clusterId = getModalClusterId(prefix);
  if ($(`${prefix}ClusterGrid`) && (!clusterId || clusterId === "locked")) {
    return {
      ok: false,
      error: i18n.t("app.클러스터를_선택해_주세요"),
      focusId: `${prefix}ClusterGrid`,
    };
  }
  if (clusterId && clusterId !== "fairytale") {
    const mapped = mapClusterSubgenre(clusterId, $(`${prefix}MainGenre`)?.value);
    if (!mapped) {
      return {
        ok: false,
        error: i18n.t("app.세부_장르를_선택해_주세요"),
        focusId: `${prefix}MainGenre`,
      };
    }
    return {
      ok: true,
      main: mapped.main,
      sub: mapped.sub,
      purpose: mapped.purpose,
      cluster_id: clusterId,
      genre_detail: readModalGenreDetail(prefix),
    };
  }
  const mode = getPurposeCategoryMode(purpose);
  const main = String($(`${prefix}MainGenre`)?.value || "").trim();
  const sub = String($(`${prefix}SubGenre`)?.value || "").trim();
  if (!main) {
    return {
      ok: false,
      error: i18n.t('app.장르를_선택해_주세요_토리가_학습하는_데_필'),
      focusId: `${prefix}MainGenre`,
    };
  }
  if ((mode === "fiction" || mode === "translation") && !sub) {
    return {
      ok: false,
      error: mode === "translation"
        ? i18n.t('app.번역문_언어를_선택해_주세요_토리_학습에_필')
        : i18n.t('app.서브_장르를_선택해_주세요_토리_학습에_필요'),
      focusId: `${prefix}SubGenre`,
    };
  }
  return {
    ok: true,
    main,
    sub: (mode === "fiction" || mode === "translation") ? sub : "",
    purpose: normalizePurposeKey(purpose),
    cluster_id: clusterId || inferClusterId(purpose, main, sub),
    genre_detail: readModalGenreDetail(prefix),
  };
}

/** Pending insert for +챕터: { partId, index } or null. */
let pendingChapterInsert = null;
let chapterInsertDragActive = false;
let suppressNextNewChapterClick = false;

function clearChapterInsertTarget() {
  pendingChapterInsert = null;
  chapterInsertDragActive = false;
  updateChapterInsertBanner();
  clearChapterInsertMarkers();
  $("outline")?.classList.remove("is-chapter-insert-drag");
  $("newChapterButton")?.classList.remove("is-dragging-source");
}

function clearChapterInsertMarkers() {
  const outline = $("outline");
  if (!outline) return;
  outline.querySelectorAll(".chapter-insert-slot").forEach((slot) => {
    slot.classList.remove("is-active");
  });
  outline.querySelectorAll(".outline-chapter").forEach((section) => {
    section.classList.remove("drag-insert-before", "drag-insert-after");
  });
}

function chaptersInInsertGroup(partId) {
  if (partId == null) {
    if ((state.parts || []).length) {
      return Array.isArray(state.ungroupedChapters) ? state.ungroupedChapters : [];
    }
    return Array.isArray(state.outline) ? state.outline : [];
  }
  const part = (state.parts || []).find((p) => Number(p.id) === Number(partId));
  return part?.chapters || [];
}

function describeChapterInsertTarget(target) {
  if (!target) return i18n.t('app.맨_아래');
  const partId = target.partId == null ? null : Number(target.partId);
  const index = Number(target.index) || 0;
  const chapters = chaptersInInsertGroup(partId);
  const partLabel = partId == null
    ? ((state.parts || []).length ? i18n.t('app.미분류') : i18n.t('app.목차'))
    : ((state.parts || []).find((p) => Number(p.id) === partId)?.title || i18n.t('app.폴더'));
  if (!chapters.length) return `${i18n.t('app.partLabel_안_첫_폴더', {partLabel: partLabel})}`;
  if (index >= chapters.length) {
    const last = chapters[chapters.length - 1];
    return `${i18n.t('app.partLabel_last_title_마지', {partLabel: partLabel, 'last?.title || "마지막"': last?.title || "마지막"})}`;
  }
  if (index <= 0) {
    return `${i18n.t('app.partLabel_chapters_0_ti', {partLabel: partLabel, 'chapters[0]?.title || "첫 폴더"': chapters[0]?.title || "첫 폴더"})}`;
  }
  const before = chapters[index - 1];
  const after = chapters[index];
  return `${i18n.t('app.partLabel_before_title', {partLabel: partLabel, 'before?.title || "?"': before?.title || "?", 'after?.title || "?"': after?.title || "?"})}`;
}

function updateChapterInsertBanner() {
  const banner = $("chapterInsertBanner");
  const text = $("chapterInsertBannerText");
  if (!banner || !text) return;
  if (!pendingChapterInsert) {
    banner.classList.add("hidden");
    return;
  }
  banner.classList.remove("hidden");
  text.textContent = `${i18n.t('app.삽입_위치_describeChapterIns', {'describeChapterInsertTarget(pendingChapterInsert)': describeChapterInsertTarget(pendingChapterInsert)})}`;
}

function setPendingChapterInsert(partId, index) {
  const chapters = chaptersInInsertGroup(partId);
  const max = chapters.length;
  pendingChapterInsert = {
    partId: partId == null || partId === "" ? null : Number(partId),
    index: Math.max(0, Math.min(Number(index) || 0, max)),
  };
  updateChapterInsertBanner();
  const outline = $("outline");
  if (!outline) return;
  clearChapterInsertMarkers();
  highlightChapterInsertSlot(pendingChapterInsert);
}

function highlightChapterInsertSlot(target) {
  if (!target) return;
  const outline = $("outline");
  if (!outline) return;
  const partKey = target.partId == null ? "" : String(target.partId);
  outline.querySelectorAll(".chapter-insert-slot").forEach((slot) => {
    const samePart = String(slot.dataset.partId || "") === partKey;
    const sameIndex = Number(slot.dataset.insertIndex) === Number(target.index);
    slot.classList.toggle("is-active", samePart && sameIndex);
  });
}

function chapterInsertHosts(outline) {
  if (!outline) return [];
  return [...outline.querySelectorAll("[data-part-chapters]")];
}

function injectChapterInsertSlots(outline) {
  if (!outline) return;
  const hosts = chapterInsertHosts(outline);
  if (!hosts.length) return;

  hosts.forEach((host) => {
    const rawPart = host.dataset.partChapters;
    const partId = rawPart === "" || rawPart == null ? null : Number(rawPart);
    const chapters = [...host.querySelectorAll(":scope > .outline-chapter")];

    const makeSlot = (index) => {
      const slot = document.createElement("div");
      slot.className = "chapter-insert-slot";
      slot.dataset.insertIndex = String(index);
      slot.dataset.partId = partId == null ? "" : String(partId);
      slot.setAttribute("aria-hidden", "true");
      slot.addEventListener("dragover", (event) => {
        if (!chapterInsertDragActive) return;
        event.preventDefault();
        event.stopPropagation();
        try { event.dataTransfer.dropEffect = "copy"; } catch (_) { /* ignore */ }
        clearChapterInsertMarkers();
        slot.classList.add("is-active");
      });
      slot.addEventListener("drop", (event) => {
        if (!chapterInsertDragActive) return;
        event.preventDefault();
        event.stopPropagation();
        finishNewChapterInsertDrop(partId, index);
      });
      return slot;
    };

    const keepNodes = [...host.childNodes].filter(
      (node) => !(node.nodeType === 1 && (
        node.classList?.contains("outline-chapter")
        || node.classList?.contains("chapter-insert-slot")
      )),
    );
    const fragment = document.createDocumentFragment();
    keepNodes.forEach((node) => fragment.appendChild(node));
    fragment.appendChild(makeSlot(0));
    chapters.forEach((section, index) => {
      fragment.appendChild(section);
      fragment.appendChild(makeSlot(index + 1));
    });
    host.replaceChildren(fragment);
  });

  if (pendingChapterInsert) highlightChapterInsertSlot(pendingChapterInsert);
}

function resolveNewChapterInsertDrop(outline, clientY, eventTarget) {
  if (!outline) return null;
  const section = eventTarget?.closest?.(".outline-chapter");
  let host = eventTarget?.closest?.("[data-part-chapters]");
  if (!host && section) host = chapterGroupContainer(section);
  if (!host || !outline.contains(host)) return null;

  const rawPart = host.dataset.partChapters;
  const partId = rawPart === "" || rawPart == null ? null : Number(rawPart);
  const chapters = [...host.querySelectorAll(":scope > .outline-chapter")];

  if (section && host.contains(section)) {
    const index = chapters.indexOf(section);
    if (index < 0) return { partId, index: chapters.length, host, section: null, before: false };
    const rect = section.getBoundingClientRect();
    const before = clientY < rect.top + rect.height / 2;
    return {
      partId,
      index: before ? index : index + 1,
      host,
      section,
      before,
    };
  }

  // Empty group / between slots
  return { partId, index: chapters.length, host, section: null, before: false };
}

function finishNewChapterInsertDrop(partId, index) {
  chapterInsertDragActive = false;
  suppressNextNewChapterClick = true;
  window.setTimeout(() => { suppressNextNewChapterClick = false; }, 120);
  $("newChapterButton")?.classList.remove("is-dragging-source");
  $("outline")?.classList.remove("is-chapter-insert-drag");
  clearChapterInsertMarkers();
  setPendingChapterInsert(partId, index);
  // Drop = create at that position immediately (prompt for name)
  createChapter({
    partId: partId == null ? null : Number(partId),
    insertIndex: Number(index),
  }).catch(handleError);
}

function setupNewChapterDrag() {
  const button = $("newChapterButton");
  if (!button || button.dataset.dragBound === "1") return;
  button.dataset.dragBound = "1";
  button.draggable = true;

  button.addEventListener("dragstart", (event) => {
    if (!state.projectId) {
      event.preventDefault();
      toast(i18n.t('app.먼저_새_작품을_만들어_주세요'));
      return;
    }
    chapterInsertDragActive = true;
    button.classList.add("is-dragging-source");
    event.dataTransfer.effectAllowed = "copy";
    try {
      event.dataTransfer.setData("text/plain", "supertory-new-chapter");
      event.dataTransfer.setData("application/x-supertory-new-chapter", "1");
    } catch (_) {
      /* ignore */
    }
    const outline = $("outline");
    outline?.classList.add("is-chapter-insert-drag");
  });

  button.addEventListener("dragend", () => {
    chapterInsertDragActive = false;
    button.classList.remove("is-dragging-source");
    const outline = $("outline");
    outline?.classList.remove("is-chapter-insert-drag");
    if (pendingChapterInsert) highlightChapterInsertSlot(pendingChapterInsert);
    else clearChapterInsertMarkers();
  });

  const outline = $("outline");
  if (outline && outline.dataset.insertDropBound !== "1") {
    outline.dataset.insertDropBound = "1";
    outline.addEventListener("dragover", (event) => {
      if (!chapterInsertDragActive) return;
      if (event.target.closest?.(".chapter-insert-slot")) {
        event.preventDefault();
        try { event.dataTransfer.dropEffect = "copy"; } catch (_) { /* ignore */ }
        return;
      }
      const drop = resolveNewChapterInsertDrop(outline, event.clientY, event.target);
      if (!drop) return;
      event.preventDefault();
      try { event.dataTransfer.dropEffect = "copy"; } catch (_) { /* ignore */ }
      clearChapterInsertMarkers();
      highlightChapterInsertSlot({ partId: drop.partId, index: drop.index });
      if (drop.section) {
        drop.section.classList.toggle("drag-insert-before", drop.before);
        drop.section.classList.toggle("drag-insert-after", !drop.before);
      }
    });
    outline.addEventListener("drop", (event) => {
      if (!chapterInsertDragActive) return;
      if (event.target.closest?.(".chapter-insert-slot")) return;
      const drop = resolveNewChapterInsertDrop(outline, event.clientY, event.target);
      if (!drop) return;
      event.preventDefault();
      event.stopPropagation();
      finishNewChapterInsertDrop(drop.partId, drop.index);
    });
  }

  $("clearChapterInsertButton")?.addEventListener("click", () => {
    clearChapterInsertTarget();
    toast(i18n.t('app.삽입_위치를_취소했어요_클릭_추가는_맨_아래'));
  });
}

function openRenumberChaptersModal(message) {
  const modal = $("renumberChaptersModal");
  if (!modal) return;
  if (message && $("renumberChaptersMessage")) {
    $("renumberChaptersMessage").innerHTML = message;
  } else if ($("renumberChaptersMessage")) {
    $("renumberChaptersMessage").innerHTML =
      i18n.t('app.목록_번호를_재정렬_하시겠습니까_br_현재');
  }
  modal.classList.remove("hidden");
}

function closeRenumberChaptersModal() {
  $("renumberChaptersModal")?.classList.add("hidden");
}

async function renumberChapterTitles(style = "jang") {
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  if (!state.outline?.length) return toast(i18n.t('app.정리할_챕터가_없어요'));
  const result = await api(`/api/projects/${state.projectId}/chapters/renumber-titles`, {
    method: "PUT",
    body: JSON.stringify({ style }),
  });
  // Server logs folder.renumber_titles only when titles actually changed
  const changed = Number(result?.changed);
  if (changed > 0 && typeof noteFolderUndoAvailable === "function") {
    noteFolderUndoAvailable();
  }
  await loadProject();
  if (typeof refreshFolderUndoHintFromServer === "function") {
    refreshFolderUndoHintFromServer().catch(() => {});
  }
  toast(`${i18n.t('app.챕터_순번을_다시_매겼어요_result_co', {'result.count || state.outline.length': result.count || state.outline.length})}`);
}

/* —— 바인더 목차: 폴더 개수 + 우클릭 글자 크기 + 안내 팁(닫기) —— */
const OUTLINE_TITLE_FONT_KEY = "supertory.outlineTitleFontSize";
const OUTLINE_TITLE_FONT_MIN = 11;
const OUTLINE_TITLE_FONT_MAX = 18;
const OUTLINE_TITLE_FONT_DEFAULT = 12;
const OUTLINE_TIP_HIDDEN_KEY = "supertory.outlineTipHidden";
const OUTLINE_ROW_GAP_KEY = "supertory.outlineRowGap";
const OUTLINE_ROW_GAP_MIN = 0;
const OUTLINE_ROW_GAP_MAX = 12;
const OUTLINE_ROW_GAP_DEFAULT = 4;

function getOutlineRowGap() {
  try {
    const n = Number(localStorage.getItem(OUTLINE_ROW_GAP_KEY));
    if (Number.isFinite(n) && n >= OUTLINE_ROW_GAP_MIN && n <= OUTLINE_ROW_GAP_MAX) {
      return Math.round(n);
    }
  } catch (_) { /* ignore */ }
  return OUTLINE_ROW_GAP_DEFAULT;
}

function applyOutlineRowGap(gapPx, { persist = true } = {}) {
  const gap = Math.max(
    OUTLINE_ROW_GAP_MIN,
    Math.min(
      OUTLINE_ROW_GAP_MAX,
      Math.round(Number(gapPx) || getOutlineRowGap() || OUTLINE_ROW_GAP_DEFAULT),
    ),
  );
  const root = $("manuscriptBinder") || $("outline");
  if (root) root.style.setProperty("--outline-row-gap", `${gap}px`);
  if ($("outline")) $("outline").style.setProperty("--outline-row-gap", `${gap}px`);
  if ($("outlineRowGapValue")) $("outlineRowGapValue").textContent = String(gap);
  document.querySelectorAll("#outlineSpacingMenu [data-outline-gap]").forEach((btn) => {
    btn.classList.toggle("is-active", Number(btn.dataset.outlineGap) === gap);
  });
  if (persist) {
    try { localStorage.setItem(OUTLINE_ROW_GAP_KEY, String(gap)); } catch (_) { /* ignore */ }
  }
  return gap;
}

function hideOutlineSpacingMenu() {
  const menu = $("outlineSpacingMenu");
  const btn = $("outlineSpacingButton");
  menu?.classList.add("hidden");
  // 메뉴 전용 expanded 만 끄고, 스크롤 조절 모드 활성 표시는 유지
  if (!isOutlineSpacingAdjustMode()) {
    btn?.setAttribute("aria-expanded", "false");
  }
}

function showOutlineSpacingMenu(anchorEl) {
  const menu = $("outlineSpacingMenu");
  const btn = $("outlineSpacingButton");
  if (!menu) return;
  // 글자 크기 + 줄간격 통합 메뉴
  applyOutlineTitleFontSize(getOutlineTitleFontSize(), { persist: false });
  applyOutlineRowGap(getOutlineRowGap(), { persist: false });
  menu.classList.remove("hidden");
  btn?.setAttribute("aria-expanded", "true");
  const pad = 8;
  const ar = (anchorEl || btn)?.getBoundingClientRect?.();
  let left = ar ? ar.left : 12;
  let top = ar ? ar.bottom + 4 : 12;
  const rect = menu.getBoundingClientRect();
  const width = rect.width || 200;
  const height = rect.height || 320;
  if (left + width > window.innerWidth - pad) {
    left = Math.max(pad, window.innerWidth - width - pad);
  }
  if (top + height > window.innerHeight - pad) {
    top = ar
      ? Math.max(pad, ar.top - height - 4)
      : Math.max(pad, window.innerHeight - height - pad);
  }
  menu.style.left = `${Math.round(left)}px`;
  menu.style.top = `${Math.round(top)}px`;
}

/** 목차 줄간격 아이콘: 클릭 후 휠로 글자 크기+줄간격 동시 조절 */
let outlineSpacingAdjustMode = false;
let outlineSpacingAdjustToastAt = 0;

function isOutlineSpacingAdjustMode() {
  return Boolean(outlineSpacingAdjustMode);
}

function isOutlineSpacingAdjustSurface(target) {
  return Boolean(
    target?.closest?.(
      "#outline, #manuscriptBinder, #outlineSpacingButton, .outline-spacing-btn, #binderPanel, #settingsBinder",
    ),
  );
}

/** 목차 영역(휠 조절 대상) — 아이콘·메뉴 제외 */
function isOutlineScrollAdjustTarget(target) {
  if (!target?.closest) return false;
  if (target.closest("#outlineSpacingButton, .outline-spacing-btn, #outlineSpacingMenu")) {
    return false;
  }
  return Boolean(
    target.closest(
      "#outline, #manuscriptBinder .binder-view, #manuscriptBinder #outline, #binderPanel #outline, .outline-tree, #manuscriptBinder",
    ),
  );
}

function syncOutlineSpacingAdjustUi() {
  const btn = $("outlineSpacingButton");
  if (!btn) return;
  const on = isOutlineSpacingAdjustMode();
  btn.classList.toggle("is-adjust-mode", on);
  btn.setAttribute("aria-pressed", on ? "true" : "false");
  btn.setAttribute("aria-expanded", on ? "true" : "false");
  btn.title = on
    ? i18n.t('app.조절_모드_목차_위에서_스크롤로_글자_줄간격')
    : i18n.t('app.목차_줄간격_조절_클릭_후_목차에서_스크롤');
  document.body.classList.toggle("outline-spacing-adjust-mode", on);
  $("manuscriptBinder")?.classList.toggle("is-spacing-adjust-mode", on);
  $("outline")?.classList.toggle("is-spacing-adjust-mode", on);
}

function enterOutlineSpacingAdjustMode({ toastMsg = true } = {}) {
  if (outlineSpacingAdjustMode) {
    syncOutlineSpacingAdjustUi();
    return;
  }
  hideOutlineTitleFontMenu();
  hideOutlineSpacingMenu();
  outlineSpacingAdjustMode = true;
  syncOutlineSpacingAdjustUi();
  if (toastMsg) {
    toast(i18n.t('app.목차_조절_모드_목록_위에서_스크롤하세요_다'));
  }
}

function exitOutlineSpacingAdjustMode({ toastMsg = false } = {}) {
  if (!outlineSpacingAdjustMode) {
    syncOutlineSpacingAdjustUi();
    return;
  }
  outlineSpacingAdjustMode = false;
  syncOutlineSpacingAdjustUi();
  if (toastMsg) toast(i18n.t('app.목차_조절_모드를_끝냈어요'));
}

function toggleOutlineSpacingAdjustMode() {
  if (outlineSpacingAdjustMode) exitOutlineSpacingAdjustMode({ toastMsg: true });
  else enterOutlineSpacingAdjustMode({ toastMsg: true });
}

/**
 * 글자 크기 + 행 간격을 한 단계씩 같이 조절 (휠/버튼 공용).
 * @param {number} delta 양수=크게, 음수=작게
 */
function nudgeOutlineSpacingScale(delta) {
  const step = Math.sign(Number(delta) || 0);
  if (!step) return null;
  const prevFont = getOutlineTitleFontSize();
  const prevGap = getOutlineRowGap();
  const nextFont = applyOutlineTitleFontSize(prevFont + step, { persist: true });
  // 갭은 폰트와 같은 방향으로 1px, 범위 클램프
  const nextGap = applyOutlineRowGap(prevGap + step, { persist: true });
  // 둘 다 한계에 걸리면 안내
  const atMin = nextFont <= OUTLINE_TITLE_FONT_MIN && nextGap <= OUTLINE_ROW_GAP_MIN && step < 0;
  const atMax = nextFont >= OUTLINE_TITLE_FONT_MAX && nextGap >= OUTLINE_ROW_GAP_MAX && step > 0;
  const now = Date.now();
  if ((atMin || atMax) && now - outlineSpacingAdjustToastAt > 900) {
    outlineSpacingAdjustToastAt = now;
    toast(atMax ? i18n.t('app.더_이상_키울_수_없어요') : i18n.t('app.더_이상_줄일_수_없어요'));
  } else if (now - outlineSpacingAdjustToastAt > 1200 && (nextFont !== prevFont || nextGap !== prevGap)) {
    outlineSpacingAdjustToastAt = now;
    // 너무 잦은 토스트 방지 — 가끔 현재 값만
  }
  return { font: nextFont, gap: nextGap };
}

function onOutlineSpacingAdjustWheel(event) {
  if (!isOutlineSpacingAdjustMode()) return;
  if (!isOutlineScrollAdjustTarget(event.target)) return;
  // 조절 모드에서는 목록 스크롤 대신 크기 조절
  event.preventDefault();
  event.stopPropagation();
  const raw = Number(event.deltaY) || 0;
  if (!raw) return;
  // 트랙패드 작은 값 누적 완화: 한 틱 = 1단계
  const step = raw < 0 ? 1 : -1;
  nudgeOutlineSpacingScale(step);
}

function getOutlineTitleFontSize() {
  try {
    const n = Number(localStorage.getItem(OUTLINE_TITLE_FONT_KEY));
    if (Number.isFinite(n) && n >= OUTLINE_TITLE_FONT_MIN && n <= OUTLINE_TITLE_FONT_MAX) {
      return Math.round(n);
    }
  } catch (_) { /* ignore */ }
  return OUTLINE_TITLE_FONT_DEFAULT;
}

function applyOutlineTitleFontSize(sizePx, { persist = true } = {}) {
  const size = Math.max(
    OUTLINE_TITLE_FONT_MIN,
    Math.min(
      OUTLINE_TITLE_FONT_MAX,
      Math.round(Number(sizePx) || getOutlineTitleFontSize() || OUTLINE_TITLE_FONT_DEFAULT),
    ),
  );
  const root = $("manuscriptBinder") || $("outline");
  if (root) root.style.setProperty("--outline-title-size", `${size}px`);
  if ($("outline")) $("outline").style.setProperty("--outline-title-size", `${size}px`);
  if ($("outlineTitleFontValue")) $("outlineTitleFontValue").textContent = String(size);
  document.querySelectorAll("#outlineSpacingMenu [data-outline-font]").forEach((btn) => {
    btn.classList.toggle("is-active", Number(btn.dataset.outlineFont) === size);
  });
  if (persist) {
    try { localStorage.setItem(OUTLINE_TITLE_FONT_KEY, String(size)); } catch (_) { /* ignore */ }
  }
  return size;
}

function hideOutlineTitleFontMenu() {
  // 글자 크기는 줄간격 메뉴에 통합됨
  hideOutlineSpacingMenu();
}

function showOutlineTitleFontMenu(_clientX, _clientY) {
  // 호환: 예전 진입점 → 통합 메뉴
  showOutlineSpacingMenu($("outlineSpacingButton"));
}

function updateOutlineFolderCount() {
  const folderEl = $("outlineFolderCount");
  const sceneEl = $("outlineSceneCount");
  const folderN = Array.isArray(state.outline)
    ? state.outline.filter((ch) => !ch?.transparent && !String(ch?.notes_md || "").includes("supertory:transparent_volume")).length
    : 0;
  let sceneN = 0;
  try {
    sceneN = flattenAllOutlineScenes().length;
  } catch (_) {
    for (const chapter of state.outline || []) {
      sceneN += flattenChapterScenes(chapter).length;
    }
  }
  if (folderEl) {
    const num = folderEl.querySelector(".outline-count-num");
    if (num) num.textContent = String(folderN);
    else folderEl.textContent = String(folderN);
    folderEl.setAttribute("aria-label", `${i18n.t('app.폴더_folderN_개', {folderN: folderN})}`);
    folderEl.title = `${i18n.t('app.폴더_folderN_개', {folderN: folderN})}`;
  }
  if (sceneEl) {
    const num = sceneEl.querySelector(".outline-count-num");
    if (num) num.textContent = String(sceneN);
    else sceneEl.textContent = String(sceneN);
    sceneEl.setAttribute("aria-label", `${i18n.t('app.원고_sceneN_개', {sceneN: sceneN})}`);
    sceneEl.title = `${i18n.t('app.원고_sceneN_개', {sceneN: sceneN})}`;
  }
  const heading = $("outlineTocHeading");
  if (heading) {
    heading.title = `${i18n.t('app.폴더_folderN_원고_sceneN_클릭', {folderN: folderN, sceneN: sceneN})}`;
  }
}

function isOutlineTipHidden() {
  return isGuideTipHidden("outline");
}

function setOutlineTipHidden(hidden) {
  setGuideTipHidden("outline", hidden, { quiet: true });
}

function syncOutlineTipBox() {
  syncGuideTipBoxes();
}

function isOutlineFontMenuTarget(target) {
  // 목차 제목 우클릭 없음 · 글자 크기는 줄간격 아이콘 우클릭 메뉴
  return Boolean(
    target?.closest?.(
      "#outlineSpacingButton, .outline-spacing-btn, #outlineSpacingMenu",
    ),
  );
}

function isOutlineOverviewOpen() {
  return Boolean($("outlineOverviewModal") && !$("outlineOverviewModal").classList.contains("hidden"));
}

function closeOutlineOverview() {
  $("outlineOverviewModal")?.classList.add("hidden");
}

function renderOutlineOverviewSceneTree(scenes, depth = 0, includeChildChapters = true) {
  const list = Array.isArray(scenes) ? scenes : [];
  const currentId = Number(state.sceneId) || 0;
  return list.map((scene) => {
    const display = typeof getOutlineSceneDisplay === "function"
      ? getOutlineSceneDisplay(scene)
      : { label: scene.title || i18n.t('app.원고'), isPreview: false };
    const sid = Number(scene.id);
    const depthClass = depth > 0 ? ` is-depth-${Math.min(depth, 5)}` : "";
    const currentClass = sid === currentId ? " is-current" : "";
    const previewClass = display.isPreview ? " is-body-preview" : "";
    const kids = renderOutlineOverviewSceneTree(scene.children || [], depth + 1, includeChildChapters);
    const nestedFolders = includeChildChapters
      ? (scene.child_chapters || [])
        .map((ch) => renderOutlineOverviewChapter(ch, "is-level-2"))
        .join("")
      : "";
    return `
      <button type="button" class="outline-overview-scene${depthClass}${currentClass}" data-overview-scene="${sid}" title="${escapeHtml(display.tooltip || display.label)}">
        <span class="outline-overview-scene-label${previewClass}">${escapeHtml(display.label)}</span>
      </button>
      ${kids}
      ${nestedFolders}`;
  }).join("");
}

function renderOutlineOverviewChapter(chapter, folderLevel = "is-level-1", includeChildChapters = true) {
  const transparent = Boolean(chapter.transparent)
    || String(chapter.notes_md || "").includes("supertory:transparent_volume");
  const scenesHtml = renderOutlineOverviewSceneTree(chapter.scenes || [], 0, includeChildChapters);
  if (transparent) {
    return scenesHtml || "";
  }
  return `
    <button type="button" class="outline-overview-folder ${folderLevel}" data-overview-chapter="${chapter.id}" title="${escapeHtml(chapter.title || "폴더")}">
      ${escapeHtml(chapter.title || i18n.t('app.폴더'))}
    </button>
    ${scenesHtml}`;
}

function outlineOverviewFolderLevel(depth) {
  if (depth <= 0) return "is-level-0";
  if (depth >= 2) return "is-level-2";
  return "is-level-1";
}

/** Recurse binder folder forest. Boxes are containers; non-box folders are chapter rows. */
function renderOutlineOverviewFolderNode(node, depth = 0) {
  if (!node) return "";
  const kids = typeof getBinderChildFolders === "function"
    ? getBinderChildFolders(node)
    : (node.children || []);
  const isBox = typeof binderFolderNodeIsBox === "function" && binderFolderNodeIsBox(node);
  if (isBox) {
    const scenesHtml = renderOutlineOverviewSceneTree(node.scenes || [], 0, false);
    const nested = kids.map((child) => renderOutlineOverviewFolderNode(child, depth + 1)).join("");
    const inner = `${scenesHtml}${nested}`;
    if (typeof isTransparentBinderNode === "function" && isTransparentBinderNode(node)) {
      return inner || i18n.t('app.p_class_outline_overvie_2');
    }
    return `
      <section class="outline-overview-part">
        <button type="button" class="outline-overview-part-title" data-overview-part="${node.id}" title="${escapeHtml(node.title || "폴더")}">
          ${escapeHtml(node.title || i18n.t('app.폴더'))}
        </button>
        ${inner || i18n.t('app.p_class_outline_overvie_2')}
      </section>`;
  }
  const chapterHtml = renderOutlineOverviewChapter(
    node,
    outlineOverviewFolderLevel(depth),
    false
  );
  const nested = kids.map((child) => renderOutlineOverviewFolderNode(child, depth + 1)).join("");
  return `${chapterHtml}${nested}`;
}

function renderOutlineOverviewBody() {
  const body = $("outlineOverviewBody");
  if (!body) return;
  if (!state.projectId) {
    body.innerHTML = i18n.t('app.p_class_outline_overvie');
    return;
  }

  if (typeof shouldUseFoldersOutline === "function" && shouldUseFoldersOutline()) {
    const roots = (state.folders || []).map((folder) => (
      typeof normalizeApiFolderNode === "function" ? normalizeApiFolderNode(folder) : folder
    ));
    const forestHtml = roots.map((node) => renderOutlineOverviewFolderNode(node, 0)).join("");
    const seen = new Set();
    const markSeen = (nodes) => {
      for (const node of nodes || []) {
        if (!node) continue;
        const id = Number(node.id);
        if (id) seen.add(id);
        const children = typeof getBinderChildFolders === "function"
          ? getBinderChildFolders(node)
          : (node.children || []);
        markSeen(children);
      }
    };
    markSeen(roots);
    const leftover = [];
    walkReadingOrderChapters(state.outline || [], (chapter) => {
      const id = Number(chapter.id);
      if (!id || seen.has(id)) return;
      seen.add(id);
      leftover.push(chapter);
    });
    const leftoverHtml = leftover.length
      ? `${i18n.t('app.div_class_outline_overv')}${leftover.map((ch) => renderOutlineOverviewChapter(ch, "is-level-1")).join("")}`
      : "";
    if (!forestHtml && !leftoverHtml) {
      body.innerHTML = i18n.t('app.p_class_outline_overvie_3');
      return;
    }
    body.innerHTML = `${forestHtml}${leftoverHtml}`;
    return;
  }

  const parts = Array.isArray(state.parts) ? state.parts : [];
  const ungrouped = Array.isArray(state.ungroupedChapters)
    ? state.ungroupedChapters
    : (state.outline || []);
  const partBlocks = parts.map((part) => {
    const chapters = part.chapters || [];
    const chapterHtml = chapters.length
      ? chapters.map((ch) => renderOutlineOverviewChapter(ch, "is-level-1")).join("")
      : i18n.t('app.p_class_outline_overvie_2');
    return `
      <section class="outline-overview-part">
        <button type="button" class="outline-overview-part-title" data-overview-part="${part.id}" title="${escapeHtml(part.title || "폴더")}">
          ${escapeHtml(part.title || i18n.t('app.폴더'))}
        </button>
        ${chapterHtml}
      </section>`;
  }).join("");

  const ungroupedHtml = ungrouped.length
    ? `
      ${parts.length ? i18n.t('app.div_class_outline_overv') : ""}
      ${ungrouped.map((ch) => renderOutlineOverviewChapter(ch, parts.length ? "is-level-1" : "is-level-0")).join("")}`
    : "";

  if (!partBlocks && !ungroupedHtml) {
    body.innerHTML = i18n.t('app.p_class_outline_overvie_3');
    return;
  }
  body.innerHTML = `${partBlocks}${ungroupedHtml}`;
}

function openOutlineOverview() {
  if (!state.projectId) {
    toast(i18n.t('app.작품을_먼저_선택해_주세요'));
    return;
  }
  renderOutlineOverviewBody();
  $("outlineOverviewModal")?.classList.remove("hidden");
  requestAnimationFrame(() => {
    $("outlineOverviewBody")?.querySelector?.(".outline-overview-scene.is-current")?.scrollIntoView?.({
      block: "nearest",
    });
  });
}

function focusOutlineBinderTarget({ partId = null, chapterId = null, sceneId = null } = {}) {
  const outline = $("outline");
  if (!outline) return;
  if (partId != null) {
    setPartCollapsed?.(Number(partId), false);
    const el = outline.querySelector(`.outline-part[data-part-id="${partId}"]`)
      || outline.querySelector(`.outline-part[data-chapter-id="${partId}"]`);
    el?.scrollIntoView?.({ block: "nearest", behavior: "smooth" });
    el?.querySelector?.("[data-rename-part], [data-rename-chapter]")?.classList?.add("is-selected");
    return;
  }
  if (chapterId != null) {
    setChapterCollapsed?.(Number(chapterId), false);
    const el = outline.querySelector(`.outline-chapter[data-chapter-id="${chapterId}"]`);
    el?.scrollIntoView?.({ block: "nearest", behavior: "smooth" });
    el?.querySelector?.("[data-rename-chapter]")?.classList?.add("is-selected");
  }
}

function setupOutlineOverview() {
  if (setupOutlineOverview._bound) return;
  setupOutlineOverview._bound = true;

  const heading = $("outlineTocHeading");
  heading?.addEventListener("click", (event) => {
    // Count badges keep their own right-click menu; left click on heading opens overview
    if (event.target.closest?.(".outline-count-badges, #outlineFolderCount, #outlineSceneCount")) {
      // Still allow overview when clicking badges — one glance TOC
    }
    event.preventDefault();
    openOutlineOverview();
  });
  heading?.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") return;
    event.preventDefault();
    openOutlineOverview();
  });

  document.querySelectorAll("[data-close-outline-overview]").forEach((el) => {
    el.addEventListener("click", closeOutlineOverview);
  });

  $("outlineOverviewBody")?.addEventListener("click", (event) => {
    const sceneBtn = event.target.closest?.("[data-overview-scene]");
    if (sceneBtn) {
      const id = Number(sceneBtn.dataset.overviewScene);
      if (!id) return;
      closeOutlineOverview();
      openScene(id).catch(handleError);
      return;
    }
    const chapterBtn = event.target.closest?.("[data-overview-chapter]");
    if (chapterBtn) {
      const id = Number(chapterBtn.dataset.overviewChapter);
      if (!id) return;
      closeOutlineOverview();
      focusOutlineBinderTarget({ chapterId: id });
      return;
    }
    const partBtn = event.target.closest?.("[data-overview-part]");
    if (partBtn) {
      const id = Number(partBtn.dataset.overviewPart);
      if (!id) return;
      closeOutlineOverview();
      focusOutlineBinderTarget({ partId: id });
    }
  });

  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    if (!isOutlineOverviewOpen()) return;
    event.preventDefault();
    closeOutlineOverview();
  });
}

function setupOutlineBinderChrome() {
  if (setupOutlineBinderChrome._bound) return;
  setupOutlineBinderChrome._bound = true;
  applyOutlineTitleFontSize(getOutlineTitleFontSize(), { persist: false });
  applyOutlineRowGap(getOutlineRowGap(), { persist: false });
  syncOutlineTipBox();
  updateOutlineFolderCount();

  // outline tip dismiss is handled by setupGuideTips (data-guide-tip-dismiss)

  // 목차 제목·개수: 우클릭 메뉴 없음 (글자 크기는 줄간격 아이콘 우클릭)

  $("outlineTitleFontDown")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    applyOutlineTitleFontSize(getOutlineTitleFontSize() - 1);
  });
  $("outlineTitleFontUp")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    applyOutlineTitleFontSize(getOutlineTitleFontSize() + 1);
  });

  // 줄간격 아이콘: 클릭 → 조절 모드, 목차 위 휠 → 글자+줄간격 동시 조절
  $("outlineSpacingButton")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    hideOutlineSpacingMenu();
    toggleOutlineSpacingAdjustMode();
  });
  // 우클릭: 글자 크기 + 줄간격 통합 메뉴 (하단: 개수 숨기기 · 이 기능 숨기기)
  $("outlineSpacingButton")?.addEventListener("contextmenu", (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (isOutlineSpacingAdjustMode()) exitOutlineSpacingAdjustMode({ toastMsg: false });
    const menu = $("outlineSpacingMenu");
    if (menu && !menu.classList.contains("hidden")) {
      hideOutlineSpacingMenu();
      return;
    }
    setUiFeatureCtxTarget?.(event.currentTarget);
    showOutlineSpacingMenu(event.currentTarget);
  });
  $("outlineRowGapDown")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    applyOutlineRowGap(getOutlineRowGap() - 1);
  });
  $("outlineRowGapUp")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    applyOutlineRowGap(getOutlineRowGap() + 1);
  });
  $("outlineSpacingMenu")?.addEventListener("click", (event) => {
    const hideCounts = event.target.closest?.("[data-outline-hide-counts]");
    if (hideCounts) {
      event.preventDefault();
      event.stopPropagation();
      hideOutlineSpacingMenu();
      const badges = $("outlineCountBadges")
        || document.querySelector(".outline-count-badges")
        || $("outlineFolderCount")
        || $("outlineSceneCount");
      if (badges && typeof hideUiFeatureElement === "function") {
        hideUiFeatureElement(badges);
      } else {
        toast(i18n.t('app.숨길_개수_표시를_찾지_못했어요'));
      }
      return;
    }
    const fontPreset = event.target.closest?.("[data-outline-font]");
    if (fontPreset) {
      event.preventDefault();
      event.stopPropagation();
      applyOutlineTitleFontSize(fontPreset.dataset.outlineFont);
      return;
    }
    const gapPreset = event.target.closest?.("[data-outline-gap]");
    if (gapPreset) {
      event.preventDefault();
      event.stopPropagation();
      applyOutlineRowGap(gapPreset.dataset.outlineGap);
      return;
    }
    event.stopPropagation();
  });

  // 조절 모드 휠 (capture: 목록 스크롤보다 먼저)
  document.addEventListener("wheel", onOutlineSpacingAdjustWheel, { passive: false, capture: true });

  document.addEventListener("click", (event) => {
    if (event.target.closest?.("#outlineSpacingMenu, #outlineSpacingButton")) return;
    hideOutlineSpacingMenu();
    // 조절 모드: 목차(바인더) 바깥 클릭 시 종료
    if (isOutlineSpacingAdjustMode() && !isOutlineSpacingAdjustSurface(event.target)) {
      exitOutlineSpacingAdjustMode({ toastMsg: true });
    }
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      hideOutlineSpacingMenu();
      if (isOutlineSpacingAdjustMode()) exitOutlineSpacingAdjustMode({ toastMsg: true });
    }
  });
  window.addEventListener("resize", () => {
    hideOutlineSpacingMenu();
  });
  window.addEventListener("blur", () => {
    hideOutlineSpacingMenu();
  });
  syncOutlineSpacingAdjustUi();
}

function setupRenumberChaptersModal() {
  $("renumberChaptersButton")?.addEventListener("click", () => {
    if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
    if (!state.outline?.length) return toast(i18n.t('app.정리할_챕터가_없어요'));
    openRenumberChaptersModal();
  });
  document.querySelectorAll("[data-close-renumber]").forEach((el) => {
    el.addEventListener("click", closeRenumberChaptersModal);
  });
  $("confirmRenumberChaptersButton")?.addEventListener("click", () => {
    const style = $("renumberStyleSelect")?.value || "jang";
    closeRenumberChaptersModal();
    renumberChapterTitles(style).catch(handleError);
  });
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    if (!$("renumberChaptersModal")?.classList.contains("hidden")) {
      closeRenumberChaptersModal();
    }
  });
}

/**
 * +챕터 통합:
 * - 루트 클릭: 폴더(chapter) 하나만 추가. 상위 상자+하위 폴더를 동시에 만들지 않음.
 * - 상위 폴더 안(+): 하위 폴더(chapter)만 추가
 * - 끌어다 놓기 / 삽입 위치: 해당 그룹(상자·미분류) 안에 폴더 추가
 */
async function createChapter(options = {}) {
  if (!state.projectId) return toast(i18n.t('app.먼저_새_작품을_만들어_주세요'));

  if (options.parentSceneId != null && options.parentSceneId !== "") {
    const parentSceneId = Number(options.parentSceneId);
    if (!Number.isFinite(parentSceneId) || parentSceneId <= 0) {
      return toast(i18n.t('app.상위_원고를_찾지_못했어요'));
    }
    const parentLabel = (typeof getSceneTitleById === "function" && getSceneTitleById(parentSceneId)) || i18n.t('app.선택한_원고');
    const title = await promptText({
      title: i18n.t('app.폴더_만들기'),
      message: `${i18n.t('app.parentLabel_원고_아래에_만들어집', {parentLabel: parentLabel})}`,
      label: i18n.t('app.폴더_이름'),
      defaultValue: i18n.t('app.새_폴더'),
      confirmLabel: i18n.t('app.만들기'),
    });
    if (title === null) return;
    await api(`/api/projects/${state.projectId}/chapters`, {
      method: "POST",
      body: JSON.stringify({
        title: title.trim() || i18n.t('app.새_폴더'),
        parent_scene_id: parentSceneId,
      }),
    });
    noteFolderUndoAvailable();
    setSceneCollapsed(parentSceneId, false);
    const hostChapterId = findChapterIdForScene(parentSceneId);
    if (hostChapterId) setChapterCollapsed(hostChapterId, false);
    await loadProject();
    toast(i18n.t('app.원고_아래_폴더를_만들었어요'));
    return;
  }

  const explicitPart = Object.prototype.hasOwnProperty.call(options, "partId");
  const partId = explicitPart
    ? (options.partId == null || options.partId === "" ? null : Number(options.partId))
    : (pendingChapterInsert ? pendingChapterInsert.partId : null);

  const insertIndex = options.insertIndex != null
    ? Number(options.insertIndex)
    : (pendingChapterInsert ? Number(pendingChapterInsert.index) : null);
  const placed = insertIndex != null && Number.isFinite(insertIndex);
  const partTitle = partId != null
    ? (state.parts || []).find((p) => Number(p.id) === partId)?.title
    : null;

  // Drag/click insert into a known group (including ungrouped = partId null with placed)
  if (placed || (explicitPart && partId != null)) {
    const position = describeChapterInsertTarget({ partId, index: insertIndex });
    const placeHint = placed
      ? i18n.t('app.위치_describeChapterInsert', { position: position })
      : i18n.t('app.폴더_partTitle_안에_추가됩니다', {'partTitle || ""': partTitle || ""});
    const title = await promptText({
      title: i18n.t('app.폴더_만들기'),
      message: placeHint,
      label: i18n.t('app.폴더_이름'),
      defaultValue: i18n.t('app.새_폴더'),
      confirmLabel: i18n.t('app.만들기'),
    });
    if (title === null) return;
    const body = { title: title.trim() || i18n.t('app.새_폴더') };
    if (partId != null) body.part_id = partId;
    if (placed) body.insert_index = insertIndex;
    await api(`/api/projects/${state.projectId}/chapters`, {
      method: "POST",
      body: JSON.stringify(body),
    });
    noteFolderUndoAvailable();
    if (partId != null) setPartCollapsed(partId, false);
    clearChapterInsertTarget();
    await loadProject();
    toast(partId != null
      ? `${i18n.t('app.partTitle_폴더_안에_폴더를_넣었어', {'partTitle || "폴더"': partTitle || "폴더"})}`
      : i18n.t('app.선택한_위치에_폴더를_넣었어요'));
    const groupLen = chaptersInInsertGroup(partId).length;
    if (groupLen >= 2) {
      openRenumberChaptersModal(
        i18n.t('app.목록_번호를_재정렬_하시겠습니까_br')
        + i18n.t('app.중간에_폴더를_넣었으므로_현재_바인더_순서대'),
      );
    }
    return;
  }

  // Root +폴더: 원고를 담는 폴더 하나만 만든다 (상위 상자+하위 폴더 이중 생성 금지).
  const existingFolderCount = shouldUseFoldersOutline()
    ? (state.folders || []).length
    : ((state.parts || []).length || (state.ungroupedChapters || []).length || (state.outline || []).length);
  const n = existingFolderCount + 1;
  const defaultTitle = `${i18n.t('app.n_장', {n: n})}`;
  const title = await promptText({
    title: i18n.t('app.폴더_만들기'),
    message: i18n.t('app.상위_폴더_상자가_만들어지고_그_안에_원고를'),
    label: i18n.t('app.폴더_이름'),
    defaultValue: defaultTitle,
    confirmLabel: i18n.t('app.만들기'),
  });
  if (title === null) return;
  const name = title.trim() || defaultTitle;
  await api(`/api/projects/${state.projectId}/chapters`, {
    method: "POST",
    body: JSON.stringify({ title: name }),
  });
  noteFolderUndoAvailable();
  clearChapterInsertTarget();
  await loadProject();
  toast(`${i18n.t('app.name_폴더를_만들었어요_옆_로_원고를', {name: name})}`);
}

/** Wrap an existing sub-folder into a new top-level folder box. */
async function createPart(options = {}) {
  if (!state.projectId) return toast(i18n.t('app.먼저_새_작품을_만들어_주세요'));
  const chapterId = options.chapterId != null ? Number(options.chapterId) : null;
  const n = (state.parts || []).length + 1;
  const defaultTitle = `${i18n.t('app.n_장', {n: n})}`;
  const hint = chapterId
    ? i18n.t('app.이_폴더를_새_상위_폴더_상자_안으로_넣습니')
    : i18n.t('app.여러_하위_폴더를_묶는_상위_폴더_상자입니다');
  const chosen = await promptText({
    title: i18n.t('app.상위_폴더_만들기'),
    message: hint,
    label: i18n.t('app.상위_폴더_이름'),
    defaultValue: defaultTitle,
    confirmLabel: i18n.t('app.만들기'),
  });
  if (chosen === null) return;
  const title = chosen.trim() || defaultTitle;
  const body = { title };
  if (chapterId) body.chapter_id = chapterId;
  const result = await api(`/api/projects/${state.projectId}/parts`, {
    method: "POST",
    body: JSON.stringify(body),
  });
  // Policy A: create+chapter move does not log folder.create on server
  if (!chapterId) noteFolderUndoAvailable();
  await loadProject();
  toast(chapterId
    ? `${i18n.t('app.result_title_title_상자를', {'result.title || title': result.title || title})}`
    : `${i18n.t('app.result_title_title_상위_폴', {'result.title || title': result.title || title})}`);
}

async function moveChapterToPart(chapterId, currentPartId = null) {
  const id = Number(chapterId);
  if (!id) return;
  const parts = state.parts || [];
  if (!parts.length) {
    const make = window.confirm(
      i18n.t('app.아직_상위_폴더가_없어요_지금_만들고_이_폴'),
    );
    if (!make) return;
    await createPart({ chapterId: id });
    return;
  }
  const lines = [
    i18n.t('app.옮길_상위_폴더를_숫자로_고르세요'),
    i18n.t('app.0_미분류_상위_폴더_밖'),
    ...parts.map((p, i) => `${i + 1} = ${p.title}`),
  ];
  const current = currentPartId != null
    ? (parts.findIndex((p) => Number(p.id) === Number(currentPartId)) + 1)
    : 0;
  const pick = await promptText({
    title: i18n.t('app.상위_폴더로_옮기기'),
    message: lines.join("\n"),
    label: i18n.t('app.번호'),
    defaultValue: String(current >= 0 ? current : 0),
    confirmLabel: i18n.t('app.옮기기'),
  });
  if (pick === null) return;
  const n = Number(String(pick).trim());
  if (!Number.isFinite(n) || n < 0 || n > parts.length) {
    toast(i18n.t('app.올바른_번호를_입력해_주세요'));
    return;
  }
  const targetPartId = n === 0 ? null : parts[n - 1].id;
  const result = await api(`/api/chapters/${id}/move`, {
    method: "POST",
    body: JSON.stringify({ part_id: targetPartId }),
  });
  await loadProject();
  if (!result.moved) {
    toast(i18n.t('app.이미_그_위치에_있어요'));
    return;
  }
  const dest = targetPartId == null
    ? i18n.t('app.미분류')
    : (parts.find((p) => Number(p.id) === Number(targetPartId))?.title || i18n.t('app.상위_폴더'));
  toast(`${i18n.t('app.result_title_폴더_를_dest', {'result.title || "폴더"': result.title || "폴더", dest: dest})}`);
}

async function trashPart(partId, partTitle = "") {
  const id = Number(partId);
  if (!id) return;
  const part = (state.parts || []).find((p) => Number(p.id) === id);
  let label = String(partTitle || part?.title || i18n.t('app.이_폴더')).trim() || i18n.t('app.이_폴더');
  const chapterCount = (part?.chapters || []).length;
  const sceneCount = (part?.chapters || []).reduce(
    (sum, ch) => sum + flattenChapterScenes(ch).length,
    0,
  );
  const ok = window.confirm(
    chapterCount > 0
      ? `${i18n.t('app.label_상위_폴더와_안의_하위_폴더_c', {label: label, chapterCount: chapterCount})}` +
        (sceneCount ? ` (원고 ${sceneCount}개)` : "") +
        i18n.t('app.를_휴지통에_버리시겠습니까_안의_원고도_함께')
      : `${i18n.t('app.label_상위_폴더를_휴지통에_버리시겠습', {label: label})}`,
  );
  if (!ok) return;
  const result = await api(`/api/parts/${id}/trash`, {
    method: "POST",
    body: JSON.stringify({}),
  });
  noteFolderUndoAvailable();
  await loadProject();
  const n = Number(result?.chapter_count ?? chapterCount ?? 0);
  toast(n > 0
    ? `${i18n.t('app.label_폴더와_하위_n_개를_휴지통으로', {label: label, n: n})}`
    : `${i18n.t('app.label_폴더를_휴지통으로_옮겼어요', {label: label})}`);
}

async function beginPartRename(titleButton) {
  const partId = Number(titleButton.dataset.renamePart);
  if (!partId) return;
  const section = titleButton.closest(".outline-part");
  const row = titleButton.closest(".part-row");
  if (!row || row.querySelector(".chapter-rename-input")) return;
  const original = (state.parts || []).find((p) => Number(p.id) === partId)?.title
    || titleButton.textContent
    || "";
  const input = document.createElement("input");
  input.type = "text";
  input.className = "chapter-rename-input part-rename-input";
  input.value = original;
  input.setAttribute("aria-label", i18n.t('app.권_부_이름_수정'));
  input.maxLength = 200;
  titleButton.replaceWith(input);
  input.focus();
  input.select();
  if (section) section.draggable = false;
  let finished = false;
  const finish = async (save) => {
    if (finished) return;
    finished = true;
    const nextTitle = input.value.trim();
    if (section) section.draggable = true;
    if (!save || !nextTitle || nextTitle === original) {
      await loadProject();
      return;
    }
    try {
      await api(`/api/parts/${partId}`, {
        method: "PUT",
        body: JSON.stringify({ title: nextTitle }),
      });
      noteFolderUndoAvailable();
      await loadProject();
      toast(i18n.t('app.권_부_이름을_바꿨어요'));
    } catch (error) {
      await loadProject();
      throw error;
    }
  };
  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      finish(true).catch(handleError);
    } else if (event.key === "Escape") {
      event.preventDefault();
      finish(false).catch(handleError);
    }
  });
  input.addEventListener("blur", () => finish(true).catch(handleError));
  input.addEventListener("mousedown", (event) => event.stopPropagation());
  input.addEventListener("click", (event) => event.stopPropagation());
}

async function createScene(chapterId, options = {}) {
  const afterSceneId = options.afterSceneId != null && options.afterSceneId !== ""
    ? Number(options.afterSceneId)
    : null;
  // afterSceneId: 같은 상위 아래(형제)로 만들고 기준 원고 바로 아래에 배치
  // parentSceneId only: 그 원고의 하위로 만들기
  let parentSceneId = options.parentSceneId != null && options.parentSceneId !== ""
    ? Number(options.parentSceneId)
    : null;
  if (afterSceneId && options.parentSceneId === undefined) {
    // 미지정 시 기준 원고의 상위와 맞춤
    const anchor = findSceneNodeById(afterSceneId);
    const rawParent = anchor?.parent_scene_id ?? anchor?.parentSceneId;
    parentSceneId = rawParent != null && rawParent !== "" ? Number(rawParent) : null;
    if (!Number.isFinite(parentSceneId)) parentSceneId = null;
  }
  if (afterSceneId && !Number.isFinite(parentSceneId)) parentSceneId = null;

  const isAfter = Boolean(afterSceneId);
  const isChild = !isAfter && Boolean(parentSceneId);
  const defaultTitle = isChild ? i18n.t('app.새_하위_원고') : i18n.t('app.새_씬');
  const body = { title: defaultTitle };
  if (parentSceneId) body.parent_scene_id = parentSceneId;
  const scene = await api(`/api/chapters/${chapterId}/scenes`, {
    method: "POST",
    body: JSON.stringify(body),
  });
  // 기본은 목록 끝 → 기준 원고 바로 아래로 이동
  if (isAfter && scene?.id) {
    try {
      await api(`/api/scenes/${scene.id}/move`, {
        method: "POST",
        body: JSON.stringify({ after_scene_id: afterSceneId }),
      });
    } catch (_) {
      /* 생성은 됐으니 끝 위치여도 열기 */
    }
  }
  if (parentSceneId) setSceneCollapsed(parentSceneId, false);
  setChapterCollapsed(chapterId, false);
  await loadProject();
  if (scene?.id) {
    await openScene(scene.id, { skipOutlineReload: true, skipEditorFocus: true });
    requestAnimationFrame(() => startRenameScene(scene.id));
  }
}

// ── 토리의 첫 문장 힌트 (새글쓰기 오프닝 도우미) ──────────────────────────
const DEFAULT_SCENE_PLACEHOLDER =
  i18n.t('app.여기에_글을_쓰세요_글은_이_컴퓨터에_저장됩');
const OPENING_HINT_PLACEHOLDER = i18n.t('app.토리가_작가님의_첫_문장을_기다리고_있어요');
const OPENING_HINT_DELAY_MS = 30000;
let openingHintTimer = null;

function disarmOpeningHintTimer() {
  if (openingHintTimer) {
    window.clearTimeout(openingHintTimer);
    openingHintTimer = null;
  }
}

function armOpeningHintTimer(sceneId) {
  disarmOpeningHintTimer();
  openingHintTimer = window.setTimeout(() => {
    openingHintTimer = null;
    if (state.sceneId === sceneId && state.freshOpeningSceneId === sceneId) {
      showOpeningHintButton();
    }
  }, OPENING_HINT_DELAY_MS);
}

function showOpeningHintButton() {
  $("toryOpeningHintButton")?.classList.remove("hidden");
}

function hideOpeningHintButton() {
  $("toryOpeningHintButton")?.classList.add("hidden");
}

/** 씬을 열 때마다 호출 — 방금 새글쓰기로 만든 1화면 오프닝 힌트를 걸고, 아니면 해제. */
function syncOpeningHintForScene(sceneId) {
  const editorEl = $("sceneContent");
  let isFresh = state.freshOpeningSceneId != null && sceneId === state.freshOpeningSceneId;
  // 다른 경로(동기화, 로컬 임시본 복원 등)로 이미 내용이 생겼다면 더는 "오프닝 대기" 상태가 아님.
  if (isFresh && editorEl) {
    const isEmpty = !plainTextFromHtml(editorEl.innerHTML) && !editorEl.querySelector("img");
    if (!isEmpty) {
      isFresh = false;
      setFreshOpeningSceneId(null);
    }
  }
  if (editorEl) {
    editorEl.dataset.placeholder = isFresh ? OPENING_HINT_PLACEHOLDER : DEFAULT_SCENE_PLACEHOLDER;
    if (typeof updateEditorPlaceholder === "function") updateEditorPlaceholder(editorEl);
  }
  if (isFresh) {
    armOpeningHintTimer(sceneId);
  } else {
    disarmOpeningHintTimer();
    hideOpeningHintButton();
  }
}

/** 오프닝 힌트 버튼 클릭, 그리고 입력 시작 시 타이머를 완전히 해제하는 리스너를 등록. */
function setupOpeningHintUi() {
  $("sceneContent")?.addEventListener("input", () => {
    if (state.freshOpeningSceneId != null && state.sceneId === state.freshOpeningSceneId) {
      disarmOpeningHintTimer();
      hideOpeningHintButton();
      // 스펙: "타이머 초기화/비활성화" — 재시작이 아니라 이 씬에서는 다시는 뜨지 않도록 해제.
      setFreshOpeningSceneId(null);
      const editorEl = $("sceneContent");
      if (editorEl) editorEl.dataset.placeholder = DEFAULT_SCENE_PLACEHOLDER;
    }
  });
  $("toryOpeningHintButton")?.addEventListener("click", () => {
    openOpeningIdeasModal().catch(handleError);
  });
}

