/** ```json 코드블록으로 감싸져 오더라도 첫 { ~ 마지막 } 구간만 뽑아낸다. */
function extractJsonObjectText(text) {
  const source = String(text || "");
  const fenced = source.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const body = fenced ? fenced[1] : source;
  const start = body.indexOf("{");
  const end = body.lastIndexOf("}");
  if (start === -1 || end === -1 || end < start) return null;
  return body.slice(start, end + 1);
}

/** AI JSON 응답에서 notice 문구와 6개 오프닝(type/label/text)을 뽑아낸다. */
function parseOpeningIdeas(text) {
  const jsonText = extractJsonObjectText(text);
  if (!jsonText) return { notice: "", items: [] };
  let data;
  try {
    data = JSON.parse(jsonText);
  } catch (_) {
    return { notice: "", items: [] };
  }
  const notice = String(data?.notice || "").trim();
  const raw = Array.isArray(data?.openings) ? data.openings : [];
  const items = raw
    .map((item) => ({
      type: String(item?.type || "").trim(),
      label: String(item?.label || "").trim(),
      text: String(item?.text || "").trim(),
    }))
    .filter((item) => OPENING_IDEA_TYPES.includes(item.type) && item.text);
  return { notice, items };
}

async function fetchOpeningIdeas() {
  let result;
  try {
    // 서버는 mode:"free"일 때 user_prompt/prompt가 비어 있으면 indexed_prompt를 보기도
    // 전에 거부한다("AI에게 요청할 내용을 적어 주세요.") — 다른 free 호출부들처럼 둘 다 채워 보낸다.
    const prompt = buildOpeningIdeaPrompt();
    result = await api("/api/ai/assist", {
      method: "POST",
      body: JSON.stringify({
        mode: "free",
        prompt,
        indexed_prompt: prompt,
        project_id: state.projectId,
        ...buildToryProjectContextPayload(),
      }),
    });
  } catch (error) {
    throw toAiAssistError(error);
  }
  const ideas = parseOpeningIdeas(result?.text || "");
  if (!ideas.items.length) {
    const err = new Error(AI_ASSIST_ERR_GENERIC);
    err.aiAssist = true;
    throw err;
  }
  return ideas;
}

function renderOpeningIdeas(ideas) {
  $("toryOpeningIdeasStatus")?.classList.add("hidden");
  $("toryOpeningIdeasRetryButton")?.classList.add("hidden");
  const grid = $("toryOpeningIdeasGrid");
  if (grid) {
    grid.innerHTML = ideas.items.map((item) => `
      <button type="button" class="tory-idea-card" data-opening-idea-type="${escapeHtml(item.type)}">
        <span class="tory-idea-card-label">${escapeHtml(item.label || item.type)}</span>
        <span class="tory-idea-card-text">${escapeHtml(item.text)}</span>
      </button>`).join("");
    grid.classList.remove("hidden");
  }
  const notice = $("toryOpeningIdeasNotice");
  if (notice) {
    if (ideas.notice) {
      notice.textContent = ideas.notice;
      notice.classList.remove("hidden");
    } else {
      notice.classList.add("hidden");
    }
  }
}

function showOpeningIdeasStatus(message) {
  const status = $("toryOpeningIdeasStatus");
  if (status) {
    status.textContent = message;
    status.classList.remove("hidden");
  }
  $("toryOpeningIdeasGrid")?.classList.add("hidden");
  $("toryOpeningIdeasNotice")?.classList.add("hidden");
}

async function loadOpeningIdeasIntoModal() {
  showOpeningIdeasStatus(i18n.t('app.토리가_첫_문장을_고민하고_있어요'));
  $("toryOpeningIdeasRetryButton")?.classList.add("hidden");
  try {
    const ideas = await fetchOpeningIdeas();
    renderOpeningIdeas(ideas);
  } catch (error) {
    handleAiAssistError(error);
    showOpeningIdeasStatus(i18n.t('app.문장을_만들지_못했어요_다시_시도해_주세요'));
    $("toryOpeningIdeasRetryButton")?.classList.remove("hidden");
  }
}

async function openOpeningIdeasModal() {
  $("toryOpeningIdeasModal")?.classList.remove("hidden");
  await loadOpeningIdeasIntoModal();
}

function closeOpeningIdeasModal() {
  $("toryOpeningIdeasModal")?.classList.add("hidden");
}

/** 고른 오프닝 문장을 원고 첫 줄에 넣고 커서를 끝으로 옮긴 뒤, 모달·힌트 버튼을 모두 정리. */
function applyOpeningIdea(sentence) {
  const editor = $("sceneContent");
  if (!editor || !sentence) return;
  setEditorContent(sentence, editor);
  const range = document.createRange();
  range.selectNodeContents(editor);
  range.collapse(false);
  const sel = window.getSelection();
  sel.removeAllRanges();
  sel.addRange(range);
  editor.focus();
  closeOpeningIdeasModal();
  disarmOpeningHintTimer();
  hideOpeningHintButton();
  setFreshOpeningSceneId(null);
  editor.dataset.placeholder = DEFAULT_SCENE_PLACEHOLDER;
  // 기존 dirty-flag/자동저장 로직에 그대로 편승.
  editor.dispatchEvent(new Event("input", { bubbles: true }));
}

function setupOpeningIdeasModal() {
  document.querySelectorAll("[data-close-opening-ideas]").forEach((el) => {
    el.addEventListener("click", closeOpeningIdeasModal);
  });
  $("toryOpeningIdeasRetryButton")?.addEventListener("click", () => {
    loadOpeningIdeasIntoModal().catch(handleAiAssistError);
  });
  // 카드가 AI 응답마다 새로 그려지므로(동적 라벨/문장) 위임 방식으로 클릭을 받는다.
  $("toryOpeningIdeasGrid")?.addEventListener("click", (event) => {
    const card = event.target.closest("[data-opening-idea-type]");
    if (!card) return;
    const text = card.querySelector(".tory-idea-card-text")?.textContent || "";
    applyOpeningIdea(text.trim());
  });
}

/* —— 회차별 소제목 추천 (chapter_subtitles) —————————————————————— */

const CHAPTER_SUBTITLE_MIN_CHARS = 1200;
const CHAPTER_SUBTITLE_TOOLTIP_DISABLED = i18n.t('app.회차_본문이_1_200자_이상일_때_사용할');
const CHAPTER_SUBTITLE_TOOLTIP_ENABLED = i18n.t('app.이번_회차_본문을_분석해_소제목_4가지를_추');

/**
 * 기존 제목 맨 앞의 회차 번호 표기만 프리픽스로 인식한다. 우선순위 순서 그대로 검사 —
 * "36화. "(마침표 포함)가 "36화 "(공백만)보다 먼저 매치돼야 마침표까지 프리픽스에 포함된다.
 * 숫자 회차 표기 외에 프롤로그/에필로그/외전(번호가 붙는 경우 포함)도 동일하게 보존한다.
 */
const CHAPTER_SUBTITLE_PREFIX_PATTERNS = [
  // 숫자 회차 표기
  /^\d+화\.\s*/,   // i18n.t('app.36화')
  /^\d+화\s*/,     // i18n.t('app.36화_2') / i18n.t('app.36화_2')
  /^\d+\.\s*/,     // "36. "
  /^\d+\)\s*/,     // "36) "
  /^\d+\s+/,       // "36 "  (숫자+공백만, 최후순위)
  // 프롤로그 / 에필로그 / 외전 — 번호가 붙는 경우("외전 3화. ")를 먼저 검사
  /^(?:프롤로그|에필로그|외전)\s*\d+화\.\s*/,  // i18n.t('app.외전_3화')
  /^(?:프롤로그|에필로그|외전)\s*\d+화\s*/,    // i18n.t('app.외전_3화_2') / i18n.t('app.외전_3화_2')
  /^(?:프롤로그|에필로그|외전)\s*\d+\.\s*/,    // i18n.t('app.외전_3')
  /^(?:프롤로그|에필로그|외전)\s*\d+\)\s*/,    // i18n.t('app.외전_3_2')
  /^(?:프롤로그|에필로그|외전)\.\s*/,          // i18n.t('app.프롤로그')
  /^(?:프롤로그|에필로그|외전)\)\s*/,          // i18n.t('app.프롤로그_2')
  /^(?:프롤로그|에필로그|외전)\s+/,            // i18n.t('app.프롤로그_3')  (공백만, 최후순위)
];

function splitChapterSubtitlePrefix(title) {
  const source = String(title || "");
  for (const pattern of CHAPTER_SUBTITLE_PREFIX_PATTERNS) {
    const match = source.match(pattern);
    if (match) return match[0];
  }
  return "";
}

/** 실시간 글자 수(공백 포함) 재사용 — updateSceneStats()가 이미 계산한 값을 넘겨받는다. */
function updateChapterSubtitleButtonState(charsWithSpace) {
  const button = $("chapterSubtitleSuggestButton");
  if (!button) return;
  const chars = Number.isFinite(charsWithSpace)
    ? charsWithSpace
    : computeTextStats(getEditorPlainText()).chars_with_space;
  const ready = chars >= CHAPTER_SUBTITLE_MIN_CHARS;
  button.disabled = !ready;
  button.title = ready ? CHAPTER_SUBTITLE_TOOLTIP_ENABLED : CHAPTER_SUBTITLE_TOOLTIP_DISABLED;
}

/** AI JSON 응답에서 소제목 4종(type/label/text/reason)을 뽑아낸다. 순서는 응답 그대로 유지. */
function parseChapterSubtitles(text) {
  const jsonText = extractJsonObjectText(text);
  if (!jsonText) return [];
  let data;
  try {
    data = JSON.parse(jsonText);
  } catch (_) {
    return [];
  }
  const raw = Array.isArray(data?.subtitles) ? data.subtitles : [];
  return raw
    .map((item) => ({
      type: String(item?.type || "").trim(),
      label: String(item?.label || "").trim(),
      text: String(item?.text || "").trim(),
      reason: String(item?.reason || "").trim(),
    }))
    .filter((item) => item.text);
}

async function fetchChapterSubtitles() {
  const episodeContent = getEditorPlainText();
  let result;
  try {
    result = await api("/api/ai/assist", {
      method: "POST",
      body: JSON.stringify({
        mode: "chapter_subtitles",
        episode_content: episodeContent,
        project_id: state.projectId,
        ...buildToryProjectContextPayload(),
      }),
    });
  } catch (error) {
    throw error; // api()가 /api/ai/assist 호출은 이미 aiAssist 에러로 감싸서 던짐
  }
  const items = parseChapterSubtitles(result?.text || "");
  if (!items.length) {
    const err = new Error(AI_ASSIST_ERR_GENERIC);
    err.aiAssist = true;
    throw err;
  }
  return items;
}

function renderChapterSubtitles(items) {
  $("chapterSubtitleStatus")?.classList.add("hidden");
  $("chapterSubtitleRetryButton")?.classList.add("hidden");
  const grid = $("chapterSubtitleGrid");
  if (grid) {
    grid.innerHTML = items.map((item, index) => `
      <div class="chapter-subtitle-card" data-chapter-subtitle-index="${index}">
        <span class="chapter-subtitle-card-label">${escapeHtml(item.label || item.type)}</span>
        <span class="chapter-subtitle-card-text">${escapeHtml(item.text)}</span>
        <span class="chapter-subtitle-card-reason">${escapeHtml(item.reason)}</span>
        <div class="chapter-subtitle-card-actions">
          <button type="button" class="secondary compact-btn" data-chapter-subtitle-apply>바로 적용</button>
          <button type="button" class="secondary compact-btn" data-chapter-subtitle-copy>복사하기</button>
        </div>
      </div>`).join("");
    grid.classList.remove("hidden");
  }
}

function showChapterSubtitleStatus(message) {
  const status = $("chapterSubtitleStatus");
  if (status) {
    status.textContent = message;
    status.classList.remove("hidden");
  }
  $("chapterSubtitleGrid")?.classList.add("hidden");
}

/** api()가 /api/ai/assist 실패를 이미 친근한 문구로 감싸지만, 원래 서버 메시지는
 * error.cause.message에 그대로 남아 있다(app.js toAiAssistError 참고). 네트워크/서버
 * 오류는 일반 안내 토스트로, 그 외(1,200자 미만 등 백엔드 검증 실패)는 서버 메시지를
 * 그대로 보여준다. */
function showChapterSubtitleError(error) {
  console.error(error);
  const wrapped = error?.aiAssist ? error : toAiAssistError(error);
  if (wrapped.isNetwork || wrapped.offlineSafe) {
    toast(i18n.t('app.잠시_후_다시_시도해주세요'), 4200);
    return;
  }
  const raw = String(wrapped.cause?.message || wrapped.message || AI_ASSIST_ERR_GENERIC).trim();
  toast(raw || AI_ASSIST_ERR_GENERIC, 4200);
}

async function loadChapterSubtitlesIntoModal() {
  showChapterSubtitleStatus(i18n.t('app.토리가_소제목을_고민하고_있어요'));
  $("chapterSubtitleRetryButton")?.classList.add("hidden");
  try {
    const items = await fetchChapterSubtitles();
    renderChapterSubtitles(items);
  } catch (error) {
    showChapterSubtitleError(error);
    closeChapterSubtitleModal();
  }
}

async function openChapterSubtitleModal() {
  const button = $("chapterSubtitleSuggestButton");
  if (button?.disabled) return; // 방어적 처리 — 버튼이 비활성화면 호출 자체를 막는다
  $("chapterSubtitleModal")?.classList.remove("hidden");
  await loadChapterSubtitlesIntoModal();
}

function closeChapterSubtitleModal() {
  $("chapterSubtitleModal")?.classList.add("hidden");
}

/** 기존 제목의 회차 번호 프리픽스만 남기고 뒤 텍스트를 새 소제목으로 교체해 적용한다. */
function applyChapterSubtitleToTitle(subtitleText) {
  const titleInput = $("sceneTitle");
  if (!titleInput || !subtitleText) return;
  const oldTitle = titleInput.value || "";
  const prefix = splitChapterSubtitlePrefix(oldTitle);
  titleInput.value = prefix + subtitleText;
  // 기존 dirty-flag/자동저장·바인더 동기화 로직에 그대로 편승 (applyOpeningIdea와 동일 패턴).
  titleInput.dispatchEvent(new Event("change", { bubbles: true }));
  if (state.sceneId) markSceneDirty();
  closeChapterSubtitleModal();
  toast(i18n.t('app.소제목이_적용됐어요'));
}

async function copyChapterSubtitleText(subtitleText) {
  try {
    await navigator.clipboard.writeText(subtitleText);
    toast(i18n.t('app.복사했어요_2'));
  } catch (_) {
    toast(i18n.t('app.복사에_실패했어요_직접_선택해서_복사해_주세'));
  }
}

function setupChapterSubtitleModal() {
  $("chapterSubtitleSuggestButton")?.addEventListener("click", () => {
    openChapterSubtitleModal().catch((error) => showChapterSubtitleError(error));
  });
  document.querySelectorAll("[data-close-chapter-subtitle]").forEach((el) => {
    el.addEventListener("click", closeChapterSubtitleModal);
  });
  $("chapterSubtitleRetryButton")?.addEventListener("click", () => {
    loadChapterSubtitlesIntoModal().catch((error) => showChapterSubtitleError(error));
  });
  // 카드가 응답마다 새로 그려지므로 위임 방식으로 클릭을 받는다.
  $("chapterSubtitleGrid")?.addEventListener("click", (event) => {
    const card = event.target.closest(".chapter-subtitle-card");
    if (!card) return;
    const text = card.querySelector(".chapter-subtitle-card-text")?.textContent || "";
    if (event.target.closest("[data-chapter-subtitle-apply]")) {
      applyChapterSubtitleToTitle(text.trim());
    } else if (event.target.closest("[data-chapter-subtitle-copy]")) {
      copyChapterSubtitleText(text.trim());
    }
  });
}

/**
 * "새글쓰기" 직후 기본 트리(1권 > 1부 > 1화. 본문제목)를 프롬프트 없이 조용히 만들고
 * 곧바로 에디터를 연다. part/chapter/scene 각각 기존 엔드포인트를 그대로 사용.
 * 실패해도 프로젝트 생성 자체는 이미 끝난 상태이므로 호출측에서 catch로 감싼다.
 */
async function createDefaultOpeningStructure() {
  if (!state.projectId) return null;
  const part = await api(`/api/projects/${state.projectId}/parts`, {
    method: "POST",
    body: JSON.stringify({ title: i18n.t('app.1권') }),
  });
  const chapter = await api(`/api/projects/${state.projectId}/chapters`, {
    method: "POST",
    body: JSON.stringify({ title: i18n.t('app.1부'), part_id: part.id }),
  });
  const scene = await api(`/api/chapters/${chapter.id}/scenes`, {
    method: "POST",
    body: JSON.stringify({ title: i18n.t('app.1화_본문제목') }),
  });
  setFreshOpeningSceneId(scene.id);
  await loadProject();
  await openScene(scene.id);
  return scene.id;
}

async function reparentScene(sceneId, parentSceneId) {
  return moveScene(sceneId, {
    parent_scene_id: parentSceneId == null || parentSceneId === ""
      ? null
      : Number(parentSceneId),
  });
}

async function moveScene(sceneId, payload = {}) {
  const id = Number(sceneId);
  if (!id) return null;
  const body = { ...payload };
  const result = await api(`/api/scenes/${id}/move`, {
    method: "POST",
    body: JSON.stringify(body),
  });
  if (body.parent_scene_id) setSceneCollapsed(body.parent_scene_id, false);
  if (body.chapter_id) setChapterCollapsed(body.chapter_id, false);
  await loadProject();
  if (!result?.moved) {
    toast(i18n.t('app.이미_그_위치에_있어요'));
    return result;
  }
  const title = result.title || i18n.t('app.원고');
  if (result.parent_scene_id) {
    toast(`${i18n.t('app.title_를_하위_원고로_옮겼어요', {title: title})}`);
  } else {
    toast(`${i18n.t('app.title_위치를_바꿨어요', {title: title})}`);
  }
  return result;
}

/** Global state for manuscript drag-move (survives re-renders). */
let sceneNestDragId = null;

function clearSceneNestDropUi(outline = $("outline")) {
  outline?.querySelectorAll(
    ".scene-link.is-drop-target, .scene-link.is-drop-before, .scene-link.is-drop-after, "
    + ".scene-tree-item.is-dragging-scene, .chapter-children.is-scene-drop, "
    + ".part-children.is-scene-drop, .outline-chapter.is-scene-drop, .outline-part.is-scene-drop",
  ).forEach((el) => {
    el.classList.remove(
      "is-drop-target",
      "is-drop-before",
      "is-drop-after",
      "is-dragging-scene",
      "is-scene-drop",
    );
  });
}

function collectSceneDescendantIds(rootId) {
  const root = Number(rootId);
  const out = new Set();
  if (!root) return out;
  const walk = (nodes) => {
    for (const scene of nodes || []) {
      const sid = Number(scene.id);
      if (sid === root) {
        const stack = [...(scene.children || [])];
        while (stack.length) {
          const cur = stack.pop();
          const cid = Number(cur.id);
          if (!cid || out.has(cid)) continue;
          out.add(cid);
          for (const ch of cur.children || []) stack.push(ch);
        }
        return true;
      }
      if (walk(scene.children || [])) return true;
    }
    return false;
  };
  const walkFolders = (nodes) => {
    for (const node of nodes || []) {
      if (walk(node.scenes || [])) return true;
      if (walkFolders(node.children || node.child_folders || [])) return true;
    }
    return false;
  };
  if (walkFolders(state.folders || [])) return out;
  for (const chapter of getBinderChaptersInOrder()) {
    if (walk(chapter.scenes || [])) break;
  }
  return out;
}

/** Chapter id that can receive manuscripts for an outline folder section. */
function childListOfOutlineSection(section) {
  return section?.querySelector?.(":scope > .chapter-children, :scope > .part-children") || null;
}

function sceneHostSectionForFolder(section) {
  if (!section) return null;
  const kids = childListOfOutlineSection(section);
  const transparent = kids?.querySelector?.(
    ":scope > .outline-chapter[data-transparent='true'], :scope > .outline-chapter.is-transparent-chapter",
  );
  if (transparent) return transparent;
  return section;
}

function partIdForOutlineFolderSection(section) {
  if (!section) return null;
  const isBox = section.dataset?.isBox === "1" || section.classList?.contains("outline-part");
  if (!isBox) return null;
  const raw = section.dataset.partId;
  if (raw === "" || raw == null) return null;
  const n = Number(raw);
  return Number.isFinite(n) && n > 0 ? n : null;
}

function chapterIdForOutlineFolderSection(section) {
  if (!section) return 0;
  const host = sceneHostSectionForFolder(section);
  const hostId = Number(host?.dataset?.chapterId);
  if (hostId) return hostId;
  const direct = Number(section.dataset.chapterId);
  if (direct) return direct;
  const kids = childListOfOutlineSection(section);
  const inner = kids?.querySelector?.(
    ":scope > .outline-chapter[data-chapter-id], :scope > .outline-part[data-chapter-id]",
  );
  if (inner) {
    const nested = Number(inner.dataset.chapterId);
    if (nested) return nested;
  }
  const sceneLink = host?.querySelector?.(":scope > .chapter-children > .scene-tree-item > .scene-row > .scene-link[data-chapter-id]")
    || section.querySelector(".scene-link[data-chapter-id]");
  return Number(sceneLink?.dataset?.chapterId) || 0;
}

function directSceneLinksInHost(host) {
  const children = childListOfOutlineSection(host);
  if (!children) return [];
  return [...children.querySelectorAll(
    ":scope > .scene-tree-item[data-depth=\"0\"] > .scene-row > .scene-link[data-scene]:not([data-pinned])",
  )];
}

function resolveFolderSectionSceneDrop(section, clientY, subtree) {
  const host = sceneHostSectionForFolder(section) || section;
  const fallbackChapterId = chapterIdForOutlineFolderSection(section);
  const partId = partIdForOutlineFolderSection(section) || partIdForOutlineFolderSection(host);
  if (!fallbackChapterId && !partId) return null;
  const children = childListOfOutlineSection(host);
  const childrenVisible = Boolean(
    children && !children.hidden && !children.classList.contains("is-collapsed"),
  );
  if (childrenVisible) {
    const sceneLinks = directSceneLinksInHost(host);
    if (sceneLinks.length) {
      let nearest = null;
      let best = Infinity;
      for (const sceneLink of sceneLinks) {
        const sid = Number(sceneLink.dataset.scene);
        if (!sid || subtree.has(sid)) continue;
        const rect = sceneLink.getBoundingClientRect();
        const mid = rect.top + rect.height / 2;
        const dist = Math.abs(clientY - mid);
        if (dist < best) {
          best = dist;
          nearest = { link: sceneLink, rect, sid };
        }
      }
      if (nearest) {
        const chapterId = Number(nearest.link.dataset.chapterId) || fallbackChapterId;
        if (clientY < nearest.rect.top + nearest.rect.height / 2) {
          return {
            mode: "before",
            chapterId,
            partId,
            parentSceneId: null,
            beforeSceneId: nearest.sid,
            el: nearest.link,
          };
        }
        return {
          mode: "after",
          chapterId,
          partId,
          parentSceneId: null,
          afterSceneId: nearest.sid,
          el: nearest.link,
        };
      }
    }
  }
  return {
    mode: "chapter-root",
    chapterId: fallbackChapterId,
    partId,
    parentSceneId: null,
    el: children || section,
  };
}

function resolveSceneMoveDrop(outline, clientX, clientY, eventTarget) {
  if (!sceneNestDragId || !outline) return null;
  const movingId = Number(sceneNestDragId);
  const subtree = collectSceneDescendantIds(movingId);
  subtree.add(movingId);

  const pinHost = eventTarget?.closest?.(".outline-pin-section");
  if (pinHost) return null;

  const link = eventTarget?.closest?.(".scene-link[data-scene]:not([data-pinned])");
  if (link && outline.contains(link)) {
    const targetId = Number(link.dataset.scene);
    if (!targetId || subtree.has(targetId)) return null;

    const rect = link.getBoundingClientRect();
    const ratio = (clientY - rect.top) / Math.max(rect.height, 1);
    const chapterId = Number(link.dataset.chapterId);
    if (!chapterId) return null;
    const parentRaw = link.dataset.parentScene;
    const parentOfTarget = parentRaw === "" || parentRaw == null ? null : Number(parentRaw);

    if (ratio < 0.28) {
      if (parentOfTarget != null && subtree.has(parentOfTarget)) return null;
      return {
        mode: "before",
        chapterId,
        parentSceneId: parentOfTarget,
        beforeSceneId: targetId,
        el: link,
      };
    }
    if (ratio > 0.72) {
      if (parentOfTarget != null && subtree.has(parentOfTarget)) return null;
      return {
        mode: "after",
        chapterId,
        parentSceneId: parentOfTarget,
        afterSceneId: targetId,
        el: link,
      };
    }
    return {
      mode: "nest",
      chapterId,
      parentSceneId: targetId,
      el: link,
    };
  }

  const folderSection = eventTarget?.closest?.(
    ".outline-chapter[data-chapter-id], .outline-part[data-chapter-id], .outline-part[data-part-id]",
  );
  if (folderSection && outline.contains(folderSection)) {
    return resolveFolderSectionSceneDrop(folderSection, clientY, subtree);
  }
  return null;
}

function applySceneMoveDropHint(outline, drop) {
  clearSceneNestDropUi(outline);
  if (!drop) return;
  const moving = outline.querySelector(`.scene-tree-item[data-scene-node="${sceneNestDragId}"]`);
  moving?.classList.add("is-dragging-scene");
  if (drop.mode === "before" && drop.el) {
    drop.el.classList.add("is-drop-before");
  } else if (drop.mode === "after" && drop.el) {
    drop.el.classList.add("is-drop-after");
  } else if (drop.mode === "nest" && drop.el) {
    drop.el.classList.add("is-drop-target");
  } else if (drop.mode === "chapter-root") {
    const section = drop.el?.closest?.(".outline-chapter, .outline-part") || drop.el;
    section?.classList.add("is-scene-drop");
    section?.querySelector?.(":scope > .chapter-children, :scope > .part-children")?.classList.add("is-scene-drop");
  }
}

function setupSceneNestDragAndDrop(outline) {
  if (!outline) return;
  // Bind once on #outline (delegation). Re-render keeps the same element.
  if (outline.dataset.sceneNestBound === "1") return;
  outline.dataset.sceneNestBound = "1";

  outline.addEventListener("dragstart", (event) => {
    if (event.target.closest?.("button.scene-twistie, button[data-toggle-scene], button.scene-add-btn, [data-add-after-scene], [data-add-child-scene]")) {
      event.preventDefault();
      return;
    }
    if (event.target.closest?.(".outline-pin-section")) {
      event.preventDefault();
      return;
    }
    const item = event.target.closest?.(".scene-tree-item[data-scene-node]");
    if (!item || !outline.contains(item)) return;
    if (event.target.closest?.(".chapter-row, .part-row")) return;

    const id = Number(item.dataset.sceneNode);
    if (!id) return;

    // Capture before any parent chapter/part handler sees this.
    event.stopPropagation();
    sceneNestDragId = id;
    item.classList.add("is-dragging-scene");
    event.dataTransfer.effectAllowed = "move";
    try {
      event.dataTransfer.setData("text/plain", `scene:${id}`);
      event.dataTransfer.setData("application/x-supertory-scene", String(id));
    } catch (_) { /* ignore */ }
  }, true); // capture phase so chapter dragstart never kills this

  outline.addEventListener("dragend", () => {
    clearSceneNestDropUi(outline);
    sceneNestDragId = null;
  }, true);

  outline.addEventListener("dragover", (event) => {
    if (!sceneNestDragId) return;
    const drop = resolveSceneMoveDrop(outline, event.clientX, event.clientY, event.target);
    if (!drop) return;
    event.preventDefault();
    event.stopPropagation();
    try { event.dataTransfer.dropEffect = "move"; } catch (_) { /* ignore */ }
    applySceneMoveDropHint(outline, drop);
  }, true);

  outline.addEventListener("dragleave", (event) => {
    if (!sceneNestDragId) return;
    const related = event.relatedTarget;
    if (related && outline.contains(related)) return;
    clearSceneNestDropUi(outline);
    const moving = outline.querySelector(`.scene-tree-item[data-scene-node="${sceneNestDragId}"]`);
    moving?.classList.add("is-dragging-scene");
  }, true);

  outline.addEventListener("drop", (event) => {
    if (!sceneNestDragId) return;
    const drop = resolveSceneMoveDrop(outline, event.clientX, event.clientY, event.target);
    event.preventDefault();
    event.stopPropagation();
    clearSceneNestDropUi(outline);
    const movingId = sceneNestDragId;
    sceneNestDragId = null;
    if (!drop || !movingId) return;

    const payload = {
      parent_scene_id: drop.parentSceneId == null ? null : Number(drop.parentSceneId),
    };
    if (Number(drop.chapterId) > 0) payload.chapter_id = Number(drop.chapterId);
    if (Number(drop.partId) > 0) payload.part_id = Number(drop.partId);
    if (drop.mode === "before" && drop.beforeSceneId) {
      payload.before_scene_id = Number(drop.beforeSceneId);
    } else if (drop.mode === "after" && drop.afterSceneId) {
      payload.after_scene_id = Number(drop.afterSceneId);
    }
    if (!payload.chapter_id && !payload.part_id && drop.parentSceneId == null
      && !payload.before_scene_id && !payload.after_scene_id) {
      return;
    }

    moveScene(movingId, payload).catch((error) => {
      handleError(error);
      loadProject().catch(handleError);
    });
  }, true);
}

/* —— Episode sequence (회차) + browser-like tabs —— */
const EPISODE_TABS_MAX = 14;
const EPISODE_TABS_PREFIX = "supertory.episodeTabs.";

function episodeTabsKey(projectId = state.projectId) {
  return `${EPISODE_TABS_PREFIX}${projectId || "0"}`;
}

function loadEpisodeTabsFromStorage() {
  if (!state.projectId) {
    state.episodeTabs = [];
    return;
  }
  try {
    const raw = localStorage.getItem(episodeTabsKey());
    const arr = raw ? JSON.parse(raw) : [];
    state.episodeTabs = Array.isArray(arr)
      ? arr
        .filter((t) => t && Number(t.sceneId) > 0)
        .map((t) => ({
          sceneId: Number(t.sceneId),
          title: String(t.title || "").trim() || `${i18n.t('app.씬_t_sceneId', {'t.sceneId': t.sceneId})}`,
        }))
        .slice(0, EPISODE_TABS_MAX)
      : [];
  } catch (_) {
    state.episodeTabs = [];
  }
}

function saveEpisodeTabsToStorage() {
  if (!state.projectId) return;
  try {
    localStorage.setItem(episodeTabsKey(), JSON.stringify(state.episodeTabs || []));
  } catch (_) {
    /* ignore */
  }
}

/** Chapters in binder folder DFS order (same source as the sidebar tree). */
function chaptersForReadingOrder() {
  if (typeof getBinderChaptersInOrder === "function") {
    const binder = getBinderChaptersInOrder();
    if (binder.length) return binder;
  }
  return Array.isArray(state.outline) ? state.outline.slice() : [];
}

function walkReadingOrderChapters(chapters, visit) {
  if (typeof walkBinderChapters === "function") {
    walkBinderChapters(chapters, visit);
    return;
  }
  for (const chapter of chapters || []) visit(chapter);
}

/**
 * Leftover scenes that live on state.outline but were not reached via the
 * folder tree (no folder_id / missing map). Appended last — same policy as
 * export_project's chapter.sort_order fallback.
 */
function walkOrphanOutlineChapters(seenSceneIds, visit) {
  if (!Array.isArray(state.outline) || !state.outline.length) return;
  walkReadingOrderChapters(state.outline, (chapter) => {
    const flat = flattenChapterScenes(chapter);
    if (!flat.some((scene) => {
      const id = Number(scene.id);
      return id > 0 && !seenSceneIds.has(id);
    })) return;
    visit(chapter);
  });
}

/**
 * Unique manuscript folders in binder DFS order (import chapter dropdown).
 * Same walk as getEpisodeSequence: getBinderChaptersInOrder + nested
 * child_chapters, then leftover state.outline. Boxes are skipped.
 */
function chaptersInBinderDisplayOrder() {
  const seen = new Set();
  const list = [];
  const push = (chapter) => {
    const id = Number(chapter?.id);
    if (!id || seen.has(id)) return;
    if (typeof binderFolderNodeIsBox === "function" && binderFolderNodeIsBox(chapter)) {
      return;
    }
    if (chapter.source_kind === "part") return;
    seen.add(id);
    list.push(chapter);
  };
  walkReadingOrderChapters(chaptersForReadingOrder(), push);
  if (Array.isArray(state.outline) && state.outline.length) {
    walkReadingOrderChapters(state.outline, push);
  }
  return list;
}

/** Flatten outline scenes in binder order (depth-first) → episode list. */
function getEpisodeSequence() {
  const list = [];
  const seen = new Set();
  const pushFromChapter = (chapter) => {
    const chapterTitle = String(chapter.title || "").trim();
    const flat = flattenChapterScenes(chapter);
    for (const scene of flat) {
      const sceneId = Number(scene.id);
      if (!sceneId || seen.has(sceneId)) continue;
      seen.add(sceneId);
      const index = list.length + 1;
      const sceneTitle = String(scene.title || "").trim();
      let label = chapterTitle || sceneTitle || `${i18n.t('app.index_화', {index: index})}`;
      if (flat.length > 1 && sceneTitle && chapterTitle && sceneTitle !== chapterTitle) {
        label = `${chapterTitle} · ${sceneTitle}`;
      } else if (!chapterTitle && sceneTitle) {
        label = sceneTitle;
      }
      const short = label.length > 22 ? `${label.slice(0, 22)}…` : label;
      list.push({
        sceneId,
        chapterId: Number(chapter.id),
        index,
        label,
        shortLabel: short,
        chapterTitle,
        sceneTitle,
      });
    }
  };
  walkReadingOrderChapters(chaptersForReadingOrder(), pushFromChapter);
  walkOrphanOutlineChapters(seen, pushFromChapter);
  return list;
}

/** All scene synopses in binder order (for 요약 list). */
function getSynopsisSequence() {
  const list = [];
  const seen = new Set();
  const pushFromChapter = (chapter) => {
    const chapterTitle = String(chapter.title || "").trim();
    const flat = flattenChapterScenes(chapter);
    for (const scene of flat) {
      const sceneId = Number(scene.id);
      if (!sceneId || seen.has(sceneId)) continue;
      seen.add(sceneId);
      const index = list.length + 1;
      const sceneTitle = String(scene.title || "").trim();
      let title = chapterTitle || sceneTitle || `${i18n.t('app.index_화', {index: index})}`;
      if (chapterTitle && sceneTitle && sceneTitle !== chapterTitle) {
        title = `${chapterTitle} · ${sceneTitle}`;
      }
      let synopsis = String(scene.synopsis_md || "").trim();
      // Live field for the open scene.
      if (sceneId === Number(state.sceneId) && $("sceneSynopsis")) {
        synopsis = String($("sceneSynopsis").value || "").trim();
      }
      list.push({
        sceneId,
        chapterId: Number(chapter.id),
        index,
        title,
        synopsis,
      });
    }
  };
  walkReadingOrderChapters(chaptersForReadingOrder(), pushFromChapter);
  walkOrphanOutlineChapters(seen, pushFromChapter);
  return list;
}

const TORY_SUMMARY_MIN_LENGTH = 100;
let torySceneSummaryInFlight = false;

function checkSummarizable(currentLength) {
  if (currentLength < TORY_SUMMARY_MIN_LENGTH) {
    const remaining = TORY_SUMMARY_MIN_LENGTH - currentLength;
    return {
      possible: false,
      message: `${i18n.t('app.아직_요약하기엔_짧아요_100자까지_rema', {remaining: remaining})}`,
    };
  }
  return { possible: true };
}

function getSummaryTargetLength(originalLength) {
  if (originalLength < 500) return 60;
  if (originalLength < 2000) return 80;
  if (originalLength < 5000) return 100;
  if (originalLength < 10000) return 130;
  return 150;
}

function buildSummaryPrompt(originalText, clusterId) {
  if (promptPipelineId(clusterId) === "genre_literature") {
    return buildSummaryPrompt_GenreLit(originalText);
  }
  return buildSummaryPrompt_Webnovel(originalText);
}

function buildSummaryPrompt_Webnovel(originalText) {
  const length = originalText.length;
  const target = getSummaryTargetLength(length);

  return `[현재 작업]
아래 본문을 ${target}자 내외(최대 ${target + 15}자를 넘지 않도록)로 요약하세요.

[판단 기준]
1. 이 장면/문단이 전체 이야기에서 어떤 기능을 하는지 먼저 파악한다
   (사건의 발단인가, 갈등의 심화인가, 전환점인가).
2. 그 기능을 가장 잘 드러내는 핵심 사건 → 그로 인한 결과/의미 순으로 압축한다.
3. 여러 정보 중 하나를 덜어내야 한다면, 서사적 기능이 약한 것부터 덜어낸다
   (배경 묘사 > 부차적 인물 > 핵심 갈등과 무관한 디테일 순으로 우선 제거).
4. 본문에 없는 내용을 추측하거나 덧붙이지 않는다.

[문장 규칙]
5. 원문의 표현을 그대로 가져오지 말고 자신의 언어로 재서술한다. 단, 고유명사(인물명,
   지명 등)는 원문 그대로 유지한다.
6. i18n.t('app.이_글은'), i18n.t('app.본문에서는') 같은 메타 표현으로 시작하지 않고 바로 내용으로 시작한다.
7. 수식어, 감탄사, 접속사 남발을 피하고 명사형·서술형 위주로 간결하게 쓴다.
8. 초안 작성 후 글자 수를 직접 세어 기준을 넘으면, 서사적 기능이 약한 정보부터
   덜어내며 다시 압축한다. 이 과정은 출력하지 않는다.
9. 완성된 요약문만 출력한다. 설명, 따옴표, 부연은 붙이지 않는다.

[본문]
${originalText}

[요약]`;
}

