/**
 * Parse rewrite model output into polish vs alternatives presentation.
 * @returns {{ kind: "polish"|"alternatives"|"plain", polished: string, reason: string, ask: string, alternatives: string[], displayText: string, title: string, resultHeader: string, hint: string }}
 */
function parseRewriteAssistDisplay(resultText) {
  const raw = String(resultText || "").replace(/\r\n/g, "\n").trim();
  const empty = {
    kind: "plain",
    polished: "",
    reason: "",
    ask: "",
    alternatives: [],
    displayText: "",
    title: i18n.t('app.글_다듬기_비교'),
    resultHeader: i18n.t('app.다듬은_결과'),
    hint: i18n.t('app.원문과_결과를_비교한_뒤_반영_여부를_고르세'),
  };
  if (!raw) return empty;

  // Alternatives branch (good as-is)
  if (/##\s*이미\s*좋은\s*문장/i.test(raw) || (/대안\s*1\s*[:：]/i.test(raw) && !/##\s*다듬기\s*제안/i.test(raw))) {
    const alts = [];
    const re = /(?:^|\n)\s*[-*]?\s*대안\s*(\d+)\s*[:：]\s*(.+?)(?=\n\s*[-*]?\s*대안\s*\d+\s*[:：]|\n##|\s*$)/gis;
    let m;
    while ((m = re.exec(raw)) !== null) {
      const line = String(m[2] || "").replace(/\s+/g, " ").trim();
      if (line) alts.push(line);
    }
    if (!alts.length) {
      const after = raw.split(/##\s*이미\s*좋은\s*문장[^\n]*/i)[1] || raw;
      for (const line of after.split("\n")) {
        const t = line.replace(/^\s*[-*•]\s*/, "").replace(/^대안\s*\d+\s*[:：]\s*/, "").trim();
        if (t && !/^다른 표현/.test(t) && t.length > 1) alts.push(t);
      }
    }
    const unique = [...new Set(alts)].slice(0, 5);
    return {
      kind: "alternatives",
      polished: unique[0] || "",
      reason: "",
      ask: "",
      alternatives: unique,
      displayText: unique[0] || raw,
      title: i18n.t('app.이미_좋은_문장이에요'),
      resultHeader: i18n.t('app.대안_표현_클릭해_선택'),
      hint: i18n.t('app.원문은_이미_충분해요_바꾸고_싶을_때만_아래'),
    };
  }

  // Polish / proposal branch (new: ## 다듬기 제안)
  if (/##\s*다듬기\s*제안/i.test(raw) || /\*\*다듬은\s*결과:\*\*/i.test(raw) || /##\s*다듬은\s*결과/i.test(raw)) {
    let reason = "";
    let polished = "";
    let ask = "";

    const reasonMatch = raw.match(
      /##\s*다듬기\s*제안\s*\n+([\s\S]*?)(?=\n\s*\*\*다듬은\s*결과:\*\*|\n\s*다듬은\s*결과\s*[:：]|\n##\s)/i,
    );
    if (reasonMatch) {
      reason = String(reasonMatch[1] || "").trim();
    } else {
      const r2 = raw.match(/(저는[\s\S]*?(?:보였어요|판단했어요|생각했어요)\.?)/);
      if (r2) reason = r2[1].trim();
    }

    const polishMatch = raw.match(
      /\*\*다듬은\s*결과:\*\*\s*([^\n]+(?:\n(?!작가님)[^\n]+)*)/i,
    )
      || raw.match(/다듬은\s*결과\s*[:：]\s*([^\n]+)/i)
      || raw.match(/##\s*다듬은\s*결과\s*\n+([\s\S]*?)(?=\n\s*작가님|\n##|\s*$)/i);
    if (polishMatch) {
      polished = String(polishMatch[1] || "").trim();
    }

    const askMatch = raw.match(/(작가님의\s*생각은\s*어떤가요\?[^\n]*)/i);
    if (askMatch) ask = askMatch[1].trim();
    else if (/이 문장으로 대체하시겠어요/i.test(raw)) {
      ask = i18n.t('app.작가님의_생각은_어떤가요_이_문장으로_대체하');
    }

    if (!polished) {
      // Fallback: last non-empty line that isn't reason/ask/header
      const lines = raw.split("\n").map((l) => l.trim()).filter(Boolean);
      polished = lines.filter((l) =>
        !/^#/.test(l)
        && !/^저는/.test(l)
        && !/^작가님/.test(l)
        && !/\*\*/.test(l)
        && !/대체하시겠어요/.test(l)
      ).pop() || raw;
    }

    return {
      kind: "polish",
      polished,
      reason,
      ask: ask || i18n.t('app.작가님의_생각은_어떤가요_이_문장으로_대체하'),
      alternatives: [],
      displayText: polished,
      title: i18n.t('app.다듬기_제안'),
      resultHeader: i18n.t('app.다듬은_결과'),
      hint: reason
        ? `${reason}${ask ? `\n\n${ask}` : ""}`
        : (ask || i18n.t('app.원문과_다듬은_결과를_비교한_뒤_반영_여부를')),
    };
  }

  // Plain polished text (legacy)
  return {
    kind: "plain",
    polished: raw,
    reason: "",
    ask: "",
    alternatives: [],
    displayText: raw,
    title: i18n.t('app.글_다듬기_비교'),
    resultHeader: i18n.t('app.다듬은_결과'),
    hint: i18n.t('app.원문과_결과를_비교한_뒤_반영_여부를_고르세'),
  };
}

const REWRITE_CONTEXT_CHARS = 200;
let pendingRewriteState = null;
let rewriteAssistInFlight = false;

/** @type {{ source: string, referenceText: string, targetText: string } | null} */
let pendingStyleBlendContext = null;
let styleBlendInFlight = false;

const STYLE_BLEND_GUIDE_TEXT = (
  i18n.t('app.직접_수정하며_재작성_하시겠어요_그대로_쓰신')
  + i18n.t('app.잘_어우러지는지_별도_검사를_추천합니다')
);

function setStyleBlendOfferVisible(show) {
  $("styleBlendOffer")?.classList.toggle("hidden", !show);
  $("styleBlendOfferModal")?.classList.toggle("hidden", !show);
}

function clearStyleBlendResultViews(scope = "continue") {
  const clearPair = (statusId, resultId) => {
    const status = $(statusId);
    const result = $(resultId);
    if (status) {
      status.textContent = "";
      status.classList.add("hidden");
    }
    if (result) {
      result.textContent = "";
      result.classList.add("hidden");
    }
  };
  if (scope === "rewrite") {
    clearPair("rewriteStyleBlendStatus", "rewriteStyleBlendResult");
    return;
  }
  clearPair("styleBlendStatus", "styleBlendResult");
  clearPair("styleBlendStatusModal", "styleBlendResultModal");
}

function prepareStyleBlendOffer(context) {
  pendingStyleBlendContext = context && context.referenceText && context.targetText
    ? {
      source: String(context.source || "continue"),
      referenceText: String(context.referenceText || "").trim(),
      targetText: String(context.targetText || "").trim(),
    }
    : null;
  const show = Boolean(pendingStyleBlendContext?.referenceText && pendingStyleBlendContext?.targetText);
  if (pendingStyleBlendContext?.source === "rewrite") {
    setStyleBlendOfferVisible(false);
    clearStyleBlendResultViews("rewrite");
    return;
  }
  clearStyleBlendResultViews("continue");
  setStyleBlendOfferVisible(show);
}

function setStyleBlendLoading(scope, loading, message = "") {
  const pairs = scope === "rewrite"
    ? [["rewriteStyleBlendCheckButton", "rewriteStyleBlendStatus", "rewriteStyleBlendResult"]]
    : [
      ["styleBlendCheckButton", "styleBlendStatus", "styleBlendResult"],
      ["styleBlendCheckButtonModal", "styleBlendStatusModal", "styleBlendResultModal"],
    ];
  for (const [btnId, statusId, resultId] of pairs) {
    const button = $(btnId);
    const status = $(statusId);
    const result = $(resultId);
    if (button) {
      button.disabled = Boolean(loading);
      button.textContent = loading ? i18n.t('app.스며듦_검사_중') : i18n.t('app.스며듦_검사하기');
    }
    if (status) {
      if (loading || message) {
        status.textContent = message || i18n.t('app.스며듦_검사_중_별도_호출_잠시만_기다려_주');
        status.classList.remove("hidden");
      } else {
        status.textContent = "";
        status.classList.add("hidden");
      }
    }
    if (loading && result) {
      result.textContent = "";
      result.classList.add("hidden");
    }
  }
}

function paintStyleBlendResult(scope, text) {
  const ids = scope === "rewrite"
    ? [["rewriteStyleBlendStatus", "rewriteStyleBlendResult"]]
    : [
      ["styleBlendStatus", "styleBlendResult"],
      ["styleBlendStatusModal", "styleBlendResultModal"],
    ];
  for (const [statusId, resultId] of ids) {
    const status = $(statusId);
    const result = $(resultId);
    if (status) {
      status.textContent = i18n.t('app.스며듦_검사_완료');
      status.classList.remove("hidden");
    }
    if (result) {
      result.textContent = text || i18n.t('app.결과_없음');
      result.classList.remove("hidden");
    }
  }
}

async function runStyleBlendCheck(options = {}) {
  if (styleBlendInFlight) {
    toast(i18n.t('app.이미_스며듦_검사를_진행_중이에요'));
    return null;
  }
  if (!state.projectId) {
    toast(i18n.t('app.먼저_작품을_선택해_주세요'));
    return null;
  }
  const scope = options.scope
    || (pendingStyleBlendContext?.source === "rewrite" ? "rewrite" : "continue");
  let referenceText = String(options.referenceText || pendingStyleBlendContext?.referenceText || "").trim();
  let targetText = String(options.targetText || pendingStyleBlendContext?.targetText || "").trim();
  if (scope === "rewrite") {
    targetText = String($("rewriteCompareResult")?.value || targetText).trim();
    if (!referenceText && pendingRewriteState?.referenceText) {
      referenceText = String(pendingRewriteState.referenceText || "").trim();
    }
  }
  if (!referenceText || !targetText) {
    toast(i18n.t('app.스며듦_검사에_필요한_기준_비교_텍스트가_없'));
    return null;
  }

  styleBlendInFlight = true;
  setStyleBlendLoading(scope, true);
  try {
    const project = state.projects.find((item) => item.id === state.projectId);
    const mainGenre = state.mainGenre || project?.main_genre || "";
    const subGenre = state.subGenre || project?.sub_genre || "";
    const taskPrompt = buildStyleBlendCheckPrompt(referenceText, targetText);
    const body = {
      mode: "styleblend",
      project_id: state.projectId,
      project_title: project?.title || "",
      purpose: normalizePurposeKey(state.projectPurpose || project?.purpose || "general_novel"),
      main_genre: mainGenre,
      sub_genre: subGenre,
      main_genre_label: mainGenreLabel(mainGenre),
      sub_genre_label: subGenreLabel(mainGenre, subGenre),
      keywords: normalizeKeywordList(state.keywords || project?.keywords || []),
      reference_text: referenceText,
      target_text: targetText,
      scene_content: "",
      task_prompt: taskPrompt,
      prompt: "",
      persona_mode: typeof getToryPersonaMode === "function" ? getToryPersonaMode() : "default",
      ...buildToryProjectContextPayload(),
    };
    const result = await api("/api/ai/assist", {
      method: "POST",
      body: JSON.stringify(body),
    });
    const text = String(result.text || "").trim() || i18n.t('app.결과_없음');
    setStyleBlendLoading(scope, false);
    paintStyleBlendResult(scope, text);
    toast(i18n.t('app.스며듦_검사가_끝났어요'));
    return text;
  } catch (error) {
    setStyleBlendLoading(scope, false, i18n.t('app.스며듦_검사에_실패했어요_다시_시도해_주세요'));
    handleError(error);
    return null;
  } finally {
    styleBlendInFlight = false;
    const buttons = scope === "rewrite"
      ? ["rewriteStyleBlendCheckButton"]
      : ["styleBlendCheckButton", "styleBlendCheckButtonModal"];
    for (const id of buttons) {
      const button = $(id);
      if (button) {
        button.disabled = false;
        button.textContent = i18n.t('app.스며듦_검사하기');
      }
    }
  }
}

function setupStyleBlendUi() {
  $("styleBlendCheckButton")?.addEventListener("click", () => {
    runStyleBlendCheck({ scope: "continue" }).catch(handleError);
  });
  $("styleBlendCheckButtonModal")?.addEventListener("click", () => {
    runStyleBlendCheck({ scope: "continue" }).catch(handleError);
  });
  $("rewriteStyleBlendCheckButton")?.addEventListener("click", () => {
    runStyleBlendCheck({ scope: "rewrite" }).catch(handleError);
  });
  document.querySelectorAll(".style-blend-guide").forEach((el) => {
    el.textContent = STYLE_BLEND_GUIDE_TEXT;
  });
}

function getRewriteDirectionHint() {
  return String($("rewriteDirectionHint")?.value || "").trim().slice(0, 500);
}

/** "selection" | "direct" — rewrite input mode in the tool popup. */
function getRewriteSourceMode() {
  const checked = document.querySelector('input[name="rewriteSourceMode"]:checked');
  const raw = String(checked?.value || "selection").trim().toLowerCase();
  return raw === "direct" ? "direct" : "selection";
}

function updateRewriteSourceUi() {
  // Textarea + hint always visible; selection mode still wins at execute time.
  $("rewriteDirectWrap")?.classList.remove("hidden");
  $("rewriteDirectHint")?.classList.remove("hidden");
}

function setupRewriteSourceUi() {
  const host = $("rewriteSourceOptions");
  if (!host || host.dataset.bound === "1") return;
  host.dataset.bound = "1";
  host.addEventListener("change", (event) => {
    if (!event.target?.matches?.('input[name="rewriteSourceMode"]')) return;
    updateRewriteSourceUi();
    if (getRewriteSourceMode() === "direct") {
      requestAnimationFrame(() => {
        try {
          $("rewriteDirectText")?.focus({ preventScroll: true });
        } catch (_) {
          $("rewriteDirectText")?.focus();
        }
      });
    }
  });
  updateRewriteSourceUi();
}

/** Chip labels stay i18n; fill phrases stay Korean so the model gets a stable direction. */
const REWRITE_PRESET_HINTS = {
  concise: "더 짧고 간결하게 다듬어 줘",
  enrich: "감각과 분위기를 살려서 더 풍부하게 펼쳐 줘",
  dialogue: "서술 부분에 어울리는 캐릭터의 대사를 추가해 줘",
  psychology: "캐릭터의 내면 심리를 추가해 줘",
  setting: "배경이나 주변 환경 묘사를 보강해 줘",
};

let rewriteOpenSnapshot = null;

function applyRewritePreset(presetId) {
  const hint = REWRITE_PRESET_HINTS[presetId];
  if (!hint) return;
  const el = $("rewriteDirectionHint");
  if (!el) return;
  el.value = hint;
  document.querySelectorAll("[data-rewrite-preset]").forEach((btn) => {
    btn.classList.toggle("is-active", btn.getAttribute("data-rewrite-preset") === presetId);
  });
  requestAnimationFrame(() => {
    try {
      el.focus({ preventScroll: true });
    } catch (_) {
      el.focus();
    }
    const len = String(el.value || "").length;
    try {
      el.setSelectionRange(len, len);
    } catch (_) { /* ignore */ }
  });
}

function setRewritePresetMoreOpen(open) {
  const extra = $("rewritePresetExtra");
  const btn = $("rewritePresetMoreBtn");
  extra?.classList.toggle("hidden", !open);
  if (btn) {
    btn.setAttribute("aria-expanded", open ? "true" : "false");
    btn.classList.toggle("is-open", open);
    const label = $("rewritePresetMoreLabel");
    if (label) label.textContent = open ? i18n.t("index.접기") : i18n.t("app.더_보기");
  }
}

function setupRewritePresetChips() {
  const row = $("rewritePresetRow");
  if (row && row.dataset.bound !== "1") {
    row.dataset.bound = "1";
    row.addEventListener("click", (event) => {
      const chip = event.target?.closest?.("[data-rewrite-preset]");
      if (!chip || !row.contains(chip)) return;
      event.preventDefault();
      applyRewritePreset(chip.getAttribute("data-rewrite-preset"));
    });
  }
  const extra = $("rewritePresetExtra");
  if (extra && extra.dataset.bound !== "1") {
    extra.dataset.bound = "1";
    extra.addEventListener("click", (event) => {
      const chip = event.target?.closest?.("[data-rewrite-preset]");
      if (!chip || !extra.contains(chip)) return;
      event.preventDefault();
      applyRewritePreset(chip.getAttribute("data-rewrite-preset"));
    });
  }
  const more = $("rewritePresetMoreBtn");
  if (more && more.dataset.bound !== "1") {
    more.dataset.bound = "1";
    more.addEventListener("click", (event) => {
      event.preventDefault();
      const willOpen = $("rewritePresetExtra")?.classList.contains("hidden");
      setRewritePresetMoreOpen(Boolean(willOpen));
    });
  }
}

function prepareRewritePanel({ fromSelection = false } = {}) {
  setupRewriteSourceUi();
  setupRewritePresetChips();
  setRewritePresetMoreOpen(false);
  document.querySelectorAll("[data-rewrite-preset]").forEach((btn) => {
    btn.classList.remove("is-active");
  });
  const box = $("rewriteDirectText");
  if (fromSelection) {
    const payload = getRewriteSelectionPayload();
    const selRadio = document.querySelector('input[name="rewriteSourceMode"][value="selection"]');
    if (selRadio) selRadio.checked = true;
    if (box) box.value = payload?.selectedText || "";
    rewriteOpenSnapshot = payload || null;
  } else {
    if (box) box.value = "";
    rewriteOpenSnapshot = null;
  }
  updateRewriteSourceUi();
}

/** Selection + ±context for 글 다듬기 (panel and context-menu share openRewriteAssistModal). */
function getRewriteSelectionPayload() {
  const editor = getContextRichEditor() || getActiveRichEditor() || $("sceneContent");
  if (!editor) return null;
  let range = null;
  try {
    range = getUsableEditorRange(editor) || manuscriptContextRange;
    if (range && range.collapsed) range = null;
    if (range && !editor.contains(range.commonAncestorContainer)) range = null;
  } catch (_) {
    range = null;
  }
  let selectedText = "";
  if (range) {
    try {
      selectedText = String(range.toString() || "").trim();
    } catch (_) {
      selectedText = "";
    }
  }
  if (!selectedText) {
    selectedText = String(
      (typeof getSelectedManuscriptText === "function" ? getSelectedManuscriptText() : "")
      || pendingBaitQuote
      || ""
    ).trim();
  }
  if (!selectedText) return null;

  let contextBefore = "";
  let contextAfter = "";
  if (range) {
    try {
      const pre = document.createRange();
      pre.selectNodeContents(editor);
      pre.setEnd(range.startContainer, range.startOffset);
      contextBefore = String(pre.toString() || "").slice(-REWRITE_CONTEXT_CHARS);
      const post = document.createRange();
      post.selectNodeContents(editor);
      post.setStart(range.endContainer, range.endOffset);
      contextAfter = String(post.toString() || "").slice(0, REWRITE_CONTEXT_CHARS);
    } catch (_) {
      /* plain fallback below */
    }
  }
  if (!contextBefore && !contextAfter) {
    const full = String(getEditorPlainText(editor) || "");
    const idx = full.indexOf(selectedText);
    if (idx >= 0) {
      contextBefore = full.slice(Math.max(0, idx - REWRITE_CONTEXT_CHARS), idx);
      contextAfter = full.slice(
        idx + selectedText.length,
        idx + selectedText.length + REWRITE_CONTEXT_CHARS,
      );
    }
  }

  let cloned = null;
  if (range) {
    try {
      cloned = range.cloneRange();
    } catch (_) {
      cloned = null;
    }
  }
  return {
    selectedText,
    contextBefore,
    contextAfter,
    range: cloned,
    sourceMode: "selection",
    directionHint: getRewriteDirectionHint(),
  };
}

/** Payload for rewrite from popup (selection or direct write). */
function getRewriteAssistPayload() {
  const directionHint = getRewriteDirectionHint();
  const boxText = String($("rewriteDirectText")?.value || "").trim();
  if (getRewriteSourceMode() === "direct") {
    if (!boxText) return null;
    return {
      selectedText: boxText,
      contextBefore: "",
      contextAfter: "",
      range: null,
      sourceMode: "direct",
      directionHint,
    };
  }
  const live = getRewriteSelectionPayload();
  const snap = rewriteOpenSnapshot;
  const base = live || snap;
  const selectedText = boxText || String(base?.selectedText || "").trim();
  if (!selectedText) return null;
  return {
    selectedText,
    contextBefore: base?.contextBefore || "",
    contextAfter: base?.contextAfter || "",
    range: base?.range || null,
    sourceMode: "selection",
    directionHint,
  };
}

function closeRewriteCompareModal() {
  $("rewriteCompareModal")?.classList.add("hidden");
}

function renderRewriteAlternativeList(alternatives = [], selectedIndex = 0) {
  const list = $("rewriteCompareAltList");
  if (!list) return;
  const items = Array.isArray(alternatives) ? alternatives : [];
  if (!items.length) {
    list.innerHTML = "";
    list.classList.add("hidden");
    return;
  }
  list.classList.remove("hidden");
  list.innerHTML = items.map((text, i) => {
    const active = i === selectedIndex ? " is-selected" : "";
    return (
      `<button type="button" class="rewrite-alt-item${active}" data-rewrite-alt="${i}">`
      + `${i18n.t('app.span_class_rewrite_alt', {'i + 1': i + 1})}`
      + `<span class="rewrite-alt-text">${escapeHtml(text)}</span>`
      + `</button>`
    );
  }).join("");
}

function openRewriteCompareModal(originalText, resultText, options = {}) {
  const parsed = options.parsed || parseRewriteAssistDisplay(resultText);
  const kind = parsed.kind || "plain";
  const sourceMode = String(options.sourceMode || pendingRewriteState?.sourceMode || "selection");
  const isDirect = sourceMode === "direct";

  if ($("rewriteCompareOriginal")) {
    $("rewriteCompareOriginal").textContent = String(originalText || "");
  }
  if ($("rewriteCompareModalTitle")) {
    $("rewriteCompareModalTitle").textContent = parsed.title
      || i18n.t("app.글_다듬기_비교");
  }
  if ($("rewriteCompareResultHeader")) {
    $("rewriteCompareResultHeader").textContent = parsed.resultHeader
      || i18n.t("app.다듬은_결과");
  }

  const guide = $("rewriteCompareGuide");
  if (guide) {
    guide.textContent = i18n.t("app.토리는_문장을_억지로_다듬지_않아요_이미_충");
  }

  // Reason / ask banner (polish path)
  const reasonEl = $("rewriteCompareReason");
  const reasonBits = [parsed.reason, parsed.ask].filter(Boolean);
  if (reasonEl) {
    if (kind === "polish" && reasonBits.length) {
      reasonEl.textContent = reasonBits.join("\n\n");
      reasonEl.classList.remove("hidden");
    } else if (kind === "alternatives") {
      reasonEl.textContent = parsed.hint || i18n.t('app.원문은_이미_충분해요_대안을_골라_보세요');
      reasonEl.classList.remove("hidden");
    } else {
      reasonEl.textContent = "";
      reasonEl.classList.add("hidden");
    }
  }
  if ($("rewriteCompareHint")) {
    if (isDirect) {
      $("rewriteCompareHint").textContent = i18n.t('app.직접_쓴_문장의_표현_점검_결과예요_원고_위');
    } else if (kind === "alternatives") {
      $("rewriteCompareHint").textContent = i18n.t('app.원문은_이미_충분해요_바꾸고_싶을_때만_대안');
    } else {
      $("rewriteCompareHint").textContent = i18n.t('app.원문과_다듬은_결과를_비교한_뒤_반영_여부를');
    }
  }
  $("rewriteCompareDirectNote")?.classList.toggle("hidden", !isDirect);

  const resultArea = $("rewriteCompareResult");
  // Apply/copy target: polished sentence or first alternative (not the full prose block).
  const display = String(parsed.displayText || parsed.polished || resultText || "");
  if (resultArea) resultArea.value = display;

  if (kind === "alternatives" && parsed.alternatives?.length) {
    renderRewriteAlternativeList(parsed.alternatives, 0);
    $("rewriteCompareResult")?.setAttribute("aria-label", i18n.t('app.선택한_대안_표현_수정_가능'));
  } else {
    renderRewriteAlternativeList([]);
    $("rewriteCompareResult")?.setAttribute("aria-label", i18n.t('app.다듬은_결과_수정_가능'));
  }

  // Buttons: selection → replace / copy / keep ; direct → copy only
  const applyBtn = $("rewriteCompareApplyButton");
  const copyBtn = $("rewriteCompareCopyButton");
  const keepBtn = $("rewriteCompareKeepButton");
  if (isDirect) {
    applyBtn?.classList.add("hidden");
    keepBtn?.classList.add("hidden");
    if (copyBtn) {
      copyBtn.classList.remove("hidden");
      copyBtn.textContent = i18n.t('app.복사하기');
    }
  } else {
    applyBtn?.classList.remove("hidden");
    keepBtn?.classList.remove("hidden");
    if (copyBtn) {
      copyBtn.classList.remove("hidden");
      copyBtn.textContent = i18n.t('app.복사');
    }
    if (applyBtn) applyBtn.textContent = i18n.t('app.이_문장으로_바꿔요');
    if (keepBtn) keepBtn.textContent = i18n.t('app.그대로_둘래요');
  }

  // Style-blend: selection polish only
  $("rewriteStyleBlendOffer")?.classList.toggle(
    "hidden",
    isDirect || kind === "alternatives",
  );

  $("rewriteCompareModal")?.classList.remove("hidden");
}

function applyPendingRewriteToEditor() {
  const edited = String($("rewriteCompareResult")?.value || "").trim();
  if (!edited) {
    toast(i18n.t('app.적용할_다듬은_결과가_없어요'));
    return false;
  }
  const editor = getContextRichEditor() || getActiveRichEditor() || $("sceneContent");
  const isSettings = editor?.id === "synopsisContent";
  if (!editor || (!isSettings && !state.sceneId)) {
    toast(i18n.t('app.반영하려면_원고_또는_설정_문서를_열어_주세'));
    return false;
  }
  const range = pendingRewriteState?.range;
  const original = String(pendingRewriteState?.original || "");
  const sourceMode = String(pendingRewriteState?.sourceMode || "selection");
  editor.focus();
  let applied = false;
  try {
    if (range && editor.contains(range.commonAncestorContainer)) {
      const selection = window.getSelection();
      selection?.removeAllRanges();
      selection?.addRange(range);
      range.deleteContents();
      const node = document.createTextNode(edited);
      range.insertNode(node);
      range.setStartAfter(node);
      range.collapse(true);
      selection?.removeAllRanges();
      selection?.addRange(range);
      applied = true;
    }
  } catch (_) {
    applied = false;
  }
  // Direct-write path: insert at caret, else append.
  if (!applied && sourceMode === "direct") {
    try {
      const selection = window.getSelection();
      let insertRange = null;
      if (selection && selection.rangeCount > 0) {
        const r = selection.getRangeAt(0);
        if (editor.contains(r.commonAncestorContainer)) insertRange = r;
      }
      if (!insertRange) {
        insertRange = document.createRange();
        insertRange.selectNodeContents(editor);
        insertRange.collapse(false);
      }
      insertRange.deleteContents();
      const node = document.createTextNode(edited);
      insertRange.insertNode(node);
      insertRange.setStartAfter(node);
      insertRange.collapse(true);
      selection?.removeAllRanges();
      selection?.addRange(insertRange);
      applied = true;
    } catch (_) {
      applied = false;
    }
  }
  if (!applied) {
    if (navigator.clipboard?.writeText) {
      navigator.clipboard.writeText(edited).catch(() => {});
    }
    toast(
      sourceMode === "direct"
        ? i18n.t('app.편집기에_넣지_못해_결과를_복사해_두었어요')
        : i18n.t('app.선택_구간을_찾지_못해_결과를_복사해_두었어'),
    );
    return false;
  }
  updateEditorPlaceholder(editor);
  if (isSettings) {
    markSynopsisDirty();
  } else {
    updateSceneStats();
    markSceneDirty();
  }
  closeRewriteCompareModal();
  toast(i18n.t('app.다듬은_문장으로_바꿨어요_자동_저장됩니다'));
  return true;
}

let rewriteLengthWarnResolver = null;

function closeRewriteLengthWarnModal(proceed) {
  $("rewriteLengthWarnModal")?.classList.add("hidden");
  const resolve = rewriteLengthWarnResolver;
  rewriteLengthWarnResolver = null;
  if (typeof resolve === "function") resolve(Boolean(proceed));
}

function openRewriteLengthWarnModal() {
  return new Promise((resolve) => {
    if (rewriteLengthWarnResolver) {
      rewriteLengthWarnResolver(false);
      rewriteLengthWarnResolver = null;
    }
    rewriteLengthWarnResolver = resolve;
    $("rewriteLengthWarnModal")?.classList.remove("hidden");
    requestAnimationFrame(() => {
      try {
        $("rewriteLengthWarnContinue")?.focus({ preventScroll: true });
      } catch (_) {
        $("rewriteLengthWarnContinue")?.focus();
      }
    });
  });
}

function setupRewriteLengthWarnModal() {
  if ($("rewriteLengthWarnContinue")?.dataset.bound === "1") return;
  if ($("rewriteLengthWarnContinue")) $("rewriteLengthWarnContinue").dataset.bound = "1";
  $("rewriteLengthWarnContinue")?.addEventListener("click", () => {
    closeRewriteLengthWarnModal(true);
  });
  document.querySelectorAll("[data-close-rewrite-length-warn]").forEach((el) => {
    if (el.dataset.bound === "1") return;
    el.dataset.bound = "1";
    el.addEventListener("click", () => closeRewriteLengthWarnModal(false));
  });
  if (!document.documentElement.dataset.rewriteLengthWarnEscBound) {
    document.documentElement.dataset.rewriteLengthWarnEscBound = "1";
    document.addEventListener("keydown", (event) => {
      if (event.key !== "Escape") return;
      if ($("rewriteLengthWarnModal") && !$("rewriteLengthWarnModal").classList.contains("hidden")) {
        event.preventDefault();
        closeRewriteLengthWarnModal(false);
      }
    });
  }
}

/**
 * @returns {Promise<boolean>} true = proceed with rewrite
 */
async function checkRewriteLengthGate(text) {
  const n = String(text || "").trim().length;
  if (n <= 800) return true;
  if (n > 2000) {
    toast(i18n.t('app.이_정도_분량은_다듬기보다_새로_쓰는_쪽에'));
    return false;
  }
  return openRewriteLengthWarnModal();
}

/**
 * Shared rewrite runner for dropdown + context menu.
 * Shows side-by-side compare UI; does not overwrite manuscript until Apply.
 */
async function executeRewriteAssist(payload) {
  const selectedText = String(payload?.selectedText || "").trim();
  if (!selectedText) {
    toast(
      payload?.sourceMode === "direct"
        ? i18n.t('app.다듬을_문장을_직접_입력해_주세요')
        : i18n.t('app.다듬을_문장_문단을_드래그로_선택해_주세요'),
    );
    return null;
  }
  const mayProceed = await checkRewriteLengthGate(selectedText);
  if (!mayProceed) return null;
  if (!state.projectId) {
    toast(i18n.t('app.먼저_작품을_선택해_주세요'));
    return null;
  }
  if (rewriteAssistInFlight) {
    toast(i18n.t('app.이미_문장을_다듬고_있어요'));
    return null;
  }

  const isDirectWrite = String(payload?.sourceMode || "") === "direct";
  const contextBefore = isDirectWrite ? "" : String(payload?.contextBefore || "");
  const contextAfter = isDirectWrite ? "" : String(payload?.contextAfter || "");
  const directionHint = String(
    payload?.directionHint != null ? payload.directionHint : getRewriteDirectionHint()
  ).trim().slice(0, 500);
  const project = state.projects.find((item) => item.id === state.projectId);
  const mainGenre = state.mainGenre || project?.main_genre || "";
  const subGenre = state.subGenre || project?.sub_genre || "";

  const body = {
    mode: "rewrite",
    prompt: "",
    user_prompt: directionHint,
    rewrite_direction: directionHint,
    project_title: project?.title || "",
    purpose: normalizePurposeKey(state.projectPurpose || project?.purpose || "general_novel"),
    main_genre: mainGenre,
    sub_genre: subGenre,
    main_genre_label: mainGenreLabel(mainGenre),
    sub_genre_label: subGenreLabel(mainGenre, subGenre),
    keywords: normalizeKeywordList(state.keywords || project?.keywords || []),
    scene_title: isDirectWrite ? "" : (state.scene?.title || $("sceneTitle")?.value || ""),
    scene_synopsis: isDirectWrite ? "" : (state.scene?.synopsis_md || $("sceneSynopsis")?.value || ""),
    scene_content: selectedText,
    context_before: contextBefore,
    context_after: contextAfter,
    selected_text: selectedText,
    persona_mode: typeof getToryPersonaMode === "function" ? getToryPersonaMode() : "default",
    ...(isDirectWrite ? {} : buildToryProjectContextPayload()),
  };

  rewriteAssistInFlight = true;
  setAiPanelOpen(true);
  if ($("aiMode")) $("aiMode").value = "rewrite";
  if (typeof updateForeshadowPanelVisibility === "function") updateForeshadowPanelVisibility();
  if ($("aiResult")) {
    $("aiResult").value = isDirectWrite
      ? i18n.t('app.표현을_점검_다듬는_중')
      : i18n.t('app.선택_문장을_다듬는_중');
  }
  ensureAiResultVisible();

  const aiButton = $("aiSubmitButton");
  const prevLabel = aiButton?.textContent;
  if (aiButton) {
    aiButton.disabled = true;
    aiButton.textContent = i18n.t('app.글_다듬는_중');
  }
  const toolSubmit = $("aiToolModalSubmitButton");
  const toolPrev = toolSubmit?.textContent;
  if (toolSubmit) {
    toolSubmit.disabled = true;
    toolSubmit.textContent = i18n.t('app.글_다듬는_중');
  }

  try {
    if (isDirectWrite) {
      // Independent expression check — do NOT use buildRewritePrompt / project_index.
      body.indexed_prompt = buildPlainExpressionCheckPrompt(selectedText, directionHint);
      body.project_index = null;
      body.skip_project_index = true;
    } else {
      // Manuscript selection / right-click path — buildRewritePrompt + optional index.
      await attachIndexedPromptToAssistBody(body, "rewrite", selectedText);
    }
    const result = await api("/api/ai/assist", {
      method: "POST",
      body: JSON.stringify(body),
    });
    const polished = String(result.text || "").trim();
    const fullScenePlain = isDirectWrite
      ? ""
      : String(
        (looksLikeHtml(getEditorContent()) ? plainTextFromHtml(getEditorContent()) : getEditorContent())
        || ""
      ).trim();
    // Prefer full episode as style reference; fall back to ±200 char window.
    // Direct-write has no manuscript context — reference is the input itself only.
    const referenceText = isDirectWrite
      ? selectedText
      : (fullScenePlain
        || `${contextBefore}${selectedText}${contextAfter}`.trim()
        || selectedText);
    const displayParsed = parseRewriteAssistDisplay(polished);
    const applyText = displayParsed.displayText || displayParsed.polished || polished;
    pendingRewriteState = {
      original: selectedText,
      result: polished,
      range: payload?.range || null,
      referenceText,
      contextBefore,
      contextAfter,
      sourceMode: payload?.sourceMode || "selection",
      resultKind: displayParsed.kind,
      alternatives: displayParsed.alternatives || [],
      reason: displayParsed.reason || "",
    };
    pendingStyleBlendContext = (isDirectWrite || displayParsed.kind === "alternatives")
      ? null
      : {
        source: "rewrite",
        referenceText,
        targetText: applyText,
      };
    clearStyleBlendResultViews("rewrite");
    if ($("aiResult")) {
      $("aiResult").value = polished
        ? `【원문】\n${selectedText}\n\n【결과】\n${polished}`
        : i18n.t('app.결과_없음');
    }
    prepareStyleBlendOffer(null); // hide continue offer on panel
    revealAiAssistResult({ openModal: false, mode: "rewrite" });
    openRewriteCompareModal(selectedText, polished, {
      parsed: displayParsed,
      sourceMode: isDirectWrite ? "direct" : "selection",
    });
    if (!polished) {
      toast(i18n.t('app.다듬기_응답이_비어_있어요'));
    } else if (displayParsed.kind === "alternatives") {
      toast(isDirectWrite
        ? i18n.t('app.이미_자연스러운_문장으로_보여요_필요하면_복')
        : i18n.t('app.이미_좋은_문장으로_보여요_대안을_고르거나'));
    } else {
      toast(isDirectWrite
        ? i18n.t('app.표현_점검_완료_복사해_쓰실_수_있어요')
        : i18n.t('app.다듬기_제안이_왔어요_대체_복사_유지_중_골'));
    }
    return result;
  } catch (error) {
    if ($("aiResult")) $("aiResult").value = "";
    handleError(error);
    return null;
  } finally {
    rewriteAssistInFlight = false;
    if (aiButton) {
      aiButton.disabled = false;
      aiButton.textContent = prevLabel || i18n.t('app.토리에게_물어보기');
    }
    if (toolSubmit) {
      toolSubmit.disabled = false;
      toolSubmit.textContent = toolPrev || i18n.t('app.글_다듬기');
    }
  }
}

async function runRewriteFromSelection() {
  const payload = getRewriteSelectionPayload();
  if (!payload?.selectedText) {
    toast(i18n.t('app.다듬을_문장_문단을_드래그로_선택해_주세요'));
    return null;
  }
  openRewriteAssistModal({ fromSelection: true });
  requestAnimationFrame(() => {
    try {
      $("rewriteDirectionHint")?.focus({ preventScroll: true });
    } catch (_) {
      $("rewriteDirectionHint")?.focus();
    }
  });
  toast(i18n.t('app.다듬기_방향을_적은_뒤_다듬기_를_눌러_주세'));
  return null;
}

function setupRewriteCompareModal() {
  setupRewriteLengthWarnModal();
  document.querySelectorAll("[data-close-rewrite-compare]").forEach((el) => {
    el.addEventListener("click", () => closeRewriteCompareModal());
  });
  $("rewriteCompareCopyButton")?.addEventListener("click", async () => {
    const text = String($("rewriteCompareResult")?.value || "").trim();
    if (!text) return toast(i18n.t('app.복사할_결과가_없어요'));
    try {
      await navigator.clipboard.writeText(text);
      toast(i18n.t('app.결과를_복사했어요'));
    } catch (_) {
      toast(i18n.t('app.복사에_실패했어요'));
    }
  });
  $("rewriteCompareApplyButton")?.addEventListener("click", () => {
    applyPendingRewriteToEditor();
  });
  $("rewriteCompareKeepButton")?.addEventListener("click", () => {
    closeRewriteCompareModal();
    toast(i18n.t('app.원문을_그대로_유지했어요'));
  });
  $("rewriteCompareAltList")?.addEventListener("click", (event) => {
    const btn = event.target?.closest?.("[data-rewrite-alt]");
    if (!btn) return;
    const idx = Number(btn.getAttribute("data-rewrite-alt"));
    const alts = pendingRewriteState?.alternatives || [];
    const text = alts[idx];
    if (!text) return;
    if ($("rewriteCompareResult")) $("rewriteCompareResult").value = text;
    $("rewriteCompareAltList")?.querySelectorAll(".rewrite-alt-item").forEach((el, i) => {
      el.classList.toggle("is-selected", i === idx);
    });
    if (pendingStyleBlendContext) {
      pendingStyleBlendContext.targetText = text;
    }
  });
}

function getScenePlainForSummary() {
  const raw = getEditorPlainText($("sceneContent"));
  return String(raw || "").replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim();
}

function applyTorySummaryToField(summaryText) {
  const cleaned = String(summaryText || "")
    .trim()
    .replace(/^["'「『]|["'」』]$/g, "")
    .trim();
  const field = $("sceneSynopsis");
  if (!field || !cleaned) return "";
  field.value = cleaned;
  field.dispatchEvent(new Event("input", { bubbles: true }));
  if (state.sceneId) markSceneDirty();
  return cleaned;
}

async function runTorySceneSummary() {
  if (torySceneSummaryInFlight) {
    toast(i18n.t('app.이미_요약을_만들고_있어요'));
    return;
  }
  if (!state.projectId) {
    toast(i18n.t('app.먼저_작품을_선택해_주세요'));
    return;
  }
  if (!state.sceneId) {
    toast(i18n.t('app.먼저_목차에서_씬을_열어_주세요'));
    return;
  }

  const originalText = getScenePlainForSummary();
  const check = checkSummarizable(originalText.length);
  if (!check.possible) {
    toast(check.message);
    return;
  }

  const existing = String($("sceneSynopsis")?.value || "").trim();
  if (existing) {
    const ok = window.confirm(i18n.t('app.이미_요약이_있어요_토리가_새로_쓴_요약으로'));
    if (!ok) return;
  }

  const prompt = buildSummaryPrompt(originalText);
  const project = state.projects.find((item) => item.id === state.projectId);
  const mainGenre = state.mainGenre || project?.main_genre || "";
  const subGenre = state.subGenre || project?.sub_genre || "";
  const btn = $("synopsisListButton");
  const prevTitle = btn?.title;
  const prevLabel = btn?.textContent;

  torySceneSummaryInFlight = true;
  if (btn) {
    btn.disabled = true;
    btn.textContent = i18n.t('app.요약_중');
    btn.title = i18n.t('app.토리가_본문을_요약하는_중');
  }
  setAiPanelOpen(true);
  if ($("aiMode")) $("aiMode").value = "free";
  if (typeof updateForeshadowPanelVisibility === "function") updateForeshadowPanelVisibility();
  if ($("aiPrompt")) $("aiPrompt").value = i18n.t('app.토리야_요약해_줘_본문_요약_요약_칸');
  if ($("aiResult")) $("aiResult").value = i18n.t('app.본문을_요약하는_중');
  ensureAiResultVisible();

  try {
    const result = await api("/api/ai/assist", {
      method: "POST",
      body: JSON.stringify({
        mode: "free",
        prompt,
        user_prompt: prompt,
        project_title: project?.title || "",
        purpose: normalizePurposeKey(state.projectPurpose || project?.purpose || "general_novel"),
        main_genre: mainGenre,
        sub_genre: subGenre,
        main_genre_label: mainGenreLabel(mainGenre),
        sub_genre_label: subGenreLabel(mainGenre, subGenre),
        keywords: normalizeKeywordList(state.keywords || project?.keywords || []),
        scene_title: state.scene?.title || $("sceneTitle")?.value || "",
        scene_synopsis: "",
        // Prompt already embeds the body; avoid duplicating a huge manuscript.
        scene_content: "",
        persona_mode: typeof getToryPersonaMode === "function" ? getToryPersonaMode() : "default",
        ...(typeof buildToryProjectContextPayload === "function" ? buildToryProjectContextPayload() : {}),
      }),
    });
    const applied = applyTorySummaryToField(result.text || "");
    if ($("aiResult")) $("aiResult").value = applied || result.text || i18n.t('app.결과_없음');
    revealAiAssistResult({ openModal: true, mode: "summarize" });
    if (applied) {
      toast(i18n.t('app.토리가_요약을_요약_칸에_넣었어요'));
    } else {
      toast(i18n.t('app.요약_응답이_비어_있어요_다시_시도해_주세요'));
    }
  } catch (error) {
    if ($("aiResult")) $("aiResult").value = "";
    handleError(error);
  } finally {
    torySceneSummaryInFlight = false;
    if (btn) {
      btn.disabled = false;
      btn.textContent = prevLabel || i18n.t('app.요약');
      btn.title = prevTitle || i18n.t('app.좌클릭_요약_목록_우클릭_토리야_요약해_줘');
    }
  }
}

function showSynopsisButtonContextMenu(clientX, clientY) {
  const btn = $("synopsisListButton");
  if (!btn) return;
  setUiFeatureCtxTarget?.(btn);
  if (typeof showUiFeatureContextMenu === "function") {
    showUiFeatureContextMenu(clientX, clientY, btn, [{
      label: i18n.t('app.토리야_요약해_줘'),
      hint: i18n.t('app.본문을_요약해_요약_칸에_넣기'),
      run: () => { runTorySceneSummary().catch(handleError); },
    }]);
  }
}

function isSynopsisListOpen() {
  return Boolean($("synopsisListModal") && !$("synopsisListModal").classList.contains("hidden"));
}

function closeSynopsisList() {
  $("synopsisListModal")?.classList.add("hidden");
}

function renderSynopsisListBody() {
  const body = $("synopsisListBody");
  if (!body) return;
  if (!state.projectId) {
    body.innerHTML = i18n.t('app.p_class_synopsis_list_e');
    return;
  }
  const items = getSynopsisSequence();
  if (!items.length) {
    body.innerHTML = i18n.t('app.p_class_synopsis_list_e_2');
    return;
  }
  const currentId = Number(state.sceneId) || 0;
  body.innerHTML = items.map((item) => {
    const text = item.synopsis
      ? escapeHtml(item.synopsis)
      : i18n.t('app.요약_없음_2');
    const emptyClass = item.synopsis ? "" : " is-empty";
    const currentClass = Number(item.sceneId) === currentId ? " is-current" : "";
    return `
      <button type="button" class="synopsis-list-item${currentClass}" data-synopsis-scene="${item.sceneId}">
        <span class="synopsis-list-index">${item.index}</span>
        <span class="synopsis-list-title">${escapeHtml(item.title)}</span>
        <span class="synopsis-list-text${emptyClass}">${text}</span>
      </button>
    `;
  }).join("");
}

async function openSynopsisList() {
  if (!state.projectId) {
    toast(i18n.t('app.작품을_먼저_선택해_주세요'));
    return;
  }
  // Refresh outline so synopses are up to date (includes synopsis_md).
  try {
    await loadProject();
  } catch (_) {
    /* show whatever we have */
  }
  // Keep live edit for current scene in the list.
  if (state.sceneId && $("sceneSynopsis")) {
    for (const chapter of state.outline || []) {
      const scene = (chapter.scenes || []).find((s) => Number(s.id) === Number(state.sceneId));
      if (scene) {
        scene.synopsis_md = $("sceneSynopsis").value || "";
        break;
      }
    }
  }
  renderSynopsisListBody();
  $("synopsisListModal")?.classList.remove("hidden");
}

function setupSynopsisList() {
  const synopsisBtn = $("synopsisListButton");
  if (synopsisBtn) {
    synopsisBtn.title = i18n.t('app.좌클릭_요약_목록_우클릭_토리야_요약해_줘');
  }
  synopsisBtn?.addEventListener("click", () => {
    openSynopsisList().catch(handleError);
  });
  if (synopsisBtn && synopsisBtn.dataset.torySummaryBound !== "1") {
    synopsisBtn.dataset.torySummaryBound = "1";
    synopsisBtn.addEventListener("contextmenu", (event) => {
      event.preventDefault();
      event.stopPropagation();
      showSynopsisButtonContextMenu(event.clientX, event.clientY);
    });
  }
  document.querySelectorAll("[data-close-synopsis-list]").forEach((el) => {
    el.addEventListener("click", closeSynopsisList);
  });
  $("synopsisListBody")?.addEventListener("click", (event) => {
    const btn = event.target.closest?.("[data-synopsis-scene]");
    if (!btn) return;
    const id = Number(btn.dataset.synopsisScene);
    if (!Number.isFinite(id) || id <= 0) return;
    closeSynopsisList();
    openScene(id).catch(handleError);
  });
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    if (!isSynopsisListOpen()) return;
    event.preventDefault();
    closeSynopsisList();
  });
  // Keep outline synopsis in sync while typing (for list view without save).
  $("sceneSynopsis")?.addEventListener("input", () => {
    if (!state.sceneId) return;
    for (const chapter of state.outline || []) {
      const scene = (chapter.scenes || []).find((s) => Number(s.id) === Number(state.sceneId));
      if (scene) {
        scene.synopsis_md = $("sceneSynopsis").value || "";
        break;
      }
    }
  });
}

function findEpisodeIndex(sceneId, sequence = getEpisodeSequence()) {
  return sequence.findIndex((ep) => Number(ep.sceneId) === Number(sceneId));
}

function formatEpisodeNavLabel(ep, fallback) {
  if (!ep) return fallback;
  // Prefer “N화” prefix when title already contains it; else “N화 제목”
  const raw = ep.label || ep.shortLabel || "";
  if (/\d+\s*화/.test(raw) || /제\s*\d+\s*화/.test(raw)) {
    return ep.shortLabel || raw;
  }
  return `${i18n.t('app.ep_index_화_ep_shortLabe', {'ep.index': ep.index, 'ep.shortLabel || raw': ep.shortLabel || raw})}`.trim();
}

/**
 * 제목 기준 레이아웃(CSS grid 1fr | auto | 1fr).
 * 이전/다음 라벨 길이와 무관하게 본문 제목이 가운데에 고정되도록
 * 예전에 넣던 인라인 width 를 지운다.
 */
function syncEpisodeNavLayout() {
  const titleEl = $("sceneTitle");
  const prevBtn = $("episodePrevButton");
  const nextBtn = $("episodeNextButton");
  if (prevBtn) prevBtn.style.maxWidth = "";
  if (nextBtn) nextBtn.style.maxWidth = "";
  if (titleEl) {
    titleEl.style.flex = "";
    titleEl.style.minWidth = "";
    titleEl.style.maxWidth = "";
    titleEl.style.width = "";
  }
}

let episodeNavLayoutTimer = null;
function scheduleEpisodeNavLayout() {
  if (episodeNavLayoutTimer) window.clearTimeout(episodeNavLayoutTimer);
  episodeNavLayoutTimer = window.setTimeout(() => {
    episodeNavLayoutTimer = null;
    syncEpisodeNavLayout();
  }, 16);
}

function upsertEpisodeTab(sceneId, title = "") {
  const id = Number(sceneId);
  if (!Number.isFinite(id) || id <= 0) return;
  const label = String(title || "").trim() || `${i18n.t('app.씬_id', {id: id})}`;
  const tabs = Array.isArray(state.episodeTabs) ? [...state.episodeTabs] : [];
  const existing = tabs.find((t) => Number(t.sceneId) === id);
  if (existing) {
    existing.title = label || existing.title;
  } else {
    tabs.push({ sceneId: id, title: label });
    while (tabs.length > EPISODE_TABS_MAX) tabs.shift();
  }
  state.episodeTabs = tabs;
  saveEpisodeTabsToStorage();
}

function closeEpisodeTab(sceneId) {
  const id = Number(sceneId);
  const tabs = (state.episodeTabs || []).filter((t) => Number(t.sceneId) !== id);
  const wasActive = Number(state.sceneId) === id;
  state.episodeTabs = tabs;
  saveEpisodeTabsToStorage();
  renderEpisodeChrome();
  if (!wasActive) return;
  // Switch to nearest remaining tab, or leave editor.
  if (tabs.length) {
    const next = tabs[tabs.length - 1];
    openScene(next.sceneId).catch(handleError);
  } else {
    // Keep workspace but no scene — go welcome for this project.
    void (async () => {
      if (sceneDirty) {
        try {
          cancelScheduledAutoSave();
          await persistScene({ quiet: true, saveNote: i18n.t('app.자동_저장') });
        } catch (_) { /* ignore */ }
      }
      state.sceneId = null;
      state.scene = null;
      showWelcome();
    })();
  }
}

function renderEpisodeChrome() {
  const chrome = $("episodeChrome");
  const tabBar = $("episodeTabBar");
  const prevBtn = $("episodePrevButton");
  const nextBtn = $("episodeNextButton");
  const prevLabel = $("episodePrevLabel");
  const nextLabel = $("episodeNextLabel");
  if (!chrome) return;

  const inScene = Boolean(state.sceneId) && !$("sceneWorkspace")?.classList.contains("hidden");
  chrome.classList.toggle("hidden", !inScene);
  if (!inScene) return;

  const sequence = getEpisodeSequence();
  const idx = findEpisodeIndex(state.sceneId, sequence);
  const prev = idx > 0 ? sequence[idx - 1] : null;
  const next = idx >= 0 && idx < sequence.length - 1 ? sequence[idx + 1] : null;

  if (prevBtn) {
    prevBtn.disabled = !prev;
    prevBtn.title = prev ? `${i18n.t('app.이전_회차_prev_label', {'prev.label': prev.label})}` : i18n.t('app.이전_회차_없음');
  }
  if (nextBtn) {
    nextBtn.disabled = !next;
    nextBtn.title = next ? `${i18n.t('app.다음_회차_next_label', {'next.label': next.label})}` : i18n.t('app.다음_회차_없음');
  }
  if (prevLabel) prevLabel.textContent = prev ? formatEpisodeNavLabel(prev, i18n.t('app.이전')) : i18n.t('app.이전_회차');
  if (nextLabel) nextLabel.textContent = next ? formatEpisodeNavLabel(next, i18n.t('app.다음')) : i18n.t('app.다음_회차');
  // Recalc side widths so a long center title squeezes prev/next labels.
  scheduleEpisodeNavLayout();

  // Tabs
  if (tabBar) {
    const validIds = new Set(sequence.map((ep) => ep.sceneId));
    // Drop tabs for deleted scenes
    const tabs = (state.episodeTabs || []).filter((t) => validIds.has(Number(t.sceneId)));
    if (tabs.length !== (state.episodeTabs || []).length) {
      state.episodeTabs = tabs;
      saveEpisodeTabsToStorage();
    }
    // Refresh titles from sequence when possible
    const titleById = new Map(sequence.map((ep) => [ep.sceneId, ep.shortLabel || ep.label]));
    tabBar.innerHTML = tabs.map((tab) => {
      const id = Number(tab.sceneId);
      const title = titleById.get(id) || tab.title || `${i18n.t('app.씬_id', {id: id})}`;
      const active = id === Number(state.sceneId);
      return `
        <div class="episode-tab${active ? " is-active" : ""}" role="tab" aria-selected="${active ? "true" : "false"}" data-episode-tab="${id}" title="${escapeHtml(title)}">
          <span class="episode-tab-title">${escapeHtml(title)}</span>
          <button type="button" class="episode-tab-close" data-episode-close="${id}" title="${i18n.t('app.탭_닫기')}" aria-label="${i18n.t('app.탭_닫기')}">×</button>
        </div>`;
    }).join("");
  }
}

function setupEpisodeChrome() {
  loadEpisodeTabsFromStorage();
  $("episodePrevButton")?.addEventListener("click", () => {
    const sequence = getEpisodeSequence();
    const idx = findEpisodeIndex(state.sceneId, sequence);
    if (idx > 0) openScene(sequence[idx - 1].sceneId).catch(handleError);
  });
  $("episodeNextButton")?.addEventListener("click", () => {
    const sequence = getEpisodeSequence();
    const idx = findEpisodeIndex(state.sceneId, sequence);
    if (idx >= 0 && idx < sequence.length - 1) {
      openScene(sequence[idx + 1].sceneId).catch(handleError);
    }
  });
  // Live: long center title shrinks prev/next labels
  $("sceneTitle")?.addEventListener("input", scheduleEpisodeNavLayout);
  window.addEventListener("resize", scheduleEpisodeNavLayout);
  $("episodeTabBar")?.addEventListener("click", (event) => {
    const closeId = event.target.closest?.("[data-episode-close]")?.dataset?.episodeClose;
    if (closeId) {
      event.preventDefault();
      event.stopPropagation();
      closeEpisodeTab(Number(closeId));
      return;
    }
    const tab = event.target.closest?.("[data-episode-tab]");
    if (!tab) return;
    const id = Number(tab.dataset.episodeTab);
    if (id && id !== Number(state.sceneId)) openScene(id).catch(handleError);
  });
  // Middle-click closes tab (browser-like).
  $("episodeTabBar")?.addEventListener("auxclick", (event) => {
    if (event.button !== 1) return;
    const tab = event.target.closest?.("[data-episode-tab]");
    if (!tab) return;
    event.preventDefault();
    closeEpisodeTab(Number(tab.dataset.episodeTab));
  });
  renderEpisodeChrome();
}

function showSceneEditorPane() {
  state.ideaBoardOpen = false;
  state.characterBoardOpen = false;
  state.keywordBoardOpen = false;
  hideSettingsCollectionBoard();
  hideGitsiWorkspace();
  hideSettingsSearchBoard();
  $("welcome")?.classList.add("hidden");
  $("ideaBoard")?.classList.add("hidden");
  $("keywordBoard")?.classList.add("hidden");
  $("characterBoard")?.classList.add("hidden");
  hideRelationCanvas();
  $("characterEditor")?.classList.add("hidden");
  hideItemViews();
  hideSynopsisMain();
  const workspace = $("sceneWorkspace");
  if (workspace) {
    workspace.classList.remove("hidden");
    // Solo edit mode unless split is intentionally on.
    if (!state.splitEnabled || state.splitMode !== "split") {
      workspace.classList.remove("split-active");
    }
  }
  if (!state.splitEnabled) {
    const viewer = $("splitViewer");
    if (viewer) {
      viewer.classList.add("hidden");
      viewer.classList.remove("popup-mode");
    }
    $("splitPaneResizer")?.classList.add("hidden");
  }
  closeSceneToolsDrawer();
  // Restore full editor chrome (title / format / feature bar / body)
  if (!(state.splitEnabled && state.splitMode === "split")) {
    clearSplitPrimaryPaneLayout();
  }
  const form = $("sceneEditor");
  if (form) {
    form.scrollTop = 0;
  }
  ["episode-chrome", "editor-meta", "format-toolbar", "scene-feature-bar", "writing-block", "manuscript-status-bar"].forEach((cls) => {
    document.querySelectorAll(`#sceneWorkspace .${cls}`).forEach((el) => {
      if (!(state.splitEnabled && state.splitMode === "split")) {
        el.style.removeProperty("display");
        el.style.removeProperty("visibility");
        el.style.removeProperty("max-height");
        el.style.removeProperty("height");
        el.style.removeProperty("min-height");
        el.style.removeProperty("flex");
        el.style.removeProperty("overflow");
      }
      el.classList.remove("hidden");
    });
  });
  renderEpisodeChrome();
  const editor = $("sceneContent");
  if (editor) {
    editor.setAttribute("contenteditable", "true");
    editor.setAttribute("spellcheck", "true");
    editor.removeAttribute("readonly");
    editor.removeAttribute("disabled");
    editor.style.pointerEvents = "auto";
    editor.style.userSelect = "text";
    editor.style.display = "block";
    editor.style.visibility = "visible";
    editor.tabIndex = 0;
  }
}

function fillSceneEditorFields(scene) {
  suppressSceneDirty = true;
  if ($("sceneTitle")) $("sceneTitle").value = scene.title || "";
  if ($("sceneStatus")) $("sceneStatus").value = scene.status || "idea";
  lastPersistedSceneStatus = scene.status || "idea";
  syncViewerReaderCommentsButton();
  if (lastPersistedSceneStatus !== "complete") {
    if (viewerCommentsOpen) setViewerCommentsOpen(false);
  } else if (viewerCommentsOpen && typeof isViewerOpen === "function" && isViewerOpen()) {
    loadViewerReaderComments({ startIfNeeded: true }).catch(() => {});
  }
  if ($("sceneSynopsis")) $("sceneSynopsis").value = scene.synopsis_md || "";
  setEditorContent(scene.content_md || "");
  if ($("sceneNotes")) $("sceneNotes").value = scene.notes_md || "";
  updateAuthorNotesBadge();
  updateReferenceMaterialsBadge();
  if ($("sceneGoalMetric")) {
    $("sceneGoalMetric").value = scene.goal_metric && COUNT_METRIC_LABEL[scene.goal_metric]
      ? scene.goal_metric
      : "chars_with_space";
  }
  if ($("sceneGoalCount")) $("sceneGoalCount").value = String(scene.goal_word_count || 0);
  if (!isProjectStatsScope() && $("statsGoalInput")) {
    $("statsGoalInput").value = String(scene.goal_word_count || 0);
  }
  sceneDirty = false;
  suppressSceneDirty = false;
}

async function openScene(sceneId, options = {}) {
  const nextId = Number(sceneId);
  if (!Number.isFinite(nextId) || nextId <= 0) {
    toast(i18n.t('app.씬을_열_수_없어요'));
    return;
  }
  if (
    typeof isGlumpSprintActive === "function"
    && isGlumpSprintActive()
    && Number(state.sceneId)
    && Number(state.sceneId) !== nextId
    && !confirmLeaveGlumpSprint()
  ) {
    return;
  }

  // Flush pending edits before leaving the current scene.
  if (sceneDirty && state.sceneId && state.sceneId !== nextId) {
    ensureLocalDraftSaved("scene-switch");
    cancelScheduledAutoSave();
    try {
      await persistScene({ quiet: true, saveNote: i18n.t('app.자동_저장') });
    } catch (_) {
      /* local draft kept for previous scene; continue */
    }
  }
  try {
    await flushPendingCodexSaves();
  } catch (_) {
    /* continue into the scene */
  }

  if (!options.keepBinder) {
    setActiveBinder("manuscript");
  }
  const previousSceneId = state.sceneId;
  if (!options.keepCharacter) {
    state.characterId = null;
  }

  let detail;
  let members;
  let openedFromLocalOnly = false;
  try {
    // Show shell immediately so the center is never a blank dead pane.
    showSceneEditorPane();
    detail = await api(`/api/scenes/${nextId}`);
    try {
      members = await api(`/api/scenes/${nextId}/characters`);
    } catch (_) {
      members = [];
    }
  } catch (error) {
    // Offline / server down: open local draft if we have one so work is never stranded.
    const draft = await readLocalSceneDraft(nextId);
    if (draft && (draft.content_md != null || draft.title)) {
      openedFromLocalOnly = true;
      detail = {
        id: nextId,
        title: draft.title || `${i18n.t('app.씬_nextId', {nextId: nextId})}`,
        status: draft.status || "draft",
        synopsis_md: draft.synopsis_md || "",
        notes_md: draft.notes_md || "",
        content_md: draft.content_md || "",
        reference_links: Array.isArray(draft.reference_links) ? draft.reference_links : [],
        goal_word_count: draft.goal_word_count || 0,
        goal_metric: draft.goal_metric || "chars_with_space",
        row_version: draft.row_version ?? 0,
        word_count: 0,
        revision_no: 0,
        illustrations: [],
      };
      members = [];
      toast(i18n.t('app.서버에_연결할_수_없어_이_기기에_보관된_원'));
    } else {
      handleError(error);
      return;
    }
  }

  state.sceneId = nextId;
  state.scene = detail;
  state.sceneMembers = members || [];
  sceneCastSuppressedIds.clear();
  sceneCastExtraIds.clear();
  resetSceneCastCandidates();
  sceneCastDirty = false;
  state.illustrations = detail.illustrations || [];
  state.referenceLinks = Array.isArray(detail.reference_links)
    ? detail.reference_links.map((link) => normalizeReferenceItem(link))
    : [];
  if (detail.project_purpose) state.projectPurpose = normalizePurposeKey(detail.project_purpose);

  if (state.splitEnabled && state.splitSceneId === state.sceneId && previousSceneId) {
    state.splitSceneId = previousSceneId;
  }

  cancelScheduledAutoSave();
  showSceneEditorPane();
  fillSceneEditorFields(detail);
  if (!openedFromLocalOnly) {
    await maybeRestoreLocalDraft(detail);
  } else {
    sceneDirty = true;
    setSceneSaveStatus(i18n.t('app.오프라인_보관본_연결_시_동기화'));
    scheduleAutoSave();
  }
  syncOpeningHintForScene(nextId);
  // Per-episode page color (if set) vs project-wide default
  if (typeof refreshManuscriptPageTheme === "function") {
    refreshManuscriptPageTheme();
  }
  // 떡밥·수동 알림 (토리 팝업) + 알림 센터 현재 회차 표시
  if (typeof maybeNotifyBaitRecovery === "function") {
    maybeNotifyBaitRecovery(nextId);
  }
  if (typeof renderToryNotifyList === "function") {
    renderToryNotifyList();
  }
  // Baseline length so loading a scene does not count as "chars written".
  writingTracker.lastPlainLen = (getEditorPlainText() || "").length;
  // Register / update browser-like episode tab for this scene.
  const tabTitle = detail.title
    || detail.chapter_title
    || $("sceneTitle")?.value
    || `${i18n.t('app.씬_nextId', {nextId: nextId})}`;
  upsertEpisodeTab(nextId, tabTitle);
  // Prefer chapter title from outline when available.
  const ep = getEpisodeSequence().find((e) => e.sceneId === nextId);
  if (ep?.label) upsertEpisodeTab(nextId, ep.shortLabel || ep.label);
  renderEpisodeChrome();
  renderSceneCharacters();
  const openedCast = detectKnownSceneCast(getEditorPlainText() || "", state.characters || []);
  (state.sceneMembers || []).forEach((member) => {
    const id = Number(member.character_id);
    if (!id || openedCast.has(id)) return;
    if (memberAppearanceKind(member) === "mentioned") return;
    sceneCastExtraIds.add(id);
  });
  void syncSceneCastFromManuscript({ quiet: true });
  renderIllustrations();
  renderReferenceLinks();
  updateSceneStats();
  updateSplitChrome();
  saveLastWorkspace({ projectId: state.projectId, sceneId: nextId });
  applySplitLayout();

  // Re-apply find highlights on the newly loaded scene if the find bar is open.
  if (!$("findBar")?.classList.contains("hidden")) {
    const q = $("findInput")?.value || "";
    if (q) runFindInEditor(q);
    else {
      findMatches = [];
      findIndex = -1;
      updateFindCountUi();
    }
  } else {
    findMatches = [];
    findIndex = -1;
  }

  // Focus manuscript so typing works immediately.
  requestAnimationFrame(() => {
    if (options.skipEditorFocus || isOutlineInlineRenaming()) return;
    const editor = $("sceneContent");
    if (!editor) return;
    editor.setAttribute("contenteditable", "true");
    // Keep focus on find input when searching.
    if (!$("findBar")?.classList.contains("hidden") && document.activeElement === $("findInput")) {
      return;
    }
    try {
      editor.focus({ preventScroll: true });
    } catch (_) {
      editor.focus();
    }
  });

  // Refresh outline highlight without blocking the editor.
  if (!options.skipOutlineReload && !isOutlineInlineRenaming()) {
    loadProject().then(() => {
      if (isOutlineInlineRenaming()) return;
      // Outline refresh may update episode labels (chapter renames).
      const refreshed = getEpisodeSequence().find((e) => e.sceneId === nextId);
      if (refreshed?.label) upsertEpisodeTab(nextId, refreshed.shortLabel || refreshed.label);
      renderEpisodeChrome();
    }).catch(handleError);
  }
  if (state.splitEnabled) {
    renderSplitViewer().catch(handleError);
  }
}

const CHARACTER_ROLE_LABELS = {
  protagonist: i18n.t('app.주인공'),
  antagonist: i18n.t('app.대립'),
  supporting: i18n.t('app.조연'),
  minor: i18n.t('app.단역'),
};

function getSelectedSceneCharacterIds() {
  return [...document.querySelectorAll("#sceneCharacterList input[type='checkbox']:checked")]
    .map((input) => Number(input.value))
    .filter((id) => Number.isFinite(id) && id > 0);
}

function memberAppearanceKind(member) {
  return String(member?.appearance_role || "") === "mentioned" ? "mentioned" : "appears";
}

function sceneAppearingCount(members = state.sceneMembers) {
  return (Array.isArray(members) ? members : []).filter((item) => memberAppearanceKind(item) !== "mentioned").length;
}

function sceneMentionedCount(members = state.sceneMembers) {
  return (Array.isArray(members) ? members : []).filter((item) => memberAppearanceKind(item) === "mentioned").length;
}

function getSceneCastMembersFromDom() {
  const members = [];
  const seen = new Set();
  document.querySelectorAll("#sceneCharacterList input[type='checkbox']:checked").forEach((input) => {
    const id = Number(input.value);
    if (!Number.isFinite(id) || id <= 0 || seen.has(id)) return;
    seen.add(id);
    members.push({
      character_id: id,
      appearance_role: input.dataset.castKind === "mentioned" ? "mentioned" : "supporting",
    });
  });
  return members;
}

const SCENE_CAST_MENTION_HINTS = [
  "떠올", "생각났", "생각이 났", "생각이 들", "기억", "소문", "얘기", "이야기",
  "말하길", "전해", "들었대", "들었다더", "소식", "언급", "이름만", "이름이 나",
  "에 대해", "에 대한", "그리워", "보고 싶", "행방", "자취", "어디지", "어디에",
  "누구냐", "누구였",
];
const SCENE_CAST_APPEAR_AFTER = /^(은|는|이|가|도|만)?\s*(말했|말했어|말한다|말하며|물었|물었어|되물|대답|답했|중얼|외쳤|소리쳤|웃었|미소|고개를|앉아|앉았|일어|걸어|걸었|달려|달렸|들어왔|들어와|나갔|나타났|자리에|손을 |문을 |검을 |칼을 |눈을 |바라보|쳐다|돌아섰|다가왔|다가갔|내밀|잡았|열었|닫았|끄덕|한숨|침묵|주먹을|뛰었|피했|막았|던졌|보았|봤다|보고|들었|듣고|불렀|찾았|기다려|기다렸|울었|울며|나섰|향했|멈췄|돌아보|속삭|입을 |말을 )/;
const SCENE_CAST_AFTER_OK = /^(은|는|이|가|을|를|의|도|만|과|와|랑|야|아|여|께|에게|한테|으로|로|부터|까지|이었|였|이다|이야|이라고|이며|이고|[ \n\t.,!?…~“”"'』」)\]：:]|$)/;

function sceneCastLabels(character) {
  const names = [];
  const seen = new Set();
  const raw = [character?.name, ...(Array.isArray(character?.aliases) ? character.aliases : [])];
  raw.forEach((item) => {
    const text = String(item?.alias || item || "").trim();
    if (!text) return;
    const key = text.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    names.push(text);
  });
  names.sort((a, b) => b.length - a.length);
  return names;
}

function classifySceneCastHit(text, start, end, name = "") {
  const left = text.slice(Math.max(0, start - 28), start);
  const right = text.slice(end, end + 36);
  let sentenceStart = start;
  for (let i = start - 1; i >= 0 && start - i <= 90; i -= 1) {
    if (".\n!?。…".includes(text[i])) {
      sentenceStart = i + 1;
      break;
    }
    if (i === 0) sentenceStart = 0;
  }
  let sentenceEnd = Math.min(text.length, end + 90);
  for (let i = end; i < sentenceEnd; i += 1) {
    if (".\n!?。…".includes(text[i])) {
      sentenceEnd = i;
      break;
    }
  }
  const sentence = text.slice(sentenceStart, sentenceEnd);
  if (/[”"』」]\s*$/.test(left) && SCENE_CAST_APPEAR_AFTER.test(right)) return "appears";
  if (SCENE_CAST_APPEAR_AFTER.test(right)) return "appears";
  if (SCENE_CAST_MENTION_HINTS.some((hint) => sentence.includes(hint))) return "mentioned";
  if (/^[은는이가도만을를에게한테]/.test(right || "")) return "appears";
  return "mentioned";
}

function detectKnownSceneCast(text, characters) {
  const found = new Map();
  const occupied = new Array(String(text || "").length).fill(false);
  const labeled = [];
  (characters || []).forEach((character) => {
    const id = Number(character?.id);
    if (!id) return;
    const spans = [];
    sceneCastLabels(character).forEach((name) => {
      let from = 0;
      while (from < text.length) {
        const index = text.indexOf(name, from);
        if (index < 0) break;
        const end = index + name.length;
        const prev = index > 0 ? text[index - 1] : "";
        if (/[가-힣]/.test(prev)) {
          from = index + 1;
          continue;
        }
        if (!SCENE_CAST_AFTER_OK.test(text.slice(end))) {
          from = index + 1;
          continue;
        }
        spans.push([index, end, name]);
        from = index + 1;
      }
    });
    if (spans.length) labeled.push({ id, spans });
  });
  labeled.sort((a, b) => {
    const la = Math.max(0, ...a.spans.map(([s, e]) => e - s));
    const lb = Math.max(0, ...b.spans.map(([s, e]) => e - s));
    return lb - la;
  });
  labeled.forEach(({ id, spans }) => {
    const kinds = new Set();
    spans.forEach(([start, end, name]) => {
      let taken = false;
      for (let i = start; i < end; i += 1) {
        if (occupied[i]) taken = true;
      }
      if (taken) return;
      for (let i = start; i < end; i += 1) occupied[i] = true;
      kinds.add(classifySceneCastHit(text, start, end, name));
    });
    if (kinds.has("appears")) found.set(id, "appears");
    else if (kinds.has("mentioned")) found.set(id, "mentioned");
  });
  return found;
}

function applyKnownCastPreview() {
  if (!state.sceneId || sceneCastDirty || sceneCastSyncInFlight) return;
  const text = getEditorPlainText() || "";
  const found = detectKnownSceneCast(text, state.characters || []);
  const prevPov = Number((state.sceneMembers || []).find((item) => Number(item.is_pov))?.character_id || 0);
  const members = [];
  const seen = new Set();
  found.forEach((kind, id) => {
    const cid = Number(id);
    if (sceneCastSuppressedIds.has(cid)) return;
    if (kind === "mentioned") return;
    seen.add(cid);
    members.push({
      character_id: cid,
      appearance_role: cid === prevPov ? "primary" : "supporting",
      is_pov: cid === prevPov ? 1 : 0,
    });
  });
  sceneCastExtraIds.forEach((id) => {
    const cid = Number(id);
    if (!cid || seen.has(cid) || sceneCastSuppressedIds.has(cid)) return;
    seen.add(cid);
    members.push({
      character_id: cid,
      appearance_role: cid === prevPov ? "primary" : "supporting",
      is_pov: cid === prevPov ? 1 : 0,
    });
  });
  state.sceneMembers = members;
  renderSceneCharacters();
}

function scheduleKnownCastPreview() {
  if (sceneCastPreviewTimer) window.clearTimeout(sceneCastPreviewTimer);
  sceneCastPreviewTimer = window.setTimeout(() => {
    sceneCastPreviewTimer = null;
    applyKnownCastPreview();
  }, 280);
}

function updateSceneCharactersBadge() {
  const badge = $("sceneCharactersCount");
  const chip = $("sceneCharactersChip");
  if (!badge) return;
  if (!state.sceneId) {
    badge.textContent = "";
    badge.classList.add("hidden");
    if (chip) {
      chip.title = i18n.t('app.이_회차에_등장하는_인물_연결');
      chip.setAttribute("aria-label", i18n.t('app.등장_인물'));
    }
    return;
  }
  const appears = sceneAppearingCount();
  const n = appears;
  if (!n) {
    badge.textContent = "";
    badge.classList.add("hidden");
    if (chip) {
      chip.title = i18n.t('app.이_회차에_등장하는_인물_연결');
      chip.setAttribute("aria-label", i18n.t('app.등장_인물'));
    }
    return;
  }
  badge.textContent = n > 99 ? "99+" : String(n);
  badge.classList.remove("hidden");
  if (chip) {
    const title = i18n.t("app.등장_인물_n_명_연결됨", { n: appears });
    chip.title = title;
    chip.setAttribute("aria-label", title);
  }
}

function renderSceneCastRow(character, kind, linked) {
  const id = Number(character.id);
  const role = CHARACTER_ROLE_LABELS[character.role] || character.role || "";
  const name = escapeHtml(character.name || i18n.t("app.이름_없음"));
  const kindLabel = kind === "mentioned" ? i18n.t("app.언급") : i18n.t("app.등장");
  return `
    <label class="scene-cast-item${linked ? " is-linked" : ""}${kind === "mentioned" ? " is-mentioned" : ""}" data-cast-id="${id}" data-cast-kind="${kind}">
      <input type="checkbox" value="${id}" data-cast-kind="${kind}" ${linked ? "checked" : ""} aria-label="${name} ${kindLabel}">
      <span class="scene-cast-name" title="${name}">${name}</span>
      <span class="scene-cast-kind">${escapeHtml(kindLabel)}</span>
      ${role ? `<span class="scene-cast-role">${escapeHtml(role)}</span>` : ""}
      <button type="button" class="secondary scene-cast-open" data-open-character="${id}" title="${i18n.t("app.인물_설정_열기")}">${i18n.t("index.설정")}</button>
    </label>`;
}

function renderSceneCharacters() {
  const list = $("sceneCharacterList");
  const povSelect = $("povSelect");
  if (!list) return;

  const members = Array.isArray(state.sceneMembers) ? state.sceneMembers : [];
  const kindById = new Map(
    members.map((member) => [Number(member.character_id), memberAppearanceKind(member)]),
  );
  const povId = Number(members.find((member) => member.is_pov)?.character_id || 0) || "";
  const characters = Array.isArray(state.characters) ? state.characters : [];

  if (!characters.length) {
    list.innerHTML = `
      <p class="scene-characters-empty">
        아직 만든 인물이 없어요.<br>
        <strong>+ 인물</strong>을 누르면 인물 작성 페이지로 이동합니다.
      </p>`;
  } else {
    const appearing = [];
    const rest = [];
    characters.forEach((character) => {
      const kind = kindById.get(Number(character.id));
      if (kind === "appears") appearing.push(character);
      else rest.push(character);
    });
    const blocks = [];
    blocks.push(`<div class="scene-cast-group"><p class="scene-cast-group-title">${i18n.t("app.등장")}</p>`);
    if (!appearing.length && !rest.length) {
      blocks.push(`<p class="scene-cast-empty-line">${i18n.t("app.이_회차에_등장한_인물이_없어요")}</p>`);
    } else {
      appearing.forEach((character) => blocks.push(renderSceneCastRow(character, "appears", true)));
      rest.forEach((character) => blocks.push(renderSceneCastRow(character, "appears", false)));
    }
    blocks.push("</div>");
    list.innerHTML = blocks.join("");
  }

  if (povSelect) {
    const linkedAppearing = characters.filter((c) => kindById.get(Number(c.id)) === "appears");
    const pool = linkedAppearing.length ? linkedAppearing : characters;
    povSelect.innerHTML = `<option value="">${i18n.t('index.시점_인물_없음')}</option>${
      pool.map((character) => {
        const id = Number(character.id);
        const selected = Number(povId) === id ? "selected" : "";
        return `<option value="${id}" ${selected}>${escapeHtml(character.name || `인물 #${id}`)}</option>`;
      }).join("")
    }`;
    if (povId && !pool.some((c) => Number(c.id) === Number(povId))) {
      const orphan = characters.find((c) => Number(c.id) === Number(povId));
      if (orphan) {
        const opt = document.createElement("option");
        opt.value = String(povId);
        opt.selected = true;
        opt.textContent = orphan.name || `${i18n.t('app.인물_povId', {povId: povId})}`;
        povSelect.appendChild(opt);
      }
    }
  }
  updateSceneCharactersBadge();
  if (!sceneCastDirty) {
    setSceneCastSaveUi({ dirty: false });
  } else {
    setSceneCastSaveUi({ dirty: true });
  }
}

async function refreshSceneCharactersPanel() {
  if (!state.projectId || !state.sceneId) {
    renderSceneCharacters();
    return;
  }
  try {
    const [characters, members] = await Promise.all([
      api(`/api/projects/${state.projectId}/characters`),
      api(`/api/scenes/${state.sceneId}/characters`).catch(() => []),
    ]);
    if (Array.isArray(characters)) state.characters = characters;
    state.sceneMembers = Array.isArray(members) ? members : [];
  } catch (error) {
    console.warn("[supertory] cast panel refresh failed", error);
  }
  sceneCastDirty = false;
  renderSceneCharacters();
  setSceneCastSaveUi({ dirty: false });
}

let sceneCastSaveInFlight = false;
let sceneCastSaveAgain = false;
let sceneCastDirty = false;
let sceneCastSyncInFlight = false;
let sceneCastPreviewTimer = null;
const sceneCastSuppressedIds = new Set();
const sceneCastExtraIds = new Set();
let sceneCastCandidates = [];
let sceneCastCandidateStatus = "idle";
let sceneCastCandidateTimer = null;
let sceneCastCandidateGen = 0;
const sceneCastDismissedCandidates = new Set();

function resetSceneCastCandidates() {
  sceneCastCandidateGen += 1;
  if (sceneCastCandidateTimer) {
    window.clearTimeout(sceneCastCandidateTimer);
    sceneCastCandidateTimer = null;
  }
  sceneCastCandidates = [];
  sceneCastCandidateStatus = "idle";
  sceneCastDismissedCandidates.clear();
  renderSceneCastCandidates();
}

function scheduleSceneCastCandidates() {
  if (!state.sceneId || !state.projectId) return;
  if (sceneCastCandidateTimer) window.clearTimeout(sceneCastCandidateTimer);
  sceneCastCandidateTimer = window.setTimeout(() => {
    sceneCastCandidateTimer = null;
    refreshSceneCastCandidates().catch(() => { /* quiet */ });
  }, 400);
}

function renderSceneCastCandidates() {
  const panel = $("sceneCastCandidatePanel");
  const list = $("sceneCastCandidateList");
  const statusEl = $("sceneCastCandidateStatus");
  if (!panel || !list) return;
  const names = sceneCastCandidates.filter((name) => !sceneCastDismissedCandidates.has(String(name).toLowerCase()));
  const loading = sceneCastCandidateStatus === "loading";
  const show = loading || names.length > 0;
  panel.classList.toggle("hidden", !show);
  if (statusEl) {
    if (loading) statusEl.textContent = i18n.t("index.새_이름을_찾고_있어요");
    else if (!names.length) statusEl.textContent = "";
    else statusEl.textContent = "";
  }
  if (!names.length) {
    list.innerHTML = "";
    return;
  }
  list.innerHTML = names.map((name) => {
    const safe = escapeHtml(name);
    const token = encodeURIComponent(name);
    return `<div class="scene-cast-candidate-row">
      <span class="scene-cast-name" title="${safe}">${safe}</span>
      <button type="button" class="secondary compact-btn" data-add-cast-candidate="${token}">${i18n.t("index.이_회차에_추가")}</button>
    </div>`;
  }).join("");
}

async function refreshSceneCastCandidates() {
  if (!state.sceneId || !state.projectId) return;
  const gen = ++sceneCastCandidateGen;
  const sceneId = state.sceneId;
  sceneCastCandidateStatus = "loading";
  renderSceneCastCandidates();
  try {
    const result = await api(`/api/scenes/${sceneId}/cast-candidates`, {
      method: "POST",
      body: JSON.stringify({ content_md: getEditorContent() || "" }),
    });
    if (gen !== sceneCastCandidateGen || Number(state.sceneId) !== Number(sceneId)) return;
    const incoming = Array.isArray(result?.candidates) ? result.candidates : [];
    const known = new Set(
      (state.characters || []).flatMap((item) => {
        const labels = [item?.name, ...(Array.isArray(item?.aliases) ? item.aliases : [])];
        return labels.map((label) => String(label?.alias || label || "").trim().toLowerCase()).filter(Boolean);
      }),
    );
    sceneCastCandidates = incoming.filter((name) => {
      const key = String(name || "").trim().toLowerCase();
      return key && !known.has(key) && !sceneCastDismissedCandidates.has(key);
    });
    sceneCastCandidateStatus = sceneCastCandidates.length ? "ready" : "empty";
  } catch (_) {
    if (gen !== sceneCastCandidateGen) return;
    sceneCastCandidates = [];
    sceneCastCandidateStatus = "idle";
  }
  renderSceneCastCandidates();
}

async function addSceneCastCandidate(name) {
  const displayName = String(name || "").trim();
  if (!displayName || !state.projectId || !state.sceneId) return;
  const character = await api(`/api/projects/${state.projectId}/characters`, {
    method: "POST",
    body: JSON.stringify({ name: displayName, role: "minor" }),
  });
  const newId = Number(character?.id);
  if (!newId) {
    toast(i18n.t("app.인물을_만들지_못했어요_다시_시도해_주세요"));
    return;
  }
  sceneCastDismissedCandidates.add(displayName.toLowerCase());
  sceneCastCandidates = sceneCastCandidates.filter((item) => String(item).toLowerCase() !== displayName.toLowerCase());
  if (!Array.isArray(state.characters)) state.characters = [];
  if (!state.characters.some((item) => Number(item.id) === newId)) {
    state.characters.push({
      ...character,
      short_description: character.short_description || "",
      profile_md: character.profile_md || "",
      aliases: character.aliases || [],
    });
  }
  try { renderCharacters(); } catch (_) { /* ignore */ }
  sceneCastExtraIds.add(newId);
  sceneCastSuppressedIds.delete(newId);
  const prev = Array.isArray(state.sceneMembers) ? state.sceneMembers : [];
  if (!prev.some((item) => Number(item.character_id) === newId)) {
    state.sceneMembers = [...prev, { character_id: newId, appearance_role: "supporting", is_pov: 0 }];
  }
  renderSceneCharacters();
  renderSceneCastCandidates();
  await persistSceneCharacterLinks({ quiet: true });
  toast(i18n.t("app.names_을_를_인물로_저장했어요", { names: displayName }));
}

function setSceneCastSaveUi({ dirty = sceneCastDirty, saving = false, error = false, ok = false, message = "" } = {}) {
  const hint = $("sceneCharacterSaveHint");
  const btn = $("sceneCharacterSaveButton");
  sceneCastDirty = Boolean(dirty);
  if (hint) {
    hint.classList.toggle("is-dirty", Boolean(dirty) && !saving && !error && !ok);
    hint.classList.toggle("is-error", Boolean(error));
    hint.classList.toggle("is-ok", Boolean(ok) && !error);
    if (message) {
      hint.textContent = message;
    } else if (saving) {
      hint.textContent = i18n.t('app.등장_인물_연결을_저장하는_중');
    } else if (error) {
      hint.textContent = i18n.t('app.저장에_실패했어요_다시_저장을_눌러_주세요');
    } else if (dirty) {
      hint.textContent = i18n.t('app.변경됨_저장을_눌러_이_회차에_반영하세요');
    } else if (ok) {
      hint.textContent = i18n.t('app.저장됨');
    } else {
      const appears = sceneAppearingCount();
      hint.textContent = appears
        ? i18n.t("app.등장_인물_n_명_연결됨", { n: appears })
        : i18n.t('app.인물을_체크한_뒤_저장을_눌러_주세요');
    }
  }
  if (btn) {
    btn.disabled = saving || (!dirty && !error);
    btn.textContent = saving ? i18n.t('app.저장_중') : i18n.t('app.저장');
    btn.title = dirty
      ? i18n.t('app.체크한_등장_인물_시점_연결을_이_회차에_저')
      : i18n.t('app.저장할_변경이_없어요');
  }
}

function markSceneCastDirty() {
  setSceneCastSaveUi({
    dirty: true,
    message: i18n.t('app.변경됨_저장을_눌러_이_회차에_반영하세요'),
  });
}

async function persistSceneCharacterLinks(options = {}) {
  const quiet = Boolean(options.quiet);
  if (!state.sceneId) {
    toast(i18n.t('app.먼저_회차를_열어_주세요'));
    return null;
  }
  if (sceneCastSaveInFlight) {
    sceneCastSaveAgain = true;
    return null;
  }
  const characterIds = getSelectedSceneCharacterIds();
  const members = getSceneCastMembersFromDom();
  let povId = $("povSelect")?.value || "";
  // POV must be one of the appearing cast (or empty).
  const appearingIds = members
    .filter((item) => item.appearance_role !== "mentioned")
    .map((item) => Number(item.character_id));
  if (povId && !appearingIds.includes(Number(povId))) {
    povId = "";
    if ($("povSelect")) $("povSelect").value = "";
  }
  sceneCastSaveInFlight = true;
  sceneCastSaveAgain = false;
  setSceneCastSaveUi({ dirty: true, saving: true, message: i18n.t('app.등장_인물_연결을_저장하는_중') });
  try {
    await api(`/api/scenes/${state.sceneId}/characters`, {
      method: "PUT",
      body: JSON.stringify({
        members,
        character_ids: characterIds,
        pov_id: povId || "",
      }),
    });
    // Re-read DOM in case the user toggled more while the request was in flight.
    const latestMembers = getSceneCastMembersFromDom();
    const latestIds = latestMembers.map((item) => Number(item.character_id));
    const latestAppearingIds = latestMembers
      .filter((item) => item.appearance_role !== "mentioned")
      .map((item) => Number(item.character_id));
    const latestPovRaw = $("povSelect")?.value || "";
    const latestPov = latestPovRaw && latestAppearingIds.includes(Number(latestPovRaw))
      ? latestPovRaw
      : "";
    const idsChanged = latestIds.length !== characterIds.length
      || latestIds.some((id) => !characterIds.includes(id));
    if (idsChanged || String(latestPov) !== String(povId) || sceneCastSaveAgain) {
      sceneCastSaveInFlight = false;
      return persistSceneCharacterLinks({ quiet: true });
    }
    state.sceneMembers = latestMembers.map((item) => ({
      character_id: item.character_id,
      appearance_role: Number(latestPov) === Number(item.character_id)
        ? "primary"
        : item.appearance_role,
      is_pov: Number(latestPov) === Number(item.character_id) ? 1 : 0,
    }));
    updateSceneCharactersBadge();
    // Refresh linked styling (keeps checkboxes from current members).
    renderSceneCharacters();
    const n = latestAppearingIds.length;
    setSceneCastSaveUi({
      dirty: false,
      ok: true,
      message: n
        ? i18n.t("app.등장_인물_n_명_연결됨", { n })
        : i18n.t('app.저장됨_연결된_인물_없음'),
    });
    if (!quiet) {
      toast(n ? `${i18n.t('app.등장_인물_n_명을_이_회차에_저장했어요', {n: n})}` : i18n.t('app.이_회차_인물_연결을_저장했어요_연결된_인물'));
    }
    return state.sceneMembers;
  } catch (error) {
    setSceneCastSaveUi({
      dirty: true,
      error: true,
      message: i18n.t('app.저장에_실패했어요_다시_저장을_눌러_주세요'),
    });
    throw error;
  } finally {
    sceneCastSaveInFlight = false;
  }
}

async function syncSceneCastFromManuscript(options = {}) {
  const quiet = Boolean(options.quiet);
  if (!state.sceneId || !state.projectId) return null;
  if (sceneCastDirty) return persistSceneCharacterLinks({ quiet });
  if (sceneCastSyncInFlight) return null;
  sceneCastSyncInFlight = true;
  try {
    const result = await api(`/api/scenes/${state.sceneId}/sync-cast`, {
      method: "POST",
      body: JSON.stringify({
        content_md: getEditorContent() || "",
        suppressed_ids: [...sceneCastSuppressedIds],
        extra_character_ids: [...sceneCastExtraIds],
      }),
    });
    state.sceneMembers = Array.isArray(result?.members) ? result.members : [];
    if (Array.isArray(result?.created) && result.created.length) {
      const existing = new Set((state.characters || []).map((item) => Number(item.id)));
      result.created.forEach((character) => {
        if (!existing.has(Number(character.id))) {
          state.characters.push({
            ...character,
            short_description: "",
            profile_md: "",
            aliases: character.aliases || [],
          });
        }
      });
      try { renderCharacters(); } catch (_) { /* ignore */ }
      const names = result.created.map((item) => item.name).filter(Boolean).join(", ");
      if (names) toast(i18n.t("app.names_을_를_인물로_저장했어요", { names }));
    }
    renderSceneCharacters();
    const appears = sceneAppearingCount();
    setSceneCastSaveUi({
      dirty: false,
      ok: true,
      message: appears
        ? i18n.t("app.등장_인물_n_명_연결됨", { n: appears })
        : i18n.t("app.저장됨_연결된_인물_없음"),
    });
    scheduleSceneCastCandidates();
    return state.sceneMembers;
  } catch (error) {
    if (!quiet) throw error;
    console.warn("[supertory] scene cast sync failed", error);
    return null;
  } finally {
    sceneCastSyncInFlight = false;
  }
}
async function saveSceneCharacterLinksFromButton() {
  if (!state.sceneId) {
    toast(i18n.t('app.먼저_회차를_열어_주세요'));
    return;
  }
  // Allow save even if not marked dirty (user wants to force-save current checks).
  sceneCastDirty = true;
  await persistSceneCharacterLinks({ quiet: false });
}

async function createCharacterAndLinkToScene() {
  if (!state.projectId) return toast(i18n.t('app.먼저_작품을_선택해_주세요'));
  if (!state.sceneId) return toast(i18n.t('app.먼저_회차를_열어_주세요'));
  const name = await promptText({
    title: i18n.t('app.이_회차에_인물_연결'),
    message: i18n.t('app.새_인물_이름을_적으면_만들고_이_회차에_연'),
    label: i18n.t('app.이름'),
    defaultValue: i18n.t('app.새_캐릭터'),
    confirmLabel: i18n.t('app.만들고_작성하기'),
  });
  if (name === null) return;
  const displayName = name.trim() || i18n.t('app.새_캐릭터');
  const character = await api(`/api/projects/${state.projectId}/characters`, {
    method: "POST",
    body: JSON.stringify({ name: displayName }),
  });
  const newId = Number(character?.id);
  if (!newId) {
    toast(i18n.t('app.인물을_만들지_못했어요_다시_시도해_주세요'));
    return;
  }
  // Reload cast lists, then check the new character and save scene links.
  await refreshSceneCharactersPanel();
  const checkbox = document.querySelector(
    `#sceneCharacterList input[type="checkbox"][value="${newId}"]`,
  );
  if (checkbox) checkbox.checked = true;
  // Also keep previously linked members.
  const ids = new Set(getSelectedSceneCharacterIds());
  ids.add(newId);
  // Ensure checkboxes match ids (in case render dropped one).
  document.querySelectorAll("#sceneCharacterList input[type='checkbox']").forEach((input) => {
    input.checked = ids.has(Number(input.value));
  });
  await persistSceneCharacterLinks({ quiet: true });
  // Move to character editor so the author can fill profile (same as 설정집 + 캐릭터).
  await openCharacter(newId);
  toast(`${i18n.t('app.displayName_을_를_만들고_이_회', {displayName: displayName})}`);
}

let sceneDirty = false;
let sceneSaveGen = 0;
let autoSaveTimer = null;
let autoSaveInFlight = false;
let autoSaveWaiters = [];
let suppressSceneDirty = false;
const AUTO_SAVE_DELAY_MS = 1200;
const AUTO_SAVE_RETRY_MS = 5000;
const AUTO_SAVE_RETRY_MAX_MS = 60000;
let autoSaveFailStreak = 0;
let localDraftWriteTimer = null;
let onlineSyncTimer = null;
let lastLocalDraftToastAt = 0;
let localDraftToastShownForStreak = false;
let lastPersistedSceneStatus = null;

/* ── Offline-first local draft (never lose manuscript on API failure) ── */
const LOCAL_DRAFT_PREFIX = "supertory.sceneDraft.v1.";
const LOCAL_DRAFT_INDEX_KEY = "supertory.sceneDraftIndex.v1";
const LOCAL_DRAFT_IDB_NAME = "supertory-drafts";
const LOCAL_DRAFT_IDB_STORE = "scenes";
const LOCAL_DRAFT_MAX_LS_CHARS = 1_800_000; // stay under typical 5MB quota with JSON overhead

function localDraftKey(sceneId) {
  return `${LOCAL_DRAFT_PREFIX}${Number(sceneId) || 0}`;
}

function captureSceneDraftSnapshot(extra = {}) {
  if (!state.sceneId) return null;
  const content = typeof getEditorContent === "function" ? getEditorContent() : "";
  return {
    v: 1,
    sceneId: Number(state.sceneId),
    projectId: state.projectId != null ? Number(state.projectId) : null,
    title: $("sceneTitle")?.value || state.scene?.title || i18n.t('app.제목_없음'),
    status: $("sceneStatus")?.value || state.scene?.status || "draft",
    synopsis_md: $("sceneSynopsis")?.value || "",
    notes_md: $("sceneNotes")?.value || "",
    content_md: content,
    reference_links: typeof collectReferenceLinksFromState === "function"
      ? collectReferenceLinksFromState()
      : [],
    goal_word_count: Math.max(0, Number($("sceneGoalCount")?.value || 0) || 0),
    goal_metric: $("sceneGoalMetric")?.value || "chars_with_space",
    row_version: state.scene?.row_version ?? null,
    savedAt: Date.now(),
    reason: extra.reason || "edit",
    dirty: true,
  };
}

function _readDraftIndex() {
  try {
    const raw = localStorage.getItem(LOCAL_DRAFT_INDEX_KEY);
    const arr = raw ? JSON.parse(raw) : [];
    return Array.isArray(arr) ? arr.map(Number).filter((n) => n > 0) : [];
  } catch (_) {
    return [];
  }
}

function _writeDraftIndex(ids) {
  try {
    const unique = [...new Set(ids.map(Number).filter((n) => n > 0))].slice(-80);
    localStorage.setItem(LOCAL_DRAFT_INDEX_KEY, JSON.stringify(unique));
  } catch (_) {
    /* quota — ignore */
  }
}

function _openDraftIdb() {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === "undefined") {
      reject(new Error("no idb"));
      return;
    }
    const req = indexedDB.open(LOCAL_DRAFT_IDB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(LOCAL_DRAFT_IDB_STORE)) {
        db.createObjectStore(LOCAL_DRAFT_IDB_STORE, { keyPath: "sceneId" });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error || new Error("idb open failed"));
  });
}

function writeLocalSceneDraftIdb(snapshot) {
  if (!snapshot?.sceneId) return Promise.resolve(false);
  return _openDraftIdb()
    .then((db) => new Promise((resolve) => {
      try {
        const tx = db.transaction(LOCAL_DRAFT_IDB_STORE, "readwrite");
        tx.objectStore(LOCAL_DRAFT_IDB_STORE).put(snapshot);
        tx.oncomplete = () => {
          try { db.close(); } catch (_) { /* ignore */ }
          resolve(true);
        };
        tx.onerror = () => {
          try { db.close(); } catch (_) { /* ignore */ }
          resolve(false);
        };
      } catch (_) {
        resolve(false);
      }
    }))
    .catch(() => false);
}

function readLocalSceneDraftIdb(sceneId) {
  const id = Number(sceneId);
  if (!id) return Promise.resolve(null);
  return _openDraftIdb()
    .then((db) => new Promise((resolve) => {
      try {
        const tx = db.transaction(LOCAL_DRAFT_IDB_STORE, "readonly");
        const req = tx.objectStore(LOCAL_DRAFT_IDB_STORE).get(id);
        req.onsuccess = () => {
          try { db.close(); } catch (_) { /* ignore */ }
          resolve(req.result || null);
        };
        req.onerror = () => {
          try { db.close(); } catch (_) { /* ignore */ }
          resolve(null);
        };
      } catch (_) {
        resolve(null);
      }
    }))
    .catch(() => null);
}

function clearLocalSceneDraftIdb(sceneId) {
  const id = Number(sceneId);
  if (!id) return Promise.resolve();
  return _openDraftIdb()
    .then((db) => new Promise((resolve) => {
      try {
        const tx = db.transaction(LOCAL_DRAFT_IDB_STORE, "readwrite");
        tx.objectStore(LOCAL_DRAFT_IDB_STORE).delete(id);
        tx.oncomplete = () => {
          try { db.close(); } catch (_) { /* ignore */ }
          resolve();
        };
        tx.onerror = () => {
          try { db.close(); } catch (_) { /* ignore */ }
          resolve();
        };
      } catch (_) {
        resolve();
      }
    }))
    .catch(() => {});
}

/**
 * Synchronous local write — critical path for beforeunload / offline.
 * Always attempt localStorage; large bodies go primarily to IndexedDB.
 */
function writeLocalSceneDraftSync(snapshot) {
  if (!snapshot?.sceneId) return { ok: false, where: "none" };
  const id = Number(snapshot.sceneId);
  let lsOk = false;
  try {
    const json = JSON.stringify(snapshot);
    if (json.length <= LOCAL_DRAFT_MAX_LS_CHARS) {
      localStorage.setItem(localDraftKey(id), json);
      lsOk = true;
    } else {
      // Store compact pointer in LS; full body only in IDB.
      localStorage.setItem(localDraftKey(id), JSON.stringify({
        v: 1,
        sceneId: id,
        projectId: snapshot.projectId,
        title: snapshot.title,
        savedAt: snapshot.savedAt,
        row_version: snapshot.row_version,
        dirty: true,
        idbOnly: true,
        contentLen: String(snapshot.content_md || "").length,
      }));
      lsOk = true;
    }
    const idx = _readDraftIndex();
    if (!idx.includes(id)) {
      idx.push(id);
      _writeDraftIndex(idx);
    }
  } catch (_) {
    lsOk = false;
    try {
      sessionStorage.setItem(localDraftKey(id), JSON.stringify({
        ...snapshot,
        content_md: String(snapshot.content_md || "").slice(0, 400_000),
        truncated: true,
      }));
      lsOk = true;
    } catch (__) {
      /* last resort failed */
    }
  }
  // Fire-and-forget IDB backup (does not block typing).
  writeLocalSceneDraftIdb(snapshot);
  return { ok: lsOk, where: lsOk ? "local" : "failed" };
}

function readLocalSceneDraftSync(sceneId) {
  const id = Number(sceneId);
  if (!id) return null;
  try {
    const raw = localStorage.getItem(localDraftKey(id))
      || sessionStorage.getItem(localDraftKey(id));
    if (!raw) return null;
    const data = JSON.parse(raw);
    if (!data || data.sceneId !== id) return null;
    return data;
  } catch (_) {
    return null;
  }
}

async function readLocalSceneDraft(sceneId) {
  const id = Number(sceneId);
  const fromLs = readLocalSceneDraftSync(id);
  const fromIdb = await readLocalSceneDraftIdb(id);
  if (fromIdb && fromLs) {
    return (Number(fromIdb.savedAt) || 0) >= (Number(fromLs.savedAt) || 0) ? fromIdb : fromLs;
  }
  if (fromIdb?.idbOnly === false || (fromIdb && fromIdb.content_md != null)) return fromIdb;
  if (fromLs && !fromLs.idbOnly) return fromLs;
  if (fromIdb) return fromIdb;
  return fromLs;
}

function clearLocalSceneDraft(sceneId) {
  const id = Number(sceneId);
  if (!id) return;
  try { localStorage.removeItem(localDraftKey(id)); } catch (_) { /* ignore */ }
  try { sessionStorage.removeItem(localDraftKey(id)); } catch (_) { /* ignore */ }
  _writeDraftIndex(_readDraftIndex().filter((n) => n !== id));
  clearLocalSceneDraftIdb(id);
}

/** Snapshot current editor to device storage. Safe to call very often. */
function ensureLocalDraftSaved(reason = "edit") {
  if (!state.sceneId || !state.scene) return false;
  try {
    const snap = captureSceneDraftSnapshot({ reason });
    if (!snap) return false;
    const result = writeLocalSceneDraftSync(snap);
    return Boolean(result.ok);
  } catch (_) {
    return false;
  }
}

function scheduleLocalDraftWrite() {
  if (localDraftWriteTimer) window.clearTimeout(localDraftWriteTimer);
  // Micro-debounce: still near-instant so a crash loses almost nothing.
  localDraftWriteTimer = window.setTimeout(() => {
    localDraftWriteTimer = null;
    ensureLocalDraftSaved("debounce");
  }, 200);
}

function resetAutoSaveFailStreak() {
  autoSaveFailStreak = 0;
  localDraftToastShownForStreak = false;
}

/** Back off retries so a stuck server cannot spam the network / keep the screen awake. */
function scheduleAutoSaveRetry() {
  if (autoSaveTimer) window.clearTimeout(autoSaveTimer);
  autoSaveFailStreak += 1;
  const exp = Math.min(Math.max(autoSaveFailStreak - 1, 0), 4);
  const delay = Math.min(AUTO_SAVE_RETRY_MAX_MS, AUTO_SAVE_RETRY_MS * (2 ** exp));
  autoSaveTimer = window.setTimeout(() => {
    autoSaveTimer = null;
    // Hidden / quitting: keep local draft only — don't hammer the API.
    if (document.visibilityState === "hidden") {
      ensureLocalDraftSaved("hidden-retry-skip");
      return;
    }
    persistScene({ quiet: true, saveNote: i18n.t('app.자동_저장') }).catch(() => {
      /* persistScene schedules its own retry */
    });
  }, delay);
}

function notifyLocalDraftKept(error) {
  const now = Date.now();
  // Once per failure streak, then at most once a minute (avoid toast loops).
  if (localDraftToastShownForStreak && now - lastLocalDraftToastAt < 60000) return;
  if (!localDraftToastShownForStreak && now - lastLocalDraftToastAt < 8000) return;
  lastLocalDraftToastAt = now;
  localDraftToastShownForStreak = true;
  const offline = isOfflineSafeError(error) || !isOnlineNow();
  toast(
    offline
      ? i18n.t('app.연결이_불안정해_이_기기에_원고를_보관했어요')
      : i18n.t('app.서버_저장에_실패해_이_기기에_원고를_보관했'),
  );
}

/**
 * After loading server scene, restore a newer local draft if present.
 * Returns true if editor was restored from local storage.
 */
async function maybeRestoreLocalDraft(serverScene) {
  const sceneId = Number(serverScene?.id || state.sceneId);
  if (!sceneId) return false;
  const draft = await readLocalSceneDraft(sceneId);
  if (!draft || draft.content_md == null) return false;
  if (draft.idbOnly && !draft.content_md) {
    const idb = await readLocalSceneDraftIdb(sceneId);
    if (!idb?.content_md) return false;
    Object.assign(draft, idb);
  }

  const serverContent = String(serverScene?.content_md || "");
  const localContent = String(draft.content_md || "");
  if (!localContent && !draft.title) return false;

  // Prefer local if dirty flag or content/goal differs and draft is not ancient empty.
  const contentDiffers = localContent !== serverContent
    || String(draft.title || "") !== String(serverScene?.title || "")
    || String(draft.notes_md || "") !== String(serverScene?.notes_md || "")
    || String(draft.synopsis_md || "") !== String(serverScene?.synopsis_md || "")
    || Number(draft.goal_word_count || 0) !== Number(serverScene?.goal_word_count || 0)
    || String(draft.goal_metric || "") !== String(serverScene?.goal_metric || "");
  if (!contentDiffers) {
    clearLocalSceneDraft(sceneId);
    return false;
  }

  // If local is empty and server has text, keep server (avoid wiping).
  if (!localContent.trim() && serverContent.trim()) {
    clearLocalSceneDraft(sceneId);
    return false;
  }

  suppressSceneDirty = true;
  if ($("sceneTitle") && draft.title != null) $("sceneTitle").value = draft.title;
  if ($("sceneStatus") && draft.status) $("sceneStatus").value = draft.status;
  if ($("sceneSynopsis") && draft.synopsis_md != null) $("sceneSynopsis").value = draft.synopsis_md;
  if ($("sceneNotes") && draft.notes_md != null) $("sceneNotes").value = draft.notes_md;
  setEditorContent(localContent);
  if ($("sceneGoalCount") && draft.goal_word_count != null) {
    $("sceneGoalCount").value = String(draft.goal_word_count || 0);
  }
  if (!isProjectStatsScope() && $("statsGoalInput") && draft.goal_word_count != null) {
    $("statsGoalInput").value = String(draft.goal_word_count || 0);
  }
  if ($("sceneGoalMetric") && draft.goal_metric) {
    $("sceneGoalMetric").value = draft.goal_metric;
  }
  if (Array.isArray(draft.reference_links)) {
    state.referenceLinks = draft.reference_links.map((link) => normalizeReferenceItem(link));
    if (typeof renderReferenceLinks === "function") renderReferenceLinks();
  }
  suppressSceneDirty = false;
  sceneDirty = true;
  updateAuthorNotesBadge();
  updateReferenceMaterialsBadge();
  setSceneSaveStatus(i18n.t('app.이_기기_보관본_복구됨_동기화_대기'));
  toast(i18n.t('app.연결_전_편집_내용을_이_기기에서_복구했습니'));
  scheduleAutoSave();
  return true;
}

function scheduleOnlineSync() {
  if (onlineSyncTimer) window.clearTimeout(onlineSyncTimer);
  onlineSyncTimer = window.setTimeout(() => {
    onlineSyncTimer = null;
    flushLocalDraftsToServer().catch(() => { /* ignore */ });
  }, 400);
}

async function flushLocalDraftsToServer() {
  if (!isOnlineNow()) return;
  // Current open scene first
  if (sceneDirty && state.sceneId) {
    try {
      await persistScene({ quiet: true, saveNote: i18n.t('app.오프라인_동기화') });
    } catch (_) {
      /* keep local */
    }
  }
  if (splitDirty && state.splitSceneId) {
    try {
      await persistSplitScene({ quiet: true });
    } catch (_) {
      /* keep local */
    }
  }
}

function setSceneSaveStatus(text) {
  // Footer no longer shows revision/word-count save chatter.
  // Keep a short cue only in focus-write mode.
  if ($("focusWriteSaveInfo") && typeof isFocusWriteOpen === "function" && isFocusWriteOpen()) {
    const t = String(text || "");
    if (t.includes(i18n.t('app.실패')) || t.includes(i18n.t('app.오프라인')) || t.includes(i18n.t('app.보관'))) {
      $("focusWriteSaveInfo").textContent = t.includes(i18n.t('app.보관')) ? i18n.t('app.기기에_보관됨') : i18n.t('app.저장_실패');
    } else if (t.includes(i18n.t('app.대기')) || t.includes(i18n.t('app.복구'))) $("focusWriteSaveInfo").textContent = i18n.t('app.저장_대기');
    else if (t.includes(i18n.t('app.중'))) $("focusWriteSaveInfo").textContent = i18n.t('app.저장_중');
    else if (t.includes(i18n.t('app.저장'))) $("focusWriteSaveInfo").textContent = i18n.t('app.저장됨');
    else $("focusWriteSaveInfo").textContent = "";
  }
}

function markSceneDirty() {
  if (suppressSceneDirty || !state.sceneId || !state.scene) return;
  sceneDirty = true;
  sceneSaveGen += 1;
  // Local-first: device storage before any network hop.
  scheduleLocalDraftWrite();
  setSceneSaveStatus(isOnlineNow() ? i18n.t('app.저장_대기_중') : i18n.t('app.오프라인_이_기기에_보관_중'));
  scheduleAutoSave();
  scheduleKnownCastPreview();
}

function scheduleAutoSave() {
  if (autoSaveTimer) window.clearTimeout(autoSaveTimer);
  // Fresh edits get a short delay; ongoing failure streak keeps its backoff timer.
  const delay = autoSaveFailStreak > 0
    ? Math.min(AUTO_SAVE_RETRY_MAX_MS, AUTO_SAVE_RETRY_MS * (2 ** Math.min(autoSaveFailStreak - 1, 4)))
    : AUTO_SAVE_DELAY_MS;
  autoSaveTimer = window.setTimeout(() => {
    autoSaveTimer = null;
    persistScene({ quiet: true, saveNote: i18n.t('app.자동_저장') }).catch((error) => {
      // Local draft already written; avoid noisy toasts on every quiet retry.
      if (!isOfflineSafeError(error) && !error?.localOnly) handleError(error);
      else notifyLocalDraftKept(error);
    });
  }, delay);
}

function cancelScheduledAutoSave() {
  if (autoSaveTimer) {
    window.clearTimeout(autoSaveTimer);
    autoSaveTimer = null;
  }
}

function buildSceneSaveBody(saveNote) {
  // Keep 설정집 참고자료 in sync whenever the scene is saved
  try { syncAllReferencesToProjectSources(); } catch (_) { /* ignore */ }
  return {
    title: $("sceneTitle")?.value || state.scene?.title || i18n.t('app.제목_없음'),
    status: $("sceneStatus")?.value || "draft",
    synopsis_md: $("sceneSynopsis")?.value || "",
    notes_md: $("sceneNotes")?.value || "",
    content_md: getEditorContent(),
    reference_links: collectReferenceLinksFromState(),
    goal_word_count: Math.max(0, Number($("sceneGoalCount")?.value || 0) || 0),
    goal_metric: $("sceneGoalMetric")?.value || "chars_with_space",
    row_version: state.scene.row_version,
    save_note: saveNote || i18n.t('app.저장'),
  };
}

const READER_COMMENTS_PULSE_KEY = "supertory.readerCommentsPulsePlayed";

function readReaderCommentsPulseMap() {
  try {
    const raw = localStorage.getItem(READER_COMMENTS_PULSE_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch (_) {
    return {};
  }
}

function hasReaderCommentsPulsePlayed(sceneId) {
  const id = Number(sceneId);
  if (!id) return false;
  return Boolean(readReaderCommentsPulseMap()[String(id)]);
}

function markReaderCommentsPulsePlayed(sceneId) {
  const id = Number(sceneId);
  if (!id) return;
  const map = readReaderCommentsPulseMap();
  map[String(id)] = 1;
  try {
    localStorage.setItem(READER_COMMENTS_PULSE_KEY, JSON.stringify(map));
  } catch (_) { /* quota */ }
}

function clearReaderCommentsPulsePlayed(sceneId) {
  const id = Number(sceneId);
  if (!id) return;
  const map = readReaderCommentsPulseMap();
  if (!map[String(id)]) return;
  delete map[String(id)];
  try {
    localStorage.setItem(READER_COMMENTS_PULSE_KEY, JSON.stringify(map));
  } catch (_) { /* quota */ }
}

function startVirtualReaderCommentsFlow() {
  openViewerReaderCommentsFromCta();
}

const READER_COMMENT_TOAST_SEEN_KEY = "supertory.readerCommentToastSeen";

function hasSeenReaderCommentToast() {
  try {
    return localStorage.getItem(READER_COMMENT_TOAST_SEEN_KEY) === "1";
  } catch (_) {
    return false;
  }
}

function markReaderCommentToastSeen() {
  try {
    localStorage.setItem(READER_COMMENT_TOAST_SEEN_KEY, "1");
  } catch (_) { /* quota */ }
}

function showSceneCompleteReaderCommentsToast() {
  const firstTime = !hasSeenReaderCommentToast();
  toast(i18n.t('app.완성_처리됐어요_가상독자_댓글도_받아볼_수'), firstTime ? 0 : 2600, {
    sticky: firstTime,
    dismissible: true,
    detail: firstTime
      ? i18n.t('app.나중엔_회차_뷰어_안_가상독자_댓글_받기_버')
      : undefined,
    action: {
      label: i18n.t('app.지금_받아보기'),
      onClick: () => {
        markReaderCommentToastSeen();
        startVirtualReaderCommentsFlow();
      },
    },
    onClose: firstTime ? markReaderCommentToastSeen : undefined,
  });
}

let sceneTraitAnalysisWatchTimer = 0;
let sceneTraitAnalysisWatchSceneId = null;
const characterTraitToastQueue = [];
let characterTraitToastShowing = false;

function stopSceneTraitAnalysisWatch() {
  if (sceneTraitAnalysisWatchTimer) {
    window.clearInterval(sceneTraitAnalysisWatchTimer);
    sceneTraitAnalysisWatchTimer = 0;
  }
  sceneTraitAnalysisWatchSceneId = null;
}

function enqueueCharacterTraitToasts(characters) {
  const items = Array.isArray(characters) ? characters : [];
  for (const item of items) {
    const count = Number(item?.count) || 0;
    if (count <= 0) continue;
    characterTraitToastQueue.push(item);
  }
  showNextCharacterTraitToast();
}

function showNextCharacterTraitToast() {
  if (characterTraitToastShowing) return;
  const item = characterTraitToastQueue.shift();
  if (!item) return;
  characterTraitToastShowing = true;
  const name = String(item.name || "").trim() || i18n.t("app.이_인물");
  const count = Number(item.count) || 0;
  const characterId = Number(item.id);
  const duration = 4200;
  const openSheet = () => {
    if (Number.isFinite(characterId) && characterId > 0) {
      openCharacter(characterId).catch(handleError);
    }
  };
  toast(
    i18n.t("app.name_의_인물_설정에_새로운_내용_count가지가_추가됐어요", {
      name,
      count,
    }),
    duration,
    {
      dismissible: true,
      action: {
        label: i18n.t("app.인물_설정_열기"),
        onClick: openSheet,
      },
      onClick: openSheet,
    },
  );
  window.setTimeout(() => {
    characterTraitToastShowing = false;
    showNextCharacterTraitToast();
  }, duration + 200);
}

function watchSceneTraitAnalysis(sceneId) {
  const id = Number(sceneId);
  if (!Number.isFinite(id) || id <= 0) return;
  stopSceneTraitAnalysisWatch();
  sceneTraitAnalysisWatchSceneId = id;
  const startedAt = Date.now();
  const tick = async () => {
    if (sceneTraitAnalysisWatchSceneId !== id) return;
    try {
      const job = await api(`/api/scenes/${id}/trait-analysis`);
      const status = String(job?.status || "idle");
      if (status === "running") return;
      if (status === "idle" && Date.now() - startedAt < 8000) return;
      stopSceneTraitAnalysisWatch();
      if (status === "done") {
        const characters = Array.isArray(job?.characters) ? job.characters : [];
        enqueueCharacterTraitToasts(characters);
        if (
          state.characterId &&
          !$("characterEditor")?.classList.contains("hidden")
        ) {
          const touched = characters.some(
            (entry) => Number(entry.id) === Number(state.characterId),
          );
          if (touched) {
            try {
              await openCharacter(state.characterId);
            } catch (_) {
              /* ignore */
            }
          }
        }
      }
    } catch (_) {
      if (Date.now() - startedAt > 90000) stopSceneTraitAnalysisWatch();
    }
  };
  sceneTraitAnalysisWatchTimer = window.setInterval(() => {
    tick().catch(() => { /* keep quiet */ });
  }, 1200);
  tick().catch(() => { /* keep quiet */ });
}

function pulseViewerReaderCommentsButtonIfNeeded() {
  const btn = $("viewerReaderCommentsButton");
  const sceneId = Number(state.sceneId);
  if (!btn || !sceneId || btn.disabled) return;
  if (typeof isViewerOpen === "function" && !isViewerOpen()) return;
  if (hasReaderCommentsPulsePlayed(sceneId)) return;
  markReaderCommentsPulsePlayed(sceneId);
  btn.classList.remove("is-attention");
  void btn.offsetWidth;
  btn.classList.add("is-attention");
  const clearPulse = () => btn.classList.remove("is-attention");
  btn.addEventListener("animationend", clearPulse, { once: true });
}

function syncViewerReaderCommentsButton(options = {}) {
  const btn = $("viewerReaderCommentsButton");
  if (btn) {
    const gatedOff = !isClusterFeatureVisible("reader_comments");
    setClusterFeatureHidden(btn, gatedOff);
    const enabled = !gatedOff && Boolean(state.sceneId) && lastPersistedSceneStatus === "complete";
    btn.disabled = !enabled;
    btn.title = enabled
      ? i18n.t('app.이_회차에_가상독자_댓글을_받아_봐요')
      : i18n.t('app.회차를_완성으로_바꾸면_가상독자_댓글을_받을');
  }
  syncViewerEntryCommentsBadge();
  if (options.pulse) pulseViewerReaderCommentsButtonIfNeeded();
}

function isReaderCommentsUnusedForOpenScene() {
  if (!state.sceneId || lastPersistedSceneStatus !== "complete") return false;
  return !Number(state.scene?.reader_comments_started || 0);
}

function syncViewerEntryCommentsBadge() {
  const badge = $("viewerModeCommentsBadge");
  if (!badge) return;
  const show = isReaderCommentsUnusedForOpenScene();
  badge.classList.toggle("hidden", !show);
}

function markReaderCommentsStarted() {
  const sceneId = Number(state.sceneId);
  if (!sceneId) return;
  if (state.scene) state.scene.reader_comments_started = 1;
  syncViewerEntryCommentsBadge();
  api(`/api/scenes/${sceneId}/reader-comments-started`, {
    method: "POST",
    body: JSON.stringify({}),
  })
    .then((result) => {
      if (state.scene && Number(state.sceneId) === sceneId) {
        state.scene.reader_comments_started = Number(result?.reader_comments_started || 1);
      }
      syncViewerEntryCommentsBadge();
    })
    .catch(() => {
      /* keep local flag; next openScene will refresh from DB */
    });
}

function notifySceneSaveIdle() {
  const waiters = autoSaveWaiters.splice(0);
  waiters.forEach((fn) => fn());
}

async function waitForSceneSaveIdle() {
  while (autoSaveInFlight) {
    await new Promise((resolve) => autoSaveWaiters.push(resolve));
  }
}

async function persistScene(options = {}) {
  const quiet = Boolean(options.quiet);
  const saveNote = options.saveNote || (quiet ? i18n.t('app.자동_저장') : i18n.t('app.저장'));
  if (!state.scene || !state.sceneId) return null;
  if (autoSaveInFlight) {
    ensureLocalDraftSaved("inflight");
    if (quiet) {
      scheduleAutoSave();
      return null;
    }
    await waitForSceneSaveIdle();
    if (!state.scene || !state.sceneId) return null;
  }
  // Ensure title is never empty (server requires it).
  if (!$("sceneTitle")?.value?.trim()) {
    if ($("sceneTitle")) $("sceneTitle").value = state.scene.title || i18n.t('app.제목_없음');
  }

  const saveGen = sceneSaveGen;

  // 1) LOCAL FIRST — always, before network.
  const body = buildSceneSaveBody(saveNote);
  const localSnap = {
    v: 1,
    sceneId: Number(state.sceneId),
    projectId: state.projectId != null ? Number(state.projectId) : null,
    title: body.title,
    status: body.status,
    synopsis_md: body.synopsis_md,
    notes_md: body.notes_md,
    content_md: body.content_md,
    reference_links: body.reference_links,
    goal_word_count: body.goal_word_count,
    goal_metric: body.goal_metric,
    row_version: body.row_version,
    savedAt: Date.now(),
    reason: saveNote,
    dirty: true,
  };
  const localWrite = writeLocalSceneDraftSync(localSnap);
  if (!localWrite.ok) {
    console.warn("[supertory] local draft write failed — still attempting server save");
  }

  autoSaveInFlight = true;
  if (quiet) {
    setSceneSaveStatus(
      isOnlineNow() ? i18n.t('app.자동_저장_중') : i18n.t('app.오프라인_보관_중'),
    );
  }
  try {
    if (!isOnlineNow()) {
      const offlineErr = new Error(
        i18n.t('app.오프라인_상태입니다_원고는_이_기기에_보관되'),
      );
      offlineErr.isNetwork = true;
      offlineErr.offlineSafe = true;
      throw offlineErr;
    }

    const saved = await api(`/api/scenes/${state.sceneId}`, {
      method: "PUT",
      body: JSON.stringify(body),
    });
    // Characters are secondary — failure must not discard content that already saved.
    try {
      if (sceneCastDirty) {
        await persistSceneCharacterLinks({ quiet: true });
      } else {
        await syncSceneCastFromManuscript({ quiet: true });
      }
    } catch (charError) {
      console.warn("[supertory] character membership save failed", charError);
    }
    if (saved && typeof saved === "object") {
      if (saved.row_version != null) state.scene.row_version = saved.row_version;
      if (saved.revision_no != null) state.scene.revision_no = saved.revision_no;
      if (saved.word_count != null) state.scene.word_count = saved.word_count;
      if (saved.status != null) state.scene.status = saved.status;
      if (saved.title != null) state.scene.title = saved.title;
    }
    if (state.scene) {
      state.scene.goal_word_count = body.goal_word_count;
      state.scene.goal_metric = body.goal_metric;
    }
    if (saveGen !== sceneSaveGen) {
      sceneDirty = true;
      scheduleAutoSave();
    } else {
      sceneDirty = false;
      clearLocalSceneDraft(state.sceneId);
    }
    resetAutoSaveFailStreak();
    // Binder left rail: status / title must match the open scene immediately.
    syncOpenSceneToOutlineBinder({
      sceneId: state.sceneId,
      status: body.status || saved?.status,
      title: body.title || saved?.title,
    });
    const revision = state.scene.revision_no ?? "";
    const words = state.scene.word_count ?? 0;
    const stamp = new Date().toLocaleTimeString("ko-KR", { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    setSceneSaveStatus(
      quiet
        ? `${i18n.t('app.자동_저장됨_stamp_저장본_revisio', {stamp: stamp, revision: revision, words: words})}`
        : `${i18n.t('app.저장됨_stamp_저장본_revision_w', {stamp: stamp, revision: revision, words: words})}`,
    );
    if ($("focusWriteSaveInfo") && isFocusWriteOpen()) {
      $("focusWriteSaveInfo").textContent = quiet
        ? `${i18n.t('app.자동_저장됨_stamp', {stamp: stamp})}`
        : `${i18n.t('app.저장됨_stamp', {stamp: stamp})}`;
    }
    // Keep open tab title in sync with renames.
    if (state.sceneId) {
      const title = $("sceneTitle")?.value?.trim() || state.scene?.title || "";
      if (title) upsertEpisodeTab(state.sceneId, title);
      renderEpisodeChrome();
    }
    // Refresh full-manuscript totals after content is saved.
    scheduleProjectManuscriptStats();
    // Project auto-index: debounce scene_summary regeneration after idle.
    try {
      scheduleSceneIndexAfterSave(state.sceneId, body.content_md);
    } catch (_) { /* ignore */ }
    const nextStatus = String(body.status || saved?.status || lastPersistedSceneStatus || "");
    const becameComplete = nextStatus === "complete" && lastPersistedSceneStatus !== "complete";
    if (nextStatus && nextStatus !== "complete" && state.sceneId) {
      clearReaderCommentsPulsePlayed(state.sceneId);
    }
    lastPersistedSceneStatus = nextStatus || lastPersistedSceneStatus;
    if (becameComplete) {
      showSceneCompleteReaderCommentsToast();
      watchSceneTraitAnalysis(state.sceneId);
      watchSceneItemAnalysis(state.sceneId);
    }
    else if (!quiet) toast(i18n.t('app.저장했습니다'));
    syncViewerReaderCommentsButton({ pulse: becameComplete });
    return saved;
  } catch (error) {
    // 2) Local already has the manuscript — never treat this as total loss.
    ensureLocalDraftSaved(isOfflineSafeError(error) ? "offline" : "server-error");
    const stamp = new Date().toLocaleTimeString("ko-KR", { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    if (isOfflineSafeError(error) || !isOnlineNow()) {
      setSceneSaveStatus(`${i18n.t('app.이_기기에_보관됨_stamp_연결_시_동기화', {stamp: stamp})}`);
      notifyLocalDraftKept(error);
      scheduleAutoSaveRetry();
      // Do not rethrow for quiet autosave — work is safe locally.
      if (quiet) return { localOnly: true, error };
      const friendly = new Error(
        error.message || i18n.t('app.서버에_저장하지_못했지만_원고는_이_기기에'),
      );
      friendly.offlineSafe = true;
      friendly.localOnly = true;
      throw friendly;
    }
    if (quiet) {
      setSceneSaveStatus(i18n.t('app.자동_저장_실패_기기에_보관_재시도_예정'));
      notifyLocalDraftKept(error);
      scheduleAutoSaveRetry();
      return { localOnly: true, error };
    }
    throw error;
  } finally {
    autoSaveInFlight = false;
    notifySceneSaveIdle();
  }
}

async function saveScene(event) {
  if (event) event.preventDefault();
  cancelScheduledAutoSave();
  ensureLocalDraftSaved("manual");
  try {
    await persistScene({ quiet: false, saveNote: i18n.t('app.수동_저장') });
  } catch (error) {
    if (error?.localOnly || isOfflineSafeError(error)) {
      toast(i18n.t('app.서버_저장은_보류되었지만_원고는_이_기기에'));
      return;
    }
    throw error;
  }
}

function setupSceneAutoSave() {
  const dirtyEvents = ["input", "change"];
  const fields = [
    "sceneTitle", "sceneStatus", "sceneSynopsis", "sceneNotes",
    "sceneGoalMetric", "sceneGoalCount", "sceneContent", "povSelect",
  ];
  fields.forEach((id) => {
    const el = $(id);
    if (!el) return;
    dirtyEvents.forEach((type) => {
      el.addEventListener(type, () => markSceneDirty());
    });
  });
  // Writing status bar → binder episode head must update immediately (not only after save).
  $("sceneStatus")?.addEventListener("change", () => {
    const status = $("sceneStatus")?.value || "draft";
    syncOpenSceneToOutlineBinder({ status });
    markSceneDirty();
  });
  // Some browsers fire input on <select> when using keyboard; keep binder in sync.
  $("sceneStatus")?.addEventListener("input", () => {
    const status = $("sceneStatus")?.value || "draft";
    syncOpenSceneToOutlineBinder({ status });
  });
  // Title renames also reflect on the binder list (live, while typing ends on change/blur).
  $("sceneTitle")?.addEventListener("change", () => {
    const title = $("sceneTitle")?.value?.trim() || i18n.t('app.제목_없음');
    syncOpenSceneToOutlineBinder({ title });
  });
  // Character checkboxes: mark dirty → user presses 저장 (also saved with scene autosave).
  $("sceneCharacterList")?.addEventListener("change", (event) => {
    if (event.target?.closest?.("input[type='checkbox']")) {
      const row = event.target.closest?.(".scene-cast-item");
      if (row && event.target.type === "checkbox") {
        row.classList.toggle("is-linked", event.target.checked);
        const id = Number(event.target.value);
        if (id) {
          if (event.target.checked) {
            sceneCastSuppressedIds.delete(id);
            const found = detectKnownSceneCast(getEditorPlainText() || "", state.characters || []);
            if (!found.has(id)) sceneCastExtraIds.add(id);
          } else {
            sceneCastSuppressedIds.add(id);
            sceneCastExtraIds.delete(id);
          }
        }
      }
      markSceneDirty();
      markSceneCastDirty();
    }
  });
  $("sceneCharacterList")?.addEventListener("click", (event) => {
    const openBtn = event.target.closest?.("[data-open-character]");
    if (!openBtn) return;
    event.preventDefault();
    event.stopPropagation();
    const id = Number(openBtn.dataset.openCharacter);
    if (id) openCharacter(id).catch(handleError);
  });
  $("povSelect")?.addEventListener("change", () => {
    markSceneDirty();
    markSceneCastDirty();
  });
  $("sceneCharacterSaveButton")?.addEventListener("click", () => {
    saveSceneCharacterLinksFromButton().catch(handleError);
  });
  $("sceneCharacterCreateButton")?.addEventListener("click", () => {
    createCharacterAndLinkToScene().catch(handleError);
  });
  $("sceneCastCandidateList")?.addEventListener("click", (event) => {
    const addBtn = event.target.closest?.("[data-add-cast-candidate]");
    if (!addBtn) return;
    event.preventDefault();
    const raw = addBtn.getAttribute("data-add-cast-candidate") || "";
    let name = raw;
    try { name = decodeURIComponent(raw); } catch (_) { /* keep raw */ }
    addBtn.disabled = true;
    addSceneCastCandidate(name).catch((error) => {
      addBtn.disabled = false;
      handleError(error);
    });
  });
  $("sceneItemCandidateList")?.addEventListener("click", (event) => {
    const addBtn = event.target.closest?.("[data-add-item-candidate]");
    if (!addBtn) return;
    event.preventDefault();
    const raw = addBtn.getAttribute("data-add-item-candidate") || "";
    let name = raw;
    try { name = decodeURIComponent(raw); } catch (_) { /* keep raw */ }
    addBtn.disabled = true;
    addSceneItemCandidate(name).catch((error) => {
      addBtn.disabled = false;
      handleError(error);
    });
  });
  // Reference links use delegated inputs.
  $("referenceLinkList")?.addEventListener("input", () => markSceneDirty());
  $("referenceLinkList")?.addEventListener("change", () => markSceneDirty());

  // Extra safety: contenteditable sometimes fires only input.
  $("sceneContent")?.addEventListener("blur", () => {
    if (sceneDirty) {
      ensureLocalDraftSaved("blur");
      scheduleAutoSave();
    }
  });

  // Flush: sync local draft ALWAYS; async server best-effort.
  // Local draft is the safety net — do not block window close (that kept the
  // screen awake / app stuck while retries + beforeunload fought each other).
  window.addEventListener("beforeunload", () => {
    cancelScheduledAutoSave();
    if (sceneDirty || splitDirty) {
      ensureLocalDraftSaved("beforeunload");
      if (splitDirty && state.splitSceneId) {
        try {
          const bodyEl = $("splitSceneBodyEditor");
          const titleEl = $("splitSceneTitleInput");
          writeLocalSceneDraftSync({
            v: 1,
            sceneId: Number(state.splitSceneId),
            projectId: state.projectId != null ? Number(state.projectId) : null,
            title: titleEl?.value || state.splitScene?.title || "",
            status: state.splitScene?.status || "draft",
            synopsis_md: state.splitScene?.synopsis_md || "",
            notes_md: state.splitScene?.notes_md || "",
            content_md: bodyEl ? getEditorContent(bodyEl) : (state.splitScene?.content_md || ""),
            reference_links: state.splitScene?.reference_links || [],
            goal_word_count: state.splitScene?.goal_word_count || 0,
            goal_metric: state.splitScene?.goal_metric || "chars_with_space",
            row_version: state.splitScene?.row_version ?? null,
            savedAt: Date.now(),
            reason: "beforeunload-split",
            dirty: true,
          });
        } catch (_) {
          /* ignore */
        }
      }
      // Try keepalive PUT for current scene (may be ignored by browser).
      try {
        if (state.sceneId && state.scene && isOnlineNow()) {
          const payload = JSON.stringify(buildSceneSaveBody(i18n.t('app.종료_전_저장')));
          // keepalive fetch PUT
          fetch(`/api/scenes/${state.sceneId}`, {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: payload,
            keepalive: true,
          }).catch(() => { /* local draft remains */ });
        }
      } catch (_) {
        /* ignore */
      }
    }
  });
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden") {
      if (sceneDirty) {
        ensureLocalDraftSaved("visibility");
        cancelScheduledAutoSave();
        persistScene({ quiet: true, saveNote: i18n.t('app.자동_저장') }).catch(() => {
          /* local draft already kept */
        });
      }
      if (splitDirty) {
        cancelSplitAutoSave();
        persistSplitScene({ quiet: true }).catch(() => { /* ignore */ });
      }
      flushPendingCodexSaves().catch(() => {});
    } else if (document.visibilityState === "visible") {
      // Resume sync after screen sleep / app refocus without toast spam.
      if (sceneDirty || splitDirty) scheduleOnlineSync();
    }
  });

  window.addEventListener("online", () => {
    toast(i18n.t('app.연결되었습니다_보관된_원고를_서버에_동기화합'));
    scheduleOnlineSync();
  });
  window.addEventListener("offline", () => {
    if (sceneDirty) ensureLocalDraftSaved("offline-event");
    setSceneSaveStatus(i18n.t('app.오프라인_이_기기에_보관_중'));
    toast(i18n.t('app.오프라인입니다_작성_내용은_이_기기에_계속'));
  });

  // pagehide is more reliable than beforeunload on mobile.
  window.addEventListener("pagehide", () => {
    cancelScheduledAutoSave();
    if (sceneDirty) ensureLocalDraftSaved("pagehide");
    flushPendingCodexSaves().catch(() => {});
  });
}

async function createCharacter() {
  if (!state.projectId) return toast(i18n.t('app.먼저_새_작품을_만들어_주세요'));
  const name = await promptText({
    title: i18n.t('app.캐릭터_만들기'),
    message: i18n.t('app.캐릭터_이름을_적어_주세요'),
    label: i18n.t('app.이름'),
    defaultValue: i18n.t('app.새_캐릭터'),
    confirmLabel: i18n.t('app.만들기'),
  });
  if (name === null) return;
  const character = await api(`/api/projects/${state.projectId}/characters`, { method: "POST", body: JSON.stringify({ name: name.trim() || i18n.t('app.새_캐릭터') }) });
  state.openSettingsSection = "characters";
  await loadProject();
  await openCharacter(character.id);
  toast(i18n.t('app.인물_설정을_적어_보세요'));
}

function renderCharacterPortrait(character) {
  const img = $("characterPortraitPreview");
  const empty = $("characterPortraitEmpty");
  const clearBtn = $("characterPortraitClearButton");
  const url = String(character?.portrait_url || "").trim();
  if (img) {
    if (url) {
      img.src = url;
      img.classList.remove("hidden");
    } else {
      img.removeAttribute("src");
      img.classList.add("hidden");
    }
  }
  empty?.classList.toggle("hidden", Boolean(url));
  clearBtn?.classList.toggle("hidden", !url);
}

const CHARACTER_TORI_FIELDS = [
  { key: "short_description", label: i18n.t('app.한_줄_소개'), inputId: "characterSummary" },
  { key: "profile_md", label: i18n.t('app.인물_설정'), inputId: "characterProfile" },
  { key: "strengths_md", label: i18n.t('app.무기_강점'), inputId: "characterStrengths" },
  { key: "weaknesses_md", label: i18n.t('app.약점'), inputId: "characterWeaknesses" },
  { key: "aliases", label: i18n.t('index.다른_이름_별칭'), inputId: null },
];

const TORI_TEXT_PREFIX = "〔토리〕";

function isToriDraftText(value) {
  return String(value || "").trimStart().startsWith(TORI_TEXT_PREFIX);
}

function stripToriTextPrefix(value) {
  const text = String(value || "");
  const leading = (text.match(/^\s*/) || [""])[0];
  const rest = text.slice(leading.length);
  if (!rest.startsWith(TORI_TEXT_PREFIX)) return text;
  return rest.slice(TORI_TEXT_PREFIX.length).replace(/^\s+/, "");
}

function applyToriDraftClass(el) {
  if (!el) return;
  el.classList.toggle("is-tori-draft", isToriDraftText(el.value));
}

function claimToriDraftOnInput(el, event) {
  if (!el) return false;
  if (event && event.isComposing) {
    applyToriDraftClass(el);
    return false;
  }
  const value = String(el.value || "");
  if (!isToriDraftText(value)) {
    el.classList.remove("is-tori-draft");
    return false;
  }
  const next = stripToriTextPrefix(value);
  if (next === value) {
    el.classList.add("is-tori-draft");
    return false;
  }
  const start = Number(el.selectionStart);
  const end = Number(el.selectionEnd);
  const delta = value.length - next.length;
  el.value = next;
  try {
    if (Number.isFinite(start) && Number.isFinite(end)) {
      el.setSelectionRange(Math.max(0, start - delta), Math.max(0, end - delta));
    }
  } catch (_) {
    /* some inputs do not support selection */
  }
  el.classList.remove("is-tori-draft");
  return true;
}

function syncCharacterToriDraftStyle() {
  CHARACTER_TORI_FIELDS.forEach((item) => {
    const el = $(item.inputId);
    if (el) applyToriDraftClass(el);
  });
}

let characterAnalysisField = "";
let characterAnalysisKind = "character";
let characterAnalysisWatchTimer = 0;
let characterAnalysisWatchProjectId = null;

function characterToriPending(character) {
  const raw = character?.tori_analysis;
  return raw && typeof raw === "object" ? raw : {};
}

function worldToriPending() {
  const raw = state.worldToriAnalysis;
  return raw && typeof raw === "object" ? raw : {};
}

function worldFieldLabel(fieldName) {
  for (const sec of WORLD_BUILDING_SCHEMA) {
    const field = sec.fields.find((item) => item.id === fieldName);
    if (field) return field.label;
  }
  return fieldName;
}

function syncCharacterToriBadges(character) {
  const pending = characterToriPending(character);
  document.querySelectorAll(".character-analysis-badge:not(.world-analysis-badge)").forEach((button) => {
    const field = button.getAttribute("data-tori-field");
    const has = Boolean(field && pending[field]?.content);
    button.classList.toggle("hidden", !has);
  });
}

function syncWorldToriBadges() {
  const pending = worldToriPending();
  document.querySelectorAll(".world-analysis-badge").forEach((button) => {
    const field = button.getAttribute("data-world-tori-field");
    const has = Boolean(field && pending[field]?.content);
    button.classList.toggle("hidden", !has);
  });
}

function closeCharacterAnalysisModal() {
  $("characterAnalysisModal")?.classList.add("hidden");
  characterAnalysisField = "";
  characterAnalysisKind = "character";
}

function fillAnalysisModal(label, content) {
  if ($("characterAnalysisTitle")) {
    $("characterAnalysisTitle").textContent = i18n.t('app.토리_새_분석');
  }
  if ($("characterAnalysisFieldLabel")) {
    $("characterAnalysisFieldLabel").textContent = label || "";
  }
  if ($("characterAnalysisHint")) {
    $("characterAnalysisHint").textContent =
      i18n.t('app.지금_칸에_적어_둔_내용은_그대로_둡니다_토');
  }
  if ($("characterAnalysisBody")) {
    $("characterAnalysisBody").textContent = String(content || "");
  }
  $("characterAnalysisModal")?.classList.remove("hidden");
}

function openCharacterAnalysisModal(fieldName) {
  const character = state.character?.character;
  const pending = characterToriPending(character)[fieldName];
  if (!pending?.content) {
    toast(i18n.t('app.보여줄_토리_분석이_없어요'));
    return;
  }
  const meta = CHARACTER_TORI_FIELDS.find((item) => item.key === fieldName);
  characterAnalysisKind = "character";
  characterAnalysisField = fieldName;
  fillAnalysisModal(meta?.label || fieldName, pending.content);
}

function openWorldAnalysisModal(fieldName) {
  const pending = worldToriPending()[fieldName];
  if (!pending?.content) {
    toast(i18n.t('app.보여줄_토리_분석이_없어요'));
    return;
  }
  characterAnalysisKind = "world";
  characterAnalysisField = fieldName;
  fillAnalysisModal(worldFieldLabel(fieldName), pending.content);
}

async function applyCharacterToriAnalysis() {
  if (!state.characterId || !characterAnalysisField) return;
  const label = CHARACTER_TORI_FIELDS.find((item) => item.key === characterAnalysisField)?.label || i18n.t('app.이_칸');
  const ok = window.confirm(
    `「${label}」을(를) 토리 분석으로 바꿀까요?\n지금 적어 둔 내용은 사라집니다.`,
  );
  if (!ok) return;
  const result = await api(`/api/characters/${state.characterId}/tori-analysis/apply`, {
    method: "POST",
    body: JSON.stringify({ field_name: characterAnalysisField }),
  });
  closeCharacterAnalysisModal();
  state.character = result;
  const character = result?.character;
  if (character) {
    if ($("characterSummary")) $("characterSummary").value = character.short_description || "";
    if ($("characterProfile")) $("characterProfile").value = character.profile_md || "";
    if ($("characterStrengths")) $("characterStrengths").value = character.strengths_md || "";
    if ($("characterWeaknesses")) $("characterWeaknesses").value = character.weaknesses_md || "";
    if (Array.isArray(result.aliases)) {
      setCharacterAliases(result.aliases);
    }
    if (state.character.character) {
      state.character.character = character;
    }
    syncCharacterToriBadges(character);
    syncCharacterToriDraftStyle();
  }
  await loadProject();
  toast(i18n.t('app.토리_분석으로_바꿨어요'));
}

async function applyWorldToriAnalysis() {
  if (!state.projectId || !characterAnalysisField) return;
  const label = worldFieldLabel(characterAnalysisField);
  const ok = window.confirm(
    `「${label}」을(를) 토리 분석으로 바꿀까요?\n지금 적어 둔 내용은 사라집니다.`,
  );
  if (!ok) return;
  const result = await api(`/api/projects/${state.projectId}/world-analysis/apply`, {
    method: "POST",
    body: JSON.stringify({ field_name: characterAnalysisField }),
  });
  closeCharacterAnalysisModal();
  state.worldbuildingMd = result?.worldbuilding_md || "";
  state.worldToriAnalysis = result?.world_tori_analysis && typeof result.world_tori_analysis === "object"
    ? result.world_tori_analysis
    : {};
  worldbuildingExampleDraft = false;
  syncWorldBuildingFormFromState({ force: true });
  syncWorldToriBadges();
  toast(i18n.t('app.토리_분석으로_바꿨어요'));
}

function setupCharacterAnalysisModal() {
  document.querySelectorAll("[data-close-character-analysis]").forEach((el) => {
    el.addEventListener("click", () => closeCharacterAnalysisModal());
  });
  $("characterAnalysisApplyButton")?.addEventListener("click", () => {
    if (characterAnalysisKind === "world") {
      applyWorldToriAnalysis().catch(handleError);
    } else if (characterAnalysisKind === "item") {
      applyItemToriAnalysis().catch(handleError);
    } else {
      applyCharacterToriAnalysis().catch(handleError);
    }
  });
  document.querySelectorAll(".character-analysis-badge:not(.world-analysis-badge):not(.item-analysis-badge)").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      openCharacterAnalysisModal(button.getAttribute("data-tori-field") || "");
    });
  });
  document.querySelectorAll(".item-analysis-badge").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      openItemAnalysisModal(button.getAttribute("data-item-tori-field") || "");
    });
  });
  document.addEventListener("click", (event) => {
    const fillBtn = event.target?.closest?.("[data-tori-fill]");
    if (fillBtn) {
      event.preventDefault();
      startToriSettingsFill(fillBtn.getAttribute("data-tori-fill") || "").catch(handleError);
      return;
    }
    const button = event.target?.closest?.(".world-analysis-badge");
    if (!button) return;
    event.preventDefault();
    event.stopPropagation();
    openWorldAnalysisModal(button.getAttribute("data-world-tori-field") || "");
  });
  CHARACTER_TORI_FIELDS.forEach((item) => {
    const el = $(item.inputId);
    if (!el) return;
    el.addEventListener("input", (event) => {
      claimToriDraftOnInput(el, event);
    });
    el.addEventListener("compositionend", () => {
      claimToriDraftOnInput(el);
    });
  });
  $("characterChronicleButton")?.addEventListener("click", (event) => {
    event.preventDefault();
    toggleCharacterChronicle().catch(handleError);
  });
  $("itemChronicleButton")?.addEventListener("click", (event) => {
    event.preventDefault();
    toggleItemChronicle().catch(handleError);
  });
}

function setChronicleOpen(kind, open) {
  const panel = $(kind === "item" ? "itemChronicle" : "characterChronicle");
  const button = $(kind === "item" ? "itemChronicleButton" : "characterChronicleButton");
  if (panel) {
    panel.classList.toggle("hidden", !open);
    panel.hidden = !open;
  }
  button?.setAttribute("aria-pressed", open ? "true" : "false");
}

function resetCharacterChronicle() {
  setChronicleOpen("character", false);
  const list = $("characterChronicleList");
  if (list) list.innerHTML = "";
}

function resetItemChronicle() {
  setChronicleOpen("item", false);
  const list = $("itemChronicleList");
  if (list) list.innerHTML = "";
}

function chronicleFieldLabel(kind, fieldName) {
  if (kind === "item") {
    if (fieldName === "description") return i18n.t("app.아이템_설명");
    return fieldName;
  }
  const meta = CHARACTER_TORI_FIELDS.find((item) => item.key === fieldName);
  return meta?.label || fieldName;
}

function chronicleEpisodeLabel(entry) {
  const inherited = entry?.scene_id == null || entry?.scene_id === "" || Number(entry?.scene_id) <= 0;
  if (inherited) return i18n.t("app.이전_작품에서_이어옴");
  const n = Number(entry?.episode_index);
  const title = String(entry?.scene_title || "").trim();
  const chapter = String(entry?.chapter_title || "").trim();
  const ep = Number.isFinite(n) && n > 0
    ? i18n.t("app.회차_n화", { n })
    : "";
  const bits = [];
  if (ep) bits.push(ep);
  if (chapter && chapter !== title && chapter !== ep) bits.push(chapter);
  if (title && title !== ep) bits.push(title);
  return bits.join(" · ") || i18n.t("app.회차");
}

function renderTraitChronicleList(listEl, entries, kind) {
  if (!listEl) return;
  const rows = Array.isArray(entries) ? entries : [];
  if (!rows.length) {
    listEl.innerHTML = `<p class="hint">${escapeHtml(i18n.t("app.아직_짚어_둔_변화가_없어요"))}</p>`;
    return;
  }
  listEl.innerHTML = rows.map((entry) => {
    const applied = Boolean(entry.applied);
    const status = applied
      ? i18n.t("app.적용됨")
      : i18n.t("app.이미_있던_내용이라_참고만");
    const statusClass = applied ? "is-applied" : "is-reference";
    const sceneId = entry.scene_id == null || entry.scene_id === "" ? 0 : Number(entry.scene_id);
    const inherited = !Number.isFinite(sceneId) || sceneId <= 0;
    const sceneButton = inherited
      ? ""
      : `<button type="button" class="secondary compact-btn" data-chronicle-scene="${sceneId}">${escapeHtml(i18n.t("app.본문_보기"))}</button>`;
    return `<article class="trait-chronicle-item">
      <div class="trait-chronicle-item-head">
        <span class="trait-chronicle-ep">${escapeHtml(chronicleEpisodeLabel(entry))}</span>
        <span class="trait-chronicle-field">${escapeHtml(chronicleFieldLabel(kind, entry.field_name))}</span>
      </div>
      <p class="trait-chronicle-content">${escapeHtml(String(entry.detected_content || ""))}</p>
      <div class="trait-chronicle-actions">
        <span class="trait-chronicle-status ${statusClass}">${escapeHtml(status)}</span>
        ${sceneButton}
      </div>
    </article>`;
  }).join("");
  listEl.querySelectorAll("[data-chronicle-scene]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      openChronicleScene(button.getAttribute("data-chronicle-scene")).catch(handleError);
    });
  });
}

async function loadCharacterChronicle() {
  const list = $("characterChronicleList");
  if (!list || !state.characterId) return;
  list.innerHTML = `<p class="hint">${escapeHtml(i18n.t("app.불러오는_중"))}</p>`;
  const data = await api(`/api/characters/${state.characterId}/trait-history`);
  renderTraitChronicleList(list, data?.entries, "character");
}

async function loadItemChronicle() {
  const list = $("itemChronicleList");
  if (!list || !state.itemId) return;
  list.innerHTML = `<p class="hint">${escapeHtml(i18n.t("app.불러오는_중"))}</p>`;
  const data = await api(`/api/items/${state.itemId}/trait-history`);
  renderTraitChronicleList(list, data?.entries, "item");
}

async function toggleCharacterChronicle() {
  const panel = $("characterChronicle");
  const open = Boolean(panel?.classList.contains("hidden") || panel?.hidden);
  setChronicleOpen("character", open);
  if (open) await loadCharacterChronicle();
}

async function toggleItemChronicle() {
  const panel = $("itemChronicle");
  const open = Boolean(panel?.classList.contains("hidden") || panel?.hidden);
  setChronicleOpen("item", open);
  if (open) await loadItemChronicle();
}

async function openChronicleScene(sceneId) {
  const sid = Number(sceneId);
  if (!Number.isFinite(sid) || sid <= 0) {
    toast(i18n.t("app.씬을_열_수_없어요"));
    return;
  }
  try {
    if (state.characterId) await flushCharacterAutoSave();
  } catch (_) {
    /* keep going */
  }
  try {
    if (state.itemId) await flushItemAutoSave();
  } catch (_) {
    /* keep going */
  }
  await openScene(sid);
}

function stopCharacterAnalysisWatch() {
  if (characterAnalysisWatchTimer) {
    window.clearInterval(characterAnalysisWatchTimer);
    characterAnalysisWatchTimer = 0;
  }
  characterAnalysisWatchProjectId = null;
}

function toastCharacterAnalysisResult(job) {
  const error = String(job?.error || job?.message || "").trim();
  if (error) {
    toast(error);
    return;
  }
  const created = Number(job?.created || 0);
  const filled = Number(job?.filled || 0);
  const pending = Number(job?.pending || 0);
  const worldFilled = Number(job?.world_filled || 0);
  const worldPending = Number(job?.world_pending || 0);
  const parts = [];
  if (created > 0) parts.push(`${i18n.t('app.새_인물_created_명을_목록에_넣었어요', {created: created})}`);
  if (filled > 0) parts.push(i18n.t('app.비어_있던_인물_설정_칸을_채웠어요'));
  if (worldFilled > 0) parts.push(i18n.t('app.비어_있던_세계관_칸을_채웠어요'));
  if (pending > 0) parts.push(i18n.t('app.이미_적어_둔_인물_칸은_그대로_두고_새_분'));
  if (worldPending > 0) parts.push(i18n.t('app.이미_적어_둔_세계관_칸은_그대로_두고_새'));
  if (!parts.length) {
    const filling = Boolean(document.querySelector("[data-tori-fill][aria-busy='true']"));
    if (filling) toast(i18n.t('app.채울_빈_칸이_없거나_이번엔_못_채웠어요'));
    return;
  }
  toast(`${i18n.t('app.토리_parts_join', {'parts.join(". ")': parts.join(". ")})}`);
}

function setToriFillButtonsBusy(busy) {
  document.querySelectorAll("[data-tori-fill]").forEach((button) => {
    button.disabled = Boolean(busy);
    if (busy) button.setAttribute("aria-busy", "true");
    else button.removeAttribute("aria-busy");
  });
}

async function startToriSettingsFill(kind) {
  const target = String(kind || "").trim();
  if (!state.projectId) {
    toast(i18n.t('app.먼저_작품을_선택해_주세요'));
    return;
  }
  const payload = {
    infer: true,
    include_characters: target === "characters",
    include_world: target === "world",
  };
  if (target === "world") {
    pushWorldBuildingFormToState({ commitDraft: false });
  }
  setToriFillButtonsBusy(true);
  try {
    const job = await api(`/api/projects/${state.projectId}/character-analysis`, {
      method: "POST",
      body: JSON.stringify(payload),
    });
    const status = String(job?.status || "idle");
    if (status === "skipped") {
      setToriFillButtonsBusy(false);
      toast(String(job?.error || job?.message || i18n.t('app.이번에는_못_채웠어요')));
      return;
    }
    if (status === "running") {
      toast(i18n.t('app.토리가_빈_칸을_채우는_중이에요'));
      watchCharacterAnalysis(state.projectId);
      return;
    }
    setToriFillButtonsBusy(false);
    toastCharacterAnalysisResult(job);
  } catch (error) {
    setToriFillButtonsBusy(false);
    handleError(error);
  }
}

function watchCharacterAnalysis(projectId) {
  const id = Number(projectId);
  if (!Number.isFinite(id) || id <= 0) return;
  stopCharacterAnalysisWatch();
  characterAnalysisWatchProjectId = id;
  let startedAt = Date.now();
  const tick = async () => {
    if (characterAnalysisWatchProjectId !== id) return;
    try {
      const job = await api(`/api/projects/${id}/character-analysis/status`);
      const status = String(job?.status || "idle");
      if (status === "running") return;
      if (status === "idle" && Date.now() - startedAt < 8000) return;
      stopCharacterAnalysisWatch();
      setToriFillButtonsBusy(false);
      if (status === "done" || status === "skipped") {
        toastCharacterAnalysisResult(job);
        if (status === "done" && Number(state.projectId) === id) {
          await loadProject();
          syncWorldBuildingFormFromState({ force: true });
          syncWorldToriBadges();
          if (state.characterId && !$("characterEditor")?.classList.contains("hidden")) {
            try {
              await openCharacter(state.characterId);
            } catch (_) { /* ignore */ }
          }
        }
      }
    } catch (_) {
      stopCharacterAnalysisWatch();
      setToriFillButtonsBusy(false);
    }
  };
  characterAnalysisWatchTimer = window.setInterval(() => {
    tick().catch(() => { /* keep quiet */ });
  }, 1200);
  tick().catch(() => { /* keep quiet */ });
}

const CHARACTER_EDITOR_FIELD_IDS = [
  "characterName",
  "characterSortName",
  "characterRole",
  "characterSummary",
  "characterProfile",
  "characterStrengths",
  "characterWeaknesses",
  "characterNotes",
];
const CHARACTER_AUTOSAVE_MS = 900;
let characterDirty = false;
let characterAutoSaveTimer = null;
let characterAutoSaveInFlight = false;
let suppressCharacterDirty = false;

function setCharacterSaveStatus(text) {
  if ($("characterInfo")) $("characterInfo").textContent = text || "";
}

function cancelCharacterAutoSave() {
  if (characterAutoSaveTimer) {
    window.clearTimeout(characterAutoSaveTimer);
    characterAutoSaveTimer = null;
  }
}

function splitAliasInput(text) {
  return String(text || "")
    .split(/[,，;/\n]+/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function characterAliasNamesFrom(list) {
  const names = [];
  const seen = new Set();
  (Array.isArray(list) ? list : []).forEach((item) => {
    const name = String(item?.alias || item || "").trim();
    if (!name) return;
    const key = name.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    names.push(name);
  });
  return names;
}

function currentCharacterAliasNames() {
  const fromState = characterAliasNamesFrom(state.character?.aliases);
  const pending = splitAliasInput($("newAlias")?.value || "");
  const seen = new Set(fromState.map((name) => name.toLowerCase()));
  const names = fromState.slice();
  pending.forEach((name) => {
    const key = name.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    names.push(name);
  });
  return names;
}

function sameAliasNames(left, right) {
  const a = characterAliasNamesFrom(left);
  const b = characterAliasNamesFrom(right);
  if (a.length !== b.length) return false;
  return a.every((name, index) => name.toLowerCase() === String(b[index] || "").toLowerCase());
}

function renderAliasList(aliases) {
  const list = $("aliasList");
  if (!list) return;
  const names = characterAliasNamesFrom(aliases);
  if (!names.length) {
    list.innerHTML = i18n.t("app.span_class_hint_아직_별칭이");
    return;
  }
  list.innerHTML = names.map((alias) => `
    <button type="button" class="chip alias-chip${isToriDraftText(alias) ? " is-tori-draft" : ""}" data-alias-remove="${escapeHtml(alias)}" title="${escapeHtml(i18n.t("app.별칭_삭제"))}">
      ${escapeHtml(alias)}
    </button>`).join("");
  list.querySelectorAll("[data-alias-remove]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      removeCharacterAlias(button.dataset.aliasRemove);
    });
  });
}

function setCharacterAliases(names, { render = true } = {}) {
  if (!state.character) state.character = { character: {}, aliases: [] };
  state.character.aliases = characterAliasNamesFrom(names).map((alias) => ({ alias }));
  if (render) renderAliasList(state.character.aliases);
}

function commitAliasInputToState() {
  const input = $("newAlias");
  const pending = splitAliasInput(input?.value || "");
  if (input) input.value = "";
  if (!pending.length || !state.character) return false;
  const merged = characterAliasNamesFrom([
    ...(state.character.aliases || []),
    ...pending,
  ]);
  if (sameAliasNames(merged, state.character.aliases)) return false;
  setCharacterAliases(merged);
  return true;
}

function removeCharacterAlias(alias) {
  if (!state.character || suppressCharacterDirty) return;
  const target = String(alias || "").trim().toLowerCase();
  if (!target) return;
  const next = characterAliasNamesFrom(state.character.aliases)
    .filter((name) => name.toLowerCase() !== target);
  setCharacterAliases(next);
  markCharacterDirty();
}

function characterEditorPayload() {
  return {
    name: String($("characterName")?.value || "").trim(),
    sort_name: String($("characterSortName")?.value || ""),
    role: characterStoryRole($("characterRole")?.value),
    short_description: String($("characterSummary")?.value || ""),
    profile_md: String($("characterProfile")?.value || ""),
    strengths_md: String($("characterStrengths")?.value || ""),
    weaknesses_md: String($("characterWeaknesses")?.value || ""),
    author_notes_md: String($("characterNotes")?.value || ""),
    aliases: currentCharacterAliasNames(),
    row_version: state.character?.character?.row_version,
  };
}

function characterPayloadUnchanged(payload) {
  const ch = state.character?.character;
  if (!ch) return false;
  return (
    payload.name === String(ch.name || "").trim()
    && payload.sort_name === String(ch.sort_name || "")
    && characterStoryRole(payload.role) === characterStoryRole(ch.role)
    && payload.short_description === String(ch.short_description || "")
    && payload.profile_md === String(ch.profile_md || "")
    && payload.strengths_md === String(ch.strengths_md || "")
    && payload.weaknesses_md === String(ch.weaknesses_md || "")
    && payload.author_notes_md === String(ch.author_notes_md || "")
    && sameAliasNames(payload.aliases, state.character?.aliases)
  );
}

function applyCharacterSaveToState(payload) {
  if (state.character?.character) {
    const currentVersion = Number(state.character.character.row_version || 0);
    Object.assign(state.character.character, {
      name: payload.name,
      sort_name: payload.sort_name,
      role: payload.role || "",
      short_description: payload.short_description,
      profile_md: payload.profile_md,
      strengths_md: payload.strengths_md,
      weaknesses_md: payload.weaknesses_md,
      author_notes_md: payload.author_notes_md,
    });
    if (currentVersion > 0) {
      state.character.character.row_version = currentVersion + 1;
    }
  }
  if (Array.isArray(payload.aliases)) {
    setCharacterAliases(payload.aliases);
    if ($("newAlias")) $("newAlias").value = "";
  }
  const listItem = state.characters.find((item) => Number(item.id) === Number(state.characterId));
  if (listItem) {
    listItem.name = payload.name;
    listItem.sort_name = payload.sort_name;
    listItem.role = payload.role || "";
    listItem.short_description = payload.short_description;
    listItem.profile_md = payload.profile_md;
    listItem.strengths_md = payload.strengths_md;
    listItem.weaknesses_md = payload.weaknesses_md;
    listItem.author_notes_md = payload.author_notes_md;
  }
}

function markCharacterDirty() {
  if (suppressCharacterDirty || !state.characterId || !state.character) return;
  characterDirty = true;
  setCharacterSaveStatus(i18n.t("app.저장_대기_중"));
  scheduleCharacterAutoSave();
}

function scheduleCharacterAutoSave() {
  if (!state.characterId || !state.character) return;
  cancelCharacterAutoSave();
  characterAutoSaveTimer = window.setTimeout(() => {
    characterAutoSaveTimer = null;
    persistCharacter({ quiet: true }).catch(handleError);
  }, CHARACTER_AUTOSAVE_MS);
}

async function persistCharacter(options = {}) {
  const quiet = Boolean(options.quiet);
  const characterId = options.characterId ?? state.characterId;
  const payload = options.payload || characterEditorPayload();
  if (!characterId || (!state.character && !options.payload)) return;
  if (!payload.name) {
    setCharacterSaveStatus(i18n.t("app.이름을_입력해야_저장됩니다"));
    if (!quiet) toast(i18n.t("app.캐릭터_이름을_적어_주세요"));
    return;
  }
  if (!options.payload && characterPayloadUnchanged(payload)) {
    characterDirty = false;
    cancelCharacterAutoSave();
    if (!quiet) {
      const stamp = new Date().toLocaleTimeString("ko-KR", { hour: "2-digit", minute: "2-digit", second: "2-digit" });
      setCharacterSaveStatus(`${i18n.t("app.저장됨_stamp", { stamp })}`);
      toast(i18n.t("app.인물_설정을_저장했습니다"));
    }
    return;
  }
  if (characterAutoSaveInFlight) {
    if (quiet && !options.payload) {
      scheduleCharacterAutoSave();
      return;
    }
    for (let i = 0; i < 40 && characterAutoSaveInFlight; i += 1) {
      await new Promise((r) => window.setTimeout(r, 50));
    }
  }
  characterAutoSaveInFlight = true;
  if (quiet) setCharacterSaveStatus(i18n.t("app.자동_저장_중"));
  let saved = false;
  try {
    await api(`/api/characters/${characterId}`, {
      method: "PUT",
      body: JSON.stringify({
        ...payload,
        row_version: payload.row_version ?? state.character?.character?.row_version,
      }),
    });
    characterDirty = false;
    saved = true;
    if (Number(state.characterId) === Number(characterId)) {
      applyCharacterSaveToState(payload);
      renderCharacters();
    }
    const stamp = new Date().toLocaleTimeString("ko-KR", { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    setCharacterSaveStatus(
      quiet
        ? `${i18n.t("app.자동_저장됨_stamp", { stamp })}`
        : `${i18n.t("app.저장됨_stamp", { stamp })}`,
    );
    if (!quiet) toast(i18n.t("app.인물_설정을_저장했습니다"));
  } catch (error) {
    if (quiet) {
      setCharacterSaveStatus(i18n.t("app.자동_저장_실패_다시_시도"));
      scheduleCharacterAutoSave();
    }
    throw error;
  } finally {
    characterAutoSaveInFlight = false;
  }
  if (saved && characterDirty) scheduleCharacterAutoSave();
}

async function flushCharacterAutoSave() {
  const hasPendingAlias = Boolean(String($("newAlias")?.value || "").trim());
  const shouldSave = characterDirty || hasPendingAlias;
  const payload = shouldSave ? characterEditorPayload() : null;
  const characterId = state.characterId;
  cancelCharacterAutoSave();
  if (characterAutoSaveInFlight) {
    for (let i = 0; i < 40 && characterAutoSaveInFlight; i += 1) {
      await new Promise((r) => window.setTimeout(r, 50));
    }
  }
  if (!shouldSave || !payload || !characterId) return;
  await persistCharacter({ quiet: true, characterId, payload });
}

function setupCharacterEditorAutosave() {
  const form = $("characterEditor");
  if (!form || form.dataset.autosaveBound === "1") return;
  form.dataset.autosaveBound = "1";
  setupCharacterRoleChips();
  CHARACTER_EDITOR_FIELD_IDS.forEach((id) => {
    const el = $(id);
    if (!el) return;
    el.addEventListener("input", markCharacterDirty);
    el.addEventListener("change", markCharacterDirty);
    el.addEventListener("blur", () => {
      if (!characterDirty) return;
      cancelCharacterAutoSave();
      persistCharacter({ quiet: true }).catch(handleError);
    });
  });
  const aliasInput = $("newAlias");
  if (aliasInput) {
    aliasInput.addEventListener("input", markCharacterDirty);
    aliasInput.addEventListener("change", markCharacterDirty);
    aliasInput.addEventListener("blur", () => {
      commitAliasInputToState();
      if (!characterDirty) return;
      cancelCharacterAutoSave();
      persistCharacter({ quiet: true }).catch(handleError);
    });
  }
}

async function openCharacter(characterId) {
  if (typeof isGlumpSprintActive === "function" && isGlumpSprintActive() && !confirmLeaveGlumpSprint()) {
    return;
  }
  const nextId = Number(characterId);
  if (state.characterId && Number(state.characterId) !== nextId) {
    try {
      await flushCharacterAutoSave();
    } catch (_) {
      /* keep going so the next character still opens */
    }
  }
  await closeSplitView();
  if (sceneDirty && state.sceneId) {
    try {
      await persistScene({ quiet: true, saveNote: i18n.t("app.자동_저장") });
    } catch (_) {
      /* keep going so the character still opens */
    }
  }
  state.ideaBoardOpen = false;
  state.characterBoardOpen = false;
  state.keywordBoardOpen = false;
  $("ideaBoard")?.classList.add("hidden");
  $("keywordBoard")?.classList.add("hidden");
  $("characterBoard")?.classList.add("hidden");
  hideRelationCanvas();
  hideItemViews();
  hideSynopsisMain();
  hideGitsiWorkspace();
  hideSettingsSearchBoard();
  state.characterId = nextId;
  state.character = await api(`/api/characters/${characterId}`);
  const character = state.character.character;
  setActiveBinder("settings");
  state.openSettingsSection = "characters";
  applySettingsSectionState();
  $("welcome").classList.add("hidden");
  $("sceneWorkspace").classList.add("hidden");
  $("characterEditor").classList.remove("hidden");
  closeSceneToolsDrawer();
  suppressCharacterDirty = true;
  cancelCharacterAutoSave();
  characterDirty = false;
  $("characterName").value = character.name;
  $("characterSortName").value = character.sort_name;
  syncCharacterRoleChips(character.role);
  $("characterSummary").value = character.short_description;
  $("characterProfile").value = character.profile_md;
  if ($("characterStrengths")) $("characterStrengths").value = character.strengths_md || "";
  if ($("characterWeaknesses")) $("characterWeaknesses").value = character.weaknesses_md || "";
  $("characterNotes").value = character.author_notes_md;
  state.character.aliases = Array.isArray(state.character.aliases)
    ? state.character.aliases.map((item) => ({ ...item }))
    : [];
  if ($("newAlias")) $("newAlias").value = "";
  renderAliasList(state.character.aliases);
  $("characterInfo").textContent = "";
  suppressCharacterDirty = false;
  renderCharacterPortrait(character);
  syncCharacterToriBadges(character);
  syncCharacterToriDraftStyle();
  resetCharacterChronicle();
  await loadProject();
}

async function saveCharacter(event) {
  event.preventDefault();
  cancelCharacterAutoSave();
  await persistCharacter({ quiet: false });
}

async function deleteCharacter() {
  if (!state.characterId || !state.character?.character) return;
  const name = String(state.character.character.name || i18n.t('app.이_인물')).trim() || i18n.t('app.이_인물');
  const ok = window.confirm(
    `「${name}」 인물 설정을 삭제할까요?\n\n목록에서 사라지고, 회차에 연결된 등장 정보도 빠집니다.`,
  );
  if (!ok) return;
  cancelCharacterAutoSave();
  characterDirty = false;
  await api(`/api/characters/${state.characterId}`, { method: "DELETE" });
  const deletedId = state.characterId;
  state.characterId = null;
  state.character = null;
  $("characterEditor")?.classList.add("hidden");
  await loadProject();
  // Re-open character board if still on settings characters
  state.openSettingsSection = "characters";
  applySettingsSectionState();
  await openCharacterBoard();
  toast(`${i18n.t('app.name_을_를_삭제했어요', {name: name})}`);
  return deletedId;
}

async function uploadCharacterPortrait(file) {
  if (!state.characterId) return toast(i18n.t('app.인물을_먼저_열어_주세요'));
  if (!file) return;
  if (!file.type.startsWith("image/")) return toast(i18n.t('app.이미지_파일만_올릴_수_있어요'));
  toast(i18n.t('app.이미지를_올리는_중'));
  const contentBase64 = await fileToBase64(file);
  const result = await api(`/api/characters/${state.characterId}/portrait`, {
    method: "POST",
    body: JSON.stringify({
      filename: file.name,
      mime_type: file.type,
      content_base64: contentBase64,
    }),
  });
  if (state.character?.character) {
    state.character.character.portrait_url = result.portrait_url || "";
    state.character.character.portrait_file = result.portrait_file || "";
    state.character.character.row_version = result.row_version
      || state.character.character.row_version;
  }
  renderCharacterPortrait(state.character?.character);
  toast(i18n.t('app.캐릭터_이미지를_넣었어요'));
}

async function clearCharacterPortrait() {
  if (!state.characterId) return;
  if (!window.confirm(i18n.t('app.캐릭터_이미지를_제거할까요'))) return;
  await api(`/api/characters/${state.characterId}/portrait`, { method: "DELETE" });
  if (state.character?.character) {
    state.character.character.portrait_url = "";
    state.character.character.portrait_file = "";
  }
  renderCharacterPortrait(state.character?.character);
  toast(i18n.t('app.캐릭터_이미지를_제거했어요'));
}

function setupCharacterPortraitUi() {
  $("characterPortraitAddButton")?.addEventListener("click", () => {
    $("characterPortraitFile")?.click();
  });
  $("characterPortraitClearButton")?.addEventListener("click", () => {
    clearCharacterPortrait().catch(handleError);
  });
  $("characterPortraitFile")?.addEventListener("change", () => {
    const file = $("characterPortraitFile")?.files?.[0];
    if ($("characterPortraitFile")) $("characterPortraitFile").value = "";
    if (!file) return;
    uploadCharacterPortrait(file).catch(handleError);
  });
  $("deleteCharacterButton")?.addEventListener("click", () => {
    deleteCharacter().catch(handleError);
  });
}

async function addAlias() {
  if (!state.characterId || !state.character) return;
  const added = commitAliasInputToState();
  if (!added) return;
  cancelCharacterAutoSave();
  await persistCharacter({ quiet: true });
  toast(i18n.t("app.별칭을_추가했습니다"));
}

function allScenes() {
  return flattenAllOutlineScenes().map((scene) => ({
    ...scene,
    chapterTitle: scene.chapterTitle,
  }));
}

const SPLIT_EDIT_STORAGE_KEY = "supertory.splitEditEnabled";

function loadSplitEditPreference() {
  try {
    state.splitEditEnabled = localStorage.getItem(SPLIT_EDIT_STORAGE_KEY) === "1";
  } catch (_) {
    state.splitEditEnabled = false;
  }
}

function setSplitEditEnabled(enabled, options = {}) {
  const next = Boolean(enabled);
  const changed = state.splitEditEnabled !== next;
  state.splitEditEnabled = next;
  try {
    localStorage.setItem(SPLIT_EDIT_STORAGE_KEY, next ? "1" : "0");
  } catch (_) {
    /* ignore */
  }
  applySplitEditMode();
  if (changed && !options.silent) {
    toast(next
      ? i18n.t('app.분할_자유_편집을_켰어요_끄기_전까지_유지됩')
      : i18n.t('app.분할_자유_편집을_껐어요_읽기_전용입니다'));
  }
}

function applySplitEditMode() {
  const viewer = $("splitViewer");
  const body = $("splitSceneBodyEditor");
  const title = $("splitSceneTitleInput");
  const btn = $("toggleSplitEditButton");
  const sourceMode = state.splitEnabled && state.splitKind === "source";
  const on = Boolean(state.splitEditEnabled && state.splitEnabled && !sourceMode);
  viewer?.classList.toggle("split-edit-on", on);
  if (body) {
    body.setAttribute("contenteditable", on ? "true" : "false");
    body.spellcheck = on;
  }
  if (title) {
    title.readOnly = !on;
    title.tabIndex = on ? 0 : -1;
  }
  if (btn) {
    btn.classList.toggle("is-on", on);
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    btn.classList.toggle("hidden", sourceMode);
    btn.disabled = sourceMode;
    // Short labels fit between "함께볼 회차" and the split-mode control.
    btn.textContent = on ? i18n.t('app.편집_중') : i18n.t('app.자유_편집');
    btn.title = sourceMode
      ? i18n.t('app.참고자료는_패널_안_편집_버튼으로_수정하세요')
      : on
        ? i18n.t('app.자유_편집_켜짐_누르면_읽기_전용으로_돌아갑')
        : i18n.t('app.함께보는_회차를_자유롭게_편집합니다_한_번');
  }
  if (sourceMode) applySplitSourceEditUi();
}

let splitDirty = false;
let splitAutoSaveTimer = null;
let splitAutoSaveInFlight = false;
let suppressSplitDirty = false;

function setSplitSaveStatus(text) {
  if ($("splitSaveInfo")) $("splitSaveInfo").textContent = text || "";
}

function markSplitDirty() {
  if (suppressSplitDirty || !state.splitEditEnabled || !state.splitSceneId) return;
  splitDirty = true;
  setSplitSaveStatus(isOnlineNow() ? i18n.t('app.저장_대기_중') : i18n.t('app.오프라인_이_기기에_보관_중'));
  // Immediate local snapshot for split editor.
  try {
    const bodyEl = $("splitSceneBodyEditor");
    const titleEl = $("splitSceneTitleInput");
    if (bodyEl) {
      writeLocalSceneDraftSync({
        v: 1,
        sceneId: Number(state.splitSceneId),
        projectId: state.projectId != null ? Number(state.projectId) : null,
        title: titleEl?.value || state.splitScene?.title || "",
        status: state.splitScene?.status || "draft",
        synopsis_md: state.splitScene?.synopsis_md || "",
        notes_md: state.splitScene?.notes_md || "",
        content_md: getEditorContent(bodyEl),
        reference_links: state.splitScene?.reference_links || [],
        goal_word_count: state.splitScene?.goal_word_count || 0,
        goal_metric: state.splitScene?.goal_metric || "chars_with_space",
        row_version: state.splitScene?.row_version ?? null,
        savedAt: Date.now(),
        reason: "split-edit",
        dirty: true,
      });
    }
  } catch (_) {
    /* ignore */
  }
  if (splitAutoSaveTimer) window.clearTimeout(splitAutoSaveTimer);
  splitAutoSaveTimer = window.setTimeout(() => {
    persistSplitScene({ quiet: true }).catch((error) => {
      if (!isOfflineSafeError(error)) handleError(error);
      else notifyLocalDraftKept(error);
    });
  }, 1200);
}

function cancelSplitAutoSave() {
  if (splitAutoSaveTimer) {
    window.clearTimeout(splitAutoSaveTimer);
    splitAutoSaveTimer = null;
  }
}

async function persistSplitScene(options = {}) {
  const quiet = Boolean(options.quiet);
  if (!state.splitSceneId || !state.splitScene) return null;
  if (!state.splitEditEnabled && quiet) return null;
  if (splitAutoSaveInFlight) {
    if (quiet) markSplitDirty();
    return null;
  }
  const titleEl = $("splitSceneTitleInput");
  const bodyEl = $("splitSceneBodyEditor");
  if (!titleEl || !bodyEl) return null;
  let title = (titleEl.value || "").trim();
  if (!title) {
    title = state.splitScene.title || i18n.t('app.제목_없음');
    titleEl.value = title;
  }
  const scene = state.splitScene;
  const body = {
    title,
    status: scene.status || "draft",
    synopsis_md: scene.synopsis_md || "",
    notes_md: scene.notes_md || "",
    content_md: getEditorContent(bodyEl),
    reference_links: Array.isArray(scene.reference_links) ? scene.reference_links : [],
    goal_word_count: Math.max(0, Number(scene.goal_word_count || 0) || 0),
    goal_metric: scene.goal_metric || "chars_with_space",
    row_version: scene.row_version,
    save_note: quiet ? i18n.t('app.자동_저장') : i18n.t('app.저장'),
  };
  // Local-first for split pane too.
  writeLocalSceneDraftSync({
    v: 1,
    sceneId: Number(state.splitSceneId),
    projectId: state.projectId != null ? Number(state.projectId) : null,
    title: body.title,
    status: body.status,
    synopsis_md: body.synopsis_md,
    notes_md: body.notes_md,
    content_md: body.content_md,
    reference_links: body.reference_links,
    goal_word_count: body.goal_word_count,
    goal_metric: body.goal_metric,
    row_version: body.row_version,
    savedAt: Date.now(),
    reason: quiet ? "split-auto" : "split-manual",
    dirty: true,
  });

  splitAutoSaveInFlight = true;
  if (quiet) setSplitSaveStatus(isOnlineNow() ? i18n.t('app.자동_저장_중') : i18n.t('app.오프라인_보관_중'));
  try {
    if (!isOnlineNow()) {
      const offlineErr = new Error(i18n.t('app.오프라인_분할_창_원고를_기기에_보관했습니다'));
      offlineErr.isNetwork = true;
      offlineErr.offlineSafe = true;
      throw offlineErr;
    }
    const saved = await api(`/api/scenes/${state.splitSceneId}`, {
      method: "PUT",
      body: JSON.stringify(body),
    });
    if (saved && typeof saved === "object") {
      if (saved.row_version != null) state.splitScene.row_version = saved.row_version;
      if (saved.revision_no != null) state.splitScene.revision_no = saved.revision_no;
      if (saved.word_count != null) state.splitScene.word_count = saved.word_count;
    }
    state.splitScene.title = title;
    state.splitScene.content_md = body.content_md;
    splitDirty = false;
    clearLocalSceneDraft(state.splitSceneId);
    const stamp = new Date().toLocaleTimeString("ko-KR", { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    setSplitSaveStatus(quiet ? `${i18n.t('app.자동_저장됨_stamp', {stamp: stamp})}` : `${i18n.t('app.저장됨_stamp', {stamp: stamp})}`);
    // Refresh outline titles if this scene is listed.
    loadProject().catch(() => { /* ignore */ });
    if (!quiet) toast(i18n.t('app.함께보는_회차를_저장했습니다'));
    return saved;
  } catch (error) {
    if (quiet) {
      setSplitSaveStatus(
        isOfflineSafeError(error)
          ? i18n.t('app.이_기기에_보관됨_연결_시_동기화')
          : i18n.t('app.자동_저장_실패_기기에_보관_재시도'),
      );
      markSplitDirty();
      if (isOfflineSafeError(error)) return { localOnly: true, error };
    }
    if (isOfflineSafeError(error)) {
      notifyLocalDraftKept(error);
      if (quiet) return { localOnly: true, error };
    }
    throw error;
  } finally {
    splitAutoSaveInFlight = false;
  }
}

async function flushSplitEdits() {
  if (!splitDirty || !state.splitSceneId) return;
  cancelSplitAutoSave();
  try {
    await persistSplitScene({ quiet: true });
  } catch (_) {
    /* keep going */
  }
}


let splitViewerHomeParent = null;

function ensureSplitViewerHomeParent() {
  const viewer = $("splitViewer");
  if (!viewer) return null;
  const slot = $("focusWriteSplitSlot");
  // Remember the original workspace parent (not the focus-write slot or body portal)
  if (
    !splitViewerHomeParent
    || splitViewerHomeParent === slot
    || splitViewerHomeParent === document.body
  ) {
    if (
      viewer.parentElement
      && viewer.parentElement !== slot
      && viewer.parentElement !== document.body
    ) {
      splitViewerHomeParent = viewer.parentElement;
    }
  }
  return splitViewerHomeParent;
}

/** Keep #splitViewer in workspace (popup / normal) or inside 큰 창 (side split). */
function syncSplitViewerHost() {
  const viewer = $("splitViewer");
  const slot = $("focusWriteSplitSlot");
  const card = $("focusWriteCard");
  if (!viewer) return;
  const home = ensureSplitViewerHomeParent();
  const focusOpen = typeof isFocusWriteOpen === "function" && isFocusWriteOpen();
  const embedSplit = focusOpen && state.splitEnabled && state.splitMode === "split" && slot;
  // 큰 창 위 팝업: body로 포털해 워크스페이스 스택에 갇히지 않게
  const popupOverFocus = focusOpen && state.splitEnabled && state.splitMode === "popup";

  if (embedSplit) {
    if (viewer.parentElement !== slot) slot.appendChild(viewer);
    slot.hidden = false;
    card?.classList.add("is-split");
    viewer.classList.add("in-focus-write");
    viewer.classList.remove("popup-mode");
    // Clear fixed popup geometry so flex slot can size the pane
    clearSplitViewerPopupStyles();
  } else if (popupOverFocus) {
    if (viewer.parentElement !== document.body) document.body.appendChild(viewer);
    if (slot) slot.hidden = true;
    card?.classList.remove("is-split");
    viewer.classList.remove("in-focus-write");
  } else {
    if (home && viewer.parentElement !== home) home.appendChild(viewer);
    if (slot) slot.hidden = true;
    card?.classList.remove("is-split");
    viewer.classList.remove("in-focus-write");
  }
}

function updateSplitChrome() {
  const mainBtn = $("splitViewButton");
  const focusBtn = $("focusWriteSplitButton");
  const switchBtn = $("switchSplitModeButton");
  const viewer = $("splitViewer");
  const syncMainLike = (btn, { iconOnly = false } = {}) => {
    if (!btn) return;
    if (!state.splitEnabled) {
      if (!iconOnly) btn.textContent = i18n.t('app.분할');
      btn.title = i18n.t('app.분할_다른_회차를_화면_나누기_또는_팝업으로');
      btn.classList.remove("is-active");
      btn.disabled = !state.sceneId;
      return;
    }
    btn.disabled = false;
    btn.classList.add("is-active");
    if (state.splitMode === "popup") {
      if (!iconOnly) btn.textContent = i18n.t('app.팝업_중');
      btn.title = i18n.t('app.팝업으로_보는_중_Ctrl_Alt_S_화면');
    } else {
      if (!iconOnly) btn.textContent = i18n.t('app.화면_나누기_중');
      btn.title = i18n.t('app.화면_나누기_중_Ctrl_Alt_P_팝업_E');
    }
  };
  if (!state.splitEnabled) {
    syncMainLike(mainBtn, { iconOnly: Boolean(mainBtn?.classList.contains("format-split-btn")) });
    syncMainLike(focusBtn);
    if (switchBtn) {
      switchBtn.textContent = i18n.t('app.보기_방식');
      switchBtn.disabled = false;
    }
    $("viewModeCloseItem")?.classList.add("hidden");
    applySplitEditMode();
    return;
  }
  syncMainLike(mainBtn, { iconOnly: Boolean(mainBtn?.classList.contains("format-split-btn")) });
  syncMainLike(focusBtn);
  if (switchBtn) {
    switchBtn.disabled = false;
    // Keep short so SuperTORY clip / narrow split pane does not hide the control.
    if (state.splitMode === "popup") {
      switchBtn.textContent = i18n.t('app.팝업');
      switchBtn.title = i18n.t('app.보기_방식_팝업_중_Ctrl_Alt_S_나누');
    } else {
      switchBtn.textContent = i18n.t('app.나누기');
      switchBtn.title = i18n.t('app.보기_방식_화면_나누기_중_Ctrl_Alt');
    }
  }
  $("viewModeCloseItem")?.classList.remove("hidden");
  viewer?.classList.toggle("popup-mode", state.splitMode === "popup");
  applySplitEditMode();
}

/** Clear fixed popup geometry so split (side-by-side) layout can size the pane again. */
function clearSplitViewerPopupStyles() {
  const viewer = $("splitViewer");
  if (!viewer) return;
  viewer.style.top = "";
  viewer.style.left = "";
  viewer.style.right = "";
  viewer.style.bottom = "";
  viewer.style.width = "";
  viewer.style.height = "";
  viewer.style.position = "";
  viewer.style.minWidth = "";
  viewer.style.minHeight = "";
  viewer.style.maxWidth = "";
  viewer.style.maxHeight = "";
}

function applySplitLayout() {
  const workspace = $("sceneWorkspace");
  const viewer = $("splitViewer");
  const resizer = $("splitPaneResizer");
  const focusResizer = $("focusWriteSplitResizer");
  if (!workspace || !viewer) return;
  const focusOpen = typeof isFocusWriteOpen === "function" && isFocusWriteOpen();
  const splitOn = state.splitEnabled && state.splitMode === "split";
  const popupOn = state.splitEnabled && state.splitMode === "popup";
  // Side-by-side lives inside 큰 창 when focus-write is open — keep main workspace unsplit
  workspace.classList.toggle("split-active", splitOn && !focusOpen);
  syncSplitViewerHost();
  viewer.classList.toggle("popup-mode", popupOn);
  viewer.classList.toggle("hidden", !state.splitEnabled);
  resizer?.classList.toggle("hidden", !(splitOn && !focusOpen));
  focusResizer?.classList.toggle("hidden", !(splitOn && focusOpen));
  // Leaving popup → split: strip drag/resize inline styles or the pane vanishes off-layout
  if (splitOn && !focusOpen) {
    clearSplitViewerPopupStyles();
    requestAnimationFrame(() => {
      ensureSplitLeftWidth();
      layoutSplitPrimaryPane();
      requestAnimationFrame(() => {
        ensureSplitLeftWidth();
        layoutSplitPrimaryPane();
        // Source file pane may need a second pass after flex settles
        if (state.splitKind === "source") {
          setSplitSourceUiMode(true);
          const textEl = $("splitSourceText");
          if (textEl && !textEl.classList.contains("hidden")) {
            textEl.style.minHeight = "";
            textEl.style.display = "";
            textEl.style.visibility = "";
          }
        }
      });
    });
  } else if (splitOn && focusOpen) {
    clearSplitViewerPopupStyles();
    clearSplitPrimaryPaneLayout();
    requestAnimationFrame(() => {
      ensureFocusSplitRightWidth();
    });
  } else {
    clearSplitPrimaryPaneLayout();
  }
  // Entering popup with no geometry: CSS defaults apply once inline sizes are cleared
  if (popupOn && !viewer.style.width) {
    /* rely on .split-viewer.popup-mode CSS */
  }
  updateSplitChrome();
  applySplitEditMode();
  if (state.splitKind === "source") setSplitSourceUiMode(true);
  const editor = $("sceneContent");
  if (editor) {
    editor.setAttribute("contenteditable", "true");
    editor.style.pointerEvents = "auto";
  }
  const form = $("sceneEditor");
  if (form) form.scrollTop = 0;
}

/** Measure left split pane and force the manuscript block to a real pixel height. */
function layoutSplitPrimaryPane() {
  if (!(state.splitEnabled && state.splitMode === "split")) return;
  const column = document.querySelector(".scene-workspace.split-active .writing-column");
  const form = $("sceneEditor");
  const block = form?.querySelector(".writing-block");
  const page = $("manuscriptPage");
  const status = column?.querySelector(".manuscript-status-bar");
  if (!column || !form || !block || !page) return;

  const colH = column.clientHeight || column.getBoundingClientRect().height || 0;
  if (colH < 80) return;

  const statusH = status ? status.getBoundingClientRect().height : 0;
  const formBudget = Math.max(200, Math.floor(colH - statusH - 4));
  form.style.flex = "1 1 auto";
  form.style.minHeight = "0";
  form.style.height = `${formBudget}px`;
  form.style.maxHeight = `${formBudget}px`;
  form.style.overflow = "hidden";

  // Sum chrome rows still in the form flow (서식 등). 요약은 본문 프레임 안 상태바로 이동.
  const formatShell = form.querySelector('.ms-toolbar-shell[data-toolbar-shell="format"]');
  const featureShell = form.querySelector('.ms-toolbar-shell[data-toolbar-shell="feature"]');
  const findBar = $("findBar");
  const chromeStack = form.querySelector("#msChromeStack, .ms-chrome-stack");
  const visibleH = (el) => {
    if (!el || el.classList.contains("is-collapsed") || el.classList.contains("hidden")) return 0;
    if (el.hidden) return 0;
    const style = window.getComputedStyle(el);
    if (style.display === "none" || style.visibility === "hidden") return 0;
    return el.getBoundingClientRect().height || 0;
  };
  const chrome =
    visibleH(chromeStack) +
    visibleH(formatShell) +
    visibleH(featureShell) +
    visibleH(findBar) +
    12;
  const bodyH = Math.max(180, Math.floor(formBudget - chrome));

  block.style.display = "flex";
  block.style.flexDirection = "column";
  block.style.flex = "none";
  block.style.height = `${bodyH}px`;
  block.style.minHeight = `${bodyH}px`;
  block.style.maxHeight = `${bodyH}px`;
  block.style.overflow = "hidden";
  block.style.visibility = "visible";

  page.style.display = "block";
  page.style.height = "100%";
  page.style.minHeight = `${Math.max(160, bodyH - 4)}px`;
  page.style.overflowY = "auto";
  page.style.visibility = "visible";

  const content = $("sceneContent");
  if (content) {
    content.style.display = "block";
    content.style.visibility = "visible";
    // Fill manuscript sheet so the bottom is writable paper, not a dead solid band
    content.style.minHeight = `${Math.max(160, bodyH - 8)}px`;
    content.style.height = "auto";
    content.setAttribute("contenteditable", "true");
  }

  // Right pane: force other-scene / reference body to consume remaining height
  const splitContent = $("splitSceneContent");
  const splitBody = $("splitSceneBodyEditor");
  const sourceView = $("splitSourceViewer");
  const sourceText = $("splitSourceText");
  if (splitContent) {
    splitContent.style.flex = "1 1 0";
    splitContent.style.minHeight = "0";
    splitContent.style.display = "flex";
    splitContent.style.flexDirection = "column";
    splitContent.style.overflow = "hidden";
  }
  if (state.splitKind === "source") {
    if (splitBody) {
      splitBody.classList.add("hidden");
      splitBody.setAttribute("hidden", "");
      splitBody.style.display = "none";
    }
    if (sourceView && !sourceView.classList.contains("hidden")) {
      sourceView.style.flex = "1 1 0";
      sourceView.style.minHeight = "0";
      sourceView.style.display = "flex";
      sourceView.style.flexDirection = "column";
    }
    if (sourceText && !sourceText.classList.contains("hidden")) {
      sourceText.style.flex = "1 1 0";
      sourceText.style.minHeight = "0";
      sourceText.style.height = "100%";
      sourceText.style.overflow = "auto";
    }
  } else if (splitBody && !splitBody.classList.contains("hidden")) {
    splitBody.removeAttribute("hidden");
    splitBody.style.display = "block";
    splitBody.style.flex = "1 1 0";
    splitBody.style.minHeight = "0";
    splitBody.style.height = "100%";
    splitBody.style.overflow = "auto";
  }
}

function clearSplitPrimaryPaneLayout() {
  const form = $("sceneEditor");
  const block = form?.querySelector(".writing-block");
  const page = $("manuscriptPage");
  const content = $("sceneContent");
  [form, block, page, content].forEach((el) => {
    if (!el) return;
    el.style.removeProperty("height");
    el.style.removeProperty("min-height");
    el.style.removeProperty("max-height");
    el.style.removeProperty("flex");
    el.style.removeProperty("overflow");
    el.style.removeProperty("display");
    el.style.removeProperty("visibility");
  });
  if (form) {
    form.style.removeProperty("overflow");
  }
  // Clear side-pane height hacks applied during split layout
  ["splitSceneContent", "splitSceneBodyEditor", "splitSourceViewer", "splitSourceText"].forEach((id) => {
    const el = $(id);
    if (!el) return;
    el.style.removeProperty("height");
    el.style.removeProperty("min-height");
    el.style.removeProperty("max-height");
    el.style.removeProperty("flex");
    el.style.removeProperty("overflow");
    el.style.removeProperty("display");
    el.style.removeProperty("flex-direction");
  });
}

const SPLIT_LEFT_WIDTH_STORAGE_KEY = "supertory.splitLeftWidth";
const SPLIT_LEFT_MIN = 240;
const SPLIT_RIGHT_MIN = 200;
const SPLIT_HANDLE = 28; // layout gutter = full click/hover hit (do not overflow into panes)
const FOCUS_SPLIT_RIGHT_WIDTH_STORAGE_KEY = "supertory.focusSplitRightWidth";
const FOCUS_SPLIT_RIGHT_MIN = 200;
const FOCUS_SPLIT_LEFT_MIN = 280;

function applySplitLeftWidth(widthPx) {
  const workspace = $("sceneWorkspace");
  if (!workspace) return widthPx;
  const total = workspace.getBoundingClientRect().width || window.innerWidth;
  // Guard against zero/invalid container measurements (layout not ready yet).
  if (!Number.isFinite(total) || total < SPLIT_LEFT_MIN + SPLIT_RIGHT_MIN + SPLIT_HANDLE) {
    const fallback = Math.max(SPLIT_LEFT_MIN, Math.round(Number(widthPx) || total * 0.55 || 400));
    workspace.style.setProperty("--split-left-width", `${fallback}px`);
    return fallback;
  }
  const maxLeft = Math.max(SPLIT_LEFT_MIN, total - SPLIT_RIGHT_MIN - SPLIT_HANDLE);
  const raw = Number(widthPx);
  const preferred = Number.isFinite(raw) && raw > 0 ? raw : total * 0.55;
  const width = Math.max(SPLIT_LEFT_MIN, Math.min(maxLeft, Math.round(preferred)));
  workspace.style.setProperty("--split-left-width", `${width}px`);
  return width;
}

function ensureSplitLeftWidth() {
  const workspace = $("sceneWorkspace");
  if (!workspace || !workspace.classList.contains("split-active")) return;
  const current = workspace.style.getPropertyValue("--split-left-width").trim();
  const parsed = current.endsWith("px") ? Number(current.slice(0, -2)) : Number(current);
  if (Number.isFinite(parsed) && parsed >= SPLIT_LEFT_MIN) {
    applySplitLeftWidth(parsed);
    return;
  }
  try {
    const stored = Number(localStorage.getItem(SPLIT_LEFT_WIDTH_STORAGE_KEY));
    if (Number.isFinite(stored) && stored >= SPLIT_LEFT_MIN) {
      applySplitLeftWidth(stored);
      return;
    }
  } catch (_) {
    /* ignore */
  }
  const total = workspace.getBoundingClientRect().width || 800;
  applySplitLeftWidth(total * 0.55);
}

/** 큰 창 함께보기: right pane width (px) via --focus-split-right-width on the card. */
function applyFocusSplitRightWidth(widthPx) {
  const card = $("focusWriteCard");
  const body = $("focusWriteBody");
  if (!card) return widthPx;
  const total = body?.getBoundingClientRect().width
    || card.getBoundingClientRect().width
    || window.innerWidth;
  if (!Number.isFinite(total) || total < FOCUS_SPLIT_LEFT_MIN + FOCUS_SPLIT_RIGHT_MIN + SPLIT_HANDLE) {
    const fallback = Math.max(
      FOCUS_SPLIT_RIGHT_MIN,
      Math.round(Number(widthPx) || Math.min(480, total * 0.42) || 360),
    );
    card.style.setProperty("--focus-split-right-width", `${fallback}px`);
    return fallback;
  }
  const maxRight = Math.max(FOCUS_SPLIT_RIGHT_MIN, total - FOCUS_SPLIT_LEFT_MIN - SPLIT_HANDLE);
  const raw = Number(widthPx);
  const preferred = Number.isFinite(raw) && raw > 0 ? raw : Math.min(480, total * 0.42);
  const width = Math.max(FOCUS_SPLIT_RIGHT_MIN, Math.min(maxRight, Math.round(preferred)));
  card.style.setProperty("--focus-split-right-width", `${width}px`);
  return width;
}

function ensureFocusSplitRightWidth() {
  const card = $("focusWriteCard");
  if (!card || !card.classList.contains("is-split")) return;
  const current = card.style.getPropertyValue("--focus-split-right-width").trim();
  const parsed = current.endsWith("px") ? Number(current.slice(0, -2)) : Number(current);
  if (Number.isFinite(parsed) && parsed >= FOCUS_SPLIT_RIGHT_MIN) {
    applyFocusSplitRightWidth(parsed);
    return;
  }
  try {
    const stored = Number(localStorage.getItem(FOCUS_SPLIT_RIGHT_WIDTH_STORAGE_KEY));
    if (Number.isFinite(stored) && stored >= FOCUS_SPLIT_RIGHT_MIN) {
      applyFocusSplitRightWidth(stored);
      return;
    }
  } catch (_) {
    /* ignore */
  }
  const body = $("focusWriteBody");
  const total = body?.getBoundingClientRect().width || card.getBoundingClientRect().width || 960;
  applyFocusSplitRightWidth(Math.min(480, total * 0.42));
}

function setupSplitPaneResizer() {
  const resizer = $("splitPaneResizer");
  if (!resizer) return;

  try {
    const stored = Number(localStorage.getItem(SPLIT_LEFT_WIDTH_STORAGE_KEY));
    if (Number.isFinite(stored) && stored >= SPLIT_LEFT_MIN) {
      applySplitLeftWidth(stored);
    }
  } catch (_) {
    /* ignore */
  }

  let drag = null;

  const onMove = (event) => {
    if (!drag) return;
    const workspace = $("sceneWorkspace");
    if (!workspace) return;
    const left = workspace.getBoundingClientRect().left;
    const next = applySplitLeftWidth(event.clientX - left);
    drag.currentWidth = next;
    layoutSplitPrimaryPane();
  };

  const onUp = () => {
    if (!drag) return;
    document.body.classList.remove("split-pane-resizing");
    try {
      localStorage.setItem(SPLIT_LEFT_WIDTH_STORAGE_KEY, String(drag.currentWidth || SPLIT_LEFT_MIN));
    } catch (_) {
      /* ignore */
    }
    drag = null;
    layoutSplitPrimaryPane();
    window.removeEventListener("pointermove", onMove);
    window.removeEventListener("pointerup", onUp);
    window.removeEventListener("pointercancel", onUp);
  };

  resizer.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    if (!(state.splitEnabled && state.splitMode === "split")) return;
    if (typeof isFocusWriteOpen === "function" && isFocusWriteOpen()) return;
    const column = document.querySelector(".scene-workspace.split-active .writing-column");
    const startWidth = column
      ? column.getBoundingClientRect().width
      : ($("sceneWorkspace")?.getBoundingClientRect().width || 800) * 0.55;
    drag = {
      currentWidth: startWidth,
    };
    document.body.classList.add("split-pane-resizing");
    try { resizer.setPointerCapture?.(event.pointerId); } catch (_) { /* ignore */ }
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
    event.preventDefault();
  });

  window.addEventListener("resize", () => {
    if (!(state.splitEnabled && state.splitMode === "split")) return;
    if (typeof isFocusWriteOpen === "function" && isFocusWriteOpen()) {
      ensureFocusSplitRightWidth();
      return;
    }
    ensureSplitLeftWidth();
    layoutSplitPrimaryPane();
  });
}

/** 큰 창 함께보기 좌우 너비 조절 (본문 ↔ 함께보기 사이 핸들). */
function setupFocusWriteSplitResizer() {
  const resizer = $("focusWriteSplitResizer");
  if (!resizer || resizer.dataset.bound === "1") return;
  resizer.dataset.bound = "1";

  try {
    const stored = Number(localStorage.getItem(FOCUS_SPLIT_RIGHT_WIDTH_STORAGE_KEY));
    if (Number.isFinite(stored) && stored >= FOCUS_SPLIT_RIGHT_MIN) {
      applyFocusSplitRightWidth(stored);
    }
  } catch (_) {
    /* ignore */
  }

  let drag = null;

  const onMove = (event) => {
    if (!drag) return;
    const body = $("focusWriteBody");
    if (!body) return;
    // Right pane width = distance from pointer to the body's right edge
    const bodyRect = body.getBoundingClientRect();
    const next = applyFocusSplitRightWidth(bodyRect.right - event.clientX);
    drag.currentWidth = next;
  };

  const onUp = () => {
    if (!drag) return;
    document.body.classList.remove("split-pane-resizing");
    try {
      localStorage.setItem(
        FOCUS_SPLIT_RIGHT_WIDTH_STORAGE_KEY,
        String(drag.currentWidth || FOCUS_SPLIT_RIGHT_MIN),
      );
    } catch (_) {
      /* ignore */
    }
    drag = null;
    window.removeEventListener("pointermove", onMove);
    window.removeEventListener("pointerup", onUp);
    window.removeEventListener("pointercancel", onUp);
  };

  resizer.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    if (!(state.splitEnabled && state.splitMode === "split")) return;
    if (!(typeof isFocusWriteOpen === "function" && isFocusWriteOpen())) return;
    const slot = $("focusWriteSplitSlot");
    const startWidth = slot
      ? slot.getBoundingClientRect().width
      : FOCUS_SPLIT_RIGHT_MIN * 2;
    drag = { currentWidth: startWidth };
    document.body.classList.add("split-pane-resizing");
    try { resizer.setPointerCapture?.(event.pointerId); } catch (_) { /* ignore */ }
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
    event.preventDefault();
  });
}

async function closeSplitView() {
  await flushSplitEdits();
  if (splitSourceDirty || splitSourceEditEnabled) {
    try { await saveSplitSourceText({ quiet: true }); } catch (_) { /* ignore */ }
  }
  cancelSplitAutoSave();
  if (splitSourceSaveTimer) {
    window.clearTimeout(splitSourceSaveTimer);
    splitSourceSaveTimer = null;
  }
  splitDirty = false;
  splitSourceDirty = false;
  splitSourceEditEnabled = false;
  splitSourceViewerMode = "";
  hideSplitSourceExportMenu();
  setSplitSaveStatus("");
  state.splitEnabled = false;
  state.splitMode = null;
  state.splitKind = "scene";
  state.splitSceneId = null;
  state.splitScene = null;
  state.splitSourceId = null;
  revokeSplitSourceObjectUrl();
  const linkFrame = $("splitSourceLink");
  if (linkFrame) {
    linkFrame.src = "about:blank";
    linkFrame.classList.add("hidden");
  }
  $("splitViewer")?.classList.remove("source-text-editing");
  setSplitSourceUiMode(false);
  applySplitLayout();
  closeViewModeMenu();
  // Reset popup position/size for next open.
  clearSplitViewerPopupStyles();
}

async function openSecondaryView(mode) {
  if (!state.sceneId) return toast(i18n.t('app.먼저_목차에서_씬_하나를_열어_주세요'));
  const alternative = allScenes().find((scene) => scene.id !== state.sceneId);
  const sources = typeof loadSources === "function" ? loadSources() : [];
  const usableSources = sources.filter((src) => (src.kind === "file" || src.fileName) || String(src.url || "").trim());
  if (!alternative && !usableSources.length) {
    toast(i18n.t('app.함께볼_다른_회차나_참고자료가_없어요'));
    return;
  }
  if (!alternative && usableSources.length) {
    await openSourceInSplit(usableSources[0].id, mode);
    return;
  }
  await flushSplitEdits();
  const previousMode = state.splitMode;
  state.splitEnabled = true;
  state.splitMode = mode === "popup" ? "popup" : "split";
  state.splitKind = "scene";
  state.splitSourceId = null;
  revokeSplitSourceObjectUrl();
  setSplitSourceUiMode(false);
  if (!state.splitSceneId || state.splitSceneId === state.sceneId) {
    state.splitSceneId = alternative.id;
  }
  applySplitLayout();
  closeViewModeMenu();
  await renderSplitViewer();
  if (previousMode && previousMode !== state.splitMode) {
    toast(state.splitMode === "popup" ? i18n.t('app.팝업으로_바꿨어요') : i18n.t('app.화면_나누기로_바꿨어요'));
  } else if (typeof isFocusWriteOpen === "function" && isFocusWriteOpen()) {
    toast(state.splitMode === "popup"
      ? i18n.t('app.큰_창_위에_분할을_팝업으로_열었어요')
      : i18n.t('app.큰_창_옆에_분할을_나란히_열었어요'));
  } else {
    toast(state.splitMode === "popup" ? i18n.t('app.분할을_팝업으로_열었어요') : i18n.t('app.화면을_나눠_분할을_열었어요'));
  }
}

async function handleViewModeChoice(mode) {
  if (mode === "close") {
    await closeSplitView();
    return;
  }
  if (mode !== "split" && mode !== "popup") return;
  // If a reference file is open, keep the file and only switch layout (split ↔ popup)
  if (state.splitEnabled && state.splitKind === "source" && state.splitSourceId) {
    const nextMode = mode === "popup" ? "popup" : "split";
    if (nextMode === "split") clearSplitViewerPopupStyles();
    else if (nextMode === "popup") {
      // Drop side-pane sticky sizing leftovers; popup CSS supplies defaults
      clearSplitViewerPopupStyles();
    }
    state.splitMode = nextMode;
    applySplitLayout();
    setSplitSourceUiMode(true);
    closeViewModeMenu();
    await renderSplitSourceViewer();
    // Re-layout after content paint (source text height)
    if (nextMode === "split") {
      requestAnimationFrame(() => {
        ensureSplitLeftWidth();
        layoutSplitPrimaryPane();
      });
    }
    toast(state.splitMode === "popup" ? i18n.t('app.참고자료를_팝업으로_바꿨어요') : i18n.t('app.참고자료를_화면_나누기로_바꿨어요'));
    return;
  }
  // Scene secondary view: also clear popup styles when switching to split
  if (mode === "split") clearSplitViewerPopupStyles();
  await openSecondaryView(mode);
}

async function switchSplitMode() {
  // Open the mode menu so the user can choose split / popup / close.
  if (!state.splitEnabled) {
    if (!state.sceneId) return toast(i18n.t('app.먼저_목차에서_씬_하나를_열어_주세요'));
    openViewModeMenu("main");
    return;
  }
  openViewModeMenu("split");
}

function fillSplitSceneBody(scene) {
  const body = $("splitSceneBodyEditor");
  const title = $("splitSceneTitleInput");
  if (title) title.value = scene?.title || "";
  if (!body) return;

  const raw = scene?.content_md != null ? String(scene.content_md) : "";
  // Always write into the secondary editor (never touch main #sceneContent).
  if (!raw.trim()) {
    body.innerHTML = "";
  } else if (looksLikeHtml(raw)) {
    body.innerHTML = sanitizeEditorHtml(raw);
  } else {
    body.innerHTML = escapeHtml(raw).replace(/\r\n|\r|\n/g, "<br>");
  }

  // Safety net: if injection failed for any reason, fall back to preview HTML.
  const plainAfter = (body.innerText || body.textContent || "").replace(/\s+/g, "");
  if (!plainAfter && raw.trim()) {
    body.innerHTML = contentToPreviewHtml(raw);
  }

  const empty = !plainTextFromHtml(body.innerHTML) && !body.querySelector("img");
  body.classList.toggle("placeholder-on", empty);
  // Colors come from CSS page theme variables (--page-ink / --page-editor-bg).
  body.style.removeProperty("color");
  body.style.removeProperty("background");
  // Let flex fill the side pane — fixed min-height left a dead solid band below
  body.style.minHeight = "";
  body.style.height = "";
  body.style.flex = "1 1 0";
  body.style.display = "block";
  body.style.visibility = "visible";
  body.style.overflow = "auto";
}

async function renderSplitViewer() {
  if (!state.splitEnabled) return;
  if (state.splitKind === "source") {
    await renderSplitSourceViewer();
    return;
  }
  setSplitSourceUiMode(false);
  const alternatives = allScenes().filter((scene) => scene.id !== state.sceneId);
  const sources = typeof loadSources === "function" ? loadSources() : [];
  const usableSources = sources.filter((src) => (src.kind === "file" || src.fileName) || String(src.url || "").trim());
  if (!alternatives.length) {
    if (usableSources.length) {
      await openSourceInSplit(usableSources[0].id, state.splitMode || "split");
      return;
    }
    await closeSplitView();
    toast(i18n.t('app.함께볼_회차나_참고자료가_없어_분할을_닫았어'));
    return;
  }
  if (!alternatives.some((scene) => scene.id === state.splitSceneId)) {
    state.splitSceneId = alternatives[0].id;
  }
  fillSplitCompanionSelect();
  state.splitScene = await api(`/api/scenes/${state.splitSceneId}`);
  const scene = state.splitScene;
  suppressSplitDirty = true;
  fillSplitSceneBody(scene);
  splitDirty = false;
  suppressSplitDirty = false;
  setSplitSaveStatus(state.splitEditEnabled ? i18n.t('app.편집_가능') : i18n.t('app.읽기_전용'));
  updateSplitChrome();
  applySplitEditMode();
  if (state.splitMode === "split") {
    requestAnimationFrame(() => layoutSplitPrimaryPane());
  }
}

function setupSplitEditMode() {
  loadSplitEditPreference();
  applySplitEditMode();

  $("toggleSplitEditButton")?.addEventListener("click", async () => {
    if (!state.splitEnabled) {
      toast(i18n.t('app.먼저_분할을_켜_주세요'));
      return;
    }
    if (state.splitKind === "source") {
      toast(i18n.t('app.참고자료_파일은_뷰어_전용이에요_수정할_수'));
      return;
    }
    if (state.splitEditEnabled) {
      await flushSplitEdits();
      setSplitEditEnabled(false);
      setSplitSaveStatus(i18n.t('app.읽기_전용'));
    } else {
      setSplitEditEnabled(true);
      setSplitSaveStatus(i18n.t('app.편집_가능'));
      requestAnimationFrame(() => {
        $("splitSceneBodyEditor")?.focus();
      });
    }
  });

  $("splitSceneTitleInput")?.addEventListener("input", () => {
    if (state.splitEditEnabled) markSplitDirty();
  });
  $("splitSceneBodyEditor")?.addEventListener("input", () => {
    if (state.splitEditEnabled) {
      updateEditorPlaceholder($("splitSceneBodyEditor"));
      markSplitDirty();
    }
  });
  $("splitSceneBodyEditor")?.addEventListener("keydown", (event) => {
    if (!state.splitEditEnabled) {
      // Block typing while read-only (some browsers still allow keys on contenteditable=false edges).
      if (!event.ctrlKey && !event.metaKey && event.key.length === 1) event.preventDefault();
      return;
    }
    if (!(event.ctrlKey || event.metaKey)) return;
    const key = event.key.toLowerCase();
    if (key === "b") { event.preventDefault(); applyEditorCommand("bold"); }
    else if (key === "i") { event.preventDefault(); applyEditorCommand("italic"); }
    else if (key === "u") { event.preventDefault(); applyEditorCommand("underline"); }
    else if (key === "x" && event.shiftKey) {
      event.preventDefault();
      applyEditorCommand("strikeThrough");
    }
    else if (key === "s") {
      event.preventDefault();
      persistSplitScene({ quiet: false }).catch(handleError);
    }
  });

  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden" && splitDirty && state.splitEditEnabled) {
      cancelSplitAutoSave();
      persistSplitScene({ quiet: true }).catch(() => { /* ignore */ });
    }
  });
}

function lockPopupViewerGeometry(viewer) {
  if (!viewer) return null;
  const rect = viewer.getBoundingClientRect();
  // Convert right-based CSS positioning into explicit left/top/width/height
  // so free dragging and resizing stay predictable.
  viewer.style.left = `${Math.round(rect.left)}px`;
  viewer.style.top = `${Math.round(rect.top)}px`;
  viewer.style.right = "auto";
  viewer.style.bottom = "auto";
  viewer.style.width = `${Math.round(rect.width)}px`;
  viewer.style.height = `${Math.round(rect.height)}px`;
  return rect;
}

/** Titlebar / caption strip height — used so popup chrome stays clear of Electron drag region. */
function getAppTitlebarInset() {
  const bar = document.querySelector(".app-titlebar");
  if (bar) {
    const h = bar.getBoundingClientRect().height;
    if (Number.isFinite(h) && h > 0) return Math.ceil(h);
  }
  // Electron titleBarOverlay often reports via env; fall back for is-electron shells.
  if (document.documentElement.classList.contains("is-electron")
    || document.body.classList.contains("is-electron")) {
    return 32;
  }
  return 0;
}

function setupPopupDragging() {
  const heading = $("splitHeading");
  const dragBar = $("splitPopupDragBar");
  const viewer = $("splitViewer");
  if (!viewer) return;

  let drag = null;
  let resize = null;
  const MIN_W = 280;
  const MIN_H = 220;

  // Keep Electron from treating this chrome as a window-move region.
  const markNoDrag = (el) => {
    if (!el) return;
    try {
      el.style.webkitAppRegion = "no-drag";
      el.style.appRegion = "no-drag";
    } catch (_) {
      /* ignore */
    }
  };
  markNoDrag(viewer);
  markNoDrag(dragBar);
  markNoDrag(heading);
  viewer.querySelectorAll("[data-resize-edge]").forEach((handle) => markNoDrag(handle));

  const beginDrag = (event, captureEl) => {
    if (state.splitMode !== "popup") return;
    if (event.button != null && event.button !== 0) return;
    // Don't start a move when interacting with form controls / edit surface / resize grip.
    if (event.target.closest("button, select, input, textarea, option, [contenteditable='true'], .split-body-editor, .split-popup-resize-handle, [data-resize-edge], .tory-float-resize")) return;
    // Stop bubbling so parent Electron drag regions never see this gesture.
    event.stopPropagation();
    const rect = lockPopupViewerGeometry(viewer);
    if (!rect) return;
    drag = {
      offsetX: event.clientX - rect.left,
      offsetY: event.clientY - rect.top,
      pointerId: event.pointerId,
    };
    document.body.classList.add("popup-dragging");
    try { captureEl?.setPointerCapture?.(event.pointerId); } catch (_) { /* ignore */ }
    event.preventDefault();
  };

  // Dedicated drag strip — always free to move the popup (not the app window).
  dragBar?.addEventListener("pointerdown", (event) => beginDrag(event, dragBar));
  // Also allow dragging from empty heading chrome (not from select/buttons).
  heading?.addEventListener("pointerdown", (event) => beginDrag(event, heading));

  viewer.querySelectorAll("[data-resize-edge]").forEach((handle) => {
    handle.addEventListener("pointerdown", (event) => {
      if (state.splitMode !== "popup") return;
      if (event.button != null && event.button !== 0) return;
      event.preventDefault();
      event.stopPropagation();
      const rect = lockPopupViewerGeometry(viewer);
      if (!rect) return;
      resize = {
        edge: handle.getAttribute("data-resize-edge") || "se",
        startX: event.clientX,
        startY: event.clientY,
        startLeft: rect.left,
        startTop: rect.top,
        startW: rect.width,
        startH: rect.height,
        pointerId: event.pointerId,
      };
      document.body.classList.add("popup-resizing");
      try { handle.setPointerCapture?.(event.pointerId); } catch (_) { /* ignore */ }
    });
  });

  const onPointerMove = (event) => {
    if (state.splitMode !== "popup") return;
    if (drag && (drag.pointerId == null || drag.pointerId === event.pointerId)) {
      const vw = viewer.getBoundingClientRect().width || 280;
      // Keep a slice of the window on-screen so it can always be grabbed again.
      // Prefer staying below the Electron titlebar so drag chrome never sits in app-region:drag.
      const titleInset = getAppTitlebarInset();
      const maxLeft = Math.max(8, window.innerWidth - 48);
      const maxTop = Math.max(8, window.innerHeight - 40);
      const minLeft = Math.min(8, window.innerWidth - vw);
      const minTop = titleInset > 0 ? titleInset : 0;
      const left = Math.min(maxLeft, Math.max(minLeft, event.clientX - drag.offsetX));
      const top = Math.min(maxTop, Math.max(minTop, event.clientY - drag.offsetY));
      viewer.style.left = `${Math.round(left)}px`;
      viewer.style.top = `${Math.round(top)}px`;
      viewer.style.right = "auto";
      viewer.style.bottom = "auto";
    }
    if (resize && (resize.pointerId == null || resize.pointerId === event.pointerId)) {
      applyFloatingPopupResize(viewer, resize, event, MIN_W, MIN_H);
    }
  };

  const onPointerUp = (event) => {
    if (drag && (drag.pointerId == null || drag.pointerId === event.pointerId)) {
      drag = null;
      document.body.classList.remove("popup-dragging");
    }
    if (resize && (resize.pointerId == null || resize.pointerId === event.pointerId)) {
      resize = null;
      document.body.classList.remove("popup-resizing");
    }
  };

  window.addEventListener("pointermove", onPointerMove);
  window.addEventListener("pointerup", onPointerUp);
  window.addEventListener("pointercancel", onPointerUp);
}

function handleError(error) {
  console.error(error);
  if (error?.aiAssist) {
    handleAiAssistError(error);
    return;
  }
  if (isExternalServiceOfflineMessage(error) && !error?.isNetwork) {
    toast(error.message || i18n.t("app.인터넷_연결이_필요해요"), 4200);
    return;
  }
  // Never scare the writer into thinking manuscript is lost on network blips.
  if (isOfflineSafeError(error) || error?.localOnly) {
    ensureLocalDraftSaved("handleError");
    toast(
      error?.message
      || i18n.t('app.연결_문제로_서버_저장은_보류되었지만_원고는'),
    );
    return;
  }
  toast(error.message || i18n.t('app.문제가_생겼습니다_다시_시도해_주세요'));
}

function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = String(reader.result || "");
      const marker = "base64,";
      const index = result.indexOf(marker);
      resolve(index >= 0 ? result.slice(index + marker.length) : result);
    };
    reader.onerror = () => reject(new Error(i18n.t('app.파일을_읽지_못했습니다')));
    reader.readAsDataURL(file);
  });
}

const EXPORT_FORMATS_UI = [
  { key: "docx", label: "Word", ext: ".docx", hint: i18n.t('app.Microsoft_Word에서_열립니다'), partialOk: true },
  { key: "hwpx", label: i18n.t('app.한글'), ext: ".hwpx", hint: i18n.t('app.한글_2014_이상_hwpx로_저장됩니다'), partialOk: true },
  { key: "rtf", label: "RTF", ext: ".rtf", hint: i18n.t('app.Word_한글에서_열립니다'), partialOk: true },
  { key: "txt", label: i18n.t('app.텍스트'), ext: ".txt", hint: i18n.t('app.메모장_등에서_바로_열립니다'), partialOk: true },
  { key: "md", label: "Markdown", ext: ".md", hint: i18n.t('app.마크다운_편집기에서_열립니다'), partialOk: true },
  { key: "html", label: "HTML", ext: ".html", hint: i18n.t('app.브라우저에서_바로_열립니다'), partialOk: true },
  { key: "stg", label: i18n.t('app.SuperTORY_연결_파일'), ext: ".stg", hint: i18n.t('app.작품_전체만_SuperTORY에서_열림'), partialOk: false },
];

/** @type {{ scope: 'full'|'scenes', sceneIds: number[], lockScope: boolean, titleHint: string }} */
let exportModalState = {
  scope: "full",
  sceneIds: [],
  lockScope: false,
  titleHint: "",
};

/** Local export folder prefs (from /api/export/prefs) */
let exportPrefs = {
  export_dir: "",
  save_to_folder: true,
  reveal_after_save: true,
  default_export_dir: "",
  folder_ok: false,
};

async function loadExportPrefs() {
  try {
    const data = await api("/api/export/prefs");
    exportPrefs = {
      export_dir: String(data.export_dir || ""),
      save_to_folder: data.save_to_folder !== false,
      reveal_after_save: data.reveal_after_save !== false,
      default_export_dir: String(data.default_export_dir || ""),
      folder_ok: Boolean(data.folder_ok),
    };
  } catch (_) {
    /* keep previous / defaults */
  }
  syncExportManageUi();
  return exportPrefs;
}

function syncExportManageUi() {
  const input = $("exportDirInput");
  const saveFolder = $("exportSaveToFolder");
  const reveal = $("exportRevealAfter");
  const hint = $("exportDirHint");
  if (input && document.activeElement !== input) {
    input.value = exportPrefs.export_dir || exportPrefs.default_export_dir || "";
  }
  if (saveFolder) saveFolder.checked = exportPrefs.save_to_folder !== false;
  if (reveal) reveal.checked = exportPrefs.reveal_after_save !== false;
  if (hint) {
    const path = (exportPrefs.export_dir || exportPrefs.default_export_dir || "").trim();
    if (exportPrefs.save_to_folder === false) {
      hint.textContent = i18n.t('app.브라우저_다운로드로_받습니다_보통_다운로드');
    } else if (path) {
      hint.textContent = `${i18n.t('app.저장_위치_path', {path: path})}`;
    } else {
      hint.textContent = i18n.t('app.경로를_비우면_다운로드_폴더에_저장됩니다');
    }
  }
}

async function saveExportPrefsFromUi() {
  const rawDir = ($("exportDirInput")?.value || "").trim();
  const saveToFolder = Boolean($("exportSaveToFolder")?.checked);
  const revealAfter = Boolean($("exportRevealAfter")?.checked);
  const data = await api("/api/export/prefs", {
    method: "POST",
    body: JSON.stringify({
      export_dir: rawDir,
      save_to_folder: saveToFolder,
      reveal_after_save: revealAfter,
    }),
  });
  exportPrefs = {
    export_dir: String(data.export_dir || rawDir || exportPrefs.default_export_dir || ""),
    save_to_folder: data.save_to_folder !== false,
    reveal_after_save: data.reveal_after_save !== false,
    default_export_dir: String(data.default_export_dir || exportPrefs.default_export_dir || ""),
    folder_ok: Boolean(data.folder_ok),
  };
  syncExportManageUi();
  toast(rawDir
    ? i18n.t('app.저장_폴더를_적용했어요_exportPrefs', {
      'exportPrefs.export_dir': exportPrefs.export_dir,
    })
    : i18n.t('app.경로를_비워_두어_다운로드_폴더로_저장합니다', {
      'exportPrefs.export_dir': exportPrefs.export_dir,
    }));
  return exportPrefs;
}

function listExportEpisodes() {
  // Binder folder order (folder.sort_order among siblings), not legacy chapter.sort_order.
  const episodes = [];
  const seen = new Set();
  const pushScene = (scene, chapterTitle) => {
    const id = Number(scene?.id);
    if (!id || seen.has(id)) return;
    seen.add(id);
    const fallback = `${i18n.t('app.회차_id', {id: id})}`;
    const title = String(scene.title || fallback).trim() || fallback;
    const heading = String(chapterTitle || i18n.t('app.챕터')).trim() || i18n.t('app.챕터');
    episodes.push({
      id,
      title,
      chapterTitle: heading,
      label: `${heading} · ${title}`,
    });
  };

  if (typeof shouldUseFoldersOutline === "function" && shouldUseFoldersOutline()) {
    const roots = (state.folders || []).map((f) => normalizeApiFolderNode(f));
    const walk = (nodes) => {
      for (const node of nodes || []) {
        if (!node) continue;
        const heading = String(node.title || i18n.t('app.챕터')).trim() || i18n.t('app.챕터');
        for (const scene of flattenChapterScenes(node)) {
          pushScene(scene, heading);
        }
        walk(typeof getBinderChildFolders === "function" ? getBinderChildFolders(node) : (node.children || []));
      }
    };
    walk(roots);
  }
  if (!episodes.length) {
    const chapters = typeof getBinderChaptersInOrder === "function"
      ? getBinderChaptersInOrder()
      : (state.outline || []);
    if (typeof walkBinderChapters === "function") {
      walkBinderChapters(chapters, (chapter) => {
        const heading = String(chapter.title || i18n.t('app.챕터')).trim() || i18n.t('app.챕터');
        for (const scene of flattenChapterScenes(chapter)) {
          pushScene(scene, heading);
        }
      });
    } else {
      for (const chapter of chapters) {
        const heading = String(chapter.title || i18n.t('app.챕터')).trim() || i18n.t('app.챕터');
        const scenes = Array.isArray(chapter.scenes) ? chapter.scenes : [];
        for (const scene of scenes) pushScene(scene, heading);
      }
    }
  }
  if (!episodes.length && typeof allScenes === "function") {
    for (const scene of allScenes()) {
      const id = Number(scene.id);
      if (!id) continue;
      episodes.push({
        id,
        title: String(scene.title || `${i18n.t('app.회차_id', {id: id})}`).trim(),
        chapterTitle: String(scene.chapterTitle || "").trim(),
        label: scene.chapterTitle
          ? `${scene.chapterTitle} · ${scene.title || id}`
          : (scene.title || `${i18n.t('app.회차_id', {id: id})}`),
      });
    }
  }
  return episodes;
}

function getExportScope() {
  if (exportModalState.lockScope && exportModalState.scope === "scenes") return "scenes";
  const full = $("exportScopeFull");
  if (full?.checked) return "full";
  return "scenes";
}

function getSelectedExportSceneIds() {
  const list = $("exportSceneList");
  if (!list) return [...exportModalState.sceneIds];
  return [...list.querySelectorAll('input[type="checkbox"][data-export-scene]:checked')]
    .map((el) => Number(el.dataset.exportScene))
    .filter((id) => Number.isFinite(id) && id > 0);
}

function syncExportScopeUi() {
  const scope = getExportScope();
  exportModalState.scope = scope;
  const picker = $("exportScenePicker");
  picker?.classList.toggle("hidden", scope !== "scenes");
  // stg only for full project
  $("exportFormatGrid")?.querySelectorAll("[data-export-format]").forEach((btn) => {
    const key = btn.dataset.exportFormat;
    const meta = EXPORT_FORMATS_UI.find((f) => f.key === key);
    const allow = scope === "full" || meta?.partialOk !== false;
    btn.disabled = !allow;
    btn.classList.toggle("is-disabled-scope", !allow);
    btn.title = allow
      ? ""
      : i18n.t('app.이_형식은_작품_전체_내보내기에서만_사용할');
  });
  const fullRadio = $("exportScopeFull");
  const scenesRadio = $("exportScopeScenes");
  if (exportModalState.lockScope) {
    if (fullRadio) fullRadio.disabled = exportModalState.scope !== "full";
    if (scenesRadio) scenesRadio.disabled = exportModalState.scope !== "scenes";
  } else {
    if (fullRadio) fullRadio.disabled = false;
    if (scenesRadio) scenesRadio.disabled = false;
  }
}

function renderExportScenePicker() {
  const list = $("exportSceneList");
  if (!list) return;
  const episodes = listExportEpisodes();
  const selected = new Set(
    (exportModalState.sceneIds || []).map((id) => Number(id)).filter(Boolean),
  );
  if (!episodes.length) {
    list.innerHTML = i18n.t('app.p_class_export_scene_em_2');
    return;
  }
  // If nothing preselected in scenes mode, default to current open scene or all
  if (!selected.size && exportModalState.scope === "scenes") {
    if (state.sceneId) selected.add(Number(state.sceneId));
  }
  list.innerHTML = episodes.map((ep) => {
    const checked = selected.has(ep.id) ? "checked" : "";
    return `
      <label class="export-scene-item">
        <input type="checkbox" data-export-scene="${ep.id}" ${checked}>
        <span>${escapeHtml(ep.label)}</span>
      </label>`;
  }).join("");
}

/**
 * @param {{ scope?: 'full'|'scenes', sceneIds?: number[], lockScope?: boolean, titleHint?: string }} [options]
 */
function openExportModal(options = {}) {
  if (!state.projectId) {
    toast(i18n.t('app.먼저_작품을_선택해_주세요'));
    return;
  }
  exportModalState = {
    scope: options.scope === "scenes" ? "scenes" : "full",
    sceneIds: Array.isArray(options.sceneIds)
      ? options.sceneIds.map((id) => Number(id)).filter((id) => id > 0)
      : [],
    lockScope: Boolean(options.lockScope),
    titleHint: String(options.titleHint || "").trim(),
  };

  const project = state.projects.find((p) => p.id === state.projectId);
  const label = $("exportProjectLabel");
  if (label) {
    if (exportModalState.scope === "scenes" && exportModalState.sceneIds.length === 1) {
      const hint = exportModalState.titleHint || i18n.t('app.선택_회차');
      label.textContent = `${i18n.t('app.내보낼_회차_hint_작품_project_t', {hint: hint, 'project?.title || "작품"': project?.title || "작품"})}`;
    } else if (exportModalState.scope === "scenes") {
      label.textContent = `${i18n.t('app.내보낼_작품_project_title_작품', {'project?.title || "작품"': project?.title || "작품"})}`;
    } else {
      label.textContent = `${i18n.t('app.내보낼_작품_project_title_작품_2', {'project?.title || "작품"': project?.title || "작품"})}`;
    }
  }
  const hint = $("exportModalHint");
  if (hint) {
    hint.textContent = exportModalState.scope === "scenes" && exportModalState.sceneIds.length === 1
      ? i18n.t('app.선택한_회차만_파일로_내려받습니다_형식을_고')
      : i18n.t('app.전체_원고_또는_선택한_회차만_파일로_내려받');
  }

  const fullRadio = $("exportScopeFull");
  const scenesRadio = $("exportScopeScenes");
  if (fullRadio) fullRadio.checked = exportModalState.scope === "full";
  if (scenesRadio) scenesRadio.checked = exportModalState.scope === "scenes";

  renderExportScenePicker();
  renderExportFormatGrid();
  syncExportScopeUi();
  loadExportPrefs().catch(() => { syncExportManageUi(); });

  const status = $("exportStatus");
  if (status) status.textContent = "";
  $("exportModal")?.classList.remove("hidden");
}

/** Open export modal for one or more 회차 (from binder / writing page). */
function openExportModalForScenes(sceneIds, titleHint = "") {
  const ids = (Array.isArray(sceneIds) ? sceneIds : [sceneIds])
    .map((id) => Number(id))
    .filter((id) => id > 0);
  if (!ids.length) {
    toast(i18n.t('app.내보낼_회차를_찾지_못했어요'));
    return;
  }
  openExportModal({
    scope: "scenes",
    sceneIds: ids,
    lockScope: true,
    titleHint: titleHint || (ids.length === 1 ? i18n.t('app.이_회차') : `${i18n.t('app.ids_length_개_회차', {'ids.length': ids.length})}`),
  });
}

function openExportModalForCurrentScene() {
  if (!state.sceneId) {
    toast(i18n.t('app.먼저_회차를_열어_주세요'));
    return;
  }
  const title = state.scene?.title || $("sceneTitle")?.value || i18n.t('app.현재_회차');
  openExportModalForScenes([state.sceneId], title);
}

function closeExportModal() {
  $("exportModal")?.classList.add("hidden");
  const status = $("exportStatus");
  if (status) status.textContent = "";
  $("exportFormatGrid")?.querySelectorAll("button").forEach((btn) => {
    btn.disabled = false;
  });
  exportModalState = { scope: "full", sceneIds: [], lockScope: false, titleHint: "" };
}

function renderExportFormatGrid() {
  const grid = $("exportFormatGrid");
  if (!grid) return;
  grid.innerHTML = EXPORT_FORMATS_UI.map((fmt) => `
    <button type="button" class="export-format-btn" role="listitem" data-export-format="${escapeHtml(fmt.key)}" data-partial-ok="${fmt.partialOk === false ? "0" : "1"}">
      <strong>${escapeHtml(fmt.label)}</strong>
      <span class="export-ext">${escapeHtml(fmt.ext)}</span>
      <span>${escapeHtml(fmt.hint)}</span>
    </button>
  `).join("");
  grid.querySelectorAll("[data-export-format]").forEach((button) => {
    button.addEventListener("click", () => {
      exportProjectAs(button.dataset.exportFormat).catch(handleError);
    });
  });
}

function setupExportModalUi() {
  if (setupExportModalUi._bound) return;
  setupExportModalUi._bound = true;
  document.querySelectorAll('input[name="exportScope"]').forEach((radio) => {
    radio.addEventListener("change", () => {
      if (exportModalState.lockScope) {
        // restore radios
        if ($("exportScopeFull")) $("exportScopeFull").checked = exportModalState.scope === "full";
        if ($("exportScopeScenes")) $("exportScopeScenes").checked = exportModalState.scope === "scenes";
        return;
      }
      exportModalState.scope = getExportScope();
      if (exportModalState.scope === "scenes" && !getSelectedExportSceneIds().length) {
        renderExportScenePicker();
      }
      syncExportScopeUi();
    });
  });
  $("exportSceneSelectAll")?.addEventListener("click", () => {
    $("exportSceneList")?.querySelectorAll('input[type="checkbox"][data-export-scene]').forEach((el) => {
      el.checked = true;
    });
  });
  $("exportSceneSelectNone")?.addEventListener("click", () => {
    $("exportSceneList")?.querySelectorAll('input[type="checkbox"][data-export-scene]').forEach((el) => {
      el.checked = false;
    });
  });

  $("exportDirSave")?.addEventListener("click", () => {
    saveExportPrefsFromUi().catch(handleError);
  });
  $("exportDirBrowse")?.addEventListener("click", async () => {
    try {
      const pick = window.electronAPI?.pickExportDirectory;
      if (typeof pick !== "function") {
        toast(i18n.t('app.폴더_찾아보기는_설치형_SuperTORY에서'));
        $("exportDirInput")?.focus();
        return;
      }
      const chosen = await pick();
      if (!chosen) return;
      if ($("exportDirInput")) $("exportDirInput").value = String(chosen);
      await saveExportPrefsFromUi();
    } catch (error) {
      handleError(error);
    }
  });
  $("exportDirDefault")?.addEventListener("click", () => {
    // Reset to Downloads (server default_export_dir)
    if ($("exportDirInput")) {
      $("exportDirInput").value = exportPrefs.default_export_dir || "";
    }
    saveExportPrefsFromUi().catch(handleError);
  });
  $("exportDirOpen")?.addEventListener("click", () => {
    const dir = ($("exportDirInput")?.value || exportPrefs.export_dir || "").trim();
    api("/api/export/open-folder", {
      method: "POST",
      body: JSON.stringify({ export_dir: dir }),
    })
      .then(() => toast(i18n.t('app.저장_폴더를_열었어요')))
      .catch(handleError);
  });
  $("exportSaveToFolder")?.addEventListener("change", () => {
    exportPrefs.save_to_folder = Boolean($("exportSaveToFolder")?.checked);
    syncExportManageUi();
    // Persist quietly
    api("/api/export/prefs", {
      method: "POST",
      body: JSON.stringify({
        export_dir: ($("exportDirInput")?.value || exportPrefs.export_dir || "").trim(),
        save_to_folder: exportPrefs.save_to_folder,
        reveal_after_save: Boolean($("exportRevealAfter")?.checked),
      }),
    }).then((data) => {
      exportPrefs.export_dir = String(data.export_dir || exportPrefs.export_dir);
      exportPrefs.folder_ok = Boolean(data.folder_ok);
    }).catch(() => {});
  });
  $("exportRevealAfter")?.addEventListener("change", () => {
    exportPrefs.reveal_after_save = Boolean($("exportRevealAfter")?.checked);
    api("/api/export/prefs", {
      method: "POST",
      body: JSON.stringify({
        export_dir: ($("exportDirInput")?.value || exportPrefs.export_dir || "").trim(),
        save_to_folder: Boolean($("exportSaveToFolder")?.checked),
        reveal_after_save: exportPrefs.reveal_after_save,
      }),
    }).catch(() => {});
  });
  $("exportDirInput")?.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      saveExportPrefsFromUi().catch(handleError);
    }
  });
}

async function exportProjectAs(formatKey) {
  if (!state.projectId) {
    toast(i18n.t('app.먼저_작품을_선택해_주세요'));
    return;
  }
  const key = String(formatKey || "").trim().toLowerCase();
  if (!key) return;
  const scope = getExportScope();
  let sceneIds = null;
  if (scope === "scenes") {
    sceneIds = getSelectedExportSceneIds();
    if (!sceneIds.length) {
      toast(i18n.t('app.내보낼_회차를_하나_이상_선택해_주세요'));
      return;
    }
  }
  if (key === "stg" && sceneIds) {
    toast(i18n.t('app.SuperTORY_연결_파일_stg_은_작품'));
    return;
  }

  const status = $("exportStatus");
  const grid = $("exportFormatGrid");
  const buttons = grid ? [...grid.querySelectorAll("button")] : [];
  buttons.forEach((btn) => { btn.disabled = true; });
  if (status) {
    status.textContent = sceneIds
      ? `${i18n.t('app.선택한_회차_sceneIds_length_개', {'sceneIds.length': sceneIds.length})}`
      : i18n.t('app.전체_원고_파일을_만드는_중');
  }
  try {
    // Flush open scene so latest text is included when exporting current episode
    if (sceneDirty && state.sceneId && (!sceneIds || sceneIds.includes(Number(state.sceneId)))) {
      try {
        await persistScene({ quiet: true, saveNote: i18n.t('app.내보내기_전_저장') });
      } catch (_) { /* still try export */ }
    }

    const saveToFolder = Boolean($("exportSaveToFolder")?.checked);
    const exportDir = ($("exportDirInput")?.value || exportPrefs.export_dir || "").trim();
    const body = {
      format: key,
      // Do not send UI labels (「2개 회차」 등) as manuscript/file titles.
      title: "",
      save_to_folder: saveToFolder,
      export_dir: exportDir,
      reveal_after_save: Boolean($("exportRevealAfter")?.checked),
    };
    if (sceneIds) {
      body.scene_ids = sceneIds;
      // Single-episode: use the real scene title for the download filename only.
      const hint = String(exportModalState.titleHint || "").trim();
      if (
        sceneIds.length === 1
        && hint
        && hint !== i18n.t('app.이_회차')
        && hint !== i18n.t('app.선택_회차')
        && hint !== i18n.t('app.현재_회차')
        && !/^\d+개 회차$/.test(hint)
        && !/^선택회차\d*$/.test(hint)
      ) {
        body.title = hint;
      }
    }

    const response = await fetch(`/api/projects/${state.projectId}/export`, {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    if (!response.ok) {
      let message = i18n.t('app.내보내기에_실패했습니다');
      try {
        const err = await response.json();
        if (err?.error) message = err.error;
      } catch (_) {
        /* ignore */
      }
      throw new Error(message);
    }

    const contentType = (response.headers.get("Content-Type") || "").toLowerCase();
    // Folder save: server writes file and returns JSON { path, filename, ... }
    if (saveToFolder || contentType.includes("application/json")) {
      const result = await response.json();
      if (!result?.ok && !result?.path) {
        throw new Error(result?.error || i18n.t('app.폴더에_저장하지_못했어요'));
      }
      const savedPath = result.path || result.filename || "";
      if (status) {
        status.textContent = sceneIds
          ? `${i18n.t('app.저장됨_savedPath_선택_회차_scen', {savedPath: savedPath, 'sceneIds.length': sceneIds.length})}`
          : `${i18n.t('app.저장됨_savedPath_전체_원고', {savedPath: savedPath})}`;
      }
      toast(sceneIds
        ? i18n.t('app.선택한_회차를_저장했어요_savedPath', { savedPath })
        : i18n.t('app.작품_전체를_저장했어요_savedPath', { savedPath }));
      // refresh prefs display if folder was created/normalized
      if (result.folder) {
        exportPrefs.export_dir = result.folder;
        if ($("exportDirInput")) $("exportDirInput").value = result.folder;
        syncExportManageUi();
      }
      return;
    }

    // Browser download path
    const buffer = await response.arrayBuffer();
    if (!buffer || buffer.byteLength < 4) {
      throw new Error(i18n.t('app.내보낸_파일이_비어_있어요_서버를_다시_실행'));
    }
    const head = new Uint8Array(buffer.slice(0, 4));
    const isZip = head[0] === 0x50 && head[1] === 0x4b; // PK
    const isTextish = key === "txt" || key === "md" || key === "html" || key === "rtf";
    if ((key === "docx" || key === "hwpx" || key === "stg") && !isZip) {
      const preview = new TextDecoder("utf-8").decode(buffer.slice(0, 80));
      throw new Error(
        preview.trim().startsWith("{") || preview.includes("<!DOCTYPE") || preview.includes("<html")
          ? i18n.t('app.내보내기_응답이_파일이_아니라_오류_페이지예')
          : i18n.t('app.내보낸_파일이_손상된_형식으로_내려왔어요_서'),
      );
    }
    const mime =
      response.headers.get("Content-Type")
      || (key === "docx"
        ? "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
        : key === "hwpx"
          ? "application/hwp+zip"
          : isTextish
            ? "text/plain;charset=utf-8"
            : "application/octet-stream");
    const blob = new Blob([buffer], { type: mime });
    const title = state.projects.find((p) => p.id === state.projectId)?.title || i18n.t('app.작품');
    const ext = key === "md" ? "md" : key;
    let filename = i18n.t('app.state_projects_find_p_p', { title: title, ext: ext });
    const disposition = response.headers.get("Content-Disposition") || "";
    const utfMatch = disposition.match(/filename\*=UTF-8''([^;]+)/i);
    const plainMatch = disposition.match(/filename="?([^";]+)"?/i);
    if (utfMatch?.[1]) {
      try { filename = decodeURIComponent(utfMatch[1]); } catch (_) { /* keep */ }
    } else if (plainMatch?.[1]) {
      filename = plainMatch[1];
    }
    const wantExt = key === "md" ? ".md" : `.${key}`;
    if (!filename.toLowerCase().endsWith(wantExt)) {
      filename = `${filename.replace(/\.[^.]+$/, "")}${wantExt}`;
    }
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = filename;
    anchor.rel = "noopener";
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1500);
    if (status) {
      status.textContent = sceneIds
        ? `${i18n.t('app.다운로드_filename_선택_회차_scen', {filename: filename, 'sceneIds.length': sceneIds.length})}`
        : `${i18n.t('app.다운로드_filename_전체_원고', {filename: filename})}`;
    }
    toast(sceneIds ? i18n.t('app.선택한_회차를_내보냈어요') : i18n.t('app.작품_전체를_내보냈어요'));
  } finally {
    buttons.forEach((btn) => { btn.disabled = false; });
    syncExportScopeUi();
  }
}

/** @type {"document"|"proof"} */
let importModalMode = "document";
let importPreviewTimer = 0;
let importPreviewToken = 0;

const DEFAULT_IMPORT_DELIMITER = {
  presets: ["blank"],
  blank_line_threshold: 2,
  custom: "",
};

function getImportDelimiterConfig() {
  const presets = [];
  if ($("importDelimHash")?.checked) presets.push("hash");
  if ($("importDelimStars")?.checked) presets.push("asterisk");
  if ($("importDelimDash")?.checked) presets.push("dash");
  if ($("importDelimNumbered")?.checked) presets.push("numbered");
  if ($("importDelimBlank")?.checked) presets.push("blank");
  const customOn = Boolean($("importDelimCustom")?.checked);
  const custom = customOn ? String($("importDelimCustomText")?.value || "").trim() : "";
  let threshold = Number($("importBlankThreshold")?.value || 2);
  if (!Number.isFinite(threshold)) threshold = 2;
  threshold = Math.max(1, Math.min(20, Math.round(threshold)));
  return {
    presets,
    blank_line_threshold: $("importDelimBlank")?.checked ? threshold : 0,
    custom,
  };
}

function applyImportDelimiterConfig(config) {
  const data = config && typeof config === "object" ? config : DEFAULT_IMPORT_DELIMITER;
  const presets = Array.isArray(data.presets) ? data.presets.map((item) => String(item || "").toLowerCase()) : [];
  const custom = String(data.custom || "").trim();
  const useBlank = presets.includes("blank") || Number(data.blank_line_threshold || 0) > 0;
  if ($("importDelimHash")) $("importDelimHash").checked = presets.includes("hash") || presets.includes("#");
  if ($("importDelimStars")) $("importDelimStars").checked = presets.includes("asterisk") || presets.includes("***");
  if ($("importDelimDash")) $("importDelimDash").checked = presets.includes("dash") || presets.includes("---");
  if ($("importDelimNumbered")) $("importDelimNumbered").checked = presets.includes("numbered") || presets.includes("numeric");
  if ($("importDelimBlank")) $("importDelimBlank").checked = useBlank;
  if ($("importDelimCustom")) $("importDelimCustom").checked = Boolean(custom);
  if ($("importDelimCustomText")) $("importDelimCustomText").value = custom;
  let threshold = Number(data.blank_line_threshold || 2);
  if (!Number.isFinite(threshold) || threshold < 1) threshold = 2;
  if ($("importBlankThreshold")) $("importBlankThreshold").value = String(Math.max(1, Math.min(20, Math.round(threshold))));
  syncImportDelimiterUi();
}

function resetImportDelimiterUi() {
  const current = state.projects.find((project) => project.id === state.projectId);
  const saved = current?.import_delimiter_config;
  applyImportDelimiterConfig(saved && typeof saved === "object" ? saved : DEFAULT_IMPORT_DELIMITER);
  const savedSplit = String(saved?.split || "");
  if (savedSplit && $("importSplit")?.querySelector(`option[value="${CSS.escape(savedSplit)}"]`)) {
    $("importSplit").value = savedSplit;
  }
}

function syncImportDelimiterUi() {
  const blankOn = Boolean($("importDelimBlank")?.checked);
  const customOn = Boolean($("importDelimCustom")?.checked);
  $("importBlankThresholdWrap")?.classList.toggle("hidden", !blankOn);
  $("importDelimCustomWrap")?.classList.toggle("hidden", !customOn);
}

function clearImportSplitPreview() {
  const summary = $("importSplitPreviewSummary");
  const list = $("importSplitPreviewList");
  if (summary) summary.textContent = i18n.t('app.파일을_고르면_몇_개_씬으로_나뉘는지_보여');
  if (list) list.innerHTML = "";
}

function scheduleImportSplitPreview() {
  window.clearTimeout(importPreviewTimer);
  const wrap = $("importDelimiterWrap");
  if (!wrap || wrap.classList.contains("hidden")) {
    clearImportSplitPreview();
    return;
  }
  const file = $("importFile")?.files?.[0];
  if (!file) {
    clearImportSplitPreview();
    return;
  }
  const summary = $("importSplitPreviewSummary");
  if (summary) summary.textContent = i18n.t('app.나누는_중');
  importPreviewTimer = window.setTimeout(() => {
    runImportSplitPreview().catch(handleError);
  }, 350);
}

async function runImportSplitPreview() {
  const wrap = $("importDelimiterWrap");
  const summary = $("importSplitPreviewSummary");
  const list = $("importSplitPreviewList");
  const file = $("importFile")?.files?.[0];
  if (!wrap || wrap.classList.contains("hidden") || !file) {
    clearImportSplitPreview();
    return;
  }
  const token = ++importPreviewToken;
  const contentBase64 = await fileToBase64(file);
  if (token !== importPreviewToken) return;
  const result = await api("/api/import/preview", {
    method: "POST",
    body: JSON.stringify({
      filename: file.name,
      content_base64: contentBase64,
      split: $("importSplit")?.value || "blank_lines",
      delimiter_config: getImportDelimiterConfig(),
      project_title: String($("importProjectTitle")?.value || "").trim(),
    }),
  });
  if (token !== importPreviewToken) return;
  const count = Number(result?.section_count || 0);
  if (summary) {
    summary.textContent = count > 0
      ? `${i18n.t('app.총_count_개_씬으로_분리됩니다', {count: count})}`
      : i18n.t('app.나눌_씬을_찾지_못했어요');
  }
  if (!list) return;
  const scenes = Array.isArray(result?.scenes) ? result.scenes : [];
  const extra = result?.truncated ? `${i18n.t('app.li_span_외_Math_max_0_co', {'Math.max(0, count - scenes.length)': Math.max(0, count - scenes.length)})}` : "";
  list.innerHTML = scenes.map((scene, index) => {
    const title = String(scene?.title || `${i18n.t('app.장면_index_1', {'index + 1': index + 1})}`);
    const preview = String(scene?.preview || "").trim();
    return `<li><strong>${index + 1}. ${escapeHtml(title)}</strong>${preview ? `<span>${escapeHtml(preview)}</span>` : ""}</li>`;
  }).join("") + extra;
}

function openImportModal(options = {}) {
  const mode = options.mode === "proof" ? "proof" : "document";
  importModalMode = mode;

  if (mode === "proof" && !state.projectId) {
    toast(i18n.t('app.교정본_가져오기는_작품을_먼저_연_뒤_사용할'));
    return;
  }

  const modal = $("importModal");
  $("importFile").value = "";
  $("importFileName").textContent = i18n.t('app.아직_고른_파일이_없어요');
  $("importProjectTitle").value = "";
  $("importChapterTitle").value = "";
  $("importSplit").value = "auto";
  resetImportDelimiterUi();
  clearImportSplitPreview();
  if ($("importTitleModeFromFile")) $("importTitleModeFromFile").checked = true;
  if ($("importTitleModeCustom")) $("importTitleModeCustom").checked = false;
  if ($("importApplyClean")) $("importApplyClean").checked = false;
  if ($("importDocumentKind")) {
    $("importDocumentKind").value = mode === "proof" ? "proof" : "manuscript";
  }
  modal?.setAttribute("data-import-mode", mode);
  if ($("importProofMethodPipeline")) $("importProofMethodPipeline").checked = true;

  const current = state.projects.find((project) => project.id === state.projectId);
  $("importPurpose").value = current?.purpose && purposeLabel[normalizePurposeKey(current.purpose)]
    ? normalizePurposeKey(current.purpose)
    : "general_novel";
  const importCluster = current
    ? inferClusterId(
      current.purpose,
      current.main_genre,
      current.sub_genre,
      current.cluster_id,
    )
    : "";
  setModalClusterId("import", importCluster === "locked" ? "" : importCluster);
  renderGenreClusterGrid("import", importCluster === "locked" ? "" : importCluster);
  syncModalGenreFields("import", $("importPurpose").value, {
    main: inferClusterSubKey(importCluster, current?.main_genre, current?.sub_genre)
      || current?.main_genre
      || "",
    sub: current?.sub_genre || "",
  });
  const seedKeywords = mode === "proof"
    ? []
    : normalizeKeywordList(current?.keywords ?? state.keywords ?? []);
  resetModalDraftKeywords("import", seedKeywords);

  // Title / hints for document vs proof
  if ($("importModalTitle")) {
    $("importModalTitle").textContent = mode === "proof" ? i18n.t('app.교정본_가져오기') : i18n.t('app.문서_가져오기');
  }
  $("importModalHint")?.classList.toggle("hidden", mode === "proof");
  $("importProofBanner")?.classList.toggle("hidden", mode !== "proof");
  if ($("importFileLabelText")) {
    $("importFileLabelText").textContent = mode === "proof" ? i18n.t('app.파일_선택하기') : i18n.t('app.파일_선택');
  }
  if ($("importSubmitButton")) {
    $("importSubmitButton").textContent = mode === "proof" ? i18n.t('app.적용하기') : i18n.t('app.가져오기');
  }

  const destination = $("importDestination");
  if (mode === "proof") {
    destination.value = "proof_pipeline";
  } else {
    destination.value = "new_project";
  }
  refreshImportDestinationOptions();
  syncImportProofMethodUi();
  updateImportFormVisibility();
  modal.classList.remove("hidden");
}

function closeImportModal() {
  window.clearTimeout(importPreviewTimer);
  importPreviewToken += 1;
  $("importModal").classList.add("hidden");
  $("importSubmitButton").disabled = false;
  $("importSubmitButton").textContent = i18n.t('app.가져오기');
  importModalMode = "document";
  $("importModal")?.setAttribute("data-import-mode", "document");
  if ($("importDocumentKind")) $("importDocumentKind").value = "manuscript";
  if ($("importFileLabelText")) $("importFileLabelText").textContent = i18n.t('app.파일_선택');
  resetModalDraftKeywords("import");
}

function getImportProofMethod() {
  const checked = document.querySelector('input[name="importProofMethod"]:checked');
  const value = checked?.value;
  if (value === "proof_compare" || value === "match_replace_scene" || value === "proof_pipeline") {
    return value;
  }
  return "proof_pipeline";
}

function syncImportProofMethodUi() {
  if (importModalMode !== "proof") return;
  const method = getImportProofMethod();
  const select = $("importDestination");
  if (select) select.value = method;
  document.querySelectorAll('input[name="importProofMethod"]').forEach((input) => {
    input.checked = input.value === method;
  });
}

function refreshImportDestinationOptions() {
  const select = $("importDestination");
  const current = importModalMode === "proof" ? getImportProofMethod() : select.value;
  const proofMode = importModalMode === "proof";
  const binderChapters = proofMode
    ? []
    : (typeof chaptersInBinderDisplayOrder === "function"
      ? chaptersInBinderDisplayOrder()
      : (state.outline || []));
  const options = proofMode
    ? [
      {
        value: "proof_pipeline",
        label: i18n.t('app.토리_교정_파이프라인_본문_메모_정밀_분석'),
        enabled: Boolean(state.projectId),
      },
      {
        value: "proof_compare",
        label: i18n.t('app.교정_비교_보고서_단순_텍스트_대조'),
        enabled: Boolean(state.projectId),
      },
      {
        value: "match_replace_scene",
        label: i18n.t('app.교정본으로_덮어쓰기'),
        enabled: Boolean(state.projectId),
      },
    ]
    : [
      { value: "new_project", label: i18n.t('app.새_작품으로_만들기'), enabled: true },
      { value: "new_chapter", label: i18n.t('app.현재_작품에_새_챕터로_넣기'), enabled: Boolean(state.projectId) },
      { value: "existing_chapter", label: i18n.t('app.현재_작품의_챕터에_새_씬으로_넣기'), enabled: Boolean(state.projectId && binderChapters.length) },
      { value: "replace_scene", label: i18n.t('app.지금_열린_씬에_덮어쓰기'), enabled: Boolean(state.sceneId) },
    ];
  select.innerHTML = options
    .filter((option) => option.enabled)
    .map((option) => `<option value="${option.value}">${option.label}</option>`)
    .join("");
  if (options.some((option) => option.enabled && option.value === current)) {
    select.value = current;
  } else if (options.find((o) => o.enabled)) {
    select.value = options.find((o) => o.enabled).value;
  }
  if (proofMode) {
    const selected = select.value || "proof_pipeline";
    document.querySelectorAll('input[name="importProofMethod"]').forEach((input) => {
      input.checked = input.value === selected;
    });
  }
  const chapterSelect = $("importChapterSelect");
  const currentChapter = chapterSelect.value;
  chapterSelect.innerHTML = binderChapters.map((chapter) =>
    `<option value="${chapter.id}">${escapeHtml(chapter.title)}</option>`
  ).join("") || i18n.t('app.option_value_챕터가_없어요_op');
  if (binderChapters.some((chapter) => String(chapter.id) === String(currentChapter))) {
    chapterSelect.value = currentChapter;
  }
}

function getImportTitleMode() {
  const checked = document.querySelector('input[name="importTitleMode"]:checked');
  return checked?.value === "custom" ? "custom" : "from_file";
}

function syncImportTitleModeUi() {
  const custom = getImportTitleMode() === "custom";
  $("importProjectTitleInputWrap")?.classList.toggle("hidden", !custom);
  $("importTitleFromFileHint")?.classList.toggle("hidden", custom);
  if (custom) {
    const file = $("importFile")?.files?.[0];
    const input = $("importProjectTitle");
    if (input && !String(input.value || "").trim() && file) {
      input.placeholder = file.name.replace(/\.[^.]+$/, "") || i18n.t('app.새_소설');
    }
  } else {
    refreshImportTitleFromFileHint();
  }
}

function refreshImportTitleFromFileHint() {
  const hint = $("importTitleFromFileHint");
  if (!hint) return;
  const file = $("importFile")?.files?.[0];
  const stem = file ? (file.name.replace(/\.[^.]+$/, "") || file.name) : "";
  hint.textContent = stem
    ? `${i18n.t('app.stem_을_를_제목으로_씁니다', {stem: stem})}`
    : i18n.t('app.가져온_문서_제목_또는_파일_이름_을_그대로');
}

function updateImportFormVisibility() {
  const destination = $("importDestination").value;
  const splitMode = $("importSplit").value;
  const proofMode = importModalMode === "proof"
    || destination === "proof_pipeline"
    || destination === "proof_compare"
    || destination === "match_replace_scene";
  const showWorkMeta = importModalMode !== "proof";

  $("importProofMethodWrap")?.classList.toggle("hidden", importModalMode !== "proof");
  $("importDestinationWrap")?.classList.toggle("hidden", importModalMode === "proof");
  $("importChapterWrap").classList.toggle("hidden", destination !== "existing_chapter" || importModalMode === "proof");
  // Title + genre/keyword box: common for all document imports (hidden only in proof mode).
  $("importProjectTitleWrap")?.classList.toggle("hidden", !showWorkMeta);
  $("importGenreBlock")?.classList.toggle("hidden", !showWorkMeta);
  // Hidden required controls block form submit ("not focusable") — clear when proof hides meta.
  ["importMainGenre", "importSubGenre"].forEach((id) => {
    const el = $(id);
    if (!el) return;
    if (showWorkMeta) {
      el.disabled = false;
    } else {
      el.required = false;
      el.disabled = true;
    }
  });
  if (showWorkMeta) {
    syncImportTitleModeUi();
    syncModalGenreFields("import", $("importPurpose")?.value || "general_novel", {
      keepMain: true,
      keepSub: true,
    });
  } else {
    $("importSubGenreWrap")?.classList.add("hidden");
  }
  // Proof cards already explain each method — hide legacy hint/checkbox rows in proof modal.
  const hideLegacyProofHints = importModalMode === "proof";
  $("importMatchHint")?.classList.toggle("hidden", hideLegacyProofHints || destination !== "match_replace_scene");
  $("importProofHint")?.classList.toggle("hidden", hideLegacyProofHints || destination !== "proof_compare");
  $("importPipelineHint")?.classList.toggle("hidden", hideLegacyProofHints || destination !== "proof_pipeline");
  $("importApplyCleanWrap")?.classList.toggle("hidden", hideLegacyProofHints || destination !== "proof_pipeline");

  const splitLabel = $("importSplit")?.closest("label");
  const splitHint = $("importSplitHint") || (splitLabel?.nextElementSibling);
  if (splitLabel) splitLabel.classList.toggle("hidden", proofMode);
  if (splitHint?.classList?.contains("purpose-hint")) {
    splitHint.classList.toggle("hidden", proofMode || splitMode === "blank_lines");
  }
  const showDelimiter = importModalMode !== "proof" && !proofMode && splitMode === "blank_lines";
  $("importDelimiterWrap")?.classList.toggle("hidden", !showDelimiter);
  if (showDelimiter) {
    syncImportDelimiterUi();
    scheduleImportSplitPreview();
  } else {
    window.clearTimeout(importPreviewTimer);
    clearImportSplitPreview();
  }

  const showChapterTitle = importModalMode !== "proof"
    && (destination === "new_chapter" || destination === "new_project")
    && (splitMode === "none" || splitMode === "blank_lines");
  $("importChapterTitleWrap").classList.toggle("hidden", !showChapterTitle);
  const split = $("importSplit");
  if (
    destination === "replace_scene"
    || destination === "match_replace_scene"
    || destination === "proof_compare"
    || destination === "proof_pipeline"
  ) {
    split.value = "none";
    split.disabled = true;
  } else {
    split.disabled = false;
  }
}

function proofDiffTypeLabel(type) {
  const map = {
    typo: i18n.t('app.오탈자'),
    modified: i18n.t('app.문장_수정'),
    stylistic: i18n.t('app.표현_교정'),
    added: i18n.t('app.추가_2'),
    deleted: i18n.t('app.삭제'),
  };
  return map[type] || type || i18n.t('app.수정');
}

let proofReportSceneId = null;

function closeProofReportModal() {
  $("proofReportModal")?.classList.add("hidden");
  proofReportSceneId = null;
}

function openProofReportModal(report, { match = null } = {}) {
  const modal = $("proofReportModal");
  if (!modal || !report) return;
  const summary = report.summary || {};
  const overall = summary.overall_comment || i18n.t('app.교정_비교_결과입니다');
  if ($("proofReportOverall")) $("proofReportOverall").textContent = overall;

  const sumEl = $("proofReportSummary");
  if (sumEl) {
    const chips = [
      [i18n.t('app.오탈자'), summary.typo_corrections_count],
      [i18n.t('app.문장_표현'), summary.stylistic_edits_count],
      [i18n.t('app.추가_삭제'), summary.structural_edits_count],
      [i18n.t('app.편집_메모'), summary.editor_memos_count],
    ];
    sumEl.innerHTML = chips.map(([label, n]) => `
      <span class="proof-stat-chip">
        <strong>${escapeHtml(String(n ?? 0))}</strong>
        <span>${escapeHtml(label)}</span>
      </span>
    `).join("");
  }

  const matchEl = $("proofReportMatch");
  const m = match || report.match;
  if (matchEl) {
    if (m && (m.matched_episode_number != null || m.matched_title)) {
      const conf = typeof m.confidence_score === "number"
        ? ` · 신뢰도 ${Math.round(m.confidence_score * 100)}%`
        : "";
      matchEl.classList.remove("hidden");
      matchEl.innerHTML = `${i18n.t('app.비교_대상_strong_escapeHtml', {'escapeHtml(String(m.matched_episode_number ?? "?"))': escapeHtml(String(m.matched_episode_number ?? "?"))})}`
        + ` 「${escapeHtml(m.matched_title || "회차")}」${escapeHtml(conf)}`;
    } else {
      matchEl.classList.add("hidden");
      matchEl.innerHTML = "";
    }
  }

  const memos = Array.isArray(report.editor_memos) ? report.editor_memos : [];
  const memosEl = $("proofReportMemos");
  if (memosEl) {
    if (!memos.length) {
      memosEl.innerHTML = i18n.t('app.p_class_hint_추출된_편집자_메모');
    } else {
      memosEl.innerHTML = memos.map((memo) => `
        <article class="proof-memo-card">
          <div class="proof-memo-ctx">${escapeHtml(memo.location_context || i18n.t('app.위치_미상'))}</div>
          <div class="proof-memo-body">${escapeHtml(memo.memo_content || "")}</div>
        </article>
      `).join("");
    }
  }

  const diffs = Array.isArray(report.diff_chunks) ? report.diff_chunks : [];
  const diffsEl = $("proofReportDiffs");
  if (diffsEl) {
    if (!diffs.length) {
      diffsEl.innerHTML = i18n.t('app.p_class_hint_눈에_띄는_수정_구');
    } else {
      diffsEl.innerHTML = diffs.map((chunk) => {
        const type = escapeHtml(proofDiffTypeLabel(chunk.type));
        const typeKey = escapeHtml(chunk.type || "modified");
        const orig = escapeHtml(chunk.original || "—");
        const rev = escapeHtml(chunk.revised || "—");
        const reason = escapeHtml(chunk.reason || "");
        return `
          <article class="proof-diff-card type-${typeKey}">
            <header>
              <span class="proof-diff-type">${type}</span>
              ${reason ? `<span class="proof-diff-reason">${reason}</span>` : ""}
            </header>
            <div class="proof-diff-cols">
              <div class="proof-diff-orig"><span class="proof-diff-label">원본</span><p>${orig}</p></div>
              <div class="proof-diff-rev"><span class="proof-diff-label">교정</span><p>${rev}</p></div>
            </div>
          </article>
        `;
      }).join("");
    }
  }

  proofReportSceneId = report.scene_id || m?.matched_scene_id || null;
  const openBtn = $("proofReportOpenScene");
  if (openBtn) {
    openBtn.hidden = !proofReportSceneId;
  }
  modal.classList.remove("hidden");
}

function setupProofReportModal() {
  document.querySelectorAll("[data-close-proof-report]").forEach((el) => {
    el.addEventListener("click", () => closeProofReportModal());
  });
  $("proofReportOpenScene")?.addEventListener("click", () => {
    const id = proofReportSceneId;
    closeProofReportModal();
    if (id) openScene(id).catch(handleError);
  });
}

async function submitImport(event) {
  event.preventDefault();
  const file = $("importFile").files?.[0];
  if (!file) {
    toast(i18n.t('app.가져올_파일을_먼저_골라_주세요'));
    return;
  }
  if (importModalMode === "proof") {
    syncImportProofMethodUi();
  }
  const destination = $("importDestination").value;
  if (destination !== "new_project" && !state.projectId) {
    toast(i18n.t('app.먼저_작품을_만들거나_새_작품으로_만들기를'));
    return;
  }
  if (destination === "replace_scene" && !state.sceneId) {
    toast(i18n.t('app.덮어쓸_씬을_먼저_열어_주세요'));
    return;
  }
  if ((destination === "match_replace_scene" || destination === "proof_compare" || destination === "proof_pipeline") && !state.projectId) {
    toast(i18n.t('app.회차_자동_매칭은_작품을_연_뒤_사용할_수'));
    return;
  }
  if (destination === "existing_chapter" && !$("importChapterSelect").value) {
    toast(i18n.t('app.글을_넣을_챕터를_골라_주세요'));
    return;
  }
  if (
    importModalMode === "proof"
    && destination === "match_replace_scene"
    && !window.confirm(i18n.t('app.기존_원고가_삭제되고_새_교정본으로_교체됩니'))
  ) {
    return;
  }
  const purpose = normalizePurposeKey($("importPurpose")?.value || "general_novel");
  let mainGenre = "";
  let subGenre = "";
  let genreDetail = "";
  let importClusterId = getModalClusterId("import");
  const isDocumentImport = importModalMode !== "proof"
    && destination !== "proof_pipeline"
    && destination !== "proof_compare"
    && destination !== "match_replace_scene";
  if (isDocumentImport) {
    const genres = readModalGenreValues("import", purpose);
    if (!genres.ok) {
      toast(genres.error || i18n.t('app.장르를_선택해_주세요_토리_학습에_필요해요'));
      $(genres.focusId)?.focus();
      return;
    }
    mainGenre = genres.main;
    subGenre = genres.sub;
    genreDetail = genres.genre_detail || "";
    if (genres.purpose) $("importPurpose").value = genres.purpose;
    importClusterId = genres.cluster_id || importClusterId;
  } else {
    const current = state.projects.find((project) => project.id === state.projectId);
    mainGenre = String(current?.main_genre || state.mainGenre || "").trim();
    subGenre = String(current?.sub_genre || state.subGenre || "").trim();
    genreDetail = String(current?.genre_detail || state.genreDetail || "").trim();
    importClusterId = inferClusterId(
      current?.purpose || purpose,
      mainGenre,
      subGenre,
      current?.cluster_id,
    );
  }

  const customTitle = getImportTitleMode() === "custom"
    ? String($("importProjectTitle")?.value || "").trim()
    : "";
  if (isDocumentImport && getImportTitleMode() === "custom" && !customTitle) {
    toast(i18n.t('app.제목을_입력해_주세요'));
    $("importProjectTitle")?.focus();
    return;
  }
  const projectTitle = customTitle;
  const chapterTitle = String($("importChapterTitle")?.value || "").trim() || customTitle;

  const submit = $("importSubmitButton");
  const isProofJob = importModalMode === "proof"
    || destination === "proof_pipeline"
    || destination === "proof_compare"
    || destination === "match_replace_scene";
  submit.disabled = true;
  const busyLabel = destination === "proof_pipeline"
    ? i18n.t('app.토리가_회차_식별_교정_비교_중')
    : destination === "proof_compare"
      ? i18n.t('app.토리가_교정_비교_중')
      : destination === "match_replace_scene"
        ? i18n.t('app.토리가_회차_찾는_중')
        : i18n.t('app.가져오는_중');
  submit.textContent = busyLabel;
  try {
    const contentBase64 = await fileToBase64(file);
    const documentKind = ($("importDocumentKind")?.value || (importModalMode === "proof" ? "proof" : "manuscript"));
    const body = {
      filename: file.name,
      content_base64: contentBase64,
      destination,
      split: $("importSplit").value,
      delimiter_config: $("importSplit").value === "blank_lines" ? getImportDelimiterConfig() : undefined,
      purpose: normalizePurposeKey($("importPurpose")?.value || purpose),
      cluster_id: importClusterId,
      main_genre: mainGenre,
      sub_genre: subGenre,
      genre_detail: genreDetail,
      keywords: isDocumentImport ? getModalDraftKeywords("import") : undefined,
      project_title: projectTitle,
      chapter_title: chapterTitle,
      chapter_id: $("importChapterSelect").value || null,
      scene_id: state.sceneId,
      keep_scene_title: destination === "match_replace_scene" ? true : undefined,
      apply_clean: destination === "proof_pipeline" ? Boolean($("importApplyClean")?.checked) : undefined,
      // Tory recognition: this file is editor proof / clean manuscript
      document_kind: documentKind,
      document_role: documentKind === "proof" ? "editor_proof" : "manuscript",
      is_proof: documentKind === "proof" || isProofJob,
      tory_task: documentKind === "proof" || isProofJob
        ? "proof_identify_and_compare"
        : "import_manuscript",
    };
    const path = destination === "new_project" || !state.projectId
      ? "/api/import"
      : `/api/projects/${state.projectId}/import`;
    const result = await api(path, { method: "POST", body: JSON.stringify(body) });
    closeImportModal();

    if ((destination === "proof_compare" || destination === "proof_pipeline") && (result.proof || result.pipeline)) {
      const proof = result.proof || result.pipeline?.step3_proof;
      const match = result.match || result.pipeline?.step1_match;
      if (proof) {
        openProofReportModal(proof, { match });
      }
      // Surface match confidence for Tory identification
      if (match && match.matched_episode_number != null) {
        const conf = typeof match.confidence_score === "number"
          ? ` (신뢰도 ${Math.round(match.confidence_score * 100)}%)`
          : "";
        setAiPanelOpen(true);
        if ($("aiResult")) {
          $("aiResult").value = [
            i18n.t('app.토리_교정본_식별_결과'),
            "",
            `${i18n.t('app.매칭_회차_match_matched_epis', {'match.matched_episode_number': match.matched_episode_number, 'match.matched_title || "회차"': match.matched_title || "회차", conf: conf})}`,
            match.method ? `${i18n.t('app.식별_방법_match_method', {'match.method': match.method})}` : "",
            "",
            i18n.t('app.교정_교열_보고서_창에서_오탈자_문장_수정'),
            destination === "proof_pipeline" && !result.applied
              ? i18n.t('app.원고는_덮어쓰지_않았습니다_비교_보고서만_만')
              : "",
          ].filter(Boolean).join("\n");
          ensureAiResultVisible();
        }
      }
      if (destination === "proof_pipeline" && result.applied && result.scene_ids?.length) {
        await loadProjects(result.project_id);
        await openScene(result.scene_ids[0]);
        toast(i18n.t('app.토리_교정_완료_정제_본문을_회차에_반영했습'));
      } else if (destination === "proof_pipeline") {
        const parser = result.extract?.parser || result.pipeline?.extract?.parser || "";
        toast(
          i18n.t('app.토리_교정_파이프라인_완료_parser', {
            parser: parser ? ` (${parser})` : "",
          }) + i18n.t('app.보고서_확인_원고_미변경'),
        );
      } else {
        toast(i18n.t('app.토리가_교정_비교_보고서를_만들었어요_원고는'));
      }
      submit.disabled = false;
      submit.textContent = i18n.t('app.가져오기');
      return;
    }

    await loadProjects(result.project_id);
    if (result.scene_ids?.length) {
      await openScene(result.scene_ids[0]);
    }
    if (String(result.character_analysis?.status || "") === "running") {
      watchCharacterAnalysis(result.project_id);
    }
    const warning = result.warnings?.length ? ` (${result.warnings[0]})` : "";
    const purposeName = purposeLabel[result.purpose] || "";
    const chapters = result.chapter_count ? `챕터 ${result.chapter_count}개 · ` : "";
    const packageNote = result.package_name ? ` · 파일 ${result.package_name}` : "";
    const match = result.match;
    if (match && match.matched_episode_number != null) {
      const conf = typeof match.confidence_score === "number"
        ? ` · 신뢰도 ${Math.round(match.confidence_score * 100)}%`
        : "";
      toast(
        `${i18n.t('app.match_matched_episode_n', {'match.matched_episode_number': match.matched_episode_number, 'match.matched_title || "회차"': match.matched_title || "회차"})}`
        + `${i18n.t('app.conf_result_word_count', {conf: conf, 'result.word_count || 0': result.word_count || 0, packageNote: packageNote})}`,
      );
    } else {
      toast(
        i18n.t('app.문서를_가져왔어요_purposeName', {
          purposeName: purposeName ? `${purposeName} · ` : "",
        })
        + i18n.t('app.chapters_씬_result_secti', {
          chapters,
          'result.section_count': result.section_count,
          'result.word_count': result.word_count,
          packageNote,
          warning,
        }),
      );
    }
  } catch (error) {
    handleError(error);
    submit.disabled = false;
    submit.textContent = i18n.t('app.가져오기');
  }
}

function openAdminModal(tab = null) {
  closeCreateMenu();
  hideUiFeatureContextMenu();
  $("adminModal")?.classList.remove("hidden");
  const langSel = $("adminLangSelect");
  if (langSel && typeof i18n !== "undefined" && typeof i18n.getLang === "function") {
    langSel.value = i18n.getLang();
  }
  if (tab) setAdminTab(tab);
  updateFeatureHideCountUi();
  renderHiddenFeaturesList();
  refreshAdminInfoPanel();
  refreshAdminAccountPanel().catch(handleError);
  loadTrashList().catch(handleError);
}

function closeAdminModal() {
  $("adminModal")?.classList.add("hidden");
}

function setAdminTab(tabId) {
  let id = String(tabId || "info");
  if (id === "hidden") id = "settings";
  document.querySelectorAll("#adminModal .admin-tab").forEach((btn) => {
    const on = btn.dataset.adminTab === id;
    btn.classList.toggle("is-active", on);
    btn.setAttribute("aria-selected", on ? "true" : "false");
  });
  document.querySelectorAll("#adminModal .admin-panel").forEach((panel) => {
    const on = panel.dataset.adminPanel === id;
    panel.classList.toggle("is-active", on);
    if (on) panel.removeAttribute("hidden");
    else panel.setAttribute("hidden", "");
  });
  if (id === "trash") loadTrashList().catch(handleError);
  if (id === "projects") {
    renderAdminProjectList();
    loadIndexRebuildOverview().catch(handleError);
  }
  if (id === "settings") {
    renderAdminThemeList();
    renderHiddenFeaturesList();
    if (typeof renderAdminAmbientList === "function") renderAdminAmbientList();
  }
  if (id === "info") {
    refreshAdminInfoPanel();
    renderAdminHelpManual($("adminHelpSearch")?.value || "");
    renderAdminHelpQa();
  }
  if (id === "account") refreshAdminAccountPanel().catch(handleError);
}

function renderAdminProjectList() {
  const list = $("adminProjectList");
  const hint = $("adminProjectsHint");
  if (!list) return;
  const projects = Array.isArray(state.projects) ? state.projects : [];
  if (hint) {
    hint.textContent = projects.length
      ? `${i18n.t('app.작품_projects_length_개', {'projects.length': projects.length})}`
      : i18n.t('app.아직_작품이_없어요');
  }
  if (!projects.length) {
    list.innerHTML = i18n.t('app.p_class_hint_trash_empt_6');
    return;
  }
  list.innerHTML = projects.map((project) => {
    const id = Number(project.id);
    const title = escapeHtml(project.title || `${i18n.t('app.작품_id', {id: id})}`);
    const current = Number(state.projectId) === id;
    const genre = escapeHtml(
      [project.main_genre, project.sub_genre].filter(Boolean).join(" · ") || i18n.t('app.장르_미정'),
    );
    return `
      <article class="admin-project-item${current ? " is-current" : ""}" data-admin-project="${id}">
        <div class="admin-project-item-main">
          <span class="admin-project-item-title">${title}${current ? i18n.t('app.현재_작품') : ""}</span>
          <span class="admin-project-item-meta">${genre}</span>
        </div>
        <div class="admin-project-item-actions">
          <button type="button" class="secondary compact-btn admin-project-action-btn" data-admin-rename-project="${id}">${i18n.t('index.이름_바꾸기')}</button>
          <button type="button" class="secondary compact-btn admin-danger-btn admin-project-action-btn" data-admin-delete-project="${id}">⚠️ ${i18n.t('app.완전_삭제_버튼')}</button>
        </div>
      </article>`;
  }).join("");
}

const INDEX_REBUILD_DEFAULT_SECONDS = 8;
let indexRebuildSelected = new Set();
let indexRebuildOverview = null;
let indexRebuildPollTimer = null;
let indexRebuildLastStatus = "idle";

function formatIndexRebuildEta(sceneCount, secondsPerScene) {
  const per = Number(secondsPerScene) > 0 ? Number(secondsPerScene) : INDEX_REBUILD_DEFAULT_SECONDS;
  const sec = Math.max(0, Math.round(Number(sceneCount || 0) * per));
  if (sec <= 0) return i18n.t('app.1분_미만');
  if (sec < 60) return `${i18n.t('app.약_sec_초', {sec: sec})}`;
  return `${i18n.t('app.약_Math_max_1_Math_round', {'Math.max(1, Math.round(sec / 60))': Math.max(1, Math.round(sec / 60))})}`;
}

function selectedIndexRebuildProjects() {
  const projects = Array.isArray(indexRebuildOverview?.projects) ? indexRebuildOverview.projects : [];
  return projects.filter((item) => indexRebuildSelected.has(Number(item.id)) && item.selectable);
}

function syncIndexRebuildStartButton() {
  const btn = $("indexRebuildStartButton");
  if (!btn) return;
  const running = String(indexRebuildOverview?.job?.status || "") === "running";
  btn.disabled = running || selectedIndexRebuildProjects().length === 0;
}

function paintIndexRebuildProgress(job) {
  const el = $("indexRebuildProgress");
  if (!el) return;
  el.classList.remove("is-quota", "is-error");
  const status = String(job?.status || "idle");
  if (status === "idle" && !job?.message) {
    el.textContent = "";
    return;
  }
  if (status === "quota") {
    el.classList.add("is-quota");
    el.textContent = i18n.t('app.쿼터_제한에_도달했습니다_잠시_후_다시_시도');
    return;
  }
  if (status === "error") {
    el.classList.add("is-error");
    el.textContent = job?.message || job?.error || i18n.t('app.인덱싱_중_오류가_발생했습니다');
    return;
  }
  el.textContent = String(job?.message || "");
}

function stopIndexRebuildPolling() {
  if (indexRebuildPollTimer) {
    window.clearInterval(indexRebuildPollTimer);
    indexRebuildPollTimer = null;
  }
}

function startIndexRebuildPolling() {
  if (indexRebuildPollTimer) return;
  indexRebuildPollTimer = window.setInterval(() => {
    refreshIndexRebuildJob().catch(() => { /* keep polling */ });
  }, 900);
}

async function refreshIndexRebuildJob() {
  const job = await api("/api/index/rebuild/status");
  if (indexRebuildOverview) indexRebuildOverview.job = job;
  paintIndexRebuildProgress(job);
  syncIndexRebuildStartButton();
  const status = String(job?.status || "");
  const prev = indexRebuildLastStatus;
  indexRebuildLastStatus = status;
  if (status === "running") {
    startIndexRebuildPolling();
    return job;
  }
  stopIndexRebuildPolling();
  if (prev === "running" && (status === "done" || status === "quota" || status === "error")) {
    await loadIndexRebuildOverview({ keepSelection: true });
    if (status === "done") toast(i18n.t('app.회차_인덱스_다시_만들기를_마쳤어요'));
    else if (status === "quota") toast(i18n.t('app.쿼터_제한에_도달했습니다_잠시_후_다시_시도'));
  }
  return job;
}

function renderIndexRebuildList() {
  const list = $("indexRebuildList");
  const hint = $("indexRebuildHint");
  if (!list) return;
  const projects = Array.isArray(indexRebuildOverview?.projects) ? indexRebuildOverview.projects : [];
  const pendingTotal = projects.reduce((sum, item) => sum + Number(item.pending_count || 0), 0);
  if (hint) {
    hint.textContent = projects.length
      ? `${i18n.t('app.처리가_필요한_회차_pendingTotal', {pendingTotal: pendingTotal})}`
      : i18n.t('app.아직_작품이_없어요');
  }
  if (!projects.length) {
    list.innerHTML = i18n.t('app.p_class_hint_trash_empt_7');
    syncIndexRebuildStartButton();
    return;
  }
  list.innerHTML = projects.map((project) => {
    const id = Number(project.id);
    const title = escapeHtml(project.title || `${i18n.t('app.작품_id', {id: id})}`);
    const pending = Number(project.pending_count || 0);
    const total = Number(project.scene_count || 0);
    const selectable = Boolean(project.selectable);
    const checked = selectable && indexRebuildSelected.has(id);
    const extra = project.needs_merge && pending === 0 ? i18n.t('app.인덱스_병합_남음') : "";
    const label = `${i18n.t('app.title_pending_total_회차', {title: title, pending: pending, total: total, extra: extra})}`;
    return `
      <article class="admin-project-item${selectable ? "" : " is-disabled"}" data-index-rebuild-project="${id}">
        <label class="index-rebuild-item-check">
          <input type="checkbox" data-index-rebuild-check="${id}" ${checked ? "checked" : ""} ${selectable ? "" : "disabled"}>
          <span>
            <span class="admin-project-item-title">${label}</span>
            <span class="admin-project-item-meta">${selectable ? i18n.t('app.선택하면_다시_인덱싱합니다') : i18n.t('app.이미_전부_처리된_작품입니다')}</span>
          </span>
        </label>
      </article>`;
  }).join("");
  syncIndexRebuildStartButton();
}

async function loadIndexRebuildOverview(options = {}) {
  const keepSelection = Boolean(options.keepSelection);
  let data;
  try {
    data = await api("/api/index/rebuild");
  } catch (error) {
    const msg = String(error?.message || error || "");
    const stale = Number(error?.status) === 404 || /알 수 없는 요청/.test(msg);
    const list = $("indexRebuildList");
    const hint = $("indexRebuildHint");
    const friendly = stale
      ? i18n.t('app.서버가_이전_버전입니다_SuperTory를')
      : (msg || i18n.t('app.목록을_불러오지_못했습니다'));
    if (hint) hint.textContent = friendly;
    if (list) list.innerHTML = `<p class="hint trash-empty">${escapeHtml(friendly)}</p>`;
    paintIndexRebuildProgress({ status: "error", message: friendly });
    const err = new Error(friendly);
    err.status = error?.status;
    throw err;
  }
  indexRebuildOverview = data;
  if (!keepSelection) {
    indexRebuildSelected = new Set(
      (data.projects || [])
        .filter((item) => item.selectable)
        .map((item) => Number(item.id))
        .filter((id) => indexRebuildSelected.has(id)),
    );
  } else {
    const allowed = new Set(
      (data.projects || []).filter((item) => item.selectable).map((item) => Number(item.id)),
    );
    indexRebuildSelected = new Set([...indexRebuildSelected].filter((id) => allowed.has(id)));
  }
  renderIndexRebuildList();
  paintIndexRebuildProgress(data.job);
  if (String(data.job?.status || "") === "running") startIndexRebuildPolling();
  else stopIndexRebuildPolling();
  return data;
}

function openIndexRebuildConfirm() {
  const selected = selectedIndexRebuildProjects();
  if (!selected.length) return;
  const sceneCount = selected.reduce((sum, item) => sum + Number(item.pending_count || 0), 0);
  const mergeCount = selected.length;
  const calls = sceneCount + mergeCount;
  const seconds = indexRebuildOverview?.seconds_per_scene || INDEX_REBUILD_DEFAULT_SECONDS;
  const eta = formatIndexRebuildEta(sceneCount, seconds);
  const body = $("indexRebuildConfirmBody");
  if (body) {
    body.textContent =
      `선택한 ${selected.length}개 작품, 총 ${sceneCount}개 회차를 다시 인덱싱합니다. `
      + `예상 소요 시간은 ${eta}입니다. (회차당 평균 처리 시간 기준으로 계산, Gemini 호출 약 ${calls}회) `
      + i18n.t('app.Gemini_API_호출이_발생하니_참고해주');
  }
  $("indexRebuildConfirmModal")?.classList.remove("hidden");
}

function closeIndexRebuildConfirm() {
  $("indexRebuildConfirmModal")?.classList.add("hidden");
}

async function startIndexRebuildFromAdmin() {
  const selected = selectedIndexRebuildProjects();
  if (!selected.length) return;
  closeIndexRebuildConfirm();
  const result = await api("/api/index/rebuild", {
    method: "POST",
    body: JSON.stringify({ project_ids: selected.map((item) => Number(item.id)) }),
  });
  if (indexRebuildOverview) indexRebuildOverview.job = result.job;
  indexRebuildLastStatus = "running";
  paintIndexRebuildProgress(result.job);
  syncIndexRebuildStartButton();
  startIndexRebuildPolling();
}

async function renameProjectFromAdmin(projectId) {
  const id = Number(projectId);
  if (!id) return;
  const project = (state.projects || []).find((p) => Number(p.id) === id);
  const oldTitle = String(project?.title || `${i18n.t('app.작품_id', {id: id})}`);
  const nextTitle = await promptText({
    title: i18n.t('app.작품_이름_바꾸기'),
    message: i18n.t('app.새_작품_제목을_입력해_주세요'),
    defaultValue: oldTitle,
    confirmLabel: i18n.t('app.저장'),
  });
  if (nextTitle == null) return; // 취소
  const trimmed = nextTitle.trim();
  if (!trimmed) return toast(i18n.t('app.작품_제목을_입력해_주세요'));
  if (trimmed === oldTitle) return;
  await api(`/api/projects/${id}/title`, {
    method: "PUT",
    body: JSON.stringify({ title: trimmed }),
  });
  toast(`${i18n.t('app.작품_이름을_trimmed_으_로_바꿨어요', {trimmed: trimmed})}`);
  await loadProjects(state.projectId);
  renderAdminProjectList();
}

async function deleteProjectFromAdmin(projectId) {
  const id = Number(projectId);
  if (!id) return;
  const project = (state.projects || []).find((p) => Number(p.id) === id);
  const title = String(project?.title || `${i18n.t('app.작품_id', {id: id})}`).trim();
  const ok = window.confirm(
    `「${title}」 작품을 완전히 삭제할까요?\n\n목록에서 사라지고 다시 불러올 수 없습니다.`,
  );
  if (!ok) return;
  await api(`/api/projects/${id}`, { method: "DELETE" });
  const wasCurrent = Number(state.projectId) === id;
  toast(`${i18n.t('app.title_을_를_삭제했어요', {title: title})}`);
  if (wasCurrent) {
    detachTranslationWorkspaceForProjectChange();
    state.projectId = null;
    state.sceneId = null;
    state.characterId = null;
    state.outline = [];
    state.characters = [];
    state.items = [];
    state.itemId = null;
    state.item = null;
    state.ideas = [];
    state.baits = [];
    $("characterEditor")?.classList.add("hidden");
    $("sceneWorkspace")?.classList.add("hidden");
    $("welcome")?.classList.remove("hidden");
  }
  await loadProjects(wasCurrent ? null : state.projectId);
  renderAdminProjectList();
}

/* —— Auto-update UI (Electron + electron-updater) —— */
function showAppUpdateBanner({ title, message, percent = null, sticky = false } = {}) {
  const banner = $("appUpdateBanner");
  if (!banner) {
    if (message) toast(message);
    return;
  }
  banner.hidden = false;
  banner.classList.remove("hidden");
  if ($("appUpdateBannerTitle")) $("appUpdateBannerTitle").textContent = title || i18n.t('app.업데이트');
  if ($("appUpdateBannerMessage")) $("appUpdateBannerMessage").textContent = message || "";
  const wrap = $("appUpdateBannerProgressWrap");
  const bar = $("appUpdateBannerBar");
  if (wrap && bar && percent != null && Number.isFinite(Number(percent))) {
    wrap.hidden = false;
    const pct = Math.max(0, Math.min(100, Math.round(Number(percent))));
    bar.style.width = `${pct}%`;
  } else if (wrap) {
    wrap.hidden = true;
  }
  window.clearTimeout(showAppUpdateBanner._timer);
  if (!sticky) {
    showAppUpdateBanner._timer = window.setTimeout(() => hideAppUpdateBanner(), 5000);
  }
}

function hideAppUpdateBanner() {
  const banner = $("appUpdateBanner");
  if (!banner) return;
  banner.classList.add("hidden");
  banner.hidden = true;
}

function handleAppUpdateStatus(payload) {
  if (!payload || typeof payload !== "object") return;
  const phase = String(payload.phase || "");
  const version = payload.version ? String(payload.version) : "";
  const message = String(payload.message || "");
  const percent = payload.percent != null ? Number(payload.percent) : null;
  const hint = $("adminUpdateStatusHint");

  if (phase === "checking") {
    if (hint) {
      hint.textContent = message || i18n.t('app.확인_요청을_보냈어요_새_버전이_있으면_안내');
    }
    return;
  }
  if (phase === "available") {
    if (hint) {
      hint.textContent = version
        ? `${i18n.t('app.새_버전_version_을_를_사용할_수_있', {version: version})}`
        : (message || i18n.t('app.새_업데이트가_있습니다'));
    }
    // Native dialog is shown by Electron main; toast as extra cue.
    toast(message || i18n.t('app.새로운_업데이트가_있습니다'));
    return;
  }
  if (phase === "deferred") {
    if (hint) hint.textContent = message || i18n.t('app.업데이트를_나중에_설치할_수_있습니다');
    toast(message || i18n.t('app.업데이트를_나중에_할게요'));
    hideAppUpdateBanner();
    return;
  }
  if (phase === "downloading") {
    if (hint) {
      hint.textContent = percent != null
        ? `${i18n.t('app.다운로드_중_Math_round_percen', {'Math.round(percent)': Math.round(percent)})}`
        : (message || i18n.t('app.업데이트_다운로드_중'));
    }
    showAppUpdateBanner({
      title: version ? `${i18n.t('app.업데이트_version', {version: version})}` : i18n.t('app.업데이트_다운로드'),
      message: message || i18n.t('app.백그라운드에서_받는_중'),
      percent: percent != null ? percent : 0,
      sticky: true,
    });
    return;
  }
  if (phase === "downloaded" || phase === "installing") {
    if (hint) hint.textContent = message || i18n.t('app.설치를_위해_앱을_다시_시작합니다');
    showAppUpdateBanner({
      title: i18n.t('app.업데이트_설치'),
      message: message || i18n.t('app.앱을_다시_시작합니다'),
      percent: 100,
      sticky: true,
    });
    toast(message || i18n.t('app.업데이트를_설치하기_위해_다시_시작합니다'));
    return;
  }
  if (phase === "none") {
    if (hint) {
      hint.textContent = message || i18n.t('app.현재_최신_버전이네요_새_버전이_있으면_안내');
    }
    if (message && !/최신/.test(message)) toast(message);
    return;
  }
  if (phase === "unavailable") {
    if (hint) hint.textContent = message || i18n.t('app.업데이트를_지금은_확인할_수_없습니다');
    return;
  }
  if (phase === "error") {
    if (hint) hint.textContent = message || i18n.t('app.업데이트_확인에_실패했습니다');
    toast(message || i18n.t('app.업데이트_확인에_실패했습니다'));
    hideAppUpdateBanner();
  }
}

function setupAutoUpdateUi() {
  const btn = $("adminCheckUpdateButton");
  if (btn?.dataset.updateBound === "1") return;
  if (btn) btn.dataset.updateBound = "1";

  if (window.electronAPI?.onUpdateStatus) {
    try {
      window.electronAPI.onUpdateStatus(handleAppUpdateStatus);
    } catch (_) {
      /* ignore */
    }
  }

  btn?.addEventListener("click", async () => {
    const hint = $("adminUpdateStatusHint");
    if (!window.electronAPI?.checkForUpdates) {
      if (hint) hint.textContent = i18n.t('app.업데이트_확인은_설치된_데스크톱_앱에서만_사');
      toast(i18n.t('app.업데이트_확인은_설치된_앱에서만_사용할_수'));
      return;
    }
    btn.disabled = true;
    // 결과 대기 중 문구. 실제 최신/업데이트 여부는 onUpdateStatus(phase)가 덮어씀.
    if (hint) hint.textContent = i18n.t('app.확인_요청을_보냈어요_새_버전이_있으면_안내');
    try {
      const result = await window.electronAPI.checkForUpdates();
      if (result?.reason === "dev") {
        if (hint) hint.textContent = i18n.t('app.개발_실행_중에는_자동_업데이트가_꺼져_있어');
        toast(i18n.t('app.개발_모드에서는_업데이트를_확인하지_않습니다'));
      } else if (result?.reason === "not_configured") {
        const msg = result.error
          || i18n.t('app.업데이트_서버가_설정되지_않았습니다_upda');
        if (hint) hint.textContent = msg;
        toast(msg);
      } else if (result?.ok === false && result?.error) {
        if (hint) hint.textContent = i18n.t('app.업데이트_확인에_실패했습니다');
        toast(`${i18n.t('app.업데이트_확인_실패_result_error', {'result.error': result.error})}`);
      }
      // ok인 경우: IPC 반환 시점에 update-not-available 등이 이미 왔을 수 있음.
      // 대기 문구로 다시 덮어쓰지 않고 handleAppUpdateStatus 결과를 유지한다.
    } catch (error) {
      handleError(error);
    } finally {
      btn.disabled = false;
    }
  });
}

/* —— UI feature hide (right-click) + admin “숨긴 기능” box —— */
const FEATURE_HIDE_STORAGE_KEY = "supertory.hiddenUiFeatures";
const APP_VERSION_FALLBACK = "1.3.10";
/** @type {Map<string, string>} hideId → label */
let featureHideMap = new Map();
/** Last control targeted by a multi-item context menu (for footer “숨기기”). */
let uiFeatureCtxTarget = null;
let uiFeatureCtxMenuTarget = null;

const UI_HIDEABLE_SELECTOR = [
  "button",
  ".feature-chip",
  ".icon-btn",
  ".format-btn",
  ".compact-btn",
  ".outline-action-btn",
  ".outline-new-folder-btn",
  ".stat-chip",
  ".status-scope-btn",
  ".scene-synopsis-label-btn",
  ".outline-folder-count",
  ".outline-scene-count",
  ".outline-count-badges",
  ".bookmark-chip",
  ".settings-box[data-settings-section]",
  "[data-ui-hide-label]",
  "select.format-select",
  ".format-toolbar select",
  ".status-bar-field",
  ".status-bar-progress",
  "#statusBarProgress",
  "#sceneGoalBar",
  "#writingLogButton",
].join(", ");

function loadFeatureHideMap() {
  const map = new Map();
  try {
    const raw = localStorage.getItem(FEATURE_HIDE_STORAGE_KEY);
    if (!raw) return map;
    const arr = JSON.parse(raw);
    if (!Array.isArray(arr)) return map;
    for (const item of arr) {
      if (typeof item === "string" && item) {
        map.set(item, labelFromHideId(item));
      } else if (item && typeof item === "object" && item.id) {
        map.set(String(item.id), String(item.label || labelFromHideId(item.id)));
      }
    }
  } catch (_) {
    /* ignore */
  }
  return map;
}

function saveFeatureHideMap() {
  try {
    const payload = [...featureHideMap.entries()].map(([id, label]) => ({ id, label }));
    localStorage.setItem(FEATURE_HIDE_STORAGE_KEY, JSON.stringify(payload));
  } catch (_) {
    /* ignore */
  }
  updateFeatureHideCountUi();
  renderHiddenFeaturesList();
}

function labelFromHideId(id) {
  const s = String(id || "");
  if (s.startsWith("id:")) return s.slice(3);
  return i18n.t('app.숨긴_기능');
}

function simpleUiHash(str) {
  let h = 0;
  const s = String(str || "");
  for (let i = 0; i < s.length; i += 1) {
    h = ((h << 5) - h) + s.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h).toString(36);
}

function isFeatureHideExempt(el) {
  if (!el || el.nodeType !== 1) return true;
  if (el.classList?.contains("feature-hide-exempt")) return true;
  if (el.closest?.(".context-menu, #adminModal, .modal, #outlineSpacingMenu, #formatColorPalette, #formatListPalette, #uiFeatureContextMenu")) {
    return true;
  }
  const id = el.id || "";
  if (id === "toryChatHighlightButton" || el.closest?.("#toryChatHighlightButton, .tory-chat-hl-btn")) {
    return true;
  }
  // 본문·설정집·도우미·토리와 대화 탭: 우클릭 숨기기 비활성
  if (
    id === "binderTabManuscript"
    || id === "binderTabSettings"
    || id === "aiTabTools"
    || id === "aiTabChat"
  ) {
    return true;
  }
  if (el.closest?.("#binderTabManuscript, #binderTabSettings, #aiTabTools, #aiTabChat")) {
    return true;
  }
  if (
    id === "adminModeButton"
    || id === "featureHideResetButton"
    || id === "uiThemeToggleButton"
    || id === "ambientSoundButton"
    || id === "gitsiPopoverButton"
    || id === "uiFeatureHideMenuItem"
    || id === "adminContactDevButton"
    || id === "adminHelpSearch"
  ) {
    return true;
  }
  if (el.dataset?.closeAdmin != null || el.classList?.contains("modal-close")) return true;
  if (el.closest?.(".titlebar-controls")) return true;
  return false;
}

function isManuscriptWritingSurface(target) {
  if (!target?.closest) return false;
  if (target.closest("#desktopContextMenu")) return true;
  if (target.closest("#sceneContent, #splitSceneContent, #synopsisContent, #synopsisContentB, #loglineContent, #worldContent, #introContent, #intentContent")) {
    if (target.closest("[contenteditable='true'], .rich-editor, .manuscript-page")) return true;
  }
  if (target.closest("#manuscriptPage .rich-editor, #manuscriptPage [contenteditable='true']")) return true;
  if (target.closest(".manuscript-sheet, .page-sheet") && !target.closest("button, .format-toolbar, .scene-feature-bar, .ms-toolbar-shell, .status-bar")) {
    if (target.closest("[contenteditable], .rich-editor, p, .scene-body")) return true;
  }
  return false;
}

function ensureUiHideId(el) {
  if (!el || el.nodeType !== 1) return "";
  if (el.dataset.uiHideId) return el.dataset.uiHideId;
  if (el.id) {
    el.dataset.uiHideId = `id:${el.id}`;
    return el.dataset.uiHideId;
  }
  const parts = [
    el.tagName,
    el.dataset.format || "",
    el.dataset.toolsAction || "",
    el.dataset.contextAction || "",
    el.dataset.createAction || "",
    el.dataset.colorKind || "",
    el.dataset.uiHideLabel || "",
    el.getAttribute("aria-label") || "",
    el.getAttribute("title") || "",
    (el.className && typeof el.className === "string" ? el.className : "") || "",
    (el.textContent || "").replace(/\s+/g, " ").trim().slice(0, 48),
  ].join("|");
  el.dataset.uiHideId = `auto:${simpleUiHash(parts)}`;
  return el.dataset.uiHideId;
}

function getUiFeatureLabel(el) {
  if (!el) return i18n.t('app.기능');
  const explicit = el.dataset?.uiHideLabel || el.getAttribute?.("data-ui-hide-label");
  if (explicit) return String(explicit).trim();
  const aria = (el.getAttribute?.("aria-label") || "").trim();
  if (aria) return aria.replace(/\s+/g, " ").slice(0, 60);
  const title = (el.getAttribute?.("title") || "").trim().split(/[·|]/)[0].trim();
  if (title) return title.slice(0, 60);
  const strong = el.querySelector?.("strong")?.textContent?.trim();
  if (strong) return strong.slice(0, 60);
  const text = (el.textContent || "").replace(/\s+/g, " ").trim();
  if (text) return text.slice(0, 48);
  if (el.id) return el.id;
  return i18n.t('app.이름_없는_기능');
}

/**
 * Resolve a hideable control under the pointer.
 * Disabled buttons often do not receive contextmenu — fall back to elementsFromPoint.
 * @param {EventTarget|null} target
 * @param {number} [clientX]
 * @param {number} [clientY]
 */
function findHideableControl(target, clientX, clientY) {
  const rejectIfBad = (el) => {
    if (!el || el.nodeType !== 1) return null;
    if (isFeatureHideExempt(el)) return null;
    if (el.closest?.(".context-menu, #formatColorPalette, #formatListPalette, #outlineSpacingMenu, #adminModal")) {
      return null;
    }
    if (el.closest?.("#outline") && el.matches?.("[data-scene], [data-rename-chapter], [data-rename-part], .scene-link, .folder-title-box, .part-title, .chapter-title")) {
      return null;
    }
    if (!el.matches?.(UI_HIDEABLE_SELECTOR) && !el.closest?.(UI_HIDEABLE_SELECTOR)) {
      return null;
    }
    const hit = el.matches?.(UI_HIDEABLE_SELECTOR) ? el : el.closest(UI_HIDEABLE_SELECTOR);
    if (!hit || isFeatureHideExempt(hit)) return null;
    if (hit.closest?.(".context-menu, #formatColorPalette, #formatListPalette, #outlineSpacingMenu, #adminModal")) {
      return null;
    }
    return hit;
  };

  let el = null;
  if (target?.closest) {
    el = rejectIfBad(target.closest(UI_HIDEABLE_SELECTOR));
  }

  // Disabled <button> often skips contextmenu; hit-test under cursor instead
  const needHitTest = !el || (typeof el.disabled === "boolean" && el.disabled);
  if (
    needHitTest
    && Number.isFinite(clientX)
    && Number.isFinite(clientY)
    && typeof document.elementsFromPoint === "function"
  ) {
    try {
      const stack = document.elementsFromPoint(clientX, clientY) || [];
      for (const node of stack) {
        const found = rejectIfBad(
          node?.matches?.(UI_HIDEABLE_SELECTOR)
            ? node
            : node?.closest?.(UI_HIDEABLE_SELECTOR),
        );
        if (found) {
          el = found;
          break;
        }
      }
    } catch (_) {
      /* ignore */
    }
  }

  return el || null;
}

function collectHideableControls(root = document) {
  return [...root.querySelectorAll(UI_HIDEABLE_SELECTOR)].filter((el) => {
    if (isFeatureHideExempt(el)) return false;
    if (el.getAttribute("aria-hidden") === "true") return false;
    if (el.type === "hidden") return false;
    if (el.closest?.(".context-menu, #adminModal, .modal, #formatColorPalette, #formatListPalette")) return false;
    if (el.closest?.("#outline") && el.matches?.("[data-scene], .scene-link, .folder-title-box, .part-title, .chapter-title")) {
      return false;
    }
    return true;
  });
}

function applyFeatureHideClasses() {
  collectHideableControls().forEach((el) => {
    const id = ensureUiHideId(el);
    if (!id) return;
    el.classList.toggle("ui-feature-hidden", featureHideMap.has(id));
  });
  document.querySelectorAll(".feature-hide-exempt, #toryChatHighlightButton").forEach((el) => {
    el.classList.remove("ui-feature-hidden");
  });
  ["adminModeButton", "featureHideResetButton", "guideTipResetButton", "uiThemeToggleButton", "ambientSoundButton", "adminContactDevButton"]
    .forEach((id) => $(id)?.classList.add("feature-hide-exempt"));
  updateFeatureHideCountUi();
}

function updateFeatureHideCountUi() {
  const n = featureHideMap.size;
  const hint = $("featureHideCountHint");
  if (hint) hint.textContent = n ? `${i18n.t('app.숨긴_기능_n_개', {n: n})}` : i18n.t('app.숨긴_기능_없음');
}

function hideUiFeatureElement(el, { quiet = false } = {}) {
  if (!el || isFeatureHideExempt(el)) return false;
  const id = ensureUiHideId(el);
  if (!id) return false;
  const label = getUiFeatureLabel(el);
  featureHideMap.set(id, label);
  el.classList.add("ui-feature-hidden");
  saveFeatureHideMap();
  if (!quiet) toast(`${i18n.t('app.label_을_를_숨겼습니다', {label: label})}`);
  return true;
}

function showUiFeatureById(hideId, { quiet = false } = {}) {
  if (!hideId || !featureHideMap.has(hideId)) return false;
  const label = featureHideMap.get(hideId) || i18n.t('app.기능');
  featureHideMap.delete(hideId);
  saveFeatureHideMap();
  applyFeatureHideClasses();
  if (!quiet) toast(`${i18n.t('app.label_을_를_다시_표시합니다', {label: label})}`);
  return true;
}

function resetAllHiddenFeatures() {
  if (!featureHideMap.size) {
    toast(i18n.t('app.숨긴_기능이_없어요'));
    return;
  }
  if (!window.confirm(`${i18n.t('app.숨긴_기능_featureHideMap_siz', {'featureHideMap.size': featureHideMap.size})}`)) return;
  featureHideMap = new Map();
  saveFeatureHideMap();
  applyFeatureHideClasses();
  toast(i18n.t('app.모든_기능을_다시_표시했습니다'));
}

function renderHiddenFeaturesList() {
  const host = $("hiddenFeaturesList");
  if (!host) return;
  if (!featureHideMap.size) {
    host.innerHTML = i18n.t('app.p_class_hint_trash_empt_8');
    return;
  }
  const rows = [...featureHideMap.entries()]
    .sort((a, b) => String(a[1]).localeCompare(String(b[1]), "ko"))
    .map(([id, label]) => `
      <div class="hidden-feature-item" data-hidden-id="${escapeHtml(id)}">
        <div class="hidden-feature-main">
          <span class="hidden-feature-title">${escapeHtml(label || labelFromHideId(id))}</span>
          <span class="hidden-feature-id hint">${escapeHtml(id)}</span>
        </div>
        <button type="button" class="primary compact-btn" data-hidden-activate="${escapeHtml(id)}">활성화</button>
      </div>
    `).join("");
  host.innerHTML = rows;
}

function setUiFeatureCtxTarget(el) {
  uiFeatureCtxTarget = el && el.nodeType === 1 ? el : null;
}

function hideUiFeatureContextMenu() {
  $("uiFeatureContextMenu")?.classList.add("hidden");
  uiFeatureCtxMenuTarget = null;
}

function placeContextMenuEl(menu, clientX, clientY) {
  if (!menu) return;
  menu.classList.remove("hidden");
  const pad = 8;
  const rect = menu.getBoundingClientRect();
  let left = Number(clientX) || 12;
  let top = Number(clientY) || 12;
  const w = rect.width || 220;
  const h = rect.height || 120;
  if (left + w > window.innerWidth - pad) left = Math.max(pad, window.innerWidth - w - pad);
  if (top + h > window.innerHeight - pad) top = Math.max(pad, window.innerHeight - h - pad);
  menu.style.left = `${Math.round(left)}px`;
  menu.style.top = `${Math.round(top)}px`;
}

/**
 * @param {number} x
 * @param {number} y
 * @param {Element} el
 * @param {{ label: string, hint?: string, run: () => void }[]} [extraItems]
 */
function showUiFeatureContextMenu(x, y, el, extraItems = []) {
  const menu = $("uiFeatureContextMenu");
  if (!menu || !el) return;
  uiFeatureCtxMenuTarget = el;
  setUiFeatureCtxTarget(el);
  const labelEl = $("uiFeatureContextLabel");
  if (labelEl) labelEl.textContent = getUiFeatureLabel(el);
  const extraHost = $("uiFeatureContextExtra");
  const divider = $("uiFeatureContextDivider");
  if (extraHost) {
    extraHost.innerHTML = "";
    for (const item of extraItems) {
      if (!item?.label) continue;
      const btn = document.createElement("button");
      btn.type = "button";
      btn.setAttribute("role", "menuitem");
      btn.dataset.uiFeatureExtra = "1";
      btn.innerHTML = `<strong>${escapeHtml(item.label)}</strong>${item.hint ? `<span>${escapeHtml(item.hint)}</span>` : ""}`;
      btn.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        hideUiFeatureContextMenu();
        try { item.run?.(); } catch (err) { handleError(err); }
      });
      extraHost.appendChild(btn);
    }
  }
  if (divider) divider.hidden = !(extraItems && extraItems.length);
  placeContextMenuEl(menu, x, y);
}

function onUiFeatureHideAction() {
  const el = uiFeatureCtxMenuTarget || uiFeatureCtxTarget;
  hideUiFeatureContextMenu();
  document.querySelectorAll(".context-menu:not(.hidden), #formatColorPalette:not(.hidden), #formatListPalette:not(.hidden), #outlineSpacingMenu:not(.hidden)")
    .forEach((m) => m.classList.add("hidden"));
  if (!el) {
    toast(i18n.t('app.숨길_기능을_찾지_못했어요'));
    return;
  }
  if (el.id === "outlineSpacingButton" && typeof exitOutlineSpacingAdjustMode === "function") {
    try { exitOutlineSpacingAdjustMode({ toastMsg: false }); } catch (_) { /* ignore */ }
  }
  hideUiFeatureElement(el);
}

function onGlobalUiFeatureContextMenu(event) {
  if (event.defaultPrevented) return;
  if (isManuscriptWritingSurface(event.target)) return;
  if (event.target.closest?.("#ambientSoundPopup, #binderAmbientControl, #adminAmbientSection")) return;
  if (event.target.closest?.("#projectSelect, .project-picker")) return;
  if (event.target.closest?.([
    "#adminModal",
    "#uiFeatureContextMenu",
    ".modal:not(.hidden)",
    "#desktopContextMenu",
    "#binderContextMenu",
    "#chapterContextMenu",
    "#partContextMenu",
    "#settingsContextMenu",
  ].join(", "))) return;

  // 설정집 폴더: 우클릭 메뉴는 제목(메인) 버튼에만. 본문·미리보기·→메인 등에서는 숨기기 메뉴도 열지 않음.
  const settingsBox = event.target.closest?.("#settingsAccordion .settings-box[data-settings-section]");
  if (settingsBox) {
    const onMainToggle = event.target.closest?.(".settings-box-toggle[data-settings-toggle]");
    if (!onMainToggle) return;
  }

  const el = findHideableControl(event.target, event.clientX, event.clientY);
  if (!el) return;

  // 목차 제목·개수: 우클릭 기능 없음 (글자 크기는 줄간격 아이콘 우클릭)
  if (event.target.closest?.("#outlineTocHeading, .outline-toc-heading, #outlineFolderCount, #outlineSceneCount, .outline-count-badges, .outline-folder-count, .outline-scene-count")) {
    event.preventDefault();
    return;
  }

  event.preventDefault();
  event.stopPropagation();

  const formatListBtn = el.closest?.(".format-list-btn, [data-format='list']") || (el.dataset?.format === "list" ? el : null);
  const formatColorBtn = el.closest?.("[data-color-kind]") || (el.dataset?.colorKind ? el : null);
  if (formatListBtn && formatListBtn.closest?.(".format-toolbar")) {
    setUiFeatureCtxTarget(formatListBtn);
    showUiFeatureContextMenu(event.clientX, event.clientY, formatListBtn, [{
      label: i18n.t('app.목록_기호_선택'),
      hint: i18n.t('app.글머리_번호_스타일'),
      run: () => {
        const editor = $("sceneContent");
        if (typeof showFormatListPalette === "function") showFormatListPalette(formatListBtn, editor);
      },
    }]);
    return;
  }
  if (formatColorBtn && formatColorBtn.closest?.(".format-toolbar, .tory-chat-toolbar")) {
    setUiFeatureCtxTarget(formatColorBtn);
    const kind = formatColorBtn.dataset.colorKind || "text";
    showUiFeatureContextMenu(event.clientX, event.clientY, formatColorBtn, [{
      label: kind === "highlight" ? i18n.t('app.형광펜_색_선택') : i18n.t('app.글자색_선택'),
      hint: i18n.t('app.팔레트_열기'),
      run: () => {
        const editor = $("sceneContent");
        if (typeof showFormatColorPalette === "function") {
          showFormatColorPalette(
            kind,
            formatColorBtn,
            editor,
            formatColorBtn.closest?.("#toryChatHighlightButton, .tory-chat") ? { target: "tory-chat" } : undefined,
          );
        }
      },
    }]);
    return;
  }

  if (el.id === "writingLogButton" || el.closest?.("#writingLogButton")) {
    const btn = $("writingLogButton") || el;
    setUiFeatureCtxTarget(btn);
    showUiFeatureContextMenu(event.clientX, event.clientY, btn, [{
      label: i18n.t('app.기록_달력_설정'),
      hint: i18n.t('app.글쓰기_기록_열기'),
      run: () => { openWritingLogModal?.("calendar")?.catch?.(handleError); },
    }, {
      label: i18n.t('app.폰_연동'),
      hint: i18n.t('app.연동_코드_핸드폰_기록_포함'),
      run: () => { openWritingLogModal?.("phone")?.catch?.(handleError); },
    }]);
    return;
  }

  if (el.id === "synopsisListButton" || el.closest?.("#synopsisListButton, .scene-synopsis-label-btn")) {
    const btn = $("synopsisListButton") || el;
    setUiFeatureCtxTarget(btn);
    showUiFeatureContextMenu(event.clientX, event.clientY, btn, [{
      label: i18n.t('app.토리야_요약해_줘'),
      hint: i18n.t('app.본문을_요약해_요약_칸에_넣기'),
      run: () => { runTorySceneSummary().catch(handleError); },
    }]);
    return;
  }

  if (el.id === "statusBarProgress" || el.id === "sceneGoalBar" || el.closest?.("#statusBarProgress, #sceneGoalBar")) {
    const btn = $("statusBarProgress") || el;
    setUiFeatureCtxTarget(btn);
    showUiFeatureContextMenu(event.clientX, event.clientY, btn, [{
      label: i18n.t('app.게이지_색_선택'),
      run: () => { showGoalBarColorMenu?.(btn); },
    }]);
    return;
  }

  setUiFeatureCtxTarget(el);
  showUiFeatureContextMenu(event.clientX, event.clientY, el, []);
}

function setupUiFeatureHideSystem() {
  featureHideMap = loadFeatureHideMap();
  applyFeatureHideClasses();
  updateFeatureHideCountUi();
  renderHiddenFeaturesList();

  $("featureHideResetButton")?.addEventListener("click", resetAllHiddenFeatures);

  $("hiddenFeaturesList")?.addEventListener("click", (event) => {
    const btn = event.target.closest?.("[data-hidden-activate]");
    if (!btn) return;
    event.preventDefault();
    showUiFeatureById(btn.dataset.hiddenActivate);
  });

  $("uiFeatureHideMenuItem")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    onUiFeatureHideAction();
  });

  document.addEventListener("click", (event) => {
    const hideBtn = event.target.closest?.("[data-ui-feature-hide]");
    if (!hideBtn) return;
    event.preventDefault();
    event.stopPropagation();
    onUiFeatureHideAction();
  });

  document.addEventListener("contextmenu", onGlobalUiFeatureContextMenu, false);

  document.addEventListener("click", (event) => {
    if (event.target.closest?.("#uiFeatureContextMenu")) return;
    hideUiFeatureContextMenu();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") hideUiFeatureContextMenu();
  });

  let featureHideApplyTimer = null;
  const mo = new MutationObserver(() => {
    if (featureHideApplyTimer) return;
    featureHideApplyTimer = window.setTimeout(() => {
      featureHideApplyTimer = null;
      applyFeatureHideClasses();
    }, 120);
  });
  try {
    mo.observe(document.body, { childList: true, subtree: true });
  } catch (_) {
    /* ignore */
  }
}

