function stripAmbientLoopJunk(text) {
  return String(text || "")
    .replace(/[-_\s]*loop[-_\s]*0?m?\d+s?/gi, "")
    .replace(/[-_\s]+loop\b/gi, "")
    .replace(/\b\d+m\d+s\b/gi, "")
    .replace(/[-_\s]+/g, " ")
    .trim();
}

function humanizeAmbientStem(stem) {
  return stripAmbientLoopJunk(String(stem || "").replace(/[_-]+/g, " "));
}

function ambientTrackRule(id) {
  const track = ambientSound.tracks[id];
  if (!track) return null;
  const hay = stripAmbientLoopJunk(`${track.stem} ${track.file || ""}`);
  return AMBIENT_LABEL_RULES.find((item) => item.test.test(hay) || item.test.test(`${track.stem} ${track.file || ""}`)) || null;
}

function ambientTrackLabel(id) {
  const track = ambientSound.tracks[id];
  if (!track) return i18n.t("app.배경음");
  const customTitle = String(track.customTitle || "").trim();
  if (customTitle) return customTitle;
  if (track.custom) {
    const display = String(track.displayTitle || "").trim();
    return display || humanizeAmbientStem(track.stem) || i18n.t("app.내_음원");
  }
  const rule = ambientTrackRule(id);
  if (rule) return i18n.t(rule.key);
  const display = String(track.displayTitle || "").trim();
  return display || humanizeAmbientStem(track.stem) || i18n.t("app.배경음");
}

function ambientTrackHint(id) {
  const rule = ambientTrackRule(id);
  return rule?.hintKey ? i18n.t(rule.hintKey) : "";
}

function ambientCategoryLabel(catId) {
  const meta = AMBIENT_CATEGORY_META.find((item) => item.id === catId);
  return meta ? i18n.t(meta.labelKey) : catId;
}

function ambientTrackGain(track) {
  const hay = `${track?.id || ""} ${track?.stem || ""} ${track?.file || ""}`;
  const native = /white|화이트/i.test(hay) ? AMBIENT_WHITE_NATIVE_VOLUME : AMBIENT_NATIVE_VOLUME;
  return native / AMBIENT_DEFAULT_VOLUME;
}

function ambientDefaultTrackId() {
  const all = Object.values(ambientSound.tracks);
  const brown = all.find((track) => /brown|브라운/i.test(`${track.stem} ${track.file || ""}`));
  if (brown) return brown.id;
  const noise = ambientSound.categories.find((cat) => cat.id === "noise");
  if (noise?.tracks?.[0]) return noise.tracks[0].id;
  return all[0]?.id || "";
}

function resolveAmbientTrackId(raw) {
  const value = String(raw || "").trim();
  if (value && ambientSound.tracks[value]) return value;
  const aliases = {
    "모닥불": "campfire",
    "시냇물": "stream",
    "파도": "waves",
    "밤소리": "night",
    "창가-비": "window-rain",
    "카페": "cafe",
  };
  let mapped = value;
  Object.entries(aliases).forEach(([from, to]) => {
    mapped = mapped.replace(from, to);
  });
  if (mapped && ambientSound.tracks[mapped]) return mapped;
  const strippedId = value
    .replace(/[-_]?loop[-_]?0?m?\d+s?/gi, "")
    .replace(/[-_]+$/g, "");
  if (strippedId && ambientSound.tracks[strippedId]) return strippedId;
  const all = Object.values(ambientSound.tracks);
  if (!all.length) return "";
  const lower = value.toLowerCase();
  const stemHit = all.find((track) => {
    const stem = String(track.stem || "").toLowerCase();
    const idTail = String(track.id || "").toLowerCase().split(":").pop();
    return stem === lower || idTail === lower || stem.replace(/[\s_-]+/g, "") === lower.replace(/[\s_-]+/g, "");
  });
  if (stemHit) return stemHit.id;
  const fuzzy = all.find((track) => {
    const hay = `${track.id} ${track.stem} ${track.file || ""}`.toLowerCase();
    return lower && hay.includes(lower);
  });
  if (fuzzy) return fuzzy.id;
  return ambientDefaultTrackId();
}

function applyAmbientCatalog(payload) {
  const categories = Array.isArray(payload?.categories) ? payload.categories : [];
  const tracks = {};
  const orphanCustom = [];
  const normalized = AMBIENT_CATEGORY_META.map((meta) => {
    if (meta.id === "custom") return { id: "custom", tracks: [] };
    const found = categories.find((cat) => cat?.id === meta.id) || { id: meta.id, tracks: [] };
    const list = [];
    (Array.isArray(found.tracks) ? found.tracks : []).forEach((item) => {
      if (!item || !item.id || !item.url) return;
      if (item.custom) {
        orphanCustom.push(item);
        return;
      }
      const track = {
        id: String(item.id),
        category: meta.id,
        file: String(item.file || ""),
        stem: String(item.stem || item.file || item.id),
        url: String(item.url),
        custom: false,
        customId: 0,
        customTitle: String(item.custom_title || "").trim(),
        displayTitle: String(item.display_title || "").trim(),
        enabledInPopup: item.enabled_in_popup !== false && item.enabled_in_popup !== 0,
        gain: ambientTrackGain({
          id: String(item.id),
          file: String(item.file || ""),
          stem: String(item.stem || item.file || item.id),
        }),
      };
      tracks[track.id] = track;
      list.push(track);
    });
    return { id: meta.id, tracks: list };
  });
  const customFound = categories.find((cat) => cat?.id === "custom");
  const customItems = [
    ...(Array.isArray(customFound?.tracks) ? customFound.tracks : []),
    ...orphanCustom,
  ];
  const seenCustom = new Set();
  const customTracks = [];
  customItems.forEach((item) => {
    if (!item || !item.id || !item.url || seenCustom.has(item.id)) return;
    seenCustom.add(item.id);
    const track = {
      id: String(item.id),
      category: "custom",
      file: String(item.file || ""),
      stem: String(item.stem || item.file || item.id),
      url: String(item.url),
      custom: true,
      customId: item.custom_id != null ? Number(item.custom_id) : 0,
      customTitle: String(item.custom_title || "").trim(),
      displayTitle: String(item.display_title || "").trim(),
      enabledInPopup: item.enabled_in_popup !== false && item.enabled_in_popup !== 0,
      gain: ambientTrackGain({
        id: String(item.id),
        file: String(item.file || ""),
        stem: String(item.stem || item.file || item.id),
      }),
    };
    tracks[track.id] = track;
    customTracks.push(track);
  });
  const customIndex = normalized.findIndex((cat) => cat.id === "custom");
  if (customIndex >= 0) normalized[customIndex] = { id: "custom", tracks: customTracks };
  else normalized.push({ id: "custom", tracks: customTracks });
  ambientSound.tracks = tracks;
  ambientSound.categories = normalized;
  ambientSound.catalogReady = true;
  const usage = payload?.usage || {};
  ambientSound.customUsage = {
    usedBytes: Number(usage.used_bytes) || 0,
    limitBytes: Number(usage.limit_bytes) || 400 * 1024 * 1024,
  };
  preloadAmbientArt();
  let stored = "";
  try { stored = String(localStorage.getItem(AMBIENT_TRACK_KEY) || "").trim(); } catch (_) { /* ignore */ }
  ambientSound.selectedId = resolveAmbientTrackId(stored || ambientSound.selectedId);
  if (ambientSound.selectedId) {
    try { localStorage.setItem(AMBIENT_TRACK_KEY, ambientSound.selectedId); } catch (_) { /* ignore */ }
  }
}

async function loadAmbientCatalog() {
  const data = await api("/api/ambient-tracks");
  applyAmbientCatalog(data);
  renderAdminAmbientList();
  if (isAmbientPopupOpen()) fillAmbientPopup(true);
  syncAmbientSoundUi();
}

function loadAmbientPrefs() {
  try {
    const calibrated = String(localStorage.getItem(AMBIENT_VOLUME_CALIBRATION_KEY) || "");
    if (calibrated !== AMBIENT_VOLUME_CALIBRATION) {
      ambientSound.volume = AMBIENT_DEFAULT_VOLUME;
      localStorage.setItem(AMBIENT_VOLUME_KEY, String(AMBIENT_DEFAULT_VOLUME));
      localStorage.setItem(AMBIENT_VOLUME_CALIBRATION_KEY, AMBIENT_VOLUME_CALIBRATION);
      return;
    }
    const raw = localStorage.getItem(AMBIENT_VOLUME_KEY);
    if (raw != null && raw !== "") {
      const n = Number(raw);
      if (Number.isFinite(n)) ambientSound.volume = Math.min(1, Math.max(0, n));
    }
  } catch (_) { /* ignore */ }
}

function saveAmbientTrack(id) {
  const next = resolveAmbientTrackId(id);
  ambientSound.selectedId = next;
  if (!next) return;
  try { localStorage.setItem(AMBIENT_TRACK_KEY, next); } catch (_) { /* ignore */ }
}

function saveAmbientVolume(vol) {
  ambientSound.volume = Math.min(1, Math.max(0, Number(vol) || 0));
  try { localStorage.setItem(AMBIENT_VOLUME_KEY, String(ambientSound.volume)); } catch (_) { /* ignore */ }
  if (ambientSound.master && ambientSound.ctx) {
    const now = ambientSound.ctx.currentTime;
    ambientSound.master.gain.cancelScheduledValues(now);
    ambientSound.master.gain.setTargetAtTime(ambientSound.volume, now, 0.03);
  }
}

async function ensureAmbientContext() {
  const AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) throw new Error(i18n.t("app.이_브라우저에서는_배경음을_재생할_수_없어요"));
  if (!ambientSound.ctx) {
    ambientSound.ctx = new AC();
    ambientSound.master = ambientSound.ctx.createGain();
    ambientSound.master.gain.value = ambientSound.volume;
    ambientSound.master.connect(ambientSound.ctx.destination);
  }
  if (ambientSound.ctx.state === "suspended") {
    await ambientSound.ctx.resume();
  }
  return ambientSound.ctx;
}

async function getAmbientBuffer(track) {
  const ctx = ambientSound.ctx;
  const cacheKey = `file:${track.url}`;
  if (ambientSound.buffers.has(cacheKey)) return ambientSound.buffers.get(cacheKey);
  const res = await fetch(track.url, { cache: "no-store" });
  if (!res.ok) throw new Error(i18n.t("app.배경음_파일을_찾지_못했어요"));
  const arr = await res.arrayBuffer();
  const decoded = await ctx.decodeAudioData(arr.slice(0));
  ambientSound.buffers.set(cacheKey, decoded);
  return decoded;
}

function stopAmbientVoices(fadeSec = AMBIENT_FADE_SEC) {
  const ctx = ambientSound.ctx;
  if (!ctx) {
    ambientSound.voices = [];
    return;
  }
  const now = ctx.currentTime;
  const old = ambientSound.voices;
  ambientSound.voices = [];
  old.forEach((voice) => {
    try {
      const current = Math.max(0, voice.gain.gain.value);
      voice.gain.gain.cancelScheduledValues(now);
      voice.gain.gain.setValueAtTime(current, now);
      voice.gain.gain.linearRampToValueAtTime(0, now + fadeSec);
      const stopAt = now + fadeSec + 0.05;
      voice.nodes.forEach((node) => {
        try { if (typeof node.stop === "function") node.stop(stopAt); } catch (_) { /* ignore */ }
      });
      window.setTimeout(() => {
        voice.nodes.forEach((node) => {
          try { node.disconnect(); } catch (_) { /* ignore */ }
        });
        try { voice.gain.disconnect(); } catch (_) { /* ignore */ }
      }, (fadeSec + 0.08) * 1000);
    } catch (_) { /* ignore */ }
  });
}

function createAmbientVoiceGain(targetGain) {
  const ctx = ambientSound.ctx;
  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0, ctx.currentTime);
  gain.gain.linearRampToValueAtTime(targetGain, ctx.currentTime + AMBIENT_FADE_SEC);
  gain.connect(ambientSound.master);
  return gain;
}

async function startAmbientTrack(trackId) {
  if (!ambientSound.catalogReady) {
    try { await loadAmbientCatalog(); } catch (_) { /* ignore */ }
  }
  const id = resolveAmbientTrackId(trackId);
  const track = ambientSound.tracks[id];
  if (!track?.url) throw new Error(i18n.t("app.배경음_파일을_찾지_못했어요"));
  saveAmbientTrack(id);
  syncAmbientSoundUi();
  const token = ++ambientSound.switchToken;
  await ensureAmbientContext();
  if (token !== ambientSound.switchToken) return;
  stopAmbientVoices(AMBIENT_FADE_SEC);
  const buffer = await getAmbientBuffer(track);
  if (token !== ambientSound.switchToken) return;
  const voiceGain = createAmbientVoiceGain(track.gain || ambientTrackGain(track));
  const src = ambientSound.ctx.createBufferSource();
  src.buffer = buffer;
  src.loop = true;
  src.connect(voiceGain);
  src.start();
  ambientSound.voices.push({ gain: voiceGain, nodes: [src] });
  ambientSound.playing = true;
  syncAmbientSoundUi();
}

async function toggleAmbientPlayback() {
  if (ambientSound.playing) {
    stopAmbientVoices(AMBIENT_FADE_SEC);
    ambientSound.playing = false;
    syncAmbientSoundUi();
    return;
  }
  await startAmbientTrack(ambientSound.selectedId || ambientDefaultTrackId());
}

function isAmbientPopupOpen() {
  const popup = $("ambientSoundPopup");
  return Boolean(popup && !popup.hidden && popup.classList.contains("is-open"));
}

function ambientTrackArt(track) {
  const hay = `${track?.stem || ""} ${track?.file || ""}`;
  const rules = [
    [/alpha|알파/i, "ambient-alpha.png"],
    [/beta|gamma|베타|감마/i, "ambient-beta-gamma.png"],
    [/528/, "ambient-528.png"],
    [/white|화이트/i, "ambient-white.png"],
    [/pink|핑크/i, "ambient-pink.png"],
    [/brown|브라운/i, "ambient-brown.png"],
    [/jungle/i, "ambient-jungle.png"],
    [/창가|window.?rain/i, "ambient-window-rain.png"],
    [/모닥|campfire|bonfire|fireplace/i, "ambient-campfire.png"],
    [/파도|ocean|wave|sea/i, "ambient-waves.png"],
    [/시냇물|시냇|stream|brook/i, "ambient-stream.png"],
    [/카페|cafe|coffee/i, "ambient-cafe.png"],
    [/밤|night/i, "ambient-night.png"],
    [/rain|빗/i, "ambient-light-rain.png"],
  ];
  const hit = rules.find((item) => item[0].test(hay));
  return hit ? `/ambient-art/${hit[1]}` : "";
}

const AMBIENT_CUSTOM_BADGE_COLORS = [
  "#F4C7C3",
  "#F8D4A8",
  "#F3E6A4",
  "#C8E6C0",
  "#B7E0D4",
  "#BFD7EA",
  "#C9C4E8",
  "#E4C4D9",
  "#D7CCC8",
  "#C5D5C0",
];

function hashAmbientTrackId(id) {
  const text = String(id || "");
  let hash = 0;
  for (let i = 0; i < text.length; i += 1) {
    hash = (hash * 31 + text.charCodeAt(i)) | 0;
  }
  return Math.abs(hash);
}

function ambientCustomBadgeColors(trackId) {
  const hex = AMBIENT_CUSTOM_BADGE_COLORS[
    hashAmbientTrackId(trackId) % AMBIENT_CUSTOM_BADGE_COLORS.length
  ];
  const raw = hex.slice(1);
  const r = parseInt(raw.slice(0, 2), 16) / 255;
  const g = parseInt(raw.slice(2, 4), 16) / 255;
  const b = parseInt(raw.slice(4, 6), 16) / 255;
  const toLin = (channel) => (
    channel <= 0.03928 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4
  );
  const luminance = 0.2126 * toLin(r) + 0.7152 * toLin(g) + 0.0722 * toLin(b);
  return { background: hex, color: luminance > 0.55 ? "#1a1a1a" : "#ffffff" };
}

function ambientCustomBadgeInitials(title) {
  const text = String(title || "").trim();
  if (!text) return "?";
  const hangul = /[\u1100-\u11FF\u3130-\u318F\uAC00-\uD7A3]/;
  const latin = /[A-Za-z]/;
  const first = text[0];
  if (hangul.test(first)) return first;
  if (latin.test(first)) {
    const letters = text.replace(/[^A-Za-z]/g, "").slice(0, 2);
    return (letters || first).toUpperCase();
  }
  return text.slice(0, 1);
}

function ambientChipArtHtml(track, label) {
  if (track?.custom) {
    const initials = ambientCustomBadgeInitials(label);
    const colors = ambientCustomBadgeColors(track.id);
    return `<span class="ambient-chip-initial" style="background:${escapeHtml(colors.background)};color:${escapeHtml(colors.color)}">${escapeHtml(initials)}</span>`;
  }
  const art = ambientTrackArt(track);
  return art
    ? `<img src="${escapeHtml(art)}" alt="" width="46" height="46" decoding="async">`
    : "";
}

function preloadAmbientArt() {
  const seen = new Set();
  Object.values(ambientSound.tracks).forEach((track) => {
    const src = ambientTrackArt(track);
    if (!src || seen.has(src)) return;
    seen.add(src);
    const img = new Image();
    img.decoding = "async";
    img.src = src;
  });
}

function renderAmbientTrackButtons(selected, options = {}) {
  const withHint = Boolean(options.withHint);
  const manage = Boolean(options.manage);
  const total = Object.keys(ambientSound.tracks).length;
  if (!total && !manage) {
    return `<p class="ambient-empty-hint">${escapeHtml(i18n.t("app.음원_없음"))}</p>`;
  }
  const html = ambientSound.categories.map((cat) => {
    const isCustomGroup = cat.id === "custom";
    const visibleTracks = manage
      ? cat.tracks
      : cat.tracks.filter((track) => track.enabledInPopup !== false);
    if (!visibleTracks.length && !(manage && isCustomGroup)) return "";
    const items = visibleTracks.map((track) => {
      const active = track.id === selected;
      const label = ambientTrackLabel(track.id);
      const hint = withHint ? ambientTrackHint(track.id) : "";
      const title = hint ? `${label} ${hint}` : label;
      const artHtml = ambientChipArtHtml(track, label);
      const hintHtml = hint
        ? `<span class="ambient-chip-hint">${escapeHtml(hint)}</span>`
        : "";
      const chip = `<button type="button" class="ambient-chip${active ? " is-active" : ""}${track.custom ? " is-custom" : ""}" role="menuitemradio" data-ambient-track="${escapeHtml(track.id)}" aria-checked="${active ? "true" : "false"}" title="${escapeHtml(title)}">
        <span class="ambient-chip-art${track.custom ? " is-initial" : ""}" aria-hidden="true">${artHtml}<span class="ambient-chip-check">✓</span></span>
        <span class="ambient-chip-label">${escapeHtml(label)}${hintHtml}</span>
      </button>`;
      if (!manage) return chip;
      const enabled = track.enabledInPopup !== false;
      const renameBtn = `<button type="button" class="ambient-chip-rename" data-ambient-rename="${escapeHtml(track.id)}" title="${escapeHtml(i18n.t("app.제목_바꾸기"))}" aria-label="${escapeHtml(i18n.t("app.제목_바꾸기"))}">
          <svg viewBox="0 0 24 24" width="13" height="13" aria-hidden="true"><path fill="currentColor" d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zm17.71-10.04a1 1 0 0 0 0-1.41l-2.34-2.34a1 1 0 0 0-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z"></path></svg>
        </button>`;
      const toggle = `<label class="ambient-popup-toggle">
          <input type="checkbox" data-ambient-popup-enabled="${escapeHtml(track.id)}" ${enabled ? "checked" : ""}>
          <span>${escapeHtml(i18n.t("app.토글박스에_표시"))}</span>
        </label>`;
      const deleteBtn = track.custom
        ? `<button type="button" class="ambient-chip-delete" data-ambient-custom-delete="${escapeHtml(String(track.customId || ""))}" title="${escapeHtml(i18n.t("app.음원_삭제"))}" aria-label="${escapeHtml(i18n.t("app.음원_삭제"))}">
          <svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true"><path fill="currentColor" d="M9 3h6l1 2h4v2H4V5h4zm1 6h2v9h-2zm4 0h2v9h-2zM7 9h2v9H7z"></path></svg>
        </button>`
        : "";
      return `<div class="ambient-chip-wrap${enabled ? "" : " is-hidden-from-popup"}">
        ${chip}
        ${renameBtn}
        ${deleteBtn}
        ${toggle}
      </div>`;
    }).join("");
    const uploadingHere = manage && isCustomGroup && ambientCustomUploading;
    const addBtn = manage && isCustomGroup
      ? `<button type="button" class="ambient-add-custom${uploadingHere ? " is-busy" : ""}" data-ambient-add="custom" ${ambientCustomUploading ? "disabled" : ""}>
          ${uploadingHere
            ? `<span class="ambient-add-spin" aria-hidden="true"></span>${escapeHtml(i18n.t("app.변환_중"))}`
            : escapeHtml(i18n.t("app.내_음원_추가"))}
        </button>`
      : "";
    return `<section class="ambient-rail-group" data-ambient-cat="${escapeHtml(cat.id)}">
      <h4 class="ambient-rail-title">${escapeHtml(ambientCategoryLabel(cat.id))}</h4>
      ${items ? `<div class="ambient-rail-row">${items}</div>` : ""}
      ${addBtn}
    </section>`;
  }).join("");
  if (!manage && !html.trim()) {
    return `<p class="ambient-empty-hint">${escapeHtml(i18n.t("app.음원_없음"))}</p>`;
  }
  return html;
}

function fillAmbientPopup(force = false) {
  const popup = $("ambientSoundPopup");
  if (!popup) return popup;
  if (!force && popup.querySelector("[data-ambient-track]")) {
    syncAmbientSoundUi();
    return popup;
  }
  const body = renderAmbientTrackButtons(ambientSound.selectedId);
  popup.innerHTML = `<div class="ambient-popup-body">${body}</div><button type="button" class="ambient-popup-manage" data-ambient-manage="1">${escapeHtml(i18n.t("app.음원_관리_전체_보기"))}</button>`;
  return popup;
}

function renderAdminAmbientList() {
  const host = $("adminAmbientTrackList");
  if (!host) return;
  host.innerHTML = renderAmbientTrackButtons(ambientSound.selectedId, { withHint: true, manage: true });
  syncAmbientQuotaUi();
}

function positionAmbientPopup() {
  const popup = $("ambientSoundPopup");
  const button = $("ambientSoundButton");
  if (!popup || !button) return;
  const rect = button.getBoundingClientRect();
  const pad = 8;
  const wasOpen = popup.classList.contains("is-open");
  popup.hidden = false;
  popup.style.visibility = "hidden";
  popup.classList.add("is-open");
  const mw = Math.min(popup.offsetWidth || 520, window.innerWidth - pad * 2);
  let left = rect.right + 8;
  let top = rect.bottom - (popup.offsetHeight || 56);
  if (left + mw > window.innerWidth - pad) {
    left = Math.max(pad, window.innerWidth - mw - pad);
  }
  if (top < pad) top = pad;
  if (top + (popup.offsetHeight || 56) > window.innerHeight - pad) {
    top = Math.max(pad, window.innerHeight - (popup.offsetHeight || 56) - pad);
  }
  popup.style.left = `${Math.round(left)}px`;
  popup.style.top = `${Math.round(top)}px`;
  popup.style.bottom = "auto";
  popup.style.visibility = "";
  if (!wasOpen) {
    popup.classList.remove("is-open");
    void popup.offsetWidth;
    requestAnimationFrame(() => popup.classList.add("is-open"));
  }
}

function closeAmbientPopup() {
  const popup = $("ambientSoundPopup");
  const button = $("ambientSoundButton");
  if (popup) {
    popup.classList.remove("is-open");
    popup.hidden = true;
    popup.style.visibility = "";
  }
  if (button) button.setAttribute("aria-expanded", "false");
}

function openAmbientPopup() {
  if (typeof closeUiThemeRail === "function") closeUiThemeRail();
  if (typeof closeGitsiPopover === "function") closeGitsiPopover();
  const button = $("ambientSoundButton");
  const popup = fillAmbientPopup(true);
  if (!button || !popup) return;
  button.setAttribute("aria-expanded", "true");
  positionAmbientPopup();
}

function toggleAmbientPopup() {
  if (isAmbientPopupOpen()) closeAmbientPopup();
  else openAmbientPopup();
}

function syncAmbientSoundUi() {
  const button = $("ambientSoundButton");
  const playing = Boolean(ambientSound.playing);
  const label = ambientSound.selectedId
    ? ambientTrackLabel(ambientSound.selectedId)
    : i18n.t("app.배경음");
  if (button) {
    button.classList.toggle("is-playing", playing);
    button.setAttribute("aria-pressed", playing ? "true" : "false");
    const title = playing
      ? `${i18n.t("app.배경음_정지")} · ${label}`
      : `${i18n.t("app.배경음_재생")} · ${label}`;
    button.title = title;
    button.setAttribute("aria-label", title);
  }
  const selected = ambientSound.selectedId;
  document.querySelectorAll("#ambientSoundPopup [data-ambient-track], #adminAmbientTrackList [data-ambient-track]").forEach((btn) => {
    const active = btn.getAttribute("data-ambient-track") === selected;
    btn.classList.toggle("is-active", active);
    btn.setAttribute("aria-checked", active ? "true" : "false");
  });
  const name = $("adminAmbientTrackLabel");
  if (name) name.textContent = label;
  const slider = $("adminAmbientVolume");
  const percent = $("adminAmbientVolumeValue");
  const pct = Math.round(ambientSound.volume * 100);
  if (slider && document.activeElement !== slider) slider.value = String(pct);
  if (percent) percent.textContent = `${pct}%`;
  syncAmbientQuotaUi();
}

function openAmbientSettingsPanel() {
  closeAmbientPopup();
  openAdminModal("settings");
  window.setTimeout(() => {
    $("adminAmbientSection")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }, 40);
}

function refreshAmbientSoundUi() {
  if (isAmbientPopupOpen()) fillAmbientPopup(true);
  renderAdminAmbientList();
  syncAmbientSoundUi();
}

function formatAmbientMb(bytes) {
  const mb = Number(bytes || 0) / (1024 * 1024);
  if (!Number.isFinite(mb) || mb <= 0) return "0";
  if (mb < 10) return String(Math.round(mb * 10) / 10).replace(/\.0$/, "");
  return String(Math.round(mb));
}

function syncAmbientQuotaUi() {
  const el = $("adminAmbientQuota");
  if (!el) return;
  const used = formatAmbientMb(ambientSound.customUsage?.usedBytes);
  const limit = formatAmbientMb(ambientSound.customUsage?.limitBytes || 400 * 1024 * 1024);
  el.textContent = i18n.t("app.내_음원_용량", { used, limit });
}

function syncAmbientUploadStatus(on) {
  const el = $("adminAmbientUploadStatus");
  if (!el) return;
  el.hidden = !on;
  el.textContent = on ? i18n.t("app.변환_중") : "";
}

function pickCustomAmbientFile(category) {
  if (ambientCustomUploading) return;
  ambientCustomUploadCategory = String(category || "custom") || "custom";
  const input = $("adminAmbientFileInput");
  if (!input) return;
  input.click();
}

async function uploadCustomAmbientFile(category, file) {
  if (!file || ambientCustomUploading) return;
  ambientCustomUploading = true;
  ambientCustomUploadCategory = String(category || "custom") || "custom";
  renderAdminAmbientList();
  syncAmbientUploadStatus(true);
  try {
    const form = new FormData();
    form.append("category", ambientCustomUploadCategory);
    form.append("file", file);
    await api("/api/ambient/upload", { method: "POST", body: form });
    await loadAmbientCatalog();
    toast(i18n.t("app.음원을_추가했어요"));
  } catch (error) {
    handleError(error);
    renderAdminAmbientList();
  } finally {
    ambientCustomUploading = false;
    ambientCustomUploadCategory = "";
    syncAmbientUploadStatus(false);
    renderAdminAmbientList();
  }
}

async function deleteCustomAmbientTrack(customId) {
  if (!window.confirm(i18n.t("app.이_음원을_삭제할까요"))) return;
  const track = Object.values(ambientSound.tracks).find((item) => Number(item.customId) === Number(customId));
  const wasSelected = Boolean(track && track.id === ambientSound.selectedId);
  if (wasSelected && ambientSound.playing) {
    stopAmbientVoices();
    ambientSound.playing = false;
  }
  await api(`/api/ambient/custom/${customId}`, { method: "DELETE" });
  if (track?.url) ambientSound.buffers.delete(`file:${track.url}`);
  await loadAmbientCatalog();
  if (wasSelected) {
    saveAmbientTrack(ambientDefaultTrackId());
    syncAmbientSoundUi();
  }
  toast(i18n.t("app.음원을_삭제했어요"));
}

function applyAmbientOverrideResult(trackId, data) {
  const track = ambientSound.tracks[trackId];
  if (!track || !data) return track;
  if ("custom_title" in data) track.customTitle = String(data.custom_title || "").trim();
  if ("display_title" in data) track.displayTitle = String(data.display_title || "").trim();
  if ("enabled_in_popup" in data) {
    track.enabledInPopup = data.enabled_in_popup !== false && data.enabled_in_popup !== 0;
  }
  return track;
}

async function patchAmbientTrackOverride(trackId, body) {
  const data = await api(`/api/ambient/overrides/${encodeURIComponent(trackId)}`, {
    method: "PATCH",
    body: JSON.stringify(body),
  });
  applyAmbientOverrideResult(trackId, data);
  renderAdminAmbientList();
  if (isAmbientPopupOpen()) fillAmbientPopup(true);
  syncAmbientSoundUi();
  return data;
}

function startAmbientTitleEdit(trackId) {
  const chip = document.querySelector(
    `#adminAmbientTrackList [data-ambient-track="${CSS.escape(trackId)}"]`
  );
  const label = chip?.querySelector(".ambient-chip-label");
  if (!label || label.querySelector("input")) return;
  const current = ambientTrackLabel(trackId);
  const badgeHtml = label.querySelector(".ambient-chip-badge")?.outerHTML || "";
  const hintHtml = label.querySelector(".ambient-chip-hint")?.outerHTML || "";
  const input = document.createElement("input");
  input.type = "text";
  input.className = "ambient-chip-title-input";
  input.value = current;
  input.maxLength = 80;
  input.setAttribute("aria-label", i18n.t("app.제목_바꾸기"));
  label.textContent = "";
  label.appendChild(input);
  if (badgeHtml) label.insertAdjacentHTML("beforeend", badgeHtml);
  if (hintHtml) label.insertAdjacentHTML("beforeend", hintHtml);
  input.focus();
  input.select();
  let done = false;
  const finish = async (commit) => {
    if (done) return;
    done = true;
    const next = String(input.value || "").trim();
    if (!commit || next === current) {
      renderAdminAmbientList();
      return;
    }
    try {
      await patchAmbientTrackOverride(trackId, { custom_title: next || null });
    } catch (error) {
      handleError(error);
      renderAdminAmbientList();
    }
  };
  input.addEventListener("click", (event) => event.stopPropagation());
  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      finish(true);
    } else if (event.key === "Escape") {
      event.preventDefault();
      finish(false);
    }
  });
  input.addEventListener("blur", () => finish(true));
}

function setupAmbientSound() {
  loadAmbientPrefs();
  syncAmbientSoundUi();
  loadAmbientCatalog().catch((err) => console.warn("[supertory] ambient catalog", err));
  if (document.documentElement.dataset.ambientSoundBound === "1") return;
  document.documentElement.dataset.ambientSoundBound = "1";

  const button = $("ambientSoundButton");
  if (button) {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      toggleAmbientPlayback().catch(handleError);
    });
    button.addEventListener("contextmenu", (event) => {
      event.preventDefault();
      event.stopPropagation();
      toggleAmbientPopup();
    }, true);
  }

  document.addEventListener("click", (event) => {
    if (event.target?.closest?.("#adminAmbientTrackList .ambient-chip-title-input")) {
      event.stopPropagation();
      return;
    }
    const del = event.target?.closest?.("#adminAmbientTrackList [data-ambient-custom-delete]");
    if (del) {
      event.preventDefault();
      event.stopPropagation();
      const customId = Number(del.getAttribute("data-ambient-custom-delete"));
      if (Number.isFinite(customId) && customId > 0) {
        deleteCustomAmbientTrack(customId).catch(handleError);
      }
      return;
    }
    const rename = event.target?.closest?.("#adminAmbientTrackList [data-ambient-rename], #adminAmbientTrackList .ambient-chip-label");
    if (rename) {
      event.preventDefault();
      event.stopPropagation();
      const id = rename.getAttribute("data-ambient-rename")
        || rename.closest("[data-ambient-track]")?.getAttribute("data-ambient-track");
      if (id) startAmbientTitleEdit(id);
      return;
    }
    const add = event.target?.closest?.("#adminAmbientTrackList [data-ambient-add]");
    if (add) {
      event.preventDefault();
      event.stopPropagation();
      pickCustomAmbientFile(add.getAttribute("data-ambient-add"));
      return;
    }
    const acc = event.target?.closest?.("#ambientSoundPopup [data-ambient-acc], #adminAmbientTrackList [data-ambient-acc]");
    if (acc) {
      event.preventDefault();
      event.stopPropagation();
      toggleAmbientAccordion(acc);
      return;
    }
    const manage = event.target?.closest?.("#ambientSoundPopup [data-ambient-manage]");
    if (manage) {
      event.preventDefault();
      event.stopPropagation();
      openAmbientSettingsPanel();
      return;
    }
    const pick = event.target?.closest?.("#ambientSoundPopup [data-ambient-track], #adminAmbientTrackList [data-ambient-track]");
    if (pick) {
      event.preventDefault();
      event.stopPropagation();
      const id = pick.getAttribute("data-ambient-track");
      startAmbientTrack(id).catch(handleError);
      return;
    }
    if (isAmbientPopupOpen() && !event.target?.closest?.("#ambientSoundPopup, #binderAmbientControl")) {
      closeAmbientPopup();
    }
  }, true);

  document.addEventListener("change", (event) => {
    const box = event.target?.closest?.("#adminAmbientTrackList [data-ambient-popup-enabled]");
    if (!box) return;
    const id = box.getAttribute("data-ambient-popup-enabled");
    if (!id) return;
    const enabled = Boolean(box.checked);
    patchAmbientTrackOverride(id, { enabled_in_popup: enabled }).catch((error) => {
      box.checked = !enabled;
      handleError(error);
    });
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && isAmbientPopupOpen()) closeAmbientPopup();
  });

  window.addEventListener("resize", () => {
    if (isAmbientPopupOpen()) positionAmbientPopup();
  });

  $("adminAmbientVolume")?.addEventListener("input", (event) => {
    const pct = Number(event.target.value);
    saveAmbientVolume((Number.isFinite(pct) ? pct : 50) / 100);
    const percent = $("adminAmbientVolumeValue");
    if (percent) percent.textContent = `${Math.round(ambientSound.volume * 100)}%`;
  });

  $("adminAmbientFileInput")?.addEventListener("change", (event) => {
    const file = event.target.files && event.target.files[0];
    event.target.value = "";
    const category = ambientCustomUploadCategory || "custom";
    if (!file) return;
    uploadCustomAmbientFile(category, file).catch(handleError);
  });
}

